    EXEC('CREATE PROCEDURE dbo.SP_DangKy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_DangKy
    @TenDangNhap VARCHAR(50),
    @MatKhau VARCHAR(255),
    @HoTen VARCHAR(100),
    @NgaySinh DATE,
    @GioiTinh VARCHAR(5),
    @SDT VARCHAR(20),
    @Email VARCHAR(100) = NULL
AS
BEGIN
    
    

    SET @TenDangNhap = TRIM(@TenDangNhap));
    SET @HoTen = TRIM(@HoTen));
    SET @GioiTinh = NULLIF(TRIM(@GioiTinh)), '');
    SET @SDT = NULLIF(TRIM(@SDT)), '');
    SET @Email = NULLIF(TRIM(@Email)), '');

    IF NULLIF(@TenDangNhap, '') IS NULL
       OR NULLIF(@HoTen, '') IS NULL
       OR NULLIF(@MatKhau, '') IS NULL
       OR @NgaySinh IS NULL
       OR @GioiTinh IS NULL
       OR @GioiTinh NOT IN ('Nam', 'Nữ')
       OR @SDT IS NULL
        THROW 50001, 'Vui lòng nhập đầy đủ họ tên, tên đăng nhập, giới tính, số điện thoại, ngày sinh và mật khẩu.', 1;

    IF LENGTH(@SDT) <> 10 OR @SDT LIKE '%[^0-9]%'
        RAISE EXCEPTION %;

    IF @NgaySinh >= CAST(CURRENT_TIMESTAMP AS DATE)
        RAISE EXCEPTION %;

    DECLARE @SoThuTu INT;
    DECLARE @MaNguoiDung VARCHAR(6);

    BEGIN TRY
        BEGIN TRANSACTION;

        IF EXISTS (
            SELECT 1
            FROM dbo.TaiKhoan 
            WHERE TenDangNhap = @TenDangNhap
        )
            RAISE EXCEPTION %;

        SELECT TOP (1) @MaNguoiDung = nd.MaNguoiDung
        FROM dbo.NguoiDung AS nd 
        INNER JOIN dbo.KhachHang AS kh ON kh.MaKhachHang = nd.MaNguoiDung
        WHERE nd.SDT = @SDT
          AND nd.LoaiNguoiDung = 'KhachHang';

        IF @MaNguoiDung IS NOT NULL
           AND EXISTS (
               SELECT 1
               FROM dbo.TaiKhoan 
               WHERE MaNguoiDung = @MaNguoiDung
           )
            RAISE EXCEPTION %;

        IF @MaNguoiDung IS NULL
        BEGIN
            SELECT @SoThuTu = COALESCE(MAX(CASE WHEN (SUBSTRING(MaNguoiDung, 3, 4) ~ '^[0-9]+)), 0) + 1
            FROM dbo.NguoiDung 
            WHERE MaNguoiDung LIKE 'KH%';

            IF @SoThuTu > 9999
                RAISE EXCEPTION %;

            SET @MaNguoiDung = CONCAT('KH', RIGHT(CONCAT('0000', @SoThuTu), 4));

            INSERT INTO dbo.NguoiDung (MaNguoiDung, HoTen, NgaySinh, GioiTinh, SDT, Email, LoaiNguoiDung)
            VALUES (@MaNguoiDung, @HoTen, @NgaySinh, @GioiTinh, @SDT, @Email, 'KhachHang');

            INSERT INTO dbo.KhachHang (MaKhachHang, QuocTich, CCCD)
            VALUES (@MaNguoiDung, NULL, NULL);
        END
        ELSE
        BEGIN
            UPDATE dbo.NguoiDung
            SET Email = COALESCE(Email, @Email)
            WHERE MaNguoiDung = @MaNguoiDung;
        END;

        INSERT INTO dbo.TaiKhoan (TenDangNhap, MatKhau, TrangThai, MaNguoiDung)
        VALUES (
            @TenDangNhap,
            CONVERT(VARCHAR(64), HASHBYTES('SHA2_256', @MatKhau), 2),
            'Hoạt động',
            @MaNguoiDung
        );

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        THROW;
    END CATCH;

    SELECT
        tk.TenDangNhap AS tenDangNhap,
        tk.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTen,
        nd.NgaySinh AS ngaySinh,
        nd.GioiTinh AS gioiTinh,
        nd.Email AS email,
        nd.SDT AS soDienThoai,
        nd.LoaiNguoiDung AS vaiTro,
        tk.TrangThai AS trangThai,
        nv.ChucVu AS chucVu,
        nv.MaChiNhanh AS maChiNhanh,
        kh.QuocTich AS quocTich,
        kh.CCCD AS cccd
    FROM dbo.TaiKhoan AS tk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = tk.MaNguoiDung
    LEFT JOIN dbo.NhanVien AS nv ON nv.MaNhanVien = tk.MaNguoiDung
    LEFT JOIN dbo.KhachHang AS kh ON kh.MaKhachHang = tk.MaNguoiDung
    WHERE tk.TenDangNhap = @TenDangNhap;
END;

    EXEC('CREATE PROCEDURE dbo.SP_DangNhap AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_DangNhap
    @TenDangNhap VARCHAR(50),
    @MatKhau VARCHAR(255)
AS
BEGIN
    

    SET @TenDangNhap = TRIM(@TenDangNhap));

    IF NOT EXISTS (
        SELECT 1
        FROM dbo.TaiKhoan
        WHERE TenDangNhap = @TenDangNhap
          AND MatKhau = CONVERT(VARCHAR(64), HASHBYTES('SHA2_256', @MatKhau), 2)
    )
        RAISE EXCEPTION %;

    IF EXISTS (
        SELECT 1
        FROM dbo.TaiKhoan
        WHERE TenDangNhap = @TenDangNhap
          AND TrangThai = 'Vô hiệu hóa'
    )
        RAISE EXCEPTION %;

    SELECT
        tk.TenDangNhap AS tenDangNhap,
        tk.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTen,
        nd.NgaySinh AS ngaySinh,
        nd.GioiTinh AS gioiTinh,
        nd.Email AS email,
        nd.SDT AS soDienThoai,
        nd.LoaiNguoiDung AS vaiTro,
        tk.TrangThai AS trangThai,
        nv.ChucVu AS chucVu,
        nv.MaChiNhanh AS maChiNhanh,
        kh.QuocTich AS quocTich,
        kh.CCCD AS cccd
    FROM dbo.TaiKhoan AS tk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = tk.MaNguoiDung
    LEFT JOIN dbo.NhanVien AS nv ON nv.MaNhanVien = tk.MaNguoiDung
    LEFT JOIN dbo.KhachHang AS kh ON kh.MaKhachHang = tk.MaNguoiDung
    WHERE tk.TenDangNhap = @TenDangNhap;
END; THEN (SUBSTRING(MaNguoiDung, 3, 4)::INT ELSE NULL END)), 0) + 1
