        nd.GioiTinh AS gioiTinh,
        nd.Email AS email,
        nd.SDT AS soDienThoai,
        nd.LoaiNguoiDung AS vaiTro,
        tk.TrangThai AS trangThai,
        nv.ChucVu AS chucVu,
        nv.MaChiNhanh AS maChiNhanh,
        kh.QuocTich AS quocTich,
        kh.CCCD AS cccd
    FROM dbo.TaiKhoan AS tk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = tk.MaNguoiDung
    LEFT JOIN dbo.NhanVien AS nv ON nv.MaNhanVien = tk.MaNguoiDung
    LEFT JOIN dbo.KhachHang AS kh ON kh.MaKhachHang = tk.MaNguoiDung
    WHERE tk.TenDangNhap = @TenDangNhap;
END;

    EXEC('CREATE PROCEDURE dbo.SP_DangNhap AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_DangNhap
    @TenDangNhap VARCHAR(50),
    @MatKhau VARCHAR(255)
AS
BEGIN
    

    SET @TenDangNhap = TRIM(@TenDangNhap));

    IF NOT EXISTS (
        SELECT 1
        FROM dbo.TaiKhoan
        WHERE TenDangNhap = @TenDangNhap
          AND MatKhau = CONVERT(VARCHAR(64), HASHBYTES('SHA2_256', @MatKhau), 2)
    )
        RAISE EXCEPTION %;

    IF EXISTS (
        SELECT 1
        FROM dbo.TaiKhoan
        WHERE TenDangNhap = @TenDangNhap
          AND TrangThai = 'Vô hiệu hóa'
    )
        RAISE EXCEPTION %;

    SELECT
        tk.TenDangNhap AS tenDangNhap,
        tk.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTen,
        nd.NgaySinh AS ngaySinh,
        nd.GioiTinh AS gioiTinh,
        nd.Email AS email,
        nd.SDT AS soDienThoai,
        nd.LoaiNguoiDung AS vaiTro,
        tk.TrangThai AS trangThai,
        nv.ChucVu AS chucVu,
        nv.MaChiNhanh AS maChiNhanh,
        kh.QuocTich AS quocTich,
        kh.CCCD AS cccd
    FROM dbo.TaiKhoan AS tk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = tk.MaNguoiDung
    LEFT JOIN dbo.NhanVien AS nv ON nv.MaNhanVien = tk.MaNguoiDung
    LEFT JOIN dbo.KhachHang AS kh ON kh.MaKhachHang = tk.MaNguoiDung
    WHERE tk.TenDangNhap = @TenDangNhap;
END;

-- Source: Database/SP_Chung/cap-nhat-hoa-don-qua-han.sql

-- ================================================================
-- SP_HoaDon_CapNhatNoQuaHan
-- Tu dong chuyen hoa don qua han thanh No.
-- Dung CHAR de tranh loi encoding tieng Viet khi chay script.
-- ================================================================

    EXEC('CREATE PROCEDURE dbo.SP_HoaDon_CapNhatNoQuaHan AS BEGIN  END;');
CREATE OR ALTER PROCEDURE dbo.SP_HoaDon_CapNhatNoQuaHan
    @TraKetQua BOOLEAN = 1
AS
BEGIN
    

    DECLARE @TrangThaiChuaTT VARCHAR(20) = 'Ch' + CHAR(432) + 'a TT';
    DECLARE @TrangThaiNo VARCHAR(20) = 'N' + CHAR(7907);
    DECLARE @SoHoaDonCapNhat INT = 0;

    UPDATE dbo.HoaDon
    SET TrangThai = @TrangThaiNo
    WHERE TrangThai = @TrangThaiChuaTT
      AND NgayThanhToan IS NULL
      AND NgayHanTT IS NOT NULLphi
      AND CAST(NgayHanTT AS DATE) < CAST(CURRENT_TIMESTAMP AS DATE);

    SET @SoHoaDonCapNhat = @@ROWCOUNT;

    IF @TraKetQua = 1
    BEGIN
        SELECT @SoHoaDonCapNhat AS soHoaDonCapNhat;
    END
END;


-- ============================================================================
-- PHẦN 3: ĐĂNG KÝ THUÊ & KHÁCH MỚI
-- ============================================================================

-- Source: Database/SP_DKyThue/dang-ky-thue.sql

-- =============================================
-- MODULE: ĐĂNG KÝ THUÊ PHÒNG (dành cho nhân viên Sale)
-- Chạy file này sau khi đã chạy app.sql và auth.sql.
--
-- Danh sách stored procedure:
--   1. SP_TaoHoSoDangKy          -- Khách hàng tạo hồ sơ nhu cầu thuê
--   2. SP_DanhSachHoSoDangKy     -- Nhân viên Sale xem danh sách hồ sơ chờ xử lý
--   3. SP_DanhSachPhongGiuongKhaDung -- Lấy phòng/giường còn trống để gợi ý
--   4. SP_KiemTraDieuKienThue    -- Kiểm tra hồ sơ đủ điều kiện tiến lên đặt cọc
--   5. SP_CapNhatKetQuaXuLyHoSo  -- Sale cập nhật kết quả xử lý hồ sơ
--   6. SP_TiepNhanHoSoDangKy     -- Sale tiếp nhận hồ sơ đăng ký
--   7. SP_TaoHoSoKhachVangLai    -- Sale tạo hồ sơ cho khách vãng lai
--   8. SP_LayThongTinKhachHangChoDonDangKy -- Lấy thông tin khách để tự động điền đơn
-- =============================================



END;
-- =============================================
-- 1. SP_TaoHoSoDangKy
-- Khách hàng gửi hồ sơ nhu cầu thuê phòng.
-- Mỗi khách chỉ được có 1 luồng thuê đang hoạt động.
-- Chỉ được tạo phiếu mới khi hồ sơ cũ bị từ chối hoặc hợp đồng đã hết hạn/đã thanh lý.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_TaoHoSoDangKy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_TaoHoSoDangKy
    @KhachHangId        VARCHAR(20),
    @SoNguoiO           INT             = 1,
    @NgayDuKienVaoO     DATE            = NULL,
    @GhiChu             TEXT   = NULL,
    @KhuVucMongMuon     VARCHAR(100)   = NULL,
    @LoaiPhongYeuCau    VARCHAR(200)   = NULL,
    @MucGiaToiDa        DECIMAL(18,2)   = NULL,
    @ThoiHanThue        INT             = NULL,
    @GioiTinh           VARCHAR(10)    = NULL,
    @SoNamInput         INT             = 0,
    @SoNuInput          INT             = 0
AS
BEGIN
    
    

    SET @KhachHangId    = TRIM(@KhachHangId));
    SET @GhiChu         = NULLIF(TRIM(@GhiChu)), '');
    SET @KhuVucMongMuon = NULLIF(TRIM(@KhuVucMongMuon)), '');
    SET @LoaiPhongYeuCau= NULLIF(TRIM(@LoaiPhongYeuCau)), '');
    SET @GioiTinh       = NULLIF(TRIM(@GioiTinh)), '');

    IF NOT EXISTS (SELECT 1 FROM dbo.KhachHang WHERE MaKhachHang = @KhachHangId)
        RAISE EXCEPTION %;

    IF @SoNguoiO IS NULL OR @SoNguoiO < 1
        RAISE EXCEPTION %;

    IF @GioiTinh IS NULL
    BEGIN
        SELECT @GioiTinh = nd.GioiTinh
        FROM dbo.KhachHang kh
        JOIN dbo.NguoiDung nd ON kh.MaKhachHang = nd.MaNguoiDung
        WHERE kh.MaKhachHang = @KhachHangId;
    END

    IF @GioiTinh IS NULL OR @GioiTinh NOT IN ('Nam', 'Nữ', 'Hỗn hợp', 'Khác')
        RAISE EXCEPTION %;

    IF @KhuVucMongMuon IS NULL
        RAISE EXCEPTION %;

    IF @LoaiPhongYeuCau IS NULL
        RAISE EXCEPTION %;

    IF @MucGiaToiDa IS NULL OR @MucGiaToiDa <= 0
        RAISE EXCEPTION %;

    IF @NgayDuKienVaoO IS NULL OR @NgayDuKienVaoO <= CAST(CURRENT_TIMESTAMP AS DATE)
        RAISE EXCEPTION %;

    IF @ThoiHanThue IS NULL OR @ThoiHanThue < 1
        RAISE EXCEPTION %;

    DECLARE @SoThuTu    INT;
    DECLARE @MaDangKy   VARCHAR(6);
    DECLARE @SoNam      INT = COALESCE(@SoNamInput, 0);
    DECLARE @SoNu       INT = COALESCE(@SoNuInput, 0);

    IF @GioiTinh = 'Nam' BEGIN
        SET @SoNam = @SoNguoiO;
        SET @SoNu = 0;
    END
    ELSE IF @GioiTinh = 'Nữ' BEGIN
        SET @SoNu = @SoNguoiO;
        SET @SoNam = 0;
    END
    ELSE IF @GioiTinh = 'Khác' OR @GioiTinh = 'Hỗn hợp' BEGIN
        IF @SoNam = 0 AND @SoNu = 0 SET @SoNam = @SoNguoiO;
    END
    ELSE BEGIN
        SET @SoNam = @SoNguoiO;
        SET @SoNu = 0;
    END

    BEGIN TRY
        BEGIN TRANSACTION;

        IF EXISTS (
            SELECT 1
            FROM dbo.HopDongThue 
            WHERE MaKhachHang = @KhachHangId
              AND TrangThai NOT IN ('Hết hạn', 'Đã thanh lý')
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.PhieuDatCoc AS pdcLock 
            WHERE pdcLock.MaKhachHang = @KhachHangId
              AND pdcLock.TrangThaiCoc <> 'Đã hủy'
              AND pdcLock.TrangThaiThanhToan <> 'Hết hạn'
              AND NOT EXISTS (
                  SELECT 1
                  FROM dbo.HopDongThue AS hd
                  WHERE hd.MaPhieuCoc = pdcLock.MaPhieuDatCoc
                    AND hd.TrangThai IN ('Hết hạn', 'Đã thanh lý')
              )
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.PhieuDangKy AS pdkLock 
            WHERE pdkLock.MaKhachHang = @KhachHangId
              AND pdkLock.TrangThai <> 'Từ chối'
              AND NOT EXISTS (
                  SELECT 1
                  FROM dbo.PhieuDatCoc AS pdc
                  INNER JOIN dbo.HopDongThue AS hd ON hd.MaPhieuCoc = pdc.MaPhieuDatCoc
                  WHERE pdc.MaPhieuYeuCauDangKy = pdkLock.MaDangKy
                    AND hd.TrangThai IN ('Hết hạn', 'Đã thanh lý')
              )
        )
            RAISE EXCEPTION %;

        SELECT @SoThuTu = COALESCE(MAX(CASE WHEN (SUBSTRING(MaDangKy, 3, 4) ~ '^[0-9]+)), 0) + 1
        FROM dbo.PhieuDangKy 
        WHERE MaDangKy LIKE 'DK%';

        SET @MaDangKy = CONCAT('DK', RIGHT(CONCAT('0000', @SoThuTu), 4));

        INSERT INTO dbo.PhieuDangKy (
            MaDangKy, NgayDangKy, SoNguoiDuKienO, SoNam, SoNu,
            MucGiaToiDa, ThoiGianDuKienVaoO, YeuCauKhac, TrangThai, MaKhachHang,
            KhuVucMongMuon, ThoiHanThue
        )
        VALUES (
            @MaDangKy, CAST(CURRENT_TIMESTAMP AS DATE), @SoNguoiO, @SoNam, @SoNu,
            @MucGiaToiDa, @NgayDuKienVaoO, @GhiChu, 'Chờ tiếp nhận', @KhachHangId,
            @KhuVucMongMuon, @ThoiHanThue
        );

        IF @LoaiPhongYeuCau IS NOT NULL
        BEGIN
            INSERT INTO dbo.PDK_LoaiPhong (MaDangKy, MaLoaiPhong)
            SELECT @MaDangKy, lp.MaLoaiPhong
            FROM dbo.LoaiPhong lp
            WHERE lp.TenLoaiPhong IN (SELECT TRIM(value)) FROM STRING_SPLIT(@LoaiPhongYeuCau, ','));
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    -- Trả về hồ sơ vừa tạo
    SELECT
        pdk.MaDangKy        AS maDangKy,
        pdk.NgayDangKy      AS ngayDangKy,
        pdk.SoNguoiDuKienO  AS soNguoiO,
        pdk.SoNam           AS soNam,
        pdk.SoNu            AS soNu,
        pdk.KhuVucMongMuon  AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = pdk.MaDangKy) AS loaiPhongYeuCau,
        pdk.MucGiaToiDa     AS mucGia,
        pdk.ThoiGianDuKienVaoO AS ngayDuKienVaoO,
        pdk.ThoiHanThue     AS thoiHanThue,
        pdk.YeuCauKhac      AS ghiChu,
        pdk.GhiChuSale      AS ghiChuSale,
        pdk.TrangThai       AS trangThai,
        pdk.MaKhachHang     AS maKhachHang,
        nd.HoTen            AS hoTenKhach,
        nd.SDT              AS sdtKhach,
        nd.Email            AS emailKhach
    FROM dbo.PhieuDangKy AS pdk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = pdk.MaKhachHang
    WHERE pdk.MaDangKy = @MaDangKy;
END;
-- =============================================
-- 6. SP_TiepNhanHoSoDangKy
-- Nhân viên Sale tiếp nhận hồ sơ đang ở trạng thái chờ tiếp nhận.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_TiepNhanHoSoDangKy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_TiepNhanHoSoDangKy
    @MaDangKy        VARCHAR(6),
    @NhanVienSaleId  VARCHAR(6)
AS
BEGIN
    
    

    SET @MaDangKy       = NULLIF(TRIM(@MaDangKy)), '');
    SET @NhanVienSaleId = NULLIF(TRIM(@NhanVienSaleId)), '');

    IF @MaDangKy IS NULL
        RAISE EXCEPTION %;

    IF @NhanVienSaleId IS NULL
        RAISE EXCEPTION %;

    IF NOT EXISTS (SELECT 1 FROM dbo.PhieuDangKy WHERE MaDangKy = @MaDangKy)
        RAISE EXCEPTION %;

    IF NOT EXISTS (
        SELECT 1
        FROM dbo.NhanVien
        WHERE MaNhanVien = @NhanVienSaleId
          AND ChucVu = 'Sale'
    )
        RAISE EXCEPTION %;

    IF NOT EXISTS (
        SELECT 1
        FROM dbo.PhieuDangKy
        WHERE MaDangKy = @MaDangKy
          AND TrangThai = 'Chờ tiếp nhận'
    )
        RAISE EXCEPTION %;

    DECLARE @SaleDangXuLy VARCHAR(6);
    SELECT @SaleDangXuLy = MaNhanVienSale
    FROM dbo.PhieuDangKy
    WHERE MaDangKy = @MaDangKy;

    IF @SaleDangXuLy IS NOT NULL AND @SaleDangXuLy <> @NhanVienSaleId
        RAISE EXCEPTION %;

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE dbo.PhieuDangKy
        SET MaNhanVienSale = @NhanVienSaleId
        WHERE MaDangKy = @MaDangKy
          AND TrangThai = 'Chờ tiếp nhận';

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        pdk.MaDangKy            AS maDangKy,
        pdk.NgayDangKy          AS ngayDangKy,
        pdk.SoNguoiDuKienO      AS soNguoiO,
        pdk.SoNam               AS soNam,
        pdk.SoNu                AS soNu,
        pdk.KhuVucMongMuon      AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = pdk.MaDangKy) AS loaiPhongYeuCau,
        pdk.MucGiaToiDa         AS mucGia,
        pdk.ThoiGianDuKienVaoO  AS ngayDuKienVaoO,
        pdk.ThoiHanThue         AS thoiHanThue,
        pdk.YeuCauKhac          AS ghiChu,
        pdk.GhiChuSale          AS ghiChuSale,
        pdk.TrangThai           AS trangThai,
        pdk.MaKhachHang         AS maKhachHang,
        nd.HoTen                AS hoTenKhach,
        nd.SDT                  AS sdtKhach,
        nd.Email                AS emailKhach,
        pdk.MaNhanVienSale      AS maNhanVienSale,
        nvnd.HoTen              AS hoTenSale
    FROM dbo.PhieuDangKy AS pdk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = pdk.MaKhachHang
    LEFT JOIN dbo.NguoiDung AS nvnd ON nvnd.MaNguoiDung = pdk.MaNhanVienSale
    WHERE pdk.MaDangKy = @MaDangKy;
END;
-- =============================================
-- 7. SP_HuyTiepNhanHoSoDangKy
-- Sale trả hồ sơ chưa lập lịch về hàng chờ tiếp nhận.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_HuyTiepNhanHoSoDangKy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_HuyTiepNhanHoSoDangKy
    @MaDangKy        VARCHAR(6),
    @NhanVienSaleId  VARCHAR(6)
AS
BEGIN
    
    

    SET @MaDangKy = NULLIF(TRIM(@MaDangKy)), '');
    SET @NhanVienSaleId = NULLIF(TRIM(@NhanVienSaleId)), '');

    IF NOT EXISTS (SELECT 1 FROM dbo.PhieuDangKy WHERE MaDangKy = @MaDangKy)
        RAISE EXCEPTION %;

    IF NOT EXISTS (
        SELECT 1
        FROM dbo.PhieuDangKy
        WHERE MaDangKy = @MaDangKy
          AND TrangThai = 'Đã tiếp nhận'
          AND MaNhanVienSale = @NhanVienSaleId
    )
        RAISE EXCEPTION %;

    IF EXISTS (SELECT 1 FROM dbo.LichXemPhong WHERE MaDangKy = @MaDangKy)
        RAISE EXCEPTION %;

    UPDATE dbo.PhieuDangKy
    SET TrangThai = 'Chờ tiếp nhận',
        MaNhanVienSale = NULL
    WHERE MaDangKy = @MaDangKy;

    SELECT
        MaDangKy AS maDangKy,
        TrangThai AS trangThai,
        MaNhanVienSale AS maNhanVienSale
    FROM dbo.PhieuDangKy
    WHERE MaDangKy = @MaDangKy;
END;
-- =============================================
-- 8. SP_TaoHoSoKhachVangLai
-- Sale tạo khách hàng mới và lập hồ sơ nhu cầu thuê trong cùng giao dịch.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_TaoHoSoKhachVangLai AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_TaoHoSoKhachVangLai
    @HoTen              VARCHAR(100),
    @NgaySinh           DATE,
    @GioiTinh           VARCHAR(5),
    @SDT                VARCHAR(20),
    @Email              VARCHAR(100)    = NULL,
    @QuocTich           VARCHAR(50)    = NULL,
    @CCCD               VARCHAR(20),
    @KhuVucMongMuon     VARCHAR(100),
    @LoaiPhongYeuCau    VARCHAR(200),
    @MucGiaToiDa        DECIMAL(15,2)   = NULL,
    @SoNguoiO           INT,
    @NgayDuKienVaoO     DATE,
    @ThoiHanThue        INT,
    @GhiChu             TEXT   = NULL,
    @NhanVienSaleId     VARCHAR(6),
    @HinhThucThue       VARCHAR(50)    = NULL,
    @SoNamInput         INT             = 0,
    @SoNuInput          INT             = 0
AS
BEGIN
    
    

    SET @HoTen              = NULLIF(TRIM(@HoTen)), '');
    SET @GioiTinh           = NULLIF(TRIM(@GioiTinh)), '');
    SET @SDT                = NULLIF(TRIM(@SDT)), '');
    SET @Email              = NULLIF(TRIM(@Email)), '');
    SET @QuocTich           = COALESCE(NULLIF(TRIM(@QuocTich)), ''), 'Việt Nam');
    SET @CCCD               = NULLIF(TRIM(@CCCD)), '');
    SET @HinhThucThue       = NULLIF(TRIM(@HinhThucThue)), '');

    SET @KhuVucMongMuon     = NULLIF(TRIM(@KhuVucMongMuon)), '');
    SET @LoaiPhongYeuCau    = NULLIF(TRIM(@LoaiPhongYeuCau)), '');
    SET @GhiChu             = NULLIF(TRIM(@GhiChu)), '');
    SET @NhanVienSaleId     = NULLIF(TRIM(@NhanVienSaleId)), '');

    IF @HoTen IS NULL OR @NgaySinh IS NULL OR @GioiTinh IS NULL OR @SDT IS NULL
       OR @CCCD IS NULL OR @KhuVucMongMuon IS NULL
       OR @LoaiPhongYeuCau IS NULL OR @NgayDuKienVaoO IS NULL
       OR @MucGiaToiDa IS NULL OR @SoNguoiO IS NULL OR @ThoiHanThue IS NULL OR @NhanVienSaleId IS NULL
        RAISE EXCEPTION %;

    IF @GioiTinh NOT IN ('Nam', 'Nữ', 'Hỗn hợp', 'Khác')
        RAISE EXCEPTION %;

    IF LENGTH(@SDT) <> 10 OR @SDT LIKE '%[^0-9]%'
        RAISE EXCEPTION %;

    IF LENGTH(@CCCD) <> 12 OR @CCCD LIKE '%[^0-9]%'
        RAISE EXCEPTION %;

    IF @NgaySinh >= CAST(CURRENT_TIMESTAMP AS DATE)
        RAISE EXCEPTION %;

    IF @NgayDuKienVaoO <= CAST(CURRENT_TIMESTAMP AS DATE)
        RAISE EXCEPTION %;

    IF @SoNguoiO < 1
        RAISE EXCEPTION %;

    IF @ThoiHanThue < 1
        RAISE EXCEPTION %;

    IF @MucGiaToiDa <= 0
        RAISE EXCEPTION %;

    IF NOT EXISTS (
        SELECT 1
        FROM dbo.NhanVien
        WHERE MaNhanVien = @NhanVienSaleId
          AND ChucVu = 'Sale'
    )
        RAISE EXCEPTION %;

    DECLARE @MaKhachHang VARCHAR(6);

    SELECT TOP (1) @MaKhachHang = kh.MaKhachHang
    FROM dbo.KhachHang AS kh
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = kh.MaKhachHang
    WHERE nd.SDT = @SDT
      AND nd.LoaiNguoiDung = 'KhachHang';

    IF @MaKhachHang IS NOT NULL
       AND EXISTS (
           SELECT 1
           FROM dbo.KhachHang
           WHERE MaKhachHang = @MaKhachHang
             AND COALESCE(CCCD, '') <> @CCCD
       )
        RAISE EXCEPTION %;

    IF EXISTS (
        SELECT 1
        FROM dbo.KhachHang
        WHERE CCCD = @CCCD
          AND (@MaKhachHang IS NULL OR MaKhachHang <> @MaKhachHang)
    )
        RAISE EXCEPTION %;

    IF @Email IS NOT NULL
       AND EXISTS (
           SELECT 1
           FROM dbo.NguoiDung
           WHERE Email = @Email
             AND LoaiNguoiDung = 'KhachHang'
             AND (@MaKhachHang IS NULL OR MaNguoiDung <> @MaKhachHang)
       )
        RAISE EXCEPTION %;

    DECLARE @SoKhach INT;
    DECLARE @SoDangKy INT;
    DECLARE @MaDangKy VARCHAR(6);

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @MaKhachHang IS NULL
        BEGIN
            SELECT @SoKhach = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaNguoiDung, 3, 4))), 0) + 1
            FROM dbo.NguoiDung 
            WHERE MaNguoiDung LIKE 'KH[0-9][0-9][0-9][0-9]';

            IF @SoKhach > 9999
                RAISE EXCEPTION %;

            SET @MaKhachHang = CONCAT('KH', RIGHT(CONCAT('0000', @SoKhach), 4));

            INSERT INTO dbo.NguoiDung (
                MaNguoiDung, HoTen, NgaySinh, GioiTinh, SDT, Email, UrlAvt, LoaiNguoiDung
            )
            VALUES (
                @MaKhachHang, @HoTen, @NgaySinh, @GioiTinh, @SDT, @Email, NULL, 'KhachHang'
            );

            INSERT INTO dbo.KhachHang (MaKhachHang, QuocTich, CCCD)
            VALUES (@MaKhachHang, @QuocTich, @CCCD);
        END;

        IF EXISTS (
            SELECT 1
            FROM dbo.HopDongThue 
            WHERE MaKhachHang = @MaKhachHang
              AND TrangThai NOT IN ('Hết hạn', 'Đã thanh lý')
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.PhieuDatCoc AS pdcLock 
            WHERE pdcLock.MaKhachHang = @MaKhachHang
              AND pdcLock.TrangThaiCoc <> 'Đã hủy'
              AND pdcLock.TrangThaiThanhToan <> 'Hết hạn'
              AND NOT EXISTS (
                  SELECT 1
                  FROM dbo.HopDongThue AS hd
                  WHERE hd.MaPhieuCoc = pdcLock.MaPhieuDatCoc
                    AND hd.TrangThai IN ('Hết hạn', 'Đã thanh lý')
              )
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.PhieuDangKy AS pdkLock 
            WHERE pdkLock.MaKhachHang = @MaKhachHang
              AND pdkLock.TrangThai <> 'Từ chối'
              AND NOT EXISTS (
                  SELECT 1
                  FROM dbo.PhieuDatCoc AS pdc
                  INNER JOIN dbo.HopDongThue AS hd ON hd.MaPhieuCoc = pdc.MaPhieuDatCoc
                  WHERE pdc.MaPhieuYeuCauDangKy = pdkLock.MaDangKy
                    AND hd.TrangThai IN ('Hết hạn', 'Đã thanh lý')
              )
        )
            RAISE EXCEPTION %;

        SELECT @SoDangKy = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDangKy, 3, 4))), 0) + 1
        FROM dbo.PhieuDangKy 
        WHERE MaDangKy LIKE 'DK[0-9][0-9][0-9][0-9]';

        IF @SoDangKy > 9999
            RAISE EXCEPTION %;

        SET @MaDangKy = CONCAT('DK', RIGHT(CONCAT('0000', @SoDangKy), 4));

        DECLARE @SoNam INT = COALESCE(@SoNamInput, 0);
        DECLARE @SoNu INT = COALESCE(@SoNuInput, 0);
        IF @GioiTinh = 'Nam' BEGIN
            SET @SoNam = @SoNguoiO;
            SET @SoNu = 0;
        END
        ELSE IF @GioiTinh = 'Nữ' BEGIN
            SET @SoNu = @SoNguoiO;
            SET @SoNam = 0;
        END
        ELSE IF @GioiTinh = 'Khác' OR @GioiTinh = 'Hỗn hợp' BEGIN
            IF @SoNam = 0 AND @SoNu = 0 SET @SoNam = @SoNguoiO;
        END
        ELSE BEGIN
            SET @SoNam = @SoNguoiO;
            SET @SoNu = 0;
        END

        INSERT INTO dbo.PhieuDangKy (
            MaDangKy, NgayDangKy, SoNguoiDuKienO, SoNam, SoNu,
            KhuVucMongMuon, MucGiaToiDa, ThoiGianDuKienVaoO,
            ThoiHanThue, YeuCauKhac, TrangThai, MaKhachHang, MaNhanVienSale
        )
        VALUES (
            @MaDangKy, CAST(CURRENT_TIMESTAMP AS DATE), @SoNguoiO, @SoNam, @SoNu,
            @KhuVucMongMuon, @MucGiaToiDa, @NgayDuKienVaoO,
            @ThoiHanThue, @GhiChu, 'Chờ tiếp nhận', @MaKhachHang, NULL
        );

        IF @LoaiPhongYeuCau IS NOT NULL
        BEGIN
            INSERT INTO dbo.PDK_LoaiPhong (MaDangKy, MaLoaiPhong)
            SELECT @MaDangKy, lp.MaLoaiPhong
            FROM dbo.LoaiPhong lp
            WHERE lp.TenLoaiPhong IN (SELECT TRIM(value)) FROM STRING_SPLIT(@LoaiPhongYeuCau, ','));
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        pdk.MaDangKy            AS maDangKy,
        pdk.NgayDangKy          AS ngayDangKy,
        pdk.SoNguoiDuKienO      AS soNguoiO,
        pdk.SoNam               AS soNam,
        pdk.SoNu                AS soNu,
        pdk.KhuVucMongMuon      AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = pdk.MaDangKy) AS loaiPhongYeuCau,
        pdk.MucGiaToiDa         AS mucGia,
        pdk.ThoiGianDuKienVaoO  AS ngayDuKienVaoO,
        pdk.ThoiHanThue         AS thoiHanThue,
        pdk.YeuCauKhac          AS ghiChu,
        pdk.GhiChuSale          AS ghiChuSale,
        pdk.TrangThai           AS trangThai,
        pdk.MaKhachHang         AS maKhachHang,
        nd.HoTen                AS hoTenKhach,
        nd.SDT                  AS sdtKhach,
        nd.Email                AS emailKhach,
        kh.QuocTich             AS quocTich,
        kh.CCCD                 AS cccd,
        pdk.MaNhanVienSale      AS maNhanVienSale,
        nvnd.HoTen              AS hoTenSale
    FROM dbo.PhieuDangKy AS pdk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = pdk.MaKhachHang
    INNER JOIN dbo.KhachHang AS kh ON kh.MaKhachHang = pdk.MaKhachHang
    LEFT JOIN dbo.NguoiDung AS nvnd ON nvnd.MaNguoiDung = pdk.MaNhanVienSale
    WHERE pdk.MaDangKy = @MaDangKy;
END;
-- =============================================
-- 8. SP_LayThongTinKhachHangChoDonDangKy
-- Lấy thông tin khách hàng và hồ sơ gần nhất để hệ thống tự động điền đơn đăng ký.
-- Có thể tìm bằng mã khách hàng, CCCD, số điện thoại hoặc email.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_LayThongTinKhachHangChoDonDangKy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_LayThongTinKhachHangChoDonDangKy
    @KhachHangId VARCHAR(6)   = NULL,
    @CCCD        VARCHAR(20)  = NULL,
    @SDT         VARCHAR(20)  = NULL,
    @Email       VARCHAR(100) = NULL
AS
BEGIN
    

    SET @KhachHangId = NULLIF(TRIM(@KhachHangId)), '');
    SET @CCCD        = NULLIF(TRIM(@CCCD)), '');
    SET @SDT         = NULLIF(TRIM(@SDT)), '');
    SET @Email       = NULLIF(TRIM(@Email)), '');

    IF @KhachHangId IS NULL AND @CCCD IS NULL AND @SDT IS NULL AND @Email IS NULL
        THROW 50011, 'Vui lòng nhập mã khách hàng, CCCD, số điện thoại hoặc email để tra cứu.', 1;

    DECLARE @MaKhachHangTimThay VARCHAR(6);

    SELECT TOP (1)
        @MaKhachHangTimThay = kh.MaKhachHang
    FROM dbo.KhachHang AS kh
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = kh.MaKhachHang
    WHERE (@KhachHangId IS NOT NULL AND kh.MaKhachHang = @KhachHangId)
       OR (@CCCD IS NOT NULL AND kh.CCCD = @CCCD)
       OR (@SDT IS NOT NULL AND nd.SDT = @SDT)
       OR (@Email IS NOT NULL AND nd.Email = @Email)
    ORDER BY
        CASE
            WHEN @KhachHangId IS NOT NULL AND kh.MaKhachHang = @KhachHangId THEN 1
            WHEN @CCCD IS NOT NULL AND kh.CCCD = @CCCD THEN 2
            WHEN @SDT IS NOT NULL AND nd.SDT = @SDT THEN 3
            WHEN @Email IS NOT NULL AND nd.Email = @Email THEN 4
            ELSE 5
        END,
        kh.MaKhachHang;

    IF @MaKhachHangTimThay IS NULL
        RAISE EXCEPTION %;

    SELECT
        kh.MaKhachHang          AS maKhachHang,
        nd.HoTen                AS hoTenKhach,
        nd.HoTen                AS hoTen,
        nd.NgaySinh             AS ngaySinh,
        nd.GioiTinh             AS gioiTinh,
        nd.SDT                  AS sdtKhach,
        nd.SDT                  AS soDienThoai,
        nd.Email                AS emailKhach,
        nd.Email                AS email,
        kh.QuocTich             AS quocTich,
        kh.CCCD                 AS cccd,
        hoSo.MaDangKy           AS maDangKyGanNhat,
        hoSo.KhuVucMongMuon     AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = hoSo.MaDangKy) AS loaiPhongYeuCau,
        hoSo.MucGiaToiDa        AS mucGia,
        hoSo.SoNguoiDuKienO     AS soNguoiO,
        hoSo.ThoiGianDuKienVaoO AS ngayDuKienVaoO,
        hoSo.ThoiHanThue        AS thoiHanThue,
        hoSo.YeuCauKhac         AS ghiChu,
        hoSo.GhiChuSale         AS ghiChuSale,
        hoSo.TrangThai          AS trangThaiHoSoGanNhat
    FROM dbo.KhachHang AS kh
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = kh.MaKhachHang
    OUTER APPLY (
        SELECT TOP (1)
            pdk.MaDangKy,
            pdk.KhuVucMongMuon,
            (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
             FROM dbo.PDK_LoaiPhong pdklp
             JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
             WHERE pdklp.MaDangKy = pdk.MaDangKy) AS LoaiPhongYeuCau,
            pdk.MucGiaToiDa,
            pdk.SoNguoiDuKienO,
            pdk.ThoiGianDuKienVaoO,
            pdk.ThoiHanThue,
            pdk.YeuCauKhac,
            pdk.GhiChuSale,
            pdk.TrangThai
        FROM dbo.PhieuDangKy AS pdk
        WHERE pdk.MaKhachHang = kh.MaKhachHang
        ORDER BY pdk.NgayDangKy DESC, pdk.MaDangKy DESC
    ) AS hoSo
    WHERE kh.MaKhachHang = @MaKhachHangTimThay;
END;
-- =============================================
-- 2. SP_DanhSachHoSoDangKy
-- Nhân viên Sale xem danh sách hồ sơ đăng ký thuê.
-- Mặc định lấy hồ sơ đang chờ xử lý.
-- Hỗ trợ lọc theo trạng thái và chi nhánh.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_DanhSachHoSoDangKy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_DanhSachHoSoDangKy
    @TrangThai      VARCHAR(30)    = NULL,     -- NULL = lấy tất cả; hoặc lọc theo trạng thái cụ thể
    @MaChiNhanh     VARCHAR(6)      = NULL,     -- NULL = tất cả chi nhánh
    @NhanVienSaleId VARCHAR(6)      = NULL,     -- NULL = không lọc theo sale
    @KhachHangId    VARCHAR(6)      = NULL      -- NULL = không lọc theo khách hàng
AS
BEGIN
    

    SET @TrangThai      = NULLIF(TRIM(@TrangThai)), '');
    SET @MaChiNhanh     = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @NhanVienSaleId = NULLIF(TRIM(@NhanVienSaleId)), '');
    SET @KhachHangId    = NULLIF(TRIM(@KhachHangId)), '');

    IF @TrangThai IS NOT NULL
       AND @TrangThai NOT IN ('Chờ tiếp nhận', 'Đã tiếp nhận', 'Chờ xác nhận cọc', 'Xác nhận cọc', 'Từ chối')
        RAISE EXCEPTION %;

    IF @MaChiNhanh IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
        RAISE EXCEPTION %;

    IF @NhanVienSaleId IS NOT NULL
       AND NOT EXISTS (
           SELECT 1 FROM dbo.NhanVien WHERE MaNhanVien = @NhanVienSaleId AND ChucVu = 'Sale'
       )
        RAISE EXCEPTION %;

    IF @KhachHangId IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM dbo.KhachHang WHERE MaKhachHang = @KhachHangId)
        RAISE EXCEPTION %;

    SELECT
        pdk.MaDangKy            AS maDangKy,
        pdk.NgayDangKy          AS ngayDangKy,
        pdk.SoNguoiDuKienO      AS soNguoiO,
        pdk.SoNam               AS soNam,
        pdk.SoNu                AS soNu,
        pdk.KhuVucMongMuon      AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = pdk.MaDangKy) AS loaiPhongYeuCau,
        pdk.MucGiaToiDa         AS mucGia,
        pdk.ThoiGianDuKienVaoO  AS ngayDuKienVaoO,
        pdk.ThoiHanThue         AS thoiHanThue,
        pdk.YeuCauKhac          AS ghiChu,
        pdk.GhiChuSale          AS ghiChuSale,
        pdk.TrangThai           AS trangThai,
        pdk.MaKhachHang         AS maKhachHang,
        nd.HoTen                AS hoTenKhach,
        nd.NgaySinh             AS ngaySinhKhach,
        nd.SDT                  AS sdtKhach,
        nd.Email                AS emailKhach,
        nd.GioiTinh             AS gioiTinh,
        kh.QuocTich             AS quocTich,
        kh.CCCD                 AS cccd,
        pdk.MaNhanVienSale      AS maNhanVienSale,
        nvnd.HoTen              AS hoTenSale,
        nvSale.MaChiNhanh       AS maChiNhanhSale,
        cnSale.TenChiNhanh      AS tenChiNhanhSale,
        -- Lịch xem phòng gần nhất
        lich.STTLich            AS sttLichMoiNhat,
        lich.ThoiGianHen        AS thoiGianHenMoiNhat,
        lich.TrangThai          AS trangThaiLichMoiNhat
    FROM dbo.PhieuDangKy AS pdk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = pdk.MaKhachHang
    INNER JOIN dbo.KhachHang AS kh ON kh.MaKhachHang = pdk.MaKhachHang
    LEFT JOIN dbo.NguoiDung AS nvnd ON nvnd.MaNguoiDung = pdk.MaNhanVienSale
    LEFT JOIN dbo.NhanVien AS nvSale ON nvSale.MaNhanVien = pdk.MaNhanVienSale
    LEFT JOIN dbo.ChiNhanh AS cnSale ON cnSale.MaChiNhanh = nvSale.MaChiNhanh
    OUTER APPLY (
        SELECT TOP (1) lxp.STTLich, lxp.ThoiGianHen, lxp.TrangThai
        FROM dbo.LichXemPhong AS lxp
        WHERE lxp.MaDangKy = pdk.MaDangKy
        ORDER BY lxp.STTLich DESC
    ) AS lich
    WHERE (@TrangThai IS NULL OR pdk.TrangThai = @TrangThai)
      AND (@NhanVienSaleId IS NULL OR pdk.MaNhanVienSale = @NhanVienSaleId)
      AND (@KhachHangId IS NULL OR pdk.MaKhachHang = @KhachHangId)
      AND (@MaChiNhanh IS NULL
           OR nvSale.MaChiNhanh = @MaChiNhanh
           OR EXISTS (
               SELECT 1 FROM dbo.ChiNhanh cn
               WHERE cn.MaChiNhanh = @MaChiNhanh
                 AND cn.TenChiNhanh LIKE '%' + pdk.KhuVucMongMuon + '%'
           )
           OR (
               @MaChiNhanh = 'CN0001'
               AND (
                   pdk.KhuVucMongMuon LIKE '%Quận 1%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 3%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 4%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 5%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 10%'
               )
           )
           OR (
               @MaChiNhanh = 'CN0002'
               AND (
                   pdk.KhuVucMongMuon LIKE '%Bình Thạnh%'
                   OR pdk.KhuVucMongMuon LIKE '%Phú Nhuận%'
                   OR pdk.KhuVucMongMuon LIKE '%Gò Vấp%'
                   OR pdk.KhuVucMongMuon LIKE '%Tân Bình%'
               )
           )
           OR (
               @MaChiNhanh = 'CN0003'
               AND (
                   pdk.KhuVucMongMuon LIKE '%Thủ Đức%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 2%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 9%'
               )
           )
      )
    ORDER BY pdk.NgayDangKy DESC, pdk.MaDangKy DESC;
END;
-- =============================================
-- 3. SP_DanhSachPhongGiuongKhaDung
-- Lấy danh sách phòng và giường còn trống để Sale gợi ý cho khách.
-- Hỗ trợ lọc theo loại, giới tính, chi nhánh, khu vực, loại phòng, mức giá, số người hoặc hồ sơ đăng ký.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_DanhSachPhongGiuongKhaDung AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_DanhSachPhongGiuongKhaDung
    @Loai           VARCHAR(50)    = NULL,     -- 'Nguyên căn' hoặc 'Ghép' hoặc NULL (lấy tất cả)
    @GioiTinh       VARCHAR(5)     = NULL,     -- 'Nam' hoặc 'Nữ' hoặc NULL
    @MaChiNhanh     VARCHAR(6)      = NULL,     -- Lọc theo chi nhánh
    @KhuVuc         VARCHAR(100)   = NULL,     -- Lọc theo địa chỉ/tên chi nhánh
    @LoaiPhong      VARCHAR(50)    = NULL,     -- Lọc theo tên loại phòng
    @MucGiaTu       DECIMAL(15,2)   = NULL,     -- Lọc theo ngân sách tối thiểu
    @MucGiaToiDa    DECIMAL(15,2)   = NULL,     -- Lọc theo ngân sách tối đa
    @SoNguoiO       INT             = NULL,     -- Lọc phòng đủ sức chứa/chỗ trống
    @HoSoId         VARCHAR(6)      = NULL      -- Tự lấy tiêu chí từ phiếu đăng ký
AS
BEGIN
    

    SET @Loai       = NULLIF(TRIM(@Loai)), '');
    SET @GioiTinh   = NULLIF(TRIM(@GioiTinh)), '');
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @KhuVuc     = NULLIF(TRIM(@KhuVuc)), '');
    SET @LoaiPhong  = NULLIF(TRIM(@LoaiPhong)), '');
    SET @HoSoId     = NULLIF(TRIM(@HoSoId)), '');

    DECLARE @SoNam INT = 0;
    DECLARE @SoNu INT = 0;
    DECLARE @HinhThucThue VARCHAR(50) = NULL;

    IF @HoSoId IS NOT NULL
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.PhieuDangKy WHERE MaDangKy = @HoSoId)
            RAISE EXCEPTION %;

        SELECT
            @SoNam       = COALESCE(SoNam, 0),
            @SoNu        = COALESCE(SoNu, 0),
            @KhuVuc      = COALESCE(@KhuVuc, KhuVucMongMuon),
            @MucGiaToiDa = COALESCE(@MucGiaToiDa, MucGiaToiDa),
            @SoNguoiO    = COALESCE(@SoNguoiO, SoNguoiDuKienO)
        FROM dbo.PhieuDangKy
        WHERE MaDangKy = @HoSoId;

        
        END

        IF @Loai IS NULL AND @HinhThucThue IS NOT NULL
            SET @Loai = @HinhThucThue;

        IF @GioiTinh IS NULL
        BEGIN
            IF @SoNam > 0 AND @SoNu = 0 SET @GioiTinh = 'Nam';
            ELSE IF @SoNu > 0 AND @SoNam = 0 SET @GioiTinh = 'Nữ';
        END
    END;

    IF @Loai IN ('Nguyên phòng', 'Nguyên căn')
        SET @Loai = 'Nguyên căn';
    IF @Loai IN ('Ghép giường', 'Ghép')
        SET @Loai = 'Ghép';

    IF @Loai IS NOT NULL AND @Loai NOT IN ('Nguyên căn', 'Ghép')
        RAISE EXCEPTION %;

    IF @GioiTinh IS NOT NULL AND @GioiTinh NOT IN ('Nam', 'Nữ')
        RAISE EXCEPTION %;

    IF @MucGiaTu IS NOT NULL AND @MucGiaTu < 0
        RAISE EXCEPTION %;

    IF @MucGiaToiDa IS NOT NULL AND @MucGiaToiDa < 0
        RAISE EXCEPTION %;

    IF @SoNguoiO IS NOT NULL AND @SoNguoiO < 1
        RAISE EXCEPTION %;

    IF @SoNguoiO IS NULL AND (@SoNam + @SoNu) > 0
        SET @SoNguoiO = @SoNam + @SoNu;

    DECLARE @SoNguoiCanXep INT = COALESCE(NULLIF(@SoNguoiO, 0), CASE WHEN (@SoNam + @SoNu) > 0 THEN @SoNam + @SoNu ELSE 1 END);
    DECLARE @LaNhomHonHop BOOLEAN = CASE WHEN @SoNam > 0 AND @SoNu > 0 THEN 1 ELSE 0 END;

    IF @MaChiNhanh IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
        RAISE EXCEPTION %;

    CREATE TABLE #ChiNhanhPhuHop (MaChiNhanh VARCHAR(6) PRIMARY KEY);

    IF @MaChiNhanh IS NOT NULL
    BEGIN
        INSERT INTO #ChiNhanhPhuHop (MaChiNhanh)
        SELECT MaChiNhanh
        FROM dbo.ChiNhanh
        WHERE MaChiNhanh = @MaChiNhanh
          AND TrangThai = 'Hoạt động';
    END
    ELSE IF @KhuVuc IS NULL
    BEGIN
        INSERT INTO #ChiNhanhPhuHop (MaChiNhanh)
        SELECT MaChiNhanh
        FROM dbo.ChiNhanh
        WHERE TrangThai = 'Hoạt động';
    END
    ELSE
    BEGIN
        INSERT INTO #ChiNhanhPhuHop (MaChiNhanh)
        SELECT MaChiNhanh
        FROM dbo.ChiNhanh
        WHERE TrangThai = 'Hoạt động'
          AND (DiaChi LIKE '%' + @KhuVuc + '%' OR TenChiNhanh LIKE '%' + @KhuVuc + '%');

        INSERT INTO #ChiNhanhPhuHop (MaChiNhanh)
        SELECT cn.MaChiNhanh
        FROM dbo.ChiNhanh AS cn
        WHERE cn.TrangThai = 'Hoạt động'
          AND (
              (
                  cn.MaChiNhanh = 'CN0001'
                  AND (
                      @KhuVuc LIKE '%Quận 1%'
                      OR @KhuVuc LIKE '%Quận 3%'
                      OR @KhuVuc LIKE '%Quận 4%'
                      OR @KhuVuc LIKE '%Quận 5%'
                      OR @KhuVuc LIKE '%Quận 10%'
                  )
              )
              OR (
                  cn.MaChiNhanh = 'CN0002'
                  AND (
                      @KhuVuc LIKE '%Bình Thạnh%'
                      OR @KhuVuc LIKE '%Phú Nhuận%'
                      OR @KhuVuc LIKE '%Gò Vấp%'
                      OR @KhuVuc LIKE '%Tân Bình%'
                  )
              )
              OR (
                  cn.MaChiNhanh = 'CN0003'
                  AND (
                      @KhuVuc LIKE '%Thủ Đức%'
                      OR @KhuVuc LIKE '%Quận 2%'
                      OR @KhuVuc LIKE '%Quận 9%'
                  )
              )
          )
          AND NOT EXISTS (
              SELECT 1
              FROM #ChiNhanhPhuHop AS existed
              WHERE existed.MaChiNhanh = cn.MaChiNhanh
          );
    END;

    DECLARE @KhongCoChiNhanhPhuHop BOOLEAN =
        CASE WHEN @MaChiNhanh IS NULL AND @KhuVuc IS NOT NULL AND NOT EXISTS (SELECT 1 FROM #ChiNhanhPhuHop)
             THEN 1 ELSE 0 END;

    CREATE TABLE #LoaiPhongYeuCau (MaLoaiPhong VARCHAR(6) PRIMARY KEY);

    IF @LoaiPhong IS NOT NULL
    BEGIN
        INSERT INTO #LoaiPhongYeuCau (MaLoaiPhong)
        SELECT MaLoaiPhong
        FROM dbo.LoaiPhong
        WHERE TenLoaiPhong = @LoaiPhong;
    END
    ELSE IF @HoSoId IS NOT NULL
       AND OBJECT_ID('dbo.PDK_LoaiPhong', 'U') IS NOT NULL
       AND EXISTS (SELECT 1 FROM dbo.PDK_LoaiPhong WHERE MaDangKy = @HoSoId)
    BEGIN
        INSERT INTO #LoaiPhongYeuCau (MaLoaiPhong)
        SELECT DISTINCT MaLoaiPhong
        FROM dbo.PDK_LoaiPhong
        WHERE MaDangKy = @HoSoId;
    END

    IF NOT EXISTS (SELECT 1 FROM #LoaiPhongYeuCau)
    BEGIN
        INSERT INTO #LoaiPhongYeuCau (MaLoaiPhong)
        SELECT MaLoaiPhong
        FROM dbo.LoaiPhong;
    END;

    ;WITH BedCounts AS (
        SELECT
            g.MaPhong,
            COUNT(CASE WHEN g.TinhTrang = 'Trống' THEN 1 END) AS soGiuongTrong
        FROM dbo.Giuong AS g
        GROUP BY g.MaPhong
    )
    SELECT
        p.MaPhong,
        p.TenPhong,
        p.GioiTinhChoPhep,
        p.TinhTrang,
        p.MaChiNhanh,
        p.MaLoaiPhong,
        lp.TenLoaiPhong,
        lp.MoTa,
        lp.SucChuaToiDa,
        lp.GiaThueTheoGiuong,
        lp.GiaThueNguyenPhong,
        cn.TenChiNhanh,
        cn.DiaChi,
        COALESCE(bc.soGiuongTrong, 0) AS soGiuongTrong,
        (SELECT TOP 1 UrlImg FROM dbo.HinhAnhPhong hap WHERE hap.MaPhong = p.MaPhong ORDER BY hap.STTAnh) AS urlImg
    INTO #BaseRooms
    FROM dbo.Phong AS p
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
    INNER JOIN #ChiNhanhPhuHop AS cnp ON cnp.MaChiNhanh = p.MaChiNhanh
    INNER JOIN #LoaiPhongYeuCau AS lpyc ON lpyc.MaLoaiPhong = p.MaLoaiPhong
    LEFT JOIN BedCounts AS bc ON bc.MaPhong = p.MaPhong;

    CREATE TABLE #KetQua (
        phuongAn INT NOT NULL,
        maPhong VARCHAR(4) NULL,
        tenPhong VARCHAR(100) NULL,
        loaiThue VARCHAR(30) NULL,
        maLoaiPhong VARCHAR(6) NULL,
        loaiPhong VARCHAR(100) NULL,
        moTa TEXT NULL,
        giaThue DECIMAL(15,2) NULL,
        sucChua INT NULL,
        gioiTinhChoPhep VARCHAR(20) NULL,
        tinhTrang VARCHAR(20) NULL,
        maChiNhanh VARCHAR(6) NULL,
        tenChiNhanh VARCHAR(100) NULL,
        diaChi VARCHAR(255) NULL,
        urlImg VARCHAR(500) NULL,
        maGiuong VARCHAR(3) NULL,
        soGiuong INT NULL,
        soGiuongTrong INT NULL,
        soGiuongDuKienXep INT NULL,
        tongNamDuocXep INT NULL,
        tongNuDuocXep INT NULL,
        khongCoChiNhanhPhuHop BOOLEAN NOT NULL
    );

    CREATE TABLE #PhongUngVien (
        MaPhong VARCHAR(4) NOT NULL PRIMARY KEY,
        MaLoaiPhong VARCHAR(6) NOT NULL,
        GiaMoiNguoi DECIMAL(15,2) NOT NULL,
        LaTrongNguyenPhong BOOLEAN NOT NULL,
        SoGiuongNam INT NOT NULL,
        SoGiuongNu INT NOT NULL,
        SoGiuongKhongPhanBiet INT NOT NULL
    );

    INSERT INTO #PhongUngVien (
        MaPhong, MaLoaiPhong, GiaMoiNguoi, LaTrongNguyenPhong,
        SoGiuongNam, SoGiuongNu, SoGiuongKhongPhanBiet
    )
    SELECT
        br.MaPhong,
        br.MaLoaiPhong,
        COALESCE(br.GiaThueTheoGiuong, br.GiaThueNguyenPhong / NULLIF(br.SucChuaToiDa, 0)) AS GiaMoiNguoi,
        CASE
            WHEN br.TinhTrang = 'Trống'
             AND br.soGiuongTrong >= br.SucChuaToiDa
             AND br.GioiTinhChoPhep IN ('Không phân biệt', 'Khác', 'Hỗn hợp')
                THEN 1 ELSE 0
        END AS LaTrongNguyenPhong,
        CASE WHEN br.GioiTinhChoPhep = 'Nam' THEN br.soGiuongTrong ELSE 0 END AS SoGiuongNam,
        CASE WHEN br.GioiTinhChoPhep = 'Nữ' THEN br.soGiuongTrong ELSE 0 END AS SoGiuongNu,
        CASE WHEN br.GioiTinhChoPhep IN ('Không phân biệt', 'Khác', 'Hỗn hợp') THEN br.soGiuongTrong ELSE 0 END AS SoGiuongKhongPhanBiet
    FROM #BaseRooms AS br
    WHERE br.TinhTrang IN ('Trống', 'Còn chỗ')
      AND br.soGiuongTrong > 0
      AND COALESCE(br.GiaThueTheoGiuong, br.GiaThueNguyenPhong / NULLIF(br.SucChuaToiDa, 0)) IS NOT NULL
      AND (@MucGiaTu IS NULL OR COALESCE(br.GiaThueTheoGiuong, br.GiaThueNguyenPhong / NULLIF(br.SucChuaToiDa, 0)) >= @MucGiaTu)
      AND (@MucGiaToiDa IS NULL OR COALESCE(br.GiaThueTheoGiuong, br.GiaThueNguyenPhong / NULLIF(br.SucChuaToiDa, 0)) <= @MucGiaToiDa)
      AND (
          @Loai IS NULL
          OR @Loai = 'Ghép'
          OR (
              @Loai = 'Nguyên căn'
              AND br.TinhTrang = 'Trống'
              AND br.soGiuongTrong >= br.SucChuaToiDa
          )
      );

    CREATE TABLE #LoaiPhongHopLe (
        MaLoaiPhong VARCHAR(6) NOT NULL PRIMARY KEY
    );

    INSERT INTO #LoaiPhongHopLe (MaLoaiPhong)
    SELECT puv.MaLoaiPhong
    FROM #PhongUngVien AS puv
    GROUP BY puv.MaLoaiPhong
    HAVING
        (
            @LaNhomHonHop = 0
            AND MAX(CASE
                WHEN @GioiTinh = 'Nam'
                     AND (puv.SoGiuongNam + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep THEN 1
                WHEN @GioiTinh = 'Nữ'
                     AND (puv.SoGiuongNu + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep THEN 1
                WHEN @GioiTinh IS NULL
                     AND (puv.SoGiuongNam + puv.SoGiuongNu + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep THEN 1
                ELSE 0
            END) = 1
        )
        OR
        (
            @LaNhomHonHop = 1
            AND MAX(CASE WHEN puv.LaTrongNguyenPhong = 1 AND puv.SoGiuongKhongPhanBiet >= @SoNguoiCanXep THEN 1 ELSE 0 END) = 1
        );

    ;WITH PhongTraVe AS (
        SELECT
            ROW_NUMBER() OVER (
                PARTITION BY br.MaLoaiPhong
                ORDER BY
                    CASE WHEN puv.LaTrongNguyenPhong = 1 THEN 0 ELSE 1 END,
                    puv.GiaMoiNguoi,
                    br.TenPhong,
                    br.MaPhong
            ) AS rn,
            br.*,
            puv.GiaMoiNguoi,
            puv.LaTrongNguyenPhong
        FROM #BaseRooms AS br
        INNER JOIN #PhongUngVien AS puv ON puv.MaPhong = br.MaPhong
        INNER JOIN #LoaiPhongHopLe AS lphl ON lphl.MaLoaiPhong = br.MaLoaiPhong
        WHERE
            (
                @LaNhomHonHop = 0
                AND (
                    (@GioiTinh = 'Nam' AND (puv.SoGiuongNam + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep)
                    OR (@GioiTinh = 'Nữ' AND (puv.SoGiuongNu + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep)
                    OR (@GioiTinh IS NULL AND (puv.SoGiuongNam + puv.SoGiuongNu + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep)
                )
            )
            OR
            (
                @LaNhomHonHop = 1
                AND puv.LaTrongNguyenPhong = 1
                AND puv.SoGiuongKhongPhanBiet >= @SoNguoiCanXep
            )
    )
    INSERT INTO #KetQua (
        phuongAn, maPhong, tenPhong, loaiThue, maLoaiPhong, loaiPhong, moTa,
        giaThue, sucChua, gioiTinhChoPhep, tinhTrang, maChiNhanh, tenChiNhanh,
        diaChi, urlImg, maGiuong, soGiuong, soGiuongTrong, soGiuongDuKienXep,
        tongNamDuocXep, tongNuDuocXep, khongCoChiNhanhPhuHop
    )
    SELECT
        rn,
        MaPhong,
        TenPhong,
        CASE WHEN LaTrongNguyenPhong = 1 THEN 'Nguyên căn' ELSE 'Ghép' END,
        MaLoaiPhong,
        TenLoaiPhong,
        MoTa,
        GiaMoiNguoi,
        SucChuaToiDa,
        GioiTinhChoPhep,
        TinhTrang,
        MaChiNhanh,
        TenChiNhanh,
        DiaChi,
        urlImg,
        NULL,
        NULL,
        soGiuongTrong,
        CASE WHEN soGiuongTrong >= @SoNguoiCanXep THEN @SoNguoiCanXep ELSE soGiuongTrong END,
        COALESCE(@SoNam, 0),
        COALESCE(@SoNu, 0),
        @KhongCoChiNhanhPhuHop
    FROM PhongTraVe;

    SELECT *
    FROM #KetQua
    ORDER BY loaiThue, giaThue, loaiPhong, tenPhong, maGiuong;
END;
-- =============================================
-- 4. SP_KiemTraDieuKienThue
-- Kiểm tra hồ sơ đăng ký có đủ điều kiện để chuyển sang bước đặt cọc không.
-- Trả về: hopLe (BOOLEAN), lyDo (VARCHAR)
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_KiemTraDieuKienThue AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_KiemTraDieuKienThue
    @HoSoId VARCHAR(30)
AS
BEGIN
    

    SET @HoSoId = TRIM(@HoSoId));

    IF NOT EXISTS (SELECT 1 FROM dbo.PhieuDangKy WHERE MaDangKy = @HoSoId)
        RAISE EXCEPTION %;

    UPDATE dbo.LichXemPhong
    SET TrangThai = 'Đã xem'
    WHERE MaDangKy = @HoSoId
      AND TrangThai IN ('Chờ xem', 'Yêu cầu đổi lịch', 'Yêu cầu hủy')
      AND ThoiGianHen <= CURRENT_TIMESTAMP;

    DECLARE @TrangThai          VARCHAR(30);
    DECLARE @MaKhachHang        VARCHAR(6);
    DECLARE @NgayDuKienVaoO     DATE;
    DECLARE @SoLichXemDaXem     INT;

    SELECT
        @TrangThai          = pdk.TrangThai,
        @MaKhachHang        = pdk.MaKhachHang,
        @NgayDuKienVaoO     = pdk.ThoiGianDuKienVaoO
    FROM dbo.PhieuDangKy AS pdk
    WHERE pdk.MaDangKy = @HoSoId;

    -- Đếm số lần đã xem phòng thành công
    SELECT @SoLichXemDaXem = COUNT(*)
    FROM dbo.LichXemPhong
    WHERE MaDangKy = @HoSoId AND TrangThai = 'Đã xem';

    SELECT
        @HoSoId                             AS maDangKy,
        @TrangThai                          AS trangThai,
        @NgayDuKienVaoO                     AS ngayDuKienVaoO,
        @SoLichXemDaXem                     AS soLichXemDaXem,
        -- Hồ sơ hợp lệ khi: đang ở trạng thái Chờ tiếp nhận + đã xem phòng ít nhất 1 lần
        CAST(CASE
            WHEN @TrangThai = 'Chờ tiếp nhận' AND @SoLichXemDaXem >= 1 THEN 1
            ELSE 0
        END AS BOOLEAN)                         AS hopLe,
        CASE
            WHEN @TrangThai = 'Chờ xác nhận cọc' THEN 'Hồ sơ đã được chấp nhận và đang chờ đặt cọc.'
            WHEN @TrangThai = 'Chấp nhận'         THEN 'Hồ sơ đã được chấp nhận.'
            WHEN @TrangThai = 'Từ chối'           THEN 'Hồ sơ đã bị từ chối.'
            WHEN @SoLichXemDaXem < 1               THEN 'Khách hàng chưa xem phòng lần nào. Cần sắp xếp lịch xem phòng trước.'
            ELSE 'Hồ sơ đủ điều kiện tiến hành đặt cọc.'
        END                                 AS lyDo;
END;
-- =============================================
-- 5. SP_CapNhatKetQuaXuLyHoSo
-- Nhân viên Sale cập nhật kết quả xử lý hồ sơ đăng ký.
-- TrangThai hợp lệ: 'Chấp nhận', 'Từ chối', 'Chờ xác nhận cọc'
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_CapNhatKetQuaXuLyHoSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_CapNhatKetQuaXuLyHoSo
    @HoSoId         VARCHAR(30),
    @TrangThai      VARCHAR(50),
    @GhiChuXuLy     TEXT   = NULL,
    @NhanVienSaleId VARCHAR(20)    = NULL
AS
BEGIN
    
    

    SET @HoSoId         = TRIM(@HoSoId));
    SET @TrangThai      = TRIM(@TrangThai));
    SET @NhanVienSaleId = NULLIF(TRIM(@NhanVienSaleId)), '');
    SET @GhiChuXuLy     = NULLIF(TRIM(@GhiChuXuLy)), '');

    -- Kiểm tra hồ sơ tồn tại
    IF NOT EXISTS (SELECT 1 FROM dbo.PhieuDangKy WHERE MaDangKy = @HoSoId)
        RAISE EXCEPTION %;

    UPDATE dbo.LichXemPhong
    SET TrangThai = 'Đã xem'
    WHERE MaDangKy = @HoSoId
      AND TrangThai IN ('Chờ xem', 'Yêu cầu đổi lịch', 'Yêu cầu hủy')
      AND ThoiGianHen <= CURRENT_TIMESTAMP;

    -- Kiểm tra trạng thái mới hợp lệ
    IF @TrangThai NOT IN ('Chấp nhận', 'Từ chối', 'Chờ xác nhận cọc', 'Đã tiếp nhận')
        RAISE EXCEPTION %;

    -- Kiểm tra hồ sơ có đang ở trạng thái có thể cập nhật không
    DECLARE @TrangThaiHienTai VARCHAR(30);
    SELECT @TrangThaiHienTai = TrangThai FROM dbo.PhieuDangKy WHERE MaDangKy = @HoSoId;

    IF @TrangThaiHienTai NOT IN ('Chờ tiếp nhận', 'Chờ xác nhận cọc')
        RAISE EXCEPTION %;

    IF @NhanVienSaleId IS NOT NULL
       AND EXISTS (
           SELECT 1
           FROM dbo.PhieuDangKy
           WHERE MaDangKy = @HoSoId
             AND MaNhanVienSale IS NOT NULL
             AND MaNhanVienSale <> @NhanVienSaleId
       )
        RAISE EXCEPTION %;

    -- Kiểm tra nhân viên Sale tồn tại (nếu có truyền vào)
    IF @NhanVienSaleId IS NOT NULL
       AND NOT EXISTS (
           SELECT 1 FROM dbo.NhanVien WHERE MaNhanVien = @NhanVienSaleId AND ChucVu = 'Sale'
       )
        RAISE EXCEPTION %;

    -- Nếu chấp nhận hồ sơ hoặc chuyển sang bước cọc: khách phải đã xem phòng ít nhất 1 lần
    IF @TrangThai IN ('Chờ xác nhận cọc', 'Chấp nhận')
       AND NOT EXISTS (
           SELECT 1 FROM dbo.LichXemPhong
           WHERE MaDangKy = @HoSoId AND TrangThai = 'Đã xem'
       )
        RAISE EXCEPTION %;

    BEGIN TRY
        BEGIN TRANSACTION;
        IF @TrangThai = 'Chờ xác nhận cọc'
        BEGIN
            UPDATE dbo.PhieuDangKy
            SET TrangThai = @TrangThai,
                MaNhanVienSale = COALESCE(@NhanVienSaleId, MaNhanVienSale)
            WHERE MaDangKy = @HoSoId;

            -- Khi chuyển sang chờ đặt cọc, không cập nhật GhiChuSale
        END
        ELSE
        BEGIN
            UPDATE dbo.PhieuDangKy
            SET TrangThai = @TrangThai,
                GhiChuSale = COALESCE(@GhiChuXuLy, GhiChuSale),
                MaNhanVienSale = COALESCE(@NhanVienSaleId, MaNhanVienSale)
            WHERE MaDangKy = @HoSoId;
        END;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    -- Trả về hồ sơ sau khi cập nhật
    SELECT
        pdk.MaDangKy            AS maDangKy,
        pdk.NgayDangKy          AS ngayDangKy,
        pdk.SoNguoiDuKienO      AS soNguoiO,
        pdk.SoNam               AS soNam,
        pdk.SoNu                AS soNu,
        pdk.KhuVucMongMuon      AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = pdk.MaDangKy) AS loaiPhongYeuCau,
        pdk.MucGiaToiDa         AS mucGia,
        pdk.ThoiGianDuKienVaoO  AS ngayDuKienVaoO,
        pdk.ThoiHanThue         AS thoiHanThue,
        pdk.YeuCauKhac          AS ghiChu,
        pdk.TrangThai           AS trangThai,
        pdk.MaKhachHang         AS maKhachHang,
        nd.HoTen                AS hoTenKhach,
        nd.SDT                  AS sdtKhach,
        nd.Email                AS emailKhach,
        pdk.MaNhanVienSale      AS maNhanVienSale,
        nvnd.HoTen              AS hoTenSale
    FROM dbo.PhieuDangKy AS pdk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = pdk.MaKhachHang
    LEFT JOIN dbo.NguoiDung AS nvnd ON nvnd.MaNguoiDung = pdk.MaNhanVienSale
    WHERE pdk.MaDangKy = @HoSoId;
END;
-- =============================================
-- 9. SP_TraCuuPhong
-- Tra cứu toàn bộ danh sách phòng để hiển thị trên màn hình Tra Cứu Phòng của Sale
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_TraCuuPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_TraCuuPhong
    @KhuVuc         VARCHAR(100) = NULL,
    @LoaiPhong      VARCHAR(50)  = NULL,
    @HinhThucThue   VARCHAR(50)  = NULL,
    @MucGiaToiDa    DECIMAL(15,2) = NULL
AS
BEGIN
    

    SET @KhuVuc = NULLIF(TRIM(@KhuVuc)), '');
    SET @LoaiPhong = NULLIF(TRIM(@LoaiPhong)), '');
    SET @HinhThucThue = NULLIF(TRIM(@HinhThucThue)), '');

    IF @KhuVuc = 'Tất cả khu vực' SET @KhuVuc = NULL;
    IF @LoaiPhong = 'Tất cả loại phòng' SET @LoaiPhong = NULL;
    IF @HinhThucThue = 'Tất cả hình thức' SET @HinhThucThue = NULL;

    SELECT
        p.MaPhong AS id,
        p.TenPhong AS name,
        cn.TenChiNhanh AS subName,
        cn.DiaChi AS area,
        CASE
            WHEN p.GioiTinhChoPhep = 'Nam' THEN 'Ghép nam'
            WHEN p.GioiTinhChoPhep = 'Nữ' THEN 'Ghép nữ'
            ELSE 'Nguyên căn'
        END AS type,
        COALESCE(lp.GiaThueNguyenPhong, lp.GiaThueTheoGiuong) AS price,
        (
            SELECT COUNT(*)
            FROM dbo.Giuong g
            WHERE g.MaPhong = p.MaPhong AND g.TinhTrang = 'Trống'
        ) AS emptyBeds,
        lp.SucChuaToiDa AS capacity,
        p.TinhTrang AS status
    FROM dbo.Phong p
    INNER JOIN dbo.LoaiPhong lp ON p.MaLoaiPhong = lp.MaLoaiPhong
    INNER JOIN dbo.ChiNhanh cn ON p.MaChiNhanh = cn.MaChiNhanh
    WHERE cn.TrangThai = 'Hoạt động'
      AND (@KhuVuc IS NULL OR cn.DiaChi LIKE '%' + @KhuVuc + '%' OR cn.TenChiNhanh LIKE '%' + @KhuVuc + '%')
      AND (@LoaiPhong IS NULL OR lp.TenLoaiPhong = @LoaiPhong)
      AND (@HinhThucThue IS NULL OR
           (@HinhThucThue = 'Nguyên căn' AND (p.GioiTinhChoPhep = 'Không phân biệt' OR p.GioiTinhChoPhep IS NULL)) OR
           (@HinhThucThue = 'Ghép nam' AND p.GioiTinhChoPhep = 'Nam') OR
           (@HinhThucThue = 'Ghép nữ' AND p.GioiTinhChoPhep = 'Nữ')
          )
      AND (@MucGiaToiDa IS NULL OR COALESCE(lp.GiaThueNguyenPhong, lp.GiaThueTheoGiuong) <= @MucGiaToiDa)
    ORDER BY p.TenPhong;
END; THEN (SUBSTRING(MaDangKy, 3, 4)::INT ELSE NULL END)), 0) + 1
        FROM dbo.PhieuDangKy 
        WHERE MaDangKy LIKE 'DK%';

        SET @MaDangKy = CONCAT('DK', RIGHT(CONCAT('0000', @SoThuTu), 4));

        INSERT INTO dbo.PhieuDangKy (
            MaDangKy, NgayDangKy, SoNguoiDuKienO, SoNam, SoNu,
            MucGiaToiDa, ThoiGianDuKienVaoO, YeuCauKhac, TrangThai, MaKhachHang,
            KhuVucMongMuon, ThoiHanThue
        )
        VALUES (
            @MaDangKy, CAST(CURRENT_TIMESTAMP AS DATE), @SoNguoiO, @SoNam, @SoNu,
            @MucGiaToiDa, @NgayDuKienVaoO, @GhiChu, 'Chờ tiếp nhận', @KhachHangId,
            @KhuVucMongMuon, @ThoiHanThue
        );

        IF @LoaiPhongYeuCau IS NOT NULL
        BEGIN
            INSERT INTO dbo.PDK_LoaiPhong (MaDangKy, MaLoaiPhong)
            SELECT @MaDangKy, lp.MaLoaiPhong
            FROM dbo.LoaiPhong lp
            WHERE lp.TenLoaiPhong IN (SELECT TRIM(value)) FROM STRING_SPLIT(@LoaiPhongYeuCau, ','));
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    -- Trả về hồ sơ vừa tạo
    SELECT
        pdk.MaDangKy        AS maDangKy,
        pdk.NgayDangKy      AS ngayDangKy,
        pdk.SoNguoiDuKienO  AS soNguoiO,
        pdk.SoNam           AS soNam,
        pdk.SoNu            AS soNu,
        pdk.KhuVucMongMuon  AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = pdk.MaDangKy) AS loaiPhongYeuCau,
        pdk.MucGiaToiDa     AS mucGia,
        pdk.ThoiGianDuKienVaoO AS ngayDuKienVaoO,
        pdk.ThoiHanThue     AS thoiHanThue,
        pdk.YeuCauKhac      AS ghiChu,
        pdk.GhiChuSale      AS ghiChuSale,
        pdk.TrangThai       AS trangThai,
        pdk.MaKhachHang     AS maKhachHang,
        nd.HoTen            AS hoTenKhach,
        nd.SDT              AS sdtKhach,
        nd.Email            AS emailKhach
    FROM dbo.PhieuDangKy AS pdk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = pdk.MaKhachHang
    WHERE pdk.MaDangKy = @MaDangKy;
END;
-- =============================================
-- 6. SP_TiepNhanHoSoDangKy
-- Nhân viên Sale tiếp nhận hồ sơ đang ở trạng thái chờ tiếp nhận.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_TiepNhanHoSoDangKy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_TiepNhanHoSoDangKy
    @MaDangKy        VARCHAR(6),
    @NhanVienSaleId  VARCHAR(6)
AS
BEGIN
    
    

    SET @MaDangKy       = NULLIF(TRIM(@MaDangKy)), '');
    SET @NhanVienSaleId = NULLIF(TRIM(@NhanVienSaleId)), '');

    IF @MaDangKy IS NULL
        RAISE EXCEPTION %;

    IF @NhanVienSaleId IS NULL
        RAISE EXCEPTION %;

    IF NOT EXISTS (SELECT 1 FROM dbo.PhieuDangKy WHERE MaDangKy = @MaDangKy)
        RAISE EXCEPTION %;

    IF NOT EXISTS (
        SELECT 1
        FROM dbo.NhanVien
        WHERE MaNhanVien = @NhanVienSaleId
          AND ChucVu = 'Sale'
    )
        RAISE EXCEPTION %;

    IF NOT EXISTS (
        SELECT 1
        FROM dbo.PhieuDangKy
        WHERE MaDangKy = @MaDangKy
          AND TrangThai = 'Chờ tiếp nhận'
    )
        RAISE EXCEPTION %;

    DECLARE @SaleDangXuLy VARCHAR(6);
    SELECT @SaleDangXuLy = MaNhanVienSale
    FROM dbo.PhieuDangKy
    WHERE MaDangKy = @MaDangKy;

    IF @SaleDangXuLy IS NOT NULL AND @SaleDangXuLy <> @NhanVienSaleId
        RAISE EXCEPTION %;

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE dbo.PhieuDangKy
        SET MaNhanVienSale = @NhanVienSaleId
        WHERE MaDangKy = @MaDangKy
          AND TrangThai = 'Chờ tiếp nhận';

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        pdk.MaDangKy            AS maDangKy,
        pdk.NgayDangKy          AS ngayDangKy,
        pdk.SoNguoiDuKienO      AS soNguoiO,
        pdk.SoNam               AS soNam,
        pdk.SoNu                AS soNu,
        pdk.KhuVucMongMuon      AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = pdk.MaDangKy) AS loaiPhongYeuCau,
        pdk.MucGiaToiDa         AS mucGia,
        pdk.ThoiGianDuKienVaoO  AS ngayDuKienVaoO,
        pdk.ThoiHanThue         AS thoiHanThue,
        pdk.YeuCauKhac          AS ghiChu,
        pdk.GhiChuSale          AS ghiChuSale,
        pdk.TrangThai           AS trangThai,
        pdk.MaKhachHang         AS maKhachHang,
        nd.HoTen                AS hoTenKhach,
        nd.SDT                  AS sdtKhach,
        nd.Email                AS emailKhach,
        pdk.MaNhanVienSale      AS maNhanVienSale,
        nvnd.HoTen              AS hoTenSale
    FROM dbo.PhieuDangKy AS pdk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = pdk.MaKhachHang
    LEFT JOIN dbo.NguoiDung AS nvnd ON nvnd.MaNguoiDung = pdk.MaNhanVienSale
    WHERE pdk.MaDangKy = @MaDangKy;
END;
-- =============================================
-- 7. SP_HuyTiepNhanHoSoDangKy
-- Sale trả hồ sơ chưa lập lịch về hàng chờ tiếp nhận.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_HuyTiepNhanHoSoDangKy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_HuyTiepNhanHoSoDangKy
    @MaDangKy        VARCHAR(6),
    @NhanVienSaleId  VARCHAR(6)
AS
BEGIN
    
    

    SET @MaDangKy = NULLIF(TRIM(@MaDangKy)), '');
    SET @NhanVienSaleId = NULLIF(TRIM(@NhanVienSaleId)), '');

    IF NOT EXISTS (SELECT 1 FROM dbo.PhieuDangKy WHERE MaDangKy = @MaDangKy)
        RAISE EXCEPTION %;

    IF NOT EXISTS (
        SELECT 1
        FROM dbo.PhieuDangKy
        WHERE MaDangKy = @MaDangKy
          AND TrangThai = 'Đã tiếp nhận'
          AND MaNhanVienSale = @NhanVienSaleId
    )
        RAISE EXCEPTION %;

    IF EXISTS (SELECT 1 FROM dbo.LichXemPhong WHERE MaDangKy = @MaDangKy)
        RAISE EXCEPTION %;

    UPDATE dbo.PhieuDangKy
    SET TrangThai = 'Chờ tiếp nhận',
        MaNhanVienSale = NULL
    WHERE MaDangKy = @MaDangKy;

    SELECT
        MaDangKy AS maDangKy,
        TrangThai AS trangThai,
        MaNhanVienSale AS maNhanVienSale
    FROM dbo.PhieuDangKy
    WHERE MaDangKy = @MaDangKy;
END;
-- =============================================
-- 8. SP_TaoHoSoKhachVangLai
-- Sale tạo khách hàng mới và lập hồ sơ nhu cầu thuê trong cùng giao dịch.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_TaoHoSoKhachVangLai AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_TaoHoSoKhachVangLai
    @HoTen              VARCHAR(100),
    @NgaySinh           DATE,
    @GioiTinh           VARCHAR(5),
    @SDT                VARCHAR(20),
    @Email              VARCHAR(100)    = NULL,
    @QuocTich           VARCHAR(50)    = NULL,
    @CCCD               VARCHAR(20),
    @KhuVucMongMuon     VARCHAR(100),
    @LoaiPhongYeuCau    VARCHAR(200),
    @MucGiaToiDa        DECIMAL(15,2)   = NULL,
    @SoNguoiO           INT,
    @NgayDuKienVaoO     DATE,
    @ThoiHanThue        INT,
    @GhiChu             TEXT   = NULL,
    @NhanVienSaleId     VARCHAR(6),
    @HinhThucThue       VARCHAR(50)    = NULL,
    @SoNamInput         INT             = 0,
    @SoNuInput          INT             = 0
AS
BEGIN
    
    

    SET @HoTen              = NULLIF(TRIM(@HoTen)), '');
    SET @GioiTinh           = NULLIF(TRIM(@GioiTinh)), '');
    SET @SDT                = NULLIF(TRIM(@SDT)), '');
    SET @Email              = NULLIF(TRIM(@Email)), '');
    SET @QuocTich           = COALESCE(NULLIF(TRIM(@QuocTich)), ''), 'Việt Nam');
    SET @CCCD               = NULLIF(TRIM(@CCCD)), '');
    SET @HinhThucThue       = NULLIF(TRIM(@HinhThucThue)), '');

    SET @KhuVucMongMuon     = NULLIF(TRIM(@KhuVucMongMuon)), '');
    SET @LoaiPhongYeuCau    = NULLIF(TRIM(@LoaiPhongYeuCau)), '');
    SET @GhiChu             = NULLIF(TRIM(@GhiChu)), '');
    SET @NhanVienSaleId     = NULLIF(TRIM(@NhanVienSaleId)), '');

    IF @HoTen IS NULL OR @NgaySinh IS NULL OR @GioiTinh IS NULL OR @SDT IS NULL
       OR @CCCD IS NULL OR @KhuVucMongMuon IS NULL
       OR @LoaiPhongYeuCau IS NULL OR @NgayDuKienVaoO IS NULL
       OR @MucGiaToiDa IS NULL OR @SoNguoiO IS NULL OR @ThoiHanThue IS NULL OR @NhanVienSaleId IS NULL
        RAISE EXCEPTION %;

    IF @GioiTinh NOT IN ('Nam', 'Nữ', 'Hỗn hợp', 'Khác')
        RAISE EXCEPTION %;

    IF LENGTH(@SDT) <> 10 OR @SDT LIKE '%[^0-9]%'
        RAISE EXCEPTION %;

    IF LENGTH(@CCCD) <> 12 OR @CCCD LIKE '%[^0-9]%'
        RAISE EXCEPTION %;

    IF @NgaySinh >= CAST(CURRENT_TIMESTAMP AS DATE)
        RAISE EXCEPTION %;

    IF @NgayDuKienVaoO <= CAST(CURRENT_TIMESTAMP AS DATE)
        RAISE EXCEPTION %;

    IF @SoNguoiO < 1
        RAISE EXCEPTION %;

    IF @ThoiHanThue < 1
        RAISE EXCEPTION %;

    IF @MucGiaToiDa <= 0
        RAISE EXCEPTION %;

    IF NOT EXISTS (
        SELECT 1
        FROM dbo.NhanVien
        WHERE MaNhanVien = @NhanVienSaleId
          AND ChucVu = 'Sale'
    )
        RAISE EXCEPTION %;

    DECLARE @MaKhachHang VARCHAR(6);

    SELECT TOP (1) @MaKhachHang = kh.MaKhachHang
    FROM dbo.KhachHang AS kh
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = kh.MaKhachHang
    WHERE nd.SDT = @SDT
      AND nd.LoaiNguoiDung = 'KhachHang';

    IF @MaKhachHang IS NOT NULL
       AND EXISTS (
           SELECT 1
           FROM dbo.KhachHang
           WHERE MaKhachHang = @MaKhachHang
             AND COALESCE(CCCD, '') <> @CCCD
       )
        RAISE EXCEPTION %;

    IF EXISTS (
        SELECT 1
        FROM dbo.KhachHang
        WHERE CCCD = @CCCD
          AND (@MaKhachHang IS NULL OR MaKhachHang <> @MaKhachHang)
    )
        RAISE EXCEPTION %;

    IF @Email IS NOT NULL
       AND EXISTS (
           SELECT 1
           FROM dbo.NguoiDung
           WHERE Email = @Email
             AND LoaiNguoiDung = 'KhachHang'
             AND (@MaKhachHang IS NULL OR MaNguoiDung <> @MaKhachHang)
       )
        RAISE EXCEPTION %;

    DECLARE @SoKhach INT;
    DECLARE @SoDangKy INT;
    DECLARE @MaDangKy VARCHAR(6);

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @MaKhachHang IS NULL
        BEGIN
            SELECT @SoKhach = COALESCE(MAX(CASE WHEN (SUBSTRING(MaNguoiDung, 3, 4) ~ '^[0-9]+)), 0) + 1
            FROM dbo.NguoiDung 
            WHERE MaNguoiDung LIKE 'KH[0-9][0-9][0-9][0-9]';

            IF @SoKhach > 9999
                RAISE EXCEPTION %;

            SET @MaKhachHang = CONCAT('KH', RIGHT(CONCAT('0000', @SoKhach), 4));

            INSERT INTO dbo.NguoiDung (
                MaNguoiDung, HoTen, NgaySinh, GioiTinh, SDT, Email, UrlAvt, LoaiNguoiDung
            )
            VALUES (
                @MaKhachHang, @HoTen, @NgaySinh, @GioiTinh, @SDT, @Email, NULL, 'KhachHang'
            );

            INSERT INTO dbo.KhachHang (MaKhachHang, QuocTich, CCCD)
            VALUES (@MaKhachHang, @QuocTich, @CCCD);
        END;

        IF EXISTS (
            SELECT 1
            FROM dbo.HopDongThue 
            WHERE MaKhachHang = @MaKhachHang
              AND TrangThai NOT IN ('Hết hạn', 'Đã thanh lý')
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.PhieuDatCoc AS pdcLock 
            WHERE pdcLock.MaKhachHang = @MaKhachHang
              AND pdcLock.TrangThaiCoc <> 'Đã hủy'
              AND pdcLock.TrangThaiThanhToan <> 'Hết hạn'
              AND NOT EXISTS (
                  SELECT 1
                  FROM dbo.HopDongThue AS hd
                  WHERE hd.MaPhieuCoc = pdcLock.MaPhieuDatCoc
                    AND hd.TrangThai IN ('Hết hạn', 'Đã thanh lý')
              )
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.PhieuDangKy AS pdkLock 
            WHERE pdkLock.MaKhachHang = @MaKhachHang
              AND pdkLock.TrangThai <> 'Từ chối'
              AND NOT EXISTS (
                  SELECT 1
                  FROM dbo.PhieuDatCoc AS pdc
                  INNER JOIN dbo.HopDongThue AS hd ON hd.MaPhieuCoc = pdc.MaPhieuDatCoc
                  WHERE pdc.MaPhieuYeuCauDangKy = pdkLock.MaDangKy
                    AND hd.TrangThai IN ('Hết hạn', 'Đã thanh lý')
              )
        )
            RAISE EXCEPTION %;

        SELECT @SoDangKy = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDangKy, 3, 4))), 0) + 1
        FROM dbo.PhieuDangKy 
        WHERE MaDangKy LIKE 'DK[0-9][0-9][0-9][0-9]';

        IF @SoDangKy > 9999
            RAISE EXCEPTION %;

        SET @MaDangKy = CONCAT('DK', RIGHT(CONCAT('0000', @SoDangKy), 4));

        DECLARE @SoNam INT = COALESCE(@SoNamInput, 0);
        DECLARE @SoNu INT = COALESCE(@SoNuInput, 0);
        IF @GioiTinh = 'Nam' BEGIN
            SET @SoNam = @SoNguoiO;
            SET @SoNu = 0;
        END
        ELSE IF @GioiTinh = 'Nữ' BEGIN
            SET @SoNu = @SoNguoiO;
            SET @SoNam = 0;
        END
        ELSE IF @GioiTinh = 'Khác' OR @GioiTinh = 'Hỗn hợp' BEGIN
            IF @SoNam = 0 AND @SoNu = 0 SET @SoNam = @SoNguoiO;
        END
        ELSE BEGIN
            SET @SoNam = @SoNguoiO;
            SET @SoNu = 0;
        END

        INSERT INTO dbo.PhieuDangKy (
            MaDangKy, NgayDangKy, SoNguoiDuKienO, SoNam, SoNu,
            KhuVucMongMuon, MucGiaToiDa, ThoiGianDuKienVaoO,
            ThoiHanThue, YeuCauKhac, TrangThai, MaKhachHang, MaNhanVienSale
        )
        VALUES (
            @MaDangKy, CAST(CURRENT_TIMESTAMP AS DATE), @SoNguoiO, @SoNam, @SoNu,
            @KhuVucMongMuon, @MucGiaToiDa, @NgayDuKienVaoO,
            @ThoiHanThue, @GhiChu, 'Chờ tiếp nhận', @MaKhachHang, NULL
        );

        IF @LoaiPhongYeuCau IS NOT NULL
        BEGIN
            INSERT INTO dbo.PDK_LoaiPhong (MaDangKy, MaLoaiPhong)
            SELECT @MaDangKy, lp.MaLoaiPhong
            FROM dbo.LoaiPhong lp
            WHERE lp.TenLoaiPhong IN (SELECT TRIM(value)) FROM STRING_SPLIT(@LoaiPhongYeuCau, ','));
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        pdk.MaDangKy            AS maDangKy,
        pdk.NgayDangKy          AS ngayDangKy,
        pdk.SoNguoiDuKienO      AS soNguoiO,
        pdk.SoNam               AS soNam,
        pdk.SoNu                AS soNu,
        pdk.KhuVucMongMuon      AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = pdk.MaDangKy) AS loaiPhongYeuCau,
        pdk.MucGiaToiDa         AS mucGia,
        pdk.ThoiGianDuKienVaoO  AS ngayDuKienVaoO,
        pdk.ThoiHanThue         AS thoiHanThue,
        pdk.YeuCauKhac          AS ghiChu,
        pdk.GhiChuSale          AS ghiChuSale,
        pdk.TrangThai           AS trangThai,
        pdk.MaKhachHang         AS maKhachHang,
        nd.HoTen                AS hoTenKhach,
        nd.SDT                  AS sdtKhach,
        nd.Email                AS emailKhach,
        kh.QuocTich             AS quocTich,
        kh.CCCD                 AS cccd,
        pdk.MaNhanVienSale      AS maNhanVienSale,
        nvnd.HoTen              AS hoTenSale
    FROM dbo.PhieuDangKy AS pdk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = pdk.MaKhachHang
    INNER JOIN dbo.KhachHang AS kh ON kh.MaKhachHang = pdk.MaKhachHang
    LEFT JOIN dbo.NguoiDung AS nvnd ON nvnd.MaNguoiDung = pdk.MaNhanVienSale
    WHERE pdk.MaDangKy = @MaDangKy;
END;
-- =============================================
-- 8. SP_LayThongTinKhachHangChoDonDangKy
-- Lấy thông tin khách hàng và hồ sơ gần nhất để hệ thống tự động điền đơn đăng ký.
-- Có thể tìm bằng mã khách hàng, CCCD, số điện thoại hoặc email.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_LayThongTinKhachHangChoDonDangKy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_LayThongTinKhachHangChoDonDangKy
    @KhachHangId VARCHAR(6)   = NULL,
    @CCCD        VARCHAR(20)  = NULL,
    @SDT         VARCHAR(20)  = NULL,
    @Email       VARCHAR(100) = NULL
AS
BEGIN
    

    SET @KhachHangId = NULLIF(TRIM(@KhachHangId)), '');
    SET @CCCD        = NULLIF(TRIM(@CCCD)), '');
    SET @SDT         = NULLIF(TRIM(@SDT)), '');
    SET @Email       = NULLIF(TRIM(@Email)), '');

    IF @KhachHangId IS NULL AND @CCCD IS NULL AND @SDT IS NULL AND @Email IS NULL
        THROW 50011, 'Vui lòng nhập mã khách hàng, CCCD, số điện thoại hoặc email để tra cứu.', 1;

    DECLARE @MaKhachHangTimThay VARCHAR(6);

    SELECT TOP (1)
        @MaKhachHangTimThay = kh.MaKhachHang
    FROM dbo.KhachHang AS kh
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = kh.MaKhachHang
    WHERE (@KhachHangId IS NOT NULL AND kh.MaKhachHang = @KhachHangId)
       OR (@CCCD IS NOT NULL AND kh.CCCD = @CCCD)
       OR (@SDT IS NOT NULL AND nd.SDT = @SDT)
       OR (@Email IS NOT NULL AND nd.Email = @Email)
    ORDER BY
        CASE
            WHEN @KhachHangId IS NOT NULL AND kh.MaKhachHang = @KhachHangId THEN 1
            WHEN @CCCD IS NOT NULL AND kh.CCCD = @CCCD THEN 2
            WHEN @SDT IS NOT NULL AND nd.SDT = @SDT THEN 3
            WHEN @Email IS NOT NULL AND nd.Email = @Email THEN 4
            ELSE 5
        END,
        kh.MaKhachHang;

    IF @MaKhachHangTimThay IS NULL
        RAISE EXCEPTION %;

    SELECT
        kh.MaKhachHang          AS maKhachHang,
        nd.HoTen                AS hoTenKhach,
        nd.HoTen                AS hoTen,
        nd.NgaySinh             AS ngaySinh,
        nd.GioiTinh             AS gioiTinh,
        nd.SDT                  AS sdtKhach,
        nd.SDT                  AS soDienThoai,
        nd.Email                AS emailKhach,
        nd.Email                AS email,
        kh.QuocTich             AS quocTich,
        kh.CCCD                 AS cccd,
        hoSo.MaDangKy           AS maDangKyGanNhat,
        hoSo.KhuVucMongMuon     AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = hoSo.MaDangKy) AS loaiPhongYeuCau,
        hoSo.MucGiaToiDa        AS mucGia,
        hoSo.SoNguoiDuKienO     AS soNguoiO,
        hoSo.ThoiGianDuKienVaoO AS ngayDuKienVaoO,
        hoSo.ThoiHanThue        AS thoiHanThue,
        hoSo.YeuCauKhac         AS ghiChu,
        hoSo.GhiChuSale         AS ghiChuSale,
        hoSo.TrangThai          AS trangThaiHoSoGanNhat
    FROM dbo.KhachHang AS kh
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = kh.MaKhachHang
    OUTER APPLY (
        SELECT TOP (1)
            pdk.MaDangKy,
            pdk.KhuVucMongMuon,
            (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
             FROM dbo.PDK_LoaiPhong pdklp
             JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
             WHERE pdklp.MaDangKy = pdk.MaDangKy) AS LoaiPhongYeuCau,
            pdk.MucGiaToiDa,
            pdk.SoNguoiDuKienO,
            pdk.ThoiGianDuKienVaoO,
            pdk.ThoiHanThue,
            pdk.YeuCauKhac,
            pdk.GhiChuSale,
            pdk.TrangThai
        FROM dbo.PhieuDangKy AS pdk
        WHERE pdk.MaKhachHang = kh.MaKhachHang
        ORDER BY pdk.NgayDangKy DESC, pdk.MaDangKy DESC
    ) AS hoSo
    WHERE kh.MaKhachHang = @MaKhachHangTimThay;
END;
-- =============================================
-- 2. SP_DanhSachHoSoDangKy
-- Nhân viên Sale xem danh sách hồ sơ đăng ký thuê.
-- Mặc định lấy hồ sơ đang chờ xử lý.
-- Hỗ trợ lọc theo trạng thái và chi nhánh.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_DanhSachHoSoDangKy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_DanhSachHoSoDangKy
    @TrangThai      VARCHAR(30)    = NULL,     -- NULL = lấy tất cả; hoặc lọc theo trạng thái cụ thể
    @MaChiNhanh     VARCHAR(6)      = NULL,     -- NULL = tất cả chi nhánh
    @NhanVienSaleId VARCHAR(6)      = NULL,     -- NULL = không lọc theo sale
    @KhachHangId    VARCHAR(6)      = NULL      -- NULL = không lọc theo khách hàng
AS
BEGIN
    

    SET @TrangThai      = NULLIF(TRIM(@TrangThai)), '');
    SET @MaChiNhanh     = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @NhanVienSaleId = NULLIF(TRIM(@NhanVienSaleId)), '');
    SET @KhachHangId    = NULLIF(TRIM(@KhachHangId)), '');

    IF @TrangThai IS NOT NULL
       AND @TrangThai NOT IN ('Chờ tiếp nhận', 'Đã tiếp nhận', 'Chờ xác nhận cọc', 'Xác nhận cọc', 'Từ chối')
        RAISE EXCEPTION %;

    IF @MaChiNhanh IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
        RAISE EXCEPTION %;

    IF @NhanVienSaleId IS NOT NULL
       AND NOT EXISTS (
           SELECT 1 FROM dbo.NhanVien WHERE MaNhanVien = @NhanVienSaleId AND ChucVu = 'Sale'
       )
        RAISE EXCEPTION %;

    IF @KhachHangId IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM dbo.KhachHang WHERE MaKhachHang = @KhachHangId)
        RAISE EXCEPTION %;

    SELECT
        pdk.MaDangKy            AS maDangKy,
        pdk.NgayDangKy          AS ngayDangKy,
        pdk.SoNguoiDuKienO      AS soNguoiO,
        pdk.SoNam               AS soNam,
        pdk.SoNu                AS soNu,
        pdk.KhuVucMongMuon      AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = pdk.MaDangKy) AS loaiPhongYeuCau,
        pdk.MucGiaToiDa         AS mucGia,
        pdk.ThoiGianDuKienVaoO  AS ngayDuKienVaoO,
        pdk.ThoiHanThue         AS thoiHanThue,
        pdk.YeuCauKhac          AS ghiChu,
        pdk.GhiChuSale          AS ghiChuSale,
        pdk.TrangThai           AS trangThai,
        pdk.MaKhachHang         AS maKhachHang,
        nd.HoTen                AS hoTenKhach,
        nd.NgaySinh             AS ngaySinhKhach,
        nd.SDT                  AS sdtKhach,
        nd.Email                AS emailKhach,
        nd.GioiTinh             AS gioiTinh,
        kh.QuocTich             AS quocTich,
        kh.CCCD                 AS cccd,
        pdk.MaNhanVienSale      AS maNhanVienSale,
        nvnd.HoTen              AS hoTenSale,
        nvSale.MaChiNhanh       AS maChiNhanhSale,
        cnSale.TenChiNhanh      AS tenChiNhanhSale,
        -- Lịch xem phòng gần nhất
        lich.STTLich            AS sttLichMoiNhat,
        lich.ThoiGianHen        AS thoiGianHenMoiNhat,
        lich.TrangThai          AS trangThaiLichMoiNhat
    FROM dbo.PhieuDangKy AS pdk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = pdk.MaKhachHang
    INNER JOIN dbo.KhachHang AS kh ON kh.MaKhachHang = pdk.MaKhachHang
    LEFT JOIN dbo.NguoiDung AS nvnd ON nvnd.MaNguoiDung = pdk.MaNhanVienSale
    LEFT JOIN dbo.NhanVien AS nvSale ON nvSale.MaNhanVien = pdk.MaNhanVienSale
    LEFT JOIN dbo.ChiNhanh AS cnSale ON cnSale.MaChiNhanh = nvSale.MaChiNhanh
    OUTER APPLY (
        SELECT TOP (1) lxp.STTLich, lxp.ThoiGianHen, lxp.TrangThai
        FROM dbo.LichXemPhong AS lxp
        WHERE lxp.MaDangKy = pdk.MaDangKy
        ORDER BY lxp.STTLich DESC
    ) AS lich
    WHERE (@TrangThai IS NULL OR pdk.TrangThai = @TrangThai)
      AND (@NhanVienSaleId IS NULL OR pdk.MaNhanVienSale = @NhanVienSaleId)
      AND (@KhachHangId IS NULL OR pdk.MaKhachHang = @KhachHangId)
      AND (@MaChiNhanh IS NULL
           OR nvSale.MaChiNhanh = @MaChiNhanh
           OR EXISTS (
               SELECT 1 FROM dbo.ChiNhanh cn
               WHERE cn.MaChiNhanh = @MaChiNhanh
                 AND cn.TenChiNhanh LIKE '%' + pdk.KhuVucMongMuon + '%'
           )
           OR (
               @MaChiNhanh = 'CN0001'
               AND (
                   pdk.KhuVucMongMuon LIKE '%Quận 1%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 3%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 4%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 5%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 10%'
               )
           )
           OR (
               @MaChiNhanh = 'CN0002'
               AND (
                   pdk.KhuVucMongMuon LIKE '%Bình Thạnh%'
                   OR pdk.KhuVucMongMuon LIKE '%Phú Nhuận%'
                   OR pdk.KhuVucMongMuon LIKE '%Gò Vấp%'
                   OR pdk.KhuVucMongMuon LIKE '%Tân Bình%'
               )
           )
           OR (
               @MaChiNhanh = 'CN0003'
               AND (
                   pdk.KhuVucMongMuon LIKE '%Thủ Đức%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 2%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 9%'
               )
           )
      )
    ORDER BY pdk.NgayDangKy DESC, pdk.MaDangKy DESC;
END;
-- =============================================
-- 3. SP_DanhSachPhongGiuongKhaDung
-- Lấy danh sách phòng và giường còn trống để Sale gợi ý cho khách.
-- Hỗ trợ lọc theo loại, giới tính, chi nhánh, khu vực, loại phòng, mức giá, số người hoặc hồ sơ đăng ký.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_DanhSachPhongGiuongKhaDung AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_DanhSachPhongGiuongKhaDung
    @Loai           VARCHAR(50)    = NULL,     -- 'Nguyên căn' hoặc 'Ghép' hoặc NULL (lấy tất cả)
    @GioiTinh       VARCHAR(5)     = NULL,     -- 'Nam' hoặc 'Nữ' hoặc NULL
    @MaChiNhanh     VARCHAR(6)      = NULL,     -- Lọc theo chi nhánh
    @KhuVuc         VARCHAR(100)   = NULL,     -- Lọc theo địa chỉ/tên chi nhánh
    @LoaiPhong      VARCHAR(50)    = NULL,     -- Lọc theo tên loại phòng
    @MucGiaTu       DECIMAL(15,2)   = NULL,     -- Lọc theo ngân sách tối thiểu
    @MucGiaToiDa    DECIMAL(15,2)   = NULL,     -- Lọc theo ngân sách tối đa
    @SoNguoiO       INT             = NULL,     -- Lọc phòng đủ sức chứa/chỗ trống
    @HoSoId         VARCHAR(6)      = NULL      -- Tự lấy tiêu chí từ phiếu đăng ký
AS
BEGIN
    

    SET @Loai       = NULLIF(TRIM(@Loai)), '');
    SET @GioiTinh   = NULLIF(TRIM(@GioiTinh)), '');
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @KhuVuc     = NULLIF(TRIM(@KhuVuc)), '');
    SET @LoaiPhong  = NULLIF(TRIM(@LoaiPhong)), '');
    SET @HoSoId     = NULLIF(TRIM(@HoSoId)), '');

    DECLARE @SoNam INT = 0;
    DECLARE @SoNu INT = 0;
    DECLARE @HinhThucThue VARCHAR(50) = NULL;

    IF @HoSoId IS NOT NULL
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.PhieuDangKy WHERE MaDangKy = @HoSoId)
            RAISE EXCEPTION %;

        SELECT
            @SoNam       = COALESCE(SoNam, 0),
            @SoNu        = COALESCE(SoNu, 0),
            @KhuVuc      = COALESCE(@KhuVuc, KhuVucMongMuon),
            @MucGiaToiDa = COALESCE(@MucGiaToiDa, MucGiaToiDa),
            @SoNguoiO    = COALESCE(@SoNguoiO, SoNguoiDuKienO)
        FROM dbo.PhieuDangKy
        WHERE MaDangKy = @HoSoId;

        
        END

        IF @Loai IS NULL AND @HinhThucThue IS NOT NULL
            SET @Loai = @HinhThucThue;

        IF @GioiTinh IS NULL
        BEGIN
            IF @SoNam > 0 AND @SoNu = 0 SET @GioiTinh = 'Nam';
            ELSE IF @SoNu > 0 AND @SoNam = 0 SET @GioiTinh = 'Nữ';
        END
    END;

    IF @Loai IN ('Nguyên phòng', 'Nguyên căn')
        SET @Loai = 'Nguyên căn';
    IF @Loai IN ('Ghép giường', 'Ghép')
        SET @Loai = 'Ghép';

    IF @Loai IS NOT NULL AND @Loai NOT IN ('Nguyên căn', 'Ghép')
        RAISE EXCEPTION %;

    IF @GioiTinh IS NOT NULL AND @GioiTinh NOT IN ('Nam', 'Nữ')
        RAISE EXCEPTION %;

    IF @MucGiaTu IS NOT NULL AND @MucGiaTu < 0
        RAISE EXCEPTION %;

    IF @MucGiaToiDa IS NOT NULL AND @MucGiaToiDa < 0
        RAISE EXCEPTION %;

    IF @SoNguoiO IS NOT NULL AND @SoNguoiO < 1
        RAISE EXCEPTION %;

    IF @SoNguoiO IS NULL AND (@SoNam + @SoNu) > 0
        SET @SoNguoiO = @SoNam + @SoNu;

    DECLARE @SoNguoiCanXep INT = COALESCE(NULLIF(@SoNguoiO, 0), CASE WHEN (@SoNam + @SoNu) > 0 THEN @SoNam + @SoNu ELSE 1 END);
    DECLARE @LaNhomHonHop BOOLEAN = CASE WHEN @SoNam > 0 AND @SoNu > 0 THEN 1 ELSE 0 END;

    IF @MaChiNhanh IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
        RAISE EXCEPTION %;

    CREATE TABLE #ChiNhanhPhuHop (MaChiNhanh VARCHAR(6) PRIMARY KEY);

    IF @MaChiNhanh IS NOT NULL
    BEGIN
        INSERT INTO #ChiNhanhPhuHop (MaChiNhanh)
        SELECT MaChiNhanh
        FROM dbo.ChiNhanh
        WHERE MaChiNhanh = @MaChiNhanh
          AND TrangThai = 'Hoạt động';
    END
    ELSE IF @KhuVuc IS NULL
    BEGIN
        INSERT INTO #ChiNhanhPhuHop (MaChiNhanh)
        SELECT MaChiNhanh
        FROM dbo.ChiNhanh
        WHERE TrangThai = 'Hoạt động';
    END
    ELSE
    BEGIN
        INSERT INTO #ChiNhanhPhuHop (MaChiNhanh)
        SELECT MaChiNhanh
        FROM dbo.ChiNhanh
        WHERE TrangThai = 'Hoạt động'
          AND (DiaChi LIKE '%' + @KhuVuc + '%' OR TenChiNhanh LIKE '%' + @KhuVuc + '%');

        INSERT INTO #ChiNhanhPhuHop (MaChiNhanh)
        SELECT cn.MaChiNhanh
        FROM dbo.ChiNhanh AS cn
        WHERE cn.TrangThai = 'Hoạt động'
          AND (
              (
                  cn.MaChiNhanh = 'CN0001'
                  AND (
                      @KhuVuc LIKE '%Quận 1%'
                      OR @KhuVuc LIKE '%Quận 3%'
                      OR @KhuVuc LIKE '%Quận 4%'
                      OR @KhuVuc LIKE '%Quận 5%'
                      OR @KhuVuc LIKE '%Quận 10%'
                  )
              )
              OR (
                  cn.MaChiNhanh = 'CN0002'
                  AND (
                      @KhuVuc LIKE '%Bình Thạnh%'
                      OR @KhuVuc LIKE '%Phú Nhuận%'
                      OR @KhuVuc LIKE '%Gò Vấp%'
                      OR @KhuVuc LIKE '%Tân Bình%'
                  )
              )
              OR (
                  cn.MaChiNhanh = 'CN0003'
                  AND (
                      @KhuVuc LIKE '%Thủ Đức%'
                      OR @KhuVuc LIKE '%Quận 2%'
                      OR @KhuVuc LIKE '%Quận 9%'
                  )
              )
          )
          AND NOT EXISTS (
              SELECT 1
              FROM #ChiNhanhPhuHop AS existed
              WHERE existed.MaChiNhanh = cn.MaChiNhanh
          );
    END;

    DECLARE @KhongCoChiNhanhPhuHop BOOLEAN =
        CASE WHEN @MaChiNhanh IS NULL AND @KhuVuc IS NOT NULL AND NOT EXISTS (SELECT 1 FROM #ChiNhanhPhuHop)
             THEN 1 ELSE 0 END;

    CREATE TABLE #LoaiPhongYeuCau (MaLoaiPhong VARCHAR(6) PRIMARY KEY);

    IF @LoaiPhong IS NOT NULL
    BEGIN
        INSERT INTO #LoaiPhongYeuCau (MaLoaiPhong)
        SELECT MaLoaiPhong
        FROM dbo.LoaiPhong
        WHERE TenLoaiPhong = @LoaiPhong;
    END
    ELSE IF @HoSoId IS NOT NULL
       AND OBJECT_ID('dbo.PDK_LoaiPhong', 'U') IS NOT NULL
       AND EXISTS (SELECT 1 FROM dbo.PDK_LoaiPhong WHERE MaDangKy = @HoSoId)
    BEGIN
        INSERT INTO #LoaiPhongYeuCau (MaLoaiPhong)
        SELECT DISTINCT MaLoaiPhong
        FROM dbo.PDK_LoaiPhong
        WHERE MaDangKy = @HoSoId;
    END

    IF NOT EXISTS (SELECT 1 FROM #LoaiPhongYeuCau)
    BEGIN
        INSERT INTO #LoaiPhongYeuCau (MaLoaiPhong)
        SELECT MaLoaiPhong
        FROM dbo.LoaiPhong;
    END;

    ;WITH BedCounts AS (
        SELECT
            g.MaPhong,
            COUNT(CASE WHEN g.TinhTrang = 'Trống' THEN 1 END) AS soGiuongTrong
        FROM dbo.Giuong AS g
        GROUP BY g.MaPhong
    )
    SELECT
        p.MaPhong,
        p.TenPhong,
        p.GioiTinhChoPhep,
        p.TinhTrang,
        p.MaChiNhanh,
        p.MaLoaiPhong,
        lp.TenLoaiPhong,
        lp.MoTa,
        lp.SucChuaToiDa,
        lp.GiaThueTheoGiuong,
        lp.GiaThueNguyenPhong,
        cn.TenChiNhanh,
        cn.DiaChi,
        COALESCE(bc.soGiuongTrong, 0) AS soGiuongTrong,
        (SELECT TOP 1 UrlImg FROM dbo.HinhAnhPhong hap WHERE hap.MaPhong = p.MaPhong ORDER BY hap.STTAnh) AS urlImg
    INTO #BaseRooms
    FROM dbo.Phong AS p
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
    INNER JOIN #ChiNhanhPhuHop AS cnp ON cnp.MaChiNhanh = p.MaChiNhanh
    INNER JOIN #LoaiPhongYeuCau AS lpyc ON lpyc.MaLoaiPhong = p.MaLoaiPhong
    LEFT JOIN BedCounts AS bc ON bc.MaPhong = p.MaPhong;

    CREATE TABLE #KetQua (
        phuongAn INT NOT NULL,
        maPhong VARCHAR(4) NULL,
        tenPhong VARCHAR(100) NULL,
        loaiThue VARCHAR(30) NULL,
        maLoaiPhong VARCHAR(6) NULL,
        loaiPhong VARCHAR(100) NULL,
        moTa TEXT NULL,
        giaThue DECIMAL(15,2) NULL,
        sucChua INT NULL,
        gioiTinhChoPhep VARCHAR(20) NULL,
        tinhTrang VARCHAR(20) NULL,
        maChiNhanh VARCHAR(6) NULL,
        tenChiNhanh VARCHAR(100) NULL,
        diaChi VARCHAR(255) NULL,
        urlImg VARCHAR(500) NULL,
        maGiuong VARCHAR(3) NULL,
        soGiuong INT NULL,
        soGiuongTrong INT NULL,
        soGiuongDuKienXep INT NULL,
        tongNamDuocXep INT NULL,
        tongNuDuocXep INT NULL,
        khongCoChiNhanhPhuHop BOOLEAN NOT NULL
    );

    CREATE TABLE #PhongUngVien (
        MaPhong VARCHAR(4) NOT NULL PRIMARY KEY,
        MaLoaiPhong VARCHAR(6) NOT NULL,
        GiaMoiNguoi DECIMAL(15,2) NOT NULL,
        LaTrongNguyenPhong BOOLEAN NOT NULL,
        SoGiuongNam INT NOT NULL,
        SoGiuongNu INT NOT NULL,
        SoGiuongKhongPhanBiet INT NOT NULL
    );

    INSERT INTO #PhongUngVien (
        MaPhong, MaLoaiPhong, GiaMoiNguoi, LaTrongNguyenPhong,
        SoGiuongNam, SoGiuongNu, SoGiuongKhongPhanBiet
    )
    SELECT
        br.MaPhong,
        br.MaLoaiPhong,
        COALESCE(br.GiaThueTheoGiuong, br.GiaThueNguyenPhong / NULLIF(br.SucChuaToiDa, 0)) AS GiaMoiNguoi,
        CASE
            WHEN br.TinhTrang = 'Trống'
             AND br.soGiuongTrong >= br.SucChuaToiDa
             AND br.GioiTinhChoPhep IN ('Không phân biệt', 'Khác', 'Hỗn hợp')
                THEN 1 ELSE 0
        END AS LaTrongNguyenPhong,
        CASE WHEN br.GioiTinhChoPhep = 'Nam' THEN br.soGiuongTrong ELSE 0 END AS SoGiuongNam,
        CASE WHEN br.GioiTinhChoPhep = 'Nữ' THEN br.soGiuongTrong ELSE 0 END AS SoGiuongNu,
        CASE WHEN br.GioiTinhChoPhep IN ('Không phân biệt', 'Khác', 'Hỗn hợp') THEN br.soGiuongTrong ELSE 0 END AS SoGiuongKhongPhanBiet
    FROM #BaseRooms AS br
    WHERE br.TinhTrang IN ('Trống', 'Còn chỗ')
      AND br.soGiuongTrong > 0
      AND COALESCE(br.GiaThueTheoGiuong, br.GiaThueNguyenPhong / NULLIF(br.SucChuaToiDa, 0)) IS NOT NULL
      AND (@MucGiaTu IS NULL OR COALESCE(br.GiaThueTheoGiuong, br.GiaThueNguyenPhong / NULLIF(br.SucChuaToiDa, 0)) >= @MucGiaTu)
      AND (@MucGiaToiDa IS NULL OR COALESCE(br.GiaThueTheoGiuong, br.GiaThueNguyenPhong / NULLIF(br.SucChuaToiDa, 0)) <= @MucGiaToiDa)
      AND (
          @Loai IS NULL
          OR @Loai = 'Ghép'
          OR (
              @Loai = 'Nguyên căn'
              AND br.TinhTrang = 'Trống'
              AND br.soGiuongTrong >= br.SucChuaToiDa
          )
      );

    CREATE TABLE #LoaiPhongHopLe (
        MaLoaiPhong VARCHAR(6) NOT NULL PRIMARY KEY
    );

    INSERT INTO #LoaiPhongHopLe (MaLoaiPhong)
    SELECT puv.MaLoaiPhong
    FROM #PhongUngVien AS puv
    GROUP BY puv.MaLoaiPhong
    HAVING
        (
            @LaNhomHonHop = 0
            AND MAX(CASE
                WHEN @GioiTinh = 'Nam'
                     AND (puv.SoGiuongNam + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep THEN 1
                WHEN @GioiTinh = 'Nữ'
                     AND (puv.SoGiuongNu + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep THEN 1
                WHEN @GioiTinh IS NULL
                     AND (puv.SoGiuongNam + puv.SoGiuongNu + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep THEN 1
                ELSE 0
            END) = 1
        )
        OR
        (
            @LaNhomHonHop = 1
            AND MAX(CASE WHEN puv.LaTrongNguyenPhong = 1 AND puv.SoGiuongKhongPhanBiet >= @SoNguoiCanXep THEN 1 ELSE 0 END) = 1
        );

    ;WITH PhongTraVe AS (
        SELECT
            ROW_NUMBER() OVER (
                PARTITION BY br.MaLoaiPhong
                ORDER BY
                    CASE WHEN puv.LaTrongNguyenPhong = 1 THEN 0 ELSE 1 END,
                    puv.GiaMoiNguoi,
                    br.TenPhong,
                    br.MaPhong
            ) AS rn,
            br.*,
            puv.GiaMoiNguoi,
            puv.LaTrongNguyenPhong
        FROM #BaseRooms AS br
        INNER JOIN #PhongUngVien AS puv ON puv.MaPhong = br.MaPhong
        INNER JOIN #LoaiPhongHopLe AS lphl ON lphl.MaLoaiPhong = br.MaLoaiPhong
        WHERE
            (
                @LaNhomHonHop = 0
                AND (
                    (@GioiTinh = 'Nam' AND (puv.SoGiuongNam + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep)
                    OR (@GioiTinh = 'Nữ' AND (puv.SoGiuongNu + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep)
                    OR (@GioiTinh IS NULL AND (puv.SoGiuongNam + puv.SoGiuongNu + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep)
                )
            )
            OR
            (
                @LaNhomHonHop = 1
                AND puv.LaTrongNguyenPhong = 1
                AND puv.SoGiuongKhongPhanBiet >= @SoNguoiCanXep
            )
    )
    INSERT INTO #KetQua (
        phuongAn, maPhong, tenPhong, loaiThue, maLoaiPhong, loaiPhong, moTa,
        giaThue, sucChua, gioiTinhChoPhep, tinhTrang, maChiNhanh, tenChiNhanh,
        diaChi, urlImg, maGiuong, soGiuong, soGiuongTrong, soGiuongDuKienXep,
        tongNamDuocXep, tongNuDuocXep, khongCoChiNhanhPhuHop
    )
    SELECT
        rn,
        MaPhong,
        TenPhong,
        CASE WHEN LaTrongNguyenPhong = 1 THEN 'Nguyên căn' ELSE 'Ghép' END,
        MaLoaiPhong,
        TenLoaiPhong,
        MoTa,
        GiaMoiNguoi,
        SucChuaToiDa,
        GioiTinhChoPhep,
        TinhTrang,
        MaChiNhanh,
        TenChiNhanh,
        DiaChi,
        urlImg,
        NULL,
        NULL,
        soGiuongTrong,
        CASE WHEN soGiuongTrong >= @SoNguoiCanXep THEN @SoNguoiCanXep ELSE soGiuongTrong END,
        COALESCE(@SoNam, 0),
        COALESCE(@SoNu, 0),
        @KhongCoChiNhanhPhuHop
    FROM PhongTraVe;

    SELECT *
    FROM #KetQua
    ORDER BY loaiThue, giaThue, loaiPhong, tenPhong, maGiuong;
END;
-- =============================================
-- 4. SP_KiemTraDieuKienThue
-- Kiểm tra hồ sơ đăng ký có đủ điều kiện để chuyển sang bước đặt cọc không.
-- Trả về: hopLe (BOOLEAN), lyDo (VARCHAR)
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_KiemTraDieuKienThue AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_KiemTraDieuKienThue
    @HoSoId VARCHAR(30)
AS
BEGIN
    

    SET @HoSoId = TRIM(@HoSoId));

    IF NOT EXISTS (SELECT 1 FROM dbo.PhieuDangKy WHERE MaDangKy = @HoSoId)
        RAISE EXCEPTION %;

    UPDATE dbo.LichXemPhong
    SET TrangThai = 'Đã xem'
    WHERE MaDangKy = @HoSoId
      AND TrangThai IN ('Chờ xem', 'Yêu cầu đổi lịch', 'Yêu cầu hủy')
      AND ThoiGianHen <= CURRENT_TIMESTAMP;

    DECLARE @TrangThai          VARCHAR(30);
    DECLARE @MaKhachHang        VARCHAR(6);
    DECLARE @NgayDuKienVaoO     DATE;
    DECLARE @SoLichXemDaXem     INT;

    SELECT
        @TrangThai          = pdk.TrangThai,
        @MaKhachHang        = pdk.MaKhachHang,
        @NgayDuKienVaoO     = pdk.ThoiGianDuKienVaoO
    FROM dbo.PhieuDangKy AS pdk
    WHERE pdk.MaDangKy = @HoSoId;

    -- Đếm số lần đã xem phòng thành công
    SELECT @SoLichXemDaXem = COUNT(*)
    FROM dbo.LichXemPhong
    WHERE MaDangKy = @HoSoId AND TrangThai = 'Đã xem';

    SELECT
        @HoSoId                             AS maDangKy,
        @TrangThai                          AS trangThai,
        @NgayDuKienVaoO                     AS ngayDuKienVaoO,
        @SoLichXemDaXem                     AS soLichXemDaXem,
        -- Hồ sơ hợp lệ khi: đang ở trạng thái Chờ tiếp nhận + đã xem phòng ít nhất 1 lần
        CAST(CASE
            WHEN @TrangThai = 'Chờ tiếp nhận' AND @SoLichXemDaXem >= 1 THEN 1
            ELSE 0
        END AS BOOLEAN)                         AS hopLe,
        CASE
            WHEN @TrangThai = 'Chờ xác nhận cọc' THEN 'Hồ sơ đã được chấp nhận và đang chờ đặt cọc.'
            WHEN @TrangThai = 'Chấp nhận'         THEN 'Hồ sơ đã được chấp nhận.'
            WHEN @TrangThai = 'Từ chối'           THEN 'Hồ sơ đã bị từ chối.'
            WHEN @SoLichXemDaXem < 1               THEN 'Khách hàng chưa xem phòng lần nào. Cần sắp xếp lịch xem phòng trước.'
            ELSE 'Hồ sơ đủ điều kiện tiến hành đặt cọc.'
        END                                 AS lyDo;
END;
-- =============================================
-- 5. SP_CapNhatKetQuaXuLyHoSo
-- Nhân viên Sale cập nhật kết quả xử lý hồ sơ đăng ký.
-- TrangThai hợp lệ: 'Chấp nhận', 'Từ chối', 'Chờ xác nhận cọc'
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_CapNhatKetQuaXuLyHoSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_CapNhatKetQuaXuLyHoSo
    @HoSoId         VARCHAR(30),
    @TrangThai      VARCHAR(50),
    @GhiChuXuLy     TEXT   = NULL,
    @NhanVienSaleId VARCHAR(20)    = NULL
AS
BEGIN
    
    

    SET @HoSoId         = TRIM(@HoSoId));
    SET @TrangThai      = TRIM(@TrangThai));
    SET @NhanVienSaleId = NULLIF(TRIM(@NhanVienSaleId)), '');
    SET @GhiChuXuLy     = NULLIF(TRIM(@GhiChuXuLy)), '');

    -- Kiểm tra hồ sơ tồn tại
    IF NOT EXISTS (SELECT 1 FROM dbo.PhieuDangKy WHERE MaDangKy = @HoSoId)
        RAISE EXCEPTION %;

    UPDATE dbo.LichXemPhong
    SET TrangThai = 'Đã xem'
    WHERE MaDangKy = @HoSoId
      AND TrangThai IN ('Chờ xem', 'Yêu cầu đổi lịch', 'Yêu cầu hủy')
      AND ThoiGianHen <= CURRENT_TIMESTAMP;

    -- Kiểm tra trạng thái mới hợp lệ
    IF @TrangThai NOT IN ('Chấp nhận', 'Từ chối', 'Chờ xác nhận cọc', 'Đã tiếp nhận')
        RAISE EXCEPTION %;

    -- Kiểm tra hồ sơ có đang ở trạng thái có thể cập nhật không
    DECLARE @TrangThaiHienTai VARCHAR(30);
    SELECT @TrangThaiHienTai = TrangThai FROM dbo.PhieuDangKy WHERE MaDangKy = @HoSoId;

    IF @TrangThaiHienTai NOT IN ('Chờ tiếp nhận', 'Chờ xác nhận cọc')
        RAISE EXCEPTION %;

    IF @NhanVienSaleId IS NOT NULL
       AND EXISTS (
           SELECT 1
           FROM dbo.PhieuDangKy
           WHERE MaDangKy = @HoSoId
             AND MaNhanVienSale IS NOT NULL
             AND MaNhanVienSale <> @NhanVienSaleId
       )
        RAISE EXCEPTION %;

    -- Kiểm tra nhân viên Sale tồn tại (nếu có truyền vào)
    IF @NhanVienSaleId IS NOT NULL
       AND NOT EXISTS (
           SELECT 1 FROM dbo.NhanVien WHERE MaNhanVien = @NhanVienSaleId AND ChucVu = 'Sale'
       )
        RAISE EXCEPTION %;

    -- Nếu chấp nhận hồ sơ hoặc chuyển sang bước cọc: khách phải đã xem phòng ít nhất 1 lần
    IF @TrangThai IN ('Chờ xác nhận cọc', 'Chấp nhận')
       AND NOT EXISTS (
           SELECT 1 FROM dbo.LichXemPhong
           WHERE MaDangKy = @HoSoId AND TrangThai = 'Đã xem'
       )
        RAISE EXCEPTION %;

    BEGIN TRY
        BEGIN TRANSACTION;
        IF @TrangThai = 'Chờ xác nhận cọc'
        BEGIN
            UPDATE dbo.PhieuDangKy
            SET TrangThai = @TrangThai,
                MaNhanVienSale = COALESCE(@NhanVienSaleId, MaNhanVienSale)
            WHERE MaDangKy = @HoSoId;

            -- Khi chuyển sang chờ đặt cọc, không cập nhật GhiChuSale
        END
        ELSE
        BEGIN
            UPDATE dbo.PhieuDangKy
            SET TrangThai = @TrangThai,
                GhiChuSale = COALESCE(@GhiChuXuLy, GhiChuSale),
                MaNhanVienSale = COALESCE(@NhanVienSaleId, MaNhanVienSale)
            WHERE MaDangKy = @HoSoId;
        END;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    -- Trả về hồ sơ sau khi cập nhật
    SELECT
        pdk.MaDangKy            AS maDangKy,
        pdk.NgayDangKy          AS ngayDangKy,
        pdk.SoNguoiDuKienO      AS soNguoiO,
        pdk.SoNam               AS soNam,
        pdk.SoNu                AS soNu,
        pdk.KhuVucMongMuon      AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = pdk.MaDangKy) AS loaiPhongYeuCau,
        pdk.MucGiaToiDa         AS mucGia,
        pdk.ThoiGianDuKienVaoO  AS ngayDuKienVaoO,
        pdk.ThoiHanThue         AS thoiHanThue,
        pdk.YeuCauKhac          AS ghiChu,
        pdk.TrangThai           AS trangThai,
        pdk.MaKhachHang         AS maKhachHang,
        nd.HoTen                AS hoTenKhach,
        nd.SDT                  AS sdtKhach,
        nd.Email                AS emailKhach,
        pdk.MaNhanVienSale      AS maNhanVienSale,
        nvnd.HoTen              AS hoTenSale
    FROM dbo.PhieuDangKy AS pdk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = pdk.MaKhachHang
    LEFT JOIN dbo.NguoiDung AS nvnd ON nvnd.MaNguoiDung = pdk.MaNhanVienSale
    WHERE pdk.MaDangKy = @HoSoId;
END;
-- =============================================
-- 9. SP_TraCuuPhong
-- Tra cứu toàn bộ danh sách phòng để hiển thị trên màn hình Tra Cứu Phòng của Sale
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_TraCuuPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_TraCuuPhong
    @KhuVuc         VARCHAR(100) = NULL,
    @LoaiPhong      VARCHAR(50)  = NULL,
    @HinhThucThue   VARCHAR(50)  = NULL,
    @MucGiaToiDa    DECIMAL(15,2) = NULL
AS
BEGIN
    

    SET @KhuVuc = NULLIF(TRIM(@KhuVuc)), '');
    SET @LoaiPhong = NULLIF(TRIM(@LoaiPhong)), '');
    SET @HinhThucThue = NULLIF(TRIM(@HinhThucThue)), '');

    IF @KhuVuc = 'Tất cả khu vực' SET @KhuVuc = NULL;
    IF @LoaiPhong = 'Tất cả loại phòng' SET @LoaiPhong = NULL;
    IF @HinhThucThue = 'Tất cả hình thức' SET @HinhThucThue = NULL;

    SELECT
        p.MaPhong AS id,
        p.TenPhong AS name,
        cn.TenChiNhanh AS subName,
        cn.DiaChi AS area,
        CASE
            WHEN p.GioiTinhChoPhep = 'Nam' THEN 'Ghép nam'
            WHEN p.GioiTinhChoPhep = 'Nữ' THEN 'Ghép nữ'
            ELSE 'Nguyên căn'
        END AS type,
        COALESCE(lp.GiaThueNguyenPhong, lp.GiaThueTheoGiuong) AS price,
        (
            SELECT COUNT(*)
            FROM dbo.Giuong g
            WHERE g.MaPhong = p.MaPhong AND g.TinhTrang = 'Trống'
        ) AS emptyBeds,
        lp.SucChuaToiDa AS capacity,
        p.TinhTrang AS status
    FROM dbo.Phong p
    INNER JOIN dbo.LoaiPhong lp ON p.MaLoaiPhong = lp.MaLoaiPhong
    INNER JOIN dbo.ChiNhanh cn ON p.MaChiNhanh = cn.MaChiNhanh
    WHERE cn.TrangThai = 'Hoạt động'
      AND (@KhuVuc IS NULL OR cn.DiaChi LIKE '%' + @KhuVuc + '%' OR cn.TenChiNhanh LIKE '%' + @KhuVuc + '%')
      AND (@LoaiPhong IS NULL OR lp.TenLoaiPhong = @LoaiPhong)
      AND (@HinhThucThue IS NULL OR
           (@HinhThucThue = 'Nguyên căn' AND (p.GioiTinhChoPhep = 'Không phân biệt' OR p.GioiTinhChoPhep IS NULL)) OR
           (@HinhThucThue = 'Ghép nam' AND p.GioiTinhChoPhep = 'Nam') OR
           (@HinhThucThue = 'Ghép nữ' AND p.GioiTinhChoPhep = 'Nữ')
          )
      AND (@MucGiaToiDa IS NULL OR COALESCE(lp.GiaThueNguyenPhong, lp.GiaThueTheoGiuong) <= @MucGiaToiDa)
    ORDER BY p.TenPhong;
END; THEN (SUBSTRING(MaNguoiDung, 3, 4)::INT ELSE NULL END)), 0) + 1
            FROM dbo.NguoiDung 
            WHERE MaNguoiDung LIKE 'KH[0-9][0-9][0-9][0-9]';

            IF @SoKhach > 9999
                RAISE EXCEPTION %;

            SET @MaKhachHang = CONCAT('KH', RIGHT(CONCAT('0000', @SoKhach), 4));

            INSERT INTO dbo.NguoiDung (
                MaNguoiDung, HoTen, NgaySinh, GioiTinh, SDT, Email, UrlAvt, LoaiNguoiDung
            )
            VALUES (
                @MaKhachHang, @HoTen, @NgaySinh, @GioiTinh, @SDT, @Email, NULL, 'KhachHang'
            );

            INSERT INTO dbo.KhachHang (MaKhachHang, QuocTich, CCCD)
            VALUES (@MaKhachHang, @QuocTich, @CCCD);
        END;

        IF EXISTS (
            SELECT 1
            FROM dbo.HopDongThue 
            WHERE MaKhachHang = @MaKhachHang
              AND TrangThai NOT IN ('Hết hạn', 'Đã thanh lý')
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.PhieuDatCoc AS pdcLock 
            WHERE pdcLock.MaKhachHang = @MaKhachHang
              AND pdcLock.TrangThaiCoc <> 'Đã hủy'
              AND pdcLock.TrangThaiThanhToan <> 'Hết hạn'
              AND NOT EXISTS (
                  SELECT 1
                  FROM dbo.HopDongThue AS hd
                  WHERE hd.MaPhieuCoc = pdcLock.MaPhieuDatCoc
                    AND hd.TrangThai IN ('Hết hạn', 'Đã thanh lý')
              )
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.PhieuDangKy AS pdkLock 
            WHERE pdkLock.MaKhachHang = @MaKhachHang
              AND pdkLock.TrangThai <> 'Từ chối'
              AND NOT EXISTS (
                  SELECT 1
                  FROM dbo.PhieuDatCoc AS pdc
                  INNER JOIN dbo.HopDongThue AS hd ON hd.MaPhieuCoc = pdc.MaPhieuDatCoc
                  WHERE pdc.MaPhieuYeuCauDangKy = pdkLock.MaDangKy
                    AND hd.TrangThai IN ('Hết hạn', 'Đã thanh lý')
              )
        )
            RAISE EXCEPTION %;

        SELECT @SoDangKy = COALESCE(MAX(CASE WHEN (SUBSTRING(MaDangKy, 3, 4) ~ '^[0-9]+)), 0) + 1
        FROM dbo.PhieuDangKy 
        WHERE MaDangKy LIKE 'DK[0-9][0-9][0-9][0-9]';

        IF @SoDangKy > 9999
            RAISE EXCEPTION %;

        SET @MaDangKy = CONCAT('DK', RIGHT(CONCAT('0000', @SoDangKy), 4));

        DECLARE @SoNam INT = COALESCE(@SoNamInput, 0);
        DECLARE @SoNu INT = COALESCE(@SoNuInput, 0);
        IF @GioiTinh = 'Nam' BEGIN
            SET @SoNam = @SoNguoiO;
            SET @SoNu = 0;
        END
        ELSE IF @GioiTinh = 'Nữ' BEGIN
            SET @SoNu = @SoNguoiO;
            SET @SoNam = 0;
        END
        ELSE IF @GioiTinh = 'Khác' OR @GioiTinh = 'Hỗn hợp' BEGIN
            IF @SoNam = 0 AND @SoNu = 0 SET @SoNam = @SoNguoiO;
        END
        ELSE BEGIN
            SET @SoNam = @SoNguoiO;
            SET @SoNu = 0;
        END

        INSERT INTO dbo.PhieuDangKy (
            MaDangKy, NgayDangKy, SoNguoiDuKienO, SoNam, SoNu,
            KhuVucMongMuon, MucGiaToiDa, ThoiGianDuKienVaoO,
            ThoiHanThue, YeuCauKhac, TrangThai, MaKhachHang, MaNhanVienSale
        )
        VALUES (
            @MaDangKy, CAST(CURRENT_TIMESTAMP AS DATE), @SoNguoiO, @SoNam, @SoNu,
            @KhuVucMongMuon, @MucGiaToiDa, @NgayDuKienVaoO,
            @ThoiHanThue, @GhiChu, 'Chờ tiếp nhận', @MaKhachHang, NULL
        );

        IF @LoaiPhongYeuCau IS NOT NULL
        BEGIN
            INSERT INTO dbo.PDK_LoaiPhong (MaDangKy, MaLoaiPhong)
            SELECT @MaDangKy, lp.MaLoaiPhong
            FROM dbo.LoaiPhong lp
            WHERE lp.TenLoaiPhong IN (SELECT TRIM(value)) FROM STRING_SPLIT(@LoaiPhongYeuCau, ','));
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        pdk.MaDangKy            AS maDangKy,
        pdk.NgayDangKy          AS ngayDangKy,
        pdk.SoNguoiDuKienO      AS soNguoiO,
        pdk.SoNam               AS soNam,
        pdk.SoNu                AS soNu,
        pdk.KhuVucMongMuon      AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = pdk.MaDangKy) AS loaiPhongYeuCau,
        pdk.MucGiaToiDa         AS mucGia,
        pdk.ThoiGianDuKienVaoO  AS ngayDuKienVaoO,
        pdk.ThoiHanThue         AS thoiHanThue,
        pdk.YeuCauKhac          AS ghiChu,
        pdk.GhiChuSale          AS ghiChuSale,
        pdk.TrangThai           AS trangThai,
        pdk.MaKhachHang         AS maKhachHang,
        nd.HoTen                AS hoTenKhach,
        nd.SDT                  AS sdtKhach,
        nd.Email                AS emailKhach,
        kh.QuocTich             AS quocTich,
        kh.CCCD                 AS cccd,
        pdk.MaNhanVienSale      AS maNhanVienSale,
        nvnd.HoTen              AS hoTenSale
    FROM dbo.PhieuDangKy AS pdk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = pdk.MaKhachHang
    INNER JOIN dbo.KhachHang AS kh ON kh.MaKhachHang = pdk.MaKhachHang
    LEFT JOIN dbo.NguoiDung AS nvnd ON nvnd.MaNguoiDung = pdk.MaNhanVienSale
    WHERE pdk.MaDangKy = @MaDangKy;
END;
-- =============================================
-- 8. SP_LayThongTinKhachHangChoDonDangKy
-- Lấy thông tin khách hàng và hồ sơ gần nhất để hệ thống tự động điền đơn đăng ký.
-- Có thể tìm bằng mã khách hàng, CCCD, số điện thoại hoặc email.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_LayThongTinKhachHangChoDonDangKy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_LayThongTinKhachHangChoDonDangKy
    @KhachHangId VARCHAR(6)   = NULL,
    @CCCD        VARCHAR(20)  = NULL,
    @SDT         VARCHAR(20)  = NULL,
    @Email       VARCHAR(100) = NULL
AS
BEGIN
    

    SET @KhachHangId = NULLIF(TRIM(@KhachHangId)), '');
    SET @CCCD        = NULLIF(TRIM(@CCCD)), '');
    SET @SDT         = NULLIF(TRIM(@SDT)), '');
    SET @Email       = NULLIF(TRIM(@Email)), '');

    IF @KhachHangId IS NULL AND @CCCD IS NULL AND @SDT IS NULL AND @Email IS NULL
        THROW 50011, 'Vui lòng nhập mã khách hàng, CCCD, số điện thoại hoặc email để tra cứu.', 1;

    DECLARE @MaKhachHangTimThay VARCHAR(6);

    SELECT TOP (1)
        @MaKhachHangTimThay = kh.MaKhachHang
    FROM dbo.KhachHang AS kh
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = kh.MaKhachHang
    WHERE (@KhachHangId IS NOT NULL AND kh.MaKhachHang = @KhachHangId)
       OR (@CCCD IS NOT NULL AND kh.CCCD = @CCCD)
       OR (@SDT IS NOT NULL AND nd.SDT = @SDT)
       OR (@Email IS NOT NULL AND nd.Email = @Email)
    ORDER BY
        CASE
            WHEN @KhachHangId IS NOT NULL AND kh.MaKhachHang = @KhachHangId THEN 1
            WHEN @CCCD IS NOT NULL AND kh.CCCD = @CCCD THEN 2
            WHEN @SDT IS NOT NULL AND nd.SDT = @SDT THEN 3
            WHEN @Email IS NOT NULL AND nd.Email = @Email THEN 4
            ELSE 5
        END,
        kh.MaKhachHang;

    IF @MaKhachHangTimThay IS NULL
        RAISE EXCEPTION %;

    SELECT
        kh.MaKhachHang          AS maKhachHang,
        nd.HoTen                AS hoTenKhach,
        nd.HoTen                AS hoTen,
        nd.NgaySinh             AS ngaySinh,
        nd.GioiTinh             AS gioiTinh,
        nd.SDT                  AS sdtKhach,
        nd.SDT                  AS soDienThoai,
        nd.Email                AS emailKhach,
        nd.Email                AS email,
        kh.QuocTich             AS quocTich,
        kh.CCCD                 AS cccd,
        hoSo.MaDangKy           AS maDangKyGanNhat,
        hoSo.KhuVucMongMuon     AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = hoSo.MaDangKy) AS loaiPhongYeuCau,
        hoSo.MucGiaToiDa        AS mucGia,
        hoSo.SoNguoiDuKienO     AS soNguoiO,
        hoSo.ThoiGianDuKienVaoO AS ngayDuKienVaoO,
        hoSo.ThoiHanThue        AS thoiHanThue,
        hoSo.YeuCauKhac         AS ghiChu,
        hoSo.GhiChuSale         AS ghiChuSale,
        hoSo.TrangThai          AS trangThaiHoSoGanNhat
    FROM dbo.KhachHang AS kh
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = kh.MaKhachHang
    OUTER APPLY (
        SELECT TOP (1)
            pdk.MaDangKy,
            pdk.KhuVucMongMuon,
            (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
             FROM dbo.PDK_LoaiPhong pdklp
             JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
             WHERE pdklp.MaDangKy = pdk.MaDangKy) AS LoaiPhongYeuCau,
            pdk.MucGiaToiDa,
            pdk.SoNguoiDuKienO,
            pdk.ThoiGianDuKienVaoO,
            pdk.ThoiHanThue,
            pdk.YeuCauKhac,
            pdk.GhiChuSale,
            pdk.TrangThai
        FROM dbo.PhieuDangKy AS pdk
        WHERE pdk.MaKhachHang = kh.MaKhachHang
        ORDER BY pdk.NgayDangKy DESC, pdk.MaDangKy DESC
    ) AS hoSo
    WHERE kh.MaKhachHang = @MaKhachHangTimThay;
END;
-- =============================================
-- 2. SP_DanhSachHoSoDangKy
-- Nhân viên Sale xem danh sách hồ sơ đăng ký thuê.
-- Mặc định lấy hồ sơ đang chờ xử lý.
-- Hỗ trợ lọc theo trạng thái và chi nhánh.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_DanhSachHoSoDangKy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_DanhSachHoSoDangKy
    @TrangThai      VARCHAR(30)    = NULL,     -- NULL = lấy tất cả; hoặc lọc theo trạng thái cụ thể
    @MaChiNhanh     VARCHAR(6)      = NULL,     -- NULL = tất cả chi nhánh
    @NhanVienSaleId VARCHAR(6)      = NULL,     -- NULL = không lọc theo sale
    @KhachHangId    VARCHAR(6)      = NULL      -- NULL = không lọc theo khách hàng
AS
BEGIN
    

    SET @TrangThai      = NULLIF(TRIM(@TrangThai)), '');
    SET @MaChiNhanh     = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @NhanVienSaleId = NULLIF(TRIM(@NhanVienSaleId)), '');
    SET @KhachHangId    = NULLIF(TRIM(@KhachHangId)), '');

    IF @TrangThai IS NOT NULL
       AND @TrangThai NOT IN ('Chờ tiếp nhận', 'Đã tiếp nhận', 'Chờ xác nhận cọc', 'Xác nhận cọc', 'Từ chối')
        RAISE EXCEPTION %;

    IF @MaChiNhanh IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
        RAISE EXCEPTION %;

    IF @NhanVienSaleId IS NOT NULL
       AND NOT EXISTS (
           SELECT 1 FROM dbo.NhanVien WHERE MaNhanVien = @NhanVienSaleId AND ChucVu = 'Sale'
       )
        RAISE EXCEPTION %;

    IF @KhachHangId IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM dbo.KhachHang WHERE MaKhachHang = @KhachHangId)
        RAISE EXCEPTION %;

    SELECT
        pdk.MaDangKy            AS maDangKy,
        pdk.NgayDangKy          AS ngayDangKy,
        pdk.SoNguoiDuKienO      AS soNguoiO,
        pdk.SoNam               AS soNam,
        pdk.SoNu                AS soNu,
        pdk.KhuVucMongMuon      AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = pdk.MaDangKy) AS loaiPhongYeuCau,
        pdk.MucGiaToiDa         AS mucGia,
        pdk.ThoiGianDuKienVaoO  AS ngayDuKienVaoO,
        pdk.ThoiHanThue         AS thoiHanThue,
        pdk.YeuCauKhac          AS ghiChu,
        pdk.GhiChuSale          AS ghiChuSale,
        pdk.TrangThai           AS trangThai,
        pdk.MaKhachHang         AS maKhachHang,
        nd.HoTen                AS hoTenKhach,
        nd.NgaySinh             AS ngaySinhKhach,
        nd.SDT                  AS sdtKhach,
        nd.Email                AS emailKhach,
        nd.GioiTinh             AS gioiTinh,
        kh.QuocTich             AS quocTich,
        kh.CCCD                 AS cccd,
        pdk.MaNhanVienSale      AS maNhanVienSale,
        nvnd.HoTen              AS hoTenSale,
        nvSale.MaChiNhanh       AS maChiNhanhSale,
        cnSale.TenChiNhanh      AS tenChiNhanhSale,
        -- Lịch xem phòng gần nhất
        lich.STTLich            AS sttLichMoiNhat,
        lich.ThoiGianHen        AS thoiGianHenMoiNhat,
        lich.TrangThai          AS trangThaiLichMoiNhat
    FROM dbo.PhieuDangKy AS pdk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = pdk.MaKhachHang
    INNER JOIN dbo.KhachHang AS kh ON kh.MaKhachHang = pdk.MaKhachHang
    LEFT JOIN dbo.NguoiDung AS nvnd ON nvnd.MaNguoiDung = pdk.MaNhanVienSale
    LEFT JOIN dbo.NhanVien AS nvSale ON nvSale.MaNhanVien = pdk.MaNhanVienSale
    LEFT JOIN dbo.ChiNhanh AS cnSale ON cnSale.MaChiNhanh = nvSale.MaChiNhanh
    OUTER APPLY (
        SELECT TOP (1) lxp.STTLich, lxp.ThoiGianHen, lxp.TrangThai
        FROM dbo.LichXemPhong AS lxp
        WHERE lxp.MaDangKy = pdk.MaDangKy
        ORDER BY lxp.STTLich DESC
    ) AS lich
    WHERE (@TrangThai IS NULL OR pdk.TrangThai = @TrangThai)
      AND (@NhanVienSaleId IS NULL OR pdk.MaNhanVienSale = @NhanVienSaleId)
      AND (@KhachHangId IS NULL OR pdk.MaKhachHang = @KhachHangId)
      AND (@MaChiNhanh IS NULL
           OR nvSale.MaChiNhanh = @MaChiNhanh
           OR EXISTS (
               SELECT 1 FROM dbo.ChiNhanh cn
               WHERE cn.MaChiNhanh = @MaChiNhanh
                 AND cn.TenChiNhanh LIKE '%' + pdk.KhuVucMongMuon + '%'
           )
           OR (
               @MaChiNhanh = 'CN0001'
               AND (
                   pdk.KhuVucMongMuon LIKE '%Quận 1%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 3%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 4%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 5%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 10%'
               )
           )
           OR (
               @MaChiNhanh = 'CN0002'
               AND (
                   pdk.KhuVucMongMuon LIKE '%Bình Thạnh%'
                   OR pdk.KhuVucMongMuon LIKE '%Phú Nhuận%'
                   OR pdk.KhuVucMongMuon LIKE '%Gò Vấp%'
                   OR pdk.KhuVucMongMuon LIKE '%Tân Bình%'
               )
           )
           OR (
               @MaChiNhanh = 'CN0003'
               AND (
                   pdk.KhuVucMongMuon LIKE '%Thủ Đức%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 2%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 9%'
               )
           )
      )
    ORDER BY pdk.NgayDangKy DESC, pdk.MaDangKy DESC;
END;
-- =============================================
-- 3. SP_DanhSachPhongGiuongKhaDung
-- Lấy danh sách phòng và giường còn trống để Sale gợi ý cho khách.
-- Hỗ trợ lọc theo loại, giới tính, chi nhánh, khu vực, loại phòng, mức giá, số người hoặc hồ sơ đăng ký.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_DanhSachPhongGiuongKhaDung AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_DanhSachPhongGiuongKhaDung
    @Loai           VARCHAR(50)    = NULL,     -- 'Nguyên căn' hoặc 'Ghép' hoặc NULL (lấy tất cả)
    @GioiTinh       VARCHAR(5)     = NULL,     -- 'Nam' hoặc 'Nữ' hoặc NULL
    @MaChiNhanh     VARCHAR(6)      = NULL,     -- Lọc theo chi nhánh
    @KhuVuc         VARCHAR(100)   = NULL,     -- Lọc theo địa chỉ/tên chi nhánh
    @LoaiPhong      VARCHAR(50)    = NULL,     -- Lọc theo tên loại phòng
    @MucGiaTu       DECIMAL(15,2)   = NULL,     -- Lọc theo ngân sách tối thiểu
    @MucGiaToiDa    DECIMAL(15,2)   = NULL,     -- Lọc theo ngân sách tối đa
    @SoNguoiO       INT             = NULL,     -- Lọc phòng đủ sức chứa/chỗ trống
    @HoSoId         VARCHAR(6)      = NULL      -- Tự lấy tiêu chí từ phiếu đăng ký
AS
BEGIN
    

    SET @Loai       = NULLIF(TRIM(@Loai)), '');
    SET @GioiTinh   = NULLIF(TRIM(@GioiTinh)), '');
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @KhuVuc     = NULLIF(TRIM(@KhuVuc)), '');
    SET @LoaiPhong  = NULLIF(TRIM(@LoaiPhong)), '');
    SET @HoSoId     = NULLIF(TRIM(@HoSoId)), '');

    DECLARE @SoNam INT = 0;
    DECLARE @SoNu INT = 0;
    DECLARE @HinhThucThue VARCHAR(50) = NULL;

    IF @HoSoId IS NOT NULL
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.PhieuDangKy WHERE MaDangKy = @HoSoId)
            RAISE EXCEPTION %;

        SELECT
            @SoNam       = COALESCE(SoNam, 0),
            @SoNu        = COALESCE(SoNu, 0),
            @KhuVuc      = COALESCE(@KhuVuc, KhuVucMongMuon),
            @MucGiaToiDa = COALESCE(@MucGiaToiDa, MucGiaToiDa),
            @SoNguoiO    = COALESCE(@SoNguoiO, SoNguoiDuKienO)
        FROM dbo.PhieuDangKy
        WHERE MaDangKy = @HoSoId;

        
        END

        IF @Loai IS NULL AND @HinhThucThue IS NOT NULL
            SET @Loai = @HinhThucThue;

        IF @GioiTinh IS NULL
        BEGIN
            IF @SoNam > 0 AND @SoNu = 0 SET @GioiTinh = 'Nam';
            ELSE IF @SoNu > 0 AND @SoNam = 0 SET @GioiTinh = 'Nữ';
        END
    END;

    IF @Loai IN ('Nguyên phòng', 'Nguyên căn')
        SET @Loai = 'Nguyên căn';
    IF @Loai IN ('Ghép giường', 'Ghép')
        SET @Loai = 'Ghép';

    IF @Loai IS NOT NULL AND @Loai NOT IN ('Nguyên căn', 'Ghép')
        RAISE EXCEPTION %;

    IF @GioiTinh IS NOT NULL AND @GioiTinh NOT IN ('Nam', 'Nữ')
        RAISE EXCEPTION %;

    IF @MucGiaTu IS NOT NULL AND @MucGiaTu < 0
        RAISE EXCEPTION %;

    IF @MucGiaToiDa IS NOT NULL AND @MucGiaToiDa < 0
        RAISE EXCEPTION %;

    IF @SoNguoiO IS NOT NULL AND @SoNguoiO < 1
        RAISE EXCEPTION %;

    IF @SoNguoiO IS NULL AND (@SoNam + @SoNu) > 0
        SET @SoNguoiO = @SoNam + @SoNu;

    DECLARE @SoNguoiCanXep INT = COALESCE(NULLIF(@SoNguoiO, 0), CASE WHEN (@SoNam + @SoNu) > 0 THEN @SoNam + @SoNu ELSE 1 END);
    DECLARE @LaNhomHonHop BOOLEAN = CASE WHEN @SoNam > 0 AND @SoNu > 0 THEN 1 ELSE 0 END;

    IF @MaChiNhanh IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
        RAISE EXCEPTION %;

    CREATE TABLE #ChiNhanhPhuHop (MaChiNhanh VARCHAR(6) PRIMARY KEY);

    IF @MaChiNhanh IS NOT NULL
    BEGIN
        INSERT INTO #ChiNhanhPhuHop (MaChiNhanh)
        SELECT MaChiNhanh
        FROM dbo.ChiNhanh
        WHERE MaChiNhanh = @MaChiNhanh
          AND TrangThai = 'Hoạt động';
    END
    ELSE IF @KhuVuc IS NULL
    BEGIN
        INSERT INTO #ChiNhanhPhuHop (MaChiNhanh)
        SELECT MaChiNhanh
        FROM dbo.ChiNhanh
        WHERE TrangThai = 'Hoạt động';
    END
    ELSE
    BEGIN
        INSERT INTO #ChiNhanhPhuHop (MaChiNhanh)
        SELECT MaChiNhanh
        FROM dbo.ChiNhanh
        WHERE TrangThai = 'Hoạt động'
          AND (DiaChi LIKE '%' + @KhuVuc + '%' OR TenChiNhanh LIKE '%' + @KhuVuc + '%');

        INSERT INTO #ChiNhanhPhuHop (MaChiNhanh)
        SELECT cn.MaChiNhanh
        FROM dbo.ChiNhanh AS cn
        WHERE cn.TrangThai = 'Hoạt động'
          AND (
              (
                  cn.MaChiNhanh = 'CN0001'
                  AND (
                      @KhuVuc LIKE '%Quận 1%'
                      OR @KhuVuc LIKE '%Quận 3%'
                      OR @KhuVuc LIKE '%Quận 4%'
                      OR @KhuVuc LIKE '%Quận 5%'
                      OR @KhuVuc LIKE '%Quận 10%'
                  )
              )
              OR (
                  cn.MaChiNhanh = 'CN0002'
                  AND (
                      @KhuVuc LIKE '%Bình Thạnh%'
                      OR @KhuVuc LIKE '%Phú Nhuận%'
                      OR @KhuVuc LIKE '%Gò Vấp%'
                      OR @KhuVuc LIKE '%Tân Bình%'
                  )
              )
              OR (
                  cn.MaChiNhanh = 'CN0003'
                  AND (
                      @KhuVuc LIKE '%Thủ Đức%'
                      OR @KhuVuc LIKE '%Quận 2%'
                      OR @KhuVuc LIKE '%Quận 9%'
                  )
              )
          )
          AND NOT EXISTS (
              SELECT 1
              FROM #ChiNhanhPhuHop AS existed
              WHERE existed.MaChiNhanh = cn.MaChiNhanh
          );
    END;

    DECLARE @KhongCoChiNhanhPhuHop BOOLEAN =
        CASE WHEN @MaChiNhanh IS NULL AND @KhuVuc IS NOT NULL AND NOT EXISTS (SELECT 1 FROM #ChiNhanhPhuHop)
             THEN 1 ELSE 0 END;

    CREATE TABLE #LoaiPhongYeuCau (MaLoaiPhong VARCHAR(6) PRIMARY KEY);

    IF @LoaiPhong IS NOT NULL
    BEGIN
        INSERT INTO #LoaiPhongYeuCau (MaLoaiPhong)
        SELECT MaLoaiPhong
        FROM dbo.LoaiPhong
        WHERE TenLoaiPhong = @LoaiPhong;
    END
    ELSE IF @HoSoId IS NOT NULL
       AND OBJECT_ID('dbo.PDK_LoaiPhong', 'U') IS NOT NULL
       AND EXISTS (SELECT 1 FROM dbo.PDK_LoaiPhong WHERE MaDangKy = @HoSoId)
    BEGIN
        INSERT INTO #LoaiPhongYeuCau (MaLoaiPhong)
        SELECT DISTINCT MaLoaiPhong
        FROM dbo.PDK_LoaiPhong
        WHERE MaDangKy = @HoSoId;
    END

    IF NOT EXISTS (SELECT 1 FROM #LoaiPhongYeuCau)
    BEGIN
        INSERT INTO #LoaiPhongYeuCau (MaLoaiPhong)
        SELECT MaLoaiPhong
        FROM dbo.LoaiPhong;
    END;

    ;WITH BedCounts AS (
        SELECT
            g.MaPhong,
            COUNT(CASE WHEN g.TinhTrang = 'Trống' THEN 1 END) AS soGiuongTrong
        FROM dbo.Giuong AS g
        GROUP BY g.MaPhong
    )
    SELECT
        p.MaPhong,
        p.TenPhong,
        p.GioiTinhChoPhep,
        p.TinhTrang,
        p.MaChiNhanh,
        p.MaLoaiPhong,
        lp.TenLoaiPhong,
        lp.MoTa,
        lp.SucChuaToiDa,
        lp.GiaThueTheoGiuong,
        lp.GiaThueNguyenPhong,
        cn.TenChiNhanh,
        cn.DiaChi,
        COALESCE(bc.soGiuongTrong, 0) AS soGiuongTrong,
        (SELECT TOP 1 UrlImg FROM dbo.HinhAnhPhong hap WHERE hap.MaPhong = p.MaPhong ORDER BY hap.STTAnh) AS urlImg
    INTO #BaseRooms
    FROM dbo.Phong AS p
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
    INNER JOIN #ChiNhanhPhuHop AS cnp ON cnp.MaChiNhanh = p.MaChiNhanh
    INNER JOIN #LoaiPhongYeuCau AS lpyc ON lpyc.MaLoaiPhong = p.MaLoaiPhong
    LEFT JOIN BedCounts AS bc ON bc.MaPhong = p.MaPhong;

    CREATE TABLE #KetQua (
        phuongAn INT NOT NULL,
        maPhong VARCHAR(4) NULL,
        tenPhong VARCHAR(100) NULL,
        loaiThue VARCHAR(30) NULL,
        maLoaiPhong VARCHAR(6) NULL,
        loaiPhong VARCHAR(100) NULL,
        moTa TEXT NULL,
        giaThue DECIMAL(15,2) NULL,
        sucChua INT NULL,
        gioiTinhChoPhep VARCHAR(20) NULL,
        tinhTrang VARCHAR(20) NULL,
        maChiNhanh VARCHAR(6) NULL,
        tenChiNhanh VARCHAR(100) NULL,
        diaChi VARCHAR(255) NULL,
        urlImg VARCHAR(500) NULL,
        maGiuong VARCHAR(3) NULL,
        soGiuong INT NULL,
        soGiuongTrong INT NULL,
        soGiuongDuKienXep INT NULL,
        tongNamDuocXep INT NULL,
        tongNuDuocXep INT NULL,
        khongCoChiNhanhPhuHop BOOLEAN NOT NULL
    );

    CREATE TABLE #PhongUngVien (
        MaPhong VARCHAR(4) NOT NULL PRIMARY KEY,
        MaLoaiPhong VARCHAR(6) NOT NULL,
        GiaMoiNguoi DECIMAL(15,2) NOT NULL,
        LaTrongNguyenPhong BOOLEAN NOT NULL,
        SoGiuongNam INT NOT NULL,
        SoGiuongNu INT NOT NULL,
        SoGiuongKhongPhanBiet INT NOT NULL
    );

    INSERT INTO #PhongUngVien (
        MaPhong, MaLoaiPhong, GiaMoiNguoi, LaTrongNguyenPhong,
        SoGiuongNam, SoGiuongNu, SoGiuongKhongPhanBiet
    )
    SELECT
        br.MaPhong,
        br.MaLoaiPhong,
        COALESCE(br.GiaThueTheoGiuong, br.GiaThueNguyenPhong / NULLIF(br.SucChuaToiDa, 0)) AS GiaMoiNguoi,
        CASE
            WHEN br.TinhTrang = 'Trống'
             AND br.soGiuongTrong >= br.SucChuaToiDa
             AND br.GioiTinhChoPhep IN ('Không phân biệt', 'Khác', 'Hỗn hợp')
                THEN 1 ELSE 0
        END AS LaTrongNguyenPhong,
        CASE WHEN br.GioiTinhChoPhep = 'Nam' THEN br.soGiuongTrong ELSE 0 END AS SoGiuongNam,
        CASE WHEN br.GioiTinhChoPhep = 'Nữ' THEN br.soGiuongTrong ELSE 0 END AS SoGiuongNu,
        CASE WHEN br.GioiTinhChoPhep IN ('Không phân biệt', 'Khác', 'Hỗn hợp') THEN br.soGiuongTrong ELSE 0 END AS SoGiuongKhongPhanBiet
    FROM #BaseRooms AS br
    WHERE br.TinhTrang IN ('Trống', 'Còn chỗ')
      AND br.soGiuongTrong > 0
      AND COALESCE(br.GiaThueTheoGiuong, br.GiaThueNguyenPhong / NULLIF(br.SucChuaToiDa, 0)) IS NOT NULL
      AND (@MucGiaTu IS NULL OR COALESCE(br.GiaThueTheoGiuong, br.GiaThueNguyenPhong / NULLIF(br.SucChuaToiDa, 0)) >= @MucGiaTu)
      AND (@MucGiaToiDa IS NULL OR COALESCE(br.GiaThueTheoGiuong, br.GiaThueNguyenPhong / NULLIF(br.SucChuaToiDa, 0)) <= @MucGiaToiDa)
      AND (
          @Loai IS NULL
          OR @Loai = 'Ghép'
          OR (
              @Loai = 'Nguyên căn'
              AND br.TinhTrang = 'Trống'
              AND br.soGiuongTrong >= br.SucChuaToiDa
          )
      );

    CREATE TABLE #LoaiPhongHopLe (
        MaLoaiPhong VARCHAR(6) NOT NULL PRIMARY KEY
    );

    INSERT INTO #LoaiPhongHopLe (MaLoaiPhong)
    SELECT puv.MaLoaiPhong
    FROM #PhongUngVien AS puv
    GROUP BY puv.MaLoaiPhong
    HAVING
        (
            @LaNhomHonHop = 0
            AND MAX(CASE
                WHEN @GioiTinh = 'Nam'
                     AND (puv.SoGiuongNam + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep THEN 1
                WHEN @GioiTinh = 'Nữ'
                     AND (puv.SoGiuongNu + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep THEN 1
                WHEN @GioiTinh IS NULL
                     AND (puv.SoGiuongNam + puv.SoGiuongNu + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep THEN 1
                ELSE 0
            END) = 1
        )
        OR
        (
            @LaNhomHonHop = 1
            AND MAX(CASE WHEN puv.LaTrongNguyenPhong = 1 AND puv.SoGiuongKhongPhanBiet >= @SoNguoiCanXep THEN 1 ELSE 0 END) = 1
        );

    ;WITH PhongTraVe AS (
        SELECT
            ROW_NUMBER() OVER (
                PARTITION BY br.MaLoaiPhong
                ORDER BY
                    CASE WHEN puv.LaTrongNguyenPhong = 1 THEN 0 ELSE 1 END,
                    puv.GiaMoiNguoi,
                    br.TenPhong,
                    br.MaPhong
            ) AS rn,
            br.*,
            puv.GiaMoiNguoi,
            puv.LaTrongNguyenPhong
        FROM #BaseRooms AS br
        INNER JOIN #PhongUngVien AS puv ON puv.MaPhong = br.MaPhong
        INNER JOIN #LoaiPhongHopLe AS lphl ON lphl.MaLoaiPhong = br.MaLoaiPhong
        WHERE
            (
                @LaNhomHonHop = 0
                AND (
                    (@GioiTinh = 'Nam' AND (puv.SoGiuongNam + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep)
                    OR (@GioiTinh = 'Nữ' AND (puv.SoGiuongNu + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep)
                    OR (@GioiTinh IS NULL AND (puv.SoGiuongNam + puv.SoGiuongNu + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep)
                )
            )
            OR
            (
                @LaNhomHonHop = 1
                AND puv.LaTrongNguyenPhong = 1
                AND puv.SoGiuongKhongPhanBiet >= @SoNguoiCanXep
            )
    )
    INSERT INTO #KetQua (
        phuongAn, maPhong, tenPhong, loaiThue, maLoaiPhong, loaiPhong, moTa,
        giaThue, sucChua, gioiTinhChoPhep, tinhTrang, maChiNhanh, tenChiNhanh,
        diaChi, urlImg, maGiuong, soGiuong, soGiuongTrong, soGiuongDuKienXep,
        tongNamDuocXep, tongNuDuocXep, khongCoChiNhanhPhuHop
    )
    SELECT
        rn,
        MaPhong,
        TenPhong,
        CASE WHEN LaTrongNguyenPhong = 1 THEN 'Nguyên căn' ELSE 'Ghép' END,
        MaLoaiPhong,
        TenLoaiPhong,
        MoTa,
        GiaMoiNguoi,
        SucChuaToiDa,
        GioiTinhChoPhep,
        TinhTrang,
        MaChiNhanh,
        TenChiNhanh,
        DiaChi,
        urlImg,
        NULL,
        NULL,
        soGiuongTrong,
        CASE WHEN soGiuongTrong >= @SoNguoiCanXep THEN @SoNguoiCanXep ELSE soGiuongTrong END,
        COALESCE(@SoNam, 0),
        COALESCE(@SoNu, 0),
        @KhongCoChiNhanhPhuHop
    FROM PhongTraVe;

    SELECT *
    FROM #KetQua
    ORDER BY loaiThue, giaThue, loaiPhong, tenPhong, maGiuong;
END;
-- =============================================
-- 4. SP_KiemTraDieuKienThue
-- Kiểm tra hồ sơ đăng ký có đủ điều kiện để chuyển sang bước đặt cọc không.
-- Trả về: hopLe (BOOLEAN), lyDo (VARCHAR)
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_KiemTraDieuKienThue AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_KiemTraDieuKienThue
    @HoSoId VARCHAR(30)
AS
BEGIN
    

    SET @HoSoId = TRIM(@HoSoId));

    IF NOT EXISTS (SELECT 1 FROM dbo.PhieuDangKy WHERE MaDangKy = @HoSoId)
        RAISE EXCEPTION %;

    UPDATE dbo.LichXemPhong
    SET TrangThai = 'Đã xem'
    WHERE MaDangKy = @HoSoId
      AND TrangThai IN ('Chờ xem', 'Yêu cầu đổi lịch', 'Yêu cầu hủy')
      AND ThoiGianHen <= CURRENT_TIMESTAMP;

    DECLARE @TrangThai          VARCHAR(30);
    DECLARE @MaKhachHang        VARCHAR(6);
    DECLARE @NgayDuKienVaoO     DATE;
    DECLARE @SoLichXemDaXem     INT;

    SELECT
        @TrangThai          = pdk.TrangThai,
        @MaKhachHang        = pdk.MaKhachHang,
        @NgayDuKienVaoO     = pdk.ThoiGianDuKienVaoO
    FROM dbo.PhieuDangKy AS pdk
    WHERE pdk.MaDangKy = @HoSoId;

    -- Đếm số lần đã xem phòng thành công
    SELECT @SoLichXemDaXem = COUNT(*)
    FROM dbo.LichXemPhong
    WHERE MaDangKy = @HoSoId AND TrangThai = 'Đã xem';

    SELECT
        @HoSoId                             AS maDangKy,
        @TrangThai                          AS trangThai,
        @NgayDuKienVaoO                     AS ngayDuKienVaoO,
        @SoLichXemDaXem                     AS soLichXemDaXem,
        -- Hồ sơ hợp lệ khi: đang ở trạng thái Chờ tiếp nhận + đã xem phòng ít nhất 1 lần
        CAST(CASE
            WHEN @TrangThai = 'Chờ tiếp nhận' AND @SoLichXemDaXem >= 1 THEN 1
            ELSE 0
        END AS BOOLEAN)                         AS hopLe,
        CASE
            WHEN @TrangThai = 'Chờ xác nhận cọc' THEN 'Hồ sơ đã được chấp nhận và đang chờ đặt cọc.'
            WHEN @TrangThai = 'Chấp nhận'         THEN 'Hồ sơ đã được chấp nhận.'
            WHEN @TrangThai = 'Từ chối'           THEN 'Hồ sơ đã bị từ chối.'
            WHEN @SoLichXemDaXem < 1               THEN 'Khách hàng chưa xem phòng lần nào. Cần sắp xếp lịch xem phòng trước.'
            ELSE 'Hồ sơ đủ điều kiện tiến hành đặt cọc.'
        END                                 AS lyDo;
END;
-- =============================================
-- 5. SP_CapNhatKetQuaXuLyHoSo
-- Nhân viên Sale cập nhật kết quả xử lý hồ sơ đăng ký.
-- TrangThai hợp lệ: 'Chấp nhận', 'Từ chối', 'Chờ xác nhận cọc'
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_CapNhatKetQuaXuLyHoSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_CapNhatKetQuaXuLyHoSo
    @HoSoId         VARCHAR(30),
    @TrangThai      VARCHAR(50),
    @GhiChuXuLy     TEXT   = NULL,
    @NhanVienSaleId VARCHAR(20)    = NULL
AS
BEGIN
    
    

    SET @HoSoId         = TRIM(@HoSoId));
    SET @TrangThai      = TRIM(@TrangThai));
    SET @NhanVienSaleId = NULLIF(TRIM(@NhanVienSaleId)), '');
    SET @GhiChuXuLy     = NULLIF(TRIM(@GhiChuXuLy)), '');

    -- Kiểm tra hồ sơ tồn tại
    IF NOT EXISTS (SELECT 1 FROM dbo.PhieuDangKy WHERE MaDangKy = @HoSoId)
        RAISE EXCEPTION %;

    UPDATE dbo.LichXemPhong
    SET TrangThai = 'Đã xem'
    WHERE MaDangKy = @HoSoId
      AND TrangThai IN ('Chờ xem', 'Yêu cầu đổi lịch', 'Yêu cầu hủy')
      AND ThoiGianHen <= CURRENT_TIMESTAMP;

    -- Kiểm tra trạng thái mới hợp lệ
    IF @TrangThai NOT IN ('Chấp nhận', 'Từ chối', 'Chờ xác nhận cọc', 'Đã tiếp nhận')
        RAISE EXCEPTION %;

    -- Kiểm tra hồ sơ có đang ở trạng thái có thể cập nhật không
    DECLARE @TrangThaiHienTai VARCHAR(30);
    SELECT @TrangThaiHienTai = TrangThai FROM dbo.PhieuDangKy WHERE MaDangKy = @HoSoId;

    IF @TrangThaiHienTai NOT IN ('Chờ tiếp nhận', 'Chờ xác nhận cọc')
        RAISE EXCEPTION %;

    IF @NhanVienSaleId IS NOT NULL
       AND EXISTS (
           SELECT 1
           FROM dbo.PhieuDangKy
           WHERE MaDangKy = @HoSoId
             AND MaNhanVienSale IS NOT NULL
             AND MaNhanVienSale <> @NhanVienSaleId
       )
        RAISE EXCEPTION %;

    -- Kiểm tra nhân viên Sale tồn tại (nếu có truyền vào)
    IF @NhanVienSaleId IS NOT NULL
       AND NOT EXISTS (
           SELECT 1 FROM dbo.NhanVien WHERE MaNhanVien = @NhanVienSaleId AND ChucVu = 'Sale'
       )
        RAISE EXCEPTION %;

    -- Nếu chấp nhận hồ sơ hoặc chuyển sang bước cọc: khách phải đã xem phòng ít nhất 1 lần
    IF @TrangThai IN ('Chờ xác nhận cọc', 'Chấp nhận')
       AND NOT EXISTS (
           SELECT 1 FROM dbo.LichXemPhong
           WHERE MaDangKy = @HoSoId AND TrangThai = 'Đã xem'
       )
        RAISE EXCEPTION %;

    BEGIN TRY
        BEGIN TRANSACTION;
        IF @TrangThai = 'Chờ xác nhận cọc'
        BEGIN
            UPDATE dbo.PhieuDangKy
            SET TrangThai = @TrangThai,
                MaNhanVienSale = COALESCE(@NhanVienSaleId, MaNhanVienSale)
            WHERE MaDangKy = @HoSoId;

            -- Khi chuyển sang chờ đặt cọc, không cập nhật GhiChuSale
        END
        ELSE
        BEGIN
            UPDATE dbo.PhieuDangKy
            SET TrangThai = @TrangThai,
                GhiChuSale = COALESCE(@GhiChuXuLy, GhiChuSale),
                MaNhanVienSale = COALESCE(@NhanVienSaleId, MaNhanVienSale)
            WHERE MaDangKy = @HoSoId;
        END;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    -- Trả về hồ sơ sau khi cập nhật
    SELECT
        pdk.MaDangKy            AS maDangKy,
        pdk.NgayDangKy          AS ngayDangKy,
        pdk.SoNguoiDuKienO      AS soNguoiO,
        pdk.SoNam               AS soNam,
        pdk.SoNu                AS soNu,
        pdk.KhuVucMongMuon      AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = pdk.MaDangKy) AS loaiPhongYeuCau,
        pdk.MucGiaToiDa         AS mucGia,
        pdk.ThoiGianDuKienVaoO  AS ngayDuKienVaoO,
        pdk.ThoiHanThue         AS thoiHanThue,
        pdk.YeuCauKhac          AS ghiChu,
        pdk.TrangThai           AS trangThai,
        pdk.MaKhachHang         AS maKhachHang,
        nd.HoTen                AS hoTenKhach,
        nd.SDT                  AS sdtKhach,
        nd.Email                AS emailKhach,
        pdk.MaNhanVienSale      AS maNhanVienSale,
        nvnd.HoTen              AS hoTenSale
    FROM dbo.PhieuDangKy AS pdk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = pdk.MaKhachHang
    LEFT JOIN dbo.NguoiDung AS nvnd ON nvnd.MaNguoiDung = pdk.MaNhanVienSale
    WHERE pdk.MaDangKy = @HoSoId;
END;
-- =============================================
-- 9. SP_TraCuuPhong
-- Tra cứu toàn bộ danh sách phòng để hiển thị trên màn hình Tra Cứu Phòng của Sale
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_TraCuuPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_TraCuuPhong
    @KhuVuc         VARCHAR(100) = NULL,
    @LoaiPhong      VARCHAR(50)  = NULL,
    @HinhThucThue   VARCHAR(50)  = NULL,
    @MucGiaToiDa    DECIMAL(15,2) = NULL
AS
BEGIN
    

    SET @KhuVuc = NULLIF(TRIM(@KhuVuc)), '');
    SET @LoaiPhong = NULLIF(TRIM(@LoaiPhong)), '');
    SET @HinhThucThue = NULLIF(TRIM(@HinhThucThue)), '');

    IF @KhuVuc = 'Tất cả khu vực' SET @KhuVuc = NULL;
    IF @LoaiPhong = 'Tất cả loại phòng' SET @LoaiPhong = NULL;
    IF @HinhThucThue = 'Tất cả hình thức' SET @HinhThucThue = NULL;

    SELECT
        p.MaPhong AS id,
        p.TenPhong AS name,
        cn.TenChiNhanh AS subName,
        cn.DiaChi AS area,
        CASE
            WHEN p.GioiTinhChoPhep = 'Nam' THEN 'Ghép nam'
            WHEN p.GioiTinhChoPhep = 'Nữ' THEN 'Ghép nữ'
            ELSE 'Nguyên căn'
        END AS type,
        COALESCE(lp.GiaThueNguyenPhong, lp.GiaThueTheoGiuong) AS price,
        (
            SELECT COUNT(*)
            FROM dbo.Giuong g
            WHERE g.MaPhong = p.MaPhong AND g.TinhTrang = 'Trống'
        ) AS emptyBeds,
        lp.SucChuaToiDa AS capacity,
        p.TinhTrang AS status
    FROM dbo.Phong p
    INNER JOIN dbo.LoaiPhong lp ON p.MaLoaiPhong = lp.MaLoaiPhong
    INNER JOIN dbo.ChiNhanh cn ON p.MaChiNhanh = cn.MaChiNhanh
    WHERE cn.TrangThai = 'Hoạt động'
      AND (@KhuVuc IS NULL OR cn.DiaChi LIKE '%' + @KhuVuc + '%' OR cn.TenChiNhanh LIKE '%' + @KhuVuc + '%')
      AND (@LoaiPhong IS NULL OR lp.TenLoaiPhong = @LoaiPhong)
      AND (@HinhThucThue IS NULL OR
           (@HinhThucThue = 'Nguyên căn' AND (p.GioiTinhChoPhep = 'Không phân biệt' OR p.GioiTinhChoPhep IS NULL)) OR
           (@HinhThucThue = 'Ghép nam' AND p.GioiTinhChoPhep = 'Nam') OR
           (@HinhThucThue = 'Ghép nữ' AND p.GioiTinhChoPhep = 'Nữ')
          )
      AND (@MucGiaToiDa IS NULL OR COALESCE(lp.GiaThueNguyenPhong, lp.GiaThueTheoGiuong) <= @MucGiaToiDa)
    ORDER BY p.TenPhong;
END; THEN (SUBSTRING(MaDangKy, 3, 4)::INT ELSE NULL END)), 0) + 1
        FROM dbo.PhieuDangKy 
        WHERE MaDangKy LIKE 'DK[0-9][0-9][0-9][0-9]';

        IF @SoDangKy > 9999
            RAISE EXCEPTION %;

        SET @MaDangKy = CONCAT('DK', RIGHT(CONCAT('0000', @SoDangKy), 4));

        DECLARE @SoNam INT = COALESCE(@SoNamInput, 0);
        DECLARE @SoNu INT = COALESCE(@SoNuInput, 0);
        IF @GioiTinh = 'Nam' BEGIN
            SET @SoNam = @SoNguoiO;
            SET @SoNu = 0;
        END
        ELSE IF @GioiTinh = 'Nữ' BEGIN
            SET @SoNu = @SoNguoiO;
            SET @SoNam = 0;
        END
        ELSE IF @GioiTinh = 'Khác' OR @GioiTinh = 'Hỗn hợp' BEGIN
            IF @SoNam = 0 AND @SoNu = 0 SET @SoNam = @SoNguoiO;
        END
        ELSE BEGIN
            SET @SoNam = @SoNguoiO;
            SET @SoNu = 0;
        END

        INSERT INTO dbo.PhieuDangKy (
            MaDangKy, NgayDangKy, SoNguoiDuKienO, SoNam, SoNu,
            KhuVucMongMuon, MucGiaToiDa, ThoiGianDuKienVaoO,
            ThoiHanThue, YeuCauKhac, TrangThai, MaKhachHang, MaNhanVienSale
        )
        VALUES (
            @MaDangKy, CAST(CURRENT_TIMESTAMP AS DATE), @SoNguoiO, @SoNam, @SoNu,
            @KhuVucMongMuon, @MucGiaToiDa, @NgayDuKienVaoO,
            @ThoiHanThue, @GhiChu, 'Chờ tiếp nhận', @MaKhachHang, NULL
        );

        IF @LoaiPhongYeuCau IS NOT NULL
        BEGIN
            INSERT INTO dbo.PDK_LoaiPhong (MaDangKy, MaLoaiPhong)
            SELECT @MaDangKy, lp.MaLoaiPhong
            FROM dbo.LoaiPhong lp
            WHERE lp.TenLoaiPhong IN (SELECT TRIM(value)) FROM STRING_SPLIT(@LoaiPhongYeuCau, ','));
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        pdk.MaDangKy            AS maDangKy,
        pdk.NgayDangKy          AS ngayDangKy,
        pdk.SoNguoiDuKienO      AS soNguoiO,
        pdk.SoNam               AS soNam,
        pdk.SoNu                AS soNu,
        pdk.KhuVucMongMuon      AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = pdk.MaDangKy) AS loaiPhongYeuCau,
        pdk.MucGiaToiDa         AS mucGia,
        pdk.ThoiGianDuKienVaoO  AS ngayDuKienVaoO,
        pdk.ThoiHanThue         AS thoiHanThue,
        pdk.YeuCauKhac          AS ghiChu,
        pdk.GhiChuSale          AS ghiChuSale,
        pdk.TrangThai           AS trangThai,
        pdk.MaKhachHang         AS maKhachHang,
        nd.HoTen                AS hoTenKhach,
        nd.SDT                  AS sdtKhach,
        nd.Email                AS emailKhach,
        kh.QuocTich             AS quocTich,
        kh.CCCD                 AS cccd,
        pdk.MaNhanVienSale      AS maNhanVienSale,
        nvnd.HoTen              AS hoTenSale
    FROM dbo.PhieuDangKy AS pdk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = pdk.MaKhachHang
    INNER JOIN dbo.KhachHang AS kh ON kh.MaKhachHang = pdk.MaKhachHang
    LEFT JOIN dbo.NguoiDung AS nvnd ON nvnd.MaNguoiDung = pdk.MaNhanVienSale
    WHERE pdk.MaDangKy = @MaDangKy;
END;
-- =============================================
-- 8. SP_LayThongTinKhachHangChoDonDangKy
-- Lấy thông tin khách hàng và hồ sơ gần nhất để hệ thống tự động điền đơn đăng ký.
-- Có thể tìm bằng mã khách hàng, CCCD, số điện thoại hoặc email.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_LayThongTinKhachHangChoDonDangKy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_LayThongTinKhachHangChoDonDangKy
    @KhachHangId VARCHAR(6)   = NULL,
    @CCCD        VARCHAR(20)  = NULL,
    @SDT         VARCHAR(20)  = NULL,
    @Email       VARCHAR(100) = NULL
AS
BEGIN
    

    SET @KhachHangId = NULLIF(TRIM(@KhachHangId)), '');
    SET @CCCD        = NULLIF(TRIM(@CCCD)), '');
    SET @SDT         = NULLIF(TRIM(@SDT)), '');
    SET @Email       = NULLIF(TRIM(@Email)), '');

    IF @KhachHangId IS NULL AND @CCCD IS NULL AND @SDT IS NULL AND @Email IS NULL
        THROW 50011, 'Vui lòng nhập mã khách hàng, CCCD, số điện thoại hoặc email để tra cứu.', 1;

    DECLARE @MaKhachHangTimThay VARCHAR(6);

    SELECT TOP (1)
        @MaKhachHangTimThay = kh.MaKhachHang
    FROM dbo.KhachHang AS kh
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = kh.MaKhachHang
    WHERE (@KhachHangId IS NOT NULL AND kh.MaKhachHang = @KhachHangId)
       OR (@CCCD IS NOT NULL AND kh.CCCD = @CCCD)
       OR (@SDT IS NOT NULL AND nd.SDT = @SDT)
       OR (@Email IS NOT NULL AND nd.Email = @Email)
    ORDER BY
        CASE
            WHEN @KhachHangId IS NOT NULL AND kh.MaKhachHang = @KhachHangId THEN 1
            WHEN @CCCD IS NOT NULL AND kh.CCCD = @CCCD THEN 2
            WHEN @SDT IS NOT NULL AND nd.SDT = @SDT THEN 3
            WHEN @Email IS NOT NULL AND nd.Email = @Email THEN 4
            ELSE 5
        END,
        kh.MaKhachHang;

    IF @MaKhachHangTimThay IS NULL
        RAISE EXCEPTION %;

    SELECT
        kh.MaKhachHang          AS maKhachHang,
        nd.HoTen                AS hoTenKhach,
        nd.HoTen                AS hoTen,
        nd.NgaySinh             AS ngaySinh,
        nd.GioiTinh             AS gioiTinh,
        nd.SDT                  AS sdtKhach,
        nd.SDT                  AS soDienThoai,
        nd.Email                AS emailKhach,
        nd.Email                AS email,
        kh.QuocTich             AS quocTich,
        kh.CCCD                 AS cccd,
        hoSo.MaDangKy           AS maDangKyGanNhat,
        hoSo.KhuVucMongMuon     AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = hoSo.MaDangKy) AS loaiPhongYeuCau,
        hoSo.MucGiaToiDa        AS mucGia,
        hoSo.SoNguoiDuKienO     AS soNguoiO,
        hoSo.ThoiGianDuKienVaoO AS ngayDuKienVaoO,
        hoSo.ThoiHanThue        AS thoiHanThue,
        hoSo.YeuCauKhac         AS ghiChu,
        hoSo.GhiChuSale         AS ghiChuSale,
        hoSo.TrangThai          AS trangThaiHoSoGanNhat
    FROM dbo.KhachHang AS kh
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = kh.MaKhachHang
    OUTER APPLY (
        SELECT TOP (1)
            pdk.MaDangKy,
            pdk.KhuVucMongMuon,
            (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
             FROM dbo.PDK_LoaiPhong pdklp
             JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
             WHERE pdklp.MaDangKy = pdk.MaDangKy) AS LoaiPhongYeuCau,
            pdk.MucGiaToiDa,
            pdk.SoNguoiDuKienO,
            pdk.ThoiGianDuKienVaoO,
            pdk.ThoiHanThue,
            pdk.YeuCauKhac,
            pdk.GhiChuSale,
            pdk.TrangThai
        FROM dbo.PhieuDangKy AS pdk
        WHERE pdk.MaKhachHang = kh.MaKhachHang
        ORDER BY pdk.NgayDangKy DESC, pdk.MaDangKy DESC
    ) AS hoSo
    WHERE kh.MaKhachHang = @MaKhachHangTimThay;
END;
-- =============================================
-- 2. SP_DanhSachHoSoDangKy
-- Nhân viên Sale xem danh sách hồ sơ đăng ký thuê.
-- Mặc định lấy hồ sơ đang chờ xử lý.
-- Hỗ trợ lọc theo trạng thái và chi nhánh.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_DanhSachHoSoDangKy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_DanhSachHoSoDangKy
    @TrangThai      VARCHAR(30)    = NULL,     -- NULL = lấy tất cả; hoặc lọc theo trạng thái cụ thể
    @MaChiNhanh     VARCHAR(6)      = NULL,     -- NULL = tất cả chi nhánh
    @NhanVienSaleId VARCHAR(6)      = NULL,     -- NULL = không lọc theo sale
    @KhachHangId    VARCHAR(6)      = NULL      -- NULL = không lọc theo khách hàng
AS
BEGIN
    

    SET @TrangThai      = NULLIF(TRIM(@TrangThai)), '');
    SET @MaChiNhanh     = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @NhanVienSaleId = NULLIF(TRIM(@NhanVienSaleId)), '');
    SET @KhachHangId    = NULLIF(TRIM(@KhachHangId)), '');

    IF @TrangThai IS NOT NULL
       AND @TrangThai NOT IN ('Chờ tiếp nhận', 'Đã tiếp nhận', 'Chờ xác nhận cọc', 'Xác nhận cọc', 'Từ chối')
        RAISE EXCEPTION %;

    IF @MaChiNhanh IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
        RAISE EXCEPTION %;

    IF @NhanVienSaleId IS NOT NULL
       AND NOT EXISTS (
           SELECT 1 FROM dbo.NhanVien WHERE MaNhanVien = @NhanVienSaleId AND ChucVu = 'Sale'
       )
        RAISE EXCEPTION %;

    IF @KhachHangId IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM dbo.KhachHang WHERE MaKhachHang = @KhachHangId)
        RAISE EXCEPTION %;

    SELECT
        pdk.MaDangKy            AS maDangKy,
        pdk.NgayDangKy          AS ngayDangKy,
        pdk.SoNguoiDuKienO      AS soNguoiO,
        pdk.SoNam               AS soNam,
        pdk.SoNu                AS soNu,
        pdk.KhuVucMongMuon      AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = pdk.MaDangKy) AS loaiPhongYeuCau,
        pdk.MucGiaToiDa         AS mucGia,
        pdk.ThoiGianDuKienVaoO  AS ngayDuKienVaoO,
        pdk.ThoiHanThue         AS thoiHanThue,
        pdk.YeuCauKhac          AS ghiChu,
        pdk.GhiChuSale          AS ghiChuSale,
        pdk.TrangThai           AS trangThai,
        pdk.MaKhachHang         AS maKhachHang,
        nd.HoTen                AS hoTenKhach,
        nd.NgaySinh             AS ngaySinhKhach,
        nd.SDT                  AS sdtKhach,
        nd.Email                AS emailKhach,
        nd.GioiTinh             AS gioiTinh,
        kh.QuocTich             AS quocTich,
        kh.CCCD                 AS cccd,
        pdk.MaNhanVienSale      AS maNhanVienSale,
        nvnd.HoTen              AS hoTenSale,
        nvSale.MaChiNhanh       AS maChiNhanhSale,
        cnSale.TenChiNhanh      AS tenChiNhanhSale,
        -- Lịch xem phòng gần nhất
        lich.STTLich            AS sttLichMoiNhat,
        lich.ThoiGianHen        AS thoiGianHenMoiNhat,
        lich.TrangThai          AS trangThaiLichMoiNhat
    FROM dbo.PhieuDangKy AS pdk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = pdk.MaKhachHang
    INNER JOIN dbo.KhachHang AS kh ON kh.MaKhachHang = pdk.MaKhachHang
    LEFT JOIN dbo.NguoiDung AS nvnd ON nvnd.MaNguoiDung = pdk.MaNhanVienSale
    LEFT JOIN dbo.NhanVien AS nvSale ON nvSale.MaNhanVien = pdk.MaNhanVienSale
    LEFT JOIN dbo.ChiNhanh AS cnSale ON cnSale.MaChiNhanh = nvSale.MaChiNhanh
    OUTER APPLY (
        SELECT TOP (1) lxp.STTLich, lxp.ThoiGianHen, lxp.TrangThai
        FROM dbo.LichXemPhong AS lxp
        WHERE lxp.MaDangKy = pdk.MaDangKy
        ORDER BY lxp.STTLich DESC
    ) AS lich
    WHERE (@TrangThai IS NULL OR pdk.TrangThai = @TrangThai)
      AND (@NhanVienSaleId IS NULL OR pdk.MaNhanVienSale = @NhanVienSaleId)
      AND (@KhachHangId IS NULL OR pdk.MaKhachHang = @KhachHangId)
      AND (@MaChiNhanh IS NULL
           OR nvSale.MaChiNhanh = @MaChiNhanh
           OR EXISTS (
               SELECT 1 FROM dbo.ChiNhanh cn
               WHERE cn.MaChiNhanh = @MaChiNhanh
                 AND cn.TenChiNhanh LIKE '%' + pdk.KhuVucMongMuon + '%'
           )
           OR (
               @MaChiNhanh = 'CN0001'
               AND (
                   pdk.KhuVucMongMuon LIKE '%Quận 1%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 3%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 4%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 5%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 10%'
               )
           )
           OR (
               @MaChiNhanh = 'CN0002'
               AND (
                   pdk.KhuVucMongMuon LIKE '%Bình Thạnh%'
                   OR pdk.KhuVucMongMuon LIKE '%Phú Nhuận%'
                   OR pdk.KhuVucMongMuon LIKE '%Gò Vấp%'
                   OR pdk.KhuVucMongMuon LIKE '%Tân Bình%'
               )
           )
           OR (
               @MaChiNhanh = 'CN0003'
               AND (
                   pdk.KhuVucMongMuon LIKE '%Thủ Đức%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 2%'
                   OR pdk.KhuVucMongMuon LIKE '%Quận 9%'
               )
           )
      )
    ORDER BY pdk.NgayDangKy DESC, pdk.MaDangKy DESC;
END;
-- =============================================
-- 3. SP_DanhSachPhongGiuongKhaDung
-- Lấy danh sách phòng và giường còn trống để Sale gợi ý cho khách.
-- Hỗ trợ lọc theo loại, giới tính, chi nhánh, khu vực, loại phòng, mức giá, số người hoặc hồ sơ đăng ký.
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_DanhSachPhongGiuongKhaDung AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_DanhSachPhongGiuongKhaDung
    @Loai           VARCHAR(50)    = NULL,     -- 'Nguyên căn' hoặc 'Ghép' hoặc NULL (lấy tất cả)
    @GioiTinh       VARCHAR(5)     = NULL,     -- 'Nam' hoặc 'Nữ' hoặc NULL
    @MaChiNhanh     VARCHAR(6)      = NULL,     -- Lọc theo chi nhánh
    @KhuVuc         VARCHAR(100)   = NULL,     -- Lọc theo địa chỉ/tên chi nhánh
    @LoaiPhong      VARCHAR(50)    = NULL,     -- Lọc theo tên loại phòng
    @MucGiaTu       DECIMAL(15,2)   = NULL,     -- Lọc theo ngân sách tối thiểu
    @MucGiaToiDa    DECIMAL(15,2)   = NULL,     -- Lọc theo ngân sách tối đa
    @SoNguoiO       INT             = NULL,     -- Lọc phòng đủ sức chứa/chỗ trống
    @HoSoId         VARCHAR(6)      = NULL      -- Tự lấy tiêu chí từ phiếu đăng ký
AS
BEGIN
    

    SET @Loai       = NULLIF(TRIM(@Loai)), '');
    SET @GioiTinh   = NULLIF(TRIM(@GioiTinh)), '');
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @KhuVuc     = NULLIF(TRIM(@KhuVuc)), '');
    SET @LoaiPhong  = NULLIF(TRIM(@LoaiPhong)), '');
    SET @HoSoId     = NULLIF(TRIM(@HoSoId)), '');

    DECLARE @SoNam INT = 0;
    DECLARE @SoNu INT = 0;
    DECLARE @HinhThucThue VARCHAR(50) = NULL;

    IF @HoSoId IS NOT NULL
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.PhieuDangKy WHERE MaDangKy = @HoSoId)
            RAISE EXCEPTION %;

        SELECT
            @SoNam       = COALESCE(SoNam, 0),
            @SoNu        = COALESCE(SoNu, 0),
            @KhuVuc      = COALESCE(@KhuVuc, KhuVucMongMuon),
            @MucGiaToiDa = COALESCE(@MucGiaToiDa, MucGiaToiDa),
            @SoNguoiO    = COALESCE(@SoNguoiO, SoNguoiDuKienO)
        FROM dbo.PhieuDangKy
        WHERE MaDangKy = @HoSoId;

        
        END

        IF @Loai IS NULL AND @HinhThucThue IS NOT NULL
            SET @Loai = @HinhThucThue;

        IF @GioiTinh IS NULL
        BEGIN
            IF @SoNam > 0 AND @SoNu = 0 SET @GioiTinh = 'Nam';
            ELSE IF @SoNu > 0 AND @SoNam = 0 SET @GioiTinh = 'Nữ';
        END
    END;

    IF @Loai IN ('Nguyên phòng', 'Nguyên căn')
        SET @Loai = 'Nguyên căn';
    IF @Loai IN ('Ghép giường', 'Ghép')
        SET @Loai = 'Ghép';

    IF @Loai IS NOT NULL AND @Loai NOT IN ('Nguyên căn', 'Ghép')
        RAISE EXCEPTION %;

    IF @GioiTinh IS NOT NULL AND @GioiTinh NOT IN ('Nam', 'Nữ')
        RAISE EXCEPTION %;

    IF @MucGiaTu IS NOT NULL AND @MucGiaTu < 0
        RAISE EXCEPTION %;

    IF @MucGiaToiDa IS NOT NULL AND @MucGiaToiDa < 0
        RAISE EXCEPTION %;

    IF @SoNguoiO IS NOT NULL AND @SoNguoiO < 1
        RAISE EXCEPTION %;

    IF @SoNguoiO IS NULL AND (@SoNam + @SoNu) > 0
        SET @SoNguoiO = @SoNam + @SoNu;

    DECLARE @SoNguoiCanXep INT = COALESCE(NULLIF(@SoNguoiO, 0), CASE WHEN (@SoNam + @SoNu) > 0 THEN @SoNam + @SoNu ELSE 1 END);
    DECLARE @LaNhomHonHop BOOLEAN = CASE WHEN @SoNam > 0 AND @SoNu > 0 THEN 1 ELSE 0 END;

    IF @MaChiNhanh IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
        RAISE EXCEPTION %;

    CREATE TABLE #ChiNhanhPhuHop (MaChiNhanh VARCHAR(6) PRIMARY KEY);

    IF @MaChiNhanh IS NOT NULL
    BEGIN
        INSERT INTO #ChiNhanhPhuHop (MaChiNhanh)
        SELECT MaChiNhanh
        FROM dbo.ChiNhanh
        WHERE MaChiNhanh = @MaChiNhanh
          AND TrangThai = 'Hoạt động';
    END
    ELSE IF @KhuVuc IS NULL
    BEGIN
        INSERT INTO #ChiNhanhPhuHop (MaChiNhanh)
        SELECT MaChiNhanh
        FROM dbo.ChiNhanh
        WHERE TrangThai = 'Hoạt động';
    END
    ELSE
    BEGIN
        INSERT INTO #ChiNhanhPhuHop (MaChiNhanh)
        SELECT MaChiNhanh
        FROM dbo.ChiNhanh
        WHERE TrangThai = 'Hoạt động'
          AND (DiaChi LIKE '%' + @KhuVuc + '%' OR TenChiNhanh LIKE '%' + @KhuVuc + '%');

        INSERT INTO #ChiNhanhPhuHop (MaChiNhanh)
        SELECT cn.MaChiNhanh
        FROM dbo.ChiNhanh AS cn
        WHERE cn.TrangThai = 'Hoạt động'
          AND (
              (
                  cn.MaChiNhanh = 'CN0001'
                  AND (
                      @KhuVuc LIKE '%Quận 1%'
                      OR @KhuVuc LIKE '%Quận 3%'
                      OR @KhuVuc LIKE '%Quận 4%'
                      OR @KhuVuc LIKE '%Quận 5%'
                      OR @KhuVuc LIKE '%Quận 10%'
                  )
              )
              OR (
                  cn.MaChiNhanh = 'CN0002'
                  AND (
                      @KhuVuc LIKE '%Bình Thạnh%'
                      OR @KhuVuc LIKE '%Phú Nhuận%'
                      OR @KhuVuc LIKE '%Gò Vấp%'
                      OR @KhuVuc LIKE '%Tân Bình%'
                  )
              )
              OR (
                  cn.MaChiNhanh = 'CN0003'
                  AND (
                      @KhuVuc LIKE '%Thủ Đức%'
                      OR @KhuVuc LIKE '%Quận 2%'
                      OR @KhuVuc LIKE '%Quận 9%'
                  )
              )
          )
          AND NOT EXISTS (
              SELECT 1
              FROM #ChiNhanhPhuHop AS existed
              WHERE existed.MaChiNhanh = cn.MaChiNhanh
          );
    END;

    DECLARE @KhongCoChiNhanhPhuHop BOOLEAN =
        CASE WHEN @MaChiNhanh IS NULL AND @KhuVuc IS NOT NULL AND NOT EXISTS (SELECT 1 FROM #ChiNhanhPhuHop)
             THEN 1 ELSE 0 END;

    CREATE TABLE #LoaiPhongYeuCau (MaLoaiPhong VARCHAR(6) PRIMARY KEY);

    IF @LoaiPhong IS NOT NULL
    BEGIN
        INSERT INTO #LoaiPhongYeuCau (MaLoaiPhong)
        SELECT MaLoaiPhong
        FROM dbo.LoaiPhong
        WHERE TenLoaiPhong = @LoaiPhong;
    END
    ELSE IF @HoSoId IS NOT NULL
       AND OBJECT_ID('dbo.PDK_LoaiPhong', 'U') IS NOT NULL
       AND EXISTS (SELECT 1 FROM dbo.PDK_LoaiPhong WHERE MaDangKy = @HoSoId)
    BEGIN
        INSERT INTO #LoaiPhongYeuCau (MaLoaiPhong)
        SELECT DISTINCT MaLoaiPhong
        FROM dbo.PDK_LoaiPhong
        WHERE MaDangKy = @HoSoId;
    END

    IF NOT EXISTS (SELECT 1 FROM #LoaiPhongYeuCau)
    BEGIN
        INSERT INTO #LoaiPhongYeuCau (MaLoaiPhong)
        SELECT MaLoaiPhong
        FROM dbo.LoaiPhong;
    END;

    ;WITH BedCounts AS (
        SELECT
            g.MaPhong,
            COUNT(CASE WHEN g.TinhTrang = 'Trống' THEN 1 END) AS soGiuongTrong
        FROM dbo.Giuong AS g
        GROUP BY g.MaPhong
    )
    SELECT
        p.MaPhong,
        p.TenPhong,
        p.GioiTinhChoPhep,
        p.TinhTrang,
        p.MaChiNhanh,
        p.MaLoaiPhong,
        lp.TenLoaiPhong,
        lp.MoTa,
        lp.SucChuaToiDa,
        lp.GiaThueTheoGiuong,
        lp.GiaThueNguyenPhong,
        cn.TenChiNhanh,
        cn.DiaChi,
        COALESCE(bc.soGiuongTrong, 0) AS soGiuongTrong,
        (SELECT TOP 1 UrlImg FROM dbo.HinhAnhPhong hap WHERE hap.MaPhong = p.MaPhong ORDER BY hap.STTAnh) AS urlImg
    INTO #BaseRooms
    FROM dbo.Phong AS p
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
    INNER JOIN #ChiNhanhPhuHop AS cnp ON cnp.MaChiNhanh = p.MaChiNhanh
    INNER JOIN #LoaiPhongYeuCau AS lpyc ON lpyc.MaLoaiPhong = p.MaLoaiPhong
    LEFT JOIN BedCounts AS bc ON bc.MaPhong = p.MaPhong;

    CREATE TABLE #KetQua (
        phuongAn INT NOT NULL,
        maPhong VARCHAR(4) NULL,
        tenPhong VARCHAR(100) NULL,
        loaiThue VARCHAR(30) NULL,
        maLoaiPhong VARCHAR(6) NULL,
        loaiPhong VARCHAR(100) NULL,
        moTa TEXT NULL,
        giaThue DECIMAL(15,2) NULL,
        sucChua INT NULL,
        gioiTinhChoPhep VARCHAR(20) NULL,
        tinhTrang VARCHAR(20) NULL,
        maChiNhanh VARCHAR(6) NULL,
        tenChiNhanh VARCHAR(100) NULL,
        diaChi VARCHAR(255) NULL,
        urlImg VARCHAR(500) NULL,
        maGiuong VARCHAR(3) NULL,
        soGiuong INT NULL,
        soGiuongTrong INT NULL,
        soGiuongDuKienXep INT NULL,
        tongNamDuocXep INT NULL,
        tongNuDuocXep INT NULL,
        khongCoChiNhanhPhuHop BOOLEAN NOT NULL
    );

    CREATE TABLE #PhongUngVien (
        MaPhong VARCHAR(4) NOT NULL PRIMARY KEY,
        MaLoaiPhong VARCHAR(6) NOT NULL,
        GiaMoiNguoi DECIMAL(15,2) NOT NULL,
        LaTrongNguyenPhong BOOLEAN NOT NULL,
        SoGiuongNam INT NOT NULL,
        SoGiuongNu INT NOT NULL,
        SoGiuongKhongPhanBiet INT NOT NULL
    );

    INSERT INTO #PhongUngVien (
        MaPhong, MaLoaiPhong, GiaMoiNguoi, LaTrongNguyenPhong,
        SoGiuongNam, SoGiuongNu, SoGiuongKhongPhanBiet
    )
    SELECT
        br.MaPhong,
        br.MaLoaiPhong,
        COALESCE(br.GiaThueTheoGiuong, br.GiaThueNguyenPhong / NULLIF(br.SucChuaToiDa, 0)) AS GiaMoiNguoi,
        CASE
            WHEN br.TinhTrang = 'Trống'
             AND br.soGiuongTrong >= br.SucChuaToiDa
             AND br.GioiTinhChoPhep IN ('Không phân biệt', 'Khác', 'Hỗn hợp')
                THEN 1 ELSE 0
        END AS LaTrongNguyenPhong,
        CASE WHEN br.GioiTinhChoPhep = 'Nam' THEN br.soGiuongTrong ELSE 0 END AS SoGiuongNam,
        CASE WHEN br.GioiTinhChoPhep = 'Nữ' THEN br.soGiuongTrong ELSE 0 END AS SoGiuongNu,
        CASE WHEN br.GioiTinhChoPhep IN ('Không phân biệt', 'Khác', 'Hỗn hợp') THEN br.soGiuongTrong ELSE 0 END AS SoGiuongKhongPhanBiet
    FROM #BaseRooms AS br
    WHERE br.TinhTrang IN ('Trống', 'Còn chỗ')
      AND br.soGiuongTrong > 0
      AND COALESCE(br.GiaThueTheoGiuong, br.GiaThueNguyenPhong / NULLIF(br.SucChuaToiDa, 0)) IS NOT NULL
      AND (@MucGiaTu IS NULL OR COALESCE(br.GiaThueTheoGiuong, br.GiaThueNguyenPhong / NULLIF(br.SucChuaToiDa, 0)) >= @MucGiaTu)
      AND (@MucGiaToiDa IS NULL OR COALESCE(br.GiaThueTheoGiuong, br.GiaThueNguyenPhong / NULLIF(br.SucChuaToiDa, 0)) <= @MucGiaToiDa)
      AND (
          @Loai IS NULL
          OR @Loai = 'Ghép'
          OR (
              @Loai = 'Nguyên căn'
              AND br.TinhTrang = 'Trống'
              AND br.soGiuongTrong >= br.SucChuaToiDa
          )
      );

    CREATE TABLE #LoaiPhongHopLe (
        MaLoaiPhong VARCHAR(6) NOT NULL PRIMARY KEY
    );

    INSERT INTO #LoaiPhongHopLe (MaLoaiPhong)
    SELECT puv.MaLoaiPhong
    FROM #PhongUngVien AS puv
    GROUP BY puv.MaLoaiPhong
    HAVING
        (
            @LaNhomHonHop = 0
            AND MAX(CASE
                WHEN @GioiTinh = 'Nam'
                     AND (puv.SoGiuongNam + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep THEN 1
                WHEN @GioiTinh = 'Nữ'
                     AND (puv.SoGiuongNu + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep THEN 1
                WHEN @GioiTinh IS NULL
                     AND (puv.SoGiuongNam + puv.SoGiuongNu + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep THEN 1
                ELSE 0
            END) = 1
        )
        OR
        (
            @LaNhomHonHop = 1
            AND MAX(CASE WHEN puv.LaTrongNguyenPhong = 1 AND puv.SoGiuongKhongPhanBiet >= @SoNguoiCanXep THEN 1 ELSE 0 END) = 1
        );

    ;WITH PhongTraVe AS (
        SELECT
            ROW_NUMBER() OVER (
                PARTITION BY br.MaLoaiPhong
                ORDER BY
                    CASE WHEN puv.LaTrongNguyenPhong = 1 THEN 0 ELSE 1 END,
                    puv.GiaMoiNguoi,
                    br.TenPhong,
                    br.MaPhong
            ) AS rn,
            br.*,
            puv.GiaMoiNguoi,
            puv.LaTrongNguyenPhong
        FROM #BaseRooms AS br
        INNER JOIN #PhongUngVien AS puv ON puv.MaPhong = br.MaPhong
        INNER JOIN #LoaiPhongHopLe AS lphl ON lphl.MaLoaiPhong = br.MaLoaiPhong
        WHERE
            (
                @LaNhomHonHop = 0
                AND (
                    (@GioiTinh = 'Nam' AND (puv.SoGiuongNam + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep)
                    OR (@GioiTinh = 'Nữ' AND (puv.SoGiuongNu + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep)
                    OR (@GioiTinh IS NULL AND (puv.SoGiuongNam + puv.SoGiuongNu + puv.SoGiuongKhongPhanBiet) >= @SoNguoiCanXep)
                )
            )
            OR
            (
                @LaNhomHonHop = 1
                AND puv.LaTrongNguyenPhong = 1
                AND puv.SoGiuongKhongPhanBiet >= @SoNguoiCanXep
            )
    )
    INSERT INTO #KetQua (
        phuongAn, maPhong, tenPhong, loaiThue, maLoaiPhong, loaiPhong, moTa,
        giaThue, sucChua, gioiTinhChoPhep, tinhTrang, maChiNhanh, tenChiNhanh,
        diaChi, urlImg, maGiuong, soGiuong, soGiuongTrong, soGiuongDuKienXep,
        tongNamDuocXep, tongNuDuocXep, khongCoChiNhanhPhuHop
    )
    SELECT
        rn,
        MaPhong,
        TenPhong,
        CASE WHEN LaTrongNguyenPhong = 1 THEN 'Nguyên căn' ELSE 'Ghép' END,
        MaLoaiPhong,
        TenLoaiPhong,
        MoTa,
        GiaMoiNguoi,
        SucChuaToiDa,
        GioiTinhChoPhep,
        TinhTrang,
        MaChiNhanh,
        TenChiNhanh,
        DiaChi,
        urlImg,
        NULL,
        NULL,
        soGiuongTrong,
        CASE WHEN soGiuongTrong >= @SoNguoiCanXep THEN @SoNguoiCanXep ELSE soGiuongTrong END,
        COALESCE(@SoNam, 0),
        COALESCE(@SoNu, 0),
        @KhongCoChiNhanhPhuHop
    FROM PhongTraVe;

    SELECT *
    FROM #KetQua
    ORDER BY loaiThue, giaThue, loaiPhong, tenPhong, maGiuong;
END;
-- =============================================
-- 4. SP_KiemTraDieuKienThue
-- Kiểm tra hồ sơ đăng ký có đủ điều kiện để chuyển sang bước đặt cọc không.
-- Trả về: hopLe (BOOLEAN), lyDo (VARCHAR)
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_KiemTraDieuKienThue AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_KiemTraDieuKienThue
    @HoSoId VARCHAR(30)
AS
BEGIN
    

    SET @HoSoId = TRIM(@HoSoId));

    IF NOT EXISTS (SELECT 1 FROM dbo.PhieuDangKy WHERE MaDangKy = @HoSoId)
        RAISE EXCEPTION %;

    UPDATE dbo.LichXemPhong
    SET TrangThai = 'Đã xem'
    WHERE MaDangKy = @HoSoId
      AND TrangThai IN ('Chờ xem', 'Yêu cầu đổi lịch', 'Yêu cầu hủy')
      AND ThoiGianHen <= CURRENT_TIMESTAMP;

    DECLARE @TrangThai          VARCHAR(30);
    DECLARE @MaKhachHang        VARCHAR(6);
    DECLARE @NgayDuKienVaoO     DATE;
    DECLARE @SoLichXemDaXem     INT;

    SELECT
        @TrangThai          = pdk.TrangThai,
        @MaKhachHang        = pdk.MaKhachHang,
        @NgayDuKienVaoO     = pdk.ThoiGianDuKienVaoO
    FROM dbo.PhieuDangKy AS pdk
    WHERE pdk.MaDangKy = @HoSoId;

    -- Đếm số lần đã xem phòng thành công
    SELECT @SoLichXemDaXem = COUNT(*)
    FROM dbo.LichXemPhong
    WHERE MaDangKy = @HoSoId AND TrangThai = 'Đã xem';

    SELECT
        @HoSoId                             AS maDangKy,
        @TrangThai                          AS trangThai,
        @NgayDuKienVaoO                     AS ngayDuKienVaoO,
        @SoLichXemDaXem                     AS soLichXemDaXem,
        -- Hồ sơ hợp lệ khi: đang ở trạng thái Chờ tiếp nhận + đã xem phòng ít nhất 1 lần
        CAST(CASE
            WHEN @TrangThai = 'Chờ tiếp nhận' AND @SoLichXemDaXem >= 1 THEN 1
            ELSE 0
        END AS BOOLEAN)                         AS hopLe,
        CASE
            WHEN @TrangThai = 'Chờ xác nhận cọc' THEN 'Hồ sơ đã được chấp nhận và đang chờ đặt cọc.'
            WHEN @TrangThai = 'Chấp nhận'         THEN 'Hồ sơ đã được chấp nhận.'
            WHEN @TrangThai = 'Từ chối'           THEN 'Hồ sơ đã bị từ chối.'
            WHEN @SoLichXemDaXem < 1               THEN 'Khách hàng chưa xem phòng lần nào. Cần sắp xếp lịch xem phòng trước.'
            ELSE 'Hồ sơ đủ điều kiện tiến hành đặt cọc.'
        END                                 AS lyDo;
END;
-- =============================================
-- 5. SP_CapNhatKetQuaXuLyHoSo
-- Nhân viên Sale cập nhật kết quả xử lý hồ sơ đăng ký.
-- TrangThai hợp lệ: 'Chấp nhận', 'Từ chối', 'Chờ xác nhận cọc'
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_CapNhatKetQuaXuLyHoSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_CapNhatKetQuaXuLyHoSo
    @HoSoId         VARCHAR(30),
    @TrangThai      VARCHAR(50),
    @GhiChuXuLy     TEXT   = NULL,
    @NhanVienSaleId VARCHAR(20)    = NULL
AS
BEGIN
    
    

    SET @HoSoId         = TRIM(@HoSoId));
    SET @TrangThai      = TRIM(@TrangThai));
    SET @NhanVienSaleId = NULLIF(TRIM(@NhanVienSaleId)), '');
    SET @GhiChuXuLy     = NULLIF(TRIM(@GhiChuXuLy)), '');

    -- Kiểm tra hồ sơ tồn tại
    IF NOT EXISTS (SELECT 1 FROM dbo.PhieuDangKy WHERE MaDangKy = @HoSoId)
        RAISE EXCEPTION %;

    UPDATE dbo.LichXemPhong
    SET TrangThai = 'Đã xem'
    WHERE MaDangKy = @HoSoId
      AND TrangThai IN ('Chờ xem', 'Yêu cầu đổi lịch', 'Yêu cầu hủy')
      AND ThoiGianHen <= CURRENT_TIMESTAMP;

    -- Kiểm tra trạng thái mới hợp lệ
    IF @TrangThai NOT IN ('Chấp nhận', 'Từ chối', 'Chờ xác nhận cọc', 'Đã tiếp nhận')
        RAISE EXCEPTION %;

    -- Kiểm tra hồ sơ có đang ở trạng thái có thể cập nhật không
    DECLARE @TrangThaiHienTai VARCHAR(30);
    SELECT @TrangThaiHienTai = TrangThai FROM dbo.PhieuDangKy WHERE MaDangKy = @HoSoId;

    IF @TrangThaiHienTai NOT IN ('Chờ tiếp nhận', 'Chờ xác nhận cọc')
        RAISE EXCEPTION %;

    IF @NhanVienSaleId IS NOT NULL
       AND EXISTS (
           SELECT 1
           FROM dbo.PhieuDangKy
           WHERE MaDangKy = @HoSoId
             AND MaNhanVienSale IS NOT NULL
             AND MaNhanVienSale <> @NhanVienSaleId
       )
        RAISE EXCEPTION %;

    -- Kiểm tra nhân viên Sale tồn tại (nếu có truyền vào)
    IF @NhanVienSaleId IS NOT NULL
       AND NOT EXISTS (
           SELECT 1 FROM dbo.NhanVien WHERE MaNhanVien = @NhanVienSaleId AND ChucVu = 'Sale'
       )
        RAISE EXCEPTION %;

    -- Nếu chấp nhận hồ sơ hoặc chuyển sang bước cọc: khách phải đã xem phòng ít nhất 1 lần
    IF @TrangThai IN ('Chờ xác nhận cọc', 'Chấp nhận')
       AND NOT EXISTS (
           SELECT 1 FROM dbo.LichXemPhong
           WHERE MaDangKy = @HoSoId AND TrangThai = 'Đã xem'
       )
        RAISE EXCEPTION %;

    BEGIN TRY
        BEGIN TRANSACTION;
        IF @TrangThai = 'Chờ xác nhận cọc'
        BEGIN
            UPDATE dbo.PhieuDangKy
            SET TrangThai = @TrangThai,
                MaNhanVienSale = COALESCE(@NhanVienSaleId, MaNhanVienSale)
            WHERE MaDangKy = @HoSoId;

            -- Khi chuyển sang chờ đặt cọc, không cập nhật GhiChuSale
        END
        ELSE
        BEGIN
            UPDATE dbo.PhieuDangKy
            SET TrangThai = @TrangThai,
                GhiChuSale = COALESCE(@GhiChuXuLy, GhiChuSale),
                MaNhanVienSale = COALESCE(@NhanVienSaleId, MaNhanVienSale)
            WHERE MaDangKy = @HoSoId;
        END;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    -- Trả về hồ sơ sau khi cập nhật
    SELECT
        pdk.MaDangKy            AS maDangKy,
        pdk.NgayDangKy          AS ngayDangKy,
        pdk.SoNguoiDuKienO      AS soNguoiO,
        pdk.SoNam               AS soNam,
        pdk.SoNu                AS soNu,
        pdk.KhuVucMongMuon      AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ')
         FROM dbo.PDK_LoaiPhong pdklp
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong
         WHERE pdklp.MaDangKy = pdk.MaDangKy) AS loaiPhongYeuCau,
        pdk.MucGiaToiDa         AS mucGia,
        pdk.ThoiGianDuKienVaoO  AS ngayDuKienVaoO,
        pdk.ThoiHanThue         AS thoiHanThue,
        pdk.YeuCauKhac          AS ghiChu,
        pdk.TrangThai           AS trangThai,
        pdk.MaKhachHang         AS maKhachHang,
        nd.HoTen                AS hoTenKhach,
        nd.SDT                  AS sdtKhach,
        nd.Email                AS emailKhach,
        pdk.MaNhanVienSale      AS maNhanVienSale,
        nvnd.HoTen              AS hoTenSale
    FROM dbo.PhieuDangKy AS pdk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = pdk.MaKhachHang
    LEFT JOIN dbo.NguoiDung AS nvnd ON nvnd.MaNguoiDung = pdk.MaNhanVienSale
    WHERE pdk.MaDangKy = @HoSoId;
END;
-- =============================================
-- 9. SP_TraCuuPhong
-- Tra cứu toàn bộ danh sách phòng để hiển thị trên màn hình Tra Cứu Phòng của Sale
-- =============================================

    EXEC('CREATE PROCEDURE dbo.SP_TraCuuPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_TraCuuPhong
    @KhuVuc         VARCHAR(100) = NULL,
    @LoaiPhong      VARCHAR(50)  = NULL,
    @HinhThucThue   VARCHAR(50)  = NULL,
    @MucGiaToiDa    DECIMAL(15,2) = NULL
AS
BEGIN
    

    SET @KhuVuc = NULLIF(TRIM(@KhuVuc)), '');
    SET @LoaiPhong = NULLIF(TRIM(@LoaiPhong)), '');
    SET @HinhThucThue = NULLIF(TRIM(@HinhThucThue)), '');

    IF @KhuVuc = 'Tất cả khu vực' SET @KhuVuc = NULL;
    IF @LoaiPhong = 'Tất cả loại phòng' SET @LoaiPhong = NULL;
    IF @HinhThucThue = 'Tất cả hình thức' SET @HinhThucThue = NULL;

    SELECT
        p.MaPhong AS id,
        p.TenPhong AS name,
        cn.TenChiNhanh AS subName,
        cn.DiaChi AS area,
        CASE
            WHEN p.GioiTinhChoPhep = 'Nam' THEN 'Ghép nam'
            WHEN p.GioiTinhChoPhep = 'Nữ' THEN 'Ghép nữ'
            ELSE 'Nguyên căn'
        END AS type,
        COALESCE(lp.GiaThueNguyenPhong, lp.GiaThueTheoGiuong) AS price,
        (
            SELECT COUNT(*)
            FROM dbo.Giuong g
            WHERE g.MaPhong = p.MaPhong AND g.TinhTrang = 'Trống'
        ) AS emptyBeds,
        lp.SucChuaToiDa AS capacity,
        p.TinhTrang AS status
    FROM dbo.Phong p
    INNER JOIN dbo.LoaiPhong lp ON p.MaLoaiPhong = lp.MaLoaiPhong
    INNER JOIN dbo.ChiNhanh cn ON p.MaChiNhanh = cn.MaChiNhanh
    WHERE cn.TrangThai = 'Hoạt động'
      AND (@KhuVuc IS NULL OR cn.DiaChi LIKE '%' + @KhuVuc + '%' OR cn.TenChiNhanh LIKE '%' + @KhuVuc + '%')
      AND (@LoaiPhong IS NULL OR lp.TenLoaiPhong = @LoaiPhong)
      AND (@HinhThucThue IS NULL OR
           (@HinhThucThue = 'Nguyên căn' AND (p.GioiTinhChoPhep = 'Không phân biệt' OR p.GioiTinhChoPhep IS NULL)) OR
           (@HinhThucThue = 'Ghép nam' AND p.GioiTinhChoPhep = 'Nam') OR
           (@HinhThucThue = 'Ghép nữ' AND p.GioiTinhChoPhep = 'Nữ')
          )
      AND (@MucGiaToiDa IS NULL OR COALESCE(lp.GiaThueNguyenPhong, lp.GiaThueTheoGiuong) <= @MucGiaToiDa)
    ORDER BY p.TenPhong;
END;

-- Source: Database/SP_DKyThue/khach-moi.sql

-- Du lieu va stored procedure phuc vu cong khach hang moi.
-- Khach moi duoc xac dinh la khach chua tung co phieu dat coc hoac hop dong.



    EXEC('CREATE PROCEDURE dbo.SP_KhachMoi_TrangThai AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_KhachMoi_TrangThai
    @KhachHangId VARCHAR(6)
AS
BEGIN
    

    IF NOT EXISTS (SELECT 1 FROM dbo.KhachHang WHERE MaKhachHang = @KhachHangId)
        RAISE EXCEPTION %;

    SELECT
        @KhachHangId AS khachHangId,
        CAST(CASE
            WHEN EXISTS (SELECT 1 FROM dbo.PhieuDatCoc WHERE MaKhachHang = @KhachHangId)
              OR EXISTS (SELECT 1 FROM dbo.HopDongThue WHERE MaKhachHang = @KhachHangId)
            THEN 0 ELSE 1 END AS BOOLEAN) AS laKhachMoi,
        (SELECT COUNT(*) FROM dbo.PhieuDangKy WHERE MaKhachHang = @KhachHangId) AS soHoSo,
        (SELECT COUNT(*) FROM dbo.LichXemPhong lxp
            INNER JOIN dbo.PhieuDangKy pdk ON pdk.MaDangKy = lxp.MaDangKy
            WHERE pdk.MaKhachHang = @KhachHangId) AS soLichXem,
        (SELECT COUNT(*) FROM dbo.PhieuDatCoc WHERE MaKhachHang = @KhachHangId) AS soPhieuCoc,
        (SELECT COUNT(*) FROM dbo.HopDongThue WHERE MaKhachHang = @KhachHangId) AS soHopDong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_KhachMoi_DanhSachPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_KhachMoi_DanhSachPhong
    @TenPhong VARCHAR(100) = NULL,
    @LoaiPhong VARCHAR(100) = NULL,
    @KhuVuc VARCHAR(100) = NULL,
    @MucGiaToiDa DECIMAL(15, 2) = NULL
AS
BEGIN
    

    SET @TenPhong = NULLIF(TRIM(@TenPhong)), '');
    SET @LoaiPhong = NULLIF(TRIM(@LoaiPhong)), '');
    SET @KhuVuc = NULLIF(TRIM(@KhuVuc)), '');

    IF @MucGiaToiDa IS NOT NULL AND @MucGiaToiDa < 0
        RAISE EXCEPTION %;

    WITH PhongKhaDung AS (
        SELECT
            p.MaPhong AS id,
            p.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            lp.TenLoaiPhong AS loaiPhong,
            lp.MoTa AS moTa,
            lp.GiaThueTheoGiuong AS giaTheoGiuong,
            COALESCE(lp.GiaThueNguyenPhong, lp.GiaThueTheoGiuong * lp.SucChuaToiDa) AS giaNguyenPhong,
            COALESCE(lp.GiaThueTheoGiuong, lp.GiaThueNguyenPhong) AS giaThue,
            lp.SucChuaToiDa AS sucChua,
            CASE
                WHEN SUM(CASE WHEN g.TinhTrang = 'Trống' THEN 1 ELSE 0 END) > lp.SucChuaToiDa
                    THEN lp.SucChuaToiDa
                ELSE SUM(CASE WHEN g.TinhTrang = 'Trống' THEN 1 ELSE 0 END)
            END AS soChoTrong,
            p.GioiTinhChoPhep AS gioiTinhChoPhep,
            cn.TenChiNhanh AS chiNhanh,
            cn.DiaChi AS diaChi,
            (SELECT TOP 1 UrlImg FROM dbo.HinhAnhPhong hap WHERE hap.MaPhong = p.MaPhong ORDER BY hap.STTAnh) AS urlImg
        FROM dbo.Phong AS p
        INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
        INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
        INNER JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
        -- Remove WHERE p.TinhTrang IN ('Trống', 'Còn chỗ')
        WHERE cn.TrangThai = 'Hoạt động'
          AND (
              @TenPhong IS NULL
              OR p.TenPhong LIKE '%' + @TenPhong + '%'
              OR cn.TenChiNhanh LIKE '%' + @TenPhong + '%'
              OR cn.DiaChi LIKE '%' + @TenPhong + '%'
              OR lp.TenLoaiPhong LIKE '%' + @TenPhong + '%'
          )
          AND (@LoaiPhong IS NULL OR lp.TenLoaiPhong = @LoaiPhong)
          AND (@KhuVuc IS NULL OR cn.DiaChi LIKE '%' + @KhuVuc + '%')
        GROUP BY p.MaPhong, p.TenPhong, p.GioiTinhChoPhep, lp.TenLoaiPhong, lp.MoTa,
            lp.GiaThueTheoGiuong, lp.GiaThueNguyenPhong, lp.SucChuaToiDa,
            cn.TenChiNhanh, cn.DiaChi
    )
    SELECT *
    FROM PhongKhaDung
    WHERE (1=1)
      AND (
          @MucGiaToiDa IS NULL
          OR COALESCE(giaTheoGiuong, giaNguyenPhong) <= @MucGiaToiDa
      )
    ORDER BY COALESCE(giaTheoGiuong, giaNguyenPhong), tenPhong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_KhachMoi_ChiTietPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_KhachMoi_ChiTietPhong
    @MaPhong VARCHAR(4)
AS
BEGIN
    

    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');

    IF @MaPhong IS NULL
        RAISE EXCEPTION %;

    SELECT
        p.MaPhong AS id,
        p.MaPhong AS maPhong,
        p.TenPhong AS tenPhong,
        lp.TenLoaiPhong AS loaiPhong,
        lp.MoTa AS moTa,
        lp.SucChuaToiDa AS sucChua,
        p.GioiTinhChoPhep AS gioiTinhChoPhep,
        p.TinhTrang AS tinhTrang,
        cn.TenChiNhanh AS chiNhanh,
        cn.DiaChi AS diaChi,
        lp.GiaThueTheoGiuong AS giaTheoGiuong,
        lp.GiaThueTheoGiuong AS giaThueTheoGiuong,
        COALESCE(lp.GiaThueNguyenPhong, lp.GiaThueTheoGiuong * lp.SucChuaToiDa) AS giaNguyenPhong,
        COALESCE(lp.GiaThueNguyenPhong, lp.GiaThueTheoGiuong * lp.SucChuaToiDa) AS giaThueNguyenPhong,
        COALESCE(lp.GiaThueTheoGiuong, lp.GiaThueNguyenPhong) AS giaThue,
        CASE
            WHEN CASE WHEN (SUBSTRING(p.MaPhong, 2, 1) ~ '^[0-9]+) IS NULL THEN NULL
            ELSE TRY_CONVERT(INT, SUBSTRING(p.MaPhong, 2, 1))
        END AS tang,
        (
            SELECT COUNT(*)
            FROM dbo.Giuong AS g
            WHERE g.MaPhong = p.MaPhong
              AND g.TinhTrang = 'Trống'
        ) AS soChoTrong,
        (
            SELECT TOP (1) hap.UrlImg
            FROM dbo.HinhAnhPhong AS hap
            WHERE hap.MaPhong = p.MaPhong
            ORDER BY hap.STTAnh
        ) AS anhDai,
        (
            SELECT TOP (1) hap.UrlImg
            FROM dbo.HinhAnhPhong AS hap
            WHERE hap.MaPhong = p.MaPhong
            ORDER BY hap.STTAnh
        ) AS urlImg
    FROM dbo.Phong AS p
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
    WHERE p.MaPhong = @MaPhong;

    SELECT
        hap.STTAnh AS stt,
        hap.STTAnh AS sttAnh,
        hap.UrlImg AS urlAnh,
        hap.UrlImg AS urlImg,
        CONCAT('Ảnh phòng ', hap.STTAnh) AS moTa
    FROM dbo.HinhAnhPhong AS hap
    WHERE hap.MaPhong = @MaPhong
    ORDER BY hap.STTAnh;

    SELECT
        ts.MaTaiSan AS maTaiSan,
        ts.TenTaiSan AS tenTaiSan,
        ts.TenTaiSan AS tenTienNghi,
        ts.SoLuong AS soLuong,
        ts.DonGia AS donGia
    FROM dbo.TaiSan AS ts
    WHERE ts.MaPhong = @MaPhong
    ORDER BY ts.TenTaiSan;

    SELECT
        dv.MaDichVu AS maDichVu,
        dv.TenDichVu AS tenDichVu,
        dv.DonGia AS donGia,
        dv.DonViTinh AS donViTinh
    FROM dbo.DichVu AS dv
    ORDER BY dv.TenDichVu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_KhachMoi_DanhSachHoSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_KhachMoi_DanhSachHoSo
    @KhachHangId VARCHAR(6)
AS
BEGIN
    

    SELECT
        pdk.MaDangKy AS id,
        pdk.MaDangKy AS maDangKy,
        pdk.NgayDangKy AS ngayDangKy,
        pdk.KhuVucMongMuon AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ') 
         FROM dbo.PDK_LoaiPhong pdklp 
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong 
         WHERE pdklp.MaDangKy = pdk.MaDangKy) AS loaiPhongYeuCau,
        pdk.MucGiaToiDa AS mucGia,
        pdk.SoNguoiDuKienO AS soNguoiO,
        pdk.SoNam AS soNam,
        pdk.SoNu AS soNu,
        pdk.ThoiGianDuKienVaoO AS ngayDuKienVaoO,
        pdk.ThoiHanThue AS thoiHanThue,
        pdk.YeuCauKhac AS ghiChu,
        pdk.TrangThai AS trangThai,
        lich.STTLich AS sttLich,
        lich.ThoiGianHen AS thoiGianHen,
        lich.TrangThai AS trangThaiLich
    FROM dbo.PhieuDangKy AS pdk
    OUTER APPLY (
        SELECT TOP (1) lxp.STTLich, lxp.ThoiGianHen, lxp.TrangThai
        FROM dbo.LichXemPhong AS lxp
        WHERE lxp.MaDangKy = pdk.MaDangKy
        ORDER BY lxp.STTLich DESC
    ) AS lich
    WHERE pdk.MaKhachHang = @KhachHangId
    ORDER BY pdk.NgayDangKy DESC, pdk.MaDangKy DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_KhachMoi_DanhSachLichXem AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_KhachMoi_DanhSachLichXem
    @KhachHangId VARCHAR(6)
AS
BEGIN
    

    UPDATE lxp
    SET lxp.TrangThai = 'Đã xem'
    FROM dbo.LichXemPhong AS lxp
    INNER JOIN dbo.PhieuDangKy AS pdk ON pdk.MaDangKy = lxp.MaDangKy
    WHERE pdk.MaKhachHang = @KhachHangId
      AND lxp.TrangThai IN ('Chờ xem', 'Yêu cầu đổi lịch', 'Yêu cầu hủy')
      AND lxp.ThoiGianHen <= CURRENT_TIMESTAMP;

    SELECT
        CONCAT(lxp.MaDangKy, '-', lxp.STTLich) AS id,
        lxp.MaDangKy AS maDangKy,
        lxp.STTLich AS sttLich,
        lxp.ThoiGianHen AS thoiGianHen,
        lxp.TrangThai AS trangThai,
        lxp.GhiChu AS ghiChu,
        pdk.MaNhanVienSale AS maNhanVienSale,
        ndSale.HoTen AS tenNhanVienSale,
        ndSale.SDT AS sdtNhanVienSale,
        phong.phongXem
    FROM dbo.LichXemPhong AS lxp
    INNER JOIN dbo.PhieuDangKy AS pdk ON pdk.MaDangKy = lxp.MaDangKy
    LEFT JOIN dbo.NguoiDung AS ndSale ON ndSale.MaNguoiDung = pdk.MaNhanVienSale
    OUTER APPLY (
        SELECT STRING_AGG(p.TenPhong, ', ') AS phongXem
        FROM dbo.ChiTietXemPhong AS ctxp
        INNER JOIN dbo.Phong AS p ON p.MaPhong = ctxp.MaPhong
        WHERE ctxp.MaDangKy = lxp.MaDangKy AND ctxp.STTLich = lxp.STTLich
    ) AS phong
    WHERE pdk.MaKhachHang = @KhachHangId
    ORDER BY lxp.ThoiGianHen DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_KhachMoi_ChiTietLichXem AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_KhachMoi_ChiTietLichXem
    @KhachHangId VARCHAR(6),
    @MaDangKy VARCHAR(6),
    @STTLich INT
AS
BEGIN
    

    IF NOT EXISTS (
        SELECT 1
        FROM dbo.LichXemPhong AS lxp
        INNER JOIN dbo.PhieuDangKy AS pdk ON pdk.MaDangKy = lxp.MaDangKy
        WHERE lxp.MaDangKy = @MaDangKy
          AND lxp.STTLich = @STTLich
          AND pdk.MaKhachHang = @KhachHangId
    )
        RAISE EXCEPTION %;

    UPDATE dbo.LichXemPhong
    SET TrangThai = 'Đã xem'
    WHERE MaDangKy = @MaDangKy
      AND STTLich = @STTLich
      AND TrangThai IN ('Chờ xem', 'Yêu cầu đổi lịch', 'Yêu cầu hủy')
      AND ThoiGianHen <= CURRENT_TIMESTAMP;

    SELECT
        CONCAT(lxp.MaDangKy, '-', lxp.STTLich) AS id,
        lxp.MaDangKy AS maDangKy,
        lxp.STTLich AS sttLich,
        lxp.ThoiGianHen AS thoiGianHen,
        lxp.TrangThai AS trangThai,
        lxp.GhiChu AS ghiChu,
        pdk.MaNhanVienSale AS maNhanVienSale,
        ndSale.HoTen AS tenNhanVienSale,
        ndSale.SDT AS sdtNhanVienSale
    FROM dbo.LichXemPhong AS lxp
    INNER JOIN dbo.PhieuDangKy AS pdk ON pdk.MaDangKy = lxp.MaDangKy
    LEFT JOIN dbo.NguoiDung AS ndSale ON ndSale.MaNguoiDung = pdk.MaNhanVienSale
    WHERE lxp.MaDangKy = @MaDangKy
      AND lxp.STTLich = @STTLich
      AND pdk.MaKhachHang = @KhachHangId;

    SELECT
        p.MaPhong AS maPhong,
        p.TenPhong AS tenPhong,
        lp.TenLoaiPhong AS loaiPhong,
        p.GioiTinhChoPhep AS gioiTinhChoPhep,
        p.TinhTrang AS tinhTrang,
        lp.SucChuaToiDa AS sucChua,
        lp.GiaThueTheoGiuong AS giaThueTheoGiuong,
        lp.GiaThueNguyenPhong AS giaThueNguyenPhong,
        cn.TenChiNhanh AS tenChiNhanh,
        cn.TenChiNhanh AS chiNhanh,
        cn.DiaChi AS diaChi,
        img.UrlImg AS urlImg,
        NULL AS maGiuong
    FROM dbo.ChiTietXemPhong AS ctxp
    INNER JOIN dbo.Phong AS p ON p.MaPhong = ctxp.MaPhong
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
    OUTER APPLY (
        SELECT TOP (1) hap.UrlImg
        FROM dbo.HinhAnhPhong AS hap
        WHERE hap.MaPhong = p.MaPhong
        ORDER BY hap.STTAnh
    ) AS img
    WHERE ctxp.MaDangKy = @MaDangKy
      AND ctxp.STTLich = @STTLich
    ORDER BY p.TenPhong, p.MaPhong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_KhachMoi_TaoHoSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_KhachMoi_TaoHoSo
    @KhachHangId VARCHAR(6),
    @GioiTinh VARCHAR(10) = NULL,
    @SoNamInput INT = 0,
    @SoNuInput INT = 0,
    @KhuVucMongMuon VARCHAR(100) = NULL,
    @LoaiPhongYeuCau VARCHAR(200) = NULL,
    @MucGiaToiDa DECIMAL(15, 2) = NULL,
    @SoNguoiO INT,
    @NgayDuKienVaoO DATE,
    @ThoiHanThue INT = NULL,
    @PhongQuanTam VARCHAR(400) = NULL,
    @GhiChu TEXT = NULL,
    @HoTenKhach VARCHAR(100) = NULL,
    @NgaySinhKhach DATE = NULL,
    @GioiTinhKhach VARCHAR(5) = NULL,
    @SDTKhach VARCHAR(20) = NULL,
    @EmailKhach VARCHAR(100) = NULL,
    @QuocTichKhach VARCHAR(50) = NULL,
    @CCCDKhach VARCHAR(20) = NULL
AS
BEGIN
    
    

    IF NOT EXISTS (SELECT 1 FROM dbo.KhachHang WHERE MaKhachHang = @KhachHangId)
        RAISE EXCEPTION %;

    IF EXISTS (
        SELECT 1
        FROM dbo.HopDongThue
        WHERE MaKhachHang = @KhachHangId
          AND TrangThai NOT IN ('Hết hạn', 'Đã thanh lý')
    )
        RAISE EXCEPTION %;

    IF EXISTS (
        SELECT 1
        FROM dbo.PhieuDatCoc AS pdc
        WHERE pdc.MaKhachHang = @KhachHangId
          AND pdc.TrangThaiCoc <> 'Đã hủy'
          AND pdc.TrangThaiThanhToan <> 'Hết hạn'
          AND NOT EXISTS (
              SELECT 1
              FROM dbo.HopDongThue AS hd
              WHERE hd.MaPhieuCoc = pdc.MaPhieuDatCoc
                AND hd.TrangThai IN ('Hết hạn', 'Đã thanh lý')
          )
    )
        RAISE EXCEPTION %;

    IF EXISTS (
        SELECT 1
        FROM dbo.PhieuDangKy AS pdk
        WHERE pdk.MaKhachHang = @KhachHangId
          AND pdk.TrangThai <> 'Từ chối'
          AND NOT EXISTS (
              SELECT 1
              FROM dbo.PhieuDatCoc AS pdc
              INNER JOIN dbo.HopDongThue AS hd ON hd.MaPhieuCoc = pdc.MaPhieuDatCoc
              WHERE pdc.MaPhieuYeuCauDangKy = pdk.MaDangKy
                AND hd.TrangThai IN ('Hết hạn', 'Đã thanh lý')
          )
    )
        RAISE EXCEPTION %;

    SET @KhuVucMongMuon = NULLIF(TRIM(@KhuVucMongMuon)), '');
    SET @LoaiPhongYeuCau = NULLIF(TRIM(@LoaiPhongYeuCau)), '');

    IF @SoNguoiO < 1
       OR @NgayDuKienVaoO IS NULL
       OR @NgayDuKienVaoO <= CAST(CURRENT_TIMESTAMP AS DATE)
       OR @KhuVucMongMuon IS NULL
       OR @LoaiPhongYeuCau IS NULL
       OR @MucGiaToiDa IS NULL
       OR @MucGiaToiDa <= 0
       OR @ThoiHanThue IS NULL
       OR @ThoiHanThue < 1
        RAISE EXCEPTION %;

    -- Update thông tin cá nhân nếu có truyền vào
    BEGIN TRY
        BEGIN TRANSACTION;

    UPDATE dbo.NguoiDung
    SET HoTen = COALESCE(NULLIF(TRIM(@HoTenKhach)), ''), HoTen),
        NgaySinh = COALESCE(@NgaySinhKhach, NgaySinh),
        GioiTinh = COALESCE(NULLIF(TRIM(@GioiTinhKhach)), ''), GioiTinh),
        SDT = COALESCE(NULLIF(TRIM(@SDTKhach)), ''), SDT),
        Email = COALESCE(NULLIF(TRIM(@EmailKhach)), ''), Email)
    WHERE MaNguoiDung = @KhachHangId;

    IF EXISTS (SELECT 1 FROM dbo.KhachHang WHERE MaKhachHang = @KhachHangId)
    BEGIN
        UPDATE dbo.KhachHang
        SET QuocTich = COALESCE(NULLIF(TRIM(@QuocTichKhach)), ''), QuocTich),
            CCCD = COALESCE(NULLIF(TRIM(@CCCDKhach)), ''), CCCD)
        WHERE MaKhachHang = @KhachHangId;
    END
    ELSE
    BEGIN
        INSERT INTO dbo.KhachHang (MaKhachHang, QuocTich, CCCD)
        VALUES (@KhachHangId, NULLIF(TRIM(@QuocTichKhach)), ''), NULLIF(TRIM(@CCCDKhach)), ''));
    END

    DECLARE @SoThuTu INT;
    DECLARE @MaDangKy VARCHAR(6);
    DECLARE @YeuCauKhac TEXT;
    DECLARE @SoNam INT = COALESCE(@SoNamInput, 0);
    DECLARE @SoNu INT = COALESCE(@SoNuInput, 0);

    IF @GioiTinh IS NULL
    BEGIN
        SELECT @GioiTinh = nd.GioiTinh
        FROM dbo.NguoiDung AS nd
        WHERE nd.MaNguoiDung = @KhachHangId;
    END
    
    IF @GioiTinh = 'Nam' BEGIN
        SET @SoNam = @SoNguoiO;
        SET @SoNu = 0;
    END
    ELSE IF @GioiTinh = 'Nữ' BEGIN
        SET @SoNu = @SoNguoiO;
        SET @SoNam = 0;
    END
    ELSE IF @GioiTinh = 'Khác' BEGIN
        IF @SoNam = 0 AND @SoNu = 0 SET @SoNam = @SoNguoiO;
    END
    ELSE BEGIN
        SET @SoNam = @SoNguoiO;
        SET @SoNu = 0;
    END

    SET @YeuCauKhac = CONCAT(
        CASE WHEN NULLIF(@PhongQuanTam, '') IS NULL THEN '' ELSE CONCAT('Phòng quan tâm: ', @PhongQuanTam, '. ') END,
        COALESCE(@GhiChu, '')
    );

        SELECT @SoThuTu = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDangKy, 3, 4))), 0) + 1
        FROM dbo.PhieuDangKy 
        WHERE MaDangKy LIKE 'DK%';

        SET @MaDangKy = CONCAT('DK', RIGHT(CONCAT('0000', @SoThuTu), 4));

        INSERT INTO dbo.PhieuDangKy (
            MaDangKy, NgayDangKy, SoNguoiDuKienO, SoNam, SoNu,
            KhuVucMongMuon, MucGiaToiDa, ThoiGianDuKienVaoO,
            ThoiHanThue, YeuCauKhac, TrangThai, MaKhachHang
        )
        VALUES (
            @MaDangKy, CAST(CURRENT_TIMESTAMP AS DATE), @SoNguoiO, @SoNam, @SoNu,
            @KhuVucMongMuon, @MucGiaToiDa,
            @NgayDuKienVaoO, @ThoiHanThue, NULLIF(@YeuCauKhac, ''), 'Chờ tiếp nhận', @KhachHangId
        );

        IF @LoaiPhongYeuCau IS NOT NULL
        BEGIN
            INSERT INTO dbo.PDK_LoaiPhong (MaDangKy, MaLoaiPhong)
            SELECT @MaDangKy, lp.MaLoaiPhong
            FROM dbo.LoaiPhong lp
            WHERE lp.TenLoaiPhong IN (SELECT TRIM(value)) FROM STRING_SPLIT(@LoaiPhongYeuCau, ','));
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    EXEC dbo.SP_KhachMoi_DanhSachHoSo @KhachHangId = @KhachHangId;
END;

    EXEC('CREATE PROCEDURE dbo.SP_KhachMoi_YeuCauDieuChinhLich AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_KhachMoi_YeuCauDieuChinhLich
    @KhachHangId VARCHAR(6),
    @MaDangKy VARCHAR(6),
    @STTLich INT,
    @ThaoTac VARCHAR(20),
    @ThoiGianMoi VARCHAR(255) = NULL,
    @LyDo TEXT = NULL
AS
BEGIN
    

    IF NOT EXISTS (
        SELECT 1
        FROM dbo.LichXemPhong AS lxp
        INNER JOIN dbo.PhieuDangKy AS pdk ON pdk.MaDangKy = lxp.MaDangKy
        WHERE lxp.MaDangKy = @MaDangKy
          AND lxp.STTLich = @STTLich
          AND pdk.MaKhachHang = @KhachHangId
    )
        RAISE EXCEPTION %;

    -- Kiểm tra thời gian: Chỉ cho phép yêu cầu nếu còn >= 1 tiếng so với lịch hẹn
    DECLARE @ThoiGianHen TIMESTAMP;
    DECLARE @TrangThaiHienTai VARCHAR(30);
    SELECT
        @ThoiGianHen = ThoiGianHen,
        @TrangThaiHienTai = TrangThai
    FROM dbo.LichXemPhong 
    WHERE MaDangKy = @MaDangKy AND STTLich = @STTLich;

    IF @TrangThaiHienTai <> 'Chờ xem'
        RAISE EXCEPTION %;

    IF DATEDIFF(MINUTE, CURRENT_TIMESTAMP, @ThoiGianHen) < 120
        RAISE EXCEPTION %;

    DECLARE @GhiChuKhach TEXT = '';

    IF @ThaoTac = 'Hủy'
    BEGIN
        SET @GhiChuKhach = 'Thời gian đề xuất: ' + COALESCE(@ThoiGianMoi, 'Không có') + '. Lý do hủy: ' + COALESCE(@LyDo, 'Không có');
        UPDATE dbo.LichXemPhong
        SET TrangThai = 'Yêu cầu hủy',
            GhiChu = @GhiChuKhach
        WHERE MaDangKy = @MaDangKy AND STTLich = @STTLich;
    END
    ELSE IF @ThaoTac = 'Đổi lịch'
    BEGIN
        SET @GhiChuKhach = 'Thời gian đề xuất: ' + COALESCE(@ThoiGianMoi, 'Không có') + '. Lý do đổi: ' + COALESCE(@LyDo, 'Không có');
        UPDATE dbo.LichXemPhong
        SET TrangThai = 'Yêu cầu đổi lịch',
            GhiChu = @GhiChuKhach
        WHERE MaDangKy = @MaDangKy AND STTLich = @STTLich;
    END
    ELSE
        RAISE EXCEPTION %;

    EXEC dbo.SP_KhachMoi_DanhSachLichXem @KhachHangId = @KhachHangId;
END; THEN (SUBSTRING(p.MaPhong, 2, 1)::INT ELSE NULL END) IS NULL THEN NULL
            ELSE CASE WHEN (SUBSTRING(p.MaPhong, 2, 1) ~ '^[0-9]+)
        END AS tang,
        (
            SELECT COUNT(*)
            FROM dbo.Giuong AS g
            WHERE g.MaPhong = p.MaPhong
              AND g.TinhTrang = 'Trống'
        ) AS soChoTrong,
        (
            SELECT TOP (1) hap.UrlImg
            FROM dbo.HinhAnhPhong AS hap
            WHERE hap.MaPhong = p.MaPhong
            ORDER BY hap.STTAnh
        ) AS anhDai,
        (
            SELECT TOP (1) hap.UrlImg
            FROM dbo.HinhAnhPhong AS hap
            WHERE hap.MaPhong = p.MaPhong
            ORDER BY hap.STTAnh
        ) AS urlImg
    FROM dbo.Phong AS p
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
    WHERE p.MaPhong = @MaPhong;

    SELECT
        hap.STTAnh AS stt,
        hap.STTAnh AS sttAnh,
        hap.UrlImg AS urlAnh,
        hap.UrlImg AS urlImg,
        CONCAT('Ảnh phòng ', hap.STTAnh) AS moTa
    FROM dbo.HinhAnhPhong AS hap
    WHERE hap.MaPhong = @MaPhong
    ORDER BY hap.STTAnh;

    SELECT
        ts.MaTaiSan AS maTaiSan,
        ts.TenTaiSan AS tenTaiSan,
        ts.TenTaiSan AS tenTienNghi,
        ts.SoLuong AS soLuong,
        ts.DonGia AS donGia
    FROM dbo.TaiSan AS ts
    WHERE ts.MaPhong = @MaPhong
    ORDER BY ts.TenTaiSan;

    SELECT
        dv.MaDichVu AS maDichVu,
        dv.TenDichVu AS tenDichVu,
        dv.DonGia AS donGia,
        dv.DonViTinh AS donViTinh
    FROM dbo.DichVu AS dv
    ORDER BY dv.TenDichVu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_KhachMoi_DanhSachHoSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_KhachMoi_DanhSachHoSo
    @KhachHangId VARCHAR(6)
AS
BEGIN
    

    SELECT
        pdk.MaDangKy AS id,
        pdk.MaDangKy AS maDangKy,
        pdk.NgayDangKy AS ngayDangKy,
        pdk.KhuVucMongMuon AS khuVucMongMuon,
        (SELECT STRING_AGG(lp.TenLoaiPhong, ', ') 
         FROM dbo.PDK_LoaiPhong pdklp 
         JOIN dbo.LoaiPhong lp ON pdklp.MaLoaiPhong = lp.MaLoaiPhong 
         WHERE pdklp.MaDangKy = pdk.MaDangKy) AS loaiPhongYeuCau,
        pdk.MucGiaToiDa AS mucGia,
        pdk.SoNguoiDuKienO AS soNguoiO,
        pdk.SoNam AS soNam,
        pdk.SoNu AS soNu,
        pdk.ThoiGianDuKienVaoO AS ngayDuKienVaoO,
        pdk.ThoiHanThue AS thoiHanThue,
        pdk.YeuCauKhac AS ghiChu,
        pdk.TrangThai AS trangThai,
        lich.STTLich AS sttLich,
        lich.ThoiGianHen AS thoiGianHen,
        lich.TrangThai AS trangThaiLich
    FROM dbo.PhieuDangKy AS pdk
    OUTER APPLY (
        SELECT TOP (1) lxp.STTLich, lxp.ThoiGianHen, lxp.TrangThai
        FROM dbo.LichXemPhong AS lxp
        WHERE lxp.MaDangKy = pdk.MaDangKy
        ORDER BY lxp.STTLich DESC
    ) AS lich
    WHERE pdk.MaKhachHang = @KhachHangId
    ORDER BY pdk.NgayDangKy DESC, pdk.MaDangKy DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_KhachMoi_DanhSachLichXem AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_KhachMoi_DanhSachLichXem
    @KhachHangId VARCHAR(6)
AS
BEGIN
    

    UPDATE lxp
    SET lxp.TrangThai = 'Đã xem'
    FROM dbo.LichXemPhong AS lxp
    INNER JOIN dbo.PhieuDangKy AS pdk ON pdk.MaDangKy = lxp.MaDangKy
    WHERE pdk.MaKhachHang = @KhachHangId
      AND lxp.TrangThai IN ('Chờ xem', 'Yêu cầu đổi lịch', 'Yêu cầu hủy')
      AND lxp.ThoiGianHen <= CURRENT_TIMESTAMP;

    SELECT
        CONCAT(lxp.MaDangKy, '-', lxp.STTLich) AS id,
        lxp.MaDangKy AS maDangKy,
        lxp.STTLich AS sttLich,
        lxp.ThoiGianHen AS thoiGianHen,
        lxp.TrangThai AS trangThai,
        lxp.GhiChu AS ghiChu,
        pdk.MaNhanVienSale AS maNhanVienSale,
        ndSale.HoTen AS tenNhanVienSale,
        ndSale.SDT AS sdtNhanVienSale,
        phong.phongXem
    FROM dbo.LichXemPhong AS lxp
    INNER JOIN dbo.PhieuDangKy AS pdk ON pdk.MaDangKy = lxp.MaDangKy
    LEFT JOIN dbo.NguoiDung AS ndSale ON ndSale.MaNguoiDung = pdk.MaNhanVienSale
    OUTER APPLY (
        SELECT STRING_AGG(p.TenPhong, ', ') AS phongXem
        FROM dbo.ChiTietXemPhong AS ctxp
        INNER JOIN dbo.Phong AS p ON p.MaPhong = ctxp.MaPhong
        WHERE ctxp.MaDangKy = lxp.MaDangKy AND ctxp.STTLich = lxp.STTLich
    ) AS phong
    WHERE pdk.MaKhachHang = @KhachHangId
    ORDER BY lxp.ThoiGianHen DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_KhachMoi_ChiTietLichXem AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_KhachMoi_ChiTietLichXem
    @KhachHangId VARCHAR(6),
    @MaDangKy VARCHAR(6),
    @STTLich INT
AS
BEGIN
    

    IF NOT EXISTS (
        SELECT 1
        FROM dbo.LichXemPhong AS lxp
        INNER JOIN dbo.PhieuDangKy AS pdk ON pdk.MaDangKy = lxp.MaDangKy
        WHERE lxp.MaDangKy = @MaDangKy
          AND lxp.STTLich = @STTLich
          AND pdk.MaKhachHang = @KhachHangId
    )
        RAISE EXCEPTION %;

    UPDATE dbo.LichXemPhong
    SET TrangThai = 'Đã xem'
    WHERE MaDangKy = @MaDangKy
      AND STTLich = @STTLich
      AND TrangThai IN ('Chờ xem', 'Yêu cầu đổi lịch', 'Yêu cầu hủy')
      AND ThoiGianHen <= CURRENT_TIMESTAMP;

    SELECT
        CONCAT(lxp.MaDangKy, '-', lxp.STTLich) AS id,
        lxp.MaDangKy AS maDangKy,
        lxp.STTLich AS sttLich,
        lxp.ThoiGianHen AS thoiGianHen,
        lxp.TrangThai AS trangThai,
        lxp.GhiChu AS ghiChu,
        pdk.MaNhanVienSale AS maNhanVienSale,
        ndSale.HoTen AS tenNhanVienSale,
        ndSale.SDT AS sdtNhanVienSale
    FROM dbo.LichXemPhong AS lxp
    INNER JOIN dbo.PhieuDangKy AS pdk ON pdk.MaDangKy = lxp.MaDangKy
    LEFT JOIN dbo.NguoiDung AS ndSale ON ndSale.MaNguoiDung = pdk.MaNhanVienSale
    WHERE lxp.MaDangKy = @MaDangKy
      AND lxp.STTLich = @STTLich
      AND pdk.MaKhachHang = @KhachHangId;

    SELECT
        p.MaPhong AS maPhong,
        p.TenPhong AS tenPhong,
        lp.TenLoaiPhong AS loaiPhong,
        p.GioiTinhChoPhep AS gioiTinhChoPhep,
        p.TinhTrang AS tinhTrang,
        lp.SucChuaToiDa AS sucChua,
        lp.GiaThueTheoGiuong AS giaThueTheoGiuong,
        lp.GiaThueNguyenPhong AS giaThueNguyenPhong,
        cn.TenChiNhanh AS tenChiNhanh,
        cn.TenChiNhanh AS chiNhanh,
        cn.DiaChi AS diaChi,
        img.UrlImg AS urlImg,
        NULL AS maGiuong
    FROM dbo.ChiTietXemPhong AS ctxp
    INNER JOIN dbo.Phong AS p ON p.MaPhong = ctxp.MaPhong
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
    OUTER APPLY (
        SELECT TOP (1) hap.UrlImg
        FROM dbo.HinhAnhPhong AS hap
        WHERE hap.MaPhong = p.MaPhong
        ORDER BY hap.STTAnh
    ) AS img
    WHERE ctxp.MaDangKy = @MaDangKy
      AND ctxp.STTLich = @STTLich
    ORDER BY p.TenPhong, p.MaPhong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_KhachMoi_TaoHoSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_KhachMoi_TaoHoSo
    @KhachHangId VARCHAR(6),
    @GioiTinh VARCHAR(10) = NULL,
    @SoNamInput INT = 0,
    @SoNuInput INT = 0,
    @KhuVucMongMuon VARCHAR(100) = NULL,
    @LoaiPhongYeuCau VARCHAR(200) = NULL,
    @MucGiaToiDa DECIMAL(15, 2) = NULL,
    @SoNguoiO INT,
    @NgayDuKienVaoO DATE,
    @ThoiHanThue INT = NULL,
    @PhongQuanTam VARCHAR(400) = NULL,
    @GhiChu TEXT = NULL,
    @HoTenKhach VARCHAR(100) = NULL,
    @NgaySinhKhach DATE = NULL,
    @GioiTinhKhach VARCHAR(5) = NULL,
    @SDTKhach VARCHAR(20) = NULL,
    @EmailKhach VARCHAR(100) = NULL,
    @QuocTichKhach VARCHAR(50) = NULL,
    @CCCDKhach VARCHAR(20) = NULL
AS
BEGIN
    
    

    IF NOT EXISTS (SELECT 1 FROM dbo.KhachHang WHERE MaKhachHang = @KhachHangId)
        RAISE EXCEPTION %;

    IF EXISTS (
        SELECT 1
        FROM dbo.HopDongThue
        WHERE MaKhachHang = @KhachHangId
          AND TrangThai NOT IN ('Hết hạn', 'Đã thanh lý')
    )
        RAISE EXCEPTION %;

    IF EXISTS (
        SELECT 1
        FROM dbo.PhieuDatCoc AS pdc
        WHERE pdc.MaKhachHang = @KhachHangId
          AND pdc.TrangThaiCoc <> 'Đã hủy'
          AND pdc.TrangThaiThanhToan <> 'Hết hạn'
          AND NOT EXISTS (
              SELECT 1
              FROM dbo.HopDongThue AS hd
              WHERE hd.MaPhieuCoc = pdc.MaPhieuDatCoc
                AND hd.TrangThai IN ('Hết hạn', 'Đã thanh lý')
          )
    )
        RAISE EXCEPTION %;

    IF EXISTS (
        SELECT 1
        FROM dbo.PhieuDangKy AS pdk
        WHERE pdk.MaKhachHang = @KhachHangId
          AND pdk.TrangThai <> 'Từ chối'
          AND NOT EXISTS (
              SELECT 1
              FROM dbo.PhieuDatCoc AS pdc
              INNER JOIN dbo.HopDongThue AS hd ON hd.MaPhieuCoc = pdc.MaPhieuDatCoc
              WHERE pdc.MaPhieuYeuCauDangKy = pdk.MaDangKy
                AND hd.TrangThai IN ('Hết hạn', 'Đã thanh lý')
          )
    )
        RAISE EXCEPTION %;

    SET @KhuVucMongMuon = NULLIF(TRIM(@KhuVucMongMuon)), '');
    SET @LoaiPhongYeuCau = NULLIF(TRIM(@LoaiPhongYeuCau)), '');

    IF @SoNguoiO < 1
       OR @NgayDuKienVaoO IS NULL
       OR @NgayDuKienVaoO <= CAST(CURRENT_TIMESTAMP AS DATE)
       OR @KhuVucMongMuon IS NULL
       OR @LoaiPhongYeuCau IS NULL
       OR @MucGiaToiDa IS NULL
       OR @MucGiaToiDa <= 0
       OR @ThoiHanThue IS NULL
       OR @ThoiHanThue < 1
        RAISE EXCEPTION %;

    -- Update thông tin cá nhân nếu có truyền vào
    BEGIN TRY
        BEGIN TRANSACTION;

    UPDATE dbo.NguoiDung
    SET HoTen = COALESCE(NULLIF(TRIM(@HoTenKhach)), ''), HoTen),
        NgaySinh = COALESCE(@NgaySinhKhach, NgaySinh),
        GioiTinh = COALESCE(NULLIF(TRIM(@GioiTinhKhach)), ''), GioiTinh),
        SDT = COALESCE(NULLIF(TRIM(@SDTKhach)), ''), SDT),
        Email = COALESCE(NULLIF(TRIM(@EmailKhach)), ''), Email)
    WHERE MaNguoiDung = @KhachHangId;

    IF EXISTS (SELECT 1 FROM dbo.KhachHang WHERE MaKhachHang = @KhachHangId)
    BEGIN
        UPDATE dbo.KhachHang
        SET QuocTich = COALESCE(NULLIF(TRIM(@QuocTichKhach)), ''), QuocTich),
            CCCD = COALESCE(NULLIF(TRIM(@CCCDKhach)), ''), CCCD)
        WHERE MaKhachHang = @KhachHangId;
    END
    ELSE
    BEGIN
        INSERT INTO dbo.KhachHang (MaKhachHang, QuocTich, CCCD)
        VALUES (@KhachHangId, NULLIF(TRIM(@QuocTichKhach)), ''), NULLIF(TRIM(@CCCDKhach)), ''));
    END

    DECLARE @SoThuTu INT;
    DECLARE @MaDangKy VARCHAR(6);
    DECLARE @YeuCauKhac TEXT;
    DECLARE @SoNam INT = COALESCE(@SoNamInput, 0);
    DECLARE @SoNu INT = COALESCE(@SoNuInput, 0);

    IF @GioiTinh IS NULL
    BEGIN
        SELECT @GioiTinh = nd.GioiTinh
        FROM dbo.NguoiDung AS nd
        WHERE nd.MaNguoiDung = @KhachHangId;
    END
    
    IF @GioiTinh = 'Nam' BEGIN
        SET @SoNam = @SoNguoiO;
        SET @SoNu = 0;
    END
    ELSE IF @GioiTinh = 'Nữ' BEGIN
        SET @SoNu = @SoNguoiO;
        SET @SoNam = 0;
    END
    ELSE IF @GioiTinh = 'Khác' BEGIN
        IF @SoNam = 0 AND @SoNu = 0 SET @SoNam = @SoNguoiO;
    END
    ELSE BEGIN
        SET @SoNam = @SoNguoiO;
        SET @SoNu = 0;
    END

    SET @YeuCauKhac = CONCAT(
        CASE WHEN NULLIF(@PhongQuanTam, '') IS NULL THEN '' ELSE CONCAT('Phòng quan tâm: ', @PhongQuanTam, '. ') END,
        COALESCE(@GhiChu, '')
    );

        SELECT @SoThuTu = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDangKy, 3, 4))), 0) + 1
        FROM dbo.PhieuDangKy 
        WHERE MaDangKy LIKE 'DK%';

        SET @MaDangKy = CONCAT('DK', RIGHT(CONCAT('0000', @SoThuTu), 4));

        INSERT INTO dbo.PhieuDangKy (
            MaDangKy, NgayDangKy, SoNguoiDuKienO, SoNam, SoNu,
            KhuVucMongMuon, MucGiaToiDa, ThoiGianDuKienVaoO,
            ThoiHanThue, YeuCauKhac, TrangThai, MaKhachHang
        )
        VALUES (
            @MaDangKy, CAST(CURRENT_TIMESTAMP AS DATE), @SoNguoiO, @SoNam, @SoNu,
            @KhuVucMongMuon, @MucGiaToiDa,
            @NgayDuKienVaoO, @ThoiHanThue, NULLIF(@YeuCauKhac, ''), 'Chờ tiếp nhận', @KhachHangId
        );

        IF @LoaiPhongYeuCau IS NOT NULL
        BEGIN
            INSERT INTO dbo.PDK_LoaiPhong (MaDangKy, MaLoaiPhong)
            SELECT @MaDangKy, lp.MaLoaiPhong
            FROM dbo.LoaiPhong lp
            WHERE lp.TenLoaiPhong IN (SELECT TRIM(value)) FROM STRING_SPLIT(@LoaiPhongYeuCau, ','));
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    EXEC dbo.SP_KhachMoi_DanhSachHoSo @KhachHangId = @KhachHangId;
END;

    EXEC('CREATE PROCEDURE dbo.SP_KhachMoi_YeuCauDieuChinhLich AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_KhachMoi_YeuCauDieuChinhLich
