-- ============================================================
-- SP03 – SP_KiemTraDieuKienLapHopDong
-- Màn hình : Bước 2 – Kiểm tra điều kiện (checklist bên phải)
-- Mục đích : Kiểm tra phiếu cọc có đủ điều kiện lập hợp đồng.
--            Trả OUTPUT để BUS quyết định cho phép tiếp tục hay không.
-- Input    : @MaPhieuDatCoc
-- Output   : @HopLe BOOLEAN, @MaLoi INT, @ThongBao VARCHAR(500)
-- ============================================================
CREATE OR ALTER PROCEDURE dbo.SP_KiemTraDieuKienLapHopDong
    @MaPhieuDatCoc  VARCHAR(6),
    @HopLe          BOOLEAN             OUTPUT,
    @MaLoi          INT             OUTPUT,
    @ThongBao       VARCHAR(500)   OUTPUT
AS
BEGIN
    

    -- Khởi tạo output mặc định hợp lệ
    SET @HopLe    = 0;
    SET @MaLoi    = 0;
    SET @ThongBao = '';

    BEGIN TRY
        -- [1] Phiếu cọc tồn tại?
        IF NOT EXISTS (SELECT 1 FROM dbo.PhieuDatCoc WHERE MaPhieuDatCoc = @MaPhieuDatCoc)
        BEGIN
            SET @MaLoi    = -1;
            SET @ThongBao = 'Phiếu đặt cọc không tồn tại.';
            RETURN;
        END;

        DECLARE
            @TrangThaiCoc       VARCHAR(20),
            @TrangThaiThanhToan VARCHAR(20),
            @HinhThucThue       VARCHAR(20);

        SELECT
            @TrangThaiCoc       = TrangThaiCoc,
            @TrangThaiThanhToan = TrangThaiThanhToan,
            @HinhThucThue       = HinhThucThue
        FROM dbo.PhieuDatCoc
        WHERE MaPhieuDatCoc = @MaPhieuDatCoc;

        -- [2] Phiếu cọc còn hiệu lực?
        IF @TrangThaiCoc <> 'Hiệu lực' AND @TrangThaiCoc NOT LIKE 'Hi%u%'
        BEGIN
            SET @MaLoi    = -2;
            SET @ThongBao = 'Phiếu đặt cọc không còn hiệu lực (trạng thái: ' + @TrangThaiCoc + ').';
            RETURN;
        END;

        -- [3] Đã thanh toán?
        IF @TrangThaiThanhToan <> 'Đã TT' AND @TrangThaiThanhToan NOT LIKE '%TT%'
        BEGIN
            SET @MaLoi    = -3;
            SET @ThongBao = 'Phiếu đặt cọc chưa được thanh toán (trạng thái: ' + @TrangThaiThanhToan + ').';
            RETURN;
        END;

        -- [4] Chưa lập hợp đồng?
        IF EXISTS (SELECT 1 FROM dbo.HopDongThue WHERE MaPhieuCoc = @MaPhieuDatCoc)
        BEGIN
            SET @MaLoi    = -4;
            SET @ThongBao = 'Phiếu đặt cọc đã được lập hợp đồng.';
            RETURN;
        END;

        -- [5] Hồ sơ cư trú đã được quản lý duyệt?
        
            SET @ThongBao = 'Phiếu đặt cọc chưa có hồ sơ cư trú được quản lý duyệt. Vui lòng chờ duyệt cư trú trước khi lập hợp đồng.';
            RETURN;
        END;

        -- [6] Phòng/giường chưa bị hợp đồng hiệu lực khác chiếm
        IF @HinhThucThue = 'Nguyên phòng'
        BEGIN
            -- Kiểm tra theo phòng
            IF EXISTS (
                SELECT 1
                FROM        dbo.ChiTietDatCoc   ctdc
                JOIN        dbo.HopDongThue     hdt  ON hdt.MaPhieuCoc = ctdc.MaPhieuDatCoc
                                                     AND hdt.TrangThai   = 'Hiệu lực'
                JOIN        dbo.ChiTietDatCoc   ctdc2 ON ctdc2.MaPhieuDatCoc <> @MaPhieuDatCoc
                                                      AND ctdc2.MaPhong       = ctdc.MaPhong
                                                      AND ctdc2.MaGiuong      IS NULL
                JOIN        dbo.HopDongThue     hdt2 ON hdt2.MaPhieuCoc = ctdc2.MaPhieuDatCoc
                                                     AND hdt2.TrangThai   = 'Hiệu lực'
                WHERE ctdc.MaPhieuDatCoc = @MaPhieuDatCoc
                  AND ctdc.MaGiuong IS NULL
            )
            BEGIN
                SET @MaLoi    = -5;
                SET @ThongBao = 'Phòng đã có hợp đồng hiệu lực khác.';
                RETURN;
            END;
        END
        ELSE -- Ghép giường
        BEGIN
            IF EXISTS (
                SELECT 1
                FROM        dbo.ChiTietDatCoc   ctdc
                JOIN        dbo.ChiTietDatCoc   ctdc2 ON ctdc2.MaPhieuDatCoc <> @MaPhieuDatCoc
                                                      AND ctdc2.MaPhong       = ctdc.MaPhong
                                                      AND ctdc2.MaGiuong      = ctdc.MaGiuong
                JOIN        dbo.HopDongThue     hdt2 ON hdt2.MaPhieuCoc = ctdc2.MaPhieuDatCoc
                                                     AND hdt2.TrangThai   = 'Hiệu lực'
                WHERE ctdc.MaPhieuDatCoc = @MaPhieuDatCoc
                  AND ctdc.MaGiuong IS NOT NULL
            )
            BEGIN
                SET @MaLoi    = -5;
                SET @ThongBao = 'Giường đã có hợp đồng hiệu lực khác.';
                RETURN;
            END;
        END;

        -- Tất cả điều kiện đều hợp lệ
        SET @HopLe    = 1;
        SET @MaLoi    = 0;
        SET @ThongBao = 'Phiếu đặt cọc hợp lệ. Có thể tiến hành lập hợp đồng.';

    END TRY
    BEGIN CATCH
        SET @HopLe    = 0;
        SET @MaLoi    = -99;
        SET @ThongBao = 'Lỗi hệ thống: ' + ERROR_MESSAGE();
    END CATCH;
END;
