    EXEC('CREATE PROCEDURE dbo.SP_Admin_GhiNhatKy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_GhiNhatKy
    @AdminId     VARCHAR(6)     = NULL,
    @VaiTro      VARCHAR(50)   = NULL,
    @ChucNang    VARCHAR(100)  = NULL,
    @HanhDong    VARCHAR(100),
    @DoiTuong    VARCHAR(100)  = NULL,
    @MaDoiTuong  VARCHAR(50)   = NULL,
    @NoiDung     TEXT  = NULL,
    @DuLieuTruoc TEXT  = NULL,
    @DuLieuSau   TEXT  = NULL
AS
BEGIN
    

    SET @AdminId = NULLIF(TRIM(@AdminId)), '');
    SET @VaiTro = NULLIF(TRIM(@VaiTro)), '');
    SET @ChucNang = NULLIF(TRIM(@ChucNang)), '');

    IF @VaiTro IS NULL AND @AdminId IS NOT NULL
    BEGIN
        SELECT @VaiTro = CONCAT(nd.LoaiNguoiDung, CASE WHEN nv.ChucVu IS NULL THEN '' ELSE ' - ' + nv.ChucVu END)
        FROM dbo.NguoiDung AS nd
        LEFT JOIN dbo.NhanVien AS nv ON nv.MaNhanVien = nd.MaNguoiDung
        WHERE nd.MaNguoiDung = @AdminId;
    END;

    IF @ChucNang IS NULL
        SET @ChucNang = @DoiTuong;

    INSERT INTO dbo.NhatKyHeThong (
        MaNguoiDung, VaiTro, ChucNang, HanhDong, DoiTuong, MaDoiTuong, NoiDung, DuLieuTruoc, DuLieuSau
    )
    VALUES (
        @AdminId, @VaiTro, @ChucNang, @HanhDong, @DoiTuong, @MaDoiTuong, @NoiDung, @DuLieuTruoc, @DuLieuSau
    );
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_TaoTaiKhoanNhanVien AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_TaoTaiKhoanNhanVien
    @TenDangNhap VARCHAR(50),
    @MatKhau     VARCHAR(255),
    @HoTen       VARCHAR(100),
    @NgaySinh    DATE          = NULL,
    @GioiTinh    VARCHAR(5)   = NULL,
    @SDT         VARCHAR(20)   = NULL,
    @Email       VARCHAR(100)  = NULL,
    @DiaChi      VARCHAR(255) = NULL,
    @MaChiNhanh  VARCHAR(6),
    @NgayVaoLam  DATE          = NULL,
    @ChucVu      VARCHAR(20),
    @AdminId     VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @TenDangNhap = NULLIF(TRIM(@TenDangNhap)), '');
    SET @MatKhau     = NULLIF(TRIM(@MatKhau)), '');
    SET @HoTen       = NULLIF(TRIM(@HoTen)), '');
    SET @GioiTinh    = NULLIF(TRIM(@GioiTinh)), '');
    SET @SDT         = NULLIF(TRIM(@SDT)), '');
    SET @Email       = NULLIF(TRIM(@Email)), '');
    SET @DiaChi      = NULLIF(TRIM(@DiaChi)), '');
    SET @MaChiNhanh  = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @ChucVu      = NULLIF(TRIM(@ChucVu)), '');

    IF @TenDangNhap IS NULL OR @MatKhau IS NULL OR @HoTen IS NULL
       OR @MaChiNhanh IS NULL OR @ChucVu IS NULL
        THROW 51001, 'Vui lòng nhập tên đăng nhập, mật khẩu, họ tên, chi nhánh và chức vụ.', 1;

    IF @GioiTinh IS NOT NULL AND @GioiTinh NOT IN ('Nam', 'Nữ')
        RAISE EXCEPTION %;

    IF @ChucVu NOT IN ('Sale', 'Quản lý', 'Kế toán')
        RAISE EXCEPTION %;

    IF NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
        RAISE EXCEPTION %;

    IF EXISTS (SELECT 1 FROM dbo.TaiKhoan WHERE TenDangNhap = @TenDangNhap)
        RAISE EXCEPTION %;

    IF @SDT IS NOT NULL AND EXISTS (SELECT 1 FROM dbo.NguoiDung WHERE SDT = @SDT)
        RAISE EXCEPTION %;

    IF @Email IS NOT NULL AND EXISTS (SELECT 1 FROM dbo.NguoiDung WHERE Email = @Email)
        RAISE EXCEPTION %;

    DECLARE @SoThuTu INT;
    DECLARE @MaNhanVien VARCHAR(6);

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT @SoThuTu = COALESCE(MAX(CASE WHEN (SUBSTRING(MaNguoiDung, 3, 4) ~ '^[0-9]+)), 0) + 1
        FROM dbo.NguoiDung 
        WHERE MaNguoiDung LIKE 'NV[0-9][0-9][0-9][0-9]';

        IF @SoThuTu > 9999
            RAISE EXCEPTION %;

        SET @MaNhanVien = CONCAT('NV', RIGHT(CONCAT('0000', @SoThuTu), 4));

        INSERT INTO dbo.NguoiDung (
            MaNguoiDung, HoTen, NgaySinh, GioiTinh, SDT, Email, DiaChi, UrlAvt, LoaiNguoiDung
        )
        VALUES (
            @MaNhanVien, @HoTen, @NgaySinh, @GioiTinh, @SDT, @Email, @DiaChi, NULL, 'NhanVien'
        );

        INSERT INTO dbo.NhanVien (MaNhanVien, MaChiNhanh, NgayVaoLam, ChucVu)
        VALUES (@MaNhanVien, @MaChiNhanh, COALESCE(@NgayVaoLam, CAST(CURRENT_TIMESTAMP AS DATE)), @ChucVu);

        INSERT INTO dbo.TaiKhoan (TenDangNhap, MatKhau, TrangThai, MaNguoiDung)
        VALUES (
            @TenDangNhap,
            CONVERT(VARCHAR(64), HASHBYTES('SHA2_256', @MatKhau), 2),
            'Hoạt động',
            @MaNhanVien
        );

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo tài khoản nhân viên',
            @DoiTuong = 'NhanVien',
            @MaDoiTuong = @MaNhanVien,
            @NoiDung = 'Tạo nhân viên và tài khoản đăng nhập mới.';

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        nv.MaNhanVien     AS maNhanVien,
        tk.TenDangNhap    AS tenDangNhap,
        nd.HoTen          AS hoTen,
        nd.NgaySinh       AS ngaySinh,
        nd.GioiTinh       AS gioiTinh,
        nd.SDT            AS soDienThoai,
        nd.Email          AS email,
        nd.DiaChi         AS diaChi,
        nv.ChucVu         AS chucVu,
        nv.NgayVaoLam     AS ngayVaoLam,
        nv.MaChiNhanh     AS maChiNhanh,
        cn.TenChiNhanh    AS tenChiNhanh,
        tk.TrangThai      AS trangThaiTaiKhoan
    FROM dbo.NhanVien AS nv
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nv.MaNhanVien
    INNER JOIN dbo.TaiKhoan AS tk ON tk.MaNguoiDung = nv.MaNhanVien
    INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = nv.MaChiNhanh
    WHERE nv.MaNhanVien = @MaNhanVien;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_KhoaMoTaiKhoan AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_KhoaMoTaiKhoan
    @TenDangNhap VARCHAR(50)  = NULL,
    @MaNhanVien  VARCHAR(6)   = NULL,
    @TrangThai   VARCHAR(20),
    @AdminId     VARCHAR(6)   = NULL
AS
BEGIN
    
    

    SET @TenDangNhap = NULLIF(TRIM(@TenDangNhap)), '');
    SET @MaNhanVien  = NULLIF(TRIM(@MaNhanVien)), '');
    SET @TrangThai   = NULLIF(TRIM(@TrangThai)), '');

    IF @TenDangNhap IS NULL AND @MaNhanVien IS NULL
        RAISE EXCEPTION %;

    IF @TrangThai NOT IN ('Hoạt động', 'Vô hiệu hóa')
        RAISE EXCEPTION %;

    DECLARE @TenDangNhapCanSua VARCHAR(50);
    DECLARE @MaNguoiDung VARCHAR(6);
    DECLARE @DuLieuTruoc TEXT;

    SELECT TOP (1)
        @TenDangNhapCanSua = tk.TenDangNhap,
        @MaNguoiDung = tk.MaNguoiDung
    FROM dbo.TaiKhoan AS tk
    INNER JOIN dbo.NhanVien AS nv ON nv.MaNhanVien = tk.MaNguoiDung
    WHERE (@TenDangNhap IS NOT NULL AND tk.TenDangNhap = @TenDangNhap)
       OR (@MaNhanVien IS NOT NULL AND tk.MaNguoiDung = @MaNhanVien);

    IF @TenDangNhapCanSua IS NULL
        RAISE EXCEPTION %;

    SELECT @DuLieuTruoc = (
        SELECT TenDangNhap, TrangThai, MaNguoiDung
        FROM dbo.TaiKhoan
        WHERE TenDangNhap = @TenDangNhapCanSua
        FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    UPDATE dbo.TaiKhoan
    SET TrangThai = @TrangThai
    WHERE TenDangNhap = @TenDangNhapCanSua;

    EXEC dbo.SP_Admin_GhiNhatKy
        @AdminId = @AdminId,
        @HanhDong = 'Khóa/mở tài khoản',
        @DoiTuong = 'TaiKhoan',
        @MaDoiTuong = @TenDangNhapCanSua,
        @NoiDung = @TrangThai,
        @DuLieuTruoc = @DuLieuTruoc,
        @DuLieuSau = NULL;

    SELECT
        tk.TenDangNhap AS tenDangNhap,
        tk.MaNguoiDung AS maNhanVien,
        nd.HoTen       AS hoTen,
        tk.TrangThai   AS trangThaiTaiKhoan
    FROM dbo.TaiKhoan AS tk
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = tk.MaNguoiDung
    WHERE tk.TenDangNhap = @TenDangNhapCanSua;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_GanChucVuNhanVien AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_GanChucVuNhanVien
    @MaNhanVien VARCHAR(6),
    @ChucVu     VARCHAR(20),
    @AdminId    VARCHAR(6) = NULL
AS
BEGIN
    
    

    SET @MaNhanVien = NULLIF(TRIM(@MaNhanVien)), '');
    SET @ChucVu = NULLIF(TRIM(@ChucVu)), '');

    IF @MaNhanVien IS NULL
        RAISE EXCEPTION %;

    IF @ChucVu NOT IN ('Sale', 'Quản lý', 'Kế toán')
        RAISE EXCEPTION %;

    IF NOT EXISTS (SELECT 1 FROM dbo.NhanVien WHERE MaNhanVien = @MaNhanVien)
        RAISE EXCEPTION %;

    DECLARE @DuLieuTruoc TEXT;
    SELECT @DuLieuTruoc = (
        SELECT MaNhanVien, ChucVu
        FROM dbo.NhanVien
        WHERE MaNhanVien = @MaNhanVien
        FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    UPDATE dbo.NhanVien
    SET ChucVu = @ChucVu
    WHERE MaNhanVien = @MaNhanVien;

    EXEC dbo.SP_Admin_GhiNhatKy
        @AdminId = @AdminId,
        @HanhDong = 'Gắn chức vụ nhân viên',
        @DoiTuong = 'NhanVien',
        @MaDoiTuong = @MaNhanVien,
        @NoiDung = @ChucVu,
        @DuLieuTruoc = @DuLieuTruoc;

    SELECT
        nv.MaNhanVien AS maNhanVien,
        nd.HoTen      AS hoTen,
        nv.ChucVu     AS chucVu,
        nv.MaChiNhanh AS maChiNhanh
    FROM dbo.NhanVien AS nv
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nv.MaNhanVien
    WHERE nv.MaNhanVien = @MaNhanVien;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CapNhatThongTinNhanVien AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CapNhatThongTinNhanVien
    @MaNhanVien        VARCHAR(6),
    @HoTen             VARCHAR(100) = NULL,
    @NgaySinh          DATE          = NULL,
    @GioiTinh          VARCHAR(5)   = NULL,
    @SDT               VARCHAR(20)   = NULL,
    @Email             VARCHAR(100)  = NULL,
    @DiaChi            VARCHAR(255) = NULL,
    @MaChiNhanh        VARCHAR(6)    = NULL,
    @NgayVaoLam        DATE          = NULL,
    @TrangThaiTaiKhoan VARCHAR(20)  = NULL,
    @AdminId           VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @MaNhanVien        = NULLIF(TRIM(@MaNhanVien)), '');
    SET @HoTen             = NULLIF(TRIM(@HoTen)), '');
    SET @GioiTinh          = NULLIF(TRIM(@GioiTinh)), '');
    SET @SDT               = NULLIF(TRIM(@SDT)), '');
    SET @Email             = NULLIF(TRIM(@Email)), '');
    SET @DiaChi            = NULLIF(TRIM(@DiaChi)), '');
    SET @MaChiNhanh        = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @TrangThaiTaiKhoan = NULLIF(TRIM(@TrangThaiTaiKhoan)), '');

    IF @MaNhanVien IS NULL
        RAISE EXCEPTION %;

    IF NOT EXISTS (SELECT 1 FROM dbo.NhanVien WHERE MaNhanVien = @MaNhanVien)
        RAISE EXCEPTION %;

    IF @GioiTinh IS NOT NULL AND @GioiTinh NOT IN ('Nam', 'Nữ')
        RAISE EXCEPTION %;

    IF @TrangThaiTaiKhoan IS NOT NULL AND @TrangThaiTaiKhoan NOT IN ('Hoạt động', 'Vô hiệu hóa')
        RAISE EXCEPTION %;

    IF @MaChiNhanh IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
        RAISE EXCEPTION %;

    IF @SDT IS NOT NULL AND EXISTS (
        SELECT 1 FROM dbo.NguoiDung WHERE SDT = @SDT AND MaNguoiDung <> @MaNhanVien
    )
        RAISE EXCEPTION %;

    IF @Email IS NOT NULL AND EXISTS (
        SELECT 1 FROM dbo.NguoiDung WHERE Email = @Email AND MaNguoiDung <> @MaNhanVien
    )
        RAISE EXCEPTION %;

    DECLARE @DuLieuTruoc TEXT;
    SELECT @DuLieuTruoc = (
        SELECT nd.MaNguoiDung, nd.HoTen, nd.NgaySinh, nd.GioiTinh, nd.SDT, nd.Email, nd.DiaChi,
               nv.MaChiNhanh, nv.NgayVaoLam, nv.ChucVu, tk.TrangThai AS TrangThaiTaiKhoan
        FROM dbo.NhanVien AS nv
        INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nv.MaNhanVien
        LEFT JOIN dbo.TaiKhoan AS tk ON tk.MaNguoiDung = nv.MaNhanVien
        WHERE nv.MaNhanVien = @MaNhanVien
        FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE dbo.NguoiDung
        SET HoTen = COALESCE(@HoTen, HoTen),
            NgaySinh = COALESCE(@NgaySinh, NgaySinh),
            GioiTinh = COALESCE(@GioiTinh, GioiTinh),
            SDT = COALESCE(@SDT, SDT),
            Email = COALESCE(@Email, Email),
            DiaChi = COALESCE(@DiaChi, DiaChi)
        WHERE MaNguoiDung = @MaNhanVien;

        UPDATE dbo.NhanVien
        SET MaChiNhanh = COALESCE(@MaChiNhanh, MaChiNhanh),
            NgayVaoLam = COALESCE(@NgayVaoLam, NgayVaoLam)
        WHERE MaNhanVien = @MaNhanVien;

        IF @TrangThaiTaiKhoan IS NOT NULL
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM dbo.TaiKhoan WHERE MaNguoiDung = @MaNhanVien)
                RAISE EXCEPTION %;

            UPDATE dbo.TaiKhoan
            SET TrangThai = @TrangThaiTaiKhoan
            WHERE MaNguoiDung = @MaNhanVien;
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật thông tin nhân viên',
            @DoiTuong = 'NhanVien',
            @MaDoiTuong = @MaNhanVien,
            @NoiDung = 'Cập nhật hồ sơ/chuyển chi nhánh/trạng thái làm việc.',
            @DuLieuTruoc = @DuLieuTruoc;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        nv.MaNhanVien     AS maNhanVien,
        nd.HoTen          AS hoTen,
        nd.NgaySinh       AS ngaySinh,
        nd.GioiTinh       AS gioiTinh,
        nd.SDT            AS soDienThoai,
        nd.Email          AS email,
        nd.DiaChi         AS diaChi,
        nv.ChucVu         AS chucVu,
        nv.NgayVaoLam     AS ngayVaoLam,
        nv.MaChiNhanh     AS maChiNhanh,
        cn.TenChiNhanh    AS tenChiNhanh,
        tk.TrangThai      AS trangThaiTaiKhoan
    FROM dbo.NhanVien AS nv
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nv.MaNhanVien
    INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = nv.MaChiNhanh
    LEFT JOIN dbo.TaiKhoan AS tk ON tk.MaNguoiDung = nv.MaNhanVien
    WHERE nv.MaNhanVien = @MaNhanVien;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_DanhSachNhanVien AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_DanhSachNhanVien
    @MaNhanVien        VARCHAR(6)    = NULL,
    @MaChiNhanh        VARCHAR(6)    = NULL,
    @ChucVu            VARCHAR(20)  = NULL,
    @TrangThaiTaiKhoan VARCHAR(20)  = NULL,
    @TuKhoa            VARCHAR(100) = NULL
AS
BEGIN
    

    SET @MaNhanVien = NULLIF(TRIM(@MaNhanVien)), '');
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @ChucVu = NULLIF(TRIM(@ChucVu)), '');
    SET @TrangThaiTaiKhoan = NULLIF(TRIM(@TrangThaiTaiKhoan)), '');
    SET @TuKhoa = NULLIF(TRIM(@TuKhoa)), '');

    SELECT
        nv.MaNhanVien     AS maNhanVien,
        tk.TenDangNhap    AS tenDangNhap,
        nd.HoTen          AS hoTen,
        nd.NgaySinh       AS ngaySinh,
        nd.GioiTinh       AS gioiTinh,
        nd.SDT            AS soDienThoai,
        nd.Email          AS email,
        nd.DiaChi         AS diaChi,
        nv.ChucVu         AS chucVu,
        nv.NgayVaoLam     AS ngayVaoLam,
        nv.MaChiNhanh     AS maChiNhanh,
        cn.TenChiNhanh    AS tenChiNhanh,
        tk.TrangThai      AS trangThaiTaiKhoan
    FROM dbo.NhanVien AS nv
    INNER JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nv.MaNhanVien
    INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = nv.MaChiNhanh
    LEFT JOIN dbo.TaiKhoan AS tk ON tk.MaNguoiDung = nv.MaNhanVien
    WHERE (@MaNhanVien IS NULL OR nv.MaNhanVien = @MaNhanVien)
      AND (@MaChiNhanh IS NULL OR nv.MaChiNhanh = @MaChiNhanh)
      AND (@ChucVu IS NULL OR nv.ChucVu = @ChucVu)
      AND (@TrangThaiTaiKhoan IS NULL OR tk.TrangThai = @TrangThaiTaiKhoan)
      AND (
          @TuKhoa IS NULL
          OR nd.HoTen LIKE '%' + @TuKhoa + '%'
          OR nv.MaNhanVien LIKE '%' + CONVERT(VARCHAR(100), @TuKhoa) + '%'
          OR tk.TenDangNhap LIKE '%' + CONVERT(VARCHAR(100), @TuKhoa) + '%'
          OR nd.SDT LIKE '%' + CONVERT(VARCHAR(100), @TuKhoa) + '%'
          OR nd.Email LIKE '%' + CONVERT(VARCHAR(100), @TuKhoa) + '%'
      )
    ORDER BY nv.MaNhanVien;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyChiNhanh AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyChiNhanh
    @ThaoTac     VARCHAR(20)  = 'DANH_SACH',
    @MaChiNhanh  VARCHAR(6)    = NULL,
    @TenChiNhanh VARCHAR(100) = NULL,
    @DiaChi      VARCHAR(255) = NULL,
    @SDT         VARCHAR(20)   = NULL,
    @Email       VARCHAR(100)  = NULL,
    @TrangThai   VARCHAR(20)  = NULL,
    @AdminId     VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @TenChiNhanh = NULLIF(TRIM(@TenChiNhanh)), '');
    SET @DiaChi = NULLIF(TRIM(@DiaChi)), '');
    SET @SDT = NULLIF(TRIM(@SDT)), '');
    SET @Email = NULLIF(TRIM(@Email)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');

    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            cn.MaChiNhanh AS maChiNhanh,
            cn.TenChiNhanh AS tenChiNhanh,
            cn.DiaChi AS diaChi,
            cn.SDT AS soDienThoai,
            cn.Email AS email,
            cn.TrangThai AS trangThai,
            COUNT(DISTINCT nv.MaNhanVien) AS soNhanVien,
            COUNT(DISTINCT p.MaPhong) AS soPhong
        FROM dbo.ChiNhanh AS cn
        LEFT JOIN dbo.NhanVien AS nv ON nv.MaChiNhanh = cn.MaChiNhanh
        LEFT JOIN dbo.Phong AS p ON p.MaChiNhanh = cn.MaChiNhanh
        WHERE (@MaChiNhanh IS NULL OR cn.MaChiNhanh = @MaChiNhanh)
          AND (@TrangThai IS NULL OR cn.TrangThai = @TrangThai)
        GROUP BY cn.MaChiNhanh, cn.TenChiNhanh, cn.DiaChi, cn.SDT, cn.Email, cn.TrangThai
        ORDER BY cn.MaChiNhanh;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'DOI_TRANG_THAI', 'XOA')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hoạt động', 'Ngừng hoạt động')
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF @TenChiNhanh IS NULL
            RAISE EXCEPTION %;

        DECLARE @SoChiNhanh INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaChiNhanh IS NULL
            BEGIN
                SELECT @SoChiNhanh = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaChiNhanh, 3, 4))), 0) + 1
                FROM dbo.ChiNhanh 
                WHERE MaChiNhanh LIKE 'CN[0-9][0-9][0-9][0-9]';

                IF @SoChiNhanh > 9999
                    RAISE EXCEPTION %;

                SET @MaChiNhanh = CONCAT('C', RIGHT(CONCAT('0000', @SoChiNhanh), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
                RAISE EXCEPTION %;

            INSERT INTO dbo.ChiNhanh (MaChiNhanh, TenChiNhanh, DiaChi, SDT, Email, TrangThai)
            VALUES (@MaChiNhanh, @TenChiNhanh, @DiaChi, @SDT, @Email, COALESCE(@TrangThai, 'Hoạt động'));

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo chi nhánh',
                @DoiTuong = 'ChiNhanh',
                @MaDoiTuong = @MaChiNhanh,
                @NoiDung = @TenChiNhanh;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE
    BEGIN
        IF @MaChiNhanh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
            RAISE EXCEPTION %;

        IF @ThaoTac = 'DOI_TRANG_THAI' AND @TrangThai IS NULL
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocChiNhanh TEXT;
        SELECT @DuLieuTruocChiNhanh = (
            SELECT * FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        IF @ThaoTac = 'XOA'
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.NhanVien WHERE MaChiNhanh = @MaChiNhanh)
               OR EXISTS (SELECT 1 FROM dbo.Phong WHERE MaChiNhanh = @MaChiNhanh)
                RAISE EXCEPTION %;

            DELETE FROM dbo.ChiNhanh
            WHERE MaChiNhanh = @MaChiNhanh;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa chi nhánh',
                @DoiTuong = 'ChiNhanh',
                @MaDoiTuong = @MaChiNhanh,
                @DuLieuTruoc = @DuLieuTruocChiNhanh;

            SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaChiNhanh AS maChiNhanh;
            RETURN;
        END;

        UPDATE dbo.ChiNhanh
        SET TenChiNhanh = CASE WHEN @ThaoTac = 'CAP_NHAT' THEN COALESCE(@TenChiNhanh, TenChiNhanh) ELSE TenChiNhanh END,
            DiaChi = CASE WHEN @ThaoTac = 'CAP_NHAT' THEN COALESCE(@DiaChi, DiaChi) ELSE DiaChi END,
            SDT = CASE WHEN @ThaoTac = 'CAP_NHAT' THEN COALESCE(@SDT, SDT) ELSE SDT END,
            Email = CASE WHEN @ThaoTac = 'CAP_NHAT' THEN COALESCE(@Email, Email) ELSE Email END,
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaChiNhanh = @MaChiNhanh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật chi nhánh',
            @DoiTuong = 'ChiNhanh',
            @MaDoiTuong = @MaChiNhanh,
            @NoiDung = @ThaoTac,
            @DuLieuTruoc = @DuLieuTruocChiNhanh;
    END;

    EXEC dbo.SP_Admin_QuanLyChiNhanh @ThaoTac = 'DANH_SACH', @MaChiNhanh = @MaChiNhanh;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyLoaiPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyLoaiPhong
    @ThaoTac             VARCHAR(20)  = 'DANH_SACH',
    @MaLoaiPhong         VARCHAR(6)    = NULL,
    @TenLoaiPhong        VARCHAR(100) = NULL,
    @SucChuaToiDa        INT           = NULL,
    @MoTa                TEXT = NULL,
    @GiaThueTheoGiuong   DECIMAL(15,2) = NULL,
    @GiaThueNguyenPhong  DECIMAL(15,2) = NULL,
    @AdminId             VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaLoaiPhong = NULLIF(TRIM(@MaLoaiPhong)), '');
    SET @TenLoaiPhong = NULLIF(TRIM(@TenLoaiPhong)), '');
    SET @MoTa = NULLIF(TRIM(@MoTa)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            lp.MaLoaiPhong AS maLoaiPhong,
            lp.TenLoaiPhong AS tenLoaiPhong,
            lp.SucChuaToiDa AS sucChuaToiDa,
            lp.MoTa AS moTa,
            lp.GiaThueTheoGiuong AS giaThueTheoGiuong,
            lp.GiaThueNguyenPhong AS giaThueNguyenPhong,
            COUNT(p.MaPhong) AS soPhong
        FROM dbo.LoaiPhong AS lp
        LEFT JOIN dbo.Phong AS p ON p.MaLoaiPhong = lp.MaLoaiPhong
        WHERE (@MaLoaiPhong IS NULL OR lp.MaLoaiPhong = @MaLoaiPhong)
        GROUP BY lp.MaLoaiPhong, lp.TenLoaiPhong, lp.SucChuaToiDa, lp.MoTa, lp.GiaThueTheoGiuong, lp.GiaThueNguyenPhong
        ORDER BY lp.MaLoaiPhong;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenLoaiPhong IS NULL OR @SucChuaToiDa IS NULL)
            RAISE EXCEPTION %;

        IF @SucChuaToiDa IS NOT NULL AND @SucChuaToiDa < 1
            RAISE EXCEPTION %;

        IF @GiaThueTheoGiuong IS NOT NULL AND @GiaThueTheoGiuong < 0
            RAISE EXCEPTION %;

        IF @GiaThueNguyenPhong IS NOT NULL AND @GiaThueNguyenPhong < 0
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoLoaiPhong INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaLoaiPhong IS NULL
            BEGIN
                SELECT @SoLoaiPhong = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaLoaiPhong, 3, 4))), 0) + 1
                FROM dbo.LoaiPhong 
                WHERE MaLoaiPhong LIKE 'LP[0-9][0-9][0-9][0-9]';

                IF @SoLoaiPhong > 9999
                    RAISE EXCEPTION %;

                SET @MaLoaiPhong = CONCAT('LP', RIGHT(CONCAT('0000', @SoLoaiPhong), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
                RAISE EXCEPTION %;

            INSERT INTO dbo.LoaiPhong (
                MaLoaiPhong, TenLoaiPhong, SucChuaToiDa, MoTa, GiaThueTheoGiuong, GiaThueNguyenPhong
            )
            VALUES (
                @MaLoaiPhong, @TenLoaiPhong, @SucChuaToiDa, @MoTa, @GiaThueTheoGiuong, @GiaThueNguyenPhong
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo loại phòng',
                @DoiTuong = 'LoaiPhong',
                @MaDoiTuong = @MaLoaiPhong,
                @NoiDung = @TenLoaiPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaLoaiPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocLoaiPhong TEXT;
        SELECT @DuLieuTruocLoaiPhong = (
            SELECT * FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        IF @SucChuaToiDa IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.Phong AS p
            WHERE p.MaLoaiPhong = @MaLoaiPhong
              AND (
                  SELECT COUNT(1)
                  FROM dbo.Giuong AS g
                  WHERE g.MaPhong = p.MaPhong
              ) > @SucChuaToiDa
        )
            RAISE EXCEPTION %;

        UPDATE dbo.LoaiPhong
        SET TenLoaiPhong = COALESCE(@TenLoaiPhong, TenLoaiPhong),
            SucChuaToiDa = COALESCE(@SucChuaToiDa, SucChuaToiDa),
            MoTa = COALESCE(@MoTa, MoTa),
            GiaThueTheoGiuong = COALESCE(@GiaThueTheoGiuong, GiaThueTheoGiuong),
            GiaThueNguyenPhong = COALESCE(@GiaThueNguyenPhong, GiaThueNguyenPhong)
        WHERE MaLoaiPhong = @MaLoaiPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật loại phòng',
            @DoiTuong = 'LoaiPhong',
            @MaDoiTuong = @MaLoaiPhong,
            @DuLieuTruoc = @DuLieuTruocLoaiPhong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaLoaiPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        DELETE FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa loại phòng',
            @DoiTuong = 'LoaiPhong',
            @MaDoiTuong = @MaLoaiPhong;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaLoaiPhong AS maLoaiPhong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyLoaiPhong @ThaoTac = 'DANH_SACH', @MaLoaiPhong = @MaLoaiPhong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_TaoPhongGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_TaoPhongGiuong
    @MaPhong         VARCHAR(4)    = NULL,
    @TenPhong        VARCHAR(100),
    @GioiTinhChoPhep VARCHAR(20),
    @MaChiNhanh      VARCHAR(6),
    @MaLoaiPhong     VARCHAR(6),
    @TinhTrang       VARCHAR(20)  = 'Trống',
    @UrlImg          VARCHAR(500)  = NULL,
    @SoGiuong        INT           = NULL,
    @AdminId         VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @TenPhong = NULLIF(TRIM(@TenPhong)), '');
    SET @GioiTinhChoPhep = NULLIF(TRIM(@GioiTinhChoPhep)), '');
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @MaLoaiPhong = NULLIF(TRIM(@MaLoaiPhong)), '');
    SET @TinhTrang = COALESCE(NULLIF(TRIM(@TinhTrang)), ''), 'Trống');
    EXEC dbo.SP_Admin_QuanLyChiNhanh @ThaoTac = 'DANH_SACH', @MaChiNhanh = @MaChiNhanh;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyLoaiPhong AS BEGIN  RETURN 0; END;');
