        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaLoaiPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocLoaiPhong TEXT;
        SELECT @DuLieuTruocLoaiPhong = (
            SELECT * FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        IF @SucChuaToiDa IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.Phong AS p
            WHERE p.MaLoaiPhong = @MaLoaiPhong
              AND (
                  SELECT COUNT(1)
                  FROM dbo.Giuong AS g
                  WHERE g.MaPhong = p.MaPhong
              ) > @SucChuaToiDa
        )
            RAISE EXCEPTION %;

        UPDATE dbo.LoaiPhong
        SET TenLoaiPhong = COALESCE(@TenLoaiPhong, TenLoaiPhong),
            SucChuaToiDa = COALESCE(@SucChuaToiDa, SucChuaToiDa),
            MoTa = COALESCE(@MoTa, MoTa),
            GiaThueTheoGiuong = COALESCE(@GiaThueTheoGiuong, GiaThueTheoGiuong),
            GiaThueNguyenPhong = COALESCE(@GiaThueNguyenPhong, GiaThueNguyenPhong)
        WHERE MaLoaiPhong = @MaLoaiPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật loại phòng',
            @DoiTuong = 'LoaiPhong',
            @MaDoiTuong = @MaLoaiPhong,
            @DuLieuTruoc = @DuLieuTruocLoaiPhong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaLoaiPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        DELETE FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa loại phòng',
            @DoiTuong = 'LoaiPhong',
            @MaDoiTuong = @MaLoaiPhong;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaLoaiPhong AS maLoaiPhong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyLoaiPhong @ThaoTac = 'DANH_SACH', @MaLoaiPhong = @MaLoaiPhong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_TaoPhongGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_TaoPhongGiuong
    @MaPhong         VARCHAR(4)    = NULL,
    @TenPhong        VARCHAR(100),
    @GioiTinhChoPhep VARCHAR(20),
    @MaChiNhanh      VARCHAR(6),
    @MaLoaiPhong     VARCHAR(6),
    @TinhTrang       VARCHAR(20)  = 'Trống',
    @UrlImg          VARCHAR(500)  = NULL,
    @SoGiuong        INT           = NULL,
    @AdminId         VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @TenPhong = NULLIF(TRIM(@TenPhong)), '');
    SET @GioiTinhChoPhep = NULLIF(TRIM(@GioiTinhChoPhep)), '');
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @MaLoaiPhong = NULLIF(TRIM(@MaLoaiPhong)), '');
    SET @TinhTrang = COALESCE(NULLIF(TRIM(@TinhTrang)), ''), 'Trống');
    SET @UrlImg = NULLIF(TRIM(@UrlImg)), '');

    IF @TenPhong IS NULL OR @GioiTinhChoPhep IS NULL OR @MaChiNhanh IS NULL OR @MaLoaiPhong IS NULL
        THROW 51061, 'Vui lòng nhập tên phòng, giới tính, chi nhánh và loại phòng.', 1;

    IF @GioiTinhChoPhep NOT IN ('Nam', 'Nữ', 'Không phân biệt')
        RAISE EXCEPTION %;

    IF @TinhTrang NOT IN ('Trống', 'Đã đặt cọc', 'Còn chỗ', 'Đầy', 'Giữ chỗ')
        RAISE EXCEPTION %;

    IF NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
        RAISE EXCEPTION %;

    IF NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
        RAISE EXCEPTION %;

    DECLARE @SucChuaLoaiPhong INT;
    SELECT @SucChuaLoaiPhong = SucChuaToiDa
    FROM dbo.LoaiPhong
    WHERE MaLoaiPhong = @MaLoaiPhong;

    IF @SoGiuong IS NULL
        SET @SoGiuong = @SucChuaLoaiPhong;

    IF @SoGiuong < 1 OR @SoGiuong > 99
        RAISE EXCEPTION %;

    IF @SoGiuong > @SucChuaLoaiPhong
        RAISE EXCEPTION %;

    DECLARE @SoPhong INT;
    DECLARE @SoChiNhanh INT = TRY_CONVERT(INT, SUBSTRING(@MaChiNhanh, 3, 4));
    DECLARE @Index INT = 1;
    DECLARE @MaGiuong VARCHAR(3);

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @MaPhong IS NULL
        BEGIN
            IF @SoChiNhanh IS NULL OR @SoChiNhanh NOT BETWEEN 1 AND 9
                RAISE EXCEPTION %;

            SELECT @SoPhong = COALESCE(MAX(TRY_CONVERT(INT, RIGHT(MaPhong, 2))), 0) + 1
            FROM dbo.Phong 
            WHERE MaChiNhanh = @MaChiNhanh
              AND MaPhong LIKE CONCAT('P', @SoChiNhanh, '[0-9][0-9]');

            IF @SoPhong > 99
                RAISE EXCEPTION %;

            SET @MaPhong = CONCAT('P', @SoChiNhanh, RIGHT(CONCAT('00', @SoPhong), 2));
        END;

        IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        INSERT INTO dbo.Phong (MaPhong, TenPhong, GioiTinhChoPhep, TinhTrang, MaChiNhanh, MaLoaiPhong)
        VALUES (@MaPhong, @TenPhong, @GioiTinhChoPhep, @TinhTrang, @MaChiNhanh, @MaLoaiPhong);

        IF @UrlImg IS NOT NULL
        BEGIN
            INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
            VALUES (@MaPhong, 1, @UrlImg);
        END;

        WHILE @Index <= @SoGiuong
        BEGIN
            SET @MaGiuong = CONCAT('G', RIGHT(CONCAT('00', @Index), 2));

            INSERT INTO dbo.Giuong (MaPhong, MaGiuong, SoGiuong, TinhTrang)
            VALUES (@MaPhong, @MaGiuong, @Index, 'Trống');

            SET @Index += 1;
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo phòng giường',
            @DoiTuong = 'Phong',
            @MaDoiTuong = @MaPhong,
            @NoiDung = @TenPhong;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        p.MaPhong AS maPhong,
        p.TenPhong AS tenPhong,
        p.GioiTinhChoPhep AS gioiTinhChoPhep,
        p.TinhTrang AS tinhTrangPhong,
        (SELECT TOP 1 hap.UrlImg FROM dbo.HinhAnhPhong AS hap WHERE hap.MaPhong = p.MaPhong ORDER BY hap.STTAnh) AS urlImgPhong,
        p.MaChiNhanh AS maChiNhanh,
        cn.TenChiNhanh AS tenChiNhanh,
        p.MaLoaiPhong AS maLoaiPhong,
        lp.TenLoaiPhong AS tenLoaiPhong,
        g.MaGiuong AS maGiuong,
        g.SoGiuong AS soGiuong,
        g.TinhTrang AS tinhTrangGiuong
    FROM dbo.Phong AS p
    INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    LEFT JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
    WHERE p.MaPhong = @MaPhong
    ORDER BY g.SoGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CapNhatTrangThaiPhongGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CapNhatTrangThaiPhongGiuong
    @LoaiDoiTuong VARCHAR(20),
    @MaPhong      VARCHAR(4),
    @MaGiuong     VARCHAR(3)   = NULL,
    @TrangThai    VARCHAR(20),
    @AdminId      VARCHAR(6)   = NULL
AS
BEGIN
    
    

    SET @LoaiDoiTuong = UPPER(NULLIF(TRIM(@LoaiDoiTuong)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');

    IF @LoaiDoiTuong NOT IN ('PHONG', 'GIUONG')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @LoaiDoiTuong = 'PHONG' AND @TrangThai NOT IN ('Trống', 'Đã đặt cọc', 'Còn chỗ', 'Đầy', 'Giữ chỗ', 'Bảo trì')
        RAISE EXCEPTION %;

    IF @LoaiDoiTuong = 'GIUONG' AND @TrangThai NOT IN ('Trống', 'Đã đặt cọc', 'Đang thuê')
        RAISE EXCEPTION %;

    IF @LoaiDoiTuong = 'GIUONG'
       AND (@MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
       ))
        RAISE EXCEPTION %;

    DECLARE @DuLieuTruoc TEXT;

    IF @LoaiDoiTuong = 'PHONG'
        SELECT @DuLieuTruoc = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );
    ELSE
        SELECT @DuLieuTruoc = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @LoaiDoiTuong = 'PHONG'
        BEGIN
            UPDATE dbo.Phong
            SET TinhTrang = @TrangThai
            WHERE MaPhong = @MaPhong;
        END
        ELSE
        BEGIN
            UPDATE dbo.Giuong
            SET TinhTrang = @TrangThai
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong;

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (
                    SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống'
                ) THEN 'Trống'
                WHEN NOT EXISTS (
                    SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống'
                ) THEN 'Đầy'
                WHEN EXISTS (
                    SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Đã đặt cọc'
                ) THEN 'Còn chỗ'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật trạng thái phòng/giường',
            @DoiTuong = @LoaiDoiTuong,
            @MaDoiTuong = @MaPhong,
            @NoiDung = @TrangThai,
            @DuLieuTruoc = @DuLieuTruoc;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        p.MaPhong AS maPhong,
        p.TenPhong AS tenPhong,
        p.TinhTrang AS tinhTrangPhong,
        g.MaGiuong AS maGiuong,
        g.SoGiuong AS soGiuong,
        g.TinhTrang AS tinhTrangGiuong
    FROM dbo.Phong AS p
    LEFT JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
    WHERE p.MaPhong = @MaPhong
      AND (@MaGiuong IS NULL OR g.MaGiuong = @MaGiuong)
    ORDER BY g.SoGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyPhong
    @ThaoTac         VARCHAR(20)  = 'DANH_SACH',
    @MaPhong         VARCHAR(4)    = NULL,
    @TenPhong        VARCHAR(100) = NULL,
    @GioiTinhChoPhep VARCHAR(20)  = NULL,
    @TinhTrang       VARCHAR(20)  = NULL,
    @UrlImg          VARCHAR(500)  = NULL,
    @MaChiNhanh      VARCHAR(6)    = NULL,
    @MaLoaiPhong     VARCHAR(6)    = NULL,
    @AdminId         VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @TenPhong = NULLIF(TRIM(@TenPhong)), '');
    SET @GioiTinhChoPhep = NULLIF(TRIM(@GioiTinhChoPhep)), '');
    SET @TinhTrang = NULLIF(TRIM(@TinhTrang)), '');
    SET @UrlImg = NULLIF(TRIM(@UrlImg)), '');
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @MaLoaiPhong = NULLIF(TRIM(@MaLoaiPhong)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            p.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            p.GioiTinhChoPhep AS gioiTinhChoPhep,
            p.TinhTrang AS tinhTrang,
            (SELECT TOP 1 hap.UrlImg FROM dbo.HinhAnhPhong AS hap WHERE hap.MaPhong = p.MaPhong ORDER BY hap.STTAnh) AS urlImg,
            p.MaChiNhanh AS maChiNhanh,
            cn.TenChiNhanh AS tenChiNhanh,
            p.MaLoaiPhong AS maLoaiPhong,
            lp.TenLoaiPhong AS tenLoaiPhong,
            COUNT(g.MaGiuong) AS soGiuong,
            SUM(CASE WHEN g.TinhTrang = 'Trống' THEN 1 ELSE 0 END) AS soGiuongTrong
        FROM dbo.Phong AS p
        INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
        INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
        LEFT JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
        WHERE (@MaPhong IS NULL OR p.MaPhong = @MaPhong)
          AND (@MaChiNhanh IS NULL OR p.MaChiNhanh = @MaChiNhanh)
          AND (@MaLoaiPhong IS NULL OR p.MaLoaiPhong = @MaLoaiPhong)
          AND (@TinhTrang IS NULL OR p.TinhTrang = @TinhTrang)
        GROUP BY p.MaPhong, p.TenPhong, p.GioiTinhChoPhep, p.TinhTrang,
                 p.MaChiNhanh, cn.TenChiNhanh, p.MaLoaiPhong, lp.TenLoaiPhong
        ORDER BY p.MaPhong;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO'
           AND (@TenPhong IS NULL OR @GioiTinhChoPhep IS NULL OR @MaChiNhanh IS NULL OR @MaLoaiPhong IS NULL)
            THROW 51102, 'Vui lòng nhập đầy đủ tên phòng, giới tính, chi nhánh và loại phòng.', 1;

        IF @GioiTinhChoPhep IS NOT NULL AND @GioiTinhChoPhep NOT IN ('Nam', 'Nữ', 'Không phân biệt')
            RAISE EXCEPTION %;

        IF @TinhTrang IS NOT NULL AND @TinhTrang NOT IN ('Trống', 'Đã đặt cọc', 'Còn chỗ', 'Đầy', 'Giữ chỗ', 'Bảo trì')
            RAISE EXCEPTION %;

        IF @MaChiNhanh IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
            RAISE EXCEPTION %;

        IF @MaLoaiPhong IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoPhongMoi INT;
        DECLARE @SoChiNhanhPhong INT = TRY_CONVERT(INT, SUBSTRING(@MaChiNhanh, 3, 4));

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaPhong IS NULL
            BEGIN
                IF @SoChiNhanhPhong IS NULL OR @SoChiNhanhPhong NOT BETWEEN 1 AND 9
                    RAISE EXCEPTION %;

                SELECT @SoPhongMoi = COALESCE(MAX(TRY_CONVERT(INT, RIGHT(MaPhong, 2))), 0) + 1
                FROM dbo.Phong 
                WHERE MaChiNhanh = @MaChiNhanh
                  AND MaPhong LIKE CONCAT('P', @SoChiNhanhPhong, '[0-9][0-9]');

                IF @SoPhongMoi > 99
                    RAISE EXCEPTION %;

                SET @MaPhong = CONCAT('P', @SoChiNhanhPhong, RIGHT(CONCAT('00', @SoPhongMoi), 2));
            END;

            IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
                RAISE EXCEPTION %;

            INSERT INTO dbo.Phong (MaPhong, TenPhong, GioiTinhChoPhep, TinhTrang, MaChiNhanh, MaLoaiPhong)
            VALUES (@MaPhong, @TenPhong, @GioiTinhChoPhep, COALESCE(@TinhTrang, 'Trống'), @MaChiNhanh, @MaLoaiPhong);

            IF @UrlImg IS NOT NULL
            BEGIN
                INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
                VALUES (@MaPhong, 1, @UrlImg);
            END;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo phòng',
                @DoiTuong = 'Phong',
                @MaDoiTuong = @MaPhong,
                @NoiDung = @TenPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocPhong TEXT;
        SELECT @DuLieuTruocPhong = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.Phong
        SET TenPhong = COALESCE(@TenPhong, TenPhong),
            GioiTinhChoPhep = COALESCE(@GioiTinhChoPhep, GioiTinhChoPhep),
            TinhTrang = COALESCE(@TinhTrang, TinhTrang),
            MaChiNhanh = COALESCE(@MaChiNhanh, MaChiNhanh),
            MaLoaiPhong = COALESCE(@MaLoaiPhong, MaLoaiPhong)
        WHERE MaPhong = @MaPhong;

        IF @UrlImg IS NOT NULL
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.HinhAnhPhong WHERE MaPhong = @MaPhong AND STTAnh = 1)
                UPDATE dbo.HinhAnhPhong
                SET UrlImg = @UrlImg
                WHERE MaPhong = @MaPhong AND STTAnh = 1;
            ELSE
                INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
                VALUES (@MaPhong, 1, @UrlImg);
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật phòng',
            @DoiTuong = 'Phong',
            @MaDoiTuong = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocPhong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống')
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc AS ctdc
            INNER JOIN dbo.PhieuDatCoc AS pdc ON pdc.MaPhieuDatCoc = ctdc.MaPhieuDatCoc
            WHERE ctdc.MaPhong = @MaPhong
              AND pdc.TrangThaiCoc IN ('Hiệu lực', 'Đã lập HĐ')
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietDatCoc WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong)
           OR EXISTS (SELECT 1 FROM dbo.ChiTietXemPhong WHERE MaPhong = @MaPhong)
           OR EXISTS (SELECT 1 FROM dbo.PhieuGhiChiSo WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocPhongXoa TEXT;
        SELECT @DuLieuTruocPhongXoa = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        BEGIN TRY
            BEGIN TRANSACTION;

            DELETE FROM dbo.Giuong WHERE MaPhong = @MaPhong;
            DELETE FROM dbo.Phong WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa phòng',
                @DoiTuong = 'Phong',
                @MaDoiTuong = @MaPhong,
                @DuLieuTruoc = @DuLieuTruocPhongXoa;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyPhong @ThaoTac = 'DANH_SACH', @MaPhong = @MaPhong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyGiuong
    @ThaoTac   VARCHAR(20) = 'DANH_SACH',
    @MaPhong   VARCHAR(4)   = NULL,
    @MaGiuong  VARCHAR(3)   = NULL,
    @SoGiuong  INT          = NULL,
    @TinhTrang VARCHAR(20) = NULL,
    @UrlImg    VARCHAR(500) = NULL,
    @AdminId   VARCHAR(6)   = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    SET @TinhTrang = NULLIF(TRIM(@TinhTrang)), '');
    SET @UrlImg = NULLIF(TRIM(@UrlImg)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            g.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            g.MaGiuong AS maGiuong,
            g.SoGiuong AS soGiuong,
            g.TinhTrang AS tinhTrang,
            lp.SucChuaToiDa AS sucChuaToiDa,
            (
                SELECT COUNT(1)
                FROM dbo.TaiSan AS tsChung
                WHERE tsChung.MaPhong = g.MaPhong
                  AND tsChung.LoaiTaiSan = 'Chung'
            ) AS soTaiSanChung,
            CAST(0 AS INT) AS soTaiSanRieng
        FROM dbo.Giuong AS g
        INNER JOIN dbo.Phong AS p ON p.MaPhong = g.MaPhong
        INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
        WHERE (@MaPhong IS NULL OR g.MaPhong = @MaPhong)
          AND (@MaGiuong IS NULL OR g.MaGiuong = @MaGiuong)
          AND (@TinhTrang IS NULL OR g.TinhTrang = @TinhTrang)
        ORDER BY g.MaPhong, g.SoGiuong, g.MaGiuong;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @SoGiuong IS NULL
            RAISE EXCEPTION %;

        IF @SoGiuong IS NOT NULL AND @SoGiuong < 1
            RAISE EXCEPTION %;

        IF @TinhTrang IS NOT NULL AND @TinhTrang NOT IN ('Trống', 'Đã đặt cọc', 'Đang thuê')
            RAISE EXCEPTION %;
    END;

    DECLARE @SucChuaToiDa INT;
    SELECT @SucChuaToiDa = lp.SucChuaToiDa
    FROM dbo.Phong AS p
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    WHERE p.MaPhong = @MaPhong;

    IF @SoGiuong IS NOT NULL AND @SoGiuong > @SucChuaToiDa
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF (SELECT COUNT(*) FROM dbo.Giuong WHERE MaPhong = @MaPhong) >= @SucChuaToiDa
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND SoGiuong = @SoGiuong)
            RAISE EXCEPTION %;

        IF @MaGiuong IS NULL
        BEGIN
            DECLARE @SoMaGiuong INT;
            SELECT @SoMaGiuong = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaGiuong, 2, 2))), 0) + 1
            FROM dbo.Giuong 
            WHERE MaPhong = @MaPhong
              AND MaGiuong LIKE 'G[0-9][0-9]';

            IF @SoMaGiuong > 99
                RAISE EXCEPTION %;

            SET @MaGiuong = CONCAT('G', RIGHT(CONCAT('00', @SoMaGiuong), 2));
        END;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong)
            RAISE EXCEPTION %;

        BEGIN TRY
            BEGIN TRANSACTION;

            INSERT INTO dbo.Giuong (MaPhong, MaGiuong, SoGiuong, TinhTrang)
            VALUES (@MaPhong, @MaGiuong, @SoGiuong, COALESCE(@TinhTrang, 'Trống'));

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo giường',
                @DoiTuong = 'Giuong',
                @MaDoiTuong = @MaGiuong,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF @SoGiuong IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.Giuong
            WHERE MaPhong = @MaPhong
              AND SoGiuong = @SoGiuong
              AND MaGiuong <> @MaGiuong
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocGiuong TEXT;
        SELECT @DuLieuTruocGiuong = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.Giuong
        SET SoGiuong = COALESCE(@SoGiuong, SoGiuong),
            TinhTrang = COALESCE(@TinhTrang, TinhTrang)
        WHERE MaPhong = @MaPhong
          AND MaGiuong = @MaGiuong;

        UPDATE dbo.Phong
        SET TinhTrang = CASE
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong) THEN 'Trống'
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
            ELSE 'Còn chỗ'
        END
        WHERE MaPhong = @MaPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật giường',
            @DoiTuong = 'Giuong',
            @MaDoiTuong = @MaGiuong,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocGiuong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1 FROM dbo.Giuong
            WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong AND TinhTrang <> 'Trống'
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc AS ctdc
            INNER JOIN dbo.PhieuDatCoc AS pdc ON pdc.MaPhieuDatCoc = ctdc.MaPhieuDatCoc
            WHERE ctdc.MaPhong = @MaPhong
              AND ctdc.MaGiuong = @MaGiuong
              AND pdc.TrangThaiCoc IN ('Hiệu lực', 'Đã lập HĐ')
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietXemPhong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocGiuongXoa TEXT;
        SELECT @DuLieuTruocGiuongXoa = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        BEGIN TRY
            BEGIN TRANSACTION;

            DELETE FROM dbo.Giuong
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong;

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong) THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa giường',
                @DoiTuong = 'Giuong',
                @MaDoiTuong = @MaGiuong,
                @NoiDung = @MaPhong,
                @DuLieuTruoc = @DuLieuTruocGiuongXoa;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaGiuong AS maGiuong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyGiuong @ThaoTac = 'DANH_SACH', @MaPhong = @MaPhong, @MaGiuong = @MaGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyTaiSanPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyTaiSanPhong
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaPhong   VARCHAR(4)    = NULL,
    @MaTaiSan  VARCHAR(6)    = NULL,
    @TenTaiSan VARCHAR(100) = NULL,
    @SoLuong   INT           = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @LoaiTaiSan VARCHAR(20) = NULL,
    @MaGiuong   VARCHAR(3)   = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaTaiSan = NULLIF(TRIM(@MaTaiSan)), '');
    SET @TenTaiSan = NULLIF(TRIM(@TenTaiSan)), '');
    SET @LoaiTaiSan = NULLIF(TRIM(@LoaiTaiSan)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            ts.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            ts.MaTaiSan AS maTaiSan,
            ts.TenTaiSan AS tenTaiSan,
            ts.SoLuong AS soLuong,
            ts.DonGia AS donGia,
            ts.LoaiTaiSan AS loaiTaiSan,
            ts.MaGiuong AS maGiuong,
            g.SoGiuong AS soGiuong
        FROM dbo.TaiSan AS ts
        INNER JOIN dbo.Phong AS p ON p.MaPhong = ts.MaPhong
        LEFT JOIN dbo.Giuong AS g ON g.MaPhong = ts.MaPhong AND g.MaGiuong = ts.MaGiuong
        WHERE (@MaPhong IS NULL OR ts.MaPhong = @MaPhong)
          AND (@MaTaiSan IS NULL OR ts.MaTaiSan = @MaTaiSan)
          AND (@MaGiuong IS NULL OR ts.MaGiuong = @MaGiuong)
          AND (@LoaiTaiSan IS NULL OR ts.LoaiTaiSan = @LoaiTaiSan)
        ORDER BY ts.MaPhong, ts.LoaiTaiSan, ts.MaGiuong, ts.MaTaiSan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TenTaiSan IS NULL
            RAISE EXCEPTION %;

        IF @SoLuong IS NOT NULL AND @SoLuong <= 0
            RAISE EXCEPTION %;

        IF @DonGia IS NOT NULL AND @DonGia < 0
            RAISE EXCEPTION %;

        DECLARE @LoaiTaiSanSau VARCHAR(20);
        DECLARE @MaGiuongSau VARCHAR(3);

        IF @ThaoTac = 'TAO'
        BEGIN
            SET @LoaiTaiSanSau = COALESCE(@LoaiTaiSan, 'Chung');
            SET @MaGiuongSau = @MaGiuong;
        END
        ELSE
        BEGIN
            IF @MaTaiSan IS NULL OR NOT EXISTS (
                SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
            )
                RAISE EXCEPTION %;

            SELECT
                @LoaiTaiSanSau = COALESCE(@LoaiTaiSan, LoaiTaiSan),
                @MaGiuongSau = CASE
                    WHEN @LoaiTaiSan = 'Chung' THEN NULL
                    ELSE COALESCE(@MaGiuong, MaGiuong)
                END
            FROM dbo.TaiSan
            WHERE MaPhong = @MaPhong
              AND MaTaiSan = @MaTaiSan;
        END;

        IF @LoaiTaiSanSau NOT IN ('Chung', 'Riêng')
            RAISE EXCEPTION %;

        IF @LoaiTaiSanSau = 'Chung'
            SET @MaGiuongSau = NULL;

        IF @LoaiTaiSanSau = 'Riêng' AND @MaGiuongSau IS NULL
            RAISE EXCEPTION %;

        IF @MaGiuongSau IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuongSau
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoTaiSan INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaTaiSan IS NULL
            BEGIN
                SELECT @SoTaiSan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaTaiSan, 3, 4))), 0) + 1
                FROM dbo.TaiSan 
                WHERE MaPhong = @MaPhong
                  AND MaTaiSan LIKE 'TS[0-9][0-9][0-9][0-9]';

                IF @SoTaiSan > 9999
                    RAISE EXCEPTION %;

                SET @MaTaiSan = CONCAT('TS', RIGHT(CONCAT('0000', @SoTaiSan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.TaiSan (
                MaPhong, MaTaiSan, TenTaiSan, SoLuong, DonGia, LoaiTaiSan, MaGiuong
            )
            VALUES (
                @MaPhong, @MaTaiSan, @TenTaiSan, COALESCE(@SoLuong, 1),
                @DonGia, @LoaiTaiSanSau, @MaGiuongSau
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo tài sản phòng',
                @DoiTuong = 'TaiSan',
                @MaDoiTuong = @MaTaiSan,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocTaiSan TEXT;
        SELECT @DuLieuTruocTaiSan = (
            SELECT * FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.TaiSan
        SET TenTaiSan = COALESCE(@TenTaiSan, TenTaiSan),
            SoLuong = COALESCE(@SoLuong, SoLuong),
            DonGia = COALESCE(@DonGia, DonGia),
            LoaiTaiSan = @LoaiTaiSanSau,
            MaGiuong = @MaGiuongSau
        WHERE MaPhong = @MaPhong
          AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocTaiSan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietBanGiao WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.ChiTietHuHong WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.YeuCauSuaChua WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaTaiSan AS maTaiSan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyTaiSanPhong
        @ThaoTac = 'DANH_SACH',
        @MaPhong = @MaPhong,
        @MaTaiSan = @MaTaiSan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc
    @ThaoTac           VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinhHoanCoc VARCHAR(6)    = NULL,
    @TenQuyDinh        VARCHAR(255) = NULL,
    @TyLeHoanCoc       DECIMAL(5,2)  = NULL,
    @AdminId           VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinhHoanCoc = NULLIF(TRIM(@MaQuyDinhHoanCoc)), '');
    SET @TenQuyDinh = NULLIF(TRIM(@TenQuyDinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qh.MaQuyDinhHoanCoc AS maQuyDinhHoanCoc,
            qh.TenQuyDinh AS tenQuyDinh,
            qh.TyLeHoanCoc AS tyLeHoanCoc,
            COUNT(ds.MaQuyDinhHoanCoc) AS soLanApDung
        FROM dbo.QuyDinhHoanCoc AS qh
        LEFT JOIN dbo.DoiSoat AS ds ON ds.MaQuyDinhHoanCoc = qh.MaQuyDinhHoanCoc
        WHERE (@MaQuyDinhHoanCoc IS NULL OR qh.MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
        GROUP BY qh.MaQuyDinhHoanCoc, qh.TenQuyDinh, qh.TyLeHoanCoc
        ORDER BY qh.MaQuyDinhHoanCoc;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenQuyDinh IS NULL OR @TyLeHoanCoc IS NULL)
            RAISE EXCEPTION %;

        IF @TyLeHoanCoc IS NOT NULL AND (@TyLeHoanCoc < 0 OR @TyLeHoanCoc > 100)
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinh INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinhHoanCoc IS NULL
            BEGIN
                SELECT @SoQuyDinh = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinhHoanCoc, 3, 4))), 0) + 1
                FROM dbo.QuyDinhHoanCoc 
                WHERE MaQuyDinhHoanCoc LIKE 'QH[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinh > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinhHoanCoc = CONCAT('QH', RIGHT(CONCAT('0000', @SoQuyDinh), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuyDinhHoanCoc (MaQuyDinhHoanCoc, TenQuyDinh, TyLeHoanCoc)
            VALUES (@MaQuyDinhHoanCoc, @TenQuyDinh, @TyLeHoanCoc);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo quy định hoàn cọc',
                @DoiTuong = 'QuyDinhHoanCoc',
                @MaDoiTuong = @MaQuyDinhHoanCoc,
                @NoiDung = @TenQuyDinh;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocHoanCoc TEXT;
        SELECT @DuLieuTruocHoanCoc = (
            SELECT * FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuyDinhHoanCoc
        SET TenQuyDinh = COALESCE(@TenQuyDinh, TenQuyDinh),
            TyLeHoanCoc = COALESCE(@TyLeHoanCoc, TyLeHoanCoc)
        WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc,
            @DuLieuTruoc = @DuLieuTruocHoanCoc;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DoiSoat WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinhHoanCoc AS maQuyDinhHoanCoc;
        RETURN;
    END;

    EXEC dbo.SP_Admin_CauHinhQuyDinhHoanCoc @ThaoTac = 'DANH_SACH', @MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDichVu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDichVu
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaDichVu  VARCHAR(6)    = NULL,
    @TenDichVu VARCHAR(100) = NULL,
    @DonViTinh VARCHAR(20)   = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDichVu = NULLIF(TRIM(@MaDichVu)), '');
    SET @TenDichVu = NULLIF(TRIM(@TenDichVu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dv.MaDichVu AS maDichVu,
            dv.TenDichVu AS tenDichVu,
            dv.DonViTinh AS donViTinh,
            dv.DonGia AS donGia,
            COUNT(DISTINCT dvhd.MaChiTietDVHD) AS soHopDongSuDung,
            COUNT(cthd.MaChiTietHD) AS soDongHoaDon
        FROM dbo.DichVu AS dv
        LEFT JOIN dbo.DichVuHopDong AS dvhd ON dvhd.MaDichVu = dv.MaDichVu
        LEFT JOIN dbo.ChiTietHoaDon AS cthd ON cthd.MaChiTietDVHD = dvhd.MaChiTietDVHD
        WHERE (@MaDichVu IS NULL OR dv.MaDichVu = @MaDichVu)
          AND (@TenDichVu IS NULL OR dv.TenDichVu LIKE '%' + @TenDichVu + '%')
        GROUP BY dv.MaDichVu, dv.TenDichVu, dv.DonViTinh, dv.DonGia
        ORDER BY dv.MaDichVu;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDichVu IS NULL OR @DonViTinh IS NULL OR @DonGia IS NULL)
            THROW 51202, 'Vui lòng nhập tên dịch vụ, đơn vị tính và đơn giá.', 1;

        IF @DonGia IS NOT NULL AND @DonGia <= 0
            RAISE EXCEPTION %;

        IF @TenDichVu IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DichVu
            WHERE TenDichVu = @TenDichVu
              AND (@MaDichVu IS NULL OR MaDichVu <> @MaDichVu)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDichVu INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDichVu IS NULL
            BEGIN
                SELECT @SoDichVu = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDichVu, 3, 4))), 0) + 1
                FROM dbo.DichVu 
                WHERE MaDichVu LIKE 'DV[0-9][0-9][0-9][0-9]';

                IF @SoDichVu > 9999
                    RAISE EXCEPTION %;

                SET @MaDichVu = CONCAT('DV', RIGHT(CONCAT('0000', @SoDichVu), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DichVu (MaDichVu, TenDichVu, DonViTinh, DonGia)
            VALUES (@MaDichVu, @TenDichVu, @DonViTinh, @DonGia);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo dịch vụ',
                @DoiTuong = 'DichVu',
                @MaDoiTuong = @MaDichVu,
                @NoiDung = @TenDichVu;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocDichVu TEXT;
        SELECT @DuLieuTruocDichVu = (
            SELECT * FROM dbo.DichVu WHERE MaDichVu = @MaDichVu FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DichVu
        SET TenDichVu = COALESCE(@TenDichVu, TenDichVu),
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            DonGia = COALESCE(@DonGia, DonGia)
        WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu,
            @DuLieuTruoc = @DuLieuTruocDichVu;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DichVuHopDong WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DichVu WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDichVu AS maDichVu;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDichVu @ThaoTac = 'DANH_SACH', @MaDichVu = @MaDichVu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyNoiQuy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyNoiQuy
    @ThaoTac      VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinh    VARCHAR(6)    = NULL,
    @TieuDeNoiQuy VARCHAR(255) = NULL,
    @NoiDung      TEXT = NULL,
    @TrangThai    VARCHAR(20)  = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinh = NULLIF(TRIM(@MaQuyDinh)), '');
    SET @TieuDeNoiQuy = NULLIF(TRIM(@TieuDeNoiQuy)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qd.MaQuyDinh AS maQuyDinh,
            qd.TieuDeNoiQuy AS tieuDeNoiQuy,
            qd.NoiDung AS noiDung,
            qd.TrangThai AS trangThai
        FROM dbo.QuiDinh AS qd
        WHERE (@MaQuyDinh IS NULL OR qd.MaQuyDinh = @MaQuyDinh)
          AND (@TrangThai IS NULL OR qd.TrangThai = @TrangThai)
          AND (@TieuDeNoiQuy IS NULL OR qd.TieuDeNoiQuy LIKE '%' + @TieuDeNoiQuy + '%')
        ORDER BY qd.MaQuyDinh;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TieuDeNoiQuy IS NULL
            RAISE EXCEPTION %;

        IF @TieuDeNoiQuy IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.QuiDinh
            WHERE TieuDeNoiQuy = @TieuDeNoiQuy
              AND (@MaQuyDinh IS NULL OR MaQuyDinh <> @MaQuyDinh)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinhNoiQuy INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinh IS NULL
            BEGIN
                SELECT @SoQuyDinhNoiQuy = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinh, 3, 4))), 0) + 1
                FROM dbo.QuiDinh 
                WHERE MaQuyDinh LIKE 'QD[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinhNoiQuy > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinh = CONCAT('QD', RIGHT(CONCAT('0000', @SoQuyDinhNoiQuy), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuiDinh (MaQuyDinh, TieuDeNoiQuy, NoiDung, TrangThai)
            VALUES (@MaQuyDinh, @TieuDeNoiQuy, @NoiDung, COALESCE(@TrangThai, 'Hiệu lực'));

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo nội quy',
                @DoiTuong = 'QuiDinh',
                @MaDoiTuong = @MaQuyDinh,
                @NoiDung = @TieuDeNoiQuy;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocNoiQuy TEXT;
        SELECT @DuLieuTruocNoiQuy = (
            SELECT * FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuiDinh
        SET TieuDeNoiQuy = COALESCE(@TieuDeNoiQuy, TieuDeNoiQuy),
            NoiDung = COALESCE(@NoiDung, NoiDung),
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh,
            @DuLieuTruoc = @DuLieuTruocNoiQuy;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        UPDATE dbo.QuiDinh
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinh AS maQuyDinh;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyNoiQuy @ThaoTac = 'DANH_SACH', @MaQuyDinh = @MaQuyDinh;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham
    @ThaoTac        VARCHAR(20)  = 'DANH_SACH',
    @MaDieuKhoan    VARCHAR(6)    = NULL,
    @TenDieuKhoan   VARCHAR(255) = NULL,
    @HinhThucXuPhat VARCHAR(20)  = NULL,
    @MucPhat        DECIMAL(15,2) = NULL,
    @TrangThai      VARCHAR(20)  = NULL,
    @AdminId        VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDieuKhoan = NULLIF(TRIM(@MaDieuKhoan)), '');
    SET @TenDieuKhoan = NULLIF(TRIM(@TenDieuKhoan)), '');
    SET @HinhThucXuPhat = NULLIF(TRIM(@HinhThucXuPhat)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dk.MaDieuKhoan AS maDieuKhoan,
            dk.TenDieuKhoan AS tenDieuKhoan,
            dk.HinhThucXuPhat AS hinhThucXuPhat,
            dk.MucPhat AS mucPhat,
            dk.TrangThai AS trangThai,
            COUNT(bb.MaBBViPham) AS soBienBanApDung
        FROM dbo.DieuKhoanViPham AS dk
        LEFT JOIN dbo.BienBanViPham AS bb ON bb.MaDieuKhoan = dk.MaDieuKhoan
        WHERE (@MaDieuKhoan IS NULL OR dk.MaDieuKhoan = @MaDieuKhoan)
          AND (@TrangThai IS NULL OR dk.TrangThai = @TrangThai)
          AND (@TenDieuKhoan IS NULL OR dk.TenDieuKhoan LIKE '%' + @TenDieuKhoan + '%')
        GROUP BY dk.MaDieuKhoan, dk.TenDieuKhoan, dk.HinhThucXuPhat, dk.MucPhat, dk.TrangThai
        ORDER BY dk.MaDieuKhoan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @HinhThucXuPhat IS NOT NULL AND @HinhThucXuPhat NOT IN ('Nhắc nhở', 'Phạt tiền')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @MucPhat IS NOT NULL AND @MucPhat < 0
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDieuKhoan IS NULL OR @HinhThucXuPhat IS NULL)
            RAISE EXCEPTION %;

        IF @TenDieuKhoan IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DieuKhoanViPham
            WHERE TenDieuKhoan = @TenDieuKhoan
              AND (@MaDieuKhoan IS NULL OR MaDieuKhoan <> @MaDieuKhoan)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDieuKhoan INT;

        IF @HinhThucXuPhat = 'Phạt tiền' AND COALESCE(@MucPhat, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucXuPhat = 'Nhắc nhở' AND @MucPhat IS NULL
            SET @MucPhat = 0;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDieuKhoan IS NULL
            BEGIN
                SELECT @SoDieuKhoan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDieuKhoan, 3, 4))), 0) + 1
                FROM dbo.DieuKhoanViPham 
                WHERE MaDieuKhoan LIKE 'VP[0-9][0-9][0-9][0-9]';

                IF @SoDieuKhoan > 9999
                    RAISE EXCEPTION %;

                SET @MaDieuKhoan = CONCAT('VP', RIGHT(CONCAT('0000', @SoDieuKhoan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DieuKhoanViPham (
                MaDieuKhoan, TenDieuKhoan, HinhThucXuPhat, MucPhat, TrangThai
            )
            VALUES (
                @MaDieuKhoan, @TenDieuKhoan, @HinhThucXuPhat, COALESCE(@MucPhat, 0), COALESCE(@TrangThai, 'Hiệu lực')
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo điều khoản vi phạm',
                @DoiTuong = 'DieuKhoanViPham',
                @MaDoiTuong = @MaDieuKhoan,
                @NoiDung = @TenDieuKhoan;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DECLARE @HinhThucSau VARCHAR(20);
        DECLARE @MucPhatSau DECIMAL(15,2);

        SELECT
            @HinhThucSau = COALESCE(@HinhThucXuPhat, HinhThucXuPhat),
            @MucPhatSau = COALESCE(@MucPhat, MucPhat)
        FROM dbo.DieuKhoanViPham
        WHERE MaDieuKhoan = @MaDieuKhoan;

        IF @HinhThucSau = 'Phạt tiền' AND COALESCE(@MucPhatSau, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucSau = 'Nhắc nhở' AND @MucPhatSau IS NULL
            SET @MucPhatSau = 0;

        DECLARE @DuLieuTruocDieuKhoan TEXT;
        SELECT @DuLieuTruocDieuKhoan = (
            SELECT * FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DieuKhoanViPham
        SET TenDieuKhoan = COALESCE(@TenDieuKhoan, TenDieuKhoan),
            HinhThucXuPhat = @HinhThucSau,
            MucPhat = @MucPhatSau,
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan,
            @DuLieuTruoc = @DuLieuTruocDieuKhoan;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        UPDATE dbo.DieuKhoanViPham
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.BienBanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDieuKhoan AS maDieuKhoan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDieuKhoanViPham @ThaoTac = 'DANH_SACH', @MaDieuKhoan = @MaDieuKhoan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhThamSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhThamSo
    @ThaoTac    VARCHAR(20)  = 'DANH_SACH',
    @MaThamSo   VARCHAR(50)   = NULL,
    @NhomThamSo VARCHAR(50)  = NULL,
    @TenThamSo  VARCHAR(100) = NULL,
    @GiaTri     VARCHAR(255) = NULL,
    @KieuDuLieu VARCHAR(20)  = NULL,
    @DonViTinh  VARCHAR(30)  = NULL,
    @MoTa       TEXT = NULL,
    @AdminId    VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaThamSo = NULLIF(TRIM(@MaThamSo)), '');
    SET @NhomThamSo = NULLIF(TRIM(@NhomThamSo)), '');
    SET @TenThamSo = NULLIF(TRIM(@TenThamSo)), '');
    SET @GiaTri = NULLIF(TRIM(@GiaTri)), '');
    SET @KieuDuLieu = NULLIF(TRIM(@KieuDuLieu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            MaThamSo AS maThamSo,
            NhomThamSo AS nhomThamSo,
            TenThamSo AS tenThamSo,
            GiaTri AS giaTri,
            KieuDuLieu AS kieuDuLieu,
            DonViTinh AS donViTinh,
            MoTa AS moTa,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.ThamSoHeThong
        WHERE (@MaThamSo IS NULL OR MaThamSo = @MaThamSo)
          AND (@NhomThamSo IS NULL OR NhomThamSo = @NhomThamSo)
        ORDER BY NhomThamSo, MaThamSo;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT')
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO' AND (@MaThamSo IS NULL OR @NhomThamSo IS NULL OR @TenThamSo IS NULL OR @GiaTri IS NULL)
        THROW 51262, 'Vui lòng nhập đủ mã, nhóm, tên và giá trị tham số.', 1;

    IF @MaThamSo IS NULL
        RAISE EXCEPTION %;

    IF @KieuDuLieu IS NOT NULL AND @KieuDuLieu NOT IN ('Chuỗi', 'Số', 'Ngày', 'Boolean')
        RAISE EXCEPTION %;

    DECLARE @KieuDuLieuSau VARCHAR(20);
    DECLARE @GiaTriSau VARCHAR(255);

    IF @ThaoTac = 'TAO'
    BEGIN
        SET @KieuDuLieuSau = COALESCE(@KieuDuLieu, 'Chuỗi');
        SET @GiaTriSau = @GiaTri;
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        SELECT
            @KieuDuLieuSau = COALESCE(@KieuDuLieu, KieuDuLieu),
            @GiaTriSau = COALESCE(@GiaTri, GiaTri)
        FROM dbo.ThamSoHeThong
        WHERE MaThamSo = @MaThamSo;
    END;

    IF @KieuDuLieuSau = 'Số' AND (TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) IS NULL OR TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) < 0)
        RAISE EXCEPTION %;

    IF @MaThamSo = 'THOI_HAN_THANH_TOAN_COC_GIO'
       AND (TRY_CONVERT(INT, @GiaTriSau) IS NULL OR TRY_CONVERT(INT, @GiaTriSau) <= 0)
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        INSERT INTO dbo.ThamSoHeThong (
            MaThamSo, NhomThamSo, TenThamSo, GiaTri, KieuDuLieu, DonViTinh, MoTa, CapNhatBoi
        )
        VALUES (
            @MaThamSo, @NhomThamSo, @TenThamSo, @GiaTriSau, @KieuDuLieuSau, @DonViTinh, @MoTa, @AdminId
        );

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @NoiDung = @TenThamSo;
    END
    ELSE
    BEGIN
        DECLARE @DuLieuTruocThamSo TEXT;
        SELECT @DuLieuTruocThamSo = (
            SELECT * FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.ThamSoHeThong
        SET NhomThamSo = COALESCE(@NhomThamSo, NhomThamSo),
            TenThamSo = COALESCE(@TenThamSo, TenThamSo),
            GiaTri = @GiaTriSau,
            KieuDuLieu = @KieuDuLieuSau,
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            MoTa = COALESCE(@MoTa, MoTa),
            CapNhatLuc = CURRENT_TIMESTAMP,
            CapNhatBoi = @AdminId
        WHERE MaThamSo = @MaThamSo;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @DuLieuTruoc = @DuLieuTruocThamSo;
    END;

    EXEC dbo.SP_Admin_CauHinhThamSo @ThaoTac = 'DANH_SACH', @MaThamSo = @MaThamSo;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhSaoLuu
    @ChuKyFull        VARCHAR(20)  = NULL,
    @ChuKyIncremental VARCHAR(20)  = NULL,
    @ThuMucLuuTru     VARCHAR(500) = NULL,
    @AdminId          VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ChuKyFull = NULLIF(TRIM(@ChuKyFull)), '');
    SET @ChuKyIncremental = NULLIF(TRIM(@ChuKyIncremental)), '');
    SET @ThuMucLuuTru = NULLIF(TRIM(@ThuMucLuuTru)), '');

    IF @ChuKyFull IS NOT NULL AND @ChuKyFull NOT IN ('Hàng tuần', 'Hàng tháng')
        RAISE EXCEPTION %;

    IF @ChuKyIncremental IS NOT NULL AND @ChuKyIncremental NOT IN ('Hàng ngày', 'Hàng tuần')
        RAISE EXCEPTION %;

    IF @ThuMucLuuTru IS NOT NULL
    BEGIN
        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);
    END;

    IF @ChuKyFull IS NULL AND @ChuKyIncremental IS NULL AND @ThuMucLuuTru IS NULL
    BEGIN
        SELECT
            MaCauHinh AS maCauHinh,
            ChuKyFull AS chuKyFull,
            ChuKyIncremental AS chuKyIncremental,
            ThuMucLuuTru AS thuMucLuuTru,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;
        RETURN;
    END;

    DECLARE @DuLieuTruocSaoLuu TEXT;
    SELECT @DuLieuTruocSaoLuu = (
        SELECT * FROM dbo.CauHinhSaoLuu WHERE MaCauHinh = 1 FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    UPDATE dbo.CauHinhSaoLuu
    SET ChuKyFull = COALESCE(@ChuKyFull, ChuKyFull),
        ChuKyIncremental = COALESCE(@ChuKyIncremental, ChuKyIncremental),
        ThuMucLuuTru = COALESCE(@ThuMucLuuTru, ThuMucLuuTru),
        CapNhatLuc = CURRENT_TIMESTAMP,
        CapNhatBoi = @AdminId
    WHERE MaCauHinh = 1;

    EXEC dbo.SP_Admin_GhiNhatKy
        @AdminId = @AdminId,
        @HanhDong = 'Cấu hình sao lưu',
        @DoiTuong = 'CauHinhSaoLuu',
        @MaDoiTuong = '1',
        @DuLieuTruoc = @DuLieuTruocSaoLuu;

    SELECT
        MaCauHinh AS maCauHinh,
        ChuKyFull AS chuKyFull,
        ChuKyIncremental AS chuKyIncremental,
        ThuMucLuuTru AS thuMucLuuTru,
        CapNhatLuc AS capNhatLuc,
        CapNhatBoi AS capNhatBoi
    FROM dbo.CauHinhSaoLuu
    WHERE MaCauHinh = 1;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_SaoLuuThuCong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_SaoLuuThuCong
    @LoaiSaoLuu  VARCHAR(20)  = 'Full',
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    

    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');
    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');
    IF @LoaiSaoLuu IS NULL SET @LoaiSaoLuu = 'Full';

    DECLARE @LoaiSaoLuuChuan VARCHAR(20) = UPPER(@LoaiSaoLuu);
    IF @LoaiSaoLuuChuan = 'FULL'
        SET @LoaiSaoLuu = 'Full';
    ELSE IF @LoaiSaoLuuChuan IN ('INCREMENTAL', 'DIFFERENTIAL')
        SET @LoaiSaoLuu = 'Incremental';

    IF @LoaiSaoLuu NOT IN ('Full', 'Incremental')
        RAISE EXCEPTION %;

    IF @DuongDanFile IS NULL
    BEGIN
        DECLARE @ThuMucLuuTru VARCHAR(500);
        SELECT @ThuMucLuuTru = ThuMucLuuTru
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;

        IF @ThuMucLuuTru IS NULL
            RAISE EXCEPTION %;

        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);

        SET @DuongDanFile =
            @ThuMucLuuTru + '\' + DB_NAME() + '_' + @LoaiSaoLuu + '_' +
            CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112) + REPLACE(CONVERT(CHAR(8), CURRENT_TIMESTAMP, 108), ':', '') + '.bak';
    END;

    DECLARE @MaSaoLuu INT;
    DECLARE @LenhSaoLuu TEXT;

    INSERT INTO dbo.LichSuSaoLuu (
        LoaiSaoLuu, DuongDanFile, TrangThai, ThoiGianBatDau, MaNguoiDung
    )
    VALUES (
        @LoaiSaoLuu, @DuongDanFile, 'Đang chạy', CURRENT_TIMESTAMP, @AdminId
    );

    SET @MaSaoLuu = SCOPE_IDENTITY();
    SET @LenhSaoLuu =
        'BACKUP DATABASE ' + QUOTENAME(DB_NAME()) +
        ' TO DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') +
        ''' WITH ' +
        CASE WHEN @LoaiSaoLuu = 'Incremental' THEN 'DIFFERENTIAL, INIT' ELSE 'INIT' END +
        ';';

    BEGIN TRY
        EXEC(@LenhSaoLuu);

        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thành công',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = 'Sao lưu hoàn tất.'
        WHERE MaSaoLuu = @MaSaoLuu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Sao lưu thủ công',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thất bại',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = ERROR_MESSAGE()
        WHERE MaSaoLuu = @MaSaoLuu;

        THROW;
    END CATCH;

    SELECT
        MaSaoLuu AS maSaoLuu,
        LoaiSaoLuu AS loaiSaoLuu,
        DuongDanFile AS duongDanFile,
        TrangThai AS trangThai,
        ThoiGianBatDau AS thoiGianBatDau,
        ThoiGianKetThuc AS thoiGianKetThuc,
        ThongBao AS thongBao
    FROM dbo.LichSuSaoLuu
    WHERE MaSaoLuu = @MaSaoLuu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_DanhSachSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_DanhSachSaoLuu
    @SoDong     INT          = 100,
    @TrangThai  VARCHAR(20) = NULL,
    @LoaiSaoLuu VARCHAR(20) = NULL
AS
BEGIN
    

    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 100;

    SELECT TOP (@SoDong)
        ls.MaSaoLuu AS maSaoLuu,
        ls.LoaiSaoLuu AS loaiSaoLuu,
        ls.DuongDanFile AS duongDanFile,
        ls.DungLuongByte AS dungLuongByte,
        ls.TrangThai AS trangThai,
        ls.ThoiGianBatDau AS thoiGianBatDau,
        ls.ThoiGianKetThuc AS thoiGianKetThuc,
        ls.ThongBao AS thongBao,
        ls.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung
    FROM dbo.LichSuSaoLuu AS ls
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = ls.MaNguoiDung
    WHERE (@TrangThai IS NULL OR ls.TrangThai = @TrangThai)
      AND (@LoaiSaoLuu IS NULL OR ls.LoaiSaoLuu = @LoaiSaoLuu)
    ORDER BY ls.ThoiGianBatDau DESC, ls.MaSaoLuu DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_PhucHoiDuLieu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_PhucHoiDuLieu
    @MaSaoLuu    INT           = NULL,
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL,
    @ChiTaoLenh   BOOLEAN           = 1
AS
BEGIN
    

    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');

    IF @DuongDanFile IS NULL AND @MaSaoLuu IS NOT NULL
    BEGIN
        SELECT @DuongDanFile = DuongDanFile
        FROM dbo.LichSuSaoLuu
        WHERE MaSaoLuu = @MaSaoLuu
          AND TrangThai = 'Thành công';
    END;

    IF @DuongDanFile IS NULL
        RAISE EXCEPTION %;

    DECLARE @TenDatabase SYSNAME = DB_NAME();
    DECLARE @LenhSingleUser TEXT;
    DECLARE @LenhRestore TEXT;
    DECLARE @LenhMultiUser TEXT;
    DECLARE @LenhDayDu TEXT;

    SET @LenhSingleUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET SINGLE_USER WITH ROLLBACK IMMEDIATE;';
    SET @LenhRestore = 'USE [master]; RESTORE DATABASE ' + QUOTENAME(@TenDatabase) +
        ' FROM DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') + ''' WITH REPLACE;';
    SET @LenhMultiUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET MULTI_USER;';
    SET @LenhDayDu = @LenhSingleUser + CHAR(13) + CHAR(10) + @LenhRestore + CHAR(13) + CHAR(10) + @LenhMultiUser;

    IF @ChiTaoLenh = 1
    BEGIN
        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo lệnh phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;

        SELECT
            @TenDatabase AS tenDatabase,
            @DuongDanFile AS duongDanFile,
            @LenhDayDu AS lenhPhucHoi,
            CAST(1 AS BOOLEAN) AS chiTaoLenh;
        RETURN;
    END;

    BEGIN TRY
        EXEC(@LenhSingleUser);
        EXEC(@LenhRestore);
        EXEC(@LenhMultiUser);

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        BEGIN TRY
            EXEC(@LenhMultiUser);
        END TRY
        BEGIN CATCH
        END CATCH;

        THROW;
    END CATCH;

    SELECT
        @TenDatabase AS tenDatabase,
        @DuongDanFile AS duongDanFile,
        CAST(1 AS BOOLEAN) AS daPhucHoi;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_XemNhatKyHeThong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_XemNhatKyHeThong
    @TuNgay     TIMESTAMP  = NULL,
    @DenNgay    TIMESTAMP  = NULL,
    @AdminId    VARCHAR(6)    = NULL,
    @DoiTuong   VARCHAR(100) = NULL,
    @HanhDong   VARCHAR(100) = NULL,
    @TuKhoa     VARCHAR(100) = NULL,
    @SoDong     INT           = 200
AS
BEGIN
    

    SET @AdminId = NULLIF(TRIM(@AdminId)), '');
    SET @DoiTuong = NULLIF(TRIM(@DoiTuong)), '');
    SET @HanhDong = NULLIF(TRIM(@HanhDong)), '');
    SET @TuKhoa = NULLIF(TRIM(@TuKhoa)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 200;

    SELECT TOP (@SoDong)
        nk.MaNhatKy AS maNhatKy,
        nk.ThoiGian AS thoiGian,
        nk.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung,
        nk.VaiTro AS vaiTro,
        nk.ChucNang AS chucNang,
        nk.HanhDong AS hanhDong,
        nk.DoiTuong AS doiTuong,
        nk.MaDoiTuong AS maDoiTuong,
        nk.NoiDung AS noiDung,
        nk.DuLieuTruoc AS duLieuTruoc,
        nk.DuLieuSau AS duLieuSau
    FROM dbo.NhatKyHeThong AS nk
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nk.MaNguoiDung
    WHERE (@TuNgay IS NULL OR nk.ThoiGian >= @TuNgay)
      AND (@DenNgay IS NULL OR nk.ThoiGian < DATEADD(DAY, 1, @DenNgay))
      AND (@AdminId IS NULL OR nk.MaNguoiDung = @AdminId)
      AND (@DoiTuong IS NULL OR nk.DoiTuong = @DoiTuong)
      AND (@HanhDong IS NULL OR nk.HanhDong LIKE '%' + @HanhDong + '%')
      AND (
          @TuKhoa IS NULL
          OR nk.NoiDung LIKE '%' + @TuKhoa + '%'
          OR nk.MaDoiTuong LIKE '%' + @TuKhoa + '%'
          OR nk.HanhDong LIKE '%' + @TuKhoa + '%'
      )
    ORDER BY nk.ThoiGian DESC, nk.MaNhatKy DESC;
END; THEN (SUBSTRING(MaChiNhanh, 3, 4)::INT ELSE NULL END)), 0) + 1
                FROM dbo.ChiNhanh 
                WHERE MaChiNhanh LIKE 'CN[0-9][0-9][0-9][0-9]';

                IF @SoChiNhanh > 9999
                    RAISE EXCEPTION %;

                SET @MaChiNhanh = CONCAT('C', RIGHT(CONCAT('0000', @SoChiNhanh), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
                RAISE EXCEPTION %;

            INSERT INTO dbo.ChiNhanh (MaChiNhanh, TenChiNhanh, DiaChi, SDT, Email, TrangThai)
            VALUES (@MaChiNhanh, @TenChiNhanh, @DiaChi, @SDT, @Email, COALESCE(@TrangThai, 'Hoạt động'));

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo chi nhánh',
                @DoiTuong = 'ChiNhanh',
                @MaDoiTuong = @MaChiNhanh,
                @NoiDung = @TenChiNhanh;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE
    BEGIN
        IF @MaChiNhanh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
            RAISE EXCEPTION %;

        IF @ThaoTac = 'DOI_TRANG_THAI' AND @TrangThai IS NULL
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocChiNhanh TEXT;
        SELECT @DuLieuTruocChiNhanh = (
            SELECT * FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        IF @ThaoTac = 'XOA'
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.NhanVien WHERE MaChiNhanh = @MaChiNhanh)
               OR EXISTS (SELECT 1 FROM dbo.Phong WHERE MaChiNhanh = @MaChiNhanh)
                RAISE EXCEPTION %;

            DELETE FROM dbo.ChiNhanh
            WHERE MaChiNhanh = @MaChiNhanh;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa chi nhánh',
                @DoiTuong = 'ChiNhanh',
                @MaDoiTuong = @MaChiNhanh,
                @DuLieuTruoc = @DuLieuTruocChiNhanh;

            SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaChiNhanh AS maChiNhanh;
            RETURN;
        END;

        UPDATE dbo.ChiNhanh
        SET TenChiNhanh = CASE WHEN @ThaoTac = 'CAP_NHAT' THEN COALESCE(@TenChiNhanh, TenChiNhanh) ELSE TenChiNhanh END,
            DiaChi = CASE WHEN @ThaoTac = 'CAP_NHAT' THEN COALESCE(@DiaChi, DiaChi) ELSE DiaChi END,
            SDT = CASE WHEN @ThaoTac = 'CAP_NHAT' THEN COALESCE(@SDT, SDT) ELSE SDT END,
            Email = CASE WHEN @ThaoTac = 'CAP_NHAT' THEN COALESCE(@Email, Email) ELSE Email END,
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaChiNhanh = @MaChiNhanh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật chi nhánh',
            @DoiTuong = 'ChiNhanh',
            @MaDoiTuong = @MaChiNhanh,
            @NoiDung = @ThaoTac,
            @DuLieuTruoc = @DuLieuTruocChiNhanh;
    END;

    EXEC dbo.SP_Admin_QuanLyChiNhanh @ThaoTac = 'DANH_SACH', @MaChiNhanh = @MaChiNhanh;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyLoaiPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyLoaiPhong
    @ThaoTac             VARCHAR(20)  = 'DANH_SACH',
    @MaLoaiPhong         VARCHAR(6)    = NULL,
    @TenLoaiPhong        VARCHAR(100) = NULL,
    @SucChuaToiDa        INT           = NULL,
    @MoTa                TEXT = NULL,
    @GiaThueTheoGiuong   DECIMAL(15,2) = NULL,
    @GiaThueNguyenPhong  DECIMAL(15,2) = NULL,
    @AdminId             VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaLoaiPhong = NULLIF(TRIM(@MaLoaiPhong)), '');
    SET @TenLoaiPhong = NULLIF(TRIM(@TenLoaiPhong)), '');
    SET @MoTa = NULLIF(TRIM(@MoTa)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            lp.MaLoaiPhong AS maLoaiPhong,
            lp.TenLoaiPhong AS tenLoaiPhong,
            lp.SucChuaToiDa AS sucChuaToiDa,
            lp.MoTa AS moTa,
            lp.GiaThueTheoGiuong AS giaThueTheoGiuong,
            lp.GiaThueNguyenPhong AS giaThueNguyenPhong,
            COUNT(p.MaPhong) AS soPhong
        FROM dbo.LoaiPhong AS lp
        LEFT JOIN dbo.Phong AS p ON p.MaLoaiPhong = lp.MaLoaiPhong
        WHERE (@MaLoaiPhong IS NULL OR lp.MaLoaiPhong = @MaLoaiPhong)
        GROUP BY lp.MaLoaiPhong, lp.TenLoaiPhong, lp.SucChuaToiDa, lp.MoTa, lp.GiaThueTheoGiuong, lp.GiaThueNguyenPhong
        ORDER BY lp.MaLoaiPhong;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenLoaiPhong IS NULL OR @SucChuaToiDa IS NULL)
            RAISE EXCEPTION %;

        IF @SucChuaToiDa IS NOT NULL AND @SucChuaToiDa < 1
            RAISE EXCEPTION %;

        IF @GiaThueTheoGiuong IS NOT NULL AND @GiaThueTheoGiuong < 0
            RAISE EXCEPTION %;

        IF @GiaThueNguyenPhong IS NOT NULL AND @GiaThueNguyenPhong < 0
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoLoaiPhong INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaLoaiPhong IS NULL
            BEGIN
                SELECT @SoLoaiPhong = COALESCE(MAX(CASE WHEN (SUBSTRING(MaLoaiPhong, 3, 4) ~ '^[0-9]+)), 0) + 1
                FROM dbo.LoaiPhong 
                WHERE MaLoaiPhong LIKE 'LP[0-9][0-9][0-9][0-9]';

                IF @SoLoaiPhong > 9999
                    RAISE EXCEPTION %;

                SET @MaLoaiPhong = CONCAT('LP', RIGHT(CONCAT('0000', @SoLoaiPhong), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
                RAISE EXCEPTION %;

            INSERT INTO dbo.LoaiPhong (
                MaLoaiPhong, TenLoaiPhong, SucChuaToiDa, MoTa, GiaThueTheoGiuong, GiaThueNguyenPhong
            )
            VALUES (
                @MaLoaiPhong, @TenLoaiPhong, @SucChuaToiDa, @MoTa, @GiaThueTheoGiuong, @GiaThueNguyenPhong
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo loại phòng',
                @DoiTuong = 'LoaiPhong',
                @MaDoiTuong = @MaLoaiPhong,
                @NoiDung = @TenLoaiPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaLoaiPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocLoaiPhong TEXT;
        SELECT @DuLieuTruocLoaiPhong = (
            SELECT * FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        IF @SucChuaToiDa IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.Phong AS p
            WHERE p.MaLoaiPhong = @MaLoaiPhong
              AND (
                  SELECT COUNT(1)
                  FROM dbo.Giuong AS g
                  WHERE g.MaPhong = p.MaPhong
              ) > @SucChuaToiDa
        )
            RAISE EXCEPTION %;

        UPDATE dbo.LoaiPhong
        SET TenLoaiPhong = COALESCE(@TenLoaiPhong, TenLoaiPhong),
            SucChuaToiDa = COALESCE(@SucChuaToiDa, SucChuaToiDa),
            MoTa = COALESCE(@MoTa, MoTa),
            GiaThueTheoGiuong = COALESCE(@GiaThueTheoGiuong, GiaThueTheoGiuong),
            GiaThueNguyenPhong = COALESCE(@GiaThueNguyenPhong, GiaThueNguyenPhong)
        WHERE MaLoaiPhong = @MaLoaiPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật loại phòng',
            @DoiTuong = 'LoaiPhong',
            @MaDoiTuong = @MaLoaiPhong,
            @DuLieuTruoc = @DuLieuTruocLoaiPhong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaLoaiPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        DELETE FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa loại phòng',
            @DoiTuong = 'LoaiPhong',
            @MaDoiTuong = @MaLoaiPhong;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaLoaiPhong AS maLoaiPhong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyLoaiPhong @ThaoTac = 'DANH_SACH', @MaLoaiPhong = @MaLoaiPhong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_TaoPhongGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_TaoPhongGiuong
    @MaPhong         VARCHAR(4)    = NULL,
    @TenPhong        VARCHAR(100),
    @GioiTinhChoPhep VARCHAR(20),
    @MaChiNhanh      VARCHAR(6),
    @MaLoaiPhong     VARCHAR(6),
    @TinhTrang       VARCHAR(20)  = 'Trống',
    @UrlImg          VARCHAR(500)  = NULL,
    @SoGiuong        INT           = NULL,
    @AdminId         VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @TenPhong = NULLIF(TRIM(@TenPhong)), '');
    SET @GioiTinhChoPhep = NULLIF(TRIM(@GioiTinhChoPhep)), '');
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @MaLoaiPhong = NULLIF(TRIM(@MaLoaiPhong)), '');
    SET @TinhTrang = COALESCE(NULLIF(TRIM(@TinhTrang)), ''), 'Trống');
    EXEC dbo.SP_Admin_QuanLyChiNhanh @ThaoTac = 'DANH_SACH', @MaChiNhanh = @MaChiNhanh;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyLoaiPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyLoaiPhong
    @ThaoTac             VARCHAR(20)  = 'DANH_SACH',
    @MaLoaiPhong         VARCHAR(6)    = NULL,
    @TenLoaiPhong        VARCHAR(100) = NULL,
    @SucChuaToiDa        INT           = NULL,
    @MoTa                TEXT = NULL,
    @GiaThueTheoGiuong   DECIMAL(15,2) = NULL,
    @GiaThueNguyenPhong  DECIMAL(15,2) = NULL,
    @AdminId             VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaLoaiPhong = NULLIF(TRIM(@MaLoaiPhong)), '');
    SET @TenLoaiPhong = NULLIF(TRIM(@TenLoaiPhong)), '');
    SET @MoTa = NULLIF(TRIM(@MoTa)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            lp.MaLoaiPhong AS maLoaiPhong,
            lp.TenLoaiPhong AS tenLoaiPhong,
            lp.SucChuaToiDa AS sucChuaToiDa,
            lp.MoTa AS moTa,
            lp.GiaThueTheoGiuong AS giaThueTheoGiuong,
            lp.GiaThueNguyenPhong AS giaThueNguyenPhong,
            COUNT(p.MaPhong) AS soPhong
        FROM dbo.LoaiPhong AS lp
        LEFT JOIN dbo.Phong AS p ON p.MaLoaiPhong = lp.MaLoaiPhong
        WHERE (@MaLoaiPhong IS NULL OR lp.MaLoaiPhong = @MaLoaiPhong)
        GROUP BY lp.MaLoaiPhong, lp.TenLoaiPhong, lp.SucChuaToiDa, lp.MoTa, lp.GiaThueTheoGiuong, lp.GiaThueNguyenPhong
        ORDER BY lp.MaLoaiPhong;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenLoaiPhong IS NULL OR @SucChuaToiDa IS NULL)
            RAISE EXCEPTION %;

        IF @SucChuaToiDa IS NOT NULL AND @SucChuaToiDa < 1
            RAISE EXCEPTION %;

        IF @GiaThueTheoGiuong IS NOT NULL AND @GiaThueTheoGiuong < 0
            RAISE EXCEPTION %;

        IF @GiaThueNguyenPhong IS NOT NULL AND @GiaThueNguyenPhong < 0
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoLoaiPhong INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaLoaiPhong IS NULL
            BEGIN
                SELECT @SoLoaiPhong = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaLoaiPhong, 3, 4))), 0) + 1
                FROM dbo.LoaiPhong 
                WHERE MaLoaiPhong LIKE 'LP[0-9][0-9][0-9][0-9]';

                IF @SoLoaiPhong > 9999
                    RAISE EXCEPTION %;

                SET @MaLoaiPhong = CONCAT('LP', RIGHT(CONCAT('0000', @SoLoaiPhong), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
                RAISE EXCEPTION %;

            INSERT INTO dbo.LoaiPhong (
                MaLoaiPhong, TenLoaiPhong, SucChuaToiDa, MoTa, GiaThueTheoGiuong, GiaThueNguyenPhong
            )
            VALUES (
                @MaLoaiPhong, @TenLoaiPhong, @SucChuaToiDa, @MoTa, @GiaThueTheoGiuong, @GiaThueNguyenPhong
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo loại phòng',
                @DoiTuong = 'LoaiPhong',
                @MaDoiTuong = @MaLoaiPhong,
                @NoiDung = @TenLoaiPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaLoaiPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocLoaiPhong TEXT;
        SELECT @DuLieuTruocLoaiPhong = (
            SELECT * FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        IF @SucChuaToiDa IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.Phong AS p
            WHERE p.MaLoaiPhong = @MaLoaiPhong
              AND (
                  SELECT COUNT(1)
                  FROM dbo.Giuong AS g
                  WHERE g.MaPhong = p.MaPhong
              ) > @SucChuaToiDa
        )
            RAISE EXCEPTION %;

        UPDATE dbo.LoaiPhong
        SET TenLoaiPhong = COALESCE(@TenLoaiPhong, TenLoaiPhong),
            SucChuaToiDa = COALESCE(@SucChuaToiDa, SucChuaToiDa),
            MoTa = COALESCE(@MoTa, MoTa),
            GiaThueTheoGiuong = COALESCE(@GiaThueTheoGiuong, GiaThueTheoGiuong),
            GiaThueNguyenPhong = COALESCE(@GiaThueNguyenPhong, GiaThueNguyenPhong)
        WHERE MaLoaiPhong = @MaLoaiPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật loại phòng',
            @DoiTuong = 'LoaiPhong',
            @MaDoiTuong = @MaLoaiPhong,
            @DuLieuTruoc = @DuLieuTruocLoaiPhong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaLoaiPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        DELETE FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa loại phòng',
            @DoiTuong = 'LoaiPhong',
            @MaDoiTuong = @MaLoaiPhong;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaLoaiPhong AS maLoaiPhong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyLoaiPhong @ThaoTac = 'DANH_SACH', @MaLoaiPhong = @MaLoaiPhong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_TaoPhongGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_TaoPhongGiuong
    @MaPhong         VARCHAR(4)    = NULL,
    @TenPhong        VARCHAR(100),
    @GioiTinhChoPhep VARCHAR(20),
    @MaChiNhanh      VARCHAR(6),
    @MaLoaiPhong     VARCHAR(6),
    @TinhTrang       VARCHAR(20)  = 'Trống',
    @UrlImg          VARCHAR(500)  = NULL,
    @SoGiuong        INT           = NULL,
    @AdminId         VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @TenPhong = NULLIF(TRIM(@TenPhong)), '');
    SET @GioiTinhChoPhep = NULLIF(TRIM(@GioiTinhChoPhep)), '');
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @MaLoaiPhong = NULLIF(TRIM(@MaLoaiPhong)), '');
    SET @TinhTrang = COALESCE(NULLIF(TRIM(@TinhTrang)), ''), 'Trống');
    SET @UrlImg = NULLIF(TRIM(@UrlImg)), '');

    IF @TenPhong IS NULL OR @GioiTinhChoPhep IS NULL OR @MaChiNhanh IS NULL OR @MaLoaiPhong IS NULL
        THROW 51061, 'Vui lòng nhập tên phòng, giới tính, chi nhánh và loại phòng.', 1;

    IF @GioiTinhChoPhep NOT IN ('Nam', 'Nữ', 'Không phân biệt')
        RAISE EXCEPTION %;

    IF @TinhTrang NOT IN ('Trống', 'Đã đặt cọc', 'Còn chỗ', 'Đầy', 'Giữ chỗ')
        RAISE EXCEPTION %;

    IF NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
        RAISE EXCEPTION %;

    IF NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
        RAISE EXCEPTION %;

    DECLARE @SucChuaLoaiPhong INT;
    SELECT @SucChuaLoaiPhong = SucChuaToiDa
    FROM dbo.LoaiPhong
    WHERE MaLoaiPhong = @MaLoaiPhong;

    IF @SoGiuong IS NULL
        SET @SoGiuong = @SucChuaLoaiPhong;

    IF @SoGiuong < 1 OR @SoGiuong > 99
        RAISE EXCEPTION %;

    IF @SoGiuong > @SucChuaLoaiPhong
        RAISE EXCEPTION %;

    DECLARE @SoPhong INT;
    DECLARE @SoChiNhanh INT = TRY_CONVERT(INT, SUBSTRING(@MaChiNhanh, 3, 4));
    DECLARE @Index INT = 1;
    DECLARE @MaGiuong VARCHAR(3);

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @MaPhong IS NULL
        BEGIN
            IF @SoChiNhanh IS NULL OR @SoChiNhanh NOT BETWEEN 1 AND 9
                RAISE EXCEPTION %;

            SELECT @SoPhong = COALESCE(MAX(TRY_CONVERT(INT, RIGHT(MaPhong, 2))), 0) + 1
            FROM dbo.Phong 
            WHERE MaChiNhanh = @MaChiNhanh
              AND MaPhong LIKE CONCAT('P', @SoChiNhanh, '[0-9][0-9]');

            IF @SoPhong > 99
                RAISE EXCEPTION %;

            SET @MaPhong = CONCAT('P', @SoChiNhanh, RIGHT(CONCAT('00', @SoPhong), 2));
        END;

        IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        INSERT INTO dbo.Phong (MaPhong, TenPhong, GioiTinhChoPhep, TinhTrang, MaChiNhanh, MaLoaiPhong)
        VALUES (@MaPhong, @TenPhong, @GioiTinhChoPhep, @TinhTrang, @MaChiNhanh, @MaLoaiPhong);

        IF @UrlImg IS NOT NULL
        BEGIN
            INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
            VALUES (@MaPhong, 1, @UrlImg);
        END;

        WHILE @Index <= @SoGiuong
        BEGIN
            SET @MaGiuong = CONCAT('G', RIGHT(CONCAT('00', @Index), 2));

            INSERT INTO dbo.Giuong (MaPhong, MaGiuong, SoGiuong, TinhTrang)
            VALUES (@MaPhong, @MaGiuong, @Index, 'Trống');

            SET @Index += 1;
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo phòng giường',
            @DoiTuong = 'Phong',
            @MaDoiTuong = @MaPhong,
            @NoiDung = @TenPhong;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        p.MaPhong AS maPhong,
        p.TenPhong AS tenPhong,
        p.GioiTinhChoPhep AS gioiTinhChoPhep,
        p.TinhTrang AS tinhTrangPhong,
        (SELECT TOP 1 hap.UrlImg FROM dbo.HinhAnhPhong AS hap WHERE hap.MaPhong = p.MaPhong ORDER BY hap.STTAnh) AS urlImgPhong,
        p.MaChiNhanh AS maChiNhanh,
        cn.TenChiNhanh AS tenChiNhanh,
        p.MaLoaiPhong AS maLoaiPhong,
        lp.TenLoaiPhong AS tenLoaiPhong,
        g.MaGiuong AS maGiuong,
        g.SoGiuong AS soGiuong,
        g.TinhTrang AS tinhTrangGiuong
    FROM dbo.Phong AS p
    INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    LEFT JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
    WHERE p.MaPhong = @MaPhong
    ORDER BY g.SoGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CapNhatTrangThaiPhongGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CapNhatTrangThaiPhongGiuong
    @LoaiDoiTuong VARCHAR(20),
    @MaPhong      VARCHAR(4),
    @MaGiuong     VARCHAR(3)   = NULL,
    @TrangThai    VARCHAR(20),
    @AdminId      VARCHAR(6)   = NULL
AS
BEGIN
    
    

    SET @LoaiDoiTuong = UPPER(NULLIF(TRIM(@LoaiDoiTuong)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');

    IF @LoaiDoiTuong NOT IN ('PHONG', 'GIUONG')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @LoaiDoiTuong = 'PHONG' AND @TrangThai NOT IN ('Trống', 'Đã đặt cọc', 'Còn chỗ', 'Đầy', 'Giữ chỗ', 'Bảo trì')
        RAISE EXCEPTION %;

    IF @LoaiDoiTuong = 'GIUONG' AND @TrangThai NOT IN ('Trống', 'Đã đặt cọc', 'Đang thuê')
        RAISE EXCEPTION %;

    IF @LoaiDoiTuong = 'GIUONG'
       AND (@MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
       ))
        RAISE EXCEPTION %;

    DECLARE @DuLieuTruoc TEXT;

    IF @LoaiDoiTuong = 'PHONG'
        SELECT @DuLieuTruoc = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );
    ELSE
        SELECT @DuLieuTruoc = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @LoaiDoiTuong = 'PHONG'
        BEGIN
            UPDATE dbo.Phong
            SET TinhTrang = @TrangThai
            WHERE MaPhong = @MaPhong;
        END
        ELSE
        BEGIN
            UPDATE dbo.Giuong
            SET TinhTrang = @TrangThai
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong;

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (
                    SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống'
                ) THEN 'Trống'
                WHEN NOT EXISTS (
                    SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống'
                ) THEN 'Đầy'
                WHEN EXISTS (
                    SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Đã đặt cọc'
                ) THEN 'Còn chỗ'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật trạng thái phòng/giường',
            @DoiTuong = @LoaiDoiTuong,
            @MaDoiTuong = @MaPhong,
            @NoiDung = @TrangThai,
            @DuLieuTruoc = @DuLieuTruoc;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        p.MaPhong AS maPhong,
        p.TenPhong AS tenPhong,
        p.TinhTrang AS tinhTrangPhong,
        g.MaGiuong AS maGiuong,
        g.SoGiuong AS soGiuong,
        g.TinhTrang AS tinhTrangGiuong
    FROM dbo.Phong AS p
    LEFT JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
    WHERE p.MaPhong = @MaPhong
      AND (@MaGiuong IS NULL OR g.MaGiuong = @MaGiuong)
    ORDER BY g.SoGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyPhong
    @ThaoTac         VARCHAR(20)  = 'DANH_SACH',
    @MaPhong         VARCHAR(4)    = NULL,
    @TenPhong        VARCHAR(100) = NULL,
    @GioiTinhChoPhep VARCHAR(20)  = NULL,
    @TinhTrang       VARCHAR(20)  = NULL,
    @UrlImg          VARCHAR(500)  = NULL,
    @MaChiNhanh      VARCHAR(6)    = NULL,
    @MaLoaiPhong     VARCHAR(6)    = NULL,
    @AdminId         VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @TenPhong = NULLIF(TRIM(@TenPhong)), '');
    SET @GioiTinhChoPhep = NULLIF(TRIM(@GioiTinhChoPhep)), '');
    SET @TinhTrang = NULLIF(TRIM(@TinhTrang)), '');
    SET @UrlImg = NULLIF(TRIM(@UrlImg)), '');
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @MaLoaiPhong = NULLIF(TRIM(@MaLoaiPhong)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            p.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            p.GioiTinhChoPhep AS gioiTinhChoPhep,
            p.TinhTrang AS tinhTrang,
            (SELECT TOP 1 hap.UrlImg FROM dbo.HinhAnhPhong AS hap WHERE hap.MaPhong = p.MaPhong ORDER BY hap.STTAnh) AS urlImg,
            p.MaChiNhanh AS maChiNhanh,
            cn.TenChiNhanh AS tenChiNhanh,
            p.MaLoaiPhong AS maLoaiPhong,
            lp.TenLoaiPhong AS tenLoaiPhong,
            COUNT(g.MaGiuong) AS soGiuong,
            SUM(CASE WHEN g.TinhTrang = 'Trống' THEN 1 ELSE 0 END) AS soGiuongTrong
        FROM dbo.Phong AS p
        INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
        INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
        LEFT JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
        WHERE (@MaPhong IS NULL OR p.MaPhong = @MaPhong)
          AND (@MaChiNhanh IS NULL OR p.MaChiNhanh = @MaChiNhanh)
          AND (@MaLoaiPhong IS NULL OR p.MaLoaiPhong = @MaLoaiPhong)
          AND (@TinhTrang IS NULL OR p.TinhTrang = @TinhTrang)
        GROUP BY p.MaPhong, p.TenPhong, p.GioiTinhChoPhep, p.TinhTrang,
                 p.MaChiNhanh, cn.TenChiNhanh, p.MaLoaiPhong, lp.TenLoaiPhong
        ORDER BY p.MaPhong;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO'
           AND (@TenPhong IS NULL OR @GioiTinhChoPhep IS NULL OR @MaChiNhanh IS NULL OR @MaLoaiPhong IS NULL)
            THROW 51102, 'Vui lòng nhập đầy đủ tên phòng, giới tính, chi nhánh và loại phòng.', 1;

        IF @GioiTinhChoPhep IS NOT NULL AND @GioiTinhChoPhep NOT IN ('Nam', 'Nữ', 'Không phân biệt')
            RAISE EXCEPTION %;

        IF @TinhTrang IS NOT NULL AND @TinhTrang NOT IN ('Trống', 'Đã đặt cọc', 'Còn chỗ', 'Đầy', 'Giữ chỗ', 'Bảo trì')
            RAISE EXCEPTION %;

        IF @MaChiNhanh IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
            RAISE EXCEPTION %;

        IF @MaLoaiPhong IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoPhongMoi INT;
        DECLARE @SoChiNhanhPhong INT = TRY_CONVERT(INT, SUBSTRING(@MaChiNhanh, 3, 4));

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaPhong IS NULL
            BEGIN
                IF @SoChiNhanhPhong IS NULL OR @SoChiNhanhPhong NOT BETWEEN 1 AND 9
                    RAISE EXCEPTION %;

                SELECT @SoPhongMoi = COALESCE(MAX(TRY_CONVERT(INT, RIGHT(MaPhong, 2))), 0) + 1
                FROM dbo.Phong 
                WHERE MaChiNhanh = @MaChiNhanh
                  AND MaPhong LIKE CONCAT('P', @SoChiNhanhPhong, '[0-9][0-9]');

                IF @SoPhongMoi > 99
                    RAISE EXCEPTION %;

                SET @MaPhong = CONCAT('P', @SoChiNhanhPhong, RIGHT(CONCAT('00', @SoPhongMoi), 2));
            END;

            IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
                RAISE EXCEPTION %;

            INSERT INTO dbo.Phong (MaPhong, TenPhong, GioiTinhChoPhep, TinhTrang, MaChiNhanh, MaLoaiPhong)
            VALUES (@MaPhong, @TenPhong, @GioiTinhChoPhep, COALESCE(@TinhTrang, 'Trống'), @MaChiNhanh, @MaLoaiPhong);

            IF @UrlImg IS NOT NULL
            BEGIN
                INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
                VALUES (@MaPhong, 1, @UrlImg);
            END;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo phòng',
                @DoiTuong = 'Phong',
                @MaDoiTuong = @MaPhong,
                @NoiDung = @TenPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocPhong TEXT;
        SELECT @DuLieuTruocPhong = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.Phong
        SET TenPhong = COALESCE(@TenPhong, TenPhong),
            GioiTinhChoPhep = COALESCE(@GioiTinhChoPhep, GioiTinhChoPhep),
            TinhTrang = COALESCE(@TinhTrang, TinhTrang),
            MaChiNhanh = COALESCE(@MaChiNhanh, MaChiNhanh),
            MaLoaiPhong = COALESCE(@MaLoaiPhong, MaLoaiPhong)
        WHERE MaPhong = @MaPhong;

        IF @UrlImg IS NOT NULL
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.HinhAnhPhong WHERE MaPhong = @MaPhong AND STTAnh = 1)
                UPDATE dbo.HinhAnhPhong
                SET UrlImg = @UrlImg
                WHERE MaPhong = @MaPhong AND STTAnh = 1;
            ELSE
                INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
                VALUES (@MaPhong, 1, @UrlImg);
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật phòng',
            @DoiTuong = 'Phong',
            @MaDoiTuong = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocPhong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống')
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc AS ctdc
            INNER JOIN dbo.PhieuDatCoc AS pdc ON pdc.MaPhieuDatCoc = ctdc.MaPhieuDatCoc
            WHERE ctdc.MaPhong = @MaPhong
              AND pdc.TrangThaiCoc IN ('Hiệu lực', 'Đã lập HĐ')
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietDatCoc WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong)
           OR EXISTS (SELECT 1 FROM dbo.ChiTietXemPhong WHERE MaPhong = @MaPhong)
           OR EXISTS (SELECT 1 FROM dbo.PhieuGhiChiSo WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocPhongXoa TEXT;
        SELECT @DuLieuTruocPhongXoa = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        BEGIN TRY
            BEGIN TRANSACTION;

            DELETE FROM dbo.Giuong WHERE MaPhong = @MaPhong;
            DELETE FROM dbo.Phong WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa phòng',
                @DoiTuong = 'Phong',
                @MaDoiTuong = @MaPhong,
                @DuLieuTruoc = @DuLieuTruocPhongXoa;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyPhong @ThaoTac = 'DANH_SACH', @MaPhong = @MaPhong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyGiuong
    @ThaoTac   VARCHAR(20) = 'DANH_SACH',
    @MaPhong   VARCHAR(4)   = NULL,
    @MaGiuong  VARCHAR(3)   = NULL,
    @SoGiuong  INT          = NULL,
    @TinhTrang VARCHAR(20) = NULL,
    @UrlImg    VARCHAR(500) = NULL,
    @AdminId   VARCHAR(6)   = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    SET @TinhTrang = NULLIF(TRIM(@TinhTrang)), '');
    SET @UrlImg = NULLIF(TRIM(@UrlImg)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            g.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            g.MaGiuong AS maGiuong,
            g.SoGiuong AS soGiuong,
            g.TinhTrang AS tinhTrang,
            lp.SucChuaToiDa AS sucChuaToiDa,
            (
                SELECT COUNT(1)
                FROM dbo.TaiSan AS tsChung
                WHERE tsChung.MaPhong = g.MaPhong
                  AND tsChung.LoaiTaiSan = 'Chung'
            ) AS soTaiSanChung,
            CAST(0 AS INT) AS soTaiSanRieng
        FROM dbo.Giuong AS g
        INNER JOIN dbo.Phong AS p ON p.MaPhong = g.MaPhong
        INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
        WHERE (@MaPhong IS NULL OR g.MaPhong = @MaPhong)
          AND (@MaGiuong IS NULL OR g.MaGiuong = @MaGiuong)
          AND (@TinhTrang IS NULL OR g.TinhTrang = @TinhTrang)
        ORDER BY g.MaPhong, g.SoGiuong, g.MaGiuong;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @SoGiuong IS NULL
            RAISE EXCEPTION %;

        IF @SoGiuong IS NOT NULL AND @SoGiuong < 1
            RAISE EXCEPTION %;

        IF @TinhTrang IS NOT NULL AND @TinhTrang NOT IN ('Trống', 'Đã đặt cọc', 'Đang thuê')
            RAISE EXCEPTION %;
    END;

    DECLARE @SucChuaToiDa INT;
    SELECT @SucChuaToiDa = lp.SucChuaToiDa
    FROM dbo.Phong AS p
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    WHERE p.MaPhong = @MaPhong;

    IF @SoGiuong IS NOT NULL AND @SoGiuong > @SucChuaToiDa
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF (SELECT COUNT(*) FROM dbo.Giuong WHERE MaPhong = @MaPhong) >= @SucChuaToiDa
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND SoGiuong = @SoGiuong)
            RAISE EXCEPTION %;

        IF @MaGiuong IS NULL
        BEGIN
            DECLARE @SoMaGiuong INT;
            SELECT @SoMaGiuong = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaGiuong, 2, 2))), 0) + 1
            FROM dbo.Giuong 
            WHERE MaPhong = @MaPhong
              AND MaGiuong LIKE 'G[0-9][0-9]';

            IF @SoMaGiuong > 99
                RAISE EXCEPTION %;

            SET @MaGiuong = CONCAT('G', RIGHT(CONCAT('00', @SoMaGiuong), 2));
        END;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong)
            RAISE EXCEPTION %;

        BEGIN TRY
            BEGIN TRANSACTION;

            INSERT INTO dbo.Giuong (MaPhong, MaGiuong, SoGiuong, TinhTrang)
            VALUES (@MaPhong, @MaGiuong, @SoGiuong, COALESCE(@TinhTrang, 'Trống'));

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo giường',
                @DoiTuong = 'Giuong',
                @MaDoiTuong = @MaGiuong,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF @SoGiuong IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.Giuong
            WHERE MaPhong = @MaPhong
              AND SoGiuong = @SoGiuong
              AND MaGiuong <> @MaGiuong
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocGiuong TEXT;
        SELECT @DuLieuTruocGiuong = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.Giuong
        SET SoGiuong = COALESCE(@SoGiuong, SoGiuong),
            TinhTrang = COALESCE(@TinhTrang, TinhTrang)
        WHERE MaPhong = @MaPhong
          AND MaGiuong = @MaGiuong;

        UPDATE dbo.Phong
        SET TinhTrang = CASE
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong) THEN 'Trống'
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
            ELSE 'Còn chỗ'
        END
        WHERE MaPhong = @MaPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật giường',
            @DoiTuong = 'Giuong',
            @MaDoiTuong = @MaGiuong,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocGiuong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1 FROM dbo.Giuong
            WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong AND TinhTrang <> 'Trống'
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc AS ctdc
            INNER JOIN dbo.PhieuDatCoc AS pdc ON pdc.MaPhieuDatCoc = ctdc.MaPhieuDatCoc
            WHERE ctdc.MaPhong = @MaPhong
              AND ctdc.MaGiuong = @MaGiuong
              AND pdc.TrangThaiCoc IN ('Hiệu lực', 'Đã lập HĐ')
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietXemPhong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocGiuongXoa TEXT;
        SELECT @DuLieuTruocGiuongXoa = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        BEGIN TRY
            BEGIN TRANSACTION;

            DELETE FROM dbo.Giuong
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong;

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong) THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa giường',
                @DoiTuong = 'Giuong',
                @MaDoiTuong = @MaGiuong,
                @NoiDung = @MaPhong,
                @DuLieuTruoc = @DuLieuTruocGiuongXoa;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaGiuong AS maGiuong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyGiuong @ThaoTac = 'DANH_SACH', @MaPhong = @MaPhong, @MaGiuong = @MaGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyTaiSanPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyTaiSanPhong
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaPhong   VARCHAR(4)    = NULL,
    @MaTaiSan  VARCHAR(6)    = NULL,
    @TenTaiSan VARCHAR(100) = NULL,
    @SoLuong   INT           = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @LoaiTaiSan VARCHAR(20) = NULL,
    @MaGiuong   VARCHAR(3)   = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaTaiSan = NULLIF(TRIM(@MaTaiSan)), '');
    SET @TenTaiSan = NULLIF(TRIM(@TenTaiSan)), '');
    SET @LoaiTaiSan = NULLIF(TRIM(@LoaiTaiSan)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            ts.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            ts.MaTaiSan AS maTaiSan,
            ts.TenTaiSan AS tenTaiSan,
            ts.SoLuong AS soLuong,
            ts.DonGia AS donGia,
            ts.LoaiTaiSan AS loaiTaiSan,
            ts.MaGiuong AS maGiuong,
            g.SoGiuong AS soGiuong
        FROM dbo.TaiSan AS ts
        INNER JOIN dbo.Phong AS p ON p.MaPhong = ts.MaPhong
        LEFT JOIN dbo.Giuong AS g ON g.MaPhong = ts.MaPhong AND g.MaGiuong = ts.MaGiuong
        WHERE (@MaPhong IS NULL OR ts.MaPhong = @MaPhong)
          AND (@MaTaiSan IS NULL OR ts.MaTaiSan = @MaTaiSan)
          AND (@MaGiuong IS NULL OR ts.MaGiuong = @MaGiuong)
          AND (@LoaiTaiSan IS NULL OR ts.LoaiTaiSan = @LoaiTaiSan)
        ORDER BY ts.MaPhong, ts.LoaiTaiSan, ts.MaGiuong, ts.MaTaiSan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TenTaiSan IS NULL
            RAISE EXCEPTION %;

        IF @SoLuong IS NOT NULL AND @SoLuong <= 0
            RAISE EXCEPTION %;

        IF @DonGia IS NOT NULL AND @DonGia < 0
            RAISE EXCEPTION %;

        DECLARE @LoaiTaiSanSau VARCHAR(20);
        DECLARE @MaGiuongSau VARCHAR(3);

        IF @ThaoTac = 'TAO'
        BEGIN
            SET @LoaiTaiSanSau = COALESCE(@LoaiTaiSan, 'Chung');
            SET @MaGiuongSau = @MaGiuong;
        END
        ELSE
        BEGIN
            IF @MaTaiSan IS NULL OR NOT EXISTS (
                SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
            )
                RAISE EXCEPTION %;

            SELECT
                @LoaiTaiSanSau = COALESCE(@LoaiTaiSan, LoaiTaiSan),
                @MaGiuongSau = CASE
                    WHEN @LoaiTaiSan = 'Chung' THEN NULL
                    ELSE COALESCE(@MaGiuong, MaGiuong)
                END
            FROM dbo.TaiSan
            WHERE MaPhong = @MaPhong
              AND MaTaiSan = @MaTaiSan;
        END;

        IF @LoaiTaiSanSau NOT IN ('Chung', 'Riêng')
            RAISE EXCEPTION %;

        IF @LoaiTaiSanSau = 'Chung'
            SET @MaGiuongSau = NULL;

        IF @LoaiTaiSanSau = 'Riêng' AND @MaGiuongSau IS NULL
            RAISE EXCEPTION %;

        IF @MaGiuongSau IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuongSau
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoTaiSan INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaTaiSan IS NULL
            BEGIN
                SELECT @SoTaiSan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaTaiSan, 3, 4))), 0) + 1
                FROM dbo.TaiSan 
                WHERE MaPhong = @MaPhong
                  AND MaTaiSan LIKE 'TS[0-9][0-9][0-9][0-9]';

                IF @SoTaiSan > 9999
                    RAISE EXCEPTION %;

                SET @MaTaiSan = CONCAT('TS', RIGHT(CONCAT('0000', @SoTaiSan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.TaiSan (
                MaPhong, MaTaiSan, TenTaiSan, SoLuong, DonGia, LoaiTaiSan, MaGiuong
            )
            VALUES (
                @MaPhong, @MaTaiSan, @TenTaiSan, COALESCE(@SoLuong, 1),
                @DonGia, @LoaiTaiSanSau, @MaGiuongSau
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo tài sản phòng',
                @DoiTuong = 'TaiSan',
                @MaDoiTuong = @MaTaiSan,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocTaiSan TEXT;
        SELECT @DuLieuTruocTaiSan = (
            SELECT * FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.TaiSan
        SET TenTaiSan = COALESCE(@TenTaiSan, TenTaiSan),
            SoLuong = COALESCE(@SoLuong, SoLuong),
            DonGia = COALESCE(@DonGia, DonGia),
            LoaiTaiSan = @LoaiTaiSanSau,
            MaGiuong = @MaGiuongSau
        WHERE MaPhong = @MaPhong
          AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocTaiSan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietBanGiao WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.ChiTietHuHong WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.YeuCauSuaChua WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaTaiSan AS maTaiSan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyTaiSanPhong
        @ThaoTac = 'DANH_SACH',
        @MaPhong = @MaPhong,
        @MaTaiSan = @MaTaiSan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc
    @ThaoTac           VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinhHoanCoc VARCHAR(6)    = NULL,
    @TenQuyDinh        VARCHAR(255) = NULL,
    @TyLeHoanCoc       DECIMAL(5,2)  = NULL,
    @AdminId           VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinhHoanCoc = NULLIF(TRIM(@MaQuyDinhHoanCoc)), '');
    SET @TenQuyDinh = NULLIF(TRIM(@TenQuyDinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qh.MaQuyDinhHoanCoc AS maQuyDinhHoanCoc,
            qh.TenQuyDinh AS tenQuyDinh,
            qh.TyLeHoanCoc AS tyLeHoanCoc,
            COUNT(ds.MaQuyDinhHoanCoc) AS soLanApDung
        FROM dbo.QuyDinhHoanCoc AS qh
        LEFT JOIN dbo.DoiSoat AS ds ON ds.MaQuyDinhHoanCoc = qh.MaQuyDinhHoanCoc
        WHERE (@MaQuyDinhHoanCoc IS NULL OR qh.MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
        GROUP BY qh.MaQuyDinhHoanCoc, qh.TenQuyDinh, qh.TyLeHoanCoc
        ORDER BY qh.MaQuyDinhHoanCoc;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenQuyDinh IS NULL OR @TyLeHoanCoc IS NULL)
            RAISE EXCEPTION %;

        IF @TyLeHoanCoc IS NOT NULL AND (@TyLeHoanCoc < 0 OR @TyLeHoanCoc > 100)
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinh INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinhHoanCoc IS NULL
            BEGIN
                SELECT @SoQuyDinh = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinhHoanCoc, 3, 4))), 0) + 1
                FROM dbo.QuyDinhHoanCoc 
                WHERE MaQuyDinhHoanCoc LIKE 'QH[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinh > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinhHoanCoc = CONCAT('QH', RIGHT(CONCAT('0000', @SoQuyDinh), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuyDinhHoanCoc (MaQuyDinhHoanCoc, TenQuyDinh, TyLeHoanCoc)
            VALUES (@MaQuyDinhHoanCoc, @TenQuyDinh, @TyLeHoanCoc);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo quy định hoàn cọc',
                @DoiTuong = 'QuyDinhHoanCoc',
                @MaDoiTuong = @MaQuyDinhHoanCoc,
                @NoiDung = @TenQuyDinh;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocHoanCoc TEXT;
        SELECT @DuLieuTruocHoanCoc = (
            SELECT * FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuyDinhHoanCoc
        SET TenQuyDinh = COALESCE(@TenQuyDinh, TenQuyDinh),
            TyLeHoanCoc = COALESCE(@TyLeHoanCoc, TyLeHoanCoc)
        WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc,
            @DuLieuTruoc = @DuLieuTruocHoanCoc;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DoiSoat WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinhHoanCoc AS maQuyDinhHoanCoc;
        RETURN;
    END;

    EXEC dbo.SP_Admin_CauHinhQuyDinhHoanCoc @ThaoTac = 'DANH_SACH', @MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDichVu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDichVu
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaDichVu  VARCHAR(6)    = NULL,
    @TenDichVu VARCHAR(100) = NULL,
    @DonViTinh VARCHAR(20)   = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDichVu = NULLIF(TRIM(@MaDichVu)), '');
    SET @TenDichVu = NULLIF(TRIM(@TenDichVu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dv.MaDichVu AS maDichVu,
            dv.TenDichVu AS tenDichVu,
            dv.DonViTinh AS donViTinh,
            dv.DonGia AS donGia,
            COUNT(DISTINCT dvhd.MaChiTietDVHD) AS soHopDongSuDung,
            COUNT(cthd.MaChiTietHD) AS soDongHoaDon
        FROM dbo.DichVu AS dv
        LEFT JOIN dbo.DichVuHopDong AS dvhd ON dvhd.MaDichVu = dv.MaDichVu
        LEFT JOIN dbo.ChiTietHoaDon AS cthd ON cthd.MaChiTietDVHD = dvhd.MaChiTietDVHD
        WHERE (@MaDichVu IS NULL OR dv.MaDichVu = @MaDichVu)
          AND (@TenDichVu IS NULL OR dv.TenDichVu LIKE '%' + @TenDichVu + '%')
        GROUP BY dv.MaDichVu, dv.TenDichVu, dv.DonViTinh, dv.DonGia
        ORDER BY dv.MaDichVu;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDichVu IS NULL OR @DonViTinh IS NULL OR @DonGia IS NULL)
            THROW 51202, 'Vui lòng nhập tên dịch vụ, đơn vị tính và đơn giá.', 1;

        IF @DonGia IS NOT NULL AND @DonGia <= 0
            RAISE EXCEPTION %;

        IF @TenDichVu IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DichVu
            WHERE TenDichVu = @TenDichVu
              AND (@MaDichVu IS NULL OR MaDichVu <> @MaDichVu)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDichVu INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDichVu IS NULL
            BEGIN
                SELECT @SoDichVu = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDichVu, 3, 4))), 0) + 1
                FROM dbo.DichVu 
                WHERE MaDichVu LIKE 'DV[0-9][0-9][0-9][0-9]';

                IF @SoDichVu > 9999
                    RAISE EXCEPTION %;

                SET @MaDichVu = CONCAT('DV', RIGHT(CONCAT('0000', @SoDichVu), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DichVu (MaDichVu, TenDichVu, DonViTinh, DonGia)
            VALUES (@MaDichVu, @TenDichVu, @DonViTinh, @DonGia);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo dịch vụ',
                @DoiTuong = 'DichVu',
                @MaDoiTuong = @MaDichVu,
                @NoiDung = @TenDichVu;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocDichVu TEXT;
        SELECT @DuLieuTruocDichVu = (
            SELECT * FROM dbo.DichVu WHERE MaDichVu = @MaDichVu FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DichVu
        SET TenDichVu = COALESCE(@TenDichVu, TenDichVu),
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            DonGia = COALESCE(@DonGia, DonGia)
        WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu,
            @DuLieuTruoc = @DuLieuTruocDichVu;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DichVuHopDong WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DichVu WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDichVu AS maDichVu;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDichVu @ThaoTac = 'DANH_SACH', @MaDichVu = @MaDichVu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyNoiQuy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyNoiQuy
    @ThaoTac      VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinh    VARCHAR(6)    = NULL,
    @TieuDeNoiQuy VARCHAR(255) = NULL,
    @NoiDung      TEXT = NULL,
    @TrangThai    VARCHAR(20)  = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinh = NULLIF(TRIM(@MaQuyDinh)), '');
    SET @TieuDeNoiQuy = NULLIF(TRIM(@TieuDeNoiQuy)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qd.MaQuyDinh AS maQuyDinh,
            qd.TieuDeNoiQuy AS tieuDeNoiQuy,
            qd.NoiDung AS noiDung,
            qd.TrangThai AS trangThai
        FROM dbo.QuiDinh AS qd
        WHERE (@MaQuyDinh IS NULL OR qd.MaQuyDinh = @MaQuyDinh)
          AND (@TrangThai IS NULL OR qd.TrangThai = @TrangThai)
          AND (@TieuDeNoiQuy IS NULL OR qd.TieuDeNoiQuy LIKE '%' + @TieuDeNoiQuy + '%')
        ORDER BY qd.MaQuyDinh;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TieuDeNoiQuy IS NULL
            RAISE EXCEPTION %;

        IF @TieuDeNoiQuy IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.QuiDinh
            WHERE TieuDeNoiQuy = @TieuDeNoiQuy
              AND (@MaQuyDinh IS NULL OR MaQuyDinh <> @MaQuyDinh)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinhNoiQuy INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinh IS NULL
            BEGIN
                SELECT @SoQuyDinhNoiQuy = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinh, 3, 4))), 0) + 1
                FROM dbo.QuiDinh 
                WHERE MaQuyDinh LIKE 'QD[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinhNoiQuy > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinh = CONCAT('QD', RIGHT(CONCAT('0000', @SoQuyDinhNoiQuy), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuiDinh (MaQuyDinh, TieuDeNoiQuy, NoiDung, TrangThai)
            VALUES (@MaQuyDinh, @TieuDeNoiQuy, @NoiDung, COALESCE(@TrangThai, 'Hiệu lực'));

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo nội quy',
                @DoiTuong = 'QuiDinh',
                @MaDoiTuong = @MaQuyDinh,
                @NoiDung = @TieuDeNoiQuy;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocNoiQuy TEXT;
        SELECT @DuLieuTruocNoiQuy = (
            SELECT * FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuiDinh
        SET TieuDeNoiQuy = COALESCE(@TieuDeNoiQuy, TieuDeNoiQuy),
            NoiDung = COALESCE(@NoiDung, NoiDung),
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh,
            @DuLieuTruoc = @DuLieuTruocNoiQuy;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        UPDATE dbo.QuiDinh
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinh AS maQuyDinh;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyNoiQuy @ThaoTac = 'DANH_SACH', @MaQuyDinh = @MaQuyDinh;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham
    @ThaoTac        VARCHAR(20)  = 'DANH_SACH',
    @MaDieuKhoan    VARCHAR(6)    = NULL,
    @TenDieuKhoan   VARCHAR(255) = NULL,
    @HinhThucXuPhat VARCHAR(20)  = NULL,
    @MucPhat        DECIMAL(15,2) = NULL,
    @TrangThai      VARCHAR(20)  = NULL,
    @AdminId        VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDieuKhoan = NULLIF(TRIM(@MaDieuKhoan)), '');
    SET @TenDieuKhoan = NULLIF(TRIM(@TenDieuKhoan)), '');
    SET @HinhThucXuPhat = NULLIF(TRIM(@HinhThucXuPhat)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dk.MaDieuKhoan AS maDieuKhoan,
            dk.TenDieuKhoan AS tenDieuKhoan,
            dk.HinhThucXuPhat AS hinhThucXuPhat,
            dk.MucPhat AS mucPhat,
            dk.TrangThai AS trangThai,
            COUNT(bb.MaBBViPham) AS soBienBanApDung
        FROM dbo.DieuKhoanViPham AS dk
        LEFT JOIN dbo.BienBanViPham AS bb ON bb.MaDieuKhoan = dk.MaDieuKhoan
        WHERE (@MaDieuKhoan IS NULL OR dk.MaDieuKhoan = @MaDieuKhoan)
          AND (@TrangThai IS NULL OR dk.TrangThai = @TrangThai)
          AND (@TenDieuKhoan IS NULL OR dk.TenDieuKhoan LIKE '%' + @TenDieuKhoan + '%')
        GROUP BY dk.MaDieuKhoan, dk.TenDieuKhoan, dk.HinhThucXuPhat, dk.MucPhat, dk.TrangThai
        ORDER BY dk.MaDieuKhoan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @HinhThucXuPhat IS NOT NULL AND @HinhThucXuPhat NOT IN ('Nhắc nhở', 'Phạt tiền')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @MucPhat IS NOT NULL AND @MucPhat < 0
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDieuKhoan IS NULL OR @HinhThucXuPhat IS NULL)
            RAISE EXCEPTION %;

        IF @TenDieuKhoan IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DieuKhoanViPham
            WHERE TenDieuKhoan = @TenDieuKhoan
              AND (@MaDieuKhoan IS NULL OR MaDieuKhoan <> @MaDieuKhoan)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDieuKhoan INT;

        IF @HinhThucXuPhat = 'Phạt tiền' AND COALESCE(@MucPhat, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucXuPhat = 'Nhắc nhở' AND @MucPhat IS NULL
            SET @MucPhat = 0;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDieuKhoan IS NULL
            BEGIN
                SELECT @SoDieuKhoan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDieuKhoan, 3, 4))), 0) + 1
                FROM dbo.DieuKhoanViPham 
                WHERE MaDieuKhoan LIKE 'VP[0-9][0-9][0-9][0-9]';

                IF @SoDieuKhoan > 9999
                    RAISE EXCEPTION %;

                SET @MaDieuKhoan = CONCAT('VP', RIGHT(CONCAT('0000', @SoDieuKhoan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DieuKhoanViPham (
                MaDieuKhoan, TenDieuKhoan, HinhThucXuPhat, MucPhat, TrangThai
            )
            VALUES (
                @MaDieuKhoan, @TenDieuKhoan, @HinhThucXuPhat, COALESCE(@MucPhat, 0), COALESCE(@TrangThai, 'Hiệu lực')
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo điều khoản vi phạm',
                @DoiTuong = 'DieuKhoanViPham',
                @MaDoiTuong = @MaDieuKhoan,
                @NoiDung = @TenDieuKhoan;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DECLARE @HinhThucSau VARCHAR(20);
        DECLARE @MucPhatSau DECIMAL(15,2);

        SELECT
            @HinhThucSau = COALESCE(@HinhThucXuPhat, HinhThucXuPhat),
            @MucPhatSau = COALESCE(@MucPhat, MucPhat)
        FROM dbo.DieuKhoanViPham
        WHERE MaDieuKhoan = @MaDieuKhoan;

        IF @HinhThucSau = 'Phạt tiền' AND COALESCE(@MucPhatSau, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucSau = 'Nhắc nhở' AND @MucPhatSau IS NULL
            SET @MucPhatSau = 0;

        DECLARE @DuLieuTruocDieuKhoan TEXT;
        SELECT @DuLieuTruocDieuKhoan = (
            SELECT * FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DieuKhoanViPham
        SET TenDieuKhoan = COALESCE(@TenDieuKhoan, TenDieuKhoan),
            HinhThucXuPhat = @HinhThucSau,
            MucPhat = @MucPhatSau,
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan,
            @DuLieuTruoc = @DuLieuTruocDieuKhoan;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        UPDATE dbo.DieuKhoanViPham
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.BienBanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDieuKhoan AS maDieuKhoan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDieuKhoanViPham @ThaoTac = 'DANH_SACH', @MaDieuKhoan = @MaDieuKhoan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhThamSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhThamSo
    @ThaoTac    VARCHAR(20)  = 'DANH_SACH',
    @MaThamSo   VARCHAR(50)   = NULL,
    @NhomThamSo VARCHAR(50)  = NULL,
    @TenThamSo  VARCHAR(100) = NULL,
    @GiaTri     VARCHAR(255) = NULL,
    @KieuDuLieu VARCHAR(20)  = NULL,
    @DonViTinh  VARCHAR(30)  = NULL,
    @MoTa       TEXT = NULL,
    @AdminId    VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaThamSo = NULLIF(TRIM(@MaThamSo)), '');
    SET @NhomThamSo = NULLIF(TRIM(@NhomThamSo)), '');
    SET @TenThamSo = NULLIF(TRIM(@TenThamSo)), '');
    SET @GiaTri = NULLIF(TRIM(@GiaTri)), '');
    SET @KieuDuLieu = NULLIF(TRIM(@KieuDuLieu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            MaThamSo AS maThamSo,
            NhomThamSo AS nhomThamSo,
            TenThamSo AS tenThamSo,
            GiaTri AS giaTri,
            KieuDuLieu AS kieuDuLieu,
            DonViTinh AS donViTinh,
            MoTa AS moTa,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.ThamSoHeThong
        WHERE (@MaThamSo IS NULL OR MaThamSo = @MaThamSo)
          AND (@NhomThamSo IS NULL OR NhomThamSo = @NhomThamSo)
        ORDER BY NhomThamSo, MaThamSo;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT')
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO' AND (@MaThamSo IS NULL OR @NhomThamSo IS NULL OR @TenThamSo IS NULL OR @GiaTri IS NULL)
        THROW 51262, 'Vui lòng nhập đủ mã, nhóm, tên và giá trị tham số.', 1;

    IF @MaThamSo IS NULL
        RAISE EXCEPTION %;

    IF @KieuDuLieu IS NOT NULL AND @KieuDuLieu NOT IN ('Chuỗi', 'Số', 'Ngày', 'Boolean')
        RAISE EXCEPTION %;

    DECLARE @KieuDuLieuSau VARCHAR(20);
    DECLARE @GiaTriSau VARCHAR(255);

    IF @ThaoTac = 'TAO'
    BEGIN
        SET @KieuDuLieuSau = COALESCE(@KieuDuLieu, 'Chuỗi');
        SET @GiaTriSau = @GiaTri;
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        SELECT
            @KieuDuLieuSau = COALESCE(@KieuDuLieu, KieuDuLieu),
            @GiaTriSau = COALESCE(@GiaTri, GiaTri)
        FROM dbo.ThamSoHeThong
        WHERE MaThamSo = @MaThamSo;
    END;

    IF @KieuDuLieuSau = 'Số' AND (TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) IS NULL OR TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) < 0)
        RAISE EXCEPTION %;

    IF @MaThamSo = 'THOI_HAN_THANH_TOAN_COC_GIO'
       AND (TRY_CONVERT(INT, @GiaTriSau) IS NULL OR TRY_CONVERT(INT, @GiaTriSau) <= 0)
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        INSERT INTO dbo.ThamSoHeThong (
            MaThamSo, NhomThamSo, TenThamSo, GiaTri, KieuDuLieu, DonViTinh, MoTa, CapNhatBoi
        )
        VALUES (
            @MaThamSo, @NhomThamSo, @TenThamSo, @GiaTriSau, @KieuDuLieuSau, @DonViTinh, @MoTa, @AdminId
        );

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @NoiDung = @TenThamSo;
    END
    ELSE
    BEGIN
        DECLARE @DuLieuTruocThamSo TEXT;
        SELECT @DuLieuTruocThamSo = (
            SELECT * FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.ThamSoHeThong
        SET NhomThamSo = COALESCE(@NhomThamSo, NhomThamSo),
            TenThamSo = COALESCE(@TenThamSo, TenThamSo),
            GiaTri = @GiaTriSau,
            KieuDuLieu = @KieuDuLieuSau,
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            MoTa = COALESCE(@MoTa, MoTa),
            CapNhatLuc = CURRENT_TIMESTAMP,
            CapNhatBoi = @AdminId
        WHERE MaThamSo = @MaThamSo;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @DuLieuTruoc = @DuLieuTruocThamSo;
    END;

    EXEC dbo.SP_Admin_CauHinhThamSo @ThaoTac = 'DANH_SACH', @MaThamSo = @MaThamSo;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhSaoLuu
    @ChuKyFull        VARCHAR(20)  = NULL,
    @ChuKyIncremental VARCHAR(20)  = NULL,
    @ThuMucLuuTru     VARCHAR(500) = NULL,
    @AdminId          VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ChuKyFull = NULLIF(TRIM(@ChuKyFull)), '');
    SET @ChuKyIncremental = NULLIF(TRIM(@ChuKyIncremental)), '');
    SET @ThuMucLuuTru = NULLIF(TRIM(@ThuMucLuuTru)), '');

    IF @ChuKyFull IS NOT NULL AND @ChuKyFull NOT IN ('Hàng tuần', 'Hàng tháng')
        RAISE EXCEPTION %;

    IF @ChuKyIncremental IS NOT NULL AND @ChuKyIncremental NOT IN ('Hàng ngày', 'Hàng tuần')
        RAISE EXCEPTION %;

    IF @ThuMucLuuTru IS NOT NULL
    BEGIN
        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);
    END;

    IF @ChuKyFull IS NULL AND @ChuKyIncremental IS NULL AND @ThuMucLuuTru IS NULL
    BEGIN
        SELECT
            MaCauHinh AS maCauHinh,
            ChuKyFull AS chuKyFull,
            ChuKyIncremental AS chuKyIncremental,
            ThuMucLuuTru AS thuMucLuuTru,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;
        RETURN;
    END;

    DECLARE @DuLieuTruocSaoLuu TEXT;
    SELECT @DuLieuTruocSaoLuu = (
        SELECT * FROM dbo.CauHinhSaoLuu WHERE MaCauHinh = 1 FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    UPDATE dbo.CauHinhSaoLuu
    SET ChuKyFull = COALESCE(@ChuKyFull, ChuKyFull),
        ChuKyIncremental = COALESCE(@ChuKyIncremental, ChuKyIncremental),
        ThuMucLuuTru = COALESCE(@ThuMucLuuTru, ThuMucLuuTru),
        CapNhatLuc = CURRENT_TIMESTAMP,
        CapNhatBoi = @AdminId
    WHERE MaCauHinh = 1;

    EXEC dbo.SP_Admin_GhiNhatKy
        @AdminId = @AdminId,
        @HanhDong = 'Cấu hình sao lưu',
        @DoiTuong = 'CauHinhSaoLuu',
        @MaDoiTuong = '1',
        @DuLieuTruoc = @DuLieuTruocSaoLuu;

    SELECT
        MaCauHinh AS maCauHinh,
        ChuKyFull AS chuKyFull,
        ChuKyIncremental AS chuKyIncremental,
        ThuMucLuuTru AS thuMucLuuTru,
        CapNhatLuc AS capNhatLuc,
        CapNhatBoi AS capNhatBoi
    FROM dbo.CauHinhSaoLuu
    WHERE MaCauHinh = 1;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_SaoLuuThuCong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_SaoLuuThuCong
    @LoaiSaoLuu  VARCHAR(20)  = 'Full',
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    

    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');
    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');
    IF @LoaiSaoLuu IS NULL SET @LoaiSaoLuu = 'Full';

    DECLARE @LoaiSaoLuuChuan VARCHAR(20) = UPPER(@LoaiSaoLuu);
    IF @LoaiSaoLuuChuan = 'FULL'
        SET @LoaiSaoLuu = 'Full';
    ELSE IF @LoaiSaoLuuChuan IN ('INCREMENTAL', 'DIFFERENTIAL')
        SET @LoaiSaoLuu = 'Incremental';

    IF @LoaiSaoLuu NOT IN ('Full', 'Incremental')
        RAISE EXCEPTION %;

    IF @DuongDanFile IS NULL
    BEGIN
        DECLARE @ThuMucLuuTru VARCHAR(500);
        SELECT @ThuMucLuuTru = ThuMucLuuTru
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;

        IF @ThuMucLuuTru IS NULL
            RAISE EXCEPTION %;

        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);

        SET @DuongDanFile =
            @ThuMucLuuTru + '\' + DB_NAME() + '_' + @LoaiSaoLuu + '_' +
            CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112) + REPLACE(CONVERT(CHAR(8), CURRENT_TIMESTAMP, 108), ':', '') + '.bak';
    END;

    DECLARE @MaSaoLuu INT;
    DECLARE @LenhSaoLuu TEXT;

    INSERT INTO dbo.LichSuSaoLuu (
        LoaiSaoLuu, DuongDanFile, TrangThai, ThoiGianBatDau, MaNguoiDung
    )
    VALUES (
        @LoaiSaoLuu, @DuongDanFile, 'Đang chạy', CURRENT_TIMESTAMP, @AdminId
    );

    SET @MaSaoLuu = SCOPE_IDENTITY();
    SET @LenhSaoLuu =
        'BACKUP DATABASE ' + QUOTENAME(DB_NAME()) +
        ' TO DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') +
        ''' WITH ' +
        CASE WHEN @LoaiSaoLuu = 'Incremental' THEN 'DIFFERENTIAL, INIT' ELSE 'INIT' END +
        ';';

    BEGIN TRY
        EXEC(@LenhSaoLuu);

        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thành công',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = 'Sao lưu hoàn tất.'
        WHERE MaSaoLuu = @MaSaoLuu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Sao lưu thủ công',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thất bại',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = ERROR_MESSAGE()
        WHERE MaSaoLuu = @MaSaoLuu;

        THROW;
    END CATCH;

    SELECT
        MaSaoLuu AS maSaoLuu,
        LoaiSaoLuu AS loaiSaoLuu,
        DuongDanFile AS duongDanFile,
        TrangThai AS trangThai,
        ThoiGianBatDau AS thoiGianBatDau,
        ThoiGianKetThuc AS thoiGianKetThuc,
        ThongBao AS thongBao
    FROM dbo.LichSuSaoLuu
    WHERE MaSaoLuu = @MaSaoLuu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_DanhSachSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_DanhSachSaoLuu
    @SoDong     INT          = 100,
    @TrangThai  VARCHAR(20) = NULL,
    @LoaiSaoLuu VARCHAR(20) = NULL
AS
BEGIN
    

    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 100;

    SELECT TOP (@SoDong)
        ls.MaSaoLuu AS maSaoLuu,
        ls.LoaiSaoLuu AS loaiSaoLuu,
        ls.DuongDanFile AS duongDanFile,
        ls.DungLuongByte AS dungLuongByte,
        ls.TrangThai AS trangThai,
        ls.ThoiGianBatDau AS thoiGianBatDau,
        ls.ThoiGianKetThuc AS thoiGianKetThuc,
        ls.ThongBao AS thongBao,
        ls.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung
    FROM dbo.LichSuSaoLuu AS ls
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = ls.MaNguoiDung
    WHERE (@TrangThai IS NULL OR ls.TrangThai = @TrangThai)
      AND (@LoaiSaoLuu IS NULL OR ls.LoaiSaoLuu = @LoaiSaoLuu)
    ORDER BY ls.ThoiGianBatDau DESC, ls.MaSaoLuu DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_PhucHoiDuLieu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_PhucHoiDuLieu
    @MaSaoLuu    INT           = NULL,
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL,
    @ChiTaoLenh   BOOLEAN           = 1
AS
BEGIN
    

    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');

    IF @DuongDanFile IS NULL AND @MaSaoLuu IS NOT NULL
    BEGIN
        SELECT @DuongDanFile = DuongDanFile
        FROM dbo.LichSuSaoLuu
        WHERE MaSaoLuu = @MaSaoLuu
          AND TrangThai = 'Thành công';
    END;

    IF @DuongDanFile IS NULL
        RAISE EXCEPTION %;

    DECLARE @TenDatabase SYSNAME = DB_NAME();
    DECLARE @LenhSingleUser TEXT;
    DECLARE @LenhRestore TEXT;
    DECLARE @LenhMultiUser TEXT;
    DECLARE @LenhDayDu TEXT;

    SET @LenhSingleUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET SINGLE_USER WITH ROLLBACK IMMEDIATE;';
    SET @LenhRestore = 'USE [master]; RESTORE DATABASE ' + QUOTENAME(@TenDatabase) +
        ' FROM DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') + ''' WITH REPLACE;';
    SET @LenhMultiUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET MULTI_USER;';
    SET @LenhDayDu = @LenhSingleUser + CHAR(13) + CHAR(10) + @LenhRestore + CHAR(13) + CHAR(10) + @LenhMultiUser;

    IF @ChiTaoLenh = 1
    BEGIN
        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo lệnh phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;

        SELECT
            @TenDatabase AS tenDatabase,
            @DuongDanFile AS duongDanFile,
            @LenhDayDu AS lenhPhucHoi,
            CAST(1 AS BOOLEAN) AS chiTaoLenh;
        RETURN;
    END;

    BEGIN TRY
        EXEC(@LenhSingleUser);
        EXEC(@LenhRestore);
        EXEC(@LenhMultiUser);

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        BEGIN TRY
            EXEC(@LenhMultiUser);
        END TRY
        BEGIN CATCH
        END CATCH;

        THROW;
    END CATCH;

    SELECT
        @TenDatabase AS tenDatabase,
        @DuongDanFile AS duongDanFile,
        CAST(1 AS BOOLEAN) AS daPhucHoi;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_XemNhatKyHeThong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_XemNhatKyHeThong
    @TuNgay     TIMESTAMP  = NULL,
    @DenNgay    TIMESTAMP  = NULL,
    @AdminId    VARCHAR(6)    = NULL,
    @DoiTuong   VARCHAR(100) = NULL,
    @HanhDong   VARCHAR(100) = NULL,
    @TuKhoa     VARCHAR(100) = NULL,
    @SoDong     INT           = 200
AS
BEGIN
    

    SET @AdminId = NULLIF(TRIM(@AdminId)), '');
    SET @DoiTuong = NULLIF(TRIM(@DoiTuong)), '');
    SET @HanhDong = NULLIF(TRIM(@HanhDong)), '');
    SET @TuKhoa = NULLIF(TRIM(@TuKhoa)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 200;

    SELECT TOP (@SoDong)
        nk.MaNhatKy AS maNhatKy,
        nk.ThoiGian AS thoiGian,
        nk.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung,
        nk.VaiTro AS vaiTro,
        nk.ChucNang AS chucNang,
        nk.HanhDong AS hanhDong,
        nk.DoiTuong AS doiTuong,
        nk.MaDoiTuong AS maDoiTuong,
        nk.NoiDung AS noiDung,
        nk.DuLieuTruoc AS duLieuTruoc,
        nk.DuLieuSau AS duLieuSau
    FROM dbo.NhatKyHeThong AS nk
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nk.MaNguoiDung
    WHERE (@TuNgay IS NULL OR nk.ThoiGian >= @TuNgay)
      AND (@DenNgay IS NULL OR nk.ThoiGian < DATEADD(DAY, 1, @DenNgay))
      AND (@AdminId IS NULL OR nk.MaNguoiDung = @AdminId)
      AND (@DoiTuong IS NULL OR nk.DoiTuong = @DoiTuong)
      AND (@HanhDong IS NULL OR nk.HanhDong LIKE '%' + @HanhDong + '%')
      AND (
          @TuKhoa IS NULL
          OR nk.NoiDung LIKE '%' + @TuKhoa + '%'
          OR nk.MaDoiTuong LIKE '%' + @TuKhoa + '%'
          OR nk.HanhDong LIKE '%' + @TuKhoa + '%'
      )
    ORDER BY nk.ThoiGian DESC, nk.MaNhatKy DESC;
END; THEN (SUBSTRING(MaLoaiPhong, 3, 4)::INT ELSE NULL END)), 0) + 1
                FROM dbo.LoaiPhong 
                WHERE MaLoaiPhong LIKE 'LP[0-9][0-9][0-9][0-9]';

                IF @SoLoaiPhong > 9999
                    RAISE EXCEPTION %;

                SET @MaLoaiPhong = CONCAT('LP', RIGHT(CONCAT('0000', @SoLoaiPhong), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
                RAISE EXCEPTION %;

            INSERT INTO dbo.LoaiPhong (
                MaLoaiPhong, TenLoaiPhong, SucChuaToiDa, MoTa, GiaThueTheoGiuong, GiaThueNguyenPhong
            )
            VALUES (
                @MaLoaiPhong, @TenLoaiPhong, @SucChuaToiDa, @MoTa, @GiaThueTheoGiuong, @GiaThueNguyenPhong
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo loại phòng',
                @DoiTuong = 'LoaiPhong',
                @MaDoiTuong = @MaLoaiPhong,
                @NoiDung = @TenLoaiPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaLoaiPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocLoaiPhong TEXT;
        SELECT @DuLieuTruocLoaiPhong = (
            SELECT * FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        IF @SucChuaToiDa IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.Phong AS p
            WHERE p.MaLoaiPhong = @MaLoaiPhong
              AND (
                  SELECT COUNT(1)
                  FROM dbo.Giuong AS g
                  WHERE g.MaPhong = p.MaPhong
              ) > @SucChuaToiDa
        )
            RAISE EXCEPTION %;

        UPDATE dbo.LoaiPhong
        SET TenLoaiPhong = COALESCE(@TenLoaiPhong, TenLoaiPhong),
            SucChuaToiDa = COALESCE(@SucChuaToiDa, SucChuaToiDa),
            MoTa = COALESCE(@MoTa, MoTa),
            GiaThueTheoGiuong = COALESCE(@GiaThueTheoGiuong, GiaThueTheoGiuong),
            GiaThueNguyenPhong = COALESCE(@GiaThueNguyenPhong, GiaThueNguyenPhong)
        WHERE MaLoaiPhong = @MaLoaiPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật loại phòng',
            @DoiTuong = 'LoaiPhong',
            @MaDoiTuong = @MaLoaiPhong,
            @DuLieuTruoc = @DuLieuTruocLoaiPhong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaLoaiPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        DELETE FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa loại phòng',
            @DoiTuong = 'LoaiPhong',
            @MaDoiTuong = @MaLoaiPhong;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaLoaiPhong AS maLoaiPhong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyLoaiPhong @ThaoTac = 'DANH_SACH', @MaLoaiPhong = @MaLoaiPhong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_TaoPhongGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_TaoPhongGiuong
    @MaPhong         VARCHAR(4)    = NULL,
    @TenPhong        VARCHAR(100),
    @GioiTinhChoPhep VARCHAR(20),
    @MaChiNhanh      VARCHAR(6),
    @MaLoaiPhong     VARCHAR(6),
    @TinhTrang       VARCHAR(20)  = 'Trống',
    @UrlImg          VARCHAR(500)  = NULL,
    @SoGiuong        INT           = NULL,
    @AdminId         VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @TenPhong = NULLIF(TRIM(@TenPhong)), '');
    SET @GioiTinhChoPhep = NULLIF(TRIM(@GioiTinhChoPhep)), '');
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @MaLoaiPhong = NULLIF(TRIM(@MaLoaiPhong)), '');
    SET @TinhTrang = COALESCE(NULLIF(TRIM(@TinhTrang)), ''), 'Trống');
    EXEC dbo.SP_Admin_QuanLyChiNhanh @ThaoTac = 'DANH_SACH', @MaChiNhanh = @MaChiNhanh;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyLoaiPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyLoaiPhong
    @ThaoTac             VARCHAR(20)  = 'DANH_SACH',
    @MaLoaiPhong         VARCHAR(6)    = NULL,
    @TenLoaiPhong        VARCHAR(100) = NULL,
    @SucChuaToiDa        INT           = NULL,
    @MoTa                TEXT = NULL,
    @GiaThueTheoGiuong   DECIMAL(15,2) = NULL,
    @GiaThueNguyenPhong  DECIMAL(15,2) = NULL,
    @AdminId             VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaLoaiPhong = NULLIF(TRIM(@MaLoaiPhong)), '');
    SET @TenLoaiPhong = NULLIF(TRIM(@TenLoaiPhong)), '');
    SET @MoTa = NULLIF(TRIM(@MoTa)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            lp.MaLoaiPhong AS maLoaiPhong,
            lp.TenLoaiPhong AS tenLoaiPhong,
            lp.SucChuaToiDa AS sucChuaToiDa,
            lp.MoTa AS moTa,
            lp.GiaThueTheoGiuong AS giaThueTheoGiuong,
            lp.GiaThueNguyenPhong AS giaThueNguyenPhong,
            COUNT(p.MaPhong) AS soPhong
        FROM dbo.LoaiPhong AS lp
        LEFT JOIN dbo.Phong AS p ON p.MaLoaiPhong = lp.MaLoaiPhong
        WHERE (@MaLoaiPhong IS NULL OR lp.MaLoaiPhong = @MaLoaiPhong)
        GROUP BY lp.MaLoaiPhong, lp.TenLoaiPhong, lp.SucChuaToiDa, lp.MoTa, lp.GiaThueTheoGiuong, lp.GiaThueNguyenPhong
        ORDER BY lp.MaLoaiPhong;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenLoaiPhong IS NULL OR @SucChuaToiDa IS NULL)
            RAISE EXCEPTION %;

        IF @SucChuaToiDa IS NOT NULL AND @SucChuaToiDa < 1
            RAISE EXCEPTION %;

        IF @GiaThueTheoGiuong IS NOT NULL AND @GiaThueTheoGiuong < 0
            RAISE EXCEPTION %;

        IF @GiaThueNguyenPhong IS NOT NULL AND @GiaThueNguyenPhong < 0
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoLoaiPhong INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaLoaiPhong IS NULL
            BEGIN
                SELECT @SoLoaiPhong = COALESCE(MAX(CASE WHEN (SUBSTRING(MaLoaiPhong, 3, 4) ~ '^[0-9]+)), 0) + 1
                FROM dbo.LoaiPhong 
                WHERE MaLoaiPhong LIKE 'LP[0-9][0-9][0-9][0-9]';

                IF @SoLoaiPhong > 9999
                    RAISE EXCEPTION %;

                SET @MaLoaiPhong = CONCAT('LP', RIGHT(CONCAT('0000', @SoLoaiPhong), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
                RAISE EXCEPTION %;

            INSERT INTO dbo.LoaiPhong (
                MaLoaiPhong, TenLoaiPhong, SucChuaToiDa, MoTa, GiaThueTheoGiuong, GiaThueNguyenPhong
            )
            VALUES (
                @MaLoaiPhong, @TenLoaiPhong, @SucChuaToiDa, @MoTa, @GiaThueTheoGiuong, @GiaThueNguyenPhong
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo loại phòng',
                @DoiTuong = 'LoaiPhong',
                @MaDoiTuong = @MaLoaiPhong,
                @NoiDung = @TenLoaiPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaLoaiPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocLoaiPhong TEXT;
        SELECT @DuLieuTruocLoaiPhong = (
            SELECT * FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        IF @SucChuaToiDa IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.Phong AS p
            WHERE p.MaLoaiPhong = @MaLoaiPhong
              AND (
                  SELECT COUNT(1)
                  FROM dbo.Giuong AS g
                  WHERE g.MaPhong = p.MaPhong
              ) > @SucChuaToiDa
        )
            RAISE EXCEPTION %;

        UPDATE dbo.LoaiPhong
        SET TenLoaiPhong = COALESCE(@TenLoaiPhong, TenLoaiPhong),
            SucChuaToiDa = COALESCE(@SucChuaToiDa, SucChuaToiDa),
            MoTa = COALESCE(@MoTa, MoTa),
            GiaThueTheoGiuong = COALESCE(@GiaThueTheoGiuong, GiaThueTheoGiuong),
            GiaThueNguyenPhong = COALESCE(@GiaThueNguyenPhong, GiaThueNguyenPhong)
        WHERE MaLoaiPhong = @MaLoaiPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật loại phòng',
            @DoiTuong = 'LoaiPhong',
            @MaDoiTuong = @MaLoaiPhong,
            @DuLieuTruoc = @DuLieuTruocLoaiPhong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaLoaiPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        DELETE FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa loại phòng',
            @DoiTuong = 'LoaiPhong',
            @MaDoiTuong = @MaLoaiPhong;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaLoaiPhong AS maLoaiPhong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyLoaiPhong @ThaoTac = 'DANH_SACH', @MaLoaiPhong = @MaLoaiPhong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_TaoPhongGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_TaoPhongGiuong
    @MaPhong         VARCHAR(4)    = NULL,
    @TenPhong        VARCHAR(100),
    @GioiTinhChoPhep VARCHAR(20),
    @MaChiNhanh      VARCHAR(6),
    @MaLoaiPhong     VARCHAR(6),
    @TinhTrang       VARCHAR(20)  = 'Trống',
    @UrlImg          VARCHAR(500)  = NULL,
    @SoGiuong        INT           = NULL,
    @AdminId         VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @TenPhong = NULLIF(TRIM(@TenPhong)), '');
    SET @GioiTinhChoPhep = NULLIF(TRIM(@GioiTinhChoPhep)), '');
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @MaLoaiPhong = NULLIF(TRIM(@MaLoaiPhong)), '');
    SET @TinhTrang = COALESCE(NULLIF(TRIM(@TinhTrang)), ''), 'Trống');
    SET @UrlImg = NULLIF(TRIM(@UrlImg)), '');

    IF @TenPhong IS NULL OR @GioiTinhChoPhep IS NULL OR @MaChiNhanh IS NULL OR @MaLoaiPhong IS NULL
        THROW 51061, 'Vui lòng nhập tên phòng, giới tính, chi nhánh và loại phòng.', 1;

    IF @GioiTinhChoPhep NOT IN ('Nam', 'Nữ', 'Không phân biệt')
        RAISE EXCEPTION %;

    IF @TinhTrang NOT IN ('Trống', 'Đã đặt cọc', 'Còn chỗ', 'Đầy', 'Giữ chỗ')
        RAISE EXCEPTION %;

    IF NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
        RAISE EXCEPTION %;

    IF NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
        RAISE EXCEPTION %;

    DECLARE @SucChuaLoaiPhong INT;
    SELECT @SucChuaLoaiPhong = SucChuaToiDa
    FROM dbo.LoaiPhong
    WHERE MaLoaiPhong = @MaLoaiPhong;

    IF @SoGiuong IS NULL
        SET @SoGiuong = @SucChuaLoaiPhong;

    IF @SoGiuong < 1 OR @SoGiuong > 99
        RAISE EXCEPTION %;

    IF @SoGiuong > @SucChuaLoaiPhong
        RAISE EXCEPTION %;

    DECLARE @SoPhong INT;
    DECLARE @SoChiNhanh INT = TRY_CONVERT(INT, SUBSTRING(@MaChiNhanh, 3, 4));
    DECLARE @Index INT = 1;
    DECLARE @MaGiuong VARCHAR(3);

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @MaPhong IS NULL
        BEGIN
            IF @SoChiNhanh IS NULL OR @SoChiNhanh NOT BETWEEN 1 AND 9
                RAISE EXCEPTION %;

            SELECT @SoPhong = COALESCE(MAX(TRY_CONVERT(INT, RIGHT(MaPhong, 2))), 0) + 1
            FROM dbo.Phong 
            WHERE MaChiNhanh = @MaChiNhanh
              AND MaPhong LIKE CONCAT('P', @SoChiNhanh, '[0-9][0-9]');

            IF @SoPhong > 99
                RAISE EXCEPTION %;

            SET @MaPhong = CONCAT('P', @SoChiNhanh, RIGHT(CONCAT('00', @SoPhong), 2));
        END;

        IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        INSERT INTO dbo.Phong (MaPhong, TenPhong, GioiTinhChoPhep, TinhTrang, MaChiNhanh, MaLoaiPhong)
        VALUES (@MaPhong, @TenPhong, @GioiTinhChoPhep, @TinhTrang, @MaChiNhanh, @MaLoaiPhong);

        IF @UrlImg IS NOT NULL
        BEGIN
            INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
            VALUES (@MaPhong, 1, @UrlImg);
        END;

        WHILE @Index <= @SoGiuong
        BEGIN
            SET @MaGiuong = CONCAT('G', RIGHT(CONCAT('00', @Index), 2));

            INSERT INTO dbo.Giuong (MaPhong, MaGiuong, SoGiuong, TinhTrang)
            VALUES (@MaPhong, @MaGiuong, @Index, 'Trống');

            SET @Index += 1;
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo phòng giường',
            @DoiTuong = 'Phong',
            @MaDoiTuong = @MaPhong,
            @NoiDung = @TenPhong;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        p.MaPhong AS maPhong,
        p.TenPhong AS tenPhong,
        p.GioiTinhChoPhep AS gioiTinhChoPhep,
        p.TinhTrang AS tinhTrangPhong,
        (SELECT TOP 1 hap.UrlImg FROM dbo.HinhAnhPhong AS hap WHERE hap.MaPhong = p.MaPhong ORDER BY hap.STTAnh) AS urlImgPhong,
        p.MaChiNhanh AS maChiNhanh,
        cn.TenChiNhanh AS tenChiNhanh,
        p.MaLoaiPhong AS maLoaiPhong,
        lp.TenLoaiPhong AS tenLoaiPhong,
        g.MaGiuong AS maGiuong,
        g.SoGiuong AS soGiuong,
        g.TinhTrang AS tinhTrangGiuong
    FROM dbo.Phong AS p
    INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    LEFT JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
    WHERE p.MaPhong = @MaPhong
    ORDER BY g.SoGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CapNhatTrangThaiPhongGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CapNhatTrangThaiPhongGiuong
    @LoaiDoiTuong VARCHAR(20),
    @MaPhong      VARCHAR(4),
    @MaGiuong     VARCHAR(3)   = NULL,
    @TrangThai    VARCHAR(20),
    @AdminId      VARCHAR(6)   = NULL
AS
BEGIN
    
    

    SET @LoaiDoiTuong = UPPER(NULLIF(TRIM(@LoaiDoiTuong)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');

    IF @LoaiDoiTuong NOT IN ('PHONG', 'GIUONG')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @LoaiDoiTuong = 'PHONG' AND @TrangThai NOT IN ('Trống', 'Đã đặt cọc', 'Còn chỗ', 'Đầy', 'Giữ chỗ', 'Bảo trì')
        RAISE EXCEPTION %;

    IF @LoaiDoiTuong = 'GIUONG' AND @TrangThai NOT IN ('Trống', 'Đã đặt cọc', 'Đang thuê')
        RAISE EXCEPTION %;

    IF @LoaiDoiTuong = 'GIUONG'
       AND (@MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
       ))
        RAISE EXCEPTION %;

    DECLARE @DuLieuTruoc TEXT;

    IF @LoaiDoiTuong = 'PHONG'
        SELECT @DuLieuTruoc = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );
    ELSE
        SELECT @DuLieuTruoc = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @LoaiDoiTuong = 'PHONG'
        BEGIN
            UPDATE dbo.Phong
            SET TinhTrang = @TrangThai
            WHERE MaPhong = @MaPhong;
        END
        ELSE
        BEGIN
            UPDATE dbo.Giuong
            SET TinhTrang = @TrangThai
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong;

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (
                    SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống'
                ) THEN 'Trống'
                WHEN NOT EXISTS (
                    SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống'
                ) THEN 'Đầy'
                WHEN EXISTS (
                    SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Đã đặt cọc'
                ) THEN 'Còn chỗ'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật trạng thái phòng/giường',
            @DoiTuong = @LoaiDoiTuong,
            @MaDoiTuong = @MaPhong,
            @NoiDung = @TrangThai,
            @DuLieuTruoc = @DuLieuTruoc;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        p.MaPhong AS maPhong,
        p.TenPhong AS tenPhong,
        p.TinhTrang AS tinhTrangPhong,
        g.MaGiuong AS maGiuong,
        g.SoGiuong AS soGiuong,
        g.TinhTrang AS tinhTrangGiuong
    FROM dbo.Phong AS p
    LEFT JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
    WHERE p.MaPhong = @MaPhong
      AND (@MaGiuong IS NULL OR g.MaGiuong = @MaGiuong)
    ORDER BY g.SoGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyPhong
    @ThaoTac         VARCHAR(20)  = 'DANH_SACH',
    @MaPhong         VARCHAR(4)    = NULL,
    @TenPhong        VARCHAR(100) = NULL,
    @GioiTinhChoPhep VARCHAR(20)  = NULL,
    @TinhTrang       VARCHAR(20)  = NULL,
    @UrlImg          VARCHAR(500)  = NULL,
    @MaChiNhanh      VARCHAR(6)    = NULL,
    @MaLoaiPhong     VARCHAR(6)    = NULL,
    @AdminId         VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @TenPhong = NULLIF(TRIM(@TenPhong)), '');
    SET @GioiTinhChoPhep = NULLIF(TRIM(@GioiTinhChoPhep)), '');
    SET @TinhTrang = NULLIF(TRIM(@TinhTrang)), '');
    SET @UrlImg = NULLIF(TRIM(@UrlImg)), '');
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @MaLoaiPhong = NULLIF(TRIM(@MaLoaiPhong)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            p.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            p.GioiTinhChoPhep AS gioiTinhChoPhep,
            p.TinhTrang AS tinhTrang,
            (SELECT TOP 1 hap.UrlImg FROM dbo.HinhAnhPhong AS hap WHERE hap.MaPhong = p.MaPhong ORDER BY hap.STTAnh) AS urlImg,
            p.MaChiNhanh AS maChiNhanh,
            cn.TenChiNhanh AS tenChiNhanh,
            p.MaLoaiPhong AS maLoaiPhong,
            lp.TenLoaiPhong AS tenLoaiPhong,
            COUNT(g.MaGiuong) AS soGiuong,
            SUM(CASE WHEN g.TinhTrang = 'Trống' THEN 1 ELSE 0 END) AS soGiuongTrong
        FROM dbo.Phong AS p
        INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
        INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
        LEFT JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
        WHERE (@MaPhong IS NULL OR p.MaPhong = @MaPhong)
          AND (@MaChiNhanh IS NULL OR p.MaChiNhanh = @MaChiNhanh)
          AND (@MaLoaiPhong IS NULL OR p.MaLoaiPhong = @MaLoaiPhong)
          AND (@TinhTrang IS NULL OR p.TinhTrang = @TinhTrang)
        GROUP BY p.MaPhong, p.TenPhong, p.GioiTinhChoPhep, p.TinhTrang,
                 p.MaChiNhanh, cn.TenChiNhanh, p.MaLoaiPhong, lp.TenLoaiPhong
        ORDER BY p.MaPhong;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO'
           AND (@TenPhong IS NULL OR @GioiTinhChoPhep IS NULL OR @MaChiNhanh IS NULL OR @MaLoaiPhong IS NULL)
            THROW 51102, 'Vui lòng nhập đầy đủ tên phòng, giới tính, chi nhánh và loại phòng.', 1;

        IF @GioiTinhChoPhep IS NOT NULL AND @GioiTinhChoPhep NOT IN ('Nam', 'Nữ', 'Không phân biệt')
            RAISE EXCEPTION %;

        IF @TinhTrang IS NOT NULL AND @TinhTrang NOT IN ('Trống', 'Đã đặt cọc', 'Còn chỗ', 'Đầy', 'Giữ chỗ', 'Bảo trì')
            RAISE EXCEPTION %;

        IF @MaChiNhanh IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
            RAISE EXCEPTION %;

        IF @MaLoaiPhong IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoPhongMoi INT;
        DECLARE @SoChiNhanhPhong INT = TRY_CONVERT(INT, SUBSTRING(@MaChiNhanh, 3, 4));

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaPhong IS NULL
            BEGIN
                IF @SoChiNhanhPhong IS NULL OR @SoChiNhanhPhong NOT BETWEEN 1 AND 9
                    RAISE EXCEPTION %;

                SELECT @SoPhongMoi = COALESCE(MAX(TRY_CONVERT(INT, RIGHT(MaPhong, 2))), 0) + 1
                FROM dbo.Phong 
                WHERE MaChiNhanh = @MaChiNhanh
                  AND MaPhong LIKE CONCAT('P', @SoChiNhanhPhong, '[0-9][0-9]');

                IF @SoPhongMoi > 99
                    RAISE EXCEPTION %;

                SET @MaPhong = CONCAT('P', @SoChiNhanhPhong, RIGHT(CONCAT('00', @SoPhongMoi), 2));
            END;

            IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
                RAISE EXCEPTION %;

            INSERT INTO dbo.Phong (MaPhong, TenPhong, GioiTinhChoPhep, TinhTrang, MaChiNhanh, MaLoaiPhong)
            VALUES (@MaPhong, @TenPhong, @GioiTinhChoPhep, COALESCE(@TinhTrang, 'Trống'), @MaChiNhanh, @MaLoaiPhong);

            IF @UrlImg IS NOT NULL
            BEGIN
                INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
                VALUES (@MaPhong, 1, @UrlImg);
            END;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo phòng',
                @DoiTuong = 'Phong',
                @MaDoiTuong = @MaPhong,
                @NoiDung = @TenPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocPhong TEXT;
        SELECT @DuLieuTruocPhong = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.Phong
        SET TenPhong = COALESCE(@TenPhong, TenPhong),
            GioiTinhChoPhep = COALESCE(@GioiTinhChoPhep, GioiTinhChoPhep),
            TinhTrang = COALESCE(@TinhTrang, TinhTrang),
            MaChiNhanh = COALESCE(@MaChiNhanh, MaChiNhanh),
            MaLoaiPhong = COALESCE(@MaLoaiPhong, MaLoaiPhong)
        WHERE MaPhong = @MaPhong;

        IF @UrlImg IS NOT NULL
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.HinhAnhPhong WHERE MaPhong = @MaPhong AND STTAnh = 1)
                UPDATE dbo.HinhAnhPhong
                SET UrlImg = @UrlImg
                WHERE MaPhong = @MaPhong AND STTAnh = 1;
            ELSE
                INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
                VALUES (@MaPhong, 1, @UrlImg);
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật phòng',
            @DoiTuong = 'Phong',
            @MaDoiTuong = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocPhong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống')
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc AS ctdc
            INNER JOIN dbo.PhieuDatCoc AS pdc ON pdc.MaPhieuDatCoc = ctdc.MaPhieuDatCoc
            WHERE ctdc.MaPhong = @MaPhong
              AND pdc.TrangThaiCoc IN ('Hiệu lực', 'Đã lập HĐ')
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietDatCoc WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong)
           OR EXISTS (SELECT 1 FROM dbo.ChiTietXemPhong WHERE MaPhong = @MaPhong)
           OR EXISTS (SELECT 1 FROM dbo.PhieuGhiChiSo WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocPhongXoa TEXT;
        SELECT @DuLieuTruocPhongXoa = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        BEGIN TRY
            BEGIN TRANSACTION;

            DELETE FROM dbo.Giuong WHERE MaPhong = @MaPhong;
            DELETE FROM dbo.Phong WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa phòng',
                @DoiTuong = 'Phong',
                @MaDoiTuong = @MaPhong,
                @DuLieuTruoc = @DuLieuTruocPhongXoa;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyPhong @ThaoTac = 'DANH_SACH', @MaPhong = @MaPhong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyGiuong
    @ThaoTac   VARCHAR(20) = 'DANH_SACH',
    @MaPhong   VARCHAR(4)   = NULL,
    @MaGiuong  VARCHAR(3)   = NULL,
    @SoGiuong  INT          = NULL,
    @TinhTrang VARCHAR(20) = NULL,
    @UrlImg    VARCHAR(500) = NULL,
    @AdminId   VARCHAR(6)   = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    SET @TinhTrang = NULLIF(TRIM(@TinhTrang)), '');
    SET @UrlImg = NULLIF(TRIM(@UrlImg)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            g.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            g.MaGiuong AS maGiuong,
            g.SoGiuong AS soGiuong,
            g.TinhTrang AS tinhTrang,
            lp.SucChuaToiDa AS sucChuaToiDa,
            (
                SELECT COUNT(1)
                FROM dbo.TaiSan AS tsChung
                WHERE tsChung.MaPhong = g.MaPhong
                  AND tsChung.LoaiTaiSan = 'Chung'
            ) AS soTaiSanChung,
            CAST(0 AS INT) AS soTaiSanRieng
        FROM dbo.Giuong AS g
        INNER JOIN dbo.Phong AS p ON p.MaPhong = g.MaPhong
        INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
        WHERE (@MaPhong IS NULL OR g.MaPhong = @MaPhong)
          AND (@MaGiuong IS NULL OR g.MaGiuong = @MaGiuong)
          AND (@TinhTrang IS NULL OR g.TinhTrang = @TinhTrang)
        ORDER BY g.MaPhong, g.SoGiuong, g.MaGiuong;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @SoGiuong IS NULL
            RAISE EXCEPTION %;

        IF @SoGiuong IS NOT NULL AND @SoGiuong < 1
            RAISE EXCEPTION %;

        IF @TinhTrang IS NOT NULL AND @TinhTrang NOT IN ('Trống', 'Đã đặt cọc', 'Đang thuê')
            RAISE EXCEPTION %;
    END;

    DECLARE @SucChuaToiDa INT;
    SELECT @SucChuaToiDa = lp.SucChuaToiDa
    FROM dbo.Phong AS p
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    WHERE p.MaPhong = @MaPhong;

    IF @SoGiuong IS NOT NULL AND @SoGiuong > @SucChuaToiDa
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF (SELECT COUNT(*) FROM dbo.Giuong WHERE MaPhong = @MaPhong) >= @SucChuaToiDa
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND SoGiuong = @SoGiuong)
            RAISE EXCEPTION %;

        IF @MaGiuong IS NULL
        BEGIN
            DECLARE @SoMaGiuong INT;
            SELECT @SoMaGiuong = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaGiuong, 2, 2))), 0) + 1
            FROM dbo.Giuong 
            WHERE MaPhong = @MaPhong
              AND MaGiuong LIKE 'G[0-9][0-9]';

            IF @SoMaGiuong > 99
                RAISE EXCEPTION %;

            SET @MaGiuong = CONCAT('G', RIGHT(CONCAT('00', @SoMaGiuong), 2));
        END;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong)
            RAISE EXCEPTION %;

        BEGIN TRY
            BEGIN TRANSACTION;

            INSERT INTO dbo.Giuong (MaPhong, MaGiuong, SoGiuong, TinhTrang)
            VALUES (@MaPhong, @MaGiuong, @SoGiuong, COALESCE(@TinhTrang, 'Trống'));

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo giường',
                @DoiTuong = 'Giuong',
                @MaDoiTuong = @MaGiuong,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF @SoGiuong IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.Giuong
            WHERE MaPhong = @MaPhong
              AND SoGiuong = @SoGiuong
              AND MaGiuong <> @MaGiuong
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocGiuong TEXT;
        SELECT @DuLieuTruocGiuong = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.Giuong
        SET SoGiuong = COALESCE(@SoGiuong, SoGiuong),
            TinhTrang = COALESCE(@TinhTrang, TinhTrang)
        WHERE MaPhong = @MaPhong
          AND MaGiuong = @MaGiuong;

        UPDATE dbo.Phong
        SET TinhTrang = CASE
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong) THEN 'Trống'
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
            ELSE 'Còn chỗ'
        END
        WHERE MaPhong = @MaPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật giường',
            @DoiTuong = 'Giuong',
            @MaDoiTuong = @MaGiuong,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocGiuong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1 FROM dbo.Giuong
            WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong AND TinhTrang <> 'Trống'
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc AS ctdc
            INNER JOIN dbo.PhieuDatCoc AS pdc ON pdc.MaPhieuDatCoc = ctdc.MaPhieuDatCoc
            WHERE ctdc.MaPhong = @MaPhong
              AND ctdc.MaGiuong = @MaGiuong
              AND pdc.TrangThaiCoc IN ('Hiệu lực', 'Đã lập HĐ')
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietXemPhong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocGiuongXoa TEXT;
        SELECT @DuLieuTruocGiuongXoa = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        BEGIN TRY
            BEGIN TRANSACTION;

            DELETE FROM dbo.Giuong
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong;

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong) THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa giường',
                @DoiTuong = 'Giuong',
                @MaDoiTuong = @MaGiuong,
                @NoiDung = @MaPhong,
                @DuLieuTruoc = @DuLieuTruocGiuongXoa;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaGiuong AS maGiuong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyGiuong @ThaoTac = 'DANH_SACH', @MaPhong = @MaPhong, @MaGiuong = @MaGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyTaiSanPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyTaiSanPhong
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaPhong   VARCHAR(4)    = NULL,
    @MaTaiSan  VARCHAR(6)    = NULL,
    @TenTaiSan VARCHAR(100) = NULL,
    @SoLuong   INT           = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @LoaiTaiSan VARCHAR(20) = NULL,
    @MaGiuong   VARCHAR(3)   = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaTaiSan = NULLIF(TRIM(@MaTaiSan)), '');
    SET @TenTaiSan = NULLIF(TRIM(@TenTaiSan)), '');
    SET @LoaiTaiSan = NULLIF(TRIM(@LoaiTaiSan)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            ts.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            ts.MaTaiSan AS maTaiSan,
            ts.TenTaiSan AS tenTaiSan,
            ts.SoLuong AS soLuong,
            ts.DonGia AS donGia,
            ts.LoaiTaiSan AS loaiTaiSan,
            ts.MaGiuong AS maGiuong,
            g.SoGiuong AS soGiuong
        FROM dbo.TaiSan AS ts
        INNER JOIN dbo.Phong AS p ON p.MaPhong = ts.MaPhong
        LEFT JOIN dbo.Giuong AS g ON g.MaPhong = ts.MaPhong AND g.MaGiuong = ts.MaGiuong
        WHERE (@MaPhong IS NULL OR ts.MaPhong = @MaPhong)
          AND (@MaTaiSan IS NULL OR ts.MaTaiSan = @MaTaiSan)
          AND (@MaGiuong IS NULL OR ts.MaGiuong = @MaGiuong)
          AND (@LoaiTaiSan IS NULL OR ts.LoaiTaiSan = @LoaiTaiSan)
        ORDER BY ts.MaPhong, ts.LoaiTaiSan, ts.MaGiuong, ts.MaTaiSan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TenTaiSan IS NULL
            RAISE EXCEPTION %;

        IF @SoLuong IS NOT NULL AND @SoLuong <= 0
            RAISE EXCEPTION %;

        IF @DonGia IS NOT NULL AND @DonGia < 0
            RAISE EXCEPTION %;

        DECLARE @LoaiTaiSanSau VARCHAR(20);
        DECLARE @MaGiuongSau VARCHAR(3);

        IF @ThaoTac = 'TAO'
        BEGIN
            SET @LoaiTaiSanSau = COALESCE(@LoaiTaiSan, 'Chung');
            SET @MaGiuongSau = @MaGiuong;
        END
        ELSE
        BEGIN
            IF @MaTaiSan IS NULL OR NOT EXISTS (
                SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
            )
                RAISE EXCEPTION %;

            SELECT
                @LoaiTaiSanSau = COALESCE(@LoaiTaiSan, LoaiTaiSan),
                @MaGiuongSau = CASE
                    WHEN @LoaiTaiSan = 'Chung' THEN NULL
                    ELSE COALESCE(@MaGiuong, MaGiuong)
                END
            FROM dbo.TaiSan
            WHERE MaPhong = @MaPhong
              AND MaTaiSan = @MaTaiSan;
        END;

        IF @LoaiTaiSanSau NOT IN ('Chung', 'Riêng')
            RAISE EXCEPTION %;

        IF @LoaiTaiSanSau = 'Chung'
            SET @MaGiuongSau = NULL;

        IF @LoaiTaiSanSau = 'Riêng' AND @MaGiuongSau IS NULL
            RAISE EXCEPTION %;

        IF @MaGiuongSau IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuongSau
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoTaiSan INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaTaiSan IS NULL
            BEGIN
                SELECT @SoTaiSan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaTaiSan, 3, 4))), 0) + 1
                FROM dbo.TaiSan 
                WHERE MaPhong = @MaPhong
                  AND MaTaiSan LIKE 'TS[0-9][0-9][0-9][0-9]';

                IF @SoTaiSan > 9999
                    RAISE EXCEPTION %;

                SET @MaTaiSan = CONCAT('TS', RIGHT(CONCAT('0000', @SoTaiSan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.TaiSan (
                MaPhong, MaTaiSan, TenTaiSan, SoLuong, DonGia, LoaiTaiSan, MaGiuong
            )
            VALUES (
                @MaPhong, @MaTaiSan, @TenTaiSan, COALESCE(@SoLuong, 1),
                @DonGia, @LoaiTaiSanSau, @MaGiuongSau
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo tài sản phòng',
                @DoiTuong = 'TaiSan',
                @MaDoiTuong = @MaTaiSan,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocTaiSan TEXT;
        SELECT @DuLieuTruocTaiSan = (
            SELECT * FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.TaiSan
        SET TenTaiSan = COALESCE(@TenTaiSan, TenTaiSan),
            SoLuong = COALESCE(@SoLuong, SoLuong),
            DonGia = COALESCE(@DonGia, DonGia),
            LoaiTaiSan = @LoaiTaiSanSau,
            MaGiuong = @MaGiuongSau
        WHERE MaPhong = @MaPhong
          AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocTaiSan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietBanGiao WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.ChiTietHuHong WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.YeuCauSuaChua WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaTaiSan AS maTaiSan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyTaiSanPhong
        @ThaoTac = 'DANH_SACH',
        @MaPhong = @MaPhong,
        @MaTaiSan = @MaTaiSan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc
    @ThaoTac           VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinhHoanCoc VARCHAR(6)    = NULL,
    @TenQuyDinh        VARCHAR(255) = NULL,
    @TyLeHoanCoc       DECIMAL(5,2)  = NULL,
    @AdminId           VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinhHoanCoc = NULLIF(TRIM(@MaQuyDinhHoanCoc)), '');
    SET @TenQuyDinh = NULLIF(TRIM(@TenQuyDinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qh.MaQuyDinhHoanCoc AS maQuyDinhHoanCoc,
            qh.TenQuyDinh AS tenQuyDinh,
            qh.TyLeHoanCoc AS tyLeHoanCoc,
            COUNT(ds.MaQuyDinhHoanCoc) AS soLanApDung
        FROM dbo.QuyDinhHoanCoc AS qh
        LEFT JOIN dbo.DoiSoat AS ds ON ds.MaQuyDinhHoanCoc = qh.MaQuyDinhHoanCoc
        WHERE (@MaQuyDinhHoanCoc IS NULL OR qh.MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
        GROUP BY qh.MaQuyDinhHoanCoc, qh.TenQuyDinh, qh.TyLeHoanCoc
        ORDER BY qh.MaQuyDinhHoanCoc;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenQuyDinh IS NULL OR @TyLeHoanCoc IS NULL)
            RAISE EXCEPTION %;

        IF @TyLeHoanCoc IS NOT NULL AND (@TyLeHoanCoc < 0 OR @TyLeHoanCoc > 100)
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinh INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinhHoanCoc IS NULL
            BEGIN
                SELECT @SoQuyDinh = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinhHoanCoc, 3, 4))), 0) + 1
                FROM dbo.QuyDinhHoanCoc 
                WHERE MaQuyDinhHoanCoc LIKE 'QH[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinh > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinhHoanCoc = CONCAT('QH', RIGHT(CONCAT('0000', @SoQuyDinh), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuyDinhHoanCoc (MaQuyDinhHoanCoc, TenQuyDinh, TyLeHoanCoc)
            VALUES (@MaQuyDinhHoanCoc, @TenQuyDinh, @TyLeHoanCoc);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo quy định hoàn cọc',
                @DoiTuong = 'QuyDinhHoanCoc',
                @MaDoiTuong = @MaQuyDinhHoanCoc,
                @NoiDung = @TenQuyDinh;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocHoanCoc TEXT;
        SELECT @DuLieuTruocHoanCoc = (
            SELECT * FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuyDinhHoanCoc
        SET TenQuyDinh = COALESCE(@TenQuyDinh, TenQuyDinh),
            TyLeHoanCoc = COALESCE(@TyLeHoanCoc, TyLeHoanCoc)
        WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc,
            @DuLieuTruoc = @DuLieuTruocHoanCoc;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DoiSoat WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinhHoanCoc AS maQuyDinhHoanCoc;
        RETURN;
    END;

    EXEC dbo.SP_Admin_CauHinhQuyDinhHoanCoc @ThaoTac = 'DANH_SACH', @MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDichVu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDichVu
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaDichVu  VARCHAR(6)    = NULL,
    @TenDichVu VARCHAR(100) = NULL,
    @DonViTinh VARCHAR(20)   = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDichVu = NULLIF(TRIM(@MaDichVu)), '');
    SET @TenDichVu = NULLIF(TRIM(@TenDichVu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dv.MaDichVu AS maDichVu,
            dv.TenDichVu AS tenDichVu,
            dv.DonViTinh AS donViTinh,
            dv.DonGia AS donGia,
            COUNT(DISTINCT dvhd.MaChiTietDVHD) AS soHopDongSuDung,
            COUNT(cthd.MaChiTietHD) AS soDongHoaDon
        FROM dbo.DichVu AS dv
        LEFT JOIN dbo.DichVuHopDong AS dvhd ON dvhd.MaDichVu = dv.MaDichVu
        LEFT JOIN dbo.ChiTietHoaDon AS cthd ON cthd.MaChiTietDVHD = dvhd.MaChiTietDVHD
        WHERE (@MaDichVu IS NULL OR dv.MaDichVu = @MaDichVu)
          AND (@TenDichVu IS NULL OR dv.TenDichVu LIKE '%' + @TenDichVu + '%')
        GROUP BY dv.MaDichVu, dv.TenDichVu, dv.DonViTinh, dv.DonGia
        ORDER BY dv.MaDichVu;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDichVu IS NULL OR @DonViTinh IS NULL OR @DonGia IS NULL)
            THROW 51202, 'Vui lòng nhập tên dịch vụ, đơn vị tính và đơn giá.', 1;

        IF @DonGia IS NOT NULL AND @DonGia <= 0
            RAISE EXCEPTION %;

        IF @TenDichVu IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DichVu
            WHERE TenDichVu = @TenDichVu
              AND (@MaDichVu IS NULL OR MaDichVu <> @MaDichVu)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDichVu INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDichVu IS NULL
            BEGIN
                SELECT @SoDichVu = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDichVu, 3, 4))), 0) + 1
                FROM dbo.DichVu 
                WHERE MaDichVu LIKE 'DV[0-9][0-9][0-9][0-9]';

                IF @SoDichVu > 9999
                    RAISE EXCEPTION %;

                SET @MaDichVu = CONCAT('DV', RIGHT(CONCAT('0000', @SoDichVu), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DichVu (MaDichVu, TenDichVu, DonViTinh, DonGia)
            VALUES (@MaDichVu, @TenDichVu, @DonViTinh, @DonGia);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo dịch vụ',
                @DoiTuong = 'DichVu',
                @MaDoiTuong = @MaDichVu,
                @NoiDung = @TenDichVu;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocDichVu TEXT;
        SELECT @DuLieuTruocDichVu = (
            SELECT * FROM dbo.DichVu WHERE MaDichVu = @MaDichVu FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DichVu
        SET TenDichVu = COALESCE(@TenDichVu, TenDichVu),
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            DonGia = COALESCE(@DonGia, DonGia)
        WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu,
            @DuLieuTruoc = @DuLieuTruocDichVu;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DichVuHopDong WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DichVu WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDichVu AS maDichVu;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDichVu @ThaoTac = 'DANH_SACH', @MaDichVu = @MaDichVu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyNoiQuy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyNoiQuy
    @ThaoTac      VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinh    VARCHAR(6)    = NULL,
    @TieuDeNoiQuy VARCHAR(255) = NULL,
    @NoiDung      TEXT = NULL,
    @TrangThai    VARCHAR(20)  = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinh = NULLIF(TRIM(@MaQuyDinh)), '');
    SET @TieuDeNoiQuy = NULLIF(TRIM(@TieuDeNoiQuy)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qd.MaQuyDinh AS maQuyDinh,
            qd.TieuDeNoiQuy AS tieuDeNoiQuy,
            qd.NoiDung AS noiDung,
            qd.TrangThai AS trangThai
        FROM dbo.QuiDinh AS qd
        WHERE (@MaQuyDinh IS NULL OR qd.MaQuyDinh = @MaQuyDinh)
          AND (@TrangThai IS NULL OR qd.TrangThai = @TrangThai)
          AND (@TieuDeNoiQuy IS NULL OR qd.TieuDeNoiQuy LIKE '%' + @TieuDeNoiQuy + '%')
        ORDER BY qd.MaQuyDinh;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TieuDeNoiQuy IS NULL
            RAISE EXCEPTION %;

        IF @TieuDeNoiQuy IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.QuiDinh
            WHERE TieuDeNoiQuy = @TieuDeNoiQuy
              AND (@MaQuyDinh IS NULL OR MaQuyDinh <> @MaQuyDinh)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinhNoiQuy INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinh IS NULL
            BEGIN
                SELECT @SoQuyDinhNoiQuy = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinh, 3, 4))), 0) + 1
                FROM dbo.QuiDinh 
                WHERE MaQuyDinh LIKE 'QD[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinhNoiQuy > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinh = CONCAT('QD', RIGHT(CONCAT('0000', @SoQuyDinhNoiQuy), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuiDinh (MaQuyDinh, TieuDeNoiQuy, NoiDung, TrangThai)
            VALUES (@MaQuyDinh, @TieuDeNoiQuy, @NoiDung, COALESCE(@TrangThai, 'Hiệu lực'));

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo nội quy',
                @DoiTuong = 'QuiDinh',
                @MaDoiTuong = @MaQuyDinh,
                @NoiDung = @TieuDeNoiQuy;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocNoiQuy TEXT;
        SELECT @DuLieuTruocNoiQuy = (
            SELECT * FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuiDinh
        SET TieuDeNoiQuy = COALESCE(@TieuDeNoiQuy, TieuDeNoiQuy),
            NoiDung = COALESCE(@NoiDung, NoiDung),
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh,
            @DuLieuTruoc = @DuLieuTruocNoiQuy;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        UPDATE dbo.QuiDinh
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinh AS maQuyDinh;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyNoiQuy @ThaoTac = 'DANH_SACH', @MaQuyDinh = @MaQuyDinh;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham
    @ThaoTac        VARCHAR(20)  = 'DANH_SACH',
    @MaDieuKhoan    VARCHAR(6)    = NULL,
    @TenDieuKhoan   VARCHAR(255) = NULL,
    @HinhThucXuPhat VARCHAR(20)  = NULL,
    @MucPhat        DECIMAL(15,2) = NULL,
    @TrangThai      VARCHAR(20)  = NULL,
    @AdminId        VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDieuKhoan = NULLIF(TRIM(@MaDieuKhoan)), '');
    SET @TenDieuKhoan = NULLIF(TRIM(@TenDieuKhoan)), '');
    SET @HinhThucXuPhat = NULLIF(TRIM(@HinhThucXuPhat)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dk.MaDieuKhoan AS maDieuKhoan,
            dk.TenDieuKhoan AS tenDieuKhoan,
            dk.HinhThucXuPhat AS hinhThucXuPhat,
            dk.MucPhat AS mucPhat,
            dk.TrangThai AS trangThai,
            COUNT(bb.MaBBViPham) AS soBienBanApDung
        FROM dbo.DieuKhoanViPham AS dk
        LEFT JOIN dbo.BienBanViPham AS bb ON bb.MaDieuKhoan = dk.MaDieuKhoan
        WHERE (@MaDieuKhoan IS NULL OR dk.MaDieuKhoan = @MaDieuKhoan)
          AND (@TrangThai IS NULL OR dk.TrangThai = @TrangThai)
          AND (@TenDieuKhoan IS NULL OR dk.TenDieuKhoan LIKE '%' + @TenDieuKhoan + '%')
        GROUP BY dk.MaDieuKhoan, dk.TenDieuKhoan, dk.HinhThucXuPhat, dk.MucPhat, dk.TrangThai
        ORDER BY dk.MaDieuKhoan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @HinhThucXuPhat IS NOT NULL AND @HinhThucXuPhat NOT IN ('Nhắc nhở', 'Phạt tiền')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @MucPhat IS NOT NULL AND @MucPhat < 0
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDieuKhoan IS NULL OR @HinhThucXuPhat IS NULL)
            RAISE EXCEPTION %;

        IF @TenDieuKhoan IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DieuKhoanViPham
            WHERE TenDieuKhoan = @TenDieuKhoan
              AND (@MaDieuKhoan IS NULL OR MaDieuKhoan <> @MaDieuKhoan)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDieuKhoan INT;

        IF @HinhThucXuPhat = 'Phạt tiền' AND COALESCE(@MucPhat, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucXuPhat = 'Nhắc nhở' AND @MucPhat IS NULL
            SET @MucPhat = 0;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDieuKhoan IS NULL
            BEGIN
                SELECT @SoDieuKhoan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDieuKhoan, 3, 4))), 0) + 1
                FROM dbo.DieuKhoanViPham 
                WHERE MaDieuKhoan LIKE 'VP[0-9][0-9][0-9][0-9]';

                IF @SoDieuKhoan > 9999
                    RAISE EXCEPTION %;

                SET @MaDieuKhoan = CONCAT('VP', RIGHT(CONCAT('0000', @SoDieuKhoan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DieuKhoanViPham (
                MaDieuKhoan, TenDieuKhoan, HinhThucXuPhat, MucPhat, TrangThai
            )
            VALUES (
                @MaDieuKhoan, @TenDieuKhoan, @HinhThucXuPhat, COALESCE(@MucPhat, 0), COALESCE(@TrangThai, 'Hiệu lực')
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo điều khoản vi phạm',
                @DoiTuong = 'DieuKhoanViPham',
                @MaDoiTuong = @MaDieuKhoan,
                @NoiDung = @TenDieuKhoan;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DECLARE @HinhThucSau VARCHAR(20);
        DECLARE @MucPhatSau DECIMAL(15,2);

        SELECT
            @HinhThucSau = COALESCE(@HinhThucXuPhat, HinhThucXuPhat),
            @MucPhatSau = COALESCE(@MucPhat, MucPhat)
        FROM dbo.DieuKhoanViPham
        WHERE MaDieuKhoan = @MaDieuKhoan;

        IF @HinhThucSau = 'Phạt tiền' AND COALESCE(@MucPhatSau, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucSau = 'Nhắc nhở' AND @MucPhatSau IS NULL
            SET @MucPhatSau = 0;

        DECLARE @DuLieuTruocDieuKhoan TEXT;
        SELECT @DuLieuTruocDieuKhoan = (
            SELECT * FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DieuKhoanViPham
        SET TenDieuKhoan = COALESCE(@TenDieuKhoan, TenDieuKhoan),
            HinhThucXuPhat = @HinhThucSau,
            MucPhat = @MucPhatSau,
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan,
            @DuLieuTruoc = @DuLieuTruocDieuKhoan;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        UPDATE dbo.DieuKhoanViPham
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.BienBanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDieuKhoan AS maDieuKhoan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDieuKhoanViPham @ThaoTac = 'DANH_SACH', @MaDieuKhoan = @MaDieuKhoan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhThamSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhThamSo
    @ThaoTac    VARCHAR(20)  = 'DANH_SACH',
    @MaThamSo   VARCHAR(50)   = NULL,
    @NhomThamSo VARCHAR(50)  = NULL,
    @TenThamSo  VARCHAR(100) = NULL,
    @GiaTri     VARCHAR(255) = NULL,
    @KieuDuLieu VARCHAR(20)  = NULL,
    @DonViTinh  VARCHAR(30)  = NULL,
    @MoTa       TEXT = NULL,
    @AdminId    VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaThamSo = NULLIF(TRIM(@MaThamSo)), '');
    SET @NhomThamSo = NULLIF(TRIM(@NhomThamSo)), '');
    SET @TenThamSo = NULLIF(TRIM(@TenThamSo)), '');
    SET @GiaTri = NULLIF(TRIM(@GiaTri)), '');
    SET @KieuDuLieu = NULLIF(TRIM(@KieuDuLieu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            MaThamSo AS maThamSo,
            NhomThamSo AS nhomThamSo,
            TenThamSo AS tenThamSo,
            GiaTri AS giaTri,
            KieuDuLieu AS kieuDuLieu,
            DonViTinh AS donViTinh,
            MoTa AS moTa,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.ThamSoHeThong
        WHERE (@MaThamSo IS NULL OR MaThamSo = @MaThamSo)
          AND (@NhomThamSo IS NULL OR NhomThamSo = @NhomThamSo)
        ORDER BY NhomThamSo, MaThamSo;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT')
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO' AND (@MaThamSo IS NULL OR @NhomThamSo IS NULL OR @TenThamSo IS NULL OR @GiaTri IS NULL)
        THROW 51262, 'Vui lòng nhập đủ mã, nhóm, tên và giá trị tham số.', 1;

    IF @MaThamSo IS NULL
        RAISE EXCEPTION %;

    IF @KieuDuLieu IS NOT NULL AND @KieuDuLieu NOT IN ('Chuỗi', 'Số', 'Ngày', 'Boolean')
        RAISE EXCEPTION %;

    DECLARE @KieuDuLieuSau VARCHAR(20);
    DECLARE @GiaTriSau VARCHAR(255);

    IF @ThaoTac = 'TAO'
    BEGIN
        SET @KieuDuLieuSau = COALESCE(@KieuDuLieu, 'Chuỗi');
        SET @GiaTriSau = @GiaTri;
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        SELECT
            @KieuDuLieuSau = COALESCE(@KieuDuLieu, KieuDuLieu),
            @GiaTriSau = COALESCE(@GiaTri, GiaTri)
        FROM dbo.ThamSoHeThong
        WHERE MaThamSo = @MaThamSo;
    END;

    IF @KieuDuLieuSau = 'Số' AND (TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) IS NULL OR TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) < 0)
        RAISE EXCEPTION %;

    IF @MaThamSo = 'THOI_HAN_THANH_TOAN_COC_GIO'
       AND (TRY_CONVERT(INT, @GiaTriSau) IS NULL OR TRY_CONVERT(INT, @GiaTriSau) <= 0)
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        INSERT INTO dbo.ThamSoHeThong (
            MaThamSo, NhomThamSo, TenThamSo, GiaTri, KieuDuLieu, DonViTinh, MoTa, CapNhatBoi
        )
        VALUES (
            @MaThamSo, @NhomThamSo, @TenThamSo, @GiaTriSau, @KieuDuLieuSau, @DonViTinh, @MoTa, @AdminId
        );

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @NoiDung = @TenThamSo;
    END
    ELSE
    BEGIN
        DECLARE @DuLieuTruocThamSo TEXT;
        SELECT @DuLieuTruocThamSo = (
            SELECT * FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.ThamSoHeThong
        SET NhomThamSo = COALESCE(@NhomThamSo, NhomThamSo),
            TenThamSo = COALESCE(@TenThamSo, TenThamSo),
            GiaTri = @GiaTriSau,
            KieuDuLieu = @KieuDuLieuSau,
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            MoTa = COALESCE(@MoTa, MoTa),
            CapNhatLuc = CURRENT_TIMESTAMP,
            CapNhatBoi = @AdminId
        WHERE MaThamSo = @MaThamSo;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @DuLieuTruoc = @DuLieuTruocThamSo;
    END;

    EXEC dbo.SP_Admin_CauHinhThamSo @ThaoTac = 'DANH_SACH', @MaThamSo = @MaThamSo;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhSaoLuu
    @ChuKyFull        VARCHAR(20)  = NULL,
    @ChuKyIncremental VARCHAR(20)  = NULL,
    @ThuMucLuuTru     VARCHAR(500) = NULL,
    @AdminId          VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ChuKyFull = NULLIF(TRIM(@ChuKyFull)), '');
    SET @ChuKyIncremental = NULLIF(TRIM(@ChuKyIncremental)), '');
    SET @ThuMucLuuTru = NULLIF(TRIM(@ThuMucLuuTru)), '');

    IF @ChuKyFull IS NOT NULL AND @ChuKyFull NOT IN ('Hàng tuần', 'Hàng tháng')
        RAISE EXCEPTION %;

    IF @ChuKyIncremental IS NOT NULL AND @ChuKyIncremental NOT IN ('Hàng ngày', 'Hàng tuần')
        RAISE EXCEPTION %;

    IF @ThuMucLuuTru IS NOT NULL
    BEGIN
        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);
    END;

    IF @ChuKyFull IS NULL AND @ChuKyIncremental IS NULL AND @ThuMucLuuTru IS NULL
    BEGIN
        SELECT
            MaCauHinh AS maCauHinh,
            ChuKyFull AS chuKyFull,
            ChuKyIncremental AS chuKyIncremental,
            ThuMucLuuTru AS thuMucLuuTru,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;
        RETURN;
    END;

    DECLARE @DuLieuTruocSaoLuu TEXT;
    SELECT @DuLieuTruocSaoLuu = (
        SELECT * FROM dbo.CauHinhSaoLuu WHERE MaCauHinh = 1 FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    UPDATE dbo.CauHinhSaoLuu
    SET ChuKyFull = COALESCE(@ChuKyFull, ChuKyFull),
        ChuKyIncremental = COALESCE(@ChuKyIncremental, ChuKyIncremental),
        ThuMucLuuTru = COALESCE(@ThuMucLuuTru, ThuMucLuuTru),
        CapNhatLuc = CURRENT_TIMESTAMP,
        CapNhatBoi = @AdminId
    WHERE MaCauHinh = 1;

    EXEC dbo.SP_Admin_GhiNhatKy
        @AdminId = @AdminId,
        @HanhDong = 'Cấu hình sao lưu',
        @DoiTuong = 'CauHinhSaoLuu',
        @MaDoiTuong = '1',
        @DuLieuTruoc = @DuLieuTruocSaoLuu;

    SELECT
        MaCauHinh AS maCauHinh,
        ChuKyFull AS chuKyFull,
        ChuKyIncremental AS chuKyIncremental,
        ThuMucLuuTru AS thuMucLuuTru,
        CapNhatLuc AS capNhatLuc,
        CapNhatBoi AS capNhatBoi
    FROM dbo.CauHinhSaoLuu
    WHERE MaCauHinh = 1;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_SaoLuuThuCong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_SaoLuuThuCong
    @LoaiSaoLuu  VARCHAR(20)  = 'Full',
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    

    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');
    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');
    IF @LoaiSaoLuu IS NULL SET @LoaiSaoLuu = 'Full';

    DECLARE @LoaiSaoLuuChuan VARCHAR(20) = UPPER(@LoaiSaoLuu);
    IF @LoaiSaoLuuChuan = 'FULL'
        SET @LoaiSaoLuu = 'Full';
    ELSE IF @LoaiSaoLuuChuan IN ('INCREMENTAL', 'DIFFERENTIAL')
        SET @LoaiSaoLuu = 'Incremental';

    IF @LoaiSaoLuu NOT IN ('Full', 'Incremental')
        RAISE EXCEPTION %;

    IF @DuongDanFile IS NULL
    BEGIN
        DECLARE @ThuMucLuuTru VARCHAR(500);
        SELECT @ThuMucLuuTru = ThuMucLuuTru
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;

        IF @ThuMucLuuTru IS NULL
            RAISE EXCEPTION %;

        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);

        SET @DuongDanFile =
            @ThuMucLuuTru + '\' + DB_NAME() + '_' + @LoaiSaoLuu + '_' +
            CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112) + REPLACE(CONVERT(CHAR(8), CURRENT_TIMESTAMP, 108), ':', '') + '.bak';
    END;

    DECLARE @MaSaoLuu INT;
    DECLARE @LenhSaoLuu TEXT;

    INSERT INTO dbo.LichSuSaoLuu (
        LoaiSaoLuu, DuongDanFile, TrangThai, ThoiGianBatDau, MaNguoiDung
    )
    VALUES (
        @LoaiSaoLuu, @DuongDanFile, 'Đang chạy', CURRENT_TIMESTAMP, @AdminId
    );

    SET @MaSaoLuu = SCOPE_IDENTITY();
    SET @LenhSaoLuu =
        'BACKUP DATABASE ' + QUOTENAME(DB_NAME()) +
        ' TO DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') +
        ''' WITH ' +
        CASE WHEN @LoaiSaoLuu = 'Incremental' THEN 'DIFFERENTIAL, INIT' ELSE 'INIT' END +
        ';';

    BEGIN TRY
        EXEC(@LenhSaoLuu);

        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thành công',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = 'Sao lưu hoàn tất.'
        WHERE MaSaoLuu = @MaSaoLuu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Sao lưu thủ công',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thất bại',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = ERROR_MESSAGE()
        WHERE MaSaoLuu = @MaSaoLuu;

        THROW;
    END CATCH;

    SELECT
        MaSaoLuu AS maSaoLuu,
        LoaiSaoLuu AS loaiSaoLuu,
        DuongDanFile AS duongDanFile,
        TrangThai AS trangThai,
        ThoiGianBatDau AS thoiGianBatDau,
        ThoiGianKetThuc AS thoiGianKetThuc,
        ThongBao AS thongBao
    FROM dbo.LichSuSaoLuu
    WHERE MaSaoLuu = @MaSaoLuu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_DanhSachSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_DanhSachSaoLuu
    @SoDong     INT          = 100,
    @TrangThai  VARCHAR(20) = NULL,
    @LoaiSaoLuu VARCHAR(20) = NULL
AS
BEGIN
    

    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 100;

    SELECT TOP (@SoDong)
        ls.MaSaoLuu AS maSaoLuu,
        ls.LoaiSaoLuu AS loaiSaoLuu,
        ls.DuongDanFile AS duongDanFile,
        ls.DungLuongByte AS dungLuongByte,
        ls.TrangThai AS trangThai,
        ls.ThoiGianBatDau AS thoiGianBatDau,
        ls.ThoiGianKetThuc AS thoiGianKetThuc,
        ls.ThongBao AS thongBao,
        ls.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung
    FROM dbo.LichSuSaoLuu AS ls
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = ls.MaNguoiDung
    WHERE (@TrangThai IS NULL OR ls.TrangThai = @TrangThai)
      AND (@LoaiSaoLuu IS NULL OR ls.LoaiSaoLuu = @LoaiSaoLuu)
    ORDER BY ls.ThoiGianBatDau DESC, ls.MaSaoLuu DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_PhucHoiDuLieu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_PhucHoiDuLieu
    @MaSaoLuu    INT           = NULL,
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL,
    @ChiTaoLenh   BOOLEAN           = 1
AS
BEGIN
    

    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');

    IF @DuongDanFile IS NULL AND @MaSaoLuu IS NOT NULL
    BEGIN
        SELECT @DuongDanFile = DuongDanFile
        FROM dbo.LichSuSaoLuu
        WHERE MaSaoLuu = @MaSaoLuu
          AND TrangThai = 'Thành công';
    END;

    IF @DuongDanFile IS NULL
        RAISE EXCEPTION %;

    DECLARE @TenDatabase SYSNAME = DB_NAME();
    DECLARE @LenhSingleUser TEXT;
    DECLARE @LenhRestore TEXT;
    DECLARE @LenhMultiUser TEXT;
    DECLARE @LenhDayDu TEXT;

    SET @LenhSingleUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET SINGLE_USER WITH ROLLBACK IMMEDIATE;';
    SET @LenhRestore = 'USE [master]; RESTORE DATABASE ' + QUOTENAME(@TenDatabase) +
        ' FROM DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') + ''' WITH REPLACE;';
    SET @LenhMultiUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET MULTI_USER;';
    SET @LenhDayDu = @LenhSingleUser + CHAR(13) + CHAR(10) + @LenhRestore + CHAR(13) + CHAR(10) + @LenhMultiUser;

    IF @ChiTaoLenh = 1
    BEGIN
        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo lệnh phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;

        SELECT
            @TenDatabase AS tenDatabase,
            @DuongDanFile AS duongDanFile,
            @LenhDayDu AS lenhPhucHoi,
            CAST(1 AS BOOLEAN) AS chiTaoLenh;
        RETURN;
    END;

    BEGIN TRY
        EXEC(@LenhSingleUser);
        EXEC(@LenhRestore);
        EXEC(@LenhMultiUser);

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        BEGIN TRY
            EXEC(@LenhMultiUser);
        END TRY
        BEGIN CATCH
        END CATCH;

        THROW;
    END CATCH;

    SELECT
        @TenDatabase AS tenDatabase,
        @DuongDanFile AS duongDanFile,
        CAST(1 AS BOOLEAN) AS daPhucHoi;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_XemNhatKyHeThong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_XemNhatKyHeThong
    @TuNgay     TIMESTAMP  = NULL,
    @DenNgay    TIMESTAMP  = NULL,
    @AdminId    VARCHAR(6)    = NULL,
    @DoiTuong   VARCHAR(100) = NULL,
    @HanhDong   VARCHAR(100) = NULL,
    @TuKhoa     VARCHAR(100) = NULL,
    @SoDong     INT           = 200
AS
BEGIN
    

    SET @AdminId = NULLIF(TRIM(@AdminId)), '');
    SET @DoiTuong = NULLIF(TRIM(@DoiTuong)), '');
    SET @HanhDong = NULLIF(TRIM(@HanhDong)), '');
    SET @TuKhoa = NULLIF(TRIM(@TuKhoa)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 200;

    SELECT TOP (@SoDong)
        nk.MaNhatKy AS maNhatKy,
        nk.ThoiGian AS thoiGian,
        nk.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung,
        nk.VaiTro AS vaiTro,
        nk.ChucNang AS chucNang,
        nk.HanhDong AS hanhDong,
        nk.DoiTuong AS doiTuong,
        nk.MaDoiTuong AS maDoiTuong,
        nk.NoiDung AS noiDung,
        nk.DuLieuTruoc AS duLieuTruoc,
        nk.DuLieuSau AS duLieuSau
    FROM dbo.NhatKyHeThong AS nk
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nk.MaNguoiDung
    WHERE (@TuNgay IS NULL OR nk.ThoiGian >= @TuNgay)
      AND (@DenNgay IS NULL OR nk.ThoiGian < DATEADD(DAY, 1, @DenNgay))
      AND (@AdminId IS NULL OR nk.MaNguoiDung = @AdminId)
      AND (@DoiTuong IS NULL OR nk.DoiTuong = @DoiTuong)
      AND (@HanhDong IS NULL OR nk.HanhDong LIKE '%' + @HanhDong + '%')
      AND (
          @TuKhoa IS NULL
          OR nk.NoiDung LIKE '%' + @TuKhoa + '%'
          OR nk.MaDoiTuong LIKE '%' + @TuKhoa + '%'
          OR nk.HanhDong LIKE '%' + @TuKhoa + '%'
      )
    ORDER BY nk.ThoiGian DESC, nk.MaNhatKy DESC;
END; THEN (SUBSTRING(MaLoaiPhong, 3, 4)::INT ELSE NULL END)), 0) + 1
                FROM dbo.LoaiPhong 
                WHERE MaLoaiPhong LIKE 'LP[0-9][0-9][0-9][0-9]';

                IF @SoLoaiPhong > 9999
                    RAISE EXCEPTION %;

                SET @MaLoaiPhong = CONCAT('LP', RIGHT(CONCAT('0000', @SoLoaiPhong), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
                RAISE EXCEPTION %;

            INSERT INTO dbo.LoaiPhong (
                MaLoaiPhong, TenLoaiPhong, SucChuaToiDa, MoTa, GiaThueTheoGiuong, GiaThueNguyenPhong
            )
            VALUES (
                @MaLoaiPhong, @TenLoaiPhong, @SucChuaToiDa, @MoTa, @GiaThueTheoGiuong, @GiaThueNguyenPhong
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo loại phòng',
                @DoiTuong = 'LoaiPhong',
                @MaDoiTuong = @MaLoaiPhong,
                @NoiDung = @TenLoaiPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaLoaiPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocLoaiPhong TEXT;
        SELECT @DuLieuTruocLoaiPhong = (
            SELECT * FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        IF @SucChuaToiDa IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.Phong AS p
            WHERE p.MaLoaiPhong = @MaLoaiPhong
              AND (
                  SELECT COUNT(1)
                  FROM dbo.Giuong AS g
                  WHERE g.MaPhong = p.MaPhong
              ) > @SucChuaToiDa
        )
            RAISE EXCEPTION %;

        UPDATE dbo.LoaiPhong
        SET TenLoaiPhong = COALESCE(@TenLoaiPhong, TenLoaiPhong),
            SucChuaToiDa = COALESCE(@SucChuaToiDa, SucChuaToiDa),
            MoTa = COALESCE(@MoTa, MoTa),
            GiaThueTheoGiuong = COALESCE(@GiaThueTheoGiuong, GiaThueTheoGiuong),
            GiaThueNguyenPhong = COALESCE(@GiaThueNguyenPhong, GiaThueNguyenPhong)
        WHERE MaLoaiPhong = @MaLoaiPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật loại phòng',
            @DoiTuong = 'LoaiPhong',
            @MaDoiTuong = @MaLoaiPhong,
            @DuLieuTruoc = @DuLieuTruocLoaiPhong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaLoaiPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;

        DELETE FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa loại phòng',
            @DoiTuong = 'LoaiPhong',
            @MaDoiTuong = @MaLoaiPhong;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaLoaiPhong AS maLoaiPhong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyLoaiPhong @ThaoTac = 'DANH_SACH', @MaLoaiPhong = @MaLoaiPhong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_TaoPhongGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_TaoPhongGiuong
    @MaPhong         VARCHAR(4)    = NULL,
    @TenPhong        VARCHAR(100),
    @GioiTinhChoPhep VARCHAR(20),
    @MaChiNhanh      VARCHAR(6),
    @MaLoaiPhong     VARCHAR(6),
    @TinhTrang       VARCHAR(20)  = 'Trống',
    @UrlImg          VARCHAR(500)  = NULL,
    @SoGiuong        INT           = NULL,
    @AdminId         VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @TenPhong = NULLIF(TRIM(@TenPhong)), '');
    SET @GioiTinhChoPhep = NULLIF(TRIM(@GioiTinhChoPhep)), '');
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @MaLoaiPhong = NULLIF(TRIM(@MaLoaiPhong)), '');
    SET @TinhTrang = COALESCE(NULLIF(TRIM(@TinhTrang)), ''), 'Trống');
    SET @UrlImg = NULLIF(TRIM(@UrlImg)), '');

    IF @TenPhong IS NULL OR @GioiTinhChoPhep IS NULL OR @MaChiNhanh IS NULL OR @MaLoaiPhong IS NULL
        THROW 51061, 'Vui lòng nhập tên phòng, giới tính, chi nhánh và loại phòng.', 1;

    IF @GioiTinhChoPhep NOT IN ('Nam', 'Nữ', 'Không phân biệt')
        RAISE EXCEPTION %;

    IF @TinhTrang NOT IN ('Trống', 'Đã đặt cọc', 'Còn chỗ', 'Đầy', 'Giữ chỗ')
        RAISE EXCEPTION %;

    IF NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
        RAISE EXCEPTION %;

    IF NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
        RAISE EXCEPTION %;

    DECLARE @SucChuaLoaiPhong INT;
    SELECT @SucChuaLoaiPhong = SucChuaToiDa
    FROM dbo.LoaiPhong
    WHERE MaLoaiPhong = @MaLoaiPhong;

    IF @SoGiuong IS NULL
        SET @SoGiuong = @SucChuaLoaiPhong;

    IF @SoGiuong < 1 OR @SoGiuong > 99
        RAISE EXCEPTION %;

    IF @SoGiuong > @SucChuaLoaiPhong
        RAISE EXCEPTION %;

    DECLARE @SoPhong INT;
    DECLARE @SoChiNhanh INT = CASE WHEN (SUBSTRING(@MaChiNhanh, 3, 4) ~ '^[0-9]+);
    DECLARE @Index INT = 1;
    DECLARE @MaGiuong VARCHAR(3);

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @MaPhong IS NULL
        BEGIN
            IF @SoChiNhanh IS NULL OR @SoChiNhanh NOT BETWEEN 1 AND 9
                RAISE EXCEPTION %;

            SELECT @SoPhong = COALESCE(MAX(TRY_CONVERT(INT, RIGHT(MaPhong, 2))), 0) + 1
            FROM dbo.Phong 
            WHERE MaChiNhanh = @MaChiNhanh
              AND MaPhong LIKE CONCAT('P', @SoChiNhanh, '[0-9][0-9]');

            IF @SoPhong > 99
                RAISE EXCEPTION %;

            SET @MaPhong = CONCAT('P', @SoChiNhanh, RIGHT(CONCAT('00', @SoPhong), 2));
        END;

        IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        INSERT INTO dbo.Phong (MaPhong, TenPhong, GioiTinhChoPhep, TinhTrang, MaChiNhanh, MaLoaiPhong)
        VALUES (@MaPhong, @TenPhong, @GioiTinhChoPhep, @TinhTrang, @MaChiNhanh, @MaLoaiPhong);

        IF @UrlImg IS NOT NULL
        BEGIN
            INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
            VALUES (@MaPhong, 1, @UrlImg);
        END;

        WHILE @Index <= @SoGiuong
        BEGIN
            SET @MaGiuong = CONCAT('G', RIGHT(CONCAT('00', @Index), 2));

            INSERT INTO dbo.Giuong (MaPhong, MaGiuong, SoGiuong, TinhTrang)
            VALUES (@MaPhong, @MaGiuong, @Index, 'Trống');

            SET @Index += 1;
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo phòng giường',
            @DoiTuong = 'Phong',
            @MaDoiTuong = @MaPhong,
            @NoiDung = @TenPhong;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        p.MaPhong AS maPhong,
        p.TenPhong AS tenPhong,
        p.GioiTinhChoPhep AS gioiTinhChoPhep,
        p.TinhTrang AS tinhTrangPhong,
        (SELECT TOP 1 hap.UrlImg FROM dbo.HinhAnhPhong AS hap WHERE hap.MaPhong = p.MaPhong ORDER BY hap.STTAnh) AS urlImgPhong,
        p.MaChiNhanh AS maChiNhanh,
        cn.TenChiNhanh AS tenChiNhanh,
        p.MaLoaiPhong AS maLoaiPhong,
        lp.TenLoaiPhong AS tenLoaiPhong,
        g.MaGiuong AS maGiuong,
        g.SoGiuong AS soGiuong,
        g.TinhTrang AS tinhTrangGiuong
    FROM dbo.Phong AS p
    INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    LEFT JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
    WHERE p.MaPhong = @MaPhong
    ORDER BY g.SoGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CapNhatTrangThaiPhongGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CapNhatTrangThaiPhongGiuong
    @LoaiDoiTuong VARCHAR(20),
    @MaPhong      VARCHAR(4),
    @MaGiuong     VARCHAR(3)   = NULL,
    @TrangThai    VARCHAR(20),
    @AdminId      VARCHAR(6)   = NULL
AS
BEGIN
    
    

    SET @LoaiDoiTuong = UPPER(NULLIF(TRIM(@LoaiDoiTuong)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');

    IF @LoaiDoiTuong NOT IN ('PHONG', 'GIUONG')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @LoaiDoiTuong = 'PHONG' AND @TrangThai NOT IN ('Trống', 'Đã đặt cọc', 'Còn chỗ', 'Đầy', 'Giữ chỗ', 'Bảo trì')
        RAISE EXCEPTION %;

    IF @LoaiDoiTuong = 'GIUONG' AND @TrangThai NOT IN ('Trống', 'Đã đặt cọc', 'Đang thuê')
        RAISE EXCEPTION %;

    IF @LoaiDoiTuong = 'GIUONG'
       AND (@MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
       ))
        RAISE EXCEPTION %;

    DECLARE @DuLieuTruoc TEXT;

    IF @LoaiDoiTuong = 'PHONG'
        SELECT @DuLieuTruoc = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );
    ELSE
        SELECT @DuLieuTruoc = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @LoaiDoiTuong = 'PHONG'
        BEGIN
            UPDATE dbo.Phong
            SET TinhTrang = @TrangThai
            WHERE MaPhong = @MaPhong;
        END
        ELSE
        BEGIN
            UPDATE dbo.Giuong
            SET TinhTrang = @TrangThai
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong;

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (
                    SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống'
                ) THEN 'Trống'
                WHEN NOT EXISTS (
                    SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống'
                ) THEN 'Đầy'
                WHEN EXISTS (
                    SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Đã đặt cọc'
                ) THEN 'Còn chỗ'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật trạng thái phòng/giường',
            @DoiTuong = @LoaiDoiTuong,
            @MaDoiTuong = @MaPhong,
            @NoiDung = @TrangThai,
            @DuLieuTruoc = @DuLieuTruoc;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        p.MaPhong AS maPhong,
        p.TenPhong AS tenPhong,
        p.TinhTrang AS tinhTrangPhong,
        g.MaGiuong AS maGiuong,
        g.SoGiuong AS soGiuong,
        g.TinhTrang AS tinhTrangGiuong
    FROM dbo.Phong AS p
    LEFT JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
    WHERE p.MaPhong = @MaPhong
      AND (@MaGiuong IS NULL OR g.MaGiuong = @MaGiuong)
    ORDER BY g.SoGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyPhong
    @ThaoTac         VARCHAR(20)  = 'DANH_SACH',
    @MaPhong         VARCHAR(4)    = NULL,
    @TenPhong        VARCHAR(100) = NULL,
    @GioiTinhChoPhep VARCHAR(20)  = NULL,
    @TinhTrang       VARCHAR(20)  = NULL,
    @UrlImg          VARCHAR(500)  = NULL,
    @MaChiNhanh      VARCHAR(6)    = NULL,
    @MaLoaiPhong     VARCHAR(6)    = NULL,
    @AdminId         VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @TenPhong = NULLIF(TRIM(@TenPhong)), '');
    SET @GioiTinhChoPhep = NULLIF(TRIM(@GioiTinhChoPhep)), '');
    SET @TinhTrang = NULLIF(TRIM(@TinhTrang)), '');
    SET @UrlImg = NULLIF(TRIM(@UrlImg)), '');
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @MaLoaiPhong = NULLIF(TRIM(@MaLoaiPhong)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            p.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            p.GioiTinhChoPhep AS gioiTinhChoPhep,
            p.TinhTrang AS tinhTrang,
            (SELECT TOP 1 hap.UrlImg FROM dbo.HinhAnhPhong AS hap WHERE hap.MaPhong = p.MaPhong ORDER BY hap.STTAnh) AS urlImg,
            p.MaChiNhanh AS maChiNhanh,
            cn.TenChiNhanh AS tenChiNhanh,
            p.MaLoaiPhong AS maLoaiPhong,
            lp.TenLoaiPhong AS tenLoaiPhong,
            COUNT(g.MaGiuong) AS soGiuong,
            SUM(CASE WHEN g.TinhTrang = 'Trống' THEN 1 ELSE 0 END) AS soGiuongTrong
        FROM dbo.Phong AS p
        INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
        INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
        LEFT JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
        WHERE (@MaPhong IS NULL OR p.MaPhong = @MaPhong)
          AND (@MaChiNhanh IS NULL OR p.MaChiNhanh = @MaChiNhanh)
          AND (@MaLoaiPhong IS NULL OR p.MaLoaiPhong = @MaLoaiPhong)
          AND (@TinhTrang IS NULL OR p.TinhTrang = @TinhTrang)
        GROUP BY p.MaPhong, p.TenPhong, p.GioiTinhChoPhep, p.TinhTrang,
                 p.MaChiNhanh, cn.TenChiNhanh, p.MaLoaiPhong, lp.TenLoaiPhong
        ORDER BY p.MaPhong;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO'
           AND (@TenPhong IS NULL OR @GioiTinhChoPhep IS NULL OR @MaChiNhanh IS NULL OR @MaLoaiPhong IS NULL)
            THROW 51102, 'Vui lòng nhập đầy đủ tên phòng, giới tính, chi nhánh và loại phòng.', 1;

        IF @GioiTinhChoPhep IS NOT NULL AND @GioiTinhChoPhep NOT IN ('Nam', 'Nữ', 'Không phân biệt')
            RAISE EXCEPTION %;

        IF @TinhTrang IS NOT NULL AND @TinhTrang NOT IN ('Trống', 'Đã đặt cọc', 'Còn chỗ', 'Đầy', 'Giữ chỗ', 'Bảo trì')
            RAISE EXCEPTION %;

        IF @MaChiNhanh IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
            RAISE EXCEPTION %;

        IF @MaLoaiPhong IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoPhongMoi INT;
        DECLARE @SoChiNhanhPhong INT = TRY_CONVERT(INT, SUBSTRING(@MaChiNhanh, 3, 4));

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaPhong IS NULL
            BEGIN
                IF @SoChiNhanhPhong IS NULL OR @SoChiNhanhPhong NOT BETWEEN 1 AND 9
                    RAISE EXCEPTION %;

                SELECT @SoPhongMoi = COALESCE(MAX(TRY_CONVERT(INT, RIGHT(MaPhong, 2))), 0) + 1
                FROM dbo.Phong 
                WHERE MaChiNhanh = @MaChiNhanh
                  AND MaPhong LIKE CONCAT('P', @SoChiNhanhPhong, '[0-9][0-9]');

                IF @SoPhongMoi > 99
                    RAISE EXCEPTION %;

                SET @MaPhong = CONCAT('P', @SoChiNhanhPhong, RIGHT(CONCAT('00', @SoPhongMoi), 2));
            END;

            IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
                RAISE EXCEPTION %;

            INSERT INTO dbo.Phong (MaPhong, TenPhong, GioiTinhChoPhep, TinhTrang, MaChiNhanh, MaLoaiPhong)
            VALUES (@MaPhong, @TenPhong, @GioiTinhChoPhep, COALESCE(@TinhTrang, 'Trống'), @MaChiNhanh, @MaLoaiPhong);

            IF @UrlImg IS NOT NULL
            BEGIN
                INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
                VALUES (@MaPhong, 1, @UrlImg);
            END;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo phòng',
                @DoiTuong = 'Phong',
                @MaDoiTuong = @MaPhong,
                @NoiDung = @TenPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocPhong TEXT;
        SELECT @DuLieuTruocPhong = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.Phong
        SET TenPhong = COALESCE(@TenPhong, TenPhong),
            GioiTinhChoPhep = COALESCE(@GioiTinhChoPhep, GioiTinhChoPhep),
            TinhTrang = COALESCE(@TinhTrang, TinhTrang),
            MaChiNhanh = COALESCE(@MaChiNhanh, MaChiNhanh),
            MaLoaiPhong = COALESCE(@MaLoaiPhong, MaLoaiPhong)
        WHERE MaPhong = @MaPhong;

        IF @UrlImg IS NOT NULL
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.HinhAnhPhong WHERE MaPhong = @MaPhong AND STTAnh = 1)
                UPDATE dbo.HinhAnhPhong
                SET UrlImg = @UrlImg
                WHERE MaPhong = @MaPhong AND STTAnh = 1;
            ELSE
                INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
                VALUES (@MaPhong, 1, @UrlImg);
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật phòng',
            @DoiTuong = 'Phong',
            @MaDoiTuong = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocPhong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống')
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc AS ctdc
            INNER JOIN dbo.PhieuDatCoc AS pdc ON pdc.MaPhieuDatCoc = ctdc.MaPhieuDatCoc
            WHERE ctdc.MaPhong = @MaPhong
              AND pdc.TrangThaiCoc IN ('Hiệu lực', 'Đã lập HĐ')
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietDatCoc WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong)
           OR EXISTS (SELECT 1 FROM dbo.ChiTietXemPhong WHERE MaPhong = @MaPhong)
           OR EXISTS (SELECT 1 FROM dbo.PhieuGhiChiSo WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocPhongXoa TEXT;
        SELECT @DuLieuTruocPhongXoa = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        BEGIN TRY
            BEGIN TRANSACTION;

            DELETE FROM dbo.Giuong WHERE MaPhong = @MaPhong;
            DELETE FROM dbo.Phong WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa phòng',
                @DoiTuong = 'Phong',
                @MaDoiTuong = @MaPhong,
                @DuLieuTruoc = @DuLieuTruocPhongXoa;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyPhong @ThaoTac = 'DANH_SACH', @MaPhong = @MaPhong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyGiuong
    @ThaoTac   VARCHAR(20) = 'DANH_SACH',
    @MaPhong   VARCHAR(4)   = NULL,
    @MaGiuong  VARCHAR(3)   = NULL,
    @SoGiuong  INT          = NULL,
    @TinhTrang VARCHAR(20) = NULL,
    @UrlImg    VARCHAR(500) = NULL,
    @AdminId   VARCHAR(6)   = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    SET @TinhTrang = NULLIF(TRIM(@TinhTrang)), '');
    SET @UrlImg = NULLIF(TRIM(@UrlImg)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            g.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            g.MaGiuong AS maGiuong,
            g.SoGiuong AS soGiuong,
            g.TinhTrang AS tinhTrang,
            lp.SucChuaToiDa AS sucChuaToiDa,
            (
                SELECT COUNT(1)
                FROM dbo.TaiSan AS tsChung
                WHERE tsChung.MaPhong = g.MaPhong
                  AND tsChung.LoaiTaiSan = 'Chung'
            ) AS soTaiSanChung,
            CAST(0 AS INT) AS soTaiSanRieng
        FROM dbo.Giuong AS g
        INNER JOIN dbo.Phong AS p ON p.MaPhong = g.MaPhong
        INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
        WHERE (@MaPhong IS NULL OR g.MaPhong = @MaPhong)
          AND (@MaGiuong IS NULL OR g.MaGiuong = @MaGiuong)
          AND (@TinhTrang IS NULL OR g.TinhTrang = @TinhTrang)
        ORDER BY g.MaPhong, g.SoGiuong, g.MaGiuong;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @SoGiuong IS NULL
            RAISE EXCEPTION %;

        IF @SoGiuong IS NOT NULL AND @SoGiuong < 1
            RAISE EXCEPTION %;

        IF @TinhTrang IS NOT NULL AND @TinhTrang NOT IN ('Trống', 'Đã đặt cọc', 'Đang thuê')
            RAISE EXCEPTION %;
    END;

    DECLARE @SucChuaToiDa INT;
    SELECT @SucChuaToiDa = lp.SucChuaToiDa
    FROM dbo.Phong AS p
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    WHERE p.MaPhong = @MaPhong;

    IF @SoGiuong IS NOT NULL AND @SoGiuong > @SucChuaToiDa
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF (SELECT COUNT(*) FROM dbo.Giuong WHERE MaPhong = @MaPhong) >= @SucChuaToiDa
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND SoGiuong = @SoGiuong)
            RAISE EXCEPTION %;

        IF @MaGiuong IS NULL
        BEGIN
            DECLARE @SoMaGiuong INT;
            SELECT @SoMaGiuong = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaGiuong, 2, 2))), 0) + 1
            FROM dbo.Giuong 
            WHERE MaPhong = @MaPhong
              AND MaGiuong LIKE 'G[0-9][0-9]';

            IF @SoMaGiuong > 99
                RAISE EXCEPTION %;

            SET @MaGiuong = CONCAT('G', RIGHT(CONCAT('00', @SoMaGiuong), 2));
        END;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong)
            RAISE EXCEPTION %;

        BEGIN TRY
            BEGIN TRANSACTION;

            INSERT INTO dbo.Giuong (MaPhong, MaGiuong, SoGiuong, TinhTrang)
            VALUES (@MaPhong, @MaGiuong, @SoGiuong, COALESCE(@TinhTrang, 'Trống'));

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo giường',
                @DoiTuong = 'Giuong',
                @MaDoiTuong = @MaGiuong,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF @SoGiuong IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.Giuong
            WHERE MaPhong = @MaPhong
              AND SoGiuong = @SoGiuong
              AND MaGiuong <> @MaGiuong
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocGiuong TEXT;
        SELECT @DuLieuTruocGiuong = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.Giuong
        SET SoGiuong = COALESCE(@SoGiuong, SoGiuong),
            TinhTrang = COALESCE(@TinhTrang, TinhTrang)
        WHERE MaPhong = @MaPhong
          AND MaGiuong = @MaGiuong;

        UPDATE dbo.Phong
        SET TinhTrang = CASE
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong) THEN 'Trống'
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
            ELSE 'Còn chỗ'
        END
        WHERE MaPhong = @MaPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật giường',
            @DoiTuong = 'Giuong',
            @MaDoiTuong = @MaGiuong,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocGiuong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1 FROM dbo.Giuong
            WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong AND TinhTrang <> 'Trống'
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc AS ctdc
            INNER JOIN dbo.PhieuDatCoc AS pdc ON pdc.MaPhieuDatCoc = ctdc.MaPhieuDatCoc
            WHERE ctdc.MaPhong = @MaPhong
              AND ctdc.MaGiuong = @MaGiuong
              AND pdc.TrangThaiCoc IN ('Hiệu lực', 'Đã lập HĐ')
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietXemPhong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocGiuongXoa TEXT;
        SELECT @DuLieuTruocGiuongXoa = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        BEGIN TRY
            BEGIN TRANSACTION;

            DELETE FROM dbo.Giuong
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong;

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong) THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa giường',
                @DoiTuong = 'Giuong',
                @MaDoiTuong = @MaGiuong,
                @NoiDung = @MaPhong,
                @DuLieuTruoc = @DuLieuTruocGiuongXoa;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaGiuong AS maGiuong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyGiuong @ThaoTac = 'DANH_SACH', @MaPhong = @MaPhong, @MaGiuong = @MaGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyTaiSanPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyTaiSanPhong
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaPhong   VARCHAR(4)    = NULL,
    @MaTaiSan  VARCHAR(6)    = NULL,
    @TenTaiSan VARCHAR(100) = NULL,
    @SoLuong   INT           = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @LoaiTaiSan VARCHAR(20) = NULL,
    @MaGiuong   VARCHAR(3)   = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaTaiSan = NULLIF(TRIM(@MaTaiSan)), '');
    SET @TenTaiSan = NULLIF(TRIM(@TenTaiSan)), '');
    SET @LoaiTaiSan = NULLIF(TRIM(@LoaiTaiSan)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            ts.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            ts.MaTaiSan AS maTaiSan,
            ts.TenTaiSan AS tenTaiSan,
            ts.SoLuong AS soLuong,
            ts.DonGia AS donGia,
            ts.LoaiTaiSan AS loaiTaiSan,
            ts.MaGiuong AS maGiuong,
            g.SoGiuong AS soGiuong
        FROM dbo.TaiSan AS ts
        INNER JOIN dbo.Phong AS p ON p.MaPhong = ts.MaPhong
        LEFT JOIN dbo.Giuong AS g ON g.MaPhong = ts.MaPhong AND g.MaGiuong = ts.MaGiuong
        WHERE (@MaPhong IS NULL OR ts.MaPhong = @MaPhong)
          AND (@MaTaiSan IS NULL OR ts.MaTaiSan = @MaTaiSan)
          AND (@MaGiuong IS NULL OR ts.MaGiuong = @MaGiuong)
          AND (@LoaiTaiSan IS NULL OR ts.LoaiTaiSan = @LoaiTaiSan)
        ORDER BY ts.MaPhong, ts.LoaiTaiSan, ts.MaGiuong, ts.MaTaiSan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TenTaiSan IS NULL
            RAISE EXCEPTION %;

        IF @SoLuong IS NOT NULL AND @SoLuong <= 0
            RAISE EXCEPTION %;

        IF @DonGia IS NOT NULL AND @DonGia < 0
            RAISE EXCEPTION %;

        DECLARE @LoaiTaiSanSau VARCHAR(20);
        DECLARE @MaGiuongSau VARCHAR(3);

        IF @ThaoTac = 'TAO'
        BEGIN
            SET @LoaiTaiSanSau = COALESCE(@LoaiTaiSan, 'Chung');
            SET @MaGiuongSau = @MaGiuong;
        END
        ELSE
        BEGIN
            IF @MaTaiSan IS NULL OR NOT EXISTS (
                SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
            )
                RAISE EXCEPTION %;

            SELECT
                @LoaiTaiSanSau = COALESCE(@LoaiTaiSan, LoaiTaiSan),
                @MaGiuongSau = CASE
                    WHEN @LoaiTaiSan = 'Chung' THEN NULL
                    ELSE COALESCE(@MaGiuong, MaGiuong)
                END
            FROM dbo.TaiSan
            WHERE MaPhong = @MaPhong
              AND MaTaiSan = @MaTaiSan;
        END;

        IF @LoaiTaiSanSau NOT IN ('Chung', 'Riêng')
            RAISE EXCEPTION %;

        IF @LoaiTaiSanSau = 'Chung'
            SET @MaGiuongSau = NULL;

        IF @LoaiTaiSanSau = 'Riêng' AND @MaGiuongSau IS NULL
            RAISE EXCEPTION %;

        IF @MaGiuongSau IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuongSau
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoTaiSan INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaTaiSan IS NULL
            BEGIN
                SELECT @SoTaiSan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaTaiSan, 3, 4))), 0) + 1
                FROM dbo.TaiSan 
                WHERE MaPhong = @MaPhong
                  AND MaTaiSan LIKE 'TS[0-9][0-9][0-9][0-9]';

                IF @SoTaiSan > 9999
                    RAISE EXCEPTION %;

                SET @MaTaiSan = CONCAT('TS', RIGHT(CONCAT('0000', @SoTaiSan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.TaiSan (
                MaPhong, MaTaiSan, TenTaiSan, SoLuong, DonGia, LoaiTaiSan, MaGiuong
            )
            VALUES (
                @MaPhong, @MaTaiSan, @TenTaiSan, COALESCE(@SoLuong, 1),
                @DonGia, @LoaiTaiSanSau, @MaGiuongSau
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo tài sản phòng',
                @DoiTuong = 'TaiSan',
                @MaDoiTuong = @MaTaiSan,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocTaiSan TEXT;
        SELECT @DuLieuTruocTaiSan = (
            SELECT * FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.TaiSan
        SET TenTaiSan = COALESCE(@TenTaiSan, TenTaiSan),
            SoLuong = COALESCE(@SoLuong, SoLuong),
            DonGia = COALESCE(@DonGia, DonGia),
            LoaiTaiSan = @LoaiTaiSanSau,
            MaGiuong = @MaGiuongSau
        WHERE MaPhong = @MaPhong
          AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocTaiSan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietBanGiao WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.ChiTietHuHong WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.YeuCauSuaChua WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaTaiSan AS maTaiSan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyTaiSanPhong
        @ThaoTac = 'DANH_SACH',
        @MaPhong = @MaPhong,
        @MaTaiSan = @MaTaiSan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc
    @ThaoTac           VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinhHoanCoc VARCHAR(6)    = NULL,
    @TenQuyDinh        VARCHAR(255) = NULL,
    @TyLeHoanCoc       DECIMAL(5,2)  = NULL,
    @AdminId           VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinhHoanCoc = NULLIF(TRIM(@MaQuyDinhHoanCoc)), '');
    SET @TenQuyDinh = NULLIF(TRIM(@TenQuyDinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qh.MaQuyDinhHoanCoc AS maQuyDinhHoanCoc,
            qh.TenQuyDinh AS tenQuyDinh,
            qh.TyLeHoanCoc AS tyLeHoanCoc,
            COUNT(ds.MaQuyDinhHoanCoc) AS soLanApDung
        FROM dbo.QuyDinhHoanCoc AS qh
        LEFT JOIN dbo.DoiSoat AS ds ON ds.MaQuyDinhHoanCoc = qh.MaQuyDinhHoanCoc
        WHERE (@MaQuyDinhHoanCoc IS NULL OR qh.MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
        GROUP BY qh.MaQuyDinhHoanCoc, qh.TenQuyDinh, qh.TyLeHoanCoc
        ORDER BY qh.MaQuyDinhHoanCoc;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenQuyDinh IS NULL OR @TyLeHoanCoc IS NULL)
            RAISE EXCEPTION %;

        IF @TyLeHoanCoc IS NOT NULL AND (@TyLeHoanCoc < 0 OR @TyLeHoanCoc > 100)
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinh INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinhHoanCoc IS NULL
            BEGIN
                SELECT @SoQuyDinh = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinhHoanCoc, 3, 4))), 0) + 1
                FROM dbo.QuyDinhHoanCoc 
                WHERE MaQuyDinhHoanCoc LIKE 'QH[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinh > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinhHoanCoc = CONCAT('QH', RIGHT(CONCAT('0000', @SoQuyDinh), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuyDinhHoanCoc (MaQuyDinhHoanCoc, TenQuyDinh, TyLeHoanCoc)
            VALUES (@MaQuyDinhHoanCoc, @TenQuyDinh, @TyLeHoanCoc);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo quy định hoàn cọc',
                @DoiTuong = 'QuyDinhHoanCoc',
                @MaDoiTuong = @MaQuyDinhHoanCoc,
                @NoiDung = @TenQuyDinh;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocHoanCoc TEXT;
        SELECT @DuLieuTruocHoanCoc = (
            SELECT * FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuyDinhHoanCoc
        SET TenQuyDinh = COALESCE(@TenQuyDinh, TenQuyDinh),
            TyLeHoanCoc = COALESCE(@TyLeHoanCoc, TyLeHoanCoc)
        WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc,
            @DuLieuTruoc = @DuLieuTruocHoanCoc;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DoiSoat WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinhHoanCoc AS maQuyDinhHoanCoc;
        RETURN;
    END;

    EXEC dbo.SP_Admin_CauHinhQuyDinhHoanCoc @ThaoTac = 'DANH_SACH', @MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDichVu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDichVu
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaDichVu  VARCHAR(6)    = NULL,
    @TenDichVu VARCHAR(100) = NULL,
    @DonViTinh VARCHAR(20)   = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDichVu = NULLIF(TRIM(@MaDichVu)), '');
    SET @TenDichVu = NULLIF(TRIM(@TenDichVu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dv.MaDichVu AS maDichVu,
            dv.TenDichVu AS tenDichVu,
            dv.DonViTinh AS donViTinh,
            dv.DonGia AS donGia,
            COUNT(DISTINCT dvhd.MaChiTietDVHD) AS soHopDongSuDung,
            COUNT(cthd.MaChiTietHD) AS soDongHoaDon
        FROM dbo.DichVu AS dv
        LEFT JOIN dbo.DichVuHopDong AS dvhd ON dvhd.MaDichVu = dv.MaDichVu
        LEFT JOIN dbo.ChiTietHoaDon AS cthd ON cthd.MaChiTietDVHD = dvhd.MaChiTietDVHD
        WHERE (@MaDichVu IS NULL OR dv.MaDichVu = @MaDichVu)
          AND (@TenDichVu IS NULL OR dv.TenDichVu LIKE '%' + @TenDichVu + '%')
        GROUP BY dv.MaDichVu, dv.TenDichVu, dv.DonViTinh, dv.DonGia
        ORDER BY dv.MaDichVu;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDichVu IS NULL OR @DonViTinh IS NULL OR @DonGia IS NULL)
            THROW 51202, 'Vui lòng nhập tên dịch vụ, đơn vị tính và đơn giá.', 1;

        IF @DonGia IS NOT NULL AND @DonGia <= 0
            RAISE EXCEPTION %;

        IF @TenDichVu IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DichVu
            WHERE TenDichVu = @TenDichVu
              AND (@MaDichVu IS NULL OR MaDichVu <> @MaDichVu)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDichVu INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDichVu IS NULL
            BEGIN
                SELECT @SoDichVu = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDichVu, 3, 4))), 0) + 1
                FROM dbo.DichVu 
                WHERE MaDichVu LIKE 'DV[0-9][0-9][0-9][0-9]';

                IF @SoDichVu > 9999
                    RAISE EXCEPTION %;

                SET @MaDichVu = CONCAT('DV', RIGHT(CONCAT('0000', @SoDichVu), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DichVu (MaDichVu, TenDichVu, DonViTinh, DonGia)
            VALUES (@MaDichVu, @TenDichVu, @DonViTinh, @DonGia);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo dịch vụ',
                @DoiTuong = 'DichVu',
                @MaDoiTuong = @MaDichVu,
                @NoiDung = @TenDichVu;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocDichVu TEXT;
        SELECT @DuLieuTruocDichVu = (
            SELECT * FROM dbo.DichVu WHERE MaDichVu = @MaDichVu FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DichVu
        SET TenDichVu = COALESCE(@TenDichVu, TenDichVu),
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            DonGia = COALESCE(@DonGia, DonGia)
        WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu,
            @DuLieuTruoc = @DuLieuTruocDichVu;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DichVuHopDong WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DichVu WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDichVu AS maDichVu;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDichVu @ThaoTac = 'DANH_SACH', @MaDichVu = @MaDichVu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyNoiQuy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyNoiQuy
    @ThaoTac      VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinh    VARCHAR(6)    = NULL,
    @TieuDeNoiQuy VARCHAR(255) = NULL,
    @NoiDung      TEXT = NULL,
    @TrangThai    VARCHAR(20)  = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinh = NULLIF(TRIM(@MaQuyDinh)), '');
    SET @TieuDeNoiQuy = NULLIF(TRIM(@TieuDeNoiQuy)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qd.MaQuyDinh AS maQuyDinh,
            qd.TieuDeNoiQuy AS tieuDeNoiQuy,
            qd.NoiDung AS noiDung,
            qd.TrangThai AS trangThai
        FROM dbo.QuiDinh AS qd
        WHERE (@MaQuyDinh IS NULL OR qd.MaQuyDinh = @MaQuyDinh)
          AND (@TrangThai IS NULL OR qd.TrangThai = @TrangThai)
          AND (@TieuDeNoiQuy IS NULL OR qd.TieuDeNoiQuy LIKE '%' + @TieuDeNoiQuy + '%')
        ORDER BY qd.MaQuyDinh;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TieuDeNoiQuy IS NULL
            RAISE EXCEPTION %;

        IF @TieuDeNoiQuy IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.QuiDinh
            WHERE TieuDeNoiQuy = @TieuDeNoiQuy
              AND (@MaQuyDinh IS NULL OR MaQuyDinh <> @MaQuyDinh)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinhNoiQuy INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinh IS NULL
            BEGIN
                SELECT @SoQuyDinhNoiQuy = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinh, 3, 4))), 0) + 1
                FROM dbo.QuiDinh 
                WHERE MaQuyDinh LIKE 'QD[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinhNoiQuy > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinh = CONCAT('QD', RIGHT(CONCAT('0000', @SoQuyDinhNoiQuy), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuiDinh (MaQuyDinh, TieuDeNoiQuy, NoiDung, TrangThai)
            VALUES (@MaQuyDinh, @TieuDeNoiQuy, @NoiDung, COALESCE(@TrangThai, 'Hiệu lực'));

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo nội quy',
                @DoiTuong = 'QuiDinh',
                @MaDoiTuong = @MaQuyDinh,
                @NoiDung = @TieuDeNoiQuy;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocNoiQuy TEXT;
        SELECT @DuLieuTruocNoiQuy = (
            SELECT * FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuiDinh
        SET TieuDeNoiQuy = COALESCE(@TieuDeNoiQuy, TieuDeNoiQuy),
            NoiDung = COALESCE(@NoiDung, NoiDung),
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh,
            @DuLieuTruoc = @DuLieuTruocNoiQuy;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        UPDATE dbo.QuiDinh
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinh AS maQuyDinh;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyNoiQuy @ThaoTac = 'DANH_SACH', @MaQuyDinh = @MaQuyDinh;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham
    @ThaoTac        VARCHAR(20)  = 'DANH_SACH',
    @MaDieuKhoan    VARCHAR(6)    = NULL,
    @TenDieuKhoan   VARCHAR(255) = NULL,
    @HinhThucXuPhat VARCHAR(20)  = NULL,
    @MucPhat        DECIMAL(15,2) = NULL,
    @TrangThai      VARCHAR(20)  = NULL,
    @AdminId        VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDieuKhoan = NULLIF(TRIM(@MaDieuKhoan)), '');
    SET @TenDieuKhoan = NULLIF(TRIM(@TenDieuKhoan)), '');
    SET @HinhThucXuPhat = NULLIF(TRIM(@HinhThucXuPhat)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dk.MaDieuKhoan AS maDieuKhoan,
            dk.TenDieuKhoan AS tenDieuKhoan,
            dk.HinhThucXuPhat AS hinhThucXuPhat,
            dk.MucPhat AS mucPhat,
            dk.TrangThai AS trangThai,
            COUNT(bb.MaBBViPham) AS soBienBanApDung
        FROM dbo.DieuKhoanViPham AS dk
        LEFT JOIN dbo.BienBanViPham AS bb ON bb.MaDieuKhoan = dk.MaDieuKhoan
        WHERE (@MaDieuKhoan IS NULL OR dk.MaDieuKhoan = @MaDieuKhoan)
          AND (@TrangThai IS NULL OR dk.TrangThai = @TrangThai)
          AND (@TenDieuKhoan IS NULL OR dk.TenDieuKhoan LIKE '%' + @TenDieuKhoan + '%')
        GROUP BY dk.MaDieuKhoan, dk.TenDieuKhoan, dk.HinhThucXuPhat, dk.MucPhat, dk.TrangThai
        ORDER BY dk.MaDieuKhoan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @HinhThucXuPhat IS NOT NULL AND @HinhThucXuPhat NOT IN ('Nhắc nhở', 'Phạt tiền')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @MucPhat IS NOT NULL AND @MucPhat < 0
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDieuKhoan IS NULL OR @HinhThucXuPhat IS NULL)
            RAISE EXCEPTION %;

        IF @TenDieuKhoan IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DieuKhoanViPham
            WHERE TenDieuKhoan = @TenDieuKhoan
              AND (@MaDieuKhoan IS NULL OR MaDieuKhoan <> @MaDieuKhoan)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDieuKhoan INT;

        IF @HinhThucXuPhat = 'Phạt tiền' AND COALESCE(@MucPhat, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucXuPhat = 'Nhắc nhở' AND @MucPhat IS NULL
            SET @MucPhat = 0;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDieuKhoan IS NULL
            BEGIN
                SELECT @SoDieuKhoan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDieuKhoan, 3, 4))), 0) + 1
                FROM dbo.DieuKhoanViPham 
                WHERE MaDieuKhoan LIKE 'VP[0-9][0-9][0-9][0-9]';

                IF @SoDieuKhoan > 9999
                    RAISE EXCEPTION %;

                SET @MaDieuKhoan = CONCAT('VP', RIGHT(CONCAT('0000', @SoDieuKhoan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DieuKhoanViPham (
                MaDieuKhoan, TenDieuKhoan, HinhThucXuPhat, MucPhat, TrangThai
            )
            VALUES (
                @MaDieuKhoan, @TenDieuKhoan, @HinhThucXuPhat, COALESCE(@MucPhat, 0), COALESCE(@TrangThai, 'Hiệu lực')
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo điều khoản vi phạm',
                @DoiTuong = 'DieuKhoanViPham',
                @MaDoiTuong = @MaDieuKhoan,
                @NoiDung = @TenDieuKhoan;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DECLARE @HinhThucSau VARCHAR(20);
        DECLARE @MucPhatSau DECIMAL(15,2);

        SELECT
            @HinhThucSau = COALESCE(@HinhThucXuPhat, HinhThucXuPhat),
            @MucPhatSau = COALESCE(@MucPhat, MucPhat)
        FROM dbo.DieuKhoanViPham
        WHERE MaDieuKhoan = @MaDieuKhoan;

        IF @HinhThucSau = 'Phạt tiền' AND COALESCE(@MucPhatSau, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucSau = 'Nhắc nhở' AND @MucPhatSau IS NULL
            SET @MucPhatSau = 0;

        DECLARE @DuLieuTruocDieuKhoan TEXT;
        SELECT @DuLieuTruocDieuKhoan = (
            SELECT * FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DieuKhoanViPham
        SET TenDieuKhoan = COALESCE(@TenDieuKhoan, TenDieuKhoan),
            HinhThucXuPhat = @HinhThucSau,
            MucPhat = @MucPhatSau,
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan,
            @DuLieuTruoc = @DuLieuTruocDieuKhoan;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        UPDATE dbo.DieuKhoanViPham
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.BienBanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDieuKhoan AS maDieuKhoan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDieuKhoanViPham @ThaoTac = 'DANH_SACH', @MaDieuKhoan = @MaDieuKhoan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhThamSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhThamSo
    @ThaoTac    VARCHAR(20)  = 'DANH_SACH',
    @MaThamSo   VARCHAR(50)   = NULL,
    @NhomThamSo VARCHAR(50)  = NULL,
    @TenThamSo  VARCHAR(100) = NULL,
    @GiaTri     VARCHAR(255) = NULL,
    @KieuDuLieu VARCHAR(20)  = NULL,
    @DonViTinh  VARCHAR(30)  = NULL,
    @MoTa       TEXT = NULL,
    @AdminId    VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaThamSo = NULLIF(TRIM(@MaThamSo)), '');
    SET @NhomThamSo = NULLIF(TRIM(@NhomThamSo)), '');
    SET @TenThamSo = NULLIF(TRIM(@TenThamSo)), '');
    SET @GiaTri = NULLIF(TRIM(@GiaTri)), '');
    SET @KieuDuLieu = NULLIF(TRIM(@KieuDuLieu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            MaThamSo AS maThamSo,
            NhomThamSo AS nhomThamSo,
            TenThamSo AS tenThamSo,
            GiaTri AS giaTri,
            KieuDuLieu AS kieuDuLieu,
            DonViTinh AS donViTinh,
            MoTa AS moTa,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.ThamSoHeThong
        WHERE (@MaThamSo IS NULL OR MaThamSo = @MaThamSo)
          AND (@NhomThamSo IS NULL OR NhomThamSo = @NhomThamSo)
        ORDER BY NhomThamSo, MaThamSo;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT')
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO' AND (@MaThamSo IS NULL OR @NhomThamSo IS NULL OR @TenThamSo IS NULL OR @GiaTri IS NULL)
        THROW 51262, 'Vui lòng nhập đủ mã, nhóm, tên và giá trị tham số.', 1;

    IF @MaThamSo IS NULL
        RAISE EXCEPTION %;

    IF @KieuDuLieu IS NOT NULL AND @KieuDuLieu NOT IN ('Chuỗi', 'Số', 'Ngày', 'Boolean')
        RAISE EXCEPTION %;

    DECLARE @KieuDuLieuSau VARCHAR(20);
    DECLARE @GiaTriSau VARCHAR(255);

    IF @ThaoTac = 'TAO'
    BEGIN
        SET @KieuDuLieuSau = COALESCE(@KieuDuLieu, 'Chuỗi');
        SET @GiaTriSau = @GiaTri;
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        SELECT
            @KieuDuLieuSau = COALESCE(@KieuDuLieu, KieuDuLieu),
            @GiaTriSau = COALESCE(@GiaTri, GiaTri)
        FROM dbo.ThamSoHeThong
        WHERE MaThamSo = @MaThamSo;
    END;

    IF @KieuDuLieuSau = 'Số' AND (TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) IS NULL OR TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) < 0)
        RAISE EXCEPTION %;

    IF @MaThamSo = 'THOI_HAN_THANH_TOAN_COC_GIO'
       AND (TRY_CONVERT(INT, @GiaTriSau) IS NULL OR TRY_CONVERT(INT, @GiaTriSau) <= 0)
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        INSERT INTO dbo.ThamSoHeThong (
            MaThamSo, NhomThamSo, TenThamSo, GiaTri, KieuDuLieu, DonViTinh, MoTa, CapNhatBoi
        )
        VALUES (
            @MaThamSo, @NhomThamSo, @TenThamSo, @GiaTriSau, @KieuDuLieuSau, @DonViTinh, @MoTa, @AdminId
        );

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @NoiDung = @TenThamSo;
    END
    ELSE
    BEGIN
        DECLARE @DuLieuTruocThamSo TEXT;
        SELECT @DuLieuTruocThamSo = (
            SELECT * FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.ThamSoHeThong
        SET NhomThamSo = COALESCE(@NhomThamSo, NhomThamSo),
            TenThamSo = COALESCE(@TenThamSo, TenThamSo),
            GiaTri = @GiaTriSau,
            KieuDuLieu = @KieuDuLieuSau,
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            MoTa = COALESCE(@MoTa, MoTa),
            CapNhatLuc = CURRENT_TIMESTAMP,
            CapNhatBoi = @AdminId
        WHERE MaThamSo = @MaThamSo;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @DuLieuTruoc = @DuLieuTruocThamSo;
    END;

    EXEC dbo.SP_Admin_CauHinhThamSo @ThaoTac = 'DANH_SACH', @MaThamSo = @MaThamSo;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhSaoLuu
    @ChuKyFull        VARCHAR(20)  = NULL,
    @ChuKyIncremental VARCHAR(20)  = NULL,
    @ThuMucLuuTru     VARCHAR(500) = NULL,
    @AdminId          VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ChuKyFull = NULLIF(TRIM(@ChuKyFull)), '');
    SET @ChuKyIncremental = NULLIF(TRIM(@ChuKyIncremental)), '');
    SET @ThuMucLuuTru = NULLIF(TRIM(@ThuMucLuuTru)), '');

    IF @ChuKyFull IS NOT NULL AND @ChuKyFull NOT IN ('Hàng tuần', 'Hàng tháng')
        RAISE EXCEPTION %;

    IF @ChuKyIncremental IS NOT NULL AND @ChuKyIncremental NOT IN ('Hàng ngày', 'Hàng tuần')
        RAISE EXCEPTION %;

    IF @ThuMucLuuTru IS NOT NULL
    BEGIN
        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);
    END;

    IF @ChuKyFull IS NULL AND @ChuKyIncremental IS NULL AND @ThuMucLuuTru IS NULL
    BEGIN
        SELECT
            MaCauHinh AS maCauHinh,
            ChuKyFull AS chuKyFull,
            ChuKyIncremental AS chuKyIncremental,
            ThuMucLuuTru AS thuMucLuuTru,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;
        RETURN;
    END;

    DECLARE @DuLieuTruocSaoLuu TEXT;
    SELECT @DuLieuTruocSaoLuu = (
        SELECT * FROM dbo.CauHinhSaoLuu WHERE MaCauHinh = 1 FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    UPDATE dbo.CauHinhSaoLuu
    SET ChuKyFull = COALESCE(@ChuKyFull, ChuKyFull),
        ChuKyIncremental = COALESCE(@ChuKyIncremental, ChuKyIncremental),
        ThuMucLuuTru = COALESCE(@ThuMucLuuTru, ThuMucLuuTru),
        CapNhatLuc = CURRENT_TIMESTAMP,
        CapNhatBoi = @AdminId
    WHERE MaCauHinh = 1;

    EXEC dbo.SP_Admin_GhiNhatKy
        @AdminId = @AdminId,
        @HanhDong = 'Cấu hình sao lưu',
        @DoiTuong = 'CauHinhSaoLuu',
        @MaDoiTuong = '1',
        @DuLieuTruoc = @DuLieuTruocSaoLuu;

    SELECT
        MaCauHinh AS maCauHinh,
        ChuKyFull AS chuKyFull,
        ChuKyIncremental AS chuKyIncremental,
        ThuMucLuuTru AS thuMucLuuTru,
        CapNhatLuc AS capNhatLuc,
        CapNhatBoi AS capNhatBoi
    FROM dbo.CauHinhSaoLuu
    WHERE MaCauHinh = 1;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_SaoLuuThuCong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_SaoLuuThuCong
    @LoaiSaoLuu  VARCHAR(20)  = 'Full',
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    

    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');
    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');
    IF @LoaiSaoLuu IS NULL SET @LoaiSaoLuu = 'Full';

    DECLARE @LoaiSaoLuuChuan VARCHAR(20) = UPPER(@LoaiSaoLuu);
    IF @LoaiSaoLuuChuan = 'FULL'
        SET @LoaiSaoLuu = 'Full';
    ELSE IF @LoaiSaoLuuChuan IN ('INCREMENTAL', 'DIFFERENTIAL')
        SET @LoaiSaoLuu = 'Incremental';

    IF @LoaiSaoLuu NOT IN ('Full', 'Incremental')
        RAISE EXCEPTION %;

    IF @DuongDanFile IS NULL
    BEGIN
        DECLARE @ThuMucLuuTru VARCHAR(500);
        SELECT @ThuMucLuuTru = ThuMucLuuTru
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;

        IF @ThuMucLuuTru IS NULL
            RAISE EXCEPTION %;

        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);

        SET @DuongDanFile =
            @ThuMucLuuTru + '\' + DB_NAME() + '_' + @LoaiSaoLuu + '_' +
            CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112) + REPLACE(CONVERT(CHAR(8), CURRENT_TIMESTAMP, 108), ':', '') + '.bak';
    END;

    DECLARE @MaSaoLuu INT;
    DECLARE @LenhSaoLuu TEXT;

    INSERT INTO dbo.LichSuSaoLuu (
        LoaiSaoLuu, DuongDanFile, TrangThai, ThoiGianBatDau, MaNguoiDung
    )
    VALUES (
        @LoaiSaoLuu, @DuongDanFile, 'Đang chạy', CURRENT_TIMESTAMP, @AdminId
    );

    SET @MaSaoLuu = SCOPE_IDENTITY();
    SET @LenhSaoLuu =
        'BACKUP DATABASE ' + QUOTENAME(DB_NAME()) +
        ' TO DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') +
        ''' WITH ' +
        CASE WHEN @LoaiSaoLuu = 'Incremental' THEN 'DIFFERENTIAL, INIT' ELSE 'INIT' END +
        ';';

    BEGIN TRY
        EXEC(@LenhSaoLuu);

        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thành công',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = 'Sao lưu hoàn tất.'
        WHERE MaSaoLuu = @MaSaoLuu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Sao lưu thủ công',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thất bại',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = ERROR_MESSAGE()
        WHERE MaSaoLuu = @MaSaoLuu;

        THROW;
    END CATCH;

    SELECT
        MaSaoLuu AS maSaoLuu,
        LoaiSaoLuu AS loaiSaoLuu,
        DuongDanFile AS duongDanFile,
        TrangThai AS trangThai,
        ThoiGianBatDau AS thoiGianBatDau,
        ThoiGianKetThuc AS thoiGianKetThuc,
        ThongBao AS thongBao
    FROM dbo.LichSuSaoLuu
    WHERE MaSaoLuu = @MaSaoLuu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_DanhSachSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_DanhSachSaoLuu
    @SoDong     INT          = 100,
    @TrangThai  VARCHAR(20) = NULL,
    @LoaiSaoLuu VARCHAR(20) = NULL
AS
BEGIN
    

    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 100;

    SELECT TOP (@SoDong)
        ls.MaSaoLuu AS maSaoLuu,
        ls.LoaiSaoLuu AS loaiSaoLuu,
        ls.DuongDanFile AS duongDanFile,
        ls.DungLuongByte AS dungLuongByte,
        ls.TrangThai AS trangThai,
        ls.ThoiGianBatDau AS thoiGianBatDau,
        ls.ThoiGianKetThuc AS thoiGianKetThuc,
        ls.ThongBao AS thongBao,
        ls.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung
    FROM dbo.LichSuSaoLuu AS ls
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = ls.MaNguoiDung
    WHERE (@TrangThai IS NULL OR ls.TrangThai = @TrangThai)
      AND (@LoaiSaoLuu IS NULL OR ls.LoaiSaoLuu = @LoaiSaoLuu)
    ORDER BY ls.ThoiGianBatDau DESC, ls.MaSaoLuu DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_PhucHoiDuLieu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_PhucHoiDuLieu
    @MaSaoLuu    INT           = NULL,
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL,
    @ChiTaoLenh   BOOLEAN           = 1
AS
BEGIN
    

    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');

    IF @DuongDanFile IS NULL AND @MaSaoLuu IS NOT NULL
    BEGIN
        SELECT @DuongDanFile = DuongDanFile
        FROM dbo.LichSuSaoLuu
        WHERE MaSaoLuu = @MaSaoLuu
          AND TrangThai = 'Thành công';
    END;

    IF @DuongDanFile IS NULL
        RAISE EXCEPTION %;

    DECLARE @TenDatabase SYSNAME = DB_NAME();
    DECLARE @LenhSingleUser TEXT;
    DECLARE @LenhRestore TEXT;
    DECLARE @LenhMultiUser TEXT;
    DECLARE @LenhDayDu TEXT;

    SET @LenhSingleUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET SINGLE_USER WITH ROLLBACK IMMEDIATE;';
    SET @LenhRestore = 'USE [master]; RESTORE DATABASE ' + QUOTENAME(@TenDatabase) +
        ' FROM DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') + ''' WITH REPLACE;';
    SET @LenhMultiUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET MULTI_USER;';
    SET @LenhDayDu = @LenhSingleUser + CHAR(13) + CHAR(10) + @LenhRestore + CHAR(13) + CHAR(10) + @LenhMultiUser;

    IF @ChiTaoLenh = 1
    BEGIN
        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo lệnh phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;

        SELECT
            @TenDatabase AS tenDatabase,
            @DuongDanFile AS duongDanFile,
            @LenhDayDu AS lenhPhucHoi,
            CAST(1 AS BOOLEAN) AS chiTaoLenh;
        RETURN;
    END;

    BEGIN TRY
        EXEC(@LenhSingleUser);
        EXEC(@LenhRestore);
        EXEC(@LenhMultiUser);

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        BEGIN TRY
            EXEC(@LenhMultiUser);
        END TRY
        BEGIN CATCH
        END CATCH;

        THROW;
    END CATCH;

    SELECT
        @TenDatabase AS tenDatabase,
        @DuongDanFile AS duongDanFile,
        CAST(1 AS BOOLEAN) AS daPhucHoi;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_XemNhatKyHeThong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_XemNhatKyHeThong
    @TuNgay     TIMESTAMP  = NULL,
    @DenNgay    TIMESTAMP  = NULL,
    @AdminId    VARCHAR(6)    = NULL,
    @DoiTuong   VARCHAR(100) = NULL,
    @HanhDong   VARCHAR(100) = NULL,
    @TuKhoa     VARCHAR(100) = NULL,
    @SoDong     INT           = 200
AS
BEGIN
    

    SET @AdminId = NULLIF(TRIM(@AdminId)), '');
    SET @DoiTuong = NULLIF(TRIM(@DoiTuong)), '');
    SET @HanhDong = NULLIF(TRIM(@HanhDong)), '');
    SET @TuKhoa = NULLIF(TRIM(@TuKhoa)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 200;

    SELECT TOP (@SoDong)
        nk.MaNhatKy AS maNhatKy,
        nk.ThoiGian AS thoiGian,
        nk.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung,
        nk.VaiTro AS vaiTro,
        nk.ChucNang AS chucNang,
        nk.HanhDong AS hanhDong,
        nk.DoiTuong AS doiTuong,
        nk.MaDoiTuong AS maDoiTuong,
        nk.NoiDung AS noiDung,
        nk.DuLieuTruoc AS duLieuTruoc,
        nk.DuLieuSau AS duLieuSau
    FROM dbo.NhatKyHeThong AS nk
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nk.MaNguoiDung
    WHERE (@TuNgay IS NULL OR nk.ThoiGian >= @TuNgay)
      AND (@DenNgay IS NULL OR nk.ThoiGian < DATEADD(DAY, 1, @DenNgay))
      AND (@AdminId IS NULL OR nk.MaNguoiDung = @AdminId)
      AND (@DoiTuong IS NULL OR nk.DoiTuong = @DoiTuong)
      AND (@HanhDong IS NULL OR nk.HanhDong LIKE '%' + @HanhDong + '%')
      AND (
          @TuKhoa IS NULL
          OR nk.NoiDung LIKE '%' + @TuKhoa + '%'
          OR nk.MaDoiTuong LIKE '%' + @TuKhoa + '%'
          OR nk.HanhDong LIKE '%' + @TuKhoa + '%'
      )
    ORDER BY nk.ThoiGian DESC, nk.MaNhatKy DESC;
END; THEN (SUBSTRING(@MaChiNhanh, 3, 4)::INT ELSE NULL END);
    DECLARE @Index INT = 1;
    DECLARE @MaGiuong VARCHAR(3);

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @MaPhong IS NULL
        BEGIN
            IF @SoChiNhanh IS NULL OR @SoChiNhanh NOT BETWEEN 1 AND 9
                RAISE EXCEPTION %;

            SELECT @SoPhong = COALESCE(MAX(CASE WHEN (RIGHT(MaPhong, 2) ~ '^[0-9]+)), 0) + 1
            FROM dbo.Phong 
            WHERE MaChiNhanh = @MaChiNhanh
              AND MaPhong LIKE CONCAT('P', @SoChiNhanh, '[0-9][0-9]');

            IF @SoPhong > 99
                RAISE EXCEPTION %;

            SET @MaPhong = CONCAT('P', @SoChiNhanh, RIGHT(CONCAT('00', @SoPhong), 2));
        END;

        IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        INSERT INTO dbo.Phong (MaPhong, TenPhong, GioiTinhChoPhep, TinhTrang, MaChiNhanh, MaLoaiPhong)
        VALUES (@MaPhong, @TenPhong, @GioiTinhChoPhep, @TinhTrang, @MaChiNhanh, @MaLoaiPhong);

        IF @UrlImg IS NOT NULL
        BEGIN
            INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
            VALUES (@MaPhong, 1, @UrlImg);
        END;

        WHILE @Index <= @SoGiuong
        BEGIN
            SET @MaGiuong = CONCAT('G', RIGHT(CONCAT('00', @Index), 2));

            INSERT INTO dbo.Giuong (MaPhong, MaGiuong, SoGiuong, TinhTrang)
            VALUES (@MaPhong, @MaGiuong, @Index, 'Trống');

            SET @Index += 1;
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo phòng giường',
            @DoiTuong = 'Phong',
            @MaDoiTuong = @MaPhong,
            @NoiDung = @TenPhong;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        p.MaPhong AS maPhong,
        p.TenPhong AS tenPhong,
        p.GioiTinhChoPhep AS gioiTinhChoPhep,
        p.TinhTrang AS tinhTrangPhong,
        (SELECT TOP 1 hap.UrlImg FROM dbo.HinhAnhPhong AS hap WHERE hap.MaPhong = p.MaPhong ORDER BY hap.STTAnh) AS urlImgPhong,
        p.MaChiNhanh AS maChiNhanh,
        cn.TenChiNhanh AS tenChiNhanh,
        p.MaLoaiPhong AS maLoaiPhong,
        lp.TenLoaiPhong AS tenLoaiPhong,
        g.MaGiuong AS maGiuong,
        g.SoGiuong AS soGiuong,
        g.TinhTrang AS tinhTrangGiuong
    FROM dbo.Phong AS p
    INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    LEFT JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
    WHERE p.MaPhong = @MaPhong
    ORDER BY g.SoGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CapNhatTrangThaiPhongGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CapNhatTrangThaiPhongGiuong
    @LoaiDoiTuong VARCHAR(20),
    @MaPhong      VARCHAR(4),
    @MaGiuong     VARCHAR(3)   = NULL,
    @TrangThai    VARCHAR(20),
    @AdminId      VARCHAR(6)   = NULL
AS
BEGIN
    
    

    SET @LoaiDoiTuong = UPPER(NULLIF(TRIM(@LoaiDoiTuong)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');

    IF @LoaiDoiTuong NOT IN ('PHONG', 'GIUONG')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @LoaiDoiTuong = 'PHONG' AND @TrangThai NOT IN ('Trống', 'Đã đặt cọc', 'Còn chỗ', 'Đầy', 'Giữ chỗ', 'Bảo trì')
        RAISE EXCEPTION %;

    IF @LoaiDoiTuong = 'GIUONG' AND @TrangThai NOT IN ('Trống', 'Đã đặt cọc', 'Đang thuê')
        RAISE EXCEPTION %;

    IF @LoaiDoiTuong = 'GIUONG'
       AND (@MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
       ))
        RAISE EXCEPTION %;

    DECLARE @DuLieuTruoc TEXT;

    IF @LoaiDoiTuong = 'PHONG'
        SELECT @DuLieuTruoc = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );
    ELSE
        SELECT @DuLieuTruoc = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @LoaiDoiTuong = 'PHONG'
        BEGIN
            UPDATE dbo.Phong
            SET TinhTrang = @TrangThai
            WHERE MaPhong = @MaPhong;
        END
        ELSE
        BEGIN
            UPDATE dbo.Giuong
            SET TinhTrang = @TrangThai
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong;

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (
                    SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống'
                ) THEN 'Trống'
                WHEN NOT EXISTS (
                    SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống'
                ) THEN 'Đầy'
                WHEN EXISTS (
                    SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Đã đặt cọc'
                ) THEN 'Còn chỗ'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật trạng thái phòng/giường',
            @DoiTuong = @LoaiDoiTuong,
            @MaDoiTuong = @MaPhong,
            @NoiDung = @TrangThai,
            @DuLieuTruoc = @DuLieuTruoc;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        p.MaPhong AS maPhong,
        p.TenPhong AS tenPhong,
        p.TinhTrang AS tinhTrangPhong,
        g.MaGiuong AS maGiuong,
        g.SoGiuong AS soGiuong,
        g.TinhTrang AS tinhTrangGiuong
    FROM dbo.Phong AS p
    LEFT JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
    WHERE p.MaPhong = @MaPhong
      AND (@MaGiuong IS NULL OR g.MaGiuong = @MaGiuong)
    ORDER BY g.SoGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyPhong
    @ThaoTac         VARCHAR(20)  = 'DANH_SACH',
    @MaPhong         VARCHAR(4)    = NULL,
    @TenPhong        VARCHAR(100) = NULL,
    @GioiTinhChoPhep VARCHAR(20)  = NULL,
    @TinhTrang       VARCHAR(20)  = NULL,
    @UrlImg          VARCHAR(500)  = NULL,
    @MaChiNhanh      VARCHAR(6)    = NULL,
    @MaLoaiPhong     VARCHAR(6)    = NULL,
    @AdminId         VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @TenPhong = NULLIF(TRIM(@TenPhong)), '');
    SET @GioiTinhChoPhep = NULLIF(TRIM(@GioiTinhChoPhep)), '');
    SET @TinhTrang = NULLIF(TRIM(@TinhTrang)), '');
    SET @UrlImg = NULLIF(TRIM(@UrlImg)), '');
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @MaLoaiPhong = NULLIF(TRIM(@MaLoaiPhong)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            p.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            p.GioiTinhChoPhep AS gioiTinhChoPhep,
            p.TinhTrang AS tinhTrang,
            (SELECT TOP 1 hap.UrlImg FROM dbo.HinhAnhPhong AS hap WHERE hap.MaPhong = p.MaPhong ORDER BY hap.STTAnh) AS urlImg,
            p.MaChiNhanh AS maChiNhanh,
            cn.TenChiNhanh AS tenChiNhanh,
            p.MaLoaiPhong AS maLoaiPhong,
            lp.TenLoaiPhong AS tenLoaiPhong,
            COUNT(g.MaGiuong) AS soGiuong,
            SUM(CASE WHEN g.TinhTrang = 'Trống' THEN 1 ELSE 0 END) AS soGiuongTrong
        FROM dbo.Phong AS p
        INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
        INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
        LEFT JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
        WHERE (@MaPhong IS NULL OR p.MaPhong = @MaPhong)
          AND (@MaChiNhanh IS NULL OR p.MaChiNhanh = @MaChiNhanh)
          AND (@MaLoaiPhong IS NULL OR p.MaLoaiPhong = @MaLoaiPhong)
          AND (@TinhTrang IS NULL OR p.TinhTrang = @TinhTrang)
        GROUP BY p.MaPhong, p.TenPhong, p.GioiTinhChoPhep, p.TinhTrang,
                 p.MaChiNhanh, cn.TenChiNhanh, p.MaLoaiPhong, lp.TenLoaiPhong
        ORDER BY p.MaPhong;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO'
           AND (@TenPhong IS NULL OR @GioiTinhChoPhep IS NULL OR @MaChiNhanh IS NULL OR @MaLoaiPhong IS NULL)
            THROW 51102, 'Vui lòng nhập đầy đủ tên phòng, giới tính, chi nhánh và loại phòng.', 1;

        IF @GioiTinhChoPhep IS NOT NULL AND @GioiTinhChoPhep NOT IN ('Nam', 'Nữ', 'Không phân biệt')
            RAISE EXCEPTION %;

        IF @TinhTrang IS NOT NULL AND @TinhTrang NOT IN ('Trống', 'Đã đặt cọc', 'Còn chỗ', 'Đầy', 'Giữ chỗ', 'Bảo trì')
            RAISE EXCEPTION %;

        IF @MaChiNhanh IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
            RAISE EXCEPTION %;

        IF @MaLoaiPhong IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoPhongMoi INT;
        DECLARE @SoChiNhanhPhong INT = TRY_CONVERT(INT, SUBSTRING(@MaChiNhanh, 3, 4));

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaPhong IS NULL
            BEGIN
                IF @SoChiNhanhPhong IS NULL OR @SoChiNhanhPhong NOT BETWEEN 1 AND 9
                    RAISE EXCEPTION %;

                SELECT @SoPhongMoi = COALESCE(MAX(TRY_CONVERT(INT, RIGHT(MaPhong, 2))), 0) + 1
                FROM dbo.Phong 
                WHERE MaChiNhanh = @MaChiNhanh
                  AND MaPhong LIKE CONCAT('P', @SoChiNhanhPhong, '[0-9][0-9]');

                IF @SoPhongMoi > 99
                    RAISE EXCEPTION %;

                SET @MaPhong = CONCAT('P', @SoChiNhanhPhong, RIGHT(CONCAT('00', @SoPhongMoi), 2));
            END;

            IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
                RAISE EXCEPTION %;

            INSERT INTO dbo.Phong (MaPhong, TenPhong, GioiTinhChoPhep, TinhTrang, MaChiNhanh, MaLoaiPhong)
            VALUES (@MaPhong, @TenPhong, @GioiTinhChoPhep, COALESCE(@TinhTrang, 'Trống'), @MaChiNhanh, @MaLoaiPhong);

            IF @UrlImg IS NOT NULL
            BEGIN
                INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
                VALUES (@MaPhong, 1, @UrlImg);
            END;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo phòng',
                @DoiTuong = 'Phong',
                @MaDoiTuong = @MaPhong,
                @NoiDung = @TenPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocPhong TEXT;
        SELECT @DuLieuTruocPhong = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.Phong
        SET TenPhong = COALESCE(@TenPhong, TenPhong),
            GioiTinhChoPhep = COALESCE(@GioiTinhChoPhep, GioiTinhChoPhep),
            TinhTrang = COALESCE(@TinhTrang, TinhTrang),
            MaChiNhanh = COALESCE(@MaChiNhanh, MaChiNhanh),
            MaLoaiPhong = COALESCE(@MaLoaiPhong, MaLoaiPhong)
        WHERE MaPhong = @MaPhong;

        IF @UrlImg IS NOT NULL
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.HinhAnhPhong WHERE MaPhong = @MaPhong AND STTAnh = 1)
                UPDATE dbo.HinhAnhPhong
                SET UrlImg = @UrlImg
                WHERE MaPhong = @MaPhong AND STTAnh = 1;
            ELSE
                INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
                VALUES (@MaPhong, 1, @UrlImg);
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật phòng',
            @DoiTuong = 'Phong',
            @MaDoiTuong = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocPhong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống')
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc AS ctdc
            INNER JOIN dbo.PhieuDatCoc AS pdc ON pdc.MaPhieuDatCoc = ctdc.MaPhieuDatCoc
            WHERE ctdc.MaPhong = @MaPhong
              AND pdc.TrangThaiCoc IN ('Hiệu lực', 'Đã lập HĐ')
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietDatCoc WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong)
           OR EXISTS (SELECT 1 FROM dbo.ChiTietXemPhong WHERE MaPhong = @MaPhong)
           OR EXISTS (SELECT 1 FROM dbo.PhieuGhiChiSo WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocPhongXoa TEXT;
        SELECT @DuLieuTruocPhongXoa = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        BEGIN TRY
            BEGIN TRANSACTION;

            DELETE FROM dbo.Giuong WHERE MaPhong = @MaPhong;
            DELETE FROM dbo.Phong WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa phòng',
                @DoiTuong = 'Phong',
                @MaDoiTuong = @MaPhong,
                @DuLieuTruoc = @DuLieuTruocPhongXoa;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyPhong @ThaoTac = 'DANH_SACH', @MaPhong = @MaPhong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyGiuong
    @ThaoTac   VARCHAR(20) = 'DANH_SACH',
    @MaPhong   VARCHAR(4)   = NULL,
    @MaGiuong  VARCHAR(3)   = NULL,
    @SoGiuong  INT          = NULL,
    @TinhTrang VARCHAR(20) = NULL,
    @UrlImg    VARCHAR(500) = NULL,
    @AdminId   VARCHAR(6)   = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    SET @TinhTrang = NULLIF(TRIM(@TinhTrang)), '');
    SET @UrlImg = NULLIF(TRIM(@UrlImg)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            g.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            g.MaGiuong AS maGiuong,
            g.SoGiuong AS soGiuong,
            g.TinhTrang AS tinhTrang,
            lp.SucChuaToiDa AS sucChuaToiDa,
            (
                SELECT COUNT(1)
                FROM dbo.TaiSan AS tsChung
                WHERE tsChung.MaPhong = g.MaPhong
                  AND tsChung.LoaiTaiSan = 'Chung'
            ) AS soTaiSanChung,
            CAST(0 AS INT) AS soTaiSanRieng
        FROM dbo.Giuong AS g
        INNER JOIN dbo.Phong AS p ON p.MaPhong = g.MaPhong
        INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
        WHERE (@MaPhong IS NULL OR g.MaPhong = @MaPhong)
          AND (@MaGiuong IS NULL OR g.MaGiuong = @MaGiuong)
          AND (@TinhTrang IS NULL OR g.TinhTrang = @TinhTrang)
        ORDER BY g.MaPhong, g.SoGiuong, g.MaGiuong;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @SoGiuong IS NULL
            RAISE EXCEPTION %;

        IF @SoGiuong IS NOT NULL AND @SoGiuong < 1
            RAISE EXCEPTION %;

        IF @TinhTrang IS NOT NULL AND @TinhTrang NOT IN ('Trống', 'Đã đặt cọc', 'Đang thuê')
            RAISE EXCEPTION %;
    END;

    DECLARE @SucChuaToiDa INT;
    SELECT @SucChuaToiDa = lp.SucChuaToiDa
    FROM dbo.Phong AS p
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    WHERE p.MaPhong = @MaPhong;

    IF @SoGiuong IS NOT NULL AND @SoGiuong > @SucChuaToiDa
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF (SELECT COUNT(*) FROM dbo.Giuong WHERE MaPhong = @MaPhong) >= @SucChuaToiDa
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND SoGiuong = @SoGiuong)
            RAISE EXCEPTION %;

        IF @MaGiuong IS NULL
        BEGIN
            DECLARE @SoMaGiuong INT;
            SELECT @SoMaGiuong = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaGiuong, 2, 2))), 0) + 1
            FROM dbo.Giuong 
            WHERE MaPhong = @MaPhong
              AND MaGiuong LIKE 'G[0-9][0-9]';

            IF @SoMaGiuong > 99
                RAISE EXCEPTION %;

            SET @MaGiuong = CONCAT('G', RIGHT(CONCAT('00', @SoMaGiuong), 2));
        END;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong)
            RAISE EXCEPTION %;

        BEGIN TRY
            BEGIN TRANSACTION;

            INSERT INTO dbo.Giuong (MaPhong, MaGiuong, SoGiuong, TinhTrang)
            VALUES (@MaPhong, @MaGiuong, @SoGiuong, COALESCE(@TinhTrang, 'Trống'));

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo giường',
                @DoiTuong = 'Giuong',
                @MaDoiTuong = @MaGiuong,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF @SoGiuong IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.Giuong
            WHERE MaPhong = @MaPhong
              AND SoGiuong = @SoGiuong
              AND MaGiuong <> @MaGiuong
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocGiuong TEXT;
        SELECT @DuLieuTruocGiuong = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.Giuong
        SET SoGiuong = COALESCE(@SoGiuong, SoGiuong),
            TinhTrang = COALESCE(@TinhTrang, TinhTrang)
        WHERE MaPhong = @MaPhong
          AND MaGiuong = @MaGiuong;

        UPDATE dbo.Phong
        SET TinhTrang = CASE
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong) THEN 'Trống'
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
            ELSE 'Còn chỗ'
        END
        WHERE MaPhong = @MaPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật giường',
            @DoiTuong = 'Giuong',
            @MaDoiTuong = @MaGiuong,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocGiuong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1 FROM dbo.Giuong
            WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong AND TinhTrang <> 'Trống'
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc AS ctdc
            INNER JOIN dbo.PhieuDatCoc AS pdc ON pdc.MaPhieuDatCoc = ctdc.MaPhieuDatCoc
            WHERE ctdc.MaPhong = @MaPhong
              AND ctdc.MaGiuong = @MaGiuong
              AND pdc.TrangThaiCoc IN ('Hiệu lực', 'Đã lập HĐ')
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietXemPhong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocGiuongXoa TEXT;
        SELECT @DuLieuTruocGiuongXoa = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        BEGIN TRY
            BEGIN TRANSACTION;

            DELETE FROM dbo.Giuong
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong;

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong) THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa giường',
                @DoiTuong = 'Giuong',
                @MaDoiTuong = @MaGiuong,
                @NoiDung = @MaPhong,
                @DuLieuTruoc = @DuLieuTruocGiuongXoa;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaGiuong AS maGiuong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyGiuong @ThaoTac = 'DANH_SACH', @MaPhong = @MaPhong, @MaGiuong = @MaGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyTaiSanPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyTaiSanPhong
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaPhong   VARCHAR(4)    = NULL,
    @MaTaiSan  VARCHAR(6)    = NULL,
    @TenTaiSan VARCHAR(100) = NULL,
    @SoLuong   INT           = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @LoaiTaiSan VARCHAR(20) = NULL,
    @MaGiuong   VARCHAR(3)   = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaTaiSan = NULLIF(TRIM(@MaTaiSan)), '');
    SET @TenTaiSan = NULLIF(TRIM(@TenTaiSan)), '');
    SET @LoaiTaiSan = NULLIF(TRIM(@LoaiTaiSan)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            ts.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            ts.MaTaiSan AS maTaiSan,
            ts.TenTaiSan AS tenTaiSan,
            ts.SoLuong AS soLuong,
            ts.DonGia AS donGia,
            ts.LoaiTaiSan AS loaiTaiSan,
            ts.MaGiuong AS maGiuong,
            g.SoGiuong AS soGiuong
        FROM dbo.TaiSan AS ts
        INNER JOIN dbo.Phong AS p ON p.MaPhong = ts.MaPhong
        LEFT JOIN dbo.Giuong AS g ON g.MaPhong = ts.MaPhong AND g.MaGiuong = ts.MaGiuong
        WHERE (@MaPhong IS NULL OR ts.MaPhong = @MaPhong)
          AND (@MaTaiSan IS NULL OR ts.MaTaiSan = @MaTaiSan)
          AND (@MaGiuong IS NULL OR ts.MaGiuong = @MaGiuong)
          AND (@LoaiTaiSan IS NULL OR ts.LoaiTaiSan = @LoaiTaiSan)
        ORDER BY ts.MaPhong, ts.LoaiTaiSan, ts.MaGiuong, ts.MaTaiSan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TenTaiSan IS NULL
            RAISE EXCEPTION %;

        IF @SoLuong IS NOT NULL AND @SoLuong <= 0
            RAISE EXCEPTION %;

        IF @DonGia IS NOT NULL AND @DonGia < 0
            RAISE EXCEPTION %;

        DECLARE @LoaiTaiSanSau VARCHAR(20);
        DECLARE @MaGiuongSau VARCHAR(3);

        IF @ThaoTac = 'TAO'
        BEGIN
            SET @LoaiTaiSanSau = COALESCE(@LoaiTaiSan, 'Chung');
            SET @MaGiuongSau = @MaGiuong;
        END
        ELSE
        BEGIN
            IF @MaTaiSan IS NULL OR NOT EXISTS (
                SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
            )
                RAISE EXCEPTION %;

            SELECT
                @LoaiTaiSanSau = COALESCE(@LoaiTaiSan, LoaiTaiSan),
                @MaGiuongSau = CASE
                    WHEN @LoaiTaiSan = 'Chung' THEN NULL
                    ELSE COALESCE(@MaGiuong, MaGiuong)
                END
            FROM dbo.TaiSan
            WHERE MaPhong = @MaPhong
              AND MaTaiSan = @MaTaiSan;
        END;

        IF @LoaiTaiSanSau NOT IN ('Chung', 'Riêng')
            RAISE EXCEPTION %;

        IF @LoaiTaiSanSau = 'Chung'
            SET @MaGiuongSau = NULL;

        IF @LoaiTaiSanSau = 'Riêng' AND @MaGiuongSau IS NULL
            RAISE EXCEPTION %;

        IF @MaGiuongSau IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuongSau
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoTaiSan INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaTaiSan IS NULL
            BEGIN
                SELECT @SoTaiSan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaTaiSan, 3, 4))), 0) + 1
                FROM dbo.TaiSan 
                WHERE MaPhong = @MaPhong
                  AND MaTaiSan LIKE 'TS[0-9][0-9][0-9][0-9]';

                IF @SoTaiSan > 9999
                    RAISE EXCEPTION %;

                SET @MaTaiSan = CONCAT('TS', RIGHT(CONCAT('0000', @SoTaiSan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.TaiSan (
                MaPhong, MaTaiSan, TenTaiSan, SoLuong, DonGia, LoaiTaiSan, MaGiuong
            )
            VALUES (
                @MaPhong, @MaTaiSan, @TenTaiSan, COALESCE(@SoLuong, 1),
                @DonGia, @LoaiTaiSanSau, @MaGiuongSau
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo tài sản phòng',
                @DoiTuong = 'TaiSan',
                @MaDoiTuong = @MaTaiSan,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocTaiSan TEXT;
        SELECT @DuLieuTruocTaiSan = (
            SELECT * FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.TaiSan
        SET TenTaiSan = COALESCE(@TenTaiSan, TenTaiSan),
            SoLuong = COALESCE(@SoLuong, SoLuong),
            DonGia = COALESCE(@DonGia, DonGia),
            LoaiTaiSan = @LoaiTaiSanSau,
            MaGiuong = @MaGiuongSau
        WHERE MaPhong = @MaPhong
          AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocTaiSan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietBanGiao WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.ChiTietHuHong WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.YeuCauSuaChua WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaTaiSan AS maTaiSan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyTaiSanPhong
        @ThaoTac = 'DANH_SACH',
        @MaPhong = @MaPhong,
        @MaTaiSan = @MaTaiSan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc
    @ThaoTac           VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinhHoanCoc VARCHAR(6)    = NULL,
    @TenQuyDinh        VARCHAR(255) = NULL,
    @TyLeHoanCoc       DECIMAL(5,2)  = NULL,
    @AdminId           VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinhHoanCoc = NULLIF(TRIM(@MaQuyDinhHoanCoc)), '');
    SET @TenQuyDinh = NULLIF(TRIM(@TenQuyDinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qh.MaQuyDinhHoanCoc AS maQuyDinhHoanCoc,
            qh.TenQuyDinh AS tenQuyDinh,
            qh.TyLeHoanCoc AS tyLeHoanCoc,
            COUNT(ds.MaQuyDinhHoanCoc) AS soLanApDung
        FROM dbo.QuyDinhHoanCoc AS qh
        LEFT JOIN dbo.DoiSoat AS ds ON ds.MaQuyDinhHoanCoc = qh.MaQuyDinhHoanCoc
        WHERE (@MaQuyDinhHoanCoc IS NULL OR qh.MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
        GROUP BY qh.MaQuyDinhHoanCoc, qh.TenQuyDinh, qh.TyLeHoanCoc
        ORDER BY qh.MaQuyDinhHoanCoc;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenQuyDinh IS NULL OR @TyLeHoanCoc IS NULL)
            RAISE EXCEPTION %;

        IF @TyLeHoanCoc IS NOT NULL AND (@TyLeHoanCoc < 0 OR @TyLeHoanCoc > 100)
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinh INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinhHoanCoc IS NULL
            BEGIN
                SELECT @SoQuyDinh = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinhHoanCoc, 3, 4))), 0) + 1
                FROM dbo.QuyDinhHoanCoc 
                WHERE MaQuyDinhHoanCoc LIKE 'QH[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinh > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinhHoanCoc = CONCAT('QH', RIGHT(CONCAT('0000', @SoQuyDinh), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuyDinhHoanCoc (MaQuyDinhHoanCoc, TenQuyDinh, TyLeHoanCoc)
            VALUES (@MaQuyDinhHoanCoc, @TenQuyDinh, @TyLeHoanCoc);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo quy định hoàn cọc',
                @DoiTuong = 'QuyDinhHoanCoc',
                @MaDoiTuong = @MaQuyDinhHoanCoc,
                @NoiDung = @TenQuyDinh;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocHoanCoc TEXT;
        SELECT @DuLieuTruocHoanCoc = (
            SELECT * FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuyDinhHoanCoc
        SET TenQuyDinh = COALESCE(@TenQuyDinh, TenQuyDinh),
            TyLeHoanCoc = COALESCE(@TyLeHoanCoc, TyLeHoanCoc)
        WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc,
            @DuLieuTruoc = @DuLieuTruocHoanCoc;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DoiSoat WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinhHoanCoc AS maQuyDinhHoanCoc;
        RETURN;
    END;

    EXEC dbo.SP_Admin_CauHinhQuyDinhHoanCoc @ThaoTac = 'DANH_SACH', @MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDichVu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDichVu
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaDichVu  VARCHAR(6)    = NULL,
    @TenDichVu VARCHAR(100) = NULL,
    @DonViTinh VARCHAR(20)   = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDichVu = NULLIF(TRIM(@MaDichVu)), '');
    SET @TenDichVu = NULLIF(TRIM(@TenDichVu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dv.MaDichVu AS maDichVu,
            dv.TenDichVu AS tenDichVu,
            dv.DonViTinh AS donViTinh,
            dv.DonGia AS donGia,
            COUNT(DISTINCT dvhd.MaChiTietDVHD) AS soHopDongSuDung,
            COUNT(cthd.MaChiTietHD) AS soDongHoaDon
        FROM dbo.DichVu AS dv
        LEFT JOIN dbo.DichVuHopDong AS dvhd ON dvhd.MaDichVu = dv.MaDichVu
        LEFT JOIN dbo.ChiTietHoaDon AS cthd ON cthd.MaChiTietDVHD = dvhd.MaChiTietDVHD
        WHERE (@MaDichVu IS NULL OR dv.MaDichVu = @MaDichVu)
          AND (@TenDichVu IS NULL OR dv.TenDichVu LIKE '%' + @TenDichVu + '%')
        GROUP BY dv.MaDichVu, dv.TenDichVu, dv.DonViTinh, dv.DonGia
        ORDER BY dv.MaDichVu;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDichVu IS NULL OR @DonViTinh IS NULL OR @DonGia IS NULL)
            THROW 51202, 'Vui lòng nhập tên dịch vụ, đơn vị tính và đơn giá.', 1;

        IF @DonGia IS NOT NULL AND @DonGia <= 0
            RAISE EXCEPTION %;

        IF @TenDichVu IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DichVu
            WHERE TenDichVu = @TenDichVu
              AND (@MaDichVu IS NULL OR MaDichVu <> @MaDichVu)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDichVu INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDichVu IS NULL
            BEGIN
                SELECT @SoDichVu = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDichVu, 3, 4))), 0) + 1
                FROM dbo.DichVu 
                WHERE MaDichVu LIKE 'DV[0-9][0-9][0-9][0-9]';

                IF @SoDichVu > 9999
                    RAISE EXCEPTION %;

                SET @MaDichVu = CONCAT('DV', RIGHT(CONCAT('0000', @SoDichVu), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DichVu (MaDichVu, TenDichVu, DonViTinh, DonGia)
            VALUES (@MaDichVu, @TenDichVu, @DonViTinh, @DonGia);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo dịch vụ',
                @DoiTuong = 'DichVu',
                @MaDoiTuong = @MaDichVu,
                @NoiDung = @TenDichVu;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocDichVu TEXT;
        SELECT @DuLieuTruocDichVu = (
            SELECT * FROM dbo.DichVu WHERE MaDichVu = @MaDichVu FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DichVu
        SET TenDichVu = COALESCE(@TenDichVu, TenDichVu),
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            DonGia = COALESCE(@DonGia, DonGia)
        WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu,
            @DuLieuTruoc = @DuLieuTruocDichVu;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DichVuHopDong WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DichVu WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDichVu AS maDichVu;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDichVu @ThaoTac = 'DANH_SACH', @MaDichVu = @MaDichVu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyNoiQuy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyNoiQuy
    @ThaoTac      VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinh    VARCHAR(6)    = NULL,
    @TieuDeNoiQuy VARCHAR(255) = NULL,
    @NoiDung      TEXT = NULL,
    @TrangThai    VARCHAR(20)  = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinh = NULLIF(TRIM(@MaQuyDinh)), '');
    SET @TieuDeNoiQuy = NULLIF(TRIM(@TieuDeNoiQuy)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qd.MaQuyDinh AS maQuyDinh,
            qd.TieuDeNoiQuy AS tieuDeNoiQuy,
            qd.NoiDung AS noiDung,
            qd.TrangThai AS trangThai
        FROM dbo.QuiDinh AS qd
        WHERE (@MaQuyDinh IS NULL OR qd.MaQuyDinh = @MaQuyDinh)
          AND (@TrangThai IS NULL OR qd.TrangThai = @TrangThai)
          AND (@TieuDeNoiQuy IS NULL OR qd.TieuDeNoiQuy LIKE '%' + @TieuDeNoiQuy + '%')
        ORDER BY qd.MaQuyDinh;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TieuDeNoiQuy IS NULL
            RAISE EXCEPTION %;

        IF @TieuDeNoiQuy IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.QuiDinh
            WHERE TieuDeNoiQuy = @TieuDeNoiQuy
              AND (@MaQuyDinh IS NULL OR MaQuyDinh <> @MaQuyDinh)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinhNoiQuy INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinh IS NULL
            BEGIN
                SELECT @SoQuyDinhNoiQuy = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinh, 3, 4))), 0) + 1
                FROM dbo.QuiDinh 
                WHERE MaQuyDinh LIKE 'QD[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinhNoiQuy > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinh = CONCAT('QD', RIGHT(CONCAT('0000', @SoQuyDinhNoiQuy), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuiDinh (MaQuyDinh, TieuDeNoiQuy, NoiDung, TrangThai)
            VALUES (@MaQuyDinh, @TieuDeNoiQuy, @NoiDung, COALESCE(@TrangThai, 'Hiệu lực'));

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo nội quy',
                @DoiTuong = 'QuiDinh',
                @MaDoiTuong = @MaQuyDinh,
                @NoiDung = @TieuDeNoiQuy;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocNoiQuy TEXT;
        SELECT @DuLieuTruocNoiQuy = (
            SELECT * FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuiDinh
        SET TieuDeNoiQuy = COALESCE(@TieuDeNoiQuy, TieuDeNoiQuy),
            NoiDung = COALESCE(@NoiDung, NoiDung),
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh,
            @DuLieuTruoc = @DuLieuTruocNoiQuy;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        UPDATE dbo.QuiDinh
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinh AS maQuyDinh;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyNoiQuy @ThaoTac = 'DANH_SACH', @MaQuyDinh = @MaQuyDinh;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham
    @ThaoTac        VARCHAR(20)  = 'DANH_SACH',
    @MaDieuKhoan    VARCHAR(6)    = NULL,
    @TenDieuKhoan   VARCHAR(255) = NULL,
    @HinhThucXuPhat VARCHAR(20)  = NULL,
    @MucPhat        DECIMAL(15,2) = NULL,
    @TrangThai      VARCHAR(20)  = NULL,
    @AdminId        VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDieuKhoan = NULLIF(TRIM(@MaDieuKhoan)), '');
    SET @TenDieuKhoan = NULLIF(TRIM(@TenDieuKhoan)), '');
    SET @HinhThucXuPhat = NULLIF(TRIM(@HinhThucXuPhat)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dk.MaDieuKhoan AS maDieuKhoan,
            dk.TenDieuKhoan AS tenDieuKhoan,
            dk.HinhThucXuPhat AS hinhThucXuPhat,
            dk.MucPhat AS mucPhat,
            dk.TrangThai AS trangThai,
            COUNT(bb.MaBBViPham) AS soBienBanApDung
        FROM dbo.DieuKhoanViPham AS dk
        LEFT JOIN dbo.BienBanViPham AS bb ON bb.MaDieuKhoan = dk.MaDieuKhoan
        WHERE (@MaDieuKhoan IS NULL OR dk.MaDieuKhoan = @MaDieuKhoan)
          AND (@TrangThai IS NULL OR dk.TrangThai = @TrangThai)
          AND (@TenDieuKhoan IS NULL OR dk.TenDieuKhoan LIKE '%' + @TenDieuKhoan + '%')
        GROUP BY dk.MaDieuKhoan, dk.TenDieuKhoan, dk.HinhThucXuPhat, dk.MucPhat, dk.TrangThai
        ORDER BY dk.MaDieuKhoan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @HinhThucXuPhat IS NOT NULL AND @HinhThucXuPhat NOT IN ('Nhắc nhở', 'Phạt tiền')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @MucPhat IS NOT NULL AND @MucPhat < 0
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDieuKhoan IS NULL OR @HinhThucXuPhat IS NULL)
            RAISE EXCEPTION %;

        IF @TenDieuKhoan IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DieuKhoanViPham
            WHERE TenDieuKhoan = @TenDieuKhoan
              AND (@MaDieuKhoan IS NULL OR MaDieuKhoan <> @MaDieuKhoan)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDieuKhoan INT;

        IF @HinhThucXuPhat = 'Phạt tiền' AND COALESCE(@MucPhat, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucXuPhat = 'Nhắc nhở' AND @MucPhat IS NULL
            SET @MucPhat = 0;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDieuKhoan IS NULL
            BEGIN
                SELECT @SoDieuKhoan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDieuKhoan, 3, 4))), 0) + 1
                FROM dbo.DieuKhoanViPham 
                WHERE MaDieuKhoan LIKE 'VP[0-9][0-9][0-9][0-9]';

                IF @SoDieuKhoan > 9999
                    RAISE EXCEPTION %;

                SET @MaDieuKhoan = CONCAT('VP', RIGHT(CONCAT('0000', @SoDieuKhoan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DieuKhoanViPham (
                MaDieuKhoan, TenDieuKhoan, HinhThucXuPhat, MucPhat, TrangThai
            )
            VALUES (
                @MaDieuKhoan, @TenDieuKhoan, @HinhThucXuPhat, COALESCE(@MucPhat, 0), COALESCE(@TrangThai, 'Hiệu lực')
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo điều khoản vi phạm',
                @DoiTuong = 'DieuKhoanViPham',
                @MaDoiTuong = @MaDieuKhoan,
                @NoiDung = @TenDieuKhoan;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DECLARE @HinhThucSau VARCHAR(20);
        DECLARE @MucPhatSau DECIMAL(15,2);

        SELECT
            @HinhThucSau = COALESCE(@HinhThucXuPhat, HinhThucXuPhat),
            @MucPhatSau = COALESCE(@MucPhat, MucPhat)
        FROM dbo.DieuKhoanViPham
        WHERE MaDieuKhoan = @MaDieuKhoan;

        IF @HinhThucSau = 'Phạt tiền' AND COALESCE(@MucPhatSau, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucSau = 'Nhắc nhở' AND @MucPhatSau IS NULL
            SET @MucPhatSau = 0;

        DECLARE @DuLieuTruocDieuKhoan TEXT;
        SELECT @DuLieuTruocDieuKhoan = (
            SELECT * FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DieuKhoanViPham
        SET TenDieuKhoan = COALESCE(@TenDieuKhoan, TenDieuKhoan),
            HinhThucXuPhat = @HinhThucSau,
            MucPhat = @MucPhatSau,
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan,
            @DuLieuTruoc = @DuLieuTruocDieuKhoan;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        UPDATE dbo.DieuKhoanViPham
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.BienBanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDieuKhoan AS maDieuKhoan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDieuKhoanViPham @ThaoTac = 'DANH_SACH', @MaDieuKhoan = @MaDieuKhoan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhThamSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhThamSo
    @ThaoTac    VARCHAR(20)  = 'DANH_SACH',
    @MaThamSo   VARCHAR(50)   = NULL,
    @NhomThamSo VARCHAR(50)  = NULL,
    @TenThamSo  VARCHAR(100) = NULL,
    @GiaTri     VARCHAR(255) = NULL,
    @KieuDuLieu VARCHAR(20)  = NULL,
    @DonViTinh  VARCHAR(30)  = NULL,
    @MoTa       TEXT = NULL,
    @AdminId    VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaThamSo = NULLIF(TRIM(@MaThamSo)), '');
    SET @NhomThamSo = NULLIF(TRIM(@NhomThamSo)), '');
    SET @TenThamSo = NULLIF(TRIM(@TenThamSo)), '');
    SET @GiaTri = NULLIF(TRIM(@GiaTri)), '');
    SET @KieuDuLieu = NULLIF(TRIM(@KieuDuLieu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            MaThamSo AS maThamSo,
            NhomThamSo AS nhomThamSo,
            TenThamSo AS tenThamSo,
            GiaTri AS giaTri,
            KieuDuLieu AS kieuDuLieu,
            DonViTinh AS donViTinh,
            MoTa AS moTa,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.ThamSoHeThong
        WHERE (@MaThamSo IS NULL OR MaThamSo = @MaThamSo)
          AND (@NhomThamSo IS NULL OR NhomThamSo = @NhomThamSo)
        ORDER BY NhomThamSo, MaThamSo;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT')
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO' AND (@MaThamSo IS NULL OR @NhomThamSo IS NULL OR @TenThamSo IS NULL OR @GiaTri IS NULL)
        THROW 51262, 'Vui lòng nhập đủ mã, nhóm, tên và giá trị tham số.', 1;

    IF @MaThamSo IS NULL
        RAISE EXCEPTION %;

    IF @KieuDuLieu IS NOT NULL AND @KieuDuLieu NOT IN ('Chuỗi', 'Số', 'Ngày', 'Boolean')
        RAISE EXCEPTION %;

    DECLARE @KieuDuLieuSau VARCHAR(20);
    DECLARE @GiaTriSau VARCHAR(255);

    IF @ThaoTac = 'TAO'
    BEGIN
        SET @KieuDuLieuSau = COALESCE(@KieuDuLieu, 'Chuỗi');
        SET @GiaTriSau = @GiaTri;
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        SELECT
            @KieuDuLieuSau = COALESCE(@KieuDuLieu, KieuDuLieu),
            @GiaTriSau = COALESCE(@GiaTri, GiaTri)
        FROM dbo.ThamSoHeThong
        WHERE MaThamSo = @MaThamSo;
    END;

    IF @KieuDuLieuSau = 'Số' AND (TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) IS NULL OR TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) < 0)
        RAISE EXCEPTION %;

    IF @MaThamSo = 'THOI_HAN_THANH_TOAN_COC_GIO'
       AND (TRY_CONVERT(INT, @GiaTriSau) IS NULL OR TRY_CONVERT(INT, @GiaTriSau) <= 0)
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        INSERT INTO dbo.ThamSoHeThong (
            MaThamSo, NhomThamSo, TenThamSo, GiaTri, KieuDuLieu, DonViTinh, MoTa, CapNhatBoi
        )
        VALUES (
            @MaThamSo, @NhomThamSo, @TenThamSo, @GiaTriSau, @KieuDuLieuSau, @DonViTinh, @MoTa, @AdminId
        );

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @NoiDung = @TenThamSo;
    END
    ELSE
    BEGIN
        DECLARE @DuLieuTruocThamSo TEXT;
        SELECT @DuLieuTruocThamSo = (
            SELECT * FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.ThamSoHeThong
        SET NhomThamSo = COALESCE(@NhomThamSo, NhomThamSo),
            TenThamSo = COALESCE(@TenThamSo, TenThamSo),
            GiaTri = @GiaTriSau,
            KieuDuLieu = @KieuDuLieuSau,
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            MoTa = COALESCE(@MoTa, MoTa),
            CapNhatLuc = CURRENT_TIMESTAMP,
            CapNhatBoi = @AdminId
        WHERE MaThamSo = @MaThamSo;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @DuLieuTruoc = @DuLieuTruocThamSo;
    END;

    EXEC dbo.SP_Admin_CauHinhThamSo @ThaoTac = 'DANH_SACH', @MaThamSo = @MaThamSo;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhSaoLuu
    @ChuKyFull        VARCHAR(20)  = NULL,
    @ChuKyIncremental VARCHAR(20)  = NULL,
    @ThuMucLuuTru     VARCHAR(500) = NULL,
    @AdminId          VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ChuKyFull = NULLIF(TRIM(@ChuKyFull)), '');
    SET @ChuKyIncremental = NULLIF(TRIM(@ChuKyIncremental)), '');
    SET @ThuMucLuuTru = NULLIF(TRIM(@ThuMucLuuTru)), '');

    IF @ChuKyFull IS NOT NULL AND @ChuKyFull NOT IN ('Hàng tuần', 'Hàng tháng')
        RAISE EXCEPTION %;

    IF @ChuKyIncremental IS NOT NULL AND @ChuKyIncremental NOT IN ('Hàng ngày', 'Hàng tuần')
        RAISE EXCEPTION %;

    IF @ThuMucLuuTru IS NOT NULL
    BEGIN
        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);
    END;

    IF @ChuKyFull IS NULL AND @ChuKyIncremental IS NULL AND @ThuMucLuuTru IS NULL
    BEGIN
        SELECT
            MaCauHinh AS maCauHinh,
            ChuKyFull AS chuKyFull,
            ChuKyIncremental AS chuKyIncremental,
            ThuMucLuuTru AS thuMucLuuTru,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;
        RETURN;
    END;

    DECLARE @DuLieuTruocSaoLuu TEXT;
    SELECT @DuLieuTruocSaoLuu = (
        SELECT * FROM dbo.CauHinhSaoLuu WHERE MaCauHinh = 1 FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    UPDATE dbo.CauHinhSaoLuu
    SET ChuKyFull = COALESCE(@ChuKyFull, ChuKyFull),
        ChuKyIncremental = COALESCE(@ChuKyIncremental, ChuKyIncremental),
        ThuMucLuuTru = COALESCE(@ThuMucLuuTru, ThuMucLuuTru),
        CapNhatLuc = CURRENT_TIMESTAMP,
        CapNhatBoi = @AdminId
    WHERE MaCauHinh = 1;

    EXEC dbo.SP_Admin_GhiNhatKy
        @AdminId = @AdminId,
        @HanhDong = 'Cấu hình sao lưu',
        @DoiTuong = 'CauHinhSaoLuu',
        @MaDoiTuong = '1',
        @DuLieuTruoc = @DuLieuTruocSaoLuu;

    SELECT
        MaCauHinh AS maCauHinh,
        ChuKyFull AS chuKyFull,
        ChuKyIncremental AS chuKyIncremental,
        ThuMucLuuTru AS thuMucLuuTru,
        CapNhatLuc AS capNhatLuc,
        CapNhatBoi AS capNhatBoi
    FROM dbo.CauHinhSaoLuu
    WHERE MaCauHinh = 1;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_SaoLuuThuCong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_SaoLuuThuCong
    @LoaiSaoLuu  VARCHAR(20)  = 'Full',
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    

    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');
    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');
    IF @LoaiSaoLuu IS NULL SET @LoaiSaoLuu = 'Full';

    DECLARE @LoaiSaoLuuChuan VARCHAR(20) = UPPER(@LoaiSaoLuu);
    IF @LoaiSaoLuuChuan = 'FULL'
        SET @LoaiSaoLuu = 'Full';
    ELSE IF @LoaiSaoLuuChuan IN ('INCREMENTAL', 'DIFFERENTIAL')
        SET @LoaiSaoLuu = 'Incremental';

    IF @LoaiSaoLuu NOT IN ('Full', 'Incremental')
        RAISE EXCEPTION %;

    IF @DuongDanFile IS NULL
    BEGIN
        DECLARE @ThuMucLuuTru VARCHAR(500);
        SELECT @ThuMucLuuTru = ThuMucLuuTru
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;

        IF @ThuMucLuuTru IS NULL
            RAISE EXCEPTION %;

        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);

        SET @DuongDanFile =
            @ThuMucLuuTru + '\' + DB_NAME() + '_' + @LoaiSaoLuu + '_' +
            CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112) + REPLACE(CONVERT(CHAR(8), CURRENT_TIMESTAMP, 108), ':', '') + '.bak';
    END;

    DECLARE @MaSaoLuu INT;
    DECLARE @LenhSaoLuu TEXT;

    INSERT INTO dbo.LichSuSaoLuu (
        LoaiSaoLuu, DuongDanFile, TrangThai, ThoiGianBatDau, MaNguoiDung
    )
    VALUES (
        @LoaiSaoLuu, @DuongDanFile, 'Đang chạy', CURRENT_TIMESTAMP, @AdminId
    );

    SET @MaSaoLuu = SCOPE_IDENTITY();
    SET @LenhSaoLuu =
        'BACKUP DATABASE ' + QUOTENAME(DB_NAME()) +
        ' TO DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') +
        ''' WITH ' +
        CASE WHEN @LoaiSaoLuu = 'Incremental' THEN 'DIFFERENTIAL, INIT' ELSE 'INIT' END +
        ';';

    BEGIN TRY
        EXEC(@LenhSaoLuu);

        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thành công',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = 'Sao lưu hoàn tất.'
        WHERE MaSaoLuu = @MaSaoLuu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Sao lưu thủ công',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thất bại',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = ERROR_MESSAGE()
        WHERE MaSaoLuu = @MaSaoLuu;

        THROW;
    END CATCH;

    SELECT
        MaSaoLuu AS maSaoLuu,
        LoaiSaoLuu AS loaiSaoLuu,
        DuongDanFile AS duongDanFile,
        TrangThai AS trangThai,
        ThoiGianBatDau AS thoiGianBatDau,
        ThoiGianKetThuc AS thoiGianKetThuc,
        ThongBao AS thongBao
    FROM dbo.LichSuSaoLuu
    WHERE MaSaoLuu = @MaSaoLuu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_DanhSachSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_DanhSachSaoLuu
    @SoDong     INT          = 100,
    @TrangThai  VARCHAR(20) = NULL,
    @LoaiSaoLuu VARCHAR(20) = NULL
AS
BEGIN
    

    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 100;

    SELECT TOP (@SoDong)
        ls.MaSaoLuu AS maSaoLuu,
        ls.LoaiSaoLuu AS loaiSaoLuu,
        ls.DuongDanFile AS duongDanFile,
        ls.DungLuongByte AS dungLuongByte,
        ls.TrangThai AS trangThai,
        ls.ThoiGianBatDau AS thoiGianBatDau,
        ls.ThoiGianKetThuc AS thoiGianKetThuc,
        ls.ThongBao AS thongBao,
        ls.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung
    FROM dbo.LichSuSaoLuu AS ls
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = ls.MaNguoiDung
    WHERE (@TrangThai IS NULL OR ls.TrangThai = @TrangThai)
      AND (@LoaiSaoLuu IS NULL OR ls.LoaiSaoLuu = @LoaiSaoLuu)
    ORDER BY ls.ThoiGianBatDau DESC, ls.MaSaoLuu DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_PhucHoiDuLieu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_PhucHoiDuLieu
    @MaSaoLuu    INT           = NULL,
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL,
    @ChiTaoLenh   BOOLEAN           = 1
AS
BEGIN
    

    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');

    IF @DuongDanFile IS NULL AND @MaSaoLuu IS NOT NULL
    BEGIN
        SELECT @DuongDanFile = DuongDanFile
        FROM dbo.LichSuSaoLuu
        WHERE MaSaoLuu = @MaSaoLuu
          AND TrangThai = 'Thành công';
    END;

    IF @DuongDanFile IS NULL
        RAISE EXCEPTION %;

    DECLARE @TenDatabase SYSNAME = DB_NAME();
    DECLARE @LenhSingleUser TEXT;
    DECLARE @LenhRestore TEXT;
    DECLARE @LenhMultiUser TEXT;
    DECLARE @LenhDayDu TEXT;

    SET @LenhSingleUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET SINGLE_USER WITH ROLLBACK IMMEDIATE;';
    SET @LenhRestore = 'USE [master]; RESTORE DATABASE ' + QUOTENAME(@TenDatabase) +
        ' FROM DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') + ''' WITH REPLACE;';
    SET @LenhMultiUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET MULTI_USER;';
    SET @LenhDayDu = @LenhSingleUser + CHAR(13) + CHAR(10) + @LenhRestore + CHAR(13) + CHAR(10) + @LenhMultiUser;

    IF @ChiTaoLenh = 1
    BEGIN
        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo lệnh phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;

        SELECT
            @TenDatabase AS tenDatabase,
            @DuongDanFile AS duongDanFile,
            @LenhDayDu AS lenhPhucHoi,
            CAST(1 AS BOOLEAN) AS chiTaoLenh;
        RETURN;
    END;

    BEGIN TRY
        EXEC(@LenhSingleUser);
        EXEC(@LenhRestore);
        EXEC(@LenhMultiUser);

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        BEGIN TRY
            EXEC(@LenhMultiUser);
        END TRY
        BEGIN CATCH
        END CATCH;

        THROW;
    END CATCH;

    SELECT
        @TenDatabase AS tenDatabase,
        @DuongDanFile AS duongDanFile,
        CAST(1 AS BOOLEAN) AS daPhucHoi;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_XemNhatKyHeThong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_XemNhatKyHeThong
    @TuNgay     TIMESTAMP  = NULL,
    @DenNgay    TIMESTAMP  = NULL,
    @AdminId    VARCHAR(6)    = NULL,
    @DoiTuong   VARCHAR(100) = NULL,
    @HanhDong   VARCHAR(100) = NULL,
    @TuKhoa     VARCHAR(100) = NULL,
    @SoDong     INT           = 200
AS
BEGIN
    

    SET @AdminId = NULLIF(TRIM(@AdminId)), '');
    SET @DoiTuong = NULLIF(TRIM(@DoiTuong)), '');
    SET @HanhDong = NULLIF(TRIM(@HanhDong)), '');
    SET @TuKhoa = NULLIF(TRIM(@TuKhoa)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 200;

    SELECT TOP (@SoDong)
        nk.MaNhatKy AS maNhatKy,
        nk.ThoiGian AS thoiGian,
        nk.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung,
        nk.VaiTro AS vaiTro,
        nk.ChucNang AS chucNang,
        nk.HanhDong AS hanhDong,
        nk.DoiTuong AS doiTuong,
        nk.MaDoiTuong AS maDoiTuong,
        nk.NoiDung AS noiDung,
        nk.DuLieuTruoc AS duLieuTruoc,
        nk.DuLieuSau AS duLieuSau
    FROM dbo.NhatKyHeThong AS nk
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nk.MaNguoiDung
    WHERE (@TuNgay IS NULL OR nk.ThoiGian >= @TuNgay)
      AND (@DenNgay IS NULL OR nk.ThoiGian < DATEADD(DAY, 1, @DenNgay))
      AND (@AdminId IS NULL OR nk.MaNguoiDung = @AdminId)
      AND (@DoiTuong IS NULL OR nk.DoiTuong = @DoiTuong)
      AND (@HanhDong IS NULL OR nk.HanhDong LIKE '%' + @HanhDong + '%')
      AND (
          @TuKhoa IS NULL
          OR nk.NoiDung LIKE '%' + @TuKhoa + '%'
          OR nk.MaDoiTuong LIKE '%' + @TuKhoa + '%'
          OR nk.HanhDong LIKE '%' + @TuKhoa + '%'
      )
    ORDER BY nk.ThoiGian DESC, nk.MaNhatKy DESC;
END; THEN (RIGHT(MaPhong, 2)::INT ELSE NULL END)), 0) + 1
            FROM dbo.Phong 
            WHERE MaChiNhanh = @MaChiNhanh
              AND MaPhong LIKE CONCAT('P', @SoChiNhanh, '[0-9][0-9]');

            IF @SoPhong > 99
                RAISE EXCEPTION %;

            SET @MaPhong = CONCAT('P', @SoChiNhanh, RIGHT(CONCAT('00', @SoPhong), 2));
        END;

        IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        INSERT INTO dbo.Phong (MaPhong, TenPhong, GioiTinhChoPhep, TinhTrang, MaChiNhanh, MaLoaiPhong)
        VALUES (@MaPhong, @TenPhong, @GioiTinhChoPhep, @TinhTrang, @MaChiNhanh, @MaLoaiPhong);

        IF @UrlImg IS NOT NULL
        BEGIN
            INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
            VALUES (@MaPhong, 1, @UrlImg);
        END;

        WHILE @Index <= @SoGiuong
        BEGIN
            SET @MaGiuong = CONCAT('G', RIGHT(CONCAT('00', @Index), 2));

            INSERT INTO dbo.Giuong (MaPhong, MaGiuong, SoGiuong, TinhTrang)
            VALUES (@MaPhong, @MaGiuong, @Index, 'Trống');

            SET @Index += 1;
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo phòng giường',
            @DoiTuong = 'Phong',
            @MaDoiTuong = @MaPhong,
            @NoiDung = @TenPhong;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        p.MaPhong AS maPhong,
        p.TenPhong AS tenPhong,
        p.GioiTinhChoPhep AS gioiTinhChoPhep,
        p.TinhTrang AS tinhTrangPhong,
        (SELECT TOP 1 hap.UrlImg FROM dbo.HinhAnhPhong AS hap WHERE hap.MaPhong = p.MaPhong ORDER BY hap.STTAnh) AS urlImgPhong,
        p.MaChiNhanh AS maChiNhanh,
        cn.TenChiNhanh AS tenChiNhanh,
        p.MaLoaiPhong AS maLoaiPhong,
        lp.TenLoaiPhong AS tenLoaiPhong,
        g.MaGiuong AS maGiuong,
        g.SoGiuong AS soGiuong,
        g.TinhTrang AS tinhTrangGiuong
    FROM dbo.Phong AS p
    INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    LEFT JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
    WHERE p.MaPhong = @MaPhong
    ORDER BY g.SoGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CapNhatTrangThaiPhongGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CapNhatTrangThaiPhongGiuong
    @LoaiDoiTuong VARCHAR(20),
    @MaPhong      VARCHAR(4),
    @MaGiuong     VARCHAR(3)   = NULL,
    @TrangThai    VARCHAR(20),
    @AdminId      VARCHAR(6)   = NULL
AS
BEGIN
    
    

    SET @LoaiDoiTuong = UPPER(NULLIF(TRIM(@LoaiDoiTuong)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');

    IF @LoaiDoiTuong NOT IN ('PHONG', 'GIUONG')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @LoaiDoiTuong = 'PHONG' AND @TrangThai NOT IN ('Trống', 'Đã đặt cọc', 'Còn chỗ', 'Đầy', 'Giữ chỗ', 'Bảo trì')
        RAISE EXCEPTION %;

    IF @LoaiDoiTuong = 'GIUONG' AND @TrangThai NOT IN ('Trống', 'Đã đặt cọc', 'Đang thuê')
        RAISE EXCEPTION %;

    IF @LoaiDoiTuong = 'GIUONG'
       AND (@MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
       ))
        RAISE EXCEPTION %;

    DECLARE @DuLieuTruoc TEXT;

    IF @LoaiDoiTuong = 'PHONG'
        SELECT @DuLieuTruoc = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );
    ELSE
        SELECT @DuLieuTruoc = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @LoaiDoiTuong = 'PHONG'
        BEGIN
            UPDATE dbo.Phong
            SET TinhTrang = @TrangThai
            WHERE MaPhong = @MaPhong;
        END
        ELSE
        BEGIN
            UPDATE dbo.Giuong
            SET TinhTrang = @TrangThai
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong;

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (
                    SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống'
                ) THEN 'Trống'
                WHEN NOT EXISTS (
                    SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống'
                ) THEN 'Đầy'
                WHEN EXISTS (
                    SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Đã đặt cọc'
                ) THEN 'Còn chỗ'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật trạng thái phòng/giường',
            @DoiTuong = @LoaiDoiTuong,
            @MaDoiTuong = @MaPhong,
            @NoiDung = @TrangThai,
            @DuLieuTruoc = @DuLieuTruoc;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT
        p.MaPhong AS maPhong,
        p.TenPhong AS tenPhong,
        p.TinhTrang AS tinhTrangPhong,
        g.MaGiuong AS maGiuong,
        g.SoGiuong AS soGiuong,
        g.TinhTrang AS tinhTrangGiuong
    FROM dbo.Phong AS p
    LEFT JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
    WHERE p.MaPhong = @MaPhong
      AND (@MaGiuong IS NULL OR g.MaGiuong = @MaGiuong)
    ORDER BY g.SoGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyPhong
    @ThaoTac         VARCHAR(20)  = 'DANH_SACH',
    @MaPhong         VARCHAR(4)    = NULL,
    @TenPhong        VARCHAR(100) = NULL,
    @GioiTinhChoPhep VARCHAR(20)  = NULL,
    @TinhTrang       VARCHAR(20)  = NULL,
    @UrlImg          VARCHAR(500)  = NULL,
    @MaChiNhanh      VARCHAR(6)    = NULL,
    @MaLoaiPhong     VARCHAR(6)    = NULL,
    @AdminId         VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @TenPhong = NULLIF(TRIM(@TenPhong)), '');
    SET @GioiTinhChoPhep = NULLIF(TRIM(@GioiTinhChoPhep)), '');
    SET @TinhTrang = NULLIF(TRIM(@TinhTrang)), '');
    SET @UrlImg = NULLIF(TRIM(@UrlImg)), '');
    SET @MaChiNhanh = NULLIF(TRIM(@MaChiNhanh)), '');
    SET @MaLoaiPhong = NULLIF(TRIM(@MaLoaiPhong)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            p.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            p.GioiTinhChoPhep AS gioiTinhChoPhep,
            p.TinhTrang AS tinhTrang,
            (SELECT TOP 1 hap.UrlImg FROM dbo.HinhAnhPhong AS hap WHERE hap.MaPhong = p.MaPhong ORDER BY hap.STTAnh) AS urlImg,
            p.MaChiNhanh AS maChiNhanh,
            cn.TenChiNhanh AS tenChiNhanh,
            p.MaLoaiPhong AS maLoaiPhong,
            lp.TenLoaiPhong AS tenLoaiPhong,
            COUNT(g.MaGiuong) AS soGiuong,
            SUM(CASE WHEN g.TinhTrang = 'Trống' THEN 1 ELSE 0 END) AS soGiuongTrong
        FROM dbo.Phong AS p
        INNER JOIN dbo.ChiNhanh AS cn ON cn.MaChiNhanh = p.MaChiNhanh
        INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
        LEFT JOIN dbo.Giuong AS g ON g.MaPhong = p.MaPhong
        WHERE (@MaPhong IS NULL OR p.MaPhong = @MaPhong)
          AND (@MaChiNhanh IS NULL OR p.MaChiNhanh = @MaChiNhanh)
          AND (@MaLoaiPhong IS NULL OR p.MaLoaiPhong = @MaLoaiPhong)
          AND (@TinhTrang IS NULL OR p.TinhTrang = @TinhTrang)
        GROUP BY p.MaPhong, p.TenPhong, p.GioiTinhChoPhep, p.TinhTrang,
                 p.MaChiNhanh, cn.TenChiNhanh, p.MaLoaiPhong, lp.TenLoaiPhong
        ORDER BY p.MaPhong;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO'
           AND (@TenPhong IS NULL OR @GioiTinhChoPhep IS NULL OR @MaChiNhanh IS NULL OR @MaLoaiPhong IS NULL)
            THROW 51102, 'Vui lòng nhập đầy đủ tên phòng, giới tính, chi nhánh và loại phòng.', 1;

        IF @GioiTinhChoPhep IS NOT NULL AND @GioiTinhChoPhep NOT IN ('Nam', 'Nữ', 'Không phân biệt')
            RAISE EXCEPTION %;

        IF @TinhTrang IS NOT NULL AND @TinhTrang NOT IN ('Trống', 'Đã đặt cọc', 'Còn chỗ', 'Đầy', 'Giữ chỗ', 'Bảo trì')
            RAISE EXCEPTION %;

        IF @MaChiNhanh IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.ChiNhanh WHERE MaChiNhanh = @MaChiNhanh)
            RAISE EXCEPTION %;

        IF @MaLoaiPhong IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.LoaiPhong WHERE MaLoaiPhong = @MaLoaiPhong)
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoPhongMoi INT;
        DECLARE @SoChiNhanhPhong INT = CASE WHEN (SUBSTRING(@MaChiNhanh, 3, 4) ~ '^[0-9]+);

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaPhong IS NULL
            BEGIN
                IF @SoChiNhanhPhong IS NULL OR @SoChiNhanhPhong NOT BETWEEN 1 AND 9
                    RAISE EXCEPTION %;

                SELECT @SoPhongMoi = COALESCE(MAX(TRY_CONVERT(INT, RIGHT(MaPhong, 2))), 0) + 1
                FROM dbo.Phong 
                WHERE MaChiNhanh = @MaChiNhanh
                  AND MaPhong LIKE CONCAT('P', @SoChiNhanhPhong, '[0-9][0-9]');

                IF @SoPhongMoi > 99
                    RAISE EXCEPTION %;

                SET @MaPhong = CONCAT('P', @SoChiNhanhPhong, RIGHT(CONCAT('00', @SoPhongMoi), 2));
            END;

            IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
                RAISE EXCEPTION %;

            INSERT INTO dbo.Phong (MaPhong, TenPhong, GioiTinhChoPhep, TinhTrang, MaChiNhanh, MaLoaiPhong)
            VALUES (@MaPhong, @TenPhong, @GioiTinhChoPhep, COALESCE(@TinhTrang, 'Trống'), @MaChiNhanh, @MaLoaiPhong);

            IF @UrlImg IS NOT NULL
            BEGIN
                INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
                VALUES (@MaPhong, 1, @UrlImg);
            END;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo phòng',
                @DoiTuong = 'Phong',
                @MaDoiTuong = @MaPhong,
                @NoiDung = @TenPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocPhong TEXT;
        SELECT @DuLieuTruocPhong = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.Phong
        SET TenPhong = COALESCE(@TenPhong, TenPhong),
            GioiTinhChoPhep = COALESCE(@GioiTinhChoPhep, GioiTinhChoPhep),
            TinhTrang = COALESCE(@TinhTrang, TinhTrang),
            MaChiNhanh = COALESCE(@MaChiNhanh, MaChiNhanh),
            MaLoaiPhong = COALESCE(@MaLoaiPhong, MaLoaiPhong)
        WHERE MaPhong = @MaPhong;

        IF @UrlImg IS NOT NULL
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.HinhAnhPhong WHERE MaPhong = @MaPhong AND STTAnh = 1)
                UPDATE dbo.HinhAnhPhong
                SET UrlImg = @UrlImg
                WHERE MaPhong = @MaPhong AND STTAnh = 1;
            ELSE
                INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
                VALUES (@MaPhong, 1, @UrlImg);
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật phòng',
            @DoiTuong = 'Phong',
            @MaDoiTuong = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocPhong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống')
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc AS ctdc
            INNER JOIN dbo.PhieuDatCoc AS pdc ON pdc.MaPhieuDatCoc = ctdc.MaPhieuDatCoc
            WHERE ctdc.MaPhong = @MaPhong
              AND pdc.TrangThaiCoc IN ('Hiệu lực', 'Đã lập HĐ')
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietDatCoc WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong)
           OR EXISTS (SELECT 1 FROM dbo.ChiTietXemPhong WHERE MaPhong = @MaPhong)
           OR EXISTS (SELECT 1 FROM dbo.PhieuGhiChiSo WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocPhongXoa TEXT;
        SELECT @DuLieuTruocPhongXoa = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        BEGIN TRY
            BEGIN TRANSACTION;

            DELETE FROM dbo.Giuong WHERE MaPhong = @MaPhong;
            DELETE FROM dbo.Phong WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa phòng',
                @DoiTuong = 'Phong',
                @MaDoiTuong = @MaPhong,
                @DuLieuTruoc = @DuLieuTruocPhongXoa;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyPhong @ThaoTac = 'DANH_SACH', @MaPhong = @MaPhong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyGiuong
    @ThaoTac   VARCHAR(20) = 'DANH_SACH',
    @MaPhong   VARCHAR(4)   = NULL,
    @MaGiuong  VARCHAR(3)   = NULL,
    @SoGiuong  INT          = NULL,
    @TinhTrang VARCHAR(20) = NULL,
    @UrlImg    VARCHAR(500) = NULL,
    @AdminId   VARCHAR(6)   = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    SET @TinhTrang = NULLIF(TRIM(@TinhTrang)), '');
    SET @UrlImg = NULLIF(TRIM(@UrlImg)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            g.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            g.MaGiuong AS maGiuong,
            g.SoGiuong AS soGiuong,
            g.TinhTrang AS tinhTrang,
            lp.SucChuaToiDa AS sucChuaToiDa,
            (
                SELECT COUNT(1)
                FROM dbo.TaiSan AS tsChung
                WHERE tsChung.MaPhong = g.MaPhong
                  AND tsChung.LoaiTaiSan = 'Chung'
            ) AS soTaiSanChung,
            CAST(0 AS INT) AS soTaiSanRieng
        FROM dbo.Giuong AS g
        INNER JOIN dbo.Phong AS p ON p.MaPhong = g.MaPhong
        INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
        WHERE (@MaPhong IS NULL OR g.MaPhong = @MaPhong)
          AND (@MaGiuong IS NULL OR g.MaGiuong = @MaGiuong)
          AND (@TinhTrang IS NULL OR g.TinhTrang = @TinhTrang)
        ORDER BY g.MaPhong, g.SoGiuong, g.MaGiuong;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @SoGiuong IS NULL
            RAISE EXCEPTION %;

        IF @SoGiuong IS NOT NULL AND @SoGiuong < 1
            RAISE EXCEPTION %;

        IF @TinhTrang IS NOT NULL AND @TinhTrang NOT IN ('Trống', 'Đã đặt cọc', 'Đang thuê')
            RAISE EXCEPTION %;
    END;

    DECLARE @SucChuaToiDa INT;
    SELECT @SucChuaToiDa = lp.SucChuaToiDa
    FROM dbo.Phong AS p
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    WHERE p.MaPhong = @MaPhong;

    IF @SoGiuong IS NOT NULL AND @SoGiuong > @SucChuaToiDa
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF (SELECT COUNT(*) FROM dbo.Giuong WHERE MaPhong = @MaPhong) >= @SucChuaToiDa
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND SoGiuong = @SoGiuong)
            RAISE EXCEPTION %;

        IF @MaGiuong IS NULL
        BEGIN
            DECLARE @SoMaGiuong INT;
            SELECT @SoMaGiuong = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaGiuong, 2, 2))), 0) + 1
            FROM dbo.Giuong 
            WHERE MaPhong = @MaPhong
              AND MaGiuong LIKE 'G[0-9][0-9]';

            IF @SoMaGiuong > 99
                RAISE EXCEPTION %;

            SET @MaGiuong = CONCAT('G', RIGHT(CONCAT('00', @SoMaGiuong), 2));
        END;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong)
            RAISE EXCEPTION %;

        BEGIN TRY
            BEGIN TRANSACTION;

            INSERT INTO dbo.Giuong (MaPhong, MaGiuong, SoGiuong, TinhTrang)
            VALUES (@MaPhong, @MaGiuong, @SoGiuong, COALESCE(@TinhTrang, 'Trống'));

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo giường',
                @DoiTuong = 'Giuong',
                @MaDoiTuong = @MaGiuong,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF @SoGiuong IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.Giuong
            WHERE MaPhong = @MaPhong
              AND SoGiuong = @SoGiuong
              AND MaGiuong <> @MaGiuong
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocGiuong TEXT;
        SELECT @DuLieuTruocGiuong = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.Giuong
        SET SoGiuong = COALESCE(@SoGiuong, SoGiuong),
            TinhTrang = COALESCE(@TinhTrang, TinhTrang)
        WHERE MaPhong = @MaPhong
          AND MaGiuong = @MaGiuong;

        UPDATE dbo.Phong
        SET TinhTrang = CASE
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong) THEN 'Trống'
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
            ELSE 'Còn chỗ'
        END
        WHERE MaPhong = @MaPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật giường',
            @DoiTuong = 'Giuong',
            @MaDoiTuong = @MaGiuong,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocGiuong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1 FROM dbo.Giuong
            WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong AND TinhTrang <> 'Trống'
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc AS ctdc
            INNER JOIN dbo.PhieuDatCoc AS pdc ON pdc.MaPhieuDatCoc = ctdc.MaPhieuDatCoc
            WHERE ctdc.MaPhong = @MaPhong
              AND ctdc.MaGiuong = @MaGiuong
              AND pdc.TrangThaiCoc IN ('Hiệu lực', 'Đã lập HĐ')
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietXemPhong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocGiuongXoa TEXT;
        SELECT @DuLieuTruocGiuongXoa = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        BEGIN TRY
            BEGIN TRANSACTION;

            DELETE FROM dbo.Giuong
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong;

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong) THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa giường',
                @DoiTuong = 'Giuong',
                @MaDoiTuong = @MaGiuong,
                @NoiDung = @MaPhong,
                @DuLieuTruoc = @DuLieuTruocGiuongXoa;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaGiuong AS maGiuong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyGiuong @ThaoTac = 'DANH_SACH', @MaPhong = @MaPhong, @MaGiuong = @MaGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyTaiSanPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyTaiSanPhong
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaPhong   VARCHAR(4)    = NULL,
    @MaTaiSan  VARCHAR(6)    = NULL,
    @TenTaiSan VARCHAR(100) = NULL,
    @SoLuong   INT           = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @LoaiTaiSan VARCHAR(20) = NULL,
    @MaGiuong   VARCHAR(3)   = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaTaiSan = NULLIF(TRIM(@MaTaiSan)), '');
    SET @TenTaiSan = NULLIF(TRIM(@TenTaiSan)), '');
    SET @LoaiTaiSan = NULLIF(TRIM(@LoaiTaiSan)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            ts.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            ts.MaTaiSan AS maTaiSan,
            ts.TenTaiSan AS tenTaiSan,
            ts.SoLuong AS soLuong,
            ts.DonGia AS donGia,
            ts.LoaiTaiSan AS loaiTaiSan,
            ts.MaGiuong AS maGiuong,
            g.SoGiuong AS soGiuong
        FROM dbo.TaiSan AS ts
        INNER JOIN dbo.Phong AS p ON p.MaPhong = ts.MaPhong
        LEFT JOIN dbo.Giuong AS g ON g.MaPhong = ts.MaPhong AND g.MaGiuong = ts.MaGiuong
        WHERE (@MaPhong IS NULL OR ts.MaPhong = @MaPhong)
          AND (@MaTaiSan IS NULL OR ts.MaTaiSan = @MaTaiSan)
          AND (@MaGiuong IS NULL OR ts.MaGiuong = @MaGiuong)
          AND (@LoaiTaiSan IS NULL OR ts.LoaiTaiSan = @LoaiTaiSan)
        ORDER BY ts.MaPhong, ts.LoaiTaiSan, ts.MaGiuong, ts.MaTaiSan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TenTaiSan IS NULL
            RAISE EXCEPTION %;

        IF @SoLuong IS NOT NULL AND @SoLuong <= 0
            RAISE EXCEPTION %;

        IF @DonGia IS NOT NULL AND @DonGia < 0
            RAISE EXCEPTION %;

        DECLARE @LoaiTaiSanSau VARCHAR(20);
        DECLARE @MaGiuongSau VARCHAR(3);

        IF @ThaoTac = 'TAO'
        BEGIN
            SET @LoaiTaiSanSau = COALESCE(@LoaiTaiSan, 'Chung');
            SET @MaGiuongSau = @MaGiuong;
        END
        ELSE
        BEGIN
            IF @MaTaiSan IS NULL OR NOT EXISTS (
                SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
            )
                RAISE EXCEPTION %;

            SELECT
                @LoaiTaiSanSau = COALESCE(@LoaiTaiSan, LoaiTaiSan),
                @MaGiuongSau = CASE
                    WHEN @LoaiTaiSan = 'Chung' THEN NULL
                    ELSE COALESCE(@MaGiuong, MaGiuong)
                END
            FROM dbo.TaiSan
            WHERE MaPhong = @MaPhong
              AND MaTaiSan = @MaTaiSan;
        END;

        IF @LoaiTaiSanSau NOT IN ('Chung', 'Riêng')
            RAISE EXCEPTION %;

        IF @LoaiTaiSanSau = 'Chung'
            SET @MaGiuongSau = NULL;

        IF @LoaiTaiSanSau = 'Riêng' AND @MaGiuongSau IS NULL
            RAISE EXCEPTION %;

        IF @MaGiuongSau IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuongSau
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoTaiSan INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaTaiSan IS NULL
            BEGIN
                SELECT @SoTaiSan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaTaiSan, 3, 4))), 0) + 1
                FROM dbo.TaiSan 
                WHERE MaPhong = @MaPhong
                  AND MaTaiSan LIKE 'TS[0-9][0-9][0-9][0-9]';

                IF @SoTaiSan > 9999
                    RAISE EXCEPTION %;

                SET @MaTaiSan = CONCAT('TS', RIGHT(CONCAT('0000', @SoTaiSan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.TaiSan (
                MaPhong, MaTaiSan, TenTaiSan, SoLuong, DonGia, LoaiTaiSan, MaGiuong
            )
            VALUES (
                @MaPhong, @MaTaiSan, @TenTaiSan, COALESCE(@SoLuong, 1),
                @DonGia, @LoaiTaiSanSau, @MaGiuongSau
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo tài sản phòng',
                @DoiTuong = 'TaiSan',
                @MaDoiTuong = @MaTaiSan,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocTaiSan TEXT;
        SELECT @DuLieuTruocTaiSan = (
            SELECT * FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.TaiSan
        SET TenTaiSan = COALESCE(@TenTaiSan, TenTaiSan),
            SoLuong = COALESCE(@SoLuong, SoLuong),
            DonGia = COALESCE(@DonGia, DonGia),
            LoaiTaiSan = @LoaiTaiSanSau,
            MaGiuong = @MaGiuongSau
        WHERE MaPhong = @MaPhong
          AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocTaiSan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietBanGiao WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.ChiTietHuHong WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.YeuCauSuaChua WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaTaiSan AS maTaiSan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyTaiSanPhong
        @ThaoTac = 'DANH_SACH',
        @MaPhong = @MaPhong,
        @MaTaiSan = @MaTaiSan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc
    @ThaoTac           VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinhHoanCoc VARCHAR(6)    = NULL,
    @TenQuyDinh        VARCHAR(255) = NULL,
    @TyLeHoanCoc       DECIMAL(5,2)  = NULL,
    @AdminId           VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinhHoanCoc = NULLIF(TRIM(@MaQuyDinhHoanCoc)), '');
    SET @TenQuyDinh = NULLIF(TRIM(@TenQuyDinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qh.MaQuyDinhHoanCoc AS maQuyDinhHoanCoc,
            qh.TenQuyDinh AS tenQuyDinh,
            qh.TyLeHoanCoc AS tyLeHoanCoc,
            COUNT(ds.MaQuyDinhHoanCoc) AS soLanApDung
        FROM dbo.QuyDinhHoanCoc AS qh
        LEFT JOIN dbo.DoiSoat AS ds ON ds.MaQuyDinhHoanCoc = qh.MaQuyDinhHoanCoc
        WHERE (@MaQuyDinhHoanCoc IS NULL OR qh.MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
        GROUP BY qh.MaQuyDinhHoanCoc, qh.TenQuyDinh, qh.TyLeHoanCoc
        ORDER BY qh.MaQuyDinhHoanCoc;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenQuyDinh IS NULL OR @TyLeHoanCoc IS NULL)
            RAISE EXCEPTION %;

        IF @TyLeHoanCoc IS NOT NULL AND (@TyLeHoanCoc < 0 OR @TyLeHoanCoc > 100)
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinh INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinhHoanCoc IS NULL
            BEGIN
                SELECT @SoQuyDinh = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinhHoanCoc, 3, 4))), 0) + 1
                FROM dbo.QuyDinhHoanCoc 
                WHERE MaQuyDinhHoanCoc LIKE 'QH[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinh > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinhHoanCoc = CONCAT('QH', RIGHT(CONCAT('0000', @SoQuyDinh), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuyDinhHoanCoc (MaQuyDinhHoanCoc, TenQuyDinh, TyLeHoanCoc)
            VALUES (@MaQuyDinhHoanCoc, @TenQuyDinh, @TyLeHoanCoc);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo quy định hoàn cọc',
                @DoiTuong = 'QuyDinhHoanCoc',
                @MaDoiTuong = @MaQuyDinhHoanCoc,
                @NoiDung = @TenQuyDinh;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocHoanCoc TEXT;
        SELECT @DuLieuTruocHoanCoc = (
            SELECT * FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuyDinhHoanCoc
        SET TenQuyDinh = COALESCE(@TenQuyDinh, TenQuyDinh),
            TyLeHoanCoc = COALESCE(@TyLeHoanCoc, TyLeHoanCoc)
        WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc,
            @DuLieuTruoc = @DuLieuTruocHoanCoc;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DoiSoat WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinhHoanCoc AS maQuyDinhHoanCoc;
        RETURN;
    END;

    EXEC dbo.SP_Admin_CauHinhQuyDinhHoanCoc @ThaoTac = 'DANH_SACH', @MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDichVu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDichVu
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaDichVu  VARCHAR(6)    = NULL,
    @TenDichVu VARCHAR(100) = NULL,
    @DonViTinh VARCHAR(20)   = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDichVu = NULLIF(TRIM(@MaDichVu)), '');
    SET @TenDichVu = NULLIF(TRIM(@TenDichVu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dv.MaDichVu AS maDichVu,
            dv.TenDichVu AS tenDichVu,
            dv.DonViTinh AS donViTinh,
            dv.DonGia AS donGia,
            COUNT(DISTINCT dvhd.MaChiTietDVHD) AS soHopDongSuDung,
            COUNT(cthd.MaChiTietHD) AS soDongHoaDon
        FROM dbo.DichVu AS dv
        LEFT JOIN dbo.DichVuHopDong AS dvhd ON dvhd.MaDichVu = dv.MaDichVu
        LEFT JOIN dbo.ChiTietHoaDon AS cthd ON cthd.MaChiTietDVHD = dvhd.MaChiTietDVHD
        WHERE (@MaDichVu IS NULL OR dv.MaDichVu = @MaDichVu)
          AND (@TenDichVu IS NULL OR dv.TenDichVu LIKE '%' + @TenDichVu + '%')
        GROUP BY dv.MaDichVu, dv.TenDichVu, dv.DonViTinh, dv.DonGia
        ORDER BY dv.MaDichVu;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDichVu IS NULL OR @DonViTinh IS NULL OR @DonGia IS NULL)
            THROW 51202, 'Vui lòng nhập tên dịch vụ, đơn vị tính và đơn giá.', 1;

        IF @DonGia IS NOT NULL AND @DonGia <= 0
            RAISE EXCEPTION %;

        IF @TenDichVu IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DichVu
            WHERE TenDichVu = @TenDichVu
              AND (@MaDichVu IS NULL OR MaDichVu <> @MaDichVu)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDichVu INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDichVu IS NULL
            BEGIN
                SELECT @SoDichVu = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDichVu, 3, 4))), 0) + 1
                FROM dbo.DichVu 
                WHERE MaDichVu LIKE 'DV[0-9][0-9][0-9][0-9]';

                IF @SoDichVu > 9999
                    RAISE EXCEPTION %;

                SET @MaDichVu = CONCAT('DV', RIGHT(CONCAT('0000', @SoDichVu), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DichVu (MaDichVu, TenDichVu, DonViTinh, DonGia)
            VALUES (@MaDichVu, @TenDichVu, @DonViTinh, @DonGia);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo dịch vụ',
                @DoiTuong = 'DichVu',
                @MaDoiTuong = @MaDichVu,
                @NoiDung = @TenDichVu;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocDichVu TEXT;
        SELECT @DuLieuTruocDichVu = (
            SELECT * FROM dbo.DichVu WHERE MaDichVu = @MaDichVu FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DichVu
        SET TenDichVu = COALESCE(@TenDichVu, TenDichVu),
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            DonGia = COALESCE(@DonGia, DonGia)
        WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu,
            @DuLieuTruoc = @DuLieuTruocDichVu;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DichVuHopDong WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DichVu WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDichVu AS maDichVu;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDichVu @ThaoTac = 'DANH_SACH', @MaDichVu = @MaDichVu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyNoiQuy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyNoiQuy
    @ThaoTac      VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinh    VARCHAR(6)    = NULL,
    @TieuDeNoiQuy VARCHAR(255) = NULL,
    @NoiDung      TEXT = NULL,
    @TrangThai    VARCHAR(20)  = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinh = NULLIF(TRIM(@MaQuyDinh)), '');
    SET @TieuDeNoiQuy = NULLIF(TRIM(@TieuDeNoiQuy)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qd.MaQuyDinh AS maQuyDinh,
            qd.TieuDeNoiQuy AS tieuDeNoiQuy,
            qd.NoiDung AS noiDung,
            qd.TrangThai AS trangThai
        FROM dbo.QuiDinh AS qd
        WHERE (@MaQuyDinh IS NULL OR qd.MaQuyDinh = @MaQuyDinh)
          AND (@TrangThai IS NULL OR qd.TrangThai = @TrangThai)
          AND (@TieuDeNoiQuy IS NULL OR qd.TieuDeNoiQuy LIKE '%' + @TieuDeNoiQuy + '%')
        ORDER BY qd.MaQuyDinh;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TieuDeNoiQuy IS NULL
            RAISE EXCEPTION %;

        IF @TieuDeNoiQuy IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.QuiDinh
            WHERE TieuDeNoiQuy = @TieuDeNoiQuy
              AND (@MaQuyDinh IS NULL OR MaQuyDinh <> @MaQuyDinh)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinhNoiQuy INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinh IS NULL
            BEGIN
                SELECT @SoQuyDinhNoiQuy = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinh, 3, 4))), 0) + 1
                FROM dbo.QuiDinh 
                WHERE MaQuyDinh LIKE 'QD[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinhNoiQuy > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinh = CONCAT('QD', RIGHT(CONCAT('0000', @SoQuyDinhNoiQuy), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuiDinh (MaQuyDinh, TieuDeNoiQuy, NoiDung, TrangThai)
            VALUES (@MaQuyDinh, @TieuDeNoiQuy, @NoiDung, COALESCE(@TrangThai, 'Hiệu lực'));

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo nội quy',
                @DoiTuong = 'QuiDinh',
                @MaDoiTuong = @MaQuyDinh,
                @NoiDung = @TieuDeNoiQuy;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocNoiQuy TEXT;
        SELECT @DuLieuTruocNoiQuy = (
            SELECT * FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuiDinh
        SET TieuDeNoiQuy = COALESCE(@TieuDeNoiQuy, TieuDeNoiQuy),
            NoiDung = COALESCE(@NoiDung, NoiDung),
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh,
            @DuLieuTruoc = @DuLieuTruocNoiQuy;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        UPDATE dbo.QuiDinh
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinh AS maQuyDinh;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyNoiQuy @ThaoTac = 'DANH_SACH', @MaQuyDinh = @MaQuyDinh;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham
    @ThaoTac        VARCHAR(20)  = 'DANH_SACH',
    @MaDieuKhoan    VARCHAR(6)    = NULL,
    @TenDieuKhoan   VARCHAR(255) = NULL,
    @HinhThucXuPhat VARCHAR(20)  = NULL,
    @MucPhat        DECIMAL(15,2) = NULL,
    @TrangThai      VARCHAR(20)  = NULL,
    @AdminId        VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDieuKhoan = NULLIF(TRIM(@MaDieuKhoan)), '');
    SET @TenDieuKhoan = NULLIF(TRIM(@TenDieuKhoan)), '');
    SET @HinhThucXuPhat = NULLIF(TRIM(@HinhThucXuPhat)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dk.MaDieuKhoan AS maDieuKhoan,
            dk.TenDieuKhoan AS tenDieuKhoan,
            dk.HinhThucXuPhat AS hinhThucXuPhat,
            dk.MucPhat AS mucPhat,
            dk.TrangThai AS trangThai,
            COUNT(bb.MaBBViPham) AS soBienBanApDung
        FROM dbo.DieuKhoanViPham AS dk
        LEFT JOIN dbo.BienBanViPham AS bb ON bb.MaDieuKhoan = dk.MaDieuKhoan
        WHERE (@MaDieuKhoan IS NULL OR dk.MaDieuKhoan = @MaDieuKhoan)
          AND (@TrangThai IS NULL OR dk.TrangThai = @TrangThai)
          AND (@TenDieuKhoan IS NULL OR dk.TenDieuKhoan LIKE '%' + @TenDieuKhoan + '%')
        GROUP BY dk.MaDieuKhoan, dk.TenDieuKhoan, dk.HinhThucXuPhat, dk.MucPhat, dk.TrangThai
        ORDER BY dk.MaDieuKhoan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @HinhThucXuPhat IS NOT NULL AND @HinhThucXuPhat NOT IN ('Nhắc nhở', 'Phạt tiền')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @MucPhat IS NOT NULL AND @MucPhat < 0
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDieuKhoan IS NULL OR @HinhThucXuPhat IS NULL)
            RAISE EXCEPTION %;

        IF @TenDieuKhoan IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DieuKhoanViPham
            WHERE TenDieuKhoan = @TenDieuKhoan
              AND (@MaDieuKhoan IS NULL OR MaDieuKhoan <> @MaDieuKhoan)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDieuKhoan INT;

        IF @HinhThucXuPhat = 'Phạt tiền' AND COALESCE(@MucPhat, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucXuPhat = 'Nhắc nhở' AND @MucPhat IS NULL
            SET @MucPhat = 0;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDieuKhoan IS NULL
            BEGIN
                SELECT @SoDieuKhoan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDieuKhoan, 3, 4))), 0) + 1
                FROM dbo.DieuKhoanViPham 
                WHERE MaDieuKhoan LIKE 'VP[0-9][0-9][0-9][0-9]';

                IF @SoDieuKhoan > 9999
                    RAISE EXCEPTION %;

                SET @MaDieuKhoan = CONCAT('VP', RIGHT(CONCAT('0000', @SoDieuKhoan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DieuKhoanViPham (
                MaDieuKhoan, TenDieuKhoan, HinhThucXuPhat, MucPhat, TrangThai
            )
            VALUES (
                @MaDieuKhoan, @TenDieuKhoan, @HinhThucXuPhat, COALESCE(@MucPhat, 0), COALESCE(@TrangThai, 'Hiệu lực')
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo điều khoản vi phạm',
                @DoiTuong = 'DieuKhoanViPham',
                @MaDoiTuong = @MaDieuKhoan,
                @NoiDung = @TenDieuKhoan;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DECLARE @HinhThucSau VARCHAR(20);
        DECLARE @MucPhatSau DECIMAL(15,2);

        SELECT
            @HinhThucSau = COALESCE(@HinhThucXuPhat, HinhThucXuPhat),
            @MucPhatSau = COALESCE(@MucPhat, MucPhat)
        FROM dbo.DieuKhoanViPham
        WHERE MaDieuKhoan = @MaDieuKhoan;

        IF @HinhThucSau = 'Phạt tiền' AND COALESCE(@MucPhatSau, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucSau = 'Nhắc nhở' AND @MucPhatSau IS NULL
            SET @MucPhatSau = 0;

        DECLARE @DuLieuTruocDieuKhoan TEXT;
        SELECT @DuLieuTruocDieuKhoan = (
            SELECT * FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DieuKhoanViPham
        SET TenDieuKhoan = COALESCE(@TenDieuKhoan, TenDieuKhoan),
            HinhThucXuPhat = @HinhThucSau,
            MucPhat = @MucPhatSau,
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan,
            @DuLieuTruoc = @DuLieuTruocDieuKhoan;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        UPDATE dbo.DieuKhoanViPham
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.BienBanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDieuKhoan AS maDieuKhoan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDieuKhoanViPham @ThaoTac = 'DANH_SACH', @MaDieuKhoan = @MaDieuKhoan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhThamSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhThamSo
    @ThaoTac    VARCHAR(20)  = 'DANH_SACH',
    @MaThamSo   VARCHAR(50)   = NULL,
    @NhomThamSo VARCHAR(50)  = NULL,
    @TenThamSo  VARCHAR(100) = NULL,
    @GiaTri     VARCHAR(255) = NULL,
    @KieuDuLieu VARCHAR(20)  = NULL,
    @DonViTinh  VARCHAR(30)  = NULL,
    @MoTa       TEXT = NULL,
    @AdminId    VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaThamSo = NULLIF(TRIM(@MaThamSo)), '');
    SET @NhomThamSo = NULLIF(TRIM(@NhomThamSo)), '');
    SET @TenThamSo = NULLIF(TRIM(@TenThamSo)), '');
    SET @GiaTri = NULLIF(TRIM(@GiaTri)), '');
    SET @KieuDuLieu = NULLIF(TRIM(@KieuDuLieu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            MaThamSo AS maThamSo,
            NhomThamSo AS nhomThamSo,
            TenThamSo AS tenThamSo,
            GiaTri AS giaTri,
            KieuDuLieu AS kieuDuLieu,
            DonViTinh AS donViTinh,
            MoTa AS moTa,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.ThamSoHeThong
        WHERE (@MaThamSo IS NULL OR MaThamSo = @MaThamSo)
          AND (@NhomThamSo IS NULL OR NhomThamSo = @NhomThamSo)
        ORDER BY NhomThamSo, MaThamSo;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT')
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO' AND (@MaThamSo IS NULL OR @NhomThamSo IS NULL OR @TenThamSo IS NULL OR @GiaTri IS NULL)
        THROW 51262, 'Vui lòng nhập đủ mã, nhóm, tên và giá trị tham số.', 1;

    IF @MaThamSo IS NULL
        RAISE EXCEPTION %;

    IF @KieuDuLieu IS NOT NULL AND @KieuDuLieu NOT IN ('Chuỗi', 'Số', 'Ngày', 'Boolean')
        RAISE EXCEPTION %;

    DECLARE @KieuDuLieuSau VARCHAR(20);
    DECLARE @GiaTriSau VARCHAR(255);

    IF @ThaoTac = 'TAO'
    BEGIN
        SET @KieuDuLieuSau = COALESCE(@KieuDuLieu, 'Chuỗi');
        SET @GiaTriSau = @GiaTri;
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        SELECT
            @KieuDuLieuSau = COALESCE(@KieuDuLieu, KieuDuLieu),
            @GiaTriSau = COALESCE(@GiaTri, GiaTri)
        FROM dbo.ThamSoHeThong
        WHERE MaThamSo = @MaThamSo;
    END;

    IF @KieuDuLieuSau = 'Số' AND (TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) IS NULL OR TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) < 0)
        RAISE EXCEPTION %;

    IF @MaThamSo = 'THOI_HAN_THANH_TOAN_COC_GIO'
       AND (TRY_CONVERT(INT, @GiaTriSau) IS NULL OR TRY_CONVERT(INT, @GiaTriSau) <= 0)
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        INSERT INTO dbo.ThamSoHeThong (
            MaThamSo, NhomThamSo, TenThamSo, GiaTri, KieuDuLieu, DonViTinh, MoTa, CapNhatBoi
        )
        VALUES (
            @MaThamSo, @NhomThamSo, @TenThamSo, @GiaTriSau, @KieuDuLieuSau, @DonViTinh, @MoTa, @AdminId
        );

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @NoiDung = @TenThamSo;
    END
    ELSE
    BEGIN
        DECLARE @DuLieuTruocThamSo TEXT;
        SELECT @DuLieuTruocThamSo = (
            SELECT * FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.ThamSoHeThong
        SET NhomThamSo = COALESCE(@NhomThamSo, NhomThamSo),
            TenThamSo = COALESCE(@TenThamSo, TenThamSo),
            GiaTri = @GiaTriSau,
            KieuDuLieu = @KieuDuLieuSau,
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            MoTa = COALESCE(@MoTa, MoTa),
            CapNhatLuc = CURRENT_TIMESTAMP,
            CapNhatBoi = @AdminId
        WHERE MaThamSo = @MaThamSo;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @DuLieuTruoc = @DuLieuTruocThamSo;
    END;

    EXEC dbo.SP_Admin_CauHinhThamSo @ThaoTac = 'DANH_SACH', @MaThamSo = @MaThamSo;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhSaoLuu
    @ChuKyFull        VARCHAR(20)  = NULL,
    @ChuKyIncremental VARCHAR(20)  = NULL,
    @ThuMucLuuTru     VARCHAR(500) = NULL,
    @AdminId          VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ChuKyFull = NULLIF(TRIM(@ChuKyFull)), '');
    SET @ChuKyIncremental = NULLIF(TRIM(@ChuKyIncremental)), '');
    SET @ThuMucLuuTru = NULLIF(TRIM(@ThuMucLuuTru)), '');

    IF @ChuKyFull IS NOT NULL AND @ChuKyFull NOT IN ('Hàng tuần', 'Hàng tháng')
        RAISE EXCEPTION %;

    IF @ChuKyIncremental IS NOT NULL AND @ChuKyIncremental NOT IN ('Hàng ngày', 'Hàng tuần')
        RAISE EXCEPTION %;

    IF @ThuMucLuuTru IS NOT NULL
    BEGIN
        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);
    END;

    IF @ChuKyFull IS NULL AND @ChuKyIncremental IS NULL AND @ThuMucLuuTru IS NULL
    BEGIN
        SELECT
            MaCauHinh AS maCauHinh,
            ChuKyFull AS chuKyFull,
            ChuKyIncremental AS chuKyIncremental,
            ThuMucLuuTru AS thuMucLuuTru,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;
        RETURN;
    END;

    DECLARE @DuLieuTruocSaoLuu TEXT;
    SELECT @DuLieuTruocSaoLuu = (
        SELECT * FROM dbo.CauHinhSaoLuu WHERE MaCauHinh = 1 FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    UPDATE dbo.CauHinhSaoLuu
    SET ChuKyFull = COALESCE(@ChuKyFull, ChuKyFull),
        ChuKyIncremental = COALESCE(@ChuKyIncremental, ChuKyIncremental),
        ThuMucLuuTru = COALESCE(@ThuMucLuuTru, ThuMucLuuTru),
        CapNhatLuc = CURRENT_TIMESTAMP,
        CapNhatBoi = @AdminId
    WHERE MaCauHinh = 1;

    EXEC dbo.SP_Admin_GhiNhatKy
        @AdminId = @AdminId,
        @HanhDong = 'Cấu hình sao lưu',
        @DoiTuong = 'CauHinhSaoLuu',
        @MaDoiTuong = '1',
        @DuLieuTruoc = @DuLieuTruocSaoLuu;

    SELECT
        MaCauHinh AS maCauHinh,
        ChuKyFull AS chuKyFull,
        ChuKyIncremental AS chuKyIncremental,
        ThuMucLuuTru AS thuMucLuuTru,
        CapNhatLuc AS capNhatLuc,
        CapNhatBoi AS capNhatBoi
    FROM dbo.CauHinhSaoLuu
    WHERE MaCauHinh = 1;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_SaoLuuThuCong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_SaoLuuThuCong
    @LoaiSaoLuu  VARCHAR(20)  = 'Full',
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    

    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');
    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');
    IF @LoaiSaoLuu IS NULL SET @LoaiSaoLuu = 'Full';

    DECLARE @LoaiSaoLuuChuan VARCHAR(20) = UPPER(@LoaiSaoLuu);
    IF @LoaiSaoLuuChuan = 'FULL'
        SET @LoaiSaoLuu = 'Full';
    ELSE IF @LoaiSaoLuuChuan IN ('INCREMENTAL', 'DIFFERENTIAL')
        SET @LoaiSaoLuu = 'Incremental';

    IF @LoaiSaoLuu NOT IN ('Full', 'Incremental')
        RAISE EXCEPTION %;

    IF @DuongDanFile IS NULL
    BEGIN
        DECLARE @ThuMucLuuTru VARCHAR(500);
        SELECT @ThuMucLuuTru = ThuMucLuuTru
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;

        IF @ThuMucLuuTru IS NULL
            RAISE EXCEPTION %;

        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);

        SET @DuongDanFile =
            @ThuMucLuuTru + '\' + DB_NAME() + '_' + @LoaiSaoLuu + '_' +
            CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112) + REPLACE(CONVERT(CHAR(8), CURRENT_TIMESTAMP, 108), ':', '') + '.bak';
    END;

    DECLARE @MaSaoLuu INT;
    DECLARE @LenhSaoLuu TEXT;

    INSERT INTO dbo.LichSuSaoLuu (
        LoaiSaoLuu, DuongDanFile, TrangThai, ThoiGianBatDau, MaNguoiDung
    )
    VALUES (
        @LoaiSaoLuu, @DuongDanFile, 'Đang chạy', CURRENT_TIMESTAMP, @AdminId
    );

    SET @MaSaoLuu = SCOPE_IDENTITY();
    SET @LenhSaoLuu =
        'BACKUP DATABASE ' + QUOTENAME(DB_NAME()) +
        ' TO DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') +
        ''' WITH ' +
        CASE WHEN @LoaiSaoLuu = 'Incremental' THEN 'DIFFERENTIAL, INIT' ELSE 'INIT' END +
        ';';

    BEGIN TRY
        EXEC(@LenhSaoLuu);

        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thành công',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = 'Sao lưu hoàn tất.'
        WHERE MaSaoLuu = @MaSaoLuu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Sao lưu thủ công',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thất bại',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = ERROR_MESSAGE()
        WHERE MaSaoLuu = @MaSaoLuu;

        THROW;
    END CATCH;

    SELECT
        MaSaoLuu AS maSaoLuu,
        LoaiSaoLuu AS loaiSaoLuu,
        DuongDanFile AS duongDanFile,
        TrangThai AS trangThai,
        ThoiGianBatDau AS thoiGianBatDau,
        ThoiGianKetThuc AS thoiGianKetThuc,
        ThongBao AS thongBao
    FROM dbo.LichSuSaoLuu
    WHERE MaSaoLuu = @MaSaoLuu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_DanhSachSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_DanhSachSaoLuu
    @SoDong     INT          = 100,
    @TrangThai  VARCHAR(20) = NULL,
    @LoaiSaoLuu VARCHAR(20) = NULL
AS
BEGIN
    

    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 100;

    SELECT TOP (@SoDong)
        ls.MaSaoLuu AS maSaoLuu,
        ls.LoaiSaoLuu AS loaiSaoLuu,
        ls.DuongDanFile AS duongDanFile,
        ls.DungLuongByte AS dungLuongByte,
        ls.TrangThai AS trangThai,
        ls.ThoiGianBatDau AS thoiGianBatDau,
        ls.ThoiGianKetThuc AS thoiGianKetThuc,
        ls.ThongBao AS thongBao,
        ls.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung
    FROM dbo.LichSuSaoLuu AS ls
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = ls.MaNguoiDung
    WHERE (@TrangThai IS NULL OR ls.TrangThai = @TrangThai)
      AND (@LoaiSaoLuu IS NULL OR ls.LoaiSaoLuu = @LoaiSaoLuu)
    ORDER BY ls.ThoiGianBatDau DESC, ls.MaSaoLuu DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_PhucHoiDuLieu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_PhucHoiDuLieu
    @MaSaoLuu    INT           = NULL,
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL,
    @ChiTaoLenh   BOOLEAN           = 1
AS
BEGIN
    

    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');

    IF @DuongDanFile IS NULL AND @MaSaoLuu IS NOT NULL
    BEGIN
        SELECT @DuongDanFile = DuongDanFile
        FROM dbo.LichSuSaoLuu
        WHERE MaSaoLuu = @MaSaoLuu
          AND TrangThai = 'Thành công';
    END;

    IF @DuongDanFile IS NULL
        RAISE EXCEPTION %;

    DECLARE @TenDatabase SYSNAME = DB_NAME();
    DECLARE @LenhSingleUser TEXT;
    DECLARE @LenhRestore TEXT;
    DECLARE @LenhMultiUser TEXT;
    DECLARE @LenhDayDu TEXT;

    SET @LenhSingleUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET SINGLE_USER WITH ROLLBACK IMMEDIATE;';
    SET @LenhRestore = 'USE [master]; RESTORE DATABASE ' + QUOTENAME(@TenDatabase) +
        ' FROM DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') + ''' WITH REPLACE;';
    SET @LenhMultiUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET MULTI_USER;';
    SET @LenhDayDu = @LenhSingleUser + CHAR(13) + CHAR(10) + @LenhRestore + CHAR(13) + CHAR(10) + @LenhMultiUser;

    IF @ChiTaoLenh = 1
    BEGIN
        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo lệnh phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;

        SELECT
            @TenDatabase AS tenDatabase,
            @DuongDanFile AS duongDanFile,
            @LenhDayDu AS lenhPhucHoi,
            CAST(1 AS BOOLEAN) AS chiTaoLenh;
        RETURN;
    END;

    BEGIN TRY
        EXEC(@LenhSingleUser);
        EXEC(@LenhRestore);
        EXEC(@LenhMultiUser);

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        BEGIN TRY
            EXEC(@LenhMultiUser);
        END TRY
        BEGIN CATCH
        END CATCH;

        THROW;
    END CATCH;

    SELECT
        @TenDatabase AS tenDatabase,
        @DuongDanFile AS duongDanFile,
        CAST(1 AS BOOLEAN) AS daPhucHoi;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_XemNhatKyHeThong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_XemNhatKyHeThong
    @TuNgay     TIMESTAMP  = NULL,
    @DenNgay    TIMESTAMP  = NULL,
    @AdminId    VARCHAR(6)    = NULL,
    @DoiTuong   VARCHAR(100) = NULL,
    @HanhDong   VARCHAR(100) = NULL,
    @TuKhoa     VARCHAR(100) = NULL,
    @SoDong     INT           = 200
AS
BEGIN
    

    SET @AdminId = NULLIF(TRIM(@AdminId)), '');
    SET @DoiTuong = NULLIF(TRIM(@DoiTuong)), '');
    SET @HanhDong = NULLIF(TRIM(@HanhDong)), '');
    SET @TuKhoa = NULLIF(TRIM(@TuKhoa)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 200;

    SELECT TOP (@SoDong)
        nk.MaNhatKy AS maNhatKy,
        nk.ThoiGian AS thoiGian,
        nk.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung,
        nk.VaiTro AS vaiTro,
        nk.ChucNang AS chucNang,
        nk.HanhDong AS hanhDong,
        nk.DoiTuong AS doiTuong,
        nk.MaDoiTuong AS maDoiTuong,
        nk.NoiDung AS noiDung,
        nk.DuLieuTruoc AS duLieuTruoc,
        nk.DuLieuSau AS duLieuSau
    FROM dbo.NhatKyHeThong AS nk
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nk.MaNguoiDung
    WHERE (@TuNgay IS NULL OR nk.ThoiGian >= @TuNgay)
      AND (@DenNgay IS NULL OR nk.ThoiGian < DATEADD(DAY, 1, @DenNgay))
      AND (@AdminId IS NULL OR nk.MaNguoiDung = @AdminId)
      AND (@DoiTuong IS NULL OR nk.DoiTuong = @DoiTuong)
      AND (@HanhDong IS NULL OR nk.HanhDong LIKE '%' + @HanhDong + '%')
      AND (
          @TuKhoa IS NULL
          OR nk.NoiDung LIKE '%' + @TuKhoa + '%'
          OR nk.MaDoiTuong LIKE '%' + @TuKhoa + '%'
          OR nk.HanhDong LIKE '%' + @TuKhoa + '%'
      )
    ORDER BY nk.ThoiGian DESC, nk.MaNhatKy DESC;
END; THEN (SUBSTRING(@MaChiNhanh, 3, 4)::INT ELSE NULL END);

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaPhong IS NULL
            BEGIN
                IF @SoChiNhanhPhong IS NULL OR @SoChiNhanhPhong NOT BETWEEN 1 AND 9
                    RAISE EXCEPTION %;

                SELECT @SoPhongMoi = COALESCE(MAX(CASE WHEN (RIGHT(MaPhong, 2) ~ '^[0-9]+)), 0) + 1
                FROM dbo.Phong 
                WHERE MaChiNhanh = @MaChiNhanh
                  AND MaPhong LIKE CONCAT('P', @SoChiNhanhPhong, '[0-9][0-9]');

                IF @SoPhongMoi > 99
                    RAISE EXCEPTION %;

                SET @MaPhong = CONCAT('P', @SoChiNhanhPhong, RIGHT(CONCAT('00', @SoPhongMoi), 2));
            END;

            IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
                RAISE EXCEPTION %;

            INSERT INTO dbo.Phong (MaPhong, TenPhong, GioiTinhChoPhep, TinhTrang, MaChiNhanh, MaLoaiPhong)
            VALUES (@MaPhong, @TenPhong, @GioiTinhChoPhep, COALESCE(@TinhTrang, 'Trống'), @MaChiNhanh, @MaLoaiPhong);

            IF @UrlImg IS NOT NULL
            BEGIN
                INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
                VALUES (@MaPhong, 1, @UrlImg);
            END;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo phòng',
                @DoiTuong = 'Phong',
                @MaDoiTuong = @MaPhong,
                @NoiDung = @TenPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocPhong TEXT;
        SELECT @DuLieuTruocPhong = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.Phong
        SET TenPhong = COALESCE(@TenPhong, TenPhong),
            GioiTinhChoPhep = COALESCE(@GioiTinhChoPhep, GioiTinhChoPhep),
            TinhTrang = COALESCE(@TinhTrang, TinhTrang),
            MaChiNhanh = COALESCE(@MaChiNhanh, MaChiNhanh),
            MaLoaiPhong = COALESCE(@MaLoaiPhong, MaLoaiPhong)
        WHERE MaPhong = @MaPhong;

        IF @UrlImg IS NOT NULL
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.HinhAnhPhong WHERE MaPhong = @MaPhong AND STTAnh = 1)
                UPDATE dbo.HinhAnhPhong
                SET UrlImg = @UrlImg
                WHERE MaPhong = @MaPhong AND STTAnh = 1;
            ELSE
                INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
                VALUES (@MaPhong, 1, @UrlImg);
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật phòng',
            @DoiTuong = 'Phong',
            @MaDoiTuong = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocPhong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống')
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc AS ctdc
            INNER JOIN dbo.PhieuDatCoc AS pdc ON pdc.MaPhieuDatCoc = ctdc.MaPhieuDatCoc
            WHERE ctdc.MaPhong = @MaPhong
              AND pdc.TrangThaiCoc IN ('Hiệu lực', 'Đã lập HĐ')
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietDatCoc WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong)
           OR EXISTS (SELECT 1 FROM dbo.ChiTietXemPhong WHERE MaPhong = @MaPhong)
           OR EXISTS (SELECT 1 FROM dbo.PhieuGhiChiSo WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocPhongXoa TEXT;
        SELECT @DuLieuTruocPhongXoa = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        BEGIN TRY
            BEGIN TRANSACTION;

            DELETE FROM dbo.Giuong WHERE MaPhong = @MaPhong;
            DELETE FROM dbo.Phong WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa phòng',
                @DoiTuong = 'Phong',
                @MaDoiTuong = @MaPhong,
                @DuLieuTruoc = @DuLieuTruocPhongXoa;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyPhong @ThaoTac = 'DANH_SACH', @MaPhong = @MaPhong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyGiuong
    @ThaoTac   VARCHAR(20) = 'DANH_SACH',
    @MaPhong   VARCHAR(4)   = NULL,
    @MaGiuong  VARCHAR(3)   = NULL,
    @SoGiuong  INT          = NULL,
    @TinhTrang VARCHAR(20) = NULL,
    @UrlImg    VARCHAR(500) = NULL,
    @AdminId   VARCHAR(6)   = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    SET @TinhTrang = NULLIF(TRIM(@TinhTrang)), '');
    SET @UrlImg = NULLIF(TRIM(@UrlImg)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            g.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            g.MaGiuong AS maGiuong,
            g.SoGiuong AS soGiuong,
            g.TinhTrang AS tinhTrang,
            lp.SucChuaToiDa AS sucChuaToiDa,
            (
                SELECT COUNT(1)
                FROM dbo.TaiSan AS tsChung
                WHERE tsChung.MaPhong = g.MaPhong
                  AND tsChung.LoaiTaiSan = 'Chung'
            ) AS soTaiSanChung,
            CAST(0 AS INT) AS soTaiSanRieng
        FROM dbo.Giuong AS g
        INNER JOIN dbo.Phong AS p ON p.MaPhong = g.MaPhong
        INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
        WHERE (@MaPhong IS NULL OR g.MaPhong = @MaPhong)
          AND (@MaGiuong IS NULL OR g.MaGiuong = @MaGiuong)
          AND (@TinhTrang IS NULL OR g.TinhTrang = @TinhTrang)
        ORDER BY g.MaPhong, g.SoGiuong, g.MaGiuong;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @SoGiuong IS NULL
            RAISE EXCEPTION %;

        IF @SoGiuong IS NOT NULL AND @SoGiuong < 1
            RAISE EXCEPTION %;

        IF @TinhTrang IS NOT NULL AND @TinhTrang NOT IN ('Trống', 'Đã đặt cọc', 'Đang thuê')
            RAISE EXCEPTION %;
    END;

    DECLARE @SucChuaToiDa INT;
    SELECT @SucChuaToiDa = lp.SucChuaToiDa
    FROM dbo.Phong AS p
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    WHERE p.MaPhong = @MaPhong;

    IF @SoGiuong IS NOT NULL AND @SoGiuong > @SucChuaToiDa
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF (SELECT COUNT(*) FROM dbo.Giuong WHERE MaPhong = @MaPhong) >= @SucChuaToiDa
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND SoGiuong = @SoGiuong)
            RAISE EXCEPTION %;

        IF @MaGiuong IS NULL
        BEGIN
            DECLARE @SoMaGiuong INT;
            SELECT @SoMaGiuong = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaGiuong, 2, 2))), 0) + 1
            FROM dbo.Giuong 
            WHERE MaPhong = @MaPhong
              AND MaGiuong LIKE 'G[0-9][0-9]';

            IF @SoMaGiuong > 99
                RAISE EXCEPTION %;

            SET @MaGiuong = CONCAT('G', RIGHT(CONCAT('00', @SoMaGiuong), 2));
        END;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong)
            RAISE EXCEPTION %;

        BEGIN TRY
            BEGIN TRANSACTION;

            INSERT INTO dbo.Giuong (MaPhong, MaGiuong, SoGiuong, TinhTrang)
            VALUES (@MaPhong, @MaGiuong, @SoGiuong, COALESCE(@TinhTrang, 'Trống'));

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo giường',
                @DoiTuong = 'Giuong',
                @MaDoiTuong = @MaGiuong,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF @SoGiuong IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.Giuong
            WHERE MaPhong = @MaPhong
              AND SoGiuong = @SoGiuong
              AND MaGiuong <> @MaGiuong
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocGiuong TEXT;
        SELECT @DuLieuTruocGiuong = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.Giuong
        SET SoGiuong = COALESCE(@SoGiuong, SoGiuong),
            TinhTrang = COALESCE(@TinhTrang, TinhTrang)
        WHERE MaPhong = @MaPhong
          AND MaGiuong = @MaGiuong;

        UPDATE dbo.Phong
        SET TinhTrang = CASE
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong) THEN 'Trống'
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
            ELSE 'Còn chỗ'
        END
        WHERE MaPhong = @MaPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật giường',
            @DoiTuong = 'Giuong',
            @MaDoiTuong = @MaGiuong,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocGiuong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1 FROM dbo.Giuong
            WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong AND TinhTrang <> 'Trống'
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc AS ctdc
            INNER JOIN dbo.PhieuDatCoc AS pdc ON pdc.MaPhieuDatCoc = ctdc.MaPhieuDatCoc
            WHERE ctdc.MaPhong = @MaPhong
              AND ctdc.MaGiuong = @MaGiuong
              AND pdc.TrangThaiCoc IN ('Hiệu lực', 'Đã lập HĐ')
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietXemPhong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocGiuongXoa TEXT;
        SELECT @DuLieuTruocGiuongXoa = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        BEGIN TRY
            BEGIN TRANSACTION;

            DELETE FROM dbo.Giuong
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong;

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong) THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa giường',
                @DoiTuong = 'Giuong',
                @MaDoiTuong = @MaGiuong,
                @NoiDung = @MaPhong,
                @DuLieuTruoc = @DuLieuTruocGiuongXoa;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaGiuong AS maGiuong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyGiuong @ThaoTac = 'DANH_SACH', @MaPhong = @MaPhong, @MaGiuong = @MaGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyTaiSanPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyTaiSanPhong
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaPhong   VARCHAR(4)    = NULL,
    @MaTaiSan  VARCHAR(6)    = NULL,
    @TenTaiSan VARCHAR(100) = NULL,
    @SoLuong   INT           = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @LoaiTaiSan VARCHAR(20) = NULL,
    @MaGiuong   VARCHAR(3)   = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaTaiSan = NULLIF(TRIM(@MaTaiSan)), '');
    SET @TenTaiSan = NULLIF(TRIM(@TenTaiSan)), '');
    SET @LoaiTaiSan = NULLIF(TRIM(@LoaiTaiSan)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            ts.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            ts.MaTaiSan AS maTaiSan,
            ts.TenTaiSan AS tenTaiSan,
            ts.SoLuong AS soLuong,
            ts.DonGia AS donGia,
            ts.LoaiTaiSan AS loaiTaiSan,
            ts.MaGiuong AS maGiuong,
            g.SoGiuong AS soGiuong
        FROM dbo.TaiSan AS ts
        INNER JOIN dbo.Phong AS p ON p.MaPhong = ts.MaPhong
        LEFT JOIN dbo.Giuong AS g ON g.MaPhong = ts.MaPhong AND g.MaGiuong = ts.MaGiuong
        WHERE (@MaPhong IS NULL OR ts.MaPhong = @MaPhong)
          AND (@MaTaiSan IS NULL OR ts.MaTaiSan = @MaTaiSan)
          AND (@MaGiuong IS NULL OR ts.MaGiuong = @MaGiuong)
          AND (@LoaiTaiSan IS NULL OR ts.LoaiTaiSan = @LoaiTaiSan)
        ORDER BY ts.MaPhong, ts.LoaiTaiSan, ts.MaGiuong, ts.MaTaiSan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TenTaiSan IS NULL
            RAISE EXCEPTION %;

        IF @SoLuong IS NOT NULL AND @SoLuong <= 0
            RAISE EXCEPTION %;

        IF @DonGia IS NOT NULL AND @DonGia < 0
            RAISE EXCEPTION %;

        DECLARE @LoaiTaiSanSau VARCHAR(20);
        DECLARE @MaGiuongSau VARCHAR(3);

        IF @ThaoTac = 'TAO'
        BEGIN
            SET @LoaiTaiSanSau = COALESCE(@LoaiTaiSan, 'Chung');
            SET @MaGiuongSau = @MaGiuong;
        END
        ELSE
        BEGIN
            IF @MaTaiSan IS NULL OR NOT EXISTS (
                SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
            )
                RAISE EXCEPTION %;

            SELECT
                @LoaiTaiSanSau = COALESCE(@LoaiTaiSan, LoaiTaiSan),
                @MaGiuongSau = CASE
                    WHEN @LoaiTaiSan = 'Chung' THEN NULL
                    ELSE COALESCE(@MaGiuong, MaGiuong)
                END
            FROM dbo.TaiSan
            WHERE MaPhong = @MaPhong
              AND MaTaiSan = @MaTaiSan;
        END;

        IF @LoaiTaiSanSau NOT IN ('Chung', 'Riêng')
            RAISE EXCEPTION %;

        IF @LoaiTaiSanSau = 'Chung'
            SET @MaGiuongSau = NULL;

        IF @LoaiTaiSanSau = 'Riêng' AND @MaGiuongSau IS NULL
            RAISE EXCEPTION %;

        IF @MaGiuongSau IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuongSau
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoTaiSan INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaTaiSan IS NULL
            BEGIN
                SELECT @SoTaiSan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaTaiSan, 3, 4))), 0) + 1
                FROM dbo.TaiSan 
                WHERE MaPhong = @MaPhong
                  AND MaTaiSan LIKE 'TS[0-9][0-9][0-9][0-9]';

                IF @SoTaiSan > 9999
                    RAISE EXCEPTION %;

                SET @MaTaiSan = CONCAT('TS', RIGHT(CONCAT('0000', @SoTaiSan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.TaiSan (
                MaPhong, MaTaiSan, TenTaiSan, SoLuong, DonGia, LoaiTaiSan, MaGiuong
            )
            VALUES (
                @MaPhong, @MaTaiSan, @TenTaiSan, COALESCE(@SoLuong, 1),
                @DonGia, @LoaiTaiSanSau, @MaGiuongSau
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo tài sản phòng',
                @DoiTuong = 'TaiSan',
                @MaDoiTuong = @MaTaiSan,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocTaiSan TEXT;
        SELECT @DuLieuTruocTaiSan = (
            SELECT * FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.TaiSan
        SET TenTaiSan = COALESCE(@TenTaiSan, TenTaiSan),
            SoLuong = COALESCE(@SoLuong, SoLuong),
            DonGia = COALESCE(@DonGia, DonGia),
            LoaiTaiSan = @LoaiTaiSanSau,
            MaGiuong = @MaGiuongSau
        WHERE MaPhong = @MaPhong
          AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocTaiSan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietBanGiao WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.ChiTietHuHong WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.YeuCauSuaChua WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaTaiSan AS maTaiSan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyTaiSanPhong
        @ThaoTac = 'DANH_SACH',
        @MaPhong = @MaPhong,
        @MaTaiSan = @MaTaiSan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc
    @ThaoTac           VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinhHoanCoc VARCHAR(6)    = NULL,
    @TenQuyDinh        VARCHAR(255) = NULL,
    @TyLeHoanCoc       DECIMAL(5,2)  = NULL,
    @AdminId           VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinhHoanCoc = NULLIF(TRIM(@MaQuyDinhHoanCoc)), '');
    SET @TenQuyDinh = NULLIF(TRIM(@TenQuyDinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qh.MaQuyDinhHoanCoc AS maQuyDinhHoanCoc,
            qh.TenQuyDinh AS tenQuyDinh,
            qh.TyLeHoanCoc AS tyLeHoanCoc,
            COUNT(ds.MaQuyDinhHoanCoc) AS soLanApDung
        FROM dbo.QuyDinhHoanCoc AS qh
        LEFT JOIN dbo.DoiSoat AS ds ON ds.MaQuyDinhHoanCoc = qh.MaQuyDinhHoanCoc
        WHERE (@MaQuyDinhHoanCoc IS NULL OR qh.MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
        GROUP BY qh.MaQuyDinhHoanCoc, qh.TenQuyDinh, qh.TyLeHoanCoc
        ORDER BY qh.MaQuyDinhHoanCoc;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenQuyDinh IS NULL OR @TyLeHoanCoc IS NULL)
            RAISE EXCEPTION %;

        IF @TyLeHoanCoc IS NOT NULL AND (@TyLeHoanCoc < 0 OR @TyLeHoanCoc > 100)
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinh INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinhHoanCoc IS NULL
            BEGIN
                SELECT @SoQuyDinh = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinhHoanCoc, 3, 4))), 0) + 1
                FROM dbo.QuyDinhHoanCoc 
                WHERE MaQuyDinhHoanCoc LIKE 'QH[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinh > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinhHoanCoc = CONCAT('QH', RIGHT(CONCAT('0000', @SoQuyDinh), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuyDinhHoanCoc (MaQuyDinhHoanCoc, TenQuyDinh, TyLeHoanCoc)
            VALUES (@MaQuyDinhHoanCoc, @TenQuyDinh, @TyLeHoanCoc);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo quy định hoàn cọc',
                @DoiTuong = 'QuyDinhHoanCoc',
                @MaDoiTuong = @MaQuyDinhHoanCoc,
                @NoiDung = @TenQuyDinh;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocHoanCoc TEXT;
        SELECT @DuLieuTruocHoanCoc = (
            SELECT * FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuyDinhHoanCoc
        SET TenQuyDinh = COALESCE(@TenQuyDinh, TenQuyDinh),
            TyLeHoanCoc = COALESCE(@TyLeHoanCoc, TyLeHoanCoc)
        WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc,
            @DuLieuTruoc = @DuLieuTruocHoanCoc;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DoiSoat WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinhHoanCoc AS maQuyDinhHoanCoc;
        RETURN;
    END;

    EXEC dbo.SP_Admin_CauHinhQuyDinhHoanCoc @ThaoTac = 'DANH_SACH', @MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDichVu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDichVu
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaDichVu  VARCHAR(6)    = NULL,
    @TenDichVu VARCHAR(100) = NULL,
    @DonViTinh VARCHAR(20)   = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDichVu = NULLIF(TRIM(@MaDichVu)), '');
    SET @TenDichVu = NULLIF(TRIM(@TenDichVu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dv.MaDichVu AS maDichVu,
            dv.TenDichVu AS tenDichVu,
            dv.DonViTinh AS donViTinh,
            dv.DonGia AS donGia,
            COUNT(DISTINCT dvhd.MaChiTietDVHD) AS soHopDongSuDung,
            COUNT(cthd.MaChiTietHD) AS soDongHoaDon
        FROM dbo.DichVu AS dv
        LEFT JOIN dbo.DichVuHopDong AS dvhd ON dvhd.MaDichVu = dv.MaDichVu
        LEFT JOIN dbo.ChiTietHoaDon AS cthd ON cthd.MaChiTietDVHD = dvhd.MaChiTietDVHD
        WHERE (@MaDichVu IS NULL OR dv.MaDichVu = @MaDichVu)
          AND (@TenDichVu IS NULL OR dv.TenDichVu LIKE '%' + @TenDichVu + '%')
        GROUP BY dv.MaDichVu, dv.TenDichVu, dv.DonViTinh, dv.DonGia
        ORDER BY dv.MaDichVu;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDichVu IS NULL OR @DonViTinh IS NULL OR @DonGia IS NULL)
            THROW 51202, 'Vui lòng nhập tên dịch vụ, đơn vị tính và đơn giá.', 1;

        IF @DonGia IS NOT NULL AND @DonGia <= 0
            RAISE EXCEPTION %;

        IF @TenDichVu IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DichVu
            WHERE TenDichVu = @TenDichVu
              AND (@MaDichVu IS NULL OR MaDichVu <> @MaDichVu)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDichVu INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDichVu IS NULL
            BEGIN
                SELECT @SoDichVu = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDichVu, 3, 4))), 0) + 1
                FROM dbo.DichVu 
                WHERE MaDichVu LIKE 'DV[0-9][0-9][0-9][0-9]';

                IF @SoDichVu > 9999
                    RAISE EXCEPTION %;

                SET @MaDichVu = CONCAT('DV', RIGHT(CONCAT('0000', @SoDichVu), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DichVu (MaDichVu, TenDichVu, DonViTinh, DonGia)
            VALUES (@MaDichVu, @TenDichVu, @DonViTinh, @DonGia);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo dịch vụ',
                @DoiTuong = 'DichVu',
                @MaDoiTuong = @MaDichVu,
                @NoiDung = @TenDichVu;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocDichVu TEXT;
        SELECT @DuLieuTruocDichVu = (
            SELECT * FROM dbo.DichVu WHERE MaDichVu = @MaDichVu FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DichVu
        SET TenDichVu = COALESCE(@TenDichVu, TenDichVu),
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            DonGia = COALESCE(@DonGia, DonGia)
        WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu,
            @DuLieuTruoc = @DuLieuTruocDichVu;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DichVuHopDong WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DichVu WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDichVu AS maDichVu;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDichVu @ThaoTac = 'DANH_SACH', @MaDichVu = @MaDichVu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyNoiQuy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyNoiQuy
    @ThaoTac      VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinh    VARCHAR(6)    = NULL,
    @TieuDeNoiQuy VARCHAR(255) = NULL,
    @NoiDung      TEXT = NULL,
    @TrangThai    VARCHAR(20)  = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinh = NULLIF(TRIM(@MaQuyDinh)), '');
    SET @TieuDeNoiQuy = NULLIF(TRIM(@TieuDeNoiQuy)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qd.MaQuyDinh AS maQuyDinh,
            qd.TieuDeNoiQuy AS tieuDeNoiQuy,
            qd.NoiDung AS noiDung,
            qd.TrangThai AS trangThai
        FROM dbo.QuiDinh AS qd
        WHERE (@MaQuyDinh IS NULL OR qd.MaQuyDinh = @MaQuyDinh)
          AND (@TrangThai IS NULL OR qd.TrangThai = @TrangThai)
          AND (@TieuDeNoiQuy IS NULL OR qd.TieuDeNoiQuy LIKE '%' + @TieuDeNoiQuy + '%')
        ORDER BY qd.MaQuyDinh;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TieuDeNoiQuy IS NULL
            RAISE EXCEPTION %;

        IF @TieuDeNoiQuy IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.QuiDinh
            WHERE TieuDeNoiQuy = @TieuDeNoiQuy
              AND (@MaQuyDinh IS NULL OR MaQuyDinh <> @MaQuyDinh)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinhNoiQuy INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinh IS NULL
            BEGIN
                SELECT @SoQuyDinhNoiQuy = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinh, 3, 4))), 0) + 1
                FROM dbo.QuiDinh 
                WHERE MaQuyDinh LIKE 'QD[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinhNoiQuy > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinh = CONCAT('QD', RIGHT(CONCAT('0000', @SoQuyDinhNoiQuy), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuiDinh (MaQuyDinh, TieuDeNoiQuy, NoiDung, TrangThai)
            VALUES (@MaQuyDinh, @TieuDeNoiQuy, @NoiDung, COALESCE(@TrangThai, 'Hiệu lực'));

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo nội quy',
                @DoiTuong = 'QuiDinh',
                @MaDoiTuong = @MaQuyDinh,
                @NoiDung = @TieuDeNoiQuy;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocNoiQuy TEXT;
        SELECT @DuLieuTruocNoiQuy = (
            SELECT * FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuiDinh
        SET TieuDeNoiQuy = COALESCE(@TieuDeNoiQuy, TieuDeNoiQuy),
            NoiDung = COALESCE(@NoiDung, NoiDung),
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh,
            @DuLieuTruoc = @DuLieuTruocNoiQuy;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        UPDATE dbo.QuiDinh
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinh AS maQuyDinh;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyNoiQuy @ThaoTac = 'DANH_SACH', @MaQuyDinh = @MaQuyDinh;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham
    @ThaoTac        VARCHAR(20)  = 'DANH_SACH',
    @MaDieuKhoan    VARCHAR(6)    = NULL,
    @TenDieuKhoan   VARCHAR(255) = NULL,
    @HinhThucXuPhat VARCHAR(20)  = NULL,
    @MucPhat        DECIMAL(15,2) = NULL,
    @TrangThai      VARCHAR(20)  = NULL,
    @AdminId        VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDieuKhoan = NULLIF(TRIM(@MaDieuKhoan)), '');
    SET @TenDieuKhoan = NULLIF(TRIM(@TenDieuKhoan)), '');
    SET @HinhThucXuPhat = NULLIF(TRIM(@HinhThucXuPhat)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dk.MaDieuKhoan AS maDieuKhoan,
            dk.TenDieuKhoan AS tenDieuKhoan,
            dk.HinhThucXuPhat AS hinhThucXuPhat,
            dk.MucPhat AS mucPhat,
            dk.TrangThai AS trangThai,
            COUNT(bb.MaBBViPham) AS soBienBanApDung
        FROM dbo.DieuKhoanViPham AS dk
        LEFT JOIN dbo.BienBanViPham AS bb ON bb.MaDieuKhoan = dk.MaDieuKhoan
        WHERE (@MaDieuKhoan IS NULL OR dk.MaDieuKhoan = @MaDieuKhoan)
          AND (@TrangThai IS NULL OR dk.TrangThai = @TrangThai)
          AND (@TenDieuKhoan IS NULL OR dk.TenDieuKhoan LIKE '%' + @TenDieuKhoan + '%')
        GROUP BY dk.MaDieuKhoan, dk.TenDieuKhoan, dk.HinhThucXuPhat, dk.MucPhat, dk.TrangThai
        ORDER BY dk.MaDieuKhoan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @HinhThucXuPhat IS NOT NULL AND @HinhThucXuPhat NOT IN ('Nhắc nhở', 'Phạt tiền')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @MucPhat IS NOT NULL AND @MucPhat < 0
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDieuKhoan IS NULL OR @HinhThucXuPhat IS NULL)
            RAISE EXCEPTION %;

        IF @TenDieuKhoan IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DieuKhoanViPham
            WHERE TenDieuKhoan = @TenDieuKhoan
              AND (@MaDieuKhoan IS NULL OR MaDieuKhoan <> @MaDieuKhoan)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDieuKhoan INT;

        IF @HinhThucXuPhat = 'Phạt tiền' AND COALESCE(@MucPhat, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucXuPhat = 'Nhắc nhở' AND @MucPhat IS NULL
            SET @MucPhat = 0;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDieuKhoan IS NULL
            BEGIN
                SELECT @SoDieuKhoan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDieuKhoan, 3, 4))), 0) + 1
                FROM dbo.DieuKhoanViPham 
                WHERE MaDieuKhoan LIKE 'VP[0-9][0-9][0-9][0-9]';

                IF @SoDieuKhoan > 9999
                    RAISE EXCEPTION %;

                SET @MaDieuKhoan = CONCAT('VP', RIGHT(CONCAT('0000', @SoDieuKhoan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DieuKhoanViPham (
                MaDieuKhoan, TenDieuKhoan, HinhThucXuPhat, MucPhat, TrangThai
            )
            VALUES (
                @MaDieuKhoan, @TenDieuKhoan, @HinhThucXuPhat, COALESCE(@MucPhat, 0), COALESCE(@TrangThai, 'Hiệu lực')
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo điều khoản vi phạm',
                @DoiTuong = 'DieuKhoanViPham',
                @MaDoiTuong = @MaDieuKhoan,
                @NoiDung = @TenDieuKhoan;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DECLARE @HinhThucSau VARCHAR(20);
        DECLARE @MucPhatSau DECIMAL(15,2);

        SELECT
            @HinhThucSau = COALESCE(@HinhThucXuPhat, HinhThucXuPhat),
            @MucPhatSau = COALESCE(@MucPhat, MucPhat)
        FROM dbo.DieuKhoanViPham
        WHERE MaDieuKhoan = @MaDieuKhoan;

        IF @HinhThucSau = 'Phạt tiền' AND COALESCE(@MucPhatSau, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucSau = 'Nhắc nhở' AND @MucPhatSau IS NULL
            SET @MucPhatSau = 0;

        DECLARE @DuLieuTruocDieuKhoan TEXT;
        SELECT @DuLieuTruocDieuKhoan = (
            SELECT * FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DieuKhoanViPham
        SET TenDieuKhoan = COALESCE(@TenDieuKhoan, TenDieuKhoan),
            HinhThucXuPhat = @HinhThucSau,
            MucPhat = @MucPhatSau,
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan,
            @DuLieuTruoc = @DuLieuTruocDieuKhoan;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        UPDATE dbo.DieuKhoanViPham
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.BienBanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDieuKhoan AS maDieuKhoan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDieuKhoanViPham @ThaoTac = 'DANH_SACH', @MaDieuKhoan = @MaDieuKhoan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhThamSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhThamSo
    @ThaoTac    VARCHAR(20)  = 'DANH_SACH',
    @MaThamSo   VARCHAR(50)   = NULL,
    @NhomThamSo VARCHAR(50)  = NULL,
    @TenThamSo  VARCHAR(100) = NULL,
    @GiaTri     VARCHAR(255) = NULL,
    @KieuDuLieu VARCHAR(20)  = NULL,
    @DonViTinh  VARCHAR(30)  = NULL,
    @MoTa       TEXT = NULL,
    @AdminId    VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaThamSo = NULLIF(TRIM(@MaThamSo)), '');
    SET @NhomThamSo = NULLIF(TRIM(@NhomThamSo)), '');
    SET @TenThamSo = NULLIF(TRIM(@TenThamSo)), '');
    SET @GiaTri = NULLIF(TRIM(@GiaTri)), '');
    SET @KieuDuLieu = NULLIF(TRIM(@KieuDuLieu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            MaThamSo AS maThamSo,
            NhomThamSo AS nhomThamSo,
            TenThamSo AS tenThamSo,
            GiaTri AS giaTri,
            KieuDuLieu AS kieuDuLieu,
            DonViTinh AS donViTinh,
            MoTa AS moTa,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.ThamSoHeThong
        WHERE (@MaThamSo IS NULL OR MaThamSo = @MaThamSo)
          AND (@NhomThamSo IS NULL OR NhomThamSo = @NhomThamSo)
        ORDER BY NhomThamSo, MaThamSo;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT')
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO' AND (@MaThamSo IS NULL OR @NhomThamSo IS NULL OR @TenThamSo IS NULL OR @GiaTri IS NULL)
        THROW 51262, 'Vui lòng nhập đủ mã, nhóm, tên và giá trị tham số.', 1;

    IF @MaThamSo IS NULL
        RAISE EXCEPTION %;

    IF @KieuDuLieu IS NOT NULL AND @KieuDuLieu NOT IN ('Chuỗi', 'Số', 'Ngày', 'Boolean')
        RAISE EXCEPTION %;

    DECLARE @KieuDuLieuSau VARCHAR(20);
    DECLARE @GiaTriSau VARCHAR(255);

    IF @ThaoTac = 'TAO'
    BEGIN
        SET @KieuDuLieuSau = COALESCE(@KieuDuLieu, 'Chuỗi');
        SET @GiaTriSau = @GiaTri;
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        SELECT
            @KieuDuLieuSau = COALESCE(@KieuDuLieu, KieuDuLieu),
            @GiaTriSau = COALESCE(@GiaTri, GiaTri)
        FROM dbo.ThamSoHeThong
        WHERE MaThamSo = @MaThamSo;
    END;

    IF @KieuDuLieuSau = 'Số' AND (TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) IS NULL OR TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) < 0)
        RAISE EXCEPTION %;

    IF @MaThamSo = 'THOI_HAN_THANH_TOAN_COC_GIO'
       AND (TRY_CONVERT(INT, @GiaTriSau) IS NULL OR TRY_CONVERT(INT, @GiaTriSau) <= 0)
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        INSERT INTO dbo.ThamSoHeThong (
            MaThamSo, NhomThamSo, TenThamSo, GiaTri, KieuDuLieu, DonViTinh, MoTa, CapNhatBoi
        )
        VALUES (
            @MaThamSo, @NhomThamSo, @TenThamSo, @GiaTriSau, @KieuDuLieuSau, @DonViTinh, @MoTa, @AdminId
        );

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @NoiDung = @TenThamSo;
    END
    ELSE
    BEGIN
        DECLARE @DuLieuTruocThamSo TEXT;
        SELECT @DuLieuTruocThamSo = (
            SELECT * FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.ThamSoHeThong
        SET NhomThamSo = COALESCE(@NhomThamSo, NhomThamSo),
            TenThamSo = COALESCE(@TenThamSo, TenThamSo),
            GiaTri = @GiaTriSau,
            KieuDuLieu = @KieuDuLieuSau,
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            MoTa = COALESCE(@MoTa, MoTa),
            CapNhatLuc = CURRENT_TIMESTAMP,
            CapNhatBoi = @AdminId
        WHERE MaThamSo = @MaThamSo;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @DuLieuTruoc = @DuLieuTruocThamSo;
    END;

    EXEC dbo.SP_Admin_CauHinhThamSo @ThaoTac = 'DANH_SACH', @MaThamSo = @MaThamSo;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhSaoLuu
    @ChuKyFull        VARCHAR(20)  = NULL,
    @ChuKyIncremental VARCHAR(20)  = NULL,
    @ThuMucLuuTru     VARCHAR(500) = NULL,
    @AdminId          VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ChuKyFull = NULLIF(TRIM(@ChuKyFull)), '');
    SET @ChuKyIncremental = NULLIF(TRIM(@ChuKyIncremental)), '');
    SET @ThuMucLuuTru = NULLIF(TRIM(@ThuMucLuuTru)), '');

    IF @ChuKyFull IS NOT NULL AND @ChuKyFull NOT IN ('Hàng tuần', 'Hàng tháng')
        RAISE EXCEPTION %;

    IF @ChuKyIncremental IS NOT NULL AND @ChuKyIncremental NOT IN ('Hàng ngày', 'Hàng tuần')
        RAISE EXCEPTION %;

    IF @ThuMucLuuTru IS NOT NULL
    BEGIN
        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);
    END;

    IF @ChuKyFull IS NULL AND @ChuKyIncremental IS NULL AND @ThuMucLuuTru IS NULL
    BEGIN
        SELECT
            MaCauHinh AS maCauHinh,
            ChuKyFull AS chuKyFull,
            ChuKyIncremental AS chuKyIncremental,
            ThuMucLuuTru AS thuMucLuuTru,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;
        RETURN;
    END;

    DECLARE @DuLieuTruocSaoLuu TEXT;
    SELECT @DuLieuTruocSaoLuu = (
        SELECT * FROM dbo.CauHinhSaoLuu WHERE MaCauHinh = 1 FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    UPDATE dbo.CauHinhSaoLuu
    SET ChuKyFull = COALESCE(@ChuKyFull, ChuKyFull),
        ChuKyIncremental = COALESCE(@ChuKyIncremental, ChuKyIncremental),
        ThuMucLuuTru = COALESCE(@ThuMucLuuTru, ThuMucLuuTru),
        CapNhatLuc = CURRENT_TIMESTAMP,
        CapNhatBoi = @AdminId
    WHERE MaCauHinh = 1;

    EXEC dbo.SP_Admin_GhiNhatKy
        @AdminId = @AdminId,
        @HanhDong = 'Cấu hình sao lưu',
        @DoiTuong = 'CauHinhSaoLuu',
        @MaDoiTuong = '1',
        @DuLieuTruoc = @DuLieuTruocSaoLuu;

    SELECT
        MaCauHinh AS maCauHinh,
        ChuKyFull AS chuKyFull,
        ChuKyIncremental AS chuKyIncremental,
        ThuMucLuuTru AS thuMucLuuTru,
        CapNhatLuc AS capNhatLuc,
        CapNhatBoi AS capNhatBoi
    FROM dbo.CauHinhSaoLuu
    WHERE MaCauHinh = 1;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_SaoLuuThuCong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_SaoLuuThuCong
    @LoaiSaoLuu  VARCHAR(20)  = 'Full',
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    

    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');
    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');
    IF @LoaiSaoLuu IS NULL SET @LoaiSaoLuu = 'Full';

    DECLARE @LoaiSaoLuuChuan VARCHAR(20) = UPPER(@LoaiSaoLuu);
    IF @LoaiSaoLuuChuan = 'FULL'
        SET @LoaiSaoLuu = 'Full';
    ELSE IF @LoaiSaoLuuChuan IN ('INCREMENTAL', 'DIFFERENTIAL')
        SET @LoaiSaoLuu = 'Incremental';

    IF @LoaiSaoLuu NOT IN ('Full', 'Incremental')
        RAISE EXCEPTION %;

    IF @DuongDanFile IS NULL
    BEGIN
        DECLARE @ThuMucLuuTru VARCHAR(500);
        SELECT @ThuMucLuuTru = ThuMucLuuTru
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;

        IF @ThuMucLuuTru IS NULL
            RAISE EXCEPTION %;

        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);

        SET @DuongDanFile =
            @ThuMucLuuTru + '\' + DB_NAME() + '_' + @LoaiSaoLuu + '_' +
            CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112) + REPLACE(CONVERT(CHAR(8), CURRENT_TIMESTAMP, 108), ':', '') + '.bak';
    END;

    DECLARE @MaSaoLuu INT;
    DECLARE @LenhSaoLuu TEXT;

    INSERT INTO dbo.LichSuSaoLuu (
        LoaiSaoLuu, DuongDanFile, TrangThai, ThoiGianBatDau, MaNguoiDung
    )
    VALUES (
        @LoaiSaoLuu, @DuongDanFile, 'Đang chạy', CURRENT_TIMESTAMP, @AdminId
    );

    SET @MaSaoLuu = SCOPE_IDENTITY();
    SET @LenhSaoLuu =
        'BACKUP DATABASE ' + QUOTENAME(DB_NAME()) +
        ' TO DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') +
        ''' WITH ' +
        CASE WHEN @LoaiSaoLuu = 'Incremental' THEN 'DIFFERENTIAL, INIT' ELSE 'INIT' END +
        ';';

    BEGIN TRY
        EXEC(@LenhSaoLuu);

        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thành công',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = 'Sao lưu hoàn tất.'
        WHERE MaSaoLuu = @MaSaoLuu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Sao lưu thủ công',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thất bại',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = ERROR_MESSAGE()
        WHERE MaSaoLuu = @MaSaoLuu;

        THROW;
    END CATCH;

    SELECT
        MaSaoLuu AS maSaoLuu,
        LoaiSaoLuu AS loaiSaoLuu,
        DuongDanFile AS duongDanFile,
        TrangThai AS trangThai,
        ThoiGianBatDau AS thoiGianBatDau,
        ThoiGianKetThuc AS thoiGianKetThuc,
        ThongBao AS thongBao
    FROM dbo.LichSuSaoLuu
    WHERE MaSaoLuu = @MaSaoLuu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_DanhSachSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_DanhSachSaoLuu
    @SoDong     INT          = 100,
    @TrangThai  VARCHAR(20) = NULL,
    @LoaiSaoLuu VARCHAR(20) = NULL
AS
BEGIN
    

    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 100;

    SELECT TOP (@SoDong)
        ls.MaSaoLuu AS maSaoLuu,
        ls.LoaiSaoLuu AS loaiSaoLuu,
        ls.DuongDanFile AS duongDanFile,
        ls.DungLuongByte AS dungLuongByte,
        ls.TrangThai AS trangThai,
        ls.ThoiGianBatDau AS thoiGianBatDau,
        ls.ThoiGianKetThuc AS thoiGianKetThuc,
        ls.ThongBao AS thongBao,
        ls.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung
    FROM dbo.LichSuSaoLuu AS ls
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = ls.MaNguoiDung
    WHERE (@TrangThai IS NULL OR ls.TrangThai = @TrangThai)
      AND (@LoaiSaoLuu IS NULL OR ls.LoaiSaoLuu = @LoaiSaoLuu)
    ORDER BY ls.ThoiGianBatDau DESC, ls.MaSaoLuu DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_PhucHoiDuLieu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_PhucHoiDuLieu
    @MaSaoLuu    INT           = NULL,
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL,
    @ChiTaoLenh   BOOLEAN           = 1
AS
BEGIN
    

    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');

    IF @DuongDanFile IS NULL AND @MaSaoLuu IS NOT NULL
    BEGIN
        SELECT @DuongDanFile = DuongDanFile
        FROM dbo.LichSuSaoLuu
        WHERE MaSaoLuu = @MaSaoLuu
          AND TrangThai = 'Thành công';
    END;

    IF @DuongDanFile IS NULL
        RAISE EXCEPTION %;

    DECLARE @TenDatabase SYSNAME = DB_NAME();
    DECLARE @LenhSingleUser TEXT;
    DECLARE @LenhRestore TEXT;
    DECLARE @LenhMultiUser TEXT;
    DECLARE @LenhDayDu TEXT;

    SET @LenhSingleUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET SINGLE_USER WITH ROLLBACK IMMEDIATE;';
    SET @LenhRestore = 'USE [master]; RESTORE DATABASE ' + QUOTENAME(@TenDatabase) +
        ' FROM DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') + ''' WITH REPLACE;';
    SET @LenhMultiUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET MULTI_USER;';
    SET @LenhDayDu = @LenhSingleUser + CHAR(13) + CHAR(10) + @LenhRestore + CHAR(13) + CHAR(10) + @LenhMultiUser;

    IF @ChiTaoLenh = 1
    BEGIN
        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo lệnh phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;

        SELECT
            @TenDatabase AS tenDatabase,
            @DuongDanFile AS duongDanFile,
            @LenhDayDu AS lenhPhucHoi,
            CAST(1 AS BOOLEAN) AS chiTaoLenh;
        RETURN;
    END;

    BEGIN TRY
        EXEC(@LenhSingleUser);
        EXEC(@LenhRestore);
        EXEC(@LenhMultiUser);

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        BEGIN TRY
            EXEC(@LenhMultiUser);
        END TRY
        BEGIN CATCH
        END CATCH;

        THROW;
    END CATCH;

    SELECT
        @TenDatabase AS tenDatabase,
        @DuongDanFile AS duongDanFile,
        CAST(1 AS BOOLEAN) AS daPhucHoi;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_XemNhatKyHeThong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_XemNhatKyHeThong
    @TuNgay     TIMESTAMP  = NULL,
    @DenNgay    TIMESTAMP  = NULL,
    @AdminId    VARCHAR(6)    = NULL,
    @DoiTuong   VARCHAR(100) = NULL,
    @HanhDong   VARCHAR(100) = NULL,
    @TuKhoa     VARCHAR(100) = NULL,
    @SoDong     INT           = 200
AS
BEGIN
    

    SET @AdminId = NULLIF(TRIM(@AdminId)), '');
    SET @DoiTuong = NULLIF(TRIM(@DoiTuong)), '');
    SET @HanhDong = NULLIF(TRIM(@HanhDong)), '');
    SET @TuKhoa = NULLIF(TRIM(@TuKhoa)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 200;

    SELECT TOP (@SoDong)
        nk.MaNhatKy AS maNhatKy,
        nk.ThoiGian AS thoiGian,
        nk.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung,
        nk.VaiTro AS vaiTro,
        nk.ChucNang AS chucNang,
        nk.HanhDong AS hanhDong,
        nk.DoiTuong AS doiTuong,
        nk.MaDoiTuong AS maDoiTuong,
        nk.NoiDung AS noiDung,
        nk.DuLieuTruoc AS duLieuTruoc,
        nk.DuLieuSau AS duLieuSau
    FROM dbo.NhatKyHeThong AS nk
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nk.MaNguoiDung
    WHERE (@TuNgay IS NULL OR nk.ThoiGian >= @TuNgay)
      AND (@DenNgay IS NULL OR nk.ThoiGian < DATEADD(DAY, 1, @DenNgay))
      AND (@AdminId IS NULL OR nk.MaNguoiDung = @AdminId)
      AND (@DoiTuong IS NULL OR nk.DoiTuong = @DoiTuong)
      AND (@HanhDong IS NULL OR nk.HanhDong LIKE '%' + @HanhDong + '%')
      AND (
          @TuKhoa IS NULL
          OR nk.NoiDung LIKE '%' + @TuKhoa + '%'
          OR nk.MaDoiTuong LIKE '%' + @TuKhoa + '%'
          OR nk.HanhDong LIKE '%' + @TuKhoa + '%'
      )
    ORDER BY nk.ThoiGian DESC, nk.MaNhatKy DESC;
END; THEN (RIGHT(MaPhong, 2)::INT ELSE NULL END)), 0) + 1
                FROM dbo.Phong 
                WHERE MaChiNhanh = @MaChiNhanh
                  AND MaPhong LIKE CONCAT('P', @SoChiNhanhPhong, '[0-9][0-9]');

                IF @SoPhongMoi > 99
                    RAISE EXCEPTION %;

                SET @MaPhong = CONCAT('P', @SoChiNhanhPhong, RIGHT(CONCAT('00', @SoPhongMoi), 2));
            END;

            IF EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
                RAISE EXCEPTION %;

            INSERT INTO dbo.Phong (MaPhong, TenPhong, GioiTinhChoPhep, TinhTrang, MaChiNhanh, MaLoaiPhong)
            VALUES (@MaPhong, @TenPhong, @GioiTinhChoPhep, COALESCE(@TinhTrang, 'Trống'), @MaChiNhanh, @MaLoaiPhong);

            IF @UrlImg IS NOT NULL
            BEGIN
                INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
                VALUES (@MaPhong, 1, @UrlImg);
            END;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo phòng',
                @DoiTuong = 'Phong',
                @MaDoiTuong = @MaPhong,
                @NoiDung = @TenPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocPhong TEXT;
        SELECT @DuLieuTruocPhong = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.Phong
        SET TenPhong = COALESCE(@TenPhong, TenPhong),
            GioiTinhChoPhep = COALESCE(@GioiTinhChoPhep, GioiTinhChoPhep),
            TinhTrang = COALESCE(@TinhTrang, TinhTrang),
            MaChiNhanh = COALESCE(@MaChiNhanh, MaChiNhanh),
            MaLoaiPhong = COALESCE(@MaLoaiPhong, MaLoaiPhong)
        WHERE MaPhong = @MaPhong;

        IF @UrlImg IS NOT NULL
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.HinhAnhPhong WHERE MaPhong = @MaPhong AND STTAnh = 1)
                UPDATE dbo.HinhAnhPhong
                SET UrlImg = @UrlImg
                WHERE MaPhong = @MaPhong AND STTAnh = 1;
            ELSE
                INSERT INTO dbo.HinhAnhPhong (MaPhong, STTAnh, UrlImg)
                VALUES (@MaPhong, 1, @UrlImg);
        END;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật phòng',
            @DoiTuong = 'Phong',
            @MaDoiTuong = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocPhong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống')
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc AS ctdc
            INNER JOIN dbo.PhieuDatCoc AS pdc ON pdc.MaPhieuDatCoc = ctdc.MaPhieuDatCoc
            WHERE ctdc.MaPhong = @MaPhong
              AND pdc.TrangThaiCoc IN ('Hiệu lực', 'Đã lập HĐ')
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietDatCoc WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong)
           OR EXISTS (SELECT 1 FROM dbo.ChiTietXemPhong WHERE MaPhong = @MaPhong)
           OR EXISTS (SELECT 1 FROM dbo.PhieuGhiChiSo WHERE MaPhong = @MaPhong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocPhongXoa TEXT;
        SELECT @DuLieuTruocPhongXoa = (
            SELECT * FROM dbo.Phong WHERE MaPhong = @MaPhong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        BEGIN TRY
            BEGIN TRANSACTION;

            DELETE FROM dbo.Giuong WHERE MaPhong = @MaPhong;
            DELETE FROM dbo.Phong WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa phòng',
                @DoiTuong = 'Phong',
                @MaDoiTuong = @MaPhong,
                @DuLieuTruoc = @DuLieuTruocPhongXoa;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyPhong @ThaoTac = 'DANH_SACH', @MaPhong = @MaPhong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyGiuong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyGiuong
    @ThaoTac   VARCHAR(20) = 'DANH_SACH',
    @MaPhong   VARCHAR(4)   = NULL,
    @MaGiuong  VARCHAR(3)   = NULL,
    @SoGiuong  INT          = NULL,
    @TinhTrang VARCHAR(20) = NULL,
    @UrlImg    VARCHAR(500) = NULL,
    @AdminId   VARCHAR(6)   = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    SET @TinhTrang = NULLIF(TRIM(@TinhTrang)), '');
    SET @UrlImg = NULLIF(TRIM(@UrlImg)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            g.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            g.MaGiuong AS maGiuong,
            g.SoGiuong AS soGiuong,
            g.TinhTrang AS tinhTrang,
            lp.SucChuaToiDa AS sucChuaToiDa,
            (
                SELECT COUNT(1)
                FROM dbo.TaiSan AS tsChung
                WHERE tsChung.MaPhong = g.MaPhong
                  AND tsChung.LoaiTaiSan = 'Chung'
            ) AS soTaiSanChung,
            CAST(0 AS INT) AS soTaiSanRieng
        FROM dbo.Giuong AS g
        INNER JOIN dbo.Phong AS p ON p.MaPhong = g.MaPhong
        INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
        WHERE (@MaPhong IS NULL OR g.MaPhong = @MaPhong)
          AND (@MaGiuong IS NULL OR g.MaGiuong = @MaGiuong)
          AND (@TinhTrang IS NULL OR g.TinhTrang = @TinhTrang)
        ORDER BY g.MaPhong, g.SoGiuong, g.MaGiuong;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @SoGiuong IS NULL
            RAISE EXCEPTION %;

        IF @SoGiuong IS NOT NULL AND @SoGiuong < 1
            RAISE EXCEPTION %;

        IF @TinhTrang IS NOT NULL AND @TinhTrang NOT IN ('Trống', 'Đã đặt cọc', 'Đang thuê')
            RAISE EXCEPTION %;
    END;

    DECLARE @SucChuaToiDa INT;
    SELECT @SucChuaToiDa = lp.SucChuaToiDa
    FROM dbo.Phong AS p
    INNER JOIN dbo.LoaiPhong AS lp ON lp.MaLoaiPhong = p.MaLoaiPhong
    WHERE p.MaPhong = @MaPhong;

    IF @SoGiuong IS NOT NULL AND @SoGiuong > @SucChuaToiDa
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF (SELECT COUNT(*) FROM dbo.Giuong WHERE MaPhong = @MaPhong) >= @SucChuaToiDa
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND SoGiuong = @SoGiuong)
            RAISE EXCEPTION %;

        IF @MaGiuong IS NULL
        BEGIN
            DECLARE @SoMaGiuong INT;
            SELECT @SoMaGiuong = COALESCE(MAX(CASE WHEN (SUBSTRING(MaGiuong, 2, 2) ~ '^[0-9]+)), 0) + 1
            FROM dbo.Giuong 
            WHERE MaPhong = @MaPhong
              AND MaGiuong LIKE 'G[0-9][0-9]';

            IF @SoMaGiuong > 99
                RAISE EXCEPTION %;

            SET @MaGiuong = CONCAT('G', RIGHT(CONCAT('00', @SoMaGiuong), 2));
        END;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong)
            RAISE EXCEPTION %;

        BEGIN TRY
            BEGIN TRANSACTION;

            INSERT INTO dbo.Giuong (MaPhong, MaGiuong, SoGiuong, TinhTrang)
            VALUES (@MaPhong, @MaGiuong, @SoGiuong, COALESCE(@TinhTrang, 'Trống'));

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo giường',
                @DoiTuong = 'Giuong',
                @MaDoiTuong = @MaGiuong,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF @SoGiuong IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.Giuong
            WHERE MaPhong = @MaPhong
              AND SoGiuong = @SoGiuong
              AND MaGiuong <> @MaGiuong
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocGiuong TEXT;
        SELECT @DuLieuTruocGiuong = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.Giuong
        SET SoGiuong = COALESCE(@SoGiuong, SoGiuong),
            TinhTrang = COALESCE(@TinhTrang, TinhTrang)
        WHERE MaPhong = @MaPhong
          AND MaGiuong = @MaGiuong;

        UPDATE dbo.Phong
        SET TinhTrang = CASE
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong) THEN 'Trống'
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
            ELSE 'Còn chỗ'
        END
        WHERE MaPhong = @MaPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật giường',
            @DoiTuong = 'Giuong',
            @MaDoiTuong = @MaGiuong,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocGiuong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1 FROM dbo.Giuong
            WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong AND TinhTrang <> 'Trống'
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc AS ctdc
            INNER JOIN dbo.PhieuDatCoc AS pdc ON pdc.MaPhieuDatCoc = ctdc.MaPhieuDatCoc
            WHERE ctdc.MaPhong = @MaPhong
              AND ctdc.MaGiuong = @MaGiuong
              AND pdc.TrangThaiCoc IN ('Hiệu lực', 'Đã lập HĐ')
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietXemPhong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocGiuongXoa TEXT;
        SELECT @DuLieuTruocGiuongXoa = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        BEGIN TRY
            BEGIN TRANSACTION;

            DELETE FROM dbo.Giuong
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong;

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong) THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa giường',
                @DoiTuong = 'Giuong',
                @MaDoiTuong = @MaGiuong,
                @NoiDung = @MaPhong,
                @DuLieuTruoc = @DuLieuTruocGiuongXoa;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaGiuong AS maGiuong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyGiuong @ThaoTac = 'DANH_SACH', @MaPhong = @MaPhong, @MaGiuong = @MaGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyTaiSanPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyTaiSanPhong
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaPhong   VARCHAR(4)    = NULL,
    @MaTaiSan  VARCHAR(6)    = NULL,
    @TenTaiSan VARCHAR(100) = NULL,
    @SoLuong   INT           = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @LoaiTaiSan VARCHAR(20) = NULL,
    @MaGiuong   VARCHAR(3)   = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaTaiSan = NULLIF(TRIM(@MaTaiSan)), '');
    SET @TenTaiSan = NULLIF(TRIM(@TenTaiSan)), '');
    SET @LoaiTaiSan = NULLIF(TRIM(@LoaiTaiSan)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            ts.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            ts.MaTaiSan AS maTaiSan,
            ts.TenTaiSan AS tenTaiSan,
            ts.SoLuong AS soLuong,
            ts.DonGia AS donGia,
            ts.LoaiTaiSan AS loaiTaiSan,
            ts.MaGiuong AS maGiuong,
            g.SoGiuong AS soGiuong
        FROM dbo.TaiSan AS ts
        INNER JOIN dbo.Phong AS p ON p.MaPhong = ts.MaPhong
        LEFT JOIN dbo.Giuong AS g ON g.MaPhong = ts.MaPhong AND g.MaGiuong = ts.MaGiuong
        WHERE (@MaPhong IS NULL OR ts.MaPhong = @MaPhong)
          AND (@MaTaiSan IS NULL OR ts.MaTaiSan = @MaTaiSan)
          AND (@MaGiuong IS NULL OR ts.MaGiuong = @MaGiuong)
          AND (@LoaiTaiSan IS NULL OR ts.LoaiTaiSan = @LoaiTaiSan)
        ORDER BY ts.MaPhong, ts.LoaiTaiSan, ts.MaGiuong, ts.MaTaiSan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TenTaiSan IS NULL
            RAISE EXCEPTION %;

        IF @SoLuong IS NOT NULL AND @SoLuong <= 0
            RAISE EXCEPTION %;

        IF @DonGia IS NOT NULL AND @DonGia < 0
            RAISE EXCEPTION %;

        DECLARE @LoaiTaiSanSau VARCHAR(20);
        DECLARE @MaGiuongSau VARCHAR(3);

        IF @ThaoTac = 'TAO'
        BEGIN
            SET @LoaiTaiSanSau = COALESCE(@LoaiTaiSan, 'Chung');
            SET @MaGiuongSau = @MaGiuong;
        END
        ELSE
        BEGIN
            IF @MaTaiSan IS NULL OR NOT EXISTS (
                SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
            )
                RAISE EXCEPTION %;

            SELECT
                @LoaiTaiSanSau = COALESCE(@LoaiTaiSan, LoaiTaiSan),
                @MaGiuongSau = CASE
                    WHEN @LoaiTaiSan = 'Chung' THEN NULL
                    ELSE COALESCE(@MaGiuong, MaGiuong)
                END
            FROM dbo.TaiSan
            WHERE MaPhong = @MaPhong
              AND MaTaiSan = @MaTaiSan;
        END;

        IF @LoaiTaiSanSau NOT IN ('Chung', 'Riêng')
            RAISE EXCEPTION %;

        IF @LoaiTaiSanSau = 'Chung'
            SET @MaGiuongSau = NULL;

        IF @LoaiTaiSanSau = 'Riêng' AND @MaGiuongSau IS NULL
            RAISE EXCEPTION %;

        IF @MaGiuongSau IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuongSau
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoTaiSan INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaTaiSan IS NULL
            BEGIN
                SELECT @SoTaiSan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaTaiSan, 3, 4))), 0) + 1
                FROM dbo.TaiSan 
                WHERE MaPhong = @MaPhong
                  AND MaTaiSan LIKE 'TS[0-9][0-9][0-9][0-9]';

                IF @SoTaiSan > 9999
                    RAISE EXCEPTION %;

                SET @MaTaiSan = CONCAT('TS', RIGHT(CONCAT('0000', @SoTaiSan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.TaiSan (
                MaPhong, MaTaiSan, TenTaiSan, SoLuong, DonGia, LoaiTaiSan, MaGiuong
            )
            VALUES (
                @MaPhong, @MaTaiSan, @TenTaiSan, COALESCE(@SoLuong, 1),
                @DonGia, @LoaiTaiSanSau, @MaGiuongSau
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo tài sản phòng',
                @DoiTuong = 'TaiSan',
                @MaDoiTuong = @MaTaiSan,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocTaiSan TEXT;
        SELECT @DuLieuTruocTaiSan = (
            SELECT * FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.TaiSan
        SET TenTaiSan = COALESCE(@TenTaiSan, TenTaiSan),
            SoLuong = COALESCE(@SoLuong, SoLuong),
            DonGia = COALESCE(@DonGia, DonGia),
            LoaiTaiSan = @LoaiTaiSanSau,
            MaGiuong = @MaGiuongSau
        WHERE MaPhong = @MaPhong
          AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocTaiSan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietBanGiao WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.ChiTietHuHong WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.YeuCauSuaChua WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaTaiSan AS maTaiSan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyTaiSanPhong
        @ThaoTac = 'DANH_SACH',
        @MaPhong = @MaPhong,
        @MaTaiSan = @MaTaiSan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc
    @ThaoTac           VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinhHoanCoc VARCHAR(6)    = NULL,
    @TenQuyDinh        VARCHAR(255) = NULL,
    @TyLeHoanCoc       DECIMAL(5,2)  = NULL,
    @AdminId           VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinhHoanCoc = NULLIF(TRIM(@MaQuyDinhHoanCoc)), '');
    SET @TenQuyDinh = NULLIF(TRIM(@TenQuyDinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qh.MaQuyDinhHoanCoc AS maQuyDinhHoanCoc,
            qh.TenQuyDinh AS tenQuyDinh,
            qh.TyLeHoanCoc AS tyLeHoanCoc,
            COUNT(ds.MaQuyDinhHoanCoc) AS soLanApDung
        FROM dbo.QuyDinhHoanCoc AS qh
        LEFT JOIN dbo.DoiSoat AS ds ON ds.MaQuyDinhHoanCoc = qh.MaQuyDinhHoanCoc
        WHERE (@MaQuyDinhHoanCoc IS NULL OR qh.MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
        GROUP BY qh.MaQuyDinhHoanCoc, qh.TenQuyDinh, qh.TyLeHoanCoc
        ORDER BY qh.MaQuyDinhHoanCoc;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenQuyDinh IS NULL OR @TyLeHoanCoc IS NULL)
            RAISE EXCEPTION %;

        IF @TyLeHoanCoc IS NOT NULL AND (@TyLeHoanCoc < 0 OR @TyLeHoanCoc > 100)
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinh INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinhHoanCoc IS NULL
            BEGIN
                SELECT @SoQuyDinh = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinhHoanCoc, 3, 4))), 0) + 1
                FROM dbo.QuyDinhHoanCoc 
                WHERE MaQuyDinhHoanCoc LIKE 'QH[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinh > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinhHoanCoc = CONCAT('QH', RIGHT(CONCAT('0000', @SoQuyDinh), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuyDinhHoanCoc (MaQuyDinhHoanCoc, TenQuyDinh, TyLeHoanCoc)
            VALUES (@MaQuyDinhHoanCoc, @TenQuyDinh, @TyLeHoanCoc);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo quy định hoàn cọc',
                @DoiTuong = 'QuyDinhHoanCoc',
                @MaDoiTuong = @MaQuyDinhHoanCoc,
                @NoiDung = @TenQuyDinh;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocHoanCoc TEXT;
        SELECT @DuLieuTruocHoanCoc = (
            SELECT * FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuyDinhHoanCoc
        SET TenQuyDinh = COALESCE(@TenQuyDinh, TenQuyDinh),
            TyLeHoanCoc = COALESCE(@TyLeHoanCoc, TyLeHoanCoc)
        WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc,
            @DuLieuTruoc = @DuLieuTruocHoanCoc;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DoiSoat WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinhHoanCoc AS maQuyDinhHoanCoc;
        RETURN;
    END;

    EXEC dbo.SP_Admin_CauHinhQuyDinhHoanCoc @ThaoTac = 'DANH_SACH', @MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDichVu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDichVu
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaDichVu  VARCHAR(6)    = NULL,
    @TenDichVu VARCHAR(100) = NULL,
    @DonViTinh VARCHAR(20)   = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDichVu = NULLIF(TRIM(@MaDichVu)), '');
    SET @TenDichVu = NULLIF(TRIM(@TenDichVu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dv.MaDichVu AS maDichVu,
            dv.TenDichVu AS tenDichVu,
            dv.DonViTinh AS donViTinh,
            dv.DonGia AS donGia,
            COUNT(DISTINCT dvhd.MaChiTietDVHD) AS soHopDongSuDung,
            COUNT(cthd.MaChiTietHD) AS soDongHoaDon
        FROM dbo.DichVu AS dv
        LEFT JOIN dbo.DichVuHopDong AS dvhd ON dvhd.MaDichVu = dv.MaDichVu
        LEFT JOIN dbo.ChiTietHoaDon AS cthd ON cthd.MaChiTietDVHD = dvhd.MaChiTietDVHD
        WHERE (@MaDichVu IS NULL OR dv.MaDichVu = @MaDichVu)
          AND (@TenDichVu IS NULL OR dv.TenDichVu LIKE '%' + @TenDichVu + '%')
        GROUP BY dv.MaDichVu, dv.TenDichVu, dv.DonViTinh, dv.DonGia
        ORDER BY dv.MaDichVu;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDichVu IS NULL OR @DonViTinh IS NULL OR @DonGia IS NULL)
            THROW 51202, 'Vui lòng nhập tên dịch vụ, đơn vị tính và đơn giá.', 1;

        IF @DonGia IS NOT NULL AND @DonGia <= 0
            RAISE EXCEPTION %;

        IF @TenDichVu IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DichVu
            WHERE TenDichVu = @TenDichVu
              AND (@MaDichVu IS NULL OR MaDichVu <> @MaDichVu)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDichVu INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDichVu IS NULL
            BEGIN
                SELECT @SoDichVu = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDichVu, 3, 4))), 0) + 1
                FROM dbo.DichVu 
                WHERE MaDichVu LIKE 'DV[0-9][0-9][0-9][0-9]';

                IF @SoDichVu > 9999
                    RAISE EXCEPTION %;

                SET @MaDichVu = CONCAT('DV', RIGHT(CONCAT('0000', @SoDichVu), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DichVu (MaDichVu, TenDichVu, DonViTinh, DonGia)
            VALUES (@MaDichVu, @TenDichVu, @DonViTinh, @DonGia);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo dịch vụ',
                @DoiTuong = 'DichVu',
                @MaDoiTuong = @MaDichVu,
                @NoiDung = @TenDichVu;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocDichVu TEXT;
        SELECT @DuLieuTruocDichVu = (
            SELECT * FROM dbo.DichVu WHERE MaDichVu = @MaDichVu FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DichVu
        SET TenDichVu = COALESCE(@TenDichVu, TenDichVu),
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            DonGia = COALESCE(@DonGia, DonGia)
        WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu,
            @DuLieuTruoc = @DuLieuTruocDichVu;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DichVuHopDong WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DichVu WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDichVu AS maDichVu;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDichVu @ThaoTac = 'DANH_SACH', @MaDichVu = @MaDichVu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyNoiQuy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyNoiQuy
    @ThaoTac      VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinh    VARCHAR(6)    = NULL,
    @TieuDeNoiQuy VARCHAR(255) = NULL,
    @NoiDung      TEXT = NULL,
    @TrangThai    VARCHAR(20)  = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinh = NULLIF(TRIM(@MaQuyDinh)), '');
    SET @TieuDeNoiQuy = NULLIF(TRIM(@TieuDeNoiQuy)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qd.MaQuyDinh AS maQuyDinh,
            qd.TieuDeNoiQuy AS tieuDeNoiQuy,
            qd.NoiDung AS noiDung,
            qd.TrangThai AS trangThai
        FROM dbo.QuiDinh AS qd
        WHERE (@MaQuyDinh IS NULL OR qd.MaQuyDinh = @MaQuyDinh)
          AND (@TrangThai IS NULL OR qd.TrangThai = @TrangThai)
          AND (@TieuDeNoiQuy IS NULL OR qd.TieuDeNoiQuy LIKE '%' + @TieuDeNoiQuy + '%')
        ORDER BY qd.MaQuyDinh;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TieuDeNoiQuy IS NULL
            RAISE EXCEPTION %;

        IF @TieuDeNoiQuy IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.QuiDinh
            WHERE TieuDeNoiQuy = @TieuDeNoiQuy
              AND (@MaQuyDinh IS NULL OR MaQuyDinh <> @MaQuyDinh)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinhNoiQuy INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinh IS NULL
            BEGIN
                SELECT @SoQuyDinhNoiQuy = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinh, 3, 4))), 0) + 1
                FROM dbo.QuiDinh 
                WHERE MaQuyDinh LIKE 'QD[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinhNoiQuy > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinh = CONCAT('QD', RIGHT(CONCAT('0000', @SoQuyDinhNoiQuy), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuiDinh (MaQuyDinh, TieuDeNoiQuy, NoiDung, TrangThai)
            VALUES (@MaQuyDinh, @TieuDeNoiQuy, @NoiDung, COALESCE(@TrangThai, 'Hiệu lực'));

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo nội quy',
                @DoiTuong = 'QuiDinh',
                @MaDoiTuong = @MaQuyDinh,
                @NoiDung = @TieuDeNoiQuy;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocNoiQuy TEXT;
        SELECT @DuLieuTruocNoiQuy = (
            SELECT * FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuiDinh
        SET TieuDeNoiQuy = COALESCE(@TieuDeNoiQuy, TieuDeNoiQuy),
            NoiDung = COALESCE(@NoiDung, NoiDung),
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh,
            @DuLieuTruoc = @DuLieuTruocNoiQuy;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        UPDATE dbo.QuiDinh
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinh AS maQuyDinh;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyNoiQuy @ThaoTac = 'DANH_SACH', @MaQuyDinh = @MaQuyDinh;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham
    @ThaoTac        VARCHAR(20)  = 'DANH_SACH',
    @MaDieuKhoan    VARCHAR(6)    = NULL,
    @TenDieuKhoan   VARCHAR(255) = NULL,
    @HinhThucXuPhat VARCHAR(20)  = NULL,
    @MucPhat        DECIMAL(15,2) = NULL,
    @TrangThai      VARCHAR(20)  = NULL,
    @AdminId        VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDieuKhoan = NULLIF(TRIM(@MaDieuKhoan)), '');
    SET @TenDieuKhoan = NULLIF(TRIM(@TenDieuKhoan)), '');
    SET @HinhThucXuPhat = NULLIF(TRIM(@HinhThucXuPhat)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dk.MaDieuKhoan AS maDieuKhoan,
            dk.TenDieuKhoan AS tenDieuKhoan,
            dk.HinhThucXuPhat AS hinhThucXuPhat,
            dk.MucPhat AS mucPhat,
            dk.TrangThai AS trangThai,
            COUNT(bb.MaBBViPham) AS soBienBanApDung
        FROM dbo.DieuKhoanViPham AS dk
        LEFT JOIN dbo.BienBanViPham AS bb ON bb.MaDieuKhoan = dk.MaDieuKhoan
        WHERE (@MaDieuKhoan IS NULL OR dk.MaDieuKhoan = @MaDieuKhoan)
          AND (@TrangThai IS NULL OR dk.TrangThai = @TrangThai)
          AND (@TenDieuKhoan IS NULL OR dk.TenDieuKhoan LIKE '%' + @TenDieuKhoan + '%')
        GROUP BY dk.MaDieuKhoan, dk.TenDieuKhoan, dk.HinhThucXuPhat, dk.MucPhat, dk.TrangThai
        ORDER BY dk.MaDieuKhoan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @HinhThucXuPhat IS NOT NULL AND @HinhThucXuPhat NOT IN ('Nhắc nhở', 'Phạt tiền')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @MucPhat IS NOT NULL AND @MucPhat < 0
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDieuKhoan IS NULL OR @HinhThucXuPhat IS NULL)
            RAISE EXCEPTION %;

        IF @TenDieuKhoan IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DieuKhoanViPham
            WHERE TenDieuKhoan = @TenDieuKhoan
              AND (@MaDieuKhoan IS NULL OR MaDieuKhoan <> @MaDieuKhoan)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDieuKhoan INT;

        IF @HinhThucXuPhat = 'Phạt tiền' AND COALESCE(@MucPhat, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucXuPhat = 'Nhắc nhở' AND @MucPhat IS NULL
            SET @MucPhat = 0;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDieuKhoan IS NULL
            BEGIN
                SELECT @SoDieuKhoan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDieuKhoan, 3, 4))), 0) + 1
                FROM dbo.DieuKhoanViPham 
                WHERE MaDieuKhoan LIKE 'VP[0-9][0-9][0-9][0-9]';

                IF @SoDieuKhoan > 9999
                    RAISE EXCEPTION %;

                SET @MaDieuKhoan = CONCAT('VP', RIGHT(CONCAT('0000', @SoDieuKhoan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DieuKhoanViPham (
                MaDieuKhoan, TenDieuKhoan, HinhThucXuPhat, MucPhat, TrangThai
            )
            VALUES (
                @MaDieuKhoan, @TenDieuKhoan, @HinhThucXuPhat, COALESCE(@MucPhat, 0), COALESCE(@TrangThai, 'Hiệu lực')
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo điều khoản vi phạm',
                @DoiTuong = 'DieuKhoanViPham',
                @MaDoiTuong = @MaDieuKhoan,
                @NoiDung = @TenDieuKhoan;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DECLARE @HinhThucSau VARCHAR(20);
        DECLARE @MucPhatSau DECIMAL(15,2);

        SELECT
            @HinhThucSau = COALESCE(@HinhThucXuPhat, HinhThucXuPhat),
            @MucPhatSau = COALESCE(@MucPhat, MucPhat)
        FROM dbo.DieuKhoanViPham
        WHERE MaDieuKhoan = @MaDieuKhoan;

        IF @HinhThucSau = 'Phạt tiền' AND COALESCE(@MucPhatSau, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucSau = 'Nhắc nhở' AND @MucPhatSau IS NULL
            SET @MucPhatSau = 0;

        DECLARE @DuLieuTruocDieuKhoan TEXT;
        SELECT @DuLieuTruocDieuKhoan = (
            SELECT * FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DieuKhoanViPham
        SET TenDieuKhoan = COALESCE(@TenDieuKhoan, TenDieuKhoan),
            HinhThucXuPhat = @HinhThucSau,
            MucPhat = @MucPhatSau,
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan,
            @DuLieuTruoc = @DuLieuTruocDieuKhoan;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        UPDATE dbo.DieuKhoanViPham
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.BienBanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDieuKhoan AS maDieuKhoan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDieuKhoanViPham @ThaoTac = 'DANH_SACH', @MaDieuKhoan = @MaDieuKhoan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhThamSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhThamSo
    @ThaoTac    VARCHAR(20)  = 'DANH_SACH',
    @MaThamSo   VARCHAR(50)   = NULL,
    @NhomThamSo VARCHAR(50)  = NULL,
    @TenThamSo  VARCHAR(100) = NULL,
    @GiaTri     VARCHAR(255) = NULL,
    @KieuDuLieu VARCHAR(20)  = NULL,
    @DonViTinh  VARCHAR(30)  = NULL,
    @MoTa       TEXT = NULL,
    @AdminId    VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaThamSo = NULLIF(TRIM(@MaThamSo)), '');
    SET @NhomThamSo = NULLIF(TRIM(@NhomThamSo)), '');
    SET @TenThamSo = NULLIF(TRIM(@TenThamSo)), '');
    SET @GiaTri = NULLIF(TRIM(@GiaTri)), '');
    SET @KieuDuLieu = NULLIF(TRIM(@KieuDuLieu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            MaThamSo AS maThamSo,
            NhomThamSo AS nhomThamSo,
            TenThamSo AS tenThamSo,
            GiaTri AS giaTri,
            KieuDuLieu AS kieuDuLieu,
            DonViTinh AS donViTinh,
            MoTa AS moTa,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.ThamSoHeThong
        WHERE (@MaThamSo IS NULL OR MaThamSo = @MaThamSo)
          AND (@NhomThamSo IS NULL OR NhomThamSo = @NhomThamSo)
        ORDER BY NhomThamSo, MaThamSo;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT')
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO' AND (@MaThamSo IS NULL OR @NhomThamSo IS NULL OR @TenThamSo IS NULL OR @GiaTri IS NULL)
        THROW 51262, 'Vui lòng nhập đủ mã, nhóm, tên và giá trị tham số.', 1;

    IF @MaThamSo IS NULL
        RAISE EXCEPTION %;

    IF @KieuDuLieu IS NOT NULL AND @KieuDuLieu NOT IN ('Chuỗi', 'Số', 'Ngày', 'Boolean')
        RAISE EXCEPTION %;

    DECLARE @KieuDuLieuSau VARCHAR(20);
    DECLARE @GiaTriSau VARCHAR(255);

    IF @ThaoTac = 'TAO'
    BEGIN
        SET @KieuDuLieuSau = COALESCE(@KieuDuLieu, 'Chuỗi');
        SET @GiaTriSau = @GiaTri;
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        SELECT
            @KieuDuLieuSau = COALESCE(@KieuDuLieu, KieuDuLieu),
            @GiaTriSau = COALESCE(@GiaTri, GiaTri)
        FROM dbo.ThamSoHeThong
        WHERE MaThamSo = @MaThamSo;
    END;

    IF @KieuDuLieuSau = 'Số' AND (TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) IS NULL OR TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) < 0)
        RAISE EXCEPTION %;

    IF @MaThamSo = 'THOI_HAN_THANH_TOAN_COC_GIO'
       AND (TRY_CONVERT(INT, @GiaTriSau) IS NULL OR TRY_CONVERT(INT, @GiaTriSau) <= 0)
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        INSERT INTO dbo.ThamSoHeThong (
            MaThamSo, NhomThamSo, TenThamSo, GiaTri, KieuDuLieu, DonViTinh, MoTa, CapNhatBoi
        )
        VALUES (
            @MaThamSo, @NhomThamSo, @TenThamSo, @GiaTriSau, @KieuDuLieuSau, @DonViTinh, @MoTa, @AdminId
        );

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @NoiDung = @TenThamSo;
    END
    ELSE
    BEGIN
        DECLARE @DuLieuTruocThamSo TEXT;
        SELECT @DuLieuTruocThamSo = (
            SELECT * FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.ThamSoHeThong
        SET NhomThamSo = COALESCE(@NhomThamSo, NhomThamSo),
            TenThamSo = COALESCE(@TenThamSo, TenThamSo),
            GiaTri = @GiaTriSau,
            KieuDuLieu = @KieuDuLieuSau,
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            MoTa = COALESCE(@MoTa, MoTa),
            CapNhatLuc = CURRENT_TIMESTAMP,
            CapNhatBoi = @AdminId
        WHERE MaThamSo = @MaThamSo;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @DuLieuTruoc = @DuLieuTruocThamSo;
    END;

    EXEC dbo.SP_Admin_CauHinhThamSo @ThaoTac = 'DANH_SACH', @MaThamSo = @MaThamSo;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhSaoLuu
    @ChuKyFull        VARCHAR(20)  = NULL,
    @ChuKyIncremental VARCHAR(20)  = NULL,
    @ThuMucLuuTru     VARCHAR(500) = NULL,
    @AdminId          VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ChuKyFull = NULLIF(TRIM(@ChuKyFull)), '');
    SET @ChuKyIncremental = NULLIF(TRIM(@ChuKyIncremental)), '');
    SET @ThuMucLuuTru = NULLIF(TRIM(@ThuMucLuuTru)), '');

    IF @ChuKyFull IS NOT NULL AND @ChuKyFull NOT IN ('Hàng tuần', 'Hàng tháng')
        RAISE EXCEPTION %;

    IF @ChuKyIncremental IS NOT NULL AND @ChuKyIncremental NOT IN ('Hàng ngày', 'Hàng tuần')
        RAISE EXCEPTION %;

    IF @ThuMucLuuTru IS NOT NULL
    BEGIN
        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);
    END;

    IF @ChuKyFull IS NULL AND @ChuKyIncremental IS NULL AND @ThuMucLuuTru IS NULL
    BEGIN
        SELECT
            MaCauHinh AS maCauHinh,
            ChuKyFull AS chuKyFull,
            ChuKyIncremental AS chuKyIncremental,
            ThuMucLuuTru AS thuMucLuuTru,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;
        RETURN;
    END;

    DECLARE @DuLieuTruocSaoLuu TEXT;
    SELECT @DuLieuTruocSaoLuu = (
        SELECT * FROM dbo.CauHinhSaoLuu WHERE MaCauHinh = 1 FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    UPDATE dbo.CauHinhSaoLuu
    SET ChuKyFull = COALESCE(@ChuKyFull, ChuKyFull),
        ChuKyIncremental = COALESCE(@ChuKyIncremental, ChuKyIncremental),
        ThuMucLuuTru = COALESCE(@ThuMucLuuTru, ThuMucLuuTru),
        CapNhatLuc = CURRENT_TIMESTAMP,
        CapNhatBoi = @AdminId
    WHERE MaCauHinh = 1;

    EXEC dbo.SP_Admin_GhiNhatKy
        @AdminId = @AdminId,
        @HanhDong = 'Cấu hình sao lưu',
        @DoiTuong = 'CauHinhSaoLuu',
        @MaDoiTuong = '1',
        @DuLieuTruoc = @DuLieuTruocSaoLuu;

    SELECT
        MaCauHinh AS maCauHinh,
        ChuKyFull AS chuKyFull,
        ChuKyIncremental AS chuKyIncremental,
        ThuMucLuuTru AS thuMucLuuTru,
        CapNhatLuc AS capNhatLuc,
        CapNhatBoi AS capNhatBoi
    FROM dbo.CauHinhSaoLuu
    WHERE MaCauHinh = 1;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_SaoLuuThuCong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_SaoLuuThuCong
    @LoaiSaoLuu  VARCHAR(20)  = 'Full',
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    

    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');
    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');
    IF @LoaiSaoLuu IS NULL SET @LoaiSaoLuu = 'Full';

    DECLARE @LoaiSaoLuuChuan VARCHAR(20) = UPPER(@LoaiSaoLuu);
    IF @LoaiSaoLuuChuan = 'FULL'
        SET @LoaiSaoLuu = 'Full';
    ELSE IF @LoaiSaoLuuChuan IN ('INCREMENTAL', 'DIFFERENTIAL')
        SET @LoaiSaoLuu = 'Incremental';

    IF @LoaiSaoLuu NOT IN ('Full', 'Incremental')
        RAISE EXCEPTION %;

    IF @DuongDanFile IS NULL
    BEGIN
        DECLARE @ThuMucLuuTru VARCHAR(500);
        SELECT @ThuMucLuuTru = ThuMucLuuTru
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;

        IF @ThuMucLuuTru IS NULL
            RAISE EXCEPTION %;

        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);

        SET @DuongDanFile =
            @ThuMucLuuTru + '\' + DB_NAME() + '_' + @LoaiSaoLuu + '_' +
            CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112) + REPLACE(CONVERT(CHAR(8), CURRENT_TIMESTAMP, 108), ':', '') + '.bak';
    END;

    DECLARE @MaSaoLuu INT;
    DECLARE @LenhSaoLuu TEXT;

    INSERT INTO dbo.LichSuSaoLuu (
        LoaiSaoLuu, DuongDanFile, TrangThai, ThoiGianBatDau, MaNguoiDung
    )
    VALUES (
        @LoaiSaoLuu, @DuongDanFile, 'Đang chạy', CURRENT_TIMESTAMP, @AdminId
    );

    SET @MaSaoLuu = SCOPE_IDENTITY();
    SET @LenhSaoLuu =
        'BACKUP DATABASE ' + QUOTENAME(DB_NAME()) +
        ' TO DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') +
        ''' WITH ' +
        CASE WHEN @LoaiSaoLuu = 'Incremental' THEN 'DIFFERENTIAL, INIT' ELSE 'INIT' END +
        ';';

    BEGIN TRY
        EXEC(@LenhSaoLuu);

        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thành công',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = 'Sao lưu hoàn tất.'
        WHERE MaSaoLuu = @MaSaoLuu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Sao lưu thủ công',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thất bại',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = ERROR_MESSAGE()
        WHERE MaSaoLuu = @MaSaoLuu;

        THROW;
    END CATCH;

    SELECT
        MaSaoLuu AS maSaoLuu,
        LoaiSaoLuu AS loaiSaoLuu,
        DuongDanFile AS duongDanFile,
        TrangThai AS trangThai,
        ThoiGianBatDau AS thoiGianBatDau,
        ThoiGianKetThuc AS thoiGianKetThuc,
        ThongBao AS thongBao
    FROM dbo.LichSuSaoLuu
    WHERE MaSaoLuu = @MaSaoLuu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_DanhSachSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_DanhSachSaoLuu
    @SoDong     INT          = 100,
    @TrangThai  VARCHAR(20) = NULL,
    @LoaiSaoLuu VARCHAR(20) = NULL
AS
BEGIN
    

    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 100;

    SELECT TOP (@SoDong)
        ls.MaSaoLuu AS maSaoLuu,
        ls.LoaiSaoLuu AS loaiSaoLuu,
        ls.DuongDanFile AS duongDanFile,
        ls.DungLuongByte AS dungLuongByte,
        ls.TrangThai AS trangThai,
        ls.ThoiGianBatDau AS thoiGianBatDau,
        ls.ThoiGianKetThuc AS thoiGianKetThuc,
        ls.ThongBao AS thongBao,
        ls.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung
    FROM dbo.LichSuSaoLuu AS ls
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = ls.MaNguoiDung
    WHERE (@TrangThai IS NULL OR ls.TrangThai = @TrangThai)
      AND (@LoaiSaoLuu IS NULL OR ls.LoaiSaoLuu = @LoaiSaoLuu)
    ORDER BY ls.ThoiGianBatDau DESC, ls.MaSaoLuu DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_PhucHoiDuLieu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_PhucHoiDuLieu
    @MaSaoLuu    INT           = NULL,
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL,
    @ChiTaoLenh   BOOLEAN           = 1
AS
BEGIN
    

    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');

    IF @DuongDanFile IS NULL AND @MaSaoLuu IS NOT NULL
    BEGIN
        SELECT @DuongDanFile = DuongDanFile
        FROM dbo.LichSuSaoLuu
        WHERE MaSaoLuu = @MaSaoLuu
          AND TrangThai = 'Thành công';
    END;

    IF @DuongDanFile IS NULL
        RAISE EXCEPTION %;

    DECLARE @TenDatabase SYSNAME = DB_NAME();
    DECLARE @LenhSingleUser TEXT;
    DECLARE @LenhRestore TEXT;
    DECLARE @LenhMultiUser TEXT;
    DECLARE @LenhDayDu TEXT;

    SET @LenhSingleUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET SINGLE_USER WITH ROLLBACK IMMEDIATE;';
    SET @LenhRestore = 'USE [master]; RESTORE DATABASE ' + QUOTENAME(@TenDatabase) +
        ' FROM DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') + ''' WITH REPLACE;';
    SET @LenhMultiUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET MULTI_USER;';
    SET @LenhDayDu = @LenhSingleUser + CHAR(13) + CHAR(10) + @LenhRestore + CHAR(13) + CHAR(10) + @LenhMultiUser;

    IF @ChiTaoLenh = 1
    BEGIN
        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo lệnh phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;

        SELECT
            @TenDatabase AS tenDatabase,
            @DuongDanFile AS duongDanFile,
            @LenhDayDu AS lenhPhucHoi,
            CAST(1 AS BOOLEAN) AS chiTaoLenh;
        RETURN;
    END;

    BEGIN TRY
        EXEC(@LenhSingleUser);
        EXEC(@LenhRestore);
        EXEC(@LenhMultiUser);

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        BEGIN TRY
            EXEC(@LenhMultiUser);
        END TRY
        BEGIN CATCH
        END CATCH;

        THROW;
    END CATCH;

    SELECT
        @TenDatabase AS tenDatabase,
        @DuongDanFile AS duongDanFile,
        CAST(1 AS BOOLEAN) AS daPhucHoi;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_XemNhatKyHeThong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_XemNhatKyHeThong
    @TuNgay     TIMESTAMP  = NULL,
    @DenNgay    TIMESTAMP  = NULL,
    @AdminId    VARCHAR(6)    = NULL,
    @DoiTuong   VARCHAR(100) = NULL,
    @HanhDong   VARCHAR(100) = NULL,
    @TuKhoa     VARCHAR(100) = NULL,
    @SoDong     INT           = 200
AS
BEGIN
    

    SET @AdminId = NULLIF(TRIM(@AdminId)), '');
    SET @DoiTuong = NULLIF(TRIM(@DoiTuong)), '');
    SET @HanhDong = NULLIF(TRIM(@HanhDong)), '');
    SET @TuKhoa = NULLIF(TRIM(@TuKhoa)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 200;

    SELECT TOP (@SoDong)
        nk.MaNhatKy AS maNhatKy,
        nk.ThoiGian AS thoiGian,
        nk.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung,
        nk.VaiTro AS vaiTro,
        nk.ChucNang AS chucNang,
        nk.HanhDong AS hanhDong,
        nk.DoiTuong AS doiTuong,
        nk.MaDoiTuong AS maDoiTuong,
        nk.NoiDung AS noiDung,
        nk.DuLieuTruoc AS duLieuTruoc,
        nk.DuLieuSau AS duLieuSau
    FROM dbo.NhatKyHeThong AS nk
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nk.MaNguoiDung
    WHERE (@TuNgay IS NULL OR nk.ThoiGian >= @TuNgay)
      AND (@DenNgay IS NULL OR nk.ThoiGian < DATEADD(DAY, 1, @DenNgay))
      AND (@AdminId IS NULL OR nk.MaNguoiDung = @AdminId)
      AND (@DoiTuong IS NULL OR nk.DoiTuong = @DoiTuong)
      AND (@HanhDong IS NULL OR nk.HanhDong LIKE '%' + @HanhDong + '%')
      AND (
          @TuKhoa IS NULL
          OR nk.NoiDung LIKE '%' + @TuKhoa + '%'
          OR nk.MaDoiTuong LIKE '%' + @TuKhoa + '%'
          OR nk.HanhDong LIKE '%' + @TuKhoa + '%'
      )
    ORDER BY nk.ThoiGian DESC, nk.MaNhatKy DESC;
END; THEN (SUBSTRING(MaGiuong, 2, 2)::INT ELSE NULL END)), 0) + 1
            FROM dbo.Giuong 
            WHERE MaPhong = @MaPhong
              AND MaGiuong LIKE 'G[0-9][0-9]';

            IF @SoMaGiuong > 99
                RAISE EXCEPTION %;

            SET @MaGiuong = CONCAT('G', RIGHT(CONCAT('00', @SoMaGiuong), 2));
        END;

        IF EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong)
            RAISE EXCEPTION %;

        BEGIN TRY
            BEGIN TRANSACTION;

            INSERT INTO dbo.Giuong (MaPhong, MaGiuong, SoGiuong, TinhTrang)
            VALUES (@MaPhong, @MaGiuong, @SoGiuong, COALESCE(@TinhTrang, 'Trống'));

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo giường',
                @DoiTuong = 'Giuong',
                @MaDoiTuong = @MaGiuong,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF @SoGiuong IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.Giuong
            WHERE MaPhong = @MaPhong
              AND SoGiuong = @SoGiuong
              AND MaGiuong <> @MaGiuong
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocGiuong TEXT;
        SELECT @DuLieuTruocGiuong = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.Giuong
        SET SoGiuong = COALESCE(@SoGiuong, SoGiuong),
            TinhTrang = COALESCE(@TinhTrang, TinhTrang)
        WHERE MaPhong = @MaPhong
          AND MaGiuong = @MaGiuong;

        UPDATE dbo.Phong
        SET TinhTrang = CASE
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong) THEN 'Trống'
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
            WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
            ELSE 'Còn chỗ'
        END
        WHERE MaPhong = @MaPhong;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật giường',
            @DoiTuong = 'Giuong',
            @MaDoiTuong = @MaGiuong,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocGiuong;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaGiuong IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1 FROM dbo.Giuong
            WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong AND TinhTrang <> 'Trống'
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc AS ctdc
            INNER JOIN dbo.PhieuDatCoc AS pdc ON pdc.MaPhieuDatCoc = ctdc.MaPhieuDatCoc
            WHERE ctdc.MaPhong = @MaPhong
              AND ctdc.MaGiuong = @MaGiuong
              AND pdc.TrangThaiCoc IN ('Hiệu lực', 'Đã lập HĐ')
        )
            RAISE EXCEPTION %;

        IF EXISTS (
            SELECT 1
            FROM dbo.ChiTietDatCoc
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietXemPhong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocGiuongXoa TEXT;
        SELECT @DuLieuTruocGiuongXoa = (
            SELECT * FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuong FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        BEGIN TRY
            BEGIN TRANSACTION;

            DELETE FROM dbo.Giuong
            WHERE MaPhong = @MaPhong
              AND MaGiuong = @MaGiuong;

            UPDATE dbo.Phong
            SET TinhTrang = CASE
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong) THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang <> 'Trống') THEN 'Trống'
                WHEN NOT EXISTS (SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND TinhTrang = 'Trống') THEN 'Đầy'
                ELSE 'Còn chỗ'
            END
            WHERE MaPhong = @MaPhong;

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Xóa giường',
                @DoiTuong = 'Giuong',
                @MaDoiTuong = @MaGiuong,
                @NoiDung = @MaPhong,
                @DuLieuTruoc = @DuLieuTruocGiuongXoa;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaGiuong AS maGiuong;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyGiuong @ThaoTac = 'DANH_SACH', @MaPhong = @MaPhong, @MaGiuong = @MaGiuong;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyTaiSanPhong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyTaiSanPhong
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaPhong   VARCHAR(4)    = NULL,
    @MaTaiSan  VARCHAR(6)    = NULL,
    @TenTaiSan VARCHAR(100) = NULL,
    @SoLuong   INT           = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @LoaiTaiSan VARCHAR(20) = NULL,
    @MaGiuong   VARCHAR(3)   = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaPhong = NULLIF(TRIM(@MaPhong)), '');
    SET @MaTaiSan = NULLIF(TRIM(@MaTaiSan)), '');
    SET @TenTaiSan = NULLIF(TRIM(@TenTaiSan)), '');
    SET @LoaiTaiSan = NULLIF(TRIM(@LoaiTaiSan)), '');
    SET @MaGiuong = NULLIF(TRIM(@MaGiuong)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            ts.MaPhong AS maPhong,
            p.TenPhong AS tenPhong,
            ts.MaTaiSan AS maTaiSan,
            ts.TenTaiSan AS tenTaiSan,
            ts.SoLuong AS soLuong,
            ts.DonGia AS donGia,
            ts.LoaiTaiSan AS loaiTaiSan,
            ts.MaGiuong AS maGiuong,
            g.SoGiuong AS soGiuong
        FROM dbo.TaiSan AS ts
        INNER JOIN dbo.Phong AS p ON p.MaPhong = ts.MaPhong
        LEFT JOIN dbo.Giuong AS g ON g.MaPhong = ts.MaPhong AND g.MaGiuong = ts.MaGiuong
        WHERE (@MaPhong IS NULL OR ts.MaPhong = @MaPhong)
          AND (@MaTaiSan IS NULL OR ts.MaTaiSan = @MaTaiSan)
          AND (@MaGiuong IS NULL OR ts.MaGiuong = @MaGiuong)
          AND (@LoaiTaiSan IS NULL OR ts.LoaiTaiSan = @LoaiTaiSan)
        ORDER BY ts.MaPhong, ts.LoaiTaiSan, ts.MaGiuong, ts.MaTaiSan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @MaPhong IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Phong WHERE MaPhong = @MaPhong)
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TenTaiSan IS NULL
            RAISE EXCEPTION %;

        IF @SoLuong IS NOT NULL AND @SoLuong <= 0
            RAISE EXCEPTION %;

        IF @DonGia IS NOT NULL AND @DonGia < 0
            RAISE EXCEPTION %;

        DECLARE @LoaiTaiSanSau VARCHAR(20);
        DECLARE @MaGiuongSau VARCHAR(3);

        IF @ThaoTac = 'TAO'
        BEGIN
            SET @LoaiTaiSanSau = COALESCE(@LoaiTaiSan, 'Chung');
            SET @MaGiuongSau = @MaGiuong;
        END
        ELSE
        BEGIN
            IF @MaTaiSan IS NULL OR NOT EXISTS (
                SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
            )
                RAISE EXCEPTION %;

            SELECT
                @LoaiTaiSanSau = COALESCE(@LoaiTaiSan, LoaiTaiSan),
                @MaGiuongSau = CASE
                    WHEN @LoaiTaiSan = 'Chung' THEN NULL
                    ELSE COALESCE(@MaGiuong, MaGiuong)
                END
            FROM dbo.TaiSan
            WHERE MaPhong = @MaPhong
              AND MaTaiSan = @MaTaiSan;
        END;

        IF @LoaiTaiSanSau NOT IN ('Chung', 'Riêng')
            RAISE EXCEPTION %;

        IF @LoaiTaiSanSau = 'Chung'
            SET @MaGiuongSau = NULL;

        IF @LoaiTaiSanSau = 'Riêng' AND @MaGiuongSau IS NULL
            RAISE EXCEPTION %;

        IF @MaGiuongSau IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM dbo.Giuong WHERE MaPhong = @MaPhong AND MaGiuong = @MaGiuongSau
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoTaiSan INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaTaiSan IS NULL
            BEGIN
                SELECT @SoTaiSan = COALESCE(MAX(CASE WHEN (SUBSTRING(MaTaiSan, 3, 4) ~ '^[0-9]+)), 0) + 1
                FROM dbo.TaiSan 
                WHERE MaPhong = @MaPhong
                  AND MaTaiSan LIKE 'TS[0-9][0-9][0-9][0-9]';

                IF @SoTaiSan > 9999
                    RAISE EXCEPTION %;

                SET @MaTaiSan = CONCAT('TS', RIGHT(CONCAT('0000', @SoTaiSan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.TaiSan (
                MaPhong, MaTaiSan, TenTaiSan, SoLuong, DonGia, LoaiTaiSan, MaGiuong
            )
            VALUES (
                @MaPhong, @MaTaiSan, @TenTaiSan, COALESCE(@SoLuong, 1),
                @DonGia, @LoaiTaiSanSau, @MaGiuongSau
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo tài sản phòng',
                @DoiTuong = 'TaiSan',
                @MaDoiTuong = @MaTaiSan,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocTaiSan TEXT;
        SELECT @DuLieuTruocTaiSan = (
            SELECT * FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.TaiSan
        SET TenTaiSan = COALESCE(@TenTaiSan, TenTaiSan),
            SoLuong = COALESCE(@SoLuong, SoLuong),
            DonGia = COALESCE(@DonGia, DonGia),
            LoaiTaiSan = @LoaiTaiSanSau,
            MaGiuong = @MaGiuongSau
        WHERE MaPhong = @MaPhong
          AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocTaiSan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietBanGiao WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.ChiTietHuHong WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.YeuCauSuaChua WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaTaiSan AS maTaiSan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyTaiSanPhong
        @ThaoTac = 'DANH_SACH',
        @MaPhong = @MaPhong,
        @MaTaiSan = @MaTaiSan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc
    @ThaoTac           VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinhHoanCoc VARCHAR(6)    = NULL,
    @TenQuyDinh        VARCHAR(255) = NULL,
    @TyLeHoanCoc       DECIMAL(5,2)  = NULL,
    @AdminId           VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinhHoanCoc = NULLIF(TRIM(@MaQuyDinhHoanCoc)), '');
    SET @TenQuyDinh = NULLIF(TRIM(@TenQuyDinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qh.MaQuyDinhHoanCoc AS maQuyDinhHoanCoc,
            qh.TenQuyDinh AS tenQuyDinh,
            qh.TyLeHoanCoc AS tyLeHoanCoc,
            COUNT(ds.MaQuyDinhHoanCoc) AS soLanApDung
        FROM dbo.QuyDinhHoanCoc AS qh
        LEFT JOIN dbo.DoiSoat AS ds ON ds.MaQuyDinhHoanCoc = qh.MaQuyDinhHoanCoc
        WHERE (@MaQuyDinhHoanCoc IS NULL OR qh.MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
        GROUP BY qh.MaQuyDinhHoanCoc, qh.TenQuyDinh, qh.TyLeHoanCoc
        ORDER BY qh.MaQuyDinhHoanCoc;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenQuyDinh IS NULL OR @TyLeHoanCoc IS NULL)
            RAISE EXCEPTION %;

        IF @TyLeHoanCoc IS NOT NULL AND (@TyLeHoanCoc < 0 OR @TyLeHoanCoc > 100)
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinh INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinhHoanCoc IS NULL
            BEGIN
                SELECT @SoQuyDinh = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinhHoanCoc, 3, 4))), 0) + 1
                FROM dbo.QuyDinhHoanCoc 
                WHERE MaQuyDinhHoanCoc LIKE 'QH[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinh > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinhHoanCoc = CONCAT('QH', RIGHT(CONCAT('0000', @SoQuyDinh), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuyDinhHoanCoc (MaQuyDinhHoanCoc, TenQuyDinh, TyLeHoanCoc)
            VALUES (@MaQuyDinhHoanCoc, @TenQuyDinh, @TyLeHoanCoc);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo quy định hoàn cọc',
                @DoiTuong = 'QuyDinhHoanCoc',
                @MaDoiTuong = @MaQuyDinhHoanCoc,
                @NoiDung = @TenQuyDinh;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocHoanCoc TEXT;
        SELECT @DuLieuTruocHoanCoc = (
            SELECT * FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuyDinhHoanCoc
        SET TenQuyDinh = COALESCE(@TenQuyDinh, TenQuyDinh),
            TyLeHoanCoc = COALESCE(@TyLeHoanCoc, TyLeHoanCoc)
        WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc,
            @DuLieuTruoc = @DuLieuTruocHoanCoc;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DoiSoat WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinhHoanCoc AS maQuyDinhHoanCoc;
        RETURN;
    END;

    EXEC dbo.SP_Admin_CauHinhQuyDinhHoanCoc @ThaoTac = 'DANH_SACH', @MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDichVu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDichVu
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaDichVu  VARCHAR(6)    = NULL,
    @TenDichVu VARCHAR(100) = NULL,
    @DonViTinh VARCHAR(20)   = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDichVu = NULLIF(TRIM(@MaDichVu)), '');
    SET @TenDichVu = NULLIF(TRIM(@TenDichVu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dv.MaDichVu AS maDichVu,
            dv.TenDichVu AS tenDichVu,
            dv.DonViTinh AS donViTinh,
            dv.DonGia AS donGia,
            COUNT(DISTINCT dvhd.MaChiTietDVHD) AS soHopDongSuDung,
            COUNT(cthd.MaChiTietHD) AS soDongHoaDon
        FROM dbo.DichVu AS dv
        LEFT JOIN dbo.DichVuHopDong AS dvhd ON dvhd.MaDichVu = dv.MaDichVu
        LEFT JOIN dbo.ChiTietHoaDon AS cthd ON cthd.MaChiTietDVHD = dvhd.MaChiTietDVHD
        WHERE (@MaDichVu IS NULL OR dv.MaDichVu = @MaDichVu)
          AND (@TenDichVu IS NULL OR dv.TenDichVu LIKE '%' + @TenDichVu + '%')
        GROUP BY dv.MaDichVu, dv.TenDichVu, dv.DonViTinh, dv.DonGia
        ORDER BY dv.MaDichVu;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDichVu IS NULL OR @DonViTinh IS NULL OR @DonGia IS NULL)
            THROW 51202, 'Vui lòng nhập tên dịch vụ, đơn vị tính và đơn giá.', 1;

        IF @DonGia IS NOT NULL AND @DonGia <= 0
            RAISE EXCEPTION %;

        IF @TenDichVu IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DichVu
            WHERE TenDichVu = @TenDichVu
              AND (@MaDichVu IS NULL OR MaDichVu <> @MaDichVu)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDichVu INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDichVu IS NULL
            BEGIN
                SELECT @SoDichVu = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDichVu, 3, 4))), 0) + 1
                FROM dbo.DichVu 
                WHERE MaDichVu LIKE 'DV[0-9][0-9][0-9][0-9]';

                IF @SoDichVu > 9999
                    RAISE EXCEPTION %;

                SET @MaDichVu = CONCAT('DV', RIGHT(CONCAT('0000', @SoDichVu), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DichVu (MaDichVu, TenDichVu, DonViTinh, DonGia)
            VALUES (@MaDichVu, @TenDichVu, @DonViTinh, @DonGia);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo dịch vụ',
                @DoiTuong = 'DichVu',
                @MaDoiTuong = @MaDichVu,
                @NoiDung = @TenDichVu;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocDichVu TEXT;
        SELECT @DuLieuTruocDichVu = (
            SELECT * FROM dbo.DichVu WHERE MaDichVu = @MaDichVu FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DichVu
        SET TenDichVu = COALESCE(@TenDichVu, TenDichVu),
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            DonGia = COALESCE(@DonGia, DonGia)
        WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu,
            @DuLieuTruoc = @DuLieuTruocDichVu;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DichVuHopDong WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DichVu WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDichVu AS maDichVu;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDichVu @ThaoTac = 'DANH_SACH', @MaDichVu = @MaDichVu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyNoiQuy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyNoiQuy
    @ThaoTac      VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinh    VARCHAR(6)    = NULL,
    @TieuDeNoiQuy VARCHAR(255) = NULL,
    @NoiDung      TEXT = NULL,
    @TrangThai    VARCHAR(20)  = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinh = NULLIF(TRIM(@MaQuyDinh)), '');
    SET @TieuDeNoiQuy = NULLIF(TRIM(@TieuDeNoiQuy)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qd.MaQuyDinh AS maQuyDinh,
            qd.TieuDeNoiQuy AS tieuDeNoiQuy,
            qd.NoiDung AS noiDung,
            qd.TrangThai AS trangThai
        FROM dbo.QuiDinh AS qd
        WHERE (@MaQuyDinh IS NULL OR qd.MaQuyDinh = @MaQuyDinh)
          AND (@TrangThai IS NULL OR qd.TrangThai = @TrangThai)
          AND (@TieuDeNoiQuy IS NULL OR qd.TieuDeNoiQuy LIKE '%' + @TieuDeNoiQuy + '%')
        ORDER BY qd.MaQuyDinh;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TieuDeNoiQuy IS NULL
            RAISE EXCEPTION %;

        IF @TieuDeNoiQuy IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.QuiDinh
            WHERE TieuDeNoiQuy = @TieuDeNoiQuy
              AND (@MaQuyDinh IS NULL OR MaQuyDinh <> @MaQuyDinh)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinhNoiQuy INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinh IS NULL
            BEGIN
                SELECT @SoQuyDinhNoiQuy = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinh, 3, 4))), 0) + 1
                FROM dbo.QuiDinh 
                WHERE MaQuyDinh LIKE 'QD[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinhNoiQuy > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinh = CONCAT('QD', RIGHT(CONCAT('0000', @SoQuyDinhNoiQuy), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuiDinh (MaQuyDinh, TieuDeNoiQuy, NoiDung, TrangThai)
            VALUES (@MaQuyDinh, @TieuDeNoiQuy, @NoiDung, COALESCE(@TrangThai, 'Hiệu lực'));

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo nội quy',
                @DoiTuong = 'QuiDinh',
                @MaDoiTuong = @MaQuyDinh,
                @NoiDung = @TieuDeNoiQuy;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocNoiQuy TEXT;
        SELECT @DuLieuTruocNoiQuy = (
            SELECT * FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuiDinh
        SET TieuDeNoiQuy = COALESCE(@TieuDeNoiQuy, TieuDeNoiQuy),
            NoiDung = COALESCE(@NoiDung, NoiDung),
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh,
            @DuLieuTruoc = @DuLieuTruocNoiQuy;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        UPDATE dbo.QuiDinh
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinh AS maQuyDinh;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyNoiQuy @ThaoTac = 'DANH_SACH', @MaQuyDinh = @MaQuyDinh;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham
    @ThaoTac        VARCHAR(20)  = 'DANH_SACH',
    @MaDieuKhoan    VARCHAR(6)    = NULL,
    @TenDieuKhoan   VARCHAR(255) = NULL,
    @HinhThucXuPhat VARCHAR(20)  = NULL,
    @MucPhat        DECIMAL(15,2) = NULL,
    @TrangThai      VARCHAR(20)  = NULL,
    @AdminId        VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDieuKhoan = NULLIF(TRIM(@MaDieuKhoan)), '');
    SET @TenDieuKhoan = NULLIF(TRIM(@TenDieuKhoan)), '');
    SET @HinhThucXuPhat = NULLIF(TRIM(@HinhThucXuPhat)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dk.MaDieuKhoan AS maDieuKhoan,
            dk.TenDieuKhoan AS tenDieuKhoan,
            dk.HinhThucXuPhat AS hinhThucXuPhat,
            dk.MucPhat AS mucPhat,
            dk.TrangThai AS trangThai,
            COUNT(bb.MaBBViPham) AS soBienBanApDung
        FROM dbo.DieuKhoanViPham AS dk
        LEFT JOIN dbo.BienBanViPham AS bb ON bb.MaDieuKhoan = dk.MaDieuKhoan
        WHERE (@MaDieuKhoan IS NULL OR dk.MaDieuKhoan = @MaDieuKhoan)
          AND (@TrangThai IS NULL OR dk.TrangThai = @TrangThai)
          AND (@TenDieuKhoan IS NULL OR dk.TenDieuKhoan LIKE '%' + @TenDieuKhoan + '%')
        GROUP BY dk.MaDieuKhoan, dk.TenDieuKhoan, dk.HinhThucXuPhat, dk.MucPhat, dk.TrangThai
        ORDER BY dk.MaDieuKhoan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @HinhThucXuPhat IS NOT NULL AND @HinhThucXuPhat NOT IN ('Nhắc nhở', 'Phạt tiền')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @MucPhat IS NOT NULL AND @MucPhat < 0
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDieuKhoan IS NULL OR @HinhThucXuPhat IS NULL)
            RAISE EXCEPTION %;

        IF @TenDieuKhoan IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DieuKhoanViPham
            WHERE TenDieuKhoan = @TenDieuKhoan
              AND (@MaDieuKhoan IS NULL OR MaDieuKhoan <> @MaDieuKhoan)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDieuKhoan INT;

        IF @HinhThucXuPhat = 'Phạt tiền' AND COALESCE(@MucPhat, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucXuPhat = 'Nhắc nhở' AND @MucPhat IS NULL
            SET @MucPhat = 0;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDieuKhoan IS NULL
            BEGIN
                SELECT @SoDieuKhoan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDieuKhoan, 3, 4))), 0) + 1
                FROM dbo.DieuKhoanViPham 
                WHERE MaDieuKhoan LIKE 'VP[0-9][0-9][0-9][0-9]';

                IF @SoDieuKhoan > 9999
                    RAISE EXCEPTION %;

                SET @MaDieuKhoan = CONCAT('VP', RIGHT(CONCAT('0000', @SoDieuKhoan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DieuKhoanViPham (
                MaDieuKhoan, TenDieuKhoan, HinhThucXuPhat, MucPhat, TrangThai
            )
            VALUES (
                @MaDieuKhoan, @TenDieuKhoan, @HinhThucXuPhat, COALESCE(@MucPhat, 0), COALESCE(@TrangThai, 'Hiệu lực')
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo điều khoản vi phạm',
                @DoiTuong = 'DieuKhoanViPham',
                @MaDoiTuong = @MaDieuKhoan,
                @NoiDung = @TenDieuKhoan;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DECLARE @HinhThucSau VARCHAR(20);
        DECLARE @MucPhatSau DECIMAL(15,2);

        SELECT
            @HinhThucSau = COALESCE(@HinhThucXuPhat, HinhThucXuPhat),
            @MucPhatSau = COALESCE(@MucPhat, MucPhat)
        FROM dbo.DieuKhoanViPham
        WHERE MaDieuKhoan = @MaDieuKhoan;

        IF @HinhThucSau = 'Phạt tiền' AND COALESCE(@MucPhatSau, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucSau = 'Nhắc nhở' AND @MucPhatSau IS NULL
            SET @MucPhatSau = 0;

        DECLARE @DuLieuTruocDieuKhoan TEXT;
        SELECT @DuLieuTruocDieuKhoan = (
            SELECT * FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DieuKhoanViPham
        SET TenDieuKhoan = COALESCE(@TenDieuKhoan, TenDieuKhoan),
            HinhThucXuPhat = @HinhThucSau,
            MucPhat = @MucPhatSau,
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan,
            @DuLieuTruoc = @DuLieuTruocDieuKhoan;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        UPDATE dbo.DieuKhoanViPham
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.BienBanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDieuKhoan AS maDieuKhoan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDieuKhoanViPham @ThaoTac = 'DANH_SACH', @MaDieuKhoan = @MaDieuKhoan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhThamSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhThamSo
    @ThaoTac    VARCHAR(20)  = 'DANH_SACH',
    @MaThamSo   VARCHAR(50)   = NULL,
    @NhomThamSo VARCHAR(50)  = NULL,
    @TenThamSo  VARCHAR(100) = NULL,
    @GiaTri     VARCHAR(255) = NULL,
    @KieuDuLieu VARCHAR(20)  = NULL,
    @DonViTinh  VARCHAR(30)  = NULL,
    @MoTa       TEXT = NULL,
    @AdminId    VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaThamSo = NULLIF(TRIM(@MaThamSo)), '');
    SET @NhomThamSo = NULLIF(TRIM(@NhomThamSo)), '');
    SET @TenThamSo = NULLIF(TRIM(@TenThamSo)), '');
    SET @GiaTri = NULLIF(TRIM(@GiaTri)), '');
    SET @KieuDuLieu = NULLIF(TRIM(@KieuDuLieu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            MaThamSo AS maThamSo,
            NhomThamSo AS nhomThamSo,
            TenThamSo AS tenThamSo,
            GiaTri AS giaTri,
            KieuDuLieu AS kieuDuLieu,
            DonViTinh AS donViTinh,
            MoTa AS moTa,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.ThamSoHeThong
        WHERE (@MaThamSo IS NULL OR MaThamSo = @MaThamSo)
          AND (@NhomThamSo IS NULL OR NhomThamSo = @NhomThamSo)
        ORDER BY NhomThamSo, MaThamSo;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT')
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO' AND (@MaThamSo IS NULL OR @NhomThamSo IS NULL OR @TenThamSo IS NULL OR @GiaTri IS NULL)
        THROW 51262, 'Vui lòng nhập đủ mã, nhóm, tên và giá trị tham số.', 1;

    IF @MaThamSo IS NULL
        RAISE EXCEPTION %;

    IF @KieuDuLieu IS NOT NULL AND @KieuDuLieu NOT IN ('Chuỗi', 'Số', 'Ngày', 'Boolean')
        RAISE EXCEPTION %;

    DECLARE @KieuDuLieuSau VARCHAR(20);
    DECLARE @GiaTriSau VARCHAR(255);

    IF @ThaoTac = 'TAO'
    BEGIN
        SET @KieuDuLieuSau = COALESCE(@KieuDuLieu, 'Chuỗi');
        SET @GiaTriSau = @GiaTri;
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        SELECT
            @KieuDuLieuSau = COALESCE(@KieuDuLieu, KieuDuLieu),
            @GiaTriSau = COALESCE(@GiaTri, GiaTri)
        FROM dbo.ThamSoHeThong
        WHERE MaThamSo = @MaThamSo;
    END;

    IF @KieuDuLieuSau = 'Số' AND (TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) IS NULL OR TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) < 0)
        RAISE EXCEPTION %;

    IF @MaThamSo = 'THOI_HAN_THANH_TOAN_COC_GIO'
       AND (TRY_CONVERT(INT, @GiaTriSau) IS NULL OR TRY_CONVERT(INT, @GiaTriSau) <= 0)
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        INSERT INTO dbo.ThamSoHeThong (
            MaThamSo, NhomThamSo, TenThamSo, GiaTri, KieuDuLieu, DonViTinh, MoTa, CapNhatBoi
        )
        VALUES (
            @MaThamSo, @NhomThamSo, @TenThamSo, @GiaTriSau, @KieuDuLieuSau, @DonViTinh, @MoTa, @AdminId
        );

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @NoiDung = @TenThamSo;
    END
    ELSE
    BEGIN
        DECLARE @DuLieuTruocThamSo TEXT;
        SELECT @DuLieuTruocThamSo = (
            SELECT * FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.ThamSoHeThong
        SET NhomThamSo = COALESCE(@NhomThamSo, NhomThamSo),
            TenThamSo = COALESCE(@TenThamSo, TenThamSo),
            GiaTri = @GiaTriSau,
            KieuDuLieu = @KieuDuLieuSau,
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            MoTa = COALESCE(@MoTa, MoTa),
            CapNhatLuc = CURRENT_TIMESTAMP,
            CapNhatBoi = @AdminId
        WHERE MaThamSo = @MaThamSo;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @DuLieuTruoc = @DuLieuTruocThamSo;
    END;

    EXEC dbo.SP_Admin_CauHinhThamSo @ThaoTac = 'DANH_SACH', @MaThamSo = @MaThamSo;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhSaoLuu
    @ChuKyFull        VARCHAR(20)  = NULL,
    @ChuKyIncremental VARCHAR(20)  = NULL,
    @ThuMucLuuTru     VARCHAR(500) = NULL,
    @AdminId          VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ChuKyFull = NULLIF(TRIM(@ChuKyFull)), '');
    SET @ChuKyIncremental = NULLIF(TRIM(@ChuKyIncremental)), '');
    SET @ThuMucLuuTru = NULLIF(TRIM(@ThuMucLuuTru)), '');

    IF @ChuKyFull IS NOT NULL AND @ChuKyFull NOT IN ('Hàng tuần', 'Hàng tháng')
        RAISE EXCEPTION %;

    IF @ChuKyIncremental IS NOT NULL AND @ChuKyIncremental NOT IN ('Hàng ngày', 'Hàng tuần')
        RAISE EXCEPTION %;

    IF @ThuMucLuuTru IS NOT NULL
    BEGIN
        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);
    END;

    IF @ChuKyFull IS NULL AND @ChuKyIncremental IS NULL AND @ThuMucLuuTru IS NULL
    BEGIN
        SELECT
            MaCauHinh AS maCauHinh,
            ChuKyFull AS chuKyFull,
            ChuKyIncremental AS chuKyIncremental,
            ThuMucLuuTru AS thuMucLuuTru,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;
        RETURN;
    END;

    DECLARE @DuLieuTruocSaoLuu TEXT;
    SELECT @DuLieuTruocSaoLuu = (
        SELECT * FROM dbo.CauHinhSaoLuu WHERE MaCauHinh = 1 FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    UPDATE dbo.CauHinhSaoLuu
    SET ChuKyFull = COALESCE(@ChuKyFull, ChuKyFull),
        ChuKyIncremental = COALESCE(@ChuKyIncremental, ChuKyIncremental),
        ThuMucLuuTru = COALESCE(@ThuMucLuuTru, ThuMucLuuTru),
        CapNhatLuc = CURRENT_TIMESTAMP,
        CapNhatBoi = @AdminId
    WHERE MaCauHinh = 1;

    EXEC dbo.SP_Admin_GhiNhatKy
        @AdminId = @AdminId,
        @HanhDong = 'Cấu hình sao lưu',
        @DoiTuong = 'CauHinhSaoLuu',
        @MaDoiTuong = '1',
        @DuLieuTruoc = @DuLieuTruocSaoLuu;

    SELECT
        MaCauHinh AS maCauHinh,
        ChuKyFull AS chuKyFull,
        ChuKyIncremental AS chuKyIncremental,
        ThuMucLuuTru AS thuMucLuuTru,
        CapNhatLuc AS capNhatLuc,
        CapNhatBoi AS capNhatBoi
    FROM dbo.CauHinhSaoLuu
    WHERE MaCauHinh = 1;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_SaoLuuThuCong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_SaoLuuThuCong
    @LoaiSaoLuu  VARCHAR(20)  = 'Full',
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    

    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');
    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');
    IF @LoaiSaoLuu IS NULL SET @LoaiSaoLuu = 'Full';

    DECLARE @LoaiSaoLuuChuan VARCHAR(20) = UPPER(@LoaiSaoLuu);
    IF @LoaiSaoLuuChuan = 'FULL'
        SET @LoaiSaoLuu = 'Full';
    ELSE IF @LoaiSaoLuuChuan IN ('INCREMENTAL', 'DIFFERENTIAL')
        SET @LoaiSaoLuu = 'Incremental';

    IF @LoaiSaoLuu NOT IN ('Full', 'Incremental')
        RAISE EXCEPTION %;

    IF @DuongDanFile IS NULL
    BEGIN
        DECLARE @ThuMucLuuTru VARCHAR(500);
        SELECT @ThuMucLuuTru = ThuMucLuuTru
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;

        IF @ThuMucLuuTru IS NULL
            RAISE EXCEPTION %;

        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);

        SET @DuongDanFile =
            @ThuMucLuuTru + '\' + DB_NAME() + '_' + @LoaiSaoLuu + '_' +
            CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112) + REPLACE(CONVERT(CHAR(8), CURRENT_TIMESTAMP, 108), ':', '') + '.bak';
    END;

    DECLARE @MaSaoLuu INT;
    DECLARE @LenhSaoLuu TEXT;

    INSERT INTO dbo.LichSuSaoLuu (
        LoaiSaoLuu, DuongDanFile, TrangThai, ThoiGianBatDau, MaNguoiDung
    )
    VALUES (
        @LoaiSaoLuu, @DuongDanFile, 'Đang chạy', CURRENT_TIMESTAMP, @AdminId
    );

    SET @MaSaoLuu = SCOPE_IDENTITY();
    SET @LenhSaoLuu =
        'BACKUP DATABASE ' + QUOTENAME(DB_NAME()) +
        ' TO DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') +
        ''' WITH ' +
        CASE WHEN @LoaiSaoLuu = 'Incremental' THEN 'DIFFERENTIAL, INIT' ELSE 'INIT' END +
        ';';

    BEGIN TRY
        EXEC(@LenhSaoLuu);

        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thành công',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = 'Sao lưu hoàn tất.'
        WHERE MaSaoLuu = @MaSaoLuu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Sao lưu thủ công',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thất bại',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = ERROR_MESSAGE()
        WHERE MaSaoLuu = @MaSaoLuu;

        THROW;
    END CATCH;

    SELECT
        MaSaoLuu AS maSaoLuu,
        LoaiSaoLuu AS loaiSaoLuu,
        DuongDanFile AS duongDanFile,
        TrangThai AS trangThai,
        ThoiGianBatDau AS thoiGianBatDau,
        ThoiGianKetThuc AS thoiGianKetThuc,
        ThongBao AS thongBao
    FROM dbo.LichSuSaoLuu
    WHERE MaSaoLuu = @MaSaoLuu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_DanhSachSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_DanhSachSaoLuu
    @SoDong     INT          = 100,
    @TrangThai  VARCHAR(20) = NULL,
    @LoaiSaoLuu VARCHAR(20) = NULL
AS
BEGIN
    

    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 100;

    SELECT TOP (@SoDong)
        ls.MaSaoLuu AS maSaoLuu,
        ls.LoaiSaoLuu AS loaiSaoLuu,
        ls.DuongDanFile AS duongDanFile,
        ls.DungLuongByte AS dungLuongByte,
        ls.TrangThai AS trangThai,
        ls.ThoiGianBatDau AS thoiGianBatDau,
        ls.ThoiGianKetThuc AS thoiGianKetThuc,
        ls.ThongBao AS thongBao,
        ls.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung
    FROM dbo.LichSuSaoLuu AS ls
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = ls.MaNguoiDung
    WHERE (@TrangThai IS NULL OR ls.TrangThai = @TrangThai)
      AND (@LoaiSaoLuu IS NULL OR ls.LoaiSaoLuu = @LoaiSaoLuu)
    ORDER BY ls.ThoiGianBatDau DESC, ls.MaSaoLuu DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_PhucHoiDuLieu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_PhucHoiDuLieu
    @MaSaoLuu    INT           = NULL,
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL,
    @ChiTaoLenh   BOOLEAN           = 1
AS
BEGIN
    

    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');

    IF @DuongDanFile IS NULL AND @MaSaoLuu IS NOT NULL
    BEGIN
        SELECT @DuongDanFile = DuongDanFile
        FROM dbo.LichSuSaoLuu
        WHERE MaSaoLuu = @MaSaoLuu
          AND TrangThai = 'Thành công';
    END;

    IF @DuongDanFile IS NULL
        RAISE EXCEPTION %;

    DECLARE @TenDatabase SYSNAME = DB_NAME();
    DECLARE @LenhSingleUser TEXT;
    DECLARE @LenhRestore TEXT;
    DECLARE @LenhMultiUser TEXT;
    DECLARE @LenhDayDu TEXT;

    SET @LenhSingleUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET SINGLE_USER WITH ROLLBACK IMMEDIATE;';
    SET @LenhRestore = 'USE [master]; RESTORE DATABASE ' + QUOTENAME(@TenDatabase) +
        ' FROM DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') + ''' WITH REPLACE;';
    SET @LenhMultiUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET MULTI_USER;';
    SET @LenhDayDu = @LenhSingleUser + CHAR(13) + CHAR(10) + @LenhRestore + CHAR(13) + CHAR(10) + @LenhMultiUser;

    IF @ChiTaoLenh = 1
    BEGIN
        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo lệnh phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;

        SELECT
            @TenDatabase AS tenDatabase,
            @DuongDanFile AS duongDanFile,
            @LenhDayDu AS lenhPhucHoi,
            CAST(1 AS BOOLEAN) AS chiTaoLenh;
        RETURN;
    END;

    BEGIN TRY
        EXEC(@LenhSingleUser);
        EXEC(@LenhRestore);
        EXEC(@LenhMultiUser);

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        BEGIN TRY
            EXEC(@LenhMultiUser);
        END TRY
        BEGIN CATCH
        END CATCH;

        THROW;
    END CATCH;

    SELECT
        @TenDatabase AS tenDatabase,
        @DuongDanFile AS duongDanFile,
        CAST(1 AS BOOLEAN) AS daPhucHoi;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_XemNhatKyHeThong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_XemNhatKyHeThong
    @TuNgay     TIMESTAMP  = NULL,
    @DenNgay    TIMESTAMP  = NULL,
    @AdminId    VARCHAR(6)    = NULL,
    @DoiTuong   VARCHAR(100) = NULL,
    @HanhDong   VARCHAR(100) = NULL,
    @TuKhoa     VARCHAR(100) = NULL,
    @SoDong     INT           = 200
AS
BEGIN
    

    SET @AdminId = NULLIF(TRIM(@AdminId)), '');
    SET @DoiTuong = NULLIF(TRIM(@DoiTuong)), '');
    SET @HanhDong = NULLIF(TRIM(@HanhDong)), '');
    SET @TuKhoa = NULLIF(TRIM(@TuKhoa)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 200;

    SELECT TOP (@SoDong)
        nk.MaNhatKy AS maNhatKy,
        nk.ThoiGian AS thoiGian,
        nk.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung,
        nk.VaiTro AS vaiTro,
        nk.ChucNang AS chucNang,
        nk.HanhDong AS hanhDong,
        nk.DoiTuong AS doiTuong,
        nk.MaDoiTuong AS maDoiTuong,
        nk.NoiDung AS noiDung,
        nk.DuLieuTruoc AS duLieuTruoc,
        nk.DuLieuSau AS duLieuSau
    FROM dbo.NhatKyHeThong AS nk
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nk.MaNguoiDung
    WHERE (@TuNgay IS NULL OR nk.ThoiGian >= @TuNgay)
      AND (@DenNgay IS NULL OR nk.ThoiGian < DATEADD(DAY, 1, @DenNgay))
      AND (@AdminId IS NULL OR nk.MaNguoiDung = @AdminId)
      AND (@DoiTuong IS NULL OR nk.DoiTuong = @DoiTuong)
      AND (@HanhDong IS NULL OR nk.HanhDong LIKE '%' + @HanhDong + '%')
      AND (
          @TuKhoa IS NULL
          OR nk.NoiDung LIKE '%' + @TuKhoa + '%'
          OR nk.MaDoiTuong LIKE '%' + @TuKhoa + '%'
          OR nk.HanhDong LIKE '%' + @TuKhoa + '%'
      )
    ORDER BY nk.ThoiGian DESC, nk.MaNhatKy DESC;
END; THEN (SUBSTRING(MaTaiSan, 3, 4)::INT ELSE NULL END)), 0) + 1
                FROM dbo.TaiSan 
                WHERE MaPhong = @MaPhong
                  AND MaTaiSan LIKE 'TS[0-9][0-9][0-9][0-9]';

                IF @SoTaiSan > 9999
                    RAISE EXCEPTION %;

                SET @MaTaiSan = CONCAT('TS', RIGHT(CONCAT('0000', @SoTaiSan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.TaiSan (
                MaPhong, MaTaiSan, TenTaiSan, SoLuong, DonGia, LoaiTaiSan, MaGiuong
            )
            VALUES (
                @MaPhong, @MaTaiSan, @TenTaiSan, COALESCE(@SoLuong, 1),
                @DonGia, @LoaiTaiSanSau, @MaGiuongSau
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo tài sản phòng',
                @DoiTuong = 'TaiSan',
                @MaDoiTuong = @MaTaiSan,
                @NoiDung = @MaPhong;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocTaiSan TEXT;
        SELECT @DuLieuTruocTaiSan = (
            SELECT * FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.TaiSan
        SET TenTaiSan = COALESCE(@TenTaiSan, TenTaiSan),
            SoLuong = COALESCE(@SoLuong, SoLuong),
            DonGia = COALESCE(@DonGia, DonGia),
            LoaiTaiSan = @LoaiTaiSanSau,
            MaGiuong = @MaGiuongSau
        WHERE MaPhong = @MaPhong
          AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong,
            @DuLieuTruoc = @DuLieuTruocTaiSan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaTaiSan IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.ChiTietBanGiao WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.ChiTietHuHong WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
           OR EXISTS (SELECT 1 FROM dbo.YeuCauSuaChua WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.TaiSan WHERE MaPhong = @MaPhong AND MaTaiSan = @MaTaiSan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa tài sản phòng',
            @DoiTuong = 'TaiSan',
            @MaDoiTuong = @MaTaiSan,
            @NoiDung = @MaPhong;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaPhong AS maPhong, @MaTaiSan AS maTaiSan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyTaiSanPhong
        @ThaoTac = 'DANH_SACH',
        @MaPhong = @MaPhong,
        @MaTaiSan = @MaTaiSan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhQuyDinhHoanCoc
    @ThaoTac           VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinhHoanCoc VARCHAR(6)    = NULL,
    @TenQuyDinh        VARCHAR(255) = NULL,
    @TyLeHoanCoc       DECIMAL(5,2)  = NULL,
    @AdminId           VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinhHoanCoc = NULLIF(TRIM(@MaQuyDinhHoanCoc)), '');
    SET @TenQuyDinh = NULLIF(TRIM(@TenQuyDinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qh.MaQuyDinhHoanCoc AS maQuyDinhHoanCoc,
            qh.TenQuyDinh AS tenQuyDinh,
            qh.TyLeHoanCoc AS tyLeHoanCoc,
            COUNT(ds.MaQuyDinhHoanCoc) AS soLanApDung
        FROM dbo.QuyDinhHoanCoc AS qh
        LEFT JOIN dbo.DoiSoat AS ds ON ds.MaQuyDinhHoanCoc = qh.MaQuyDinhHoanCoc
        WHERE (@MaQuyDinhHoanCoc IS NULL OR qh.MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
        GROUP BY qh.MaQuyDinhHoanCoc, qh.TenQuyDinh, qh.TyLeHoanCoc
        ORDER BY qh.MaQuyDinhHoanCoc;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenQuyDinh IS NULL OR @TyLeHoanCoc IS NULL)
            RAISE EXCEPTION %;

        IF @TyLeHoanCoc IS NOT NULL AND (@TyLeHoanCoc < 0 OR @TyLeHoanCoc > 100)
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinh INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinhHoanCoc IS NULL
            BEGIN
                SELECT @SoQuyDinh = COALESCE(MAX(CASE WHEN (SUBSTRING(MaQuyDinhHoanCoc, 3, 4) ~ '^[0-9]+)), 0) + 1
                FROM dbo.QuyDinhHoanCoc 
                WHERE MaQuyDinhHoanCoc LIKE 'QH[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinh > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinhHoanCoc = CONCAT('QH', RIGHT(CONCAT('0000', @SoQuyDinh), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuyDinhHoanCoc (MaQuyDinhHoanCoc, TenQuyDinh, TyLeHoanCoc)
            VALUES (@MaQuyDinhHoanCoc, @TenQuyDinh, @TyLeHoanCoc);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo quy định hoàn cọc',
                @DoiTuong = 'QuyDinhHoanCoc',
                @MaDoiTuong = @MaQuyDinhHoanCoc,
                @NoiDung = @TenQuyDinh;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocHoanCoc TEXT;
        SELECT @DuLieuTruocHoanCoc = (
            SELECT * FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuyDinhHoanCoc
        SET TenQuyDinh = COALESCE(@TenQuyDinh, TenQuyDinh),
            TyLeHoanCoc = COALESCE(@TyLeHoanCoc, TyLeHoanCoc)
        WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc,
            @DuLieuTruoc = @DuLieuTruocHoanCoc;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DoiSoat WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinhHoanCoc AS maQuyDinhHoanCoc;
        RETURN;
    END;

    EXEC dbo.SP_Admin_CauHinhQuyDinhHoanCoc @ThaoTac = 'DANH_SACH', @MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDichVu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDichVu
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaDichVu  VARCHAR(6)    = NULL,
    @TenDichVu VARCHAR(100) = NULL,
    @DonViTinh VARCHAR(20)   = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDichVu = NULLIF(TRIM(@MaDichVu)), '');
    SET @TenDichVu = NULLIF(TRIM(@TenDichVu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dv.MaDichVu AS maDichVu,
            dv.TenDichVu AS tenDichVu,
            dv.DonViTinh AS donViTinh,
            dv.DonGia AS donGia,
            COUNT(DISTINCT dvhd.MaChiTietDVHD) AS soHopDongSuDung,
            COUNT(cthd.MaChiTietHD) AS soDongHoaDon
        FROM dbo.DichVu AS dv
        LEFT JOIN dbo.DichVuHopDong AS dvhd ON dvhd.MaDichVu = dv.MaDichVu
        LEFT JOIN dbo.ChiTietHoaDon AS cthd ON cthd.MaChiTietDVHD = dvhd.MaChiTietDVHD
        WHERE (@MaDichVu IS NULL OR dv.MaDichVu = @MaDichVu)
          AND (@TenDichVu IS NULL OR dv.TenDichVu LIKE '%' + @TenDichVu + '%')
        GROUP BY dv.MaDichVu, dv.TenDichVu, dv.DonViTinh, dv.DonGia
        ORDER BY dv.MaDichVu;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDichVu IS NULL OR @DonViTinh IS NULL OR @DonGia IS NULL)
            THROW 51202, 'Vui lòng nhập tên dịch vụ, đơn vị tính và đơn giá.', 1;

        IF @DonGia IS NOT NULL AND @DonGia <= 0
            RAISE EXCEPTION %;

        IF @TenDichVu IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DichVu
            WHERE TenDichVu = @TenDichVu
              AND (@MaDichVu IS NULL OR MaDichVu <> @MaDichVu)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDichVu INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDichVu IS NULL
            BEGIN
                SELECT @SoDichVu = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDichVu, 3, 4))), 0) + 1
                FROM dbo.DichVu 
                WHERE MaDichVu LIKE 'DV[0-9][0-9][0-9][0-9]';

                IF @SoDichVu > 9999
                    RAISE EXCEPTION %;

                SET @MaDichVu = CONCAT('DV', RIGHT(CONCAT('0000', @SoDichVu), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DichVu (MaDichVu, TenDichVu, DonViTinh, DonGia)
            VALUES (@MaDichVu, @TenDichVu, @DonViTinh, @DonGia);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo dịch vụ',
                @DoiTuong = 'DichVu',
                @MaDoiTuong = @MaDichVu,
                @NoiDung = @TenDichVu;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocDichVu TEXT;
        SELECT @DuLieuTruocDichVu = (
            SELECT * FROM dbo.DichVu WHERE MaDichVu = @MaDichVu FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DichVu
        SET TenDichVu = COALESCE(@TenDichVu, TenDichVu),
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            DonGia = COALESCE(@DonGia, DonGia)
        WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu,
            @DuLieuTruoc = @DuLieuTruocDichVu;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DichVuHopDong WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DichVu WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDichVu AS maDichVu;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDichVu @ThaoTac = 'DANH_SACH', @MaDichVu = @MaDichVu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyNoiQuy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyNoiQuy
    @ThaoTac      VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinh    VARCHAR(6)    = NULL,
    @TieuDeNoiQuy VARCHAR(255) = NULL,
    @NoiDung      TEXT = NULL,
    @TrangThai    VARCHAR(20)  = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinh = NULLIF(TRIM(@MaQuyDinh)), '');
    SET @TieuDeNoiQuy = NULLIF(TRIM(@TieuDeNoiQuy)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qd.MaQuyDinh AS maQuyDinh,
            qd.TieuDeNoiQuy AS tieuDeNoiQuy,
            qd.NoiDung AS noiDung,
            qd.TrangThai AS trangThai
        FROM dbo.QuiDinh AS qd
        WHERE (@MaQuyDinh IS NULL OR qd.MaQuyDinh = @MaQuyDinh)
          AND (@TrangThai IS NULL OR qd.TrangThai = @TrangThai)
          AND (@TieuDeNoiQuy IS NULL OR qd.TieuDeNoiQuy LIKE '%' + @TieuDeNoiQuy + '%')
        ORDER BY qd.MaQuyDinh;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TieuDeNoiQuy IS NULL
            RAISE EXCEPTION %;

        IF @TieuDeNoiQuy IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.QuiDinh
            WHERE TieuDeNoiQuy = @TieuDeNoiQuy
              AND (@MaQuyDinh IS NULL OR MaQuyDinh <> @MaQuyDinh)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinhNoiQuy INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinh IS NULL
            BEGIN
                SELECT @SoQuyDinhNoiQuy = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinh, 3, 4))), 0) + 1
                FROM dbo.QuiDinh 
                WHERE MaQuyDinh LIKE 'QD[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinhNoiQuy > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinh = CONCAT('QD', RIGHT(CONCAT('0000', @SoQuyDinhNoiQuy), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuiDinh (MaQuyDinh, TieuDeNoiQuy, NoiDung, TrangThai)
            VALUES (@MaQuyDinh, @TieuDeNoiQuy, @NoiDung, COALESCE(@TrangThai, 'Hiệu lực'));

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo nội quy',
                @DoiTuong = 'QuiDinh',
                @MaDoiTuong = @MaQuyDinh,
                @NoiDung = @TieuDeNoiQuy;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocNoiQuy TEXT;
        SELECT @DuLieuTruocNoiQuy = (
            SELECT * FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuiDinh
        SET TieuDeNoiQuy = COALESCE(@TieuDeNoiQuy, TieuDeNoiQuy),
            NoiDung = COALESCE(@NoiDung, NoiDung),
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh,
            @DuLieuTruoc = @DuLieuTruocNoiQuy;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        UPDATE dbo.QuiDinh
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinh AS maQuyDinh;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyNoiQuy @ThaoTac = 'DANH_SACH', @MaQuyDinh = @MaQuyDinh;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham
    @ThaoTac        VARCHAR(20)  = 'DANH_SACH',
    @MaDieuKhoan    VARCHAR(6)    = NULL,
    @TenDieuKhoan   VARCHAR(255) = NULL,
    @HinhThucXuPhat VARCHAR(20)  = NULL,
    @MucPhat        DECIMAL(15,2) = NULL,
    @TrangThai      VARCHAR(20)  = NULL,
    @AdminId        VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDieuKhoan = NULLIF(TRIM(@MaDieuKhoan)), '');
    SET @TenDieuKhoan = NULLIF(TRIM(@TenDieuKhoan)), '');
    SET @HinhThucXuPhat = NULLIF(TRIM(@HinhThucXuPhat)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dk.MaDieuKhoan AS maDieuKhoan,
            dk.TenDieuKhoan AS tenDieuKhoan,
            dk.HinhThucXuPhat AS hinhThucXuPhat,
            dk.MucPhat AS mucPhat,
            dk.TrangThai AS trangThai,
            COUNT(bb.MaBBViPham) AS soBienBanApDung
        FROM dbo.DieuKhoanViPham AS dk
        LEFT JOIN dbo.BienBanViPham AS bb ON bb.MaDieuKhoan = dk.MaDieuKhoan
        WHERE (@MaDieuKhoan IS NULL OR dk.MaDieuKhoan = @MaDieuKhoan)
          AND (@TrangThai IS NULL OR dk.TrangThai = @TrangThai)
          AND (@TenDieuKhoan IS NULL OR dk.TenDieuKhoan LIKE '%' + @TenDieuKhoan + '%')
        GROUP BY dk.MaDieuKhoan, dk.TenDieuKhoan, dk.HinhThucXuPhat, dk.MucPhat, dk.TrangThai
        ORDER BY dk.MaDieuKhoan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @HinhThucXuPhat IS NOT NULL AND @HinhThucXuPhat NOT IN ('Nhắc nhở', 'Phạt tiền')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @MucPhat IS NOT NULL AND @MucPhat < 0
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDieuKhoan IS NULL OR @HinhThucXuPhat IS NULL)
            RAISE EXCEPTION %;

        IF @TenDieuKhoan IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DieuKhoanViPham
            WHERE TenDieuKhoan = @TenDieuKhoan
              AND (@MaDieuKhoan IS NULL OR MaDieuKhoan <> @MaDieuKhoan)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDieuKhoan INT;

        IF @HinhThucXuPhat = 'Phạt tiền' AND COALESCE(@MucPhat, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucXuPhat = 'Nhắc nhở' AND @MucPhat IS NULL
            SET @MucPhat = 0;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDieuKhoan IS NULL
            BEGIN
                SELECT @SoDieuKhoan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDieuKhoan, 3, 4))), 0) + 1
                FROM dbo.DieuKhoanViPham 
                WHERE MaDieuKhoan LIKE 'VP[0-9][0-9][0-9][0-9]';

                IF @SoDieuKhoan > 9999
                    RAISE EXCEPTION %;

                SET @MaDieuKhoan = CONCAT('VP', RIGHT(CONCAT('0000', @SoDieuKhoan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DieuKhoanViPham (
                MaDieuKhoan, TenDieuKhoan, HinhThucXuPhat, MucPhat, TrangThai
            )
            VALUES (
                @MaDieuKhoan, @TenDieuKhoan, @HinhThucXuPhat, COALESCE(@MucPhat, 0), COALESCE(@TrangThai, 'Hiệu lực')
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo điều khoản vi phạm',
                @DoiTuong = 'DieuKhoanViPham',
                @MaDoiTuong = @MaDieuKhoan,
                @NoiDung = @TenDieuKhoan;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DECLARE @HinhThucSau VARCHAR(20);
        DECLARE @MucPhatSau DECIMAL(15,2);

        SELECT
            @HinhThucSau = COALESCE(@HinhThucXuPhat, HinhThucXuPhat),
            @MucPhatSau = COALESCE(@MucPhat, MucPhat)
        FROM dbo.DieuKhoanViPham
        WHERE MaDieuKhoan = @MaDieuKhoan;

        IF @HinhThucSau = 'Phạt tiền' AND COALESCE(@MucPhatSau, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucSau = 'Nhắc nhở' AND @MucPhatSau IS NULL
            SET @MucPhatSau = 0;

        DECLARE @DuLieuTruocDieuKhoan TEXT;
        SELECT @DuLieuTruocDieuKhoan = (
            SELECT * FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DieuKhoanViPham
        SET TenDieuKhoan = COALESCE(@TenDieuKhoan, TenDieuKhoan),
            HinhThucXuPhat = @HinhThucSau,
            MucPhat = @MucPhatSau,
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan,
            @DuLieuTruoc = @DuLieuTruocDieuKhoan;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        UPDATE dbo.DieuKhoanViPham
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.BienBanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDieuKhoan AS maDieuKhoan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDieuKhoanViPham @ThaoTac = 'DANH_SACH', @MaDieuKhoan = @MaDieuKhoan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhThamSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhThamSo
    @ThaoTac    VARCHAR(20)  = 'DANH_SACH',
    @MaThamSo   VARCHAR(50)   = NULL,
    @NhomThamSo VARCHAR(50)  = NULL,
    @TenThamSo  VARCHAR(100) = NULL,
    @GiaTri     VARCHAR(255) = NULL,
    @KieuDuLieu VARCHAR(20)  = NULL,
    @DonViTinh  VARCHAR(30)  = NULL,
    @MoTa       TEXT = NULL,
    @AdminId    VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaThamSo = NULLIF(TRIM(@MaThamSo)), '');
    SET @NhomThamSo = NULLIF(TRIM(@NhomThamSo)), '');
    SET @TenThamSo = NULLIF(TRIM(@TenThamSo)), '');
    SET @GiaTri = NULLIF(TRIM(@GiaTri)), '');
    SET @KieuDuLieu = NULLIF(TRIM(@KieuDuLieu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            MaThamSo AS maThamSo,
            NhomThamSo AS nhomThamSo,
            TenThamSo AS tenThamSo,
            GiaTri AS giaTri,
            KieuDuLieu AS kieuDuLieu,
            DonViTinh AS donViTinh,
            MoTa AS moTa,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.ThamSoHeThong
        WHERE (@MaThamSo IS NULL OR MaThamSo = @MaThamSo)
          AND (@NhomThamSo IS NULL OR NhomThamSo = @NhomThamSo)
        ORDER BY NhomThamSo, MaThamSo;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT')
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO' AND (@MaThamSo IS NULL OR @NhomThamSo IS NULL OR @TenThamSo IS NULL OR @GiaTri IS NULL)
        THROW 51262, 'Vui lòng nhập đủ mã, nhóm, tên và giá trị tham số.', 1;

    IF @MaThamSo IS NULL
        RAISE EXCEPTION %;

    IF @KieuDuLieu IS NOT NULL AND @KieuDuLieu NOT IN ('Chuỗi', 'Số', 'Ngày', 'Boolean')
        RAISE EXCEPTION %;

    DECLARE @KieuDuLieuSau VARCHAR(20);
    DECLARE @GiaTriSau VARCHAR(255);

    IF @ThaoTac = 'TAO'
    BEGIN
        SET @KieuDuLieuSau = COALESCE(@KieuDuLieu, 'Chuỗi');
        SET @GiaTriSau = @GiaTri;
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        SELECT
            @KieuDuLieuSau = COALESCE(@KieuDuLieu, KieuDuLieu),
            @GiaTriSau = COALESCE(@GiaTri, GiaTri)
        FROM dbo.ThamSoHeThong
        WHERE MaThamSo = @MaThamSo;
    END;

    IF @KieuDuLieuSau = 'Số' AND (TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) IS NULL OR TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) < 0)
        RAISE EXCEPTION %;

    IF @MaThamSo = 'THOI_HAN_THANH_TOAN_COC_GIO'
       AND (TRY_CONVERT(INT, @GiaTriSau) IS NULL OR TRY_CONVERT(INT, @GiaTriSau) <= 0)
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        INSERT INTO dbo.ThamSoHeThong (
            MaThamSo, NhomThamSo, TenThamSo, GiaTri, KieuDuLieu, DonViTinh, MoTa, CapNhatBoi
        )
        VALUES (
            @MaThamSo, @NhomThamSo, @TenThamSo, @GiaTriSau, @KieuDuLieuSau, @DonViTinh, @MoTa, @AdminId
        );

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @NoiDung = @TenThamSo;
    END
    ELSE
    BEGIN
        DECLARE @DuLieuTruocThamSo TEXT;
        SELECT @DuLieuTruocThamSo = (
            SELECT * FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.ThamSoHeThong
        SET NhomThamSo = COALESCE(@NhomThamSo, NhomThamSo),
            TenThamSo = COALESCE(@TenThamSo, TenThamSo),
            GiaTri = @GiaTriSau,
            KieuDuLieu = @KieuDuLieuSau,
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            MoTa = COALESCE(@MoTa, MoTa),
            CapNhatLuc = CURRENT_TIMESTAMP,
            CapNhatBoi = @AdminId
        WHERE MaThamSo = @MaThamSo;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @DuLieuTruoc = @DuLieuTruocThamSo;
    END;

    EXEC dbo.SP_Admin_CauHinhThamSo @ThaoTac = 'DANH_SACH', @MaThamSo = @MaThamSo;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhSaoLuu
    @ChuKyFull        VARCHAR(20)  = NULL,
    @ChuKyIncremental VARCHAR(20)  = NULL,
    @ThuMucLuuTru     VARCHAR(500) = NULL,
    @AdminId          VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ChuKyFull = NULLIF(TRIM(@ChuKyFull)), '');
    SET @ChuKyIncremental = NULLIF(TRIM(@ChuKyIncremental)), '');
    SET @ThuMucLuuTru = NULLIF(TRIM(@ThuMucLuuTru)), '');

    IF @ChuKyFull IS NOT NULL AND @ChuKyFull NOT IN ('Hàng tuần', 'Hàng tháng')
        RAISE EXCEPTION %;

    IF @ChuKyIncremental IS NOT NULL AND @ChuKyIncremental NOT IN ('Hàng ngày', 'Hàng tuần')
        RAISE EXCEPTION %;

    IF @ThuMucLuuTru IS NOT NULL
    BEGIN
        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);
    END;

    IF @ChuKyFull IS NULL AND @ChuKyIncremental IS NULL AND @ThuMucLuuTru IS NULL
    BEGIN
        SELECT
            MaCauHinh AS maCauHinh,
            ChuKyFull AS chuKyFull,
            ChuKyIncremental AS chuKyIncremental,
            ThuMucLuuTru AS thuMucLuuTru,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;
        RETURN;
    END;

    DECLARE @DuLieuTruocSaoLuu TEXT;
    SELECT @DuLieuTruocSaoLuu = (
        SELECT * FROM dbo.CauHinhSaoLuu WHERE MaCauHinh = 1 FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    UPDATE dbo.CauHinhSaoLuu
    SET ChuKyFull = COALESCE(@ChuKyFull, ChuKyFull),
        ChuKyIncremental = COALESCE(@ChuKyIncremental, ChuKyIncremental),
        ThuMucLuuTru = COALESCE(@ThuMucLuuTru, ThuMucLuuTru),
        CapNhatLuc = CURRENT_TIMESTAMP,
        CapNhatBoi = @AdminId
    WHERE MaCauHinh = 1;

    EXEC dbo.SP_Admin_GhiNhatKy
        @AdminId = @AdminId,
        @HanhDong = 'Cấu hình sao lưu',
        @DoiTuong = 'CauHinhSaoLuu',
        @MaDoiTuong = '1',
        @DuLieuTruoc = @DuLieuTruocSaoLuu;

    SELECT
        MaCauHinh AS maCauHinh,
        ChuKyFull AS chuKyFull,
        ChuKyIncremental AS chuKyIncremental,
        ThuMucLuuTru AS thuMucLuuTru,
        CapNhatLuc AS capNhatLuc,
        CapNhatBoi AS capNhatBoi
    FROM dbo.CauHinhSaoLuu
    WHERE MaCauHinh = 1;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_SaoLuuThuCong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_SaoLuuThuCong
    @LoaiSaoLuu  VARCHAR(20)  = 'Full',
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    

    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');
    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');
    IF @LoaiSaoLuu IS NULL SET @LoaiSaoLuu = 'Full';

    DECLARE @LoaiSaoLuuChuan VARCHAR(20) = UPPER(@LoaiSaoLuu);
    IF @LoaiSaoLuuChuan = 'FULL'
        SET @LoaiSaoLuu = 'Full';
    ELSE IF @LoaiSaoLuuChuan IN ('INCREMENTAL', 'DIFFERENTIAL')
        SET @LoaiSaoLuu = 'Incremental';

    IF @LoaiSaoLuu NOT IN ('Full', 'Incremental')
        RAISE EXCEPTION %;

    IF @DuongDanFile IS NULL
    BEGIN
        DECLARE @ThuMucLuuTru VARCHAR(500);
        SELECT @ThuMucLuuTru = ThuMucLuuTru
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;

        IF @ThuMucLuuTru IS NULL
            RAISE EXCEPTION %;

        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);

        SET @DuongDanFile =
            @ThuMucLuuTru + '\' + DB_NAME() + '_' + @LoaiSaoLuu + '_' +
            CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112) + REPLACE(CONVERT(CHAR(8), CURRENT_TIMESTAMP, 108), ':', '') + '.bak';
    END;

    DECLARE @MaSaoLuu INT;
    DECLARE @LenhSaoLuu TEXT;

    INSERT INTO dbo.LichSuSaoLuu (
        LoaiSaoLuu, DuongDanFile, TrangThai, ThoiGianBatDau, MaNguoiDung
    )
    VALUES (
        @LoaiSaoLuu, @DuongDanFile, 'Đang chạy', CURRENT_TIMESTAMP, @AdminId
    );

    SET @MaSaoLuu = SCOPE_IDENTITY();
    SET @LenhSaoLuu =
        'BACKUP DATABASE ' + QUOTENAME(DB_NAME()) +
        ' TO DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') +
        ''' WITH ' +
        CASE WHEN @LoaiSaoLuu = 'Incremental' THEN 'DIFFERENTIAL, INIT' ELSE 'INIT' END +
        ';';

    BEGIN TRY
        EXEC(@LenhSaoLuu);

        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thành công',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = 'Sao lưu hoàn tất.'
        WHERE MaSaoLuu = @MaSaoLuu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Sao lưu thủ công',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thất bại',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = ERROR_MESSAGE()
        WHERE MaSaoLuu = @MaSaoLuu;

        THROW;
    END CATCH;

    SELECT
        MaSaoLuu AS maSaoLuu,
        LoaiSaoLuu AS loaiSaoLuu,
        DuongDanFile AS duongDanFile,
        TrangThai AS trangThai,
        ThoiGianBatDau AS thoiGianBatDau,
        ThoiGianKetThuc AS thoiGianKetThuc,
        ThongBao AS thongBao
    FROM dbo.LichSuSaoLuu
    WHERE MaSaoLuu = @MaSaoLuu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_DanhSachSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_DanhSachSaoLuu
    @SoDong     INT          = 100,
    @TrangThai  VARCHAR(20) = NULL,
    @LoaiSaoLuu VARCHAR(20) = NULL
AS
BEGIN
    

    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 100;

    SELECT TOP (@SoDong)
        ls.MaSaoLuu AS maSaoLuu,
        ls.LoaiSaoLuu AS loaiSaoLuu,
        ls.DuongDanFile AS duongDanFile,
        ls.DungLuongByte AS dungLuongByte,
        ls.TrangThai AS trangThai,
        ls.ThoiGianBatDau AS thoiGianBatDau,
        ls.ThoiGianKetThuc AS thoiGianKetThuc,
        ls.ThongBao AS thongBao,
        ls.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung
    FROM dbo.LichSuSaoLuu AS ls
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = ls.MaNguoiDung
    WHERE (@TrangThai IS NULL OR ls.TrangThai = @TrangThai)
      AND (@LoaiSaoLuu IS NULL OR ls.LoaiSaoLuu = @LoaiSaoLuu)
    ORDER BY ls.ThoiGianBatDau DESC, ls.MaSaoLuu DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_PhucHoiDuLieu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_PhucHoiDuLieu
    @MaSaoLuu    INT           = NULL,
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL,
    @ChiTaoLenh   BOOLEAN           = 1
AS
BEGIN
    

    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');

    IF @DuongDanFile IS NULL AND @MaSaoLuu IS NOT NULL
    BEGIN
        SELECT @DuongDanFile = DuongDanFile
        FROM dbo.LichSuSaoLuu
        WHERE MaSaoLuu = @MaSaoLuu
          AND TrangThai = 'Thành công';
    END;

    IF @DuongDanFile IS NULL
        RAISE EXCEPTION %;

    DECLARE @TenDatabase SYSNAME = DB_NAME();
    DECLARE @LenhSingleUser TEXT;
    DECLARE @LenhRestore TEXT;
    DECLARE @LenhMultiUser TEXT;
    DECLARE @LenhDayDu TEXT;

    SET @LenhSingleUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET SINGLE_USER WITH ROLLBACK IMMEDIATE;';
    SET @LenhRestore = 'USE [master]; RESTORE DATABASE ' + QUOTENAME(@TenDatabase) +
        ' FROM DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') + ''' WITH REPLACE;';
    SET @LenhMultiUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET MULTI_USER;';
    SET @LenhDayDu = @LenhSingleUser + CHAR(13) + CHAR(10) + @LenhRestore + CHAR(13) + CHAR(10) + @LenhMultiUser;

    IF @ChiTaoLenh = 1
    BEGIN
        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo lệnh phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;

        SELECT
            @TenDatabase AS tenDatabase,
            @DuongDanFile AS duongDanFile,
            @LenhDayDu AS lenhPhucHoi,
            CAST(1 AS BOOLEAN) AS chiTaoLenh;
        RETURN;
    END;

    BEGIN TRY
        EXEC(@LenhSingleUser);
        EXEC(@LenhRestore);
        EXEC(@LenhMultiUser);

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        BEGIN TRY
            EXEC(@LenhMultiUser);
        END TRY
        BEGIN CATCH
        END CATCH;

        THROW;
    END CATCH;

    SELECT
        @TenDatabase AS tenDatabase,
        @DuongDanFile AS duongDanFile,
        CAST(1 AS BOOLEAN) AS daPhucHoi;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_XemNhatKyHeThong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_XemNhatKyHeThong
    @TuNgay     TIMESTAMP  = NULL,
    @DenNgay    TIMESTAMP  = NULL,
    @AdminId    VARCHAR(6)    = NULL,
    @DoiTuong   VARCHAR(100) = NULL,
    @HanhDong   VARCHAR(100) = NULL,
    @TuKhoa     VARCHAR(100) = NULL,
    @SoDong     INT           = 200
AS
BEGIN
    

    SET @AdminId = NULLIF(TRIM(@AdminId)), '');
    SET @DoiTuong = NULLIF(TRIM(@DoiTuong)), '');
    SET @HanhDong = NULLIF(TRIM(@HanhDong)), '');
    SET @TuKhoa = NULLIF(TRIM(@TuKhoa)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 200;

    SELECT TOP (@SoDong)
        nk.MaNhatKy AS maNhatKy,
        nk.ThoiGian AS thoiGian,
        nk.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung,
        nk.VaiTro AS vaiTro,
        nk.ChucNang AS chucNang,
        nk.HanhDong AS hanhDong,
        nk.DoiTuong AS doiTuong,
        nk.MaDoiTuong AS maDoiTuong,
        nk.NoiDung AS noiDung,
        nk.DuLieuTruoc AS duLieuTruoc,
        nk.DuLieuSau AS duLieuSau
    FROM dbo.NhatKyHeThong AS nk
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nk.MaNguoiDung
    WHERE (@TuNgay IS NULL OR nk.ThoiGian >= @TuNgay)
      AND (@DenNgay IS NULL OR nk.ThoiGian < DATEADD(DAY, 1, @DenNgay))
      AND (@AdminId IS NULL OR nk.MaNguoiDung = @AdminId)
      AND (@DoiTuong IS NULL OR nk.DoiTuong = @DoiTuong)
      AND (@HanhDong IS NULL OR nk.HanhDong LIKE '%' + @HanhDong + '%')
      AND (
          @TuKhoa IS NULL
          OR nk.NoiDung LIKE '%' + @TuKhoa + '%'
          OR nk.MaDoiTuong LIKE '%' + @TuKhoa + '%'
          OR nk.HanhDong LIKE '%' + @TuKhoa + '%'
      )
    ORDER BY nk.ThoiGian DESC, nk.MaNhatKy DESC;
END; THEN (SUBSTRING(MaQuyDinhHoanCoc, 3, 4)::INT ELSE NULL END)), 0) + 1
                FROM dbo.QuyDinhHoanCoc 
                WHERE MaQuyDinhHoanCoc LIKE 'QH[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinh > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinhHoanCoc = CONCAT('QH', RIGHT(CONCAT('0000', @SoQuyDinh), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuyDinhHoanCoc (MaQuyDinhHoanCoc, TenQuyDinh, TyLeHoanCoc)
            VALUES (@MaQuyDinhHoanCoc, @TenQuyDinh, @TyLeHoanCoc);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo quy định hoàn cọc',
                @DoiTuong = 'QuyDinhHoanCoc',
                @MaDoiTuong = @MaQuyDinhHoanCoc,
                @NoiDung = @TenQuyDinh;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocHoanCoc TEXT;
        SELECT @DuLieuTruocHoanCoc = (
            SELECT * FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuyDinhHoanCoc
        SET TenQuyDinh = COALESCE(@TenQuyDinh, TenQuyDinh),
            TyLeHoanCoc = COALESCE(@TyLeHoanCoc, TyLeHoanCoc)
        WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc,
            @DuLieuTruoc = @DuLieuTruocHoanCoc;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinhHoanCoc IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc
        )
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DoiSoat WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuyDinhHoanCoc WHERE MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa quy định hoàn cọc',
            @DoiTuong = 'QuyDinhHoanCoc',
            @MaDoiTuong = @MaQuyDinhHoanCoc;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinhHoanCoc AS maQuyDinhHoanCoc;
        RETURN;
    END;

    EXEC dbo.SP_Admin_CauHinhQuyDinhHoanCoc @ThaoTac = 'DANH_SACH', @MaQuyDinhHoanCoc = @MaQuyDinhHoanCoc;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDichVu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDichVu
    @ThaoTac   VARCHAR(20)  = 'DANH_SACH',
    @MaDichVu  VARCHAR(6)    = NULL,
    @TenDichVu VARCHAR(100) = NULL,
    @DonViTinh VARCHAR(20)   = NULL,
    @DonGia    DECIMAL(15,2) = NULL,
    @AdminId   VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDichVu = NULLIF(TRIM(@MaDichVu)), '');
    SET @TenDichVu = NULLIF(TRIM(@TenDichVu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dv.MaDichVu AS maDichVu,
            dv.TenDichVu AS tenDichVu,
            dv.DonViTinh AS donViTinh,
            dv.DonGia AS donGia,
            COUNT(DISTINCT dvhd.MaChiTietDVHD) AS soHopDongSuDung,
            COUNT(cthd.MaChiTietHD) AS soDongHoaDon
        FROM dbo.DichVu AS dv
        LEFT JOIN dbo.DichVuHopDong AS dvhd ON dvhd.MaDichVu = dv.MaDichVu
        LEFT JOIN dbo.ChiTietHoaDon AS cthd ON cthd.MaChiTietDVHD = dvhd.MaChiTietDVHD
        WHERE (@MaDichVu IS NULL OR dv.MaDichVu = @MaDichVu)
          AND (@TenDichVu IS NULL OR dv.TenDichVu LIKE '%' + @TenDichVu + '%')
        GROUP BY dv.MaDichVu, dv.TenDichVu, dv.DonViTinh, dv.DonGia
        ORDER BY dv.MaDichVu;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'XOA')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDichVu IS NULL OR @DonViTinh IS NULL OR @DonGia IS NULL)
            THROW 51202, 'Vui lòng nhập tên dịch vụ, đơn vị tính và đơn giá.', 1;

        IF @DonGia IS NOT NULL AND @DonGia <= 0
            RAISE EXCEPTION %;

        IF @TenDichVu IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DichVu
            WHERE TenDichVu = @TenDichVu
              AND (@MaDichVu IS NULL OR MaDichVu <> @MaDichVu)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDichVu INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDichVu IS NULL
            BEGIN
                SELECT @SoDichVu = COALESCE(MAX(CASE WHEN (SUBSTRING(MaDichVu, 3, 4) ~ '^[0-9]+)), 0) + 1
                FROM dbo.DichVu 
                WHERE MaDichVu LIKE 'DV[0-9][0-9][0-9][0-9]';

                IF @SoDichVu > 9999
                    RAISE EXCEPTION %;

                SET @MaDichVu = CONCAT('DV', RIGHT(CONCAT('0000', @SoDichVu), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DichVu (MaDichVu, TenDichVu, DonViTinh, DonGia)
            VALUES (@MaDichVu, @TenDichVu, @DonViTinh, @DonGia);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo dịch vụ',
                @DoiTuong = 'DichVu',
                @MaDoiTuong = @MaDichVu,
                @NoiDung = @TenDichVu;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocDichVu TEXT;
        SELECT @DuLieuTruocDichVu = (
            SELECT * FROM dbo.DichVu WHERE MaDichVu = @MaDichVu FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DichVu
        SET TenDichVu = COALESCE(@TenDichVu, TenDichVu),
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            DonGia = COALESCE(@DonGia, DonGia)
        WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu,
            @DuLieuTruoc = @DuLieuTruocDichVu;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DichVuHopDong WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DichVu WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDichVu AS maDichVu;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDichVu @ThaoTac = 'DANH_SACH', @MaDichVu = @MaDichVu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyNoiQuy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyNoiQuy
    @ThaoTac      VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinh    VARCHAR(6)    = NULL,
    @TieuDeNoiQuy VARCHAR(255) = NULL,
    @NoiDung      TEXT = NULL,
    @TrangThai    VARCHAR(20)  = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinh = NULLIF(TRIM(@MaQuyDinh)), '');
    SET @TieuDeNoiQuy = NULLIF(TRIM(@TieuDeNoiQuy)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qd.MaQuyDinh AS maQuyDinh,
            qd.TieuDeNoiQuy AS tieuDeNoiQuy,
            qd.NoiDung AS noiDung,
            qd.TrangThai AS trangThai
        FROM dbo.QuiDinh AS qd
        WHERE (@MaQuyDinh IS NULL OR qd.MaQuyDinh = @MaQuyDinh)
          AND (@TrangThai IS NULL OR qd.TrangThai = @TrangThai)
          AND (@TieuDeNoiQuy IS NULL OR qd.TieuDeNoiQuy LIKE '%' + @TieuDeNoiQuy + '%')
        ORDER BY qd.MaQuyDinh;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TieuDeNoiQuy IS NULL
            RAISE EXCEPTION %;

        IF @TieuDeNoiQuy IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.QuiDinh
            WHERE TieuDeNoiQuy = @TieuDeNoiQuy
              AND (@MaQuyDinh IS NULL OR MaQuyDinh <> @MaQuyDinh)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinhNoiQuy INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinh IS NULL
            BEGIN
                SELECT @SoQuyDinhNoiQuy = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaQuyDinh, 3, 4))), 0) + 1
                FROM dbo.QuiDinh 
                WHERE MaQuyDinh LIKE 'QD[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinhNoiQuy > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinh = CONCAT('QD', RIGHT(CONCAT('0000', @SoQuyDinhNoiQuy), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuiDinh (MaQuyDinh, TieuDeNoiQuy, NoiDung, TrangThai)
            VALUES (@MaQuyDinh, @TieuDeNoiQuy, @NoiDung, COALESCE(@TrangThai, 'Hiệu lực'));

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo nội quy',
                @DoiTuong = 'QuiDinh',
                @MaDoiTuong = @MaQuyDinh,
                @NoiDung = @TieuDeNoiQuy;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocNoiQuy TEXT;
        SELECT @DuLieuTruocNoiQuy = (
            SELECT * FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuiDinh
        SET TieuDeNoiQuy = COALESCE(@TieuDeNoiQuy, TieuDeNoiQuy),
            NoiDung = COALESCE(@NoiDung, NoiDung),
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh,
            @DuLieuTruoc = @DuLieuTruocNoiQuy;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        UPDATE dbo.QuiDinh
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinh AS maQuyDinh;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyNoiQuy @ThaoTac = 'DANH_SACH', @MaQuyDinh = @MaQuyDinh;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham
    @ThaoTac        VARCHAR(20)  = 'DANH_SACH',
    @MaDieuKhoan    VARCHAR(6)    = NULL,
    @TenDieuKhoan   VARCHAR(255) = NULL,
    @HinhThucXuPhat VARCHAR(20)  = NULL,
    @MucPhat        DECIMAL(15,2) = NULL,
    @TrangThai      VARCHAR(20)  = NULL,
    @AdminId        VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDieuKhoan = NULLIF(TRIM(@MaDieuKhoan)), '');
    SET @TenDieuKhoan = NULLIF(TRIM(@TenDieuKhoan)), '');
    SET @HinhThucXuPhat = NULLIF(TRIM(@HinhThucXuPhat)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dk.MaDieuKhoan AS maDieuKhoan,
            dk.TenDieuKhoan AS tenDieuKhoan,
            dk.HinhThucXuPhat AS hinhThucXuPhat,
            dk.MucPhat AS mucPhat,
            dk.TrangThai AS trangThai,
            COUNT(bb.MaBBViPham) AS soBienBanApDung
        FROM dbo.DieuKhoanViPham AS dk
        LEFT JOIN dbo.BienBanViPham AS bb ON bb.MaDieuKhoan = dk.MaDieuKhoan
        WHERE (@MaDieuKhoan IS NULL OR dk.MaDieuKhoan = @MaDieuKhoan)
          AND (@TrangThai IS NULL OR dk.TrangThai = @TrangThai)
          AND (@TenDieuKhoan IS NULL OR dk.TenDieuKhoan LIKE '%' + @TenDieuKhoan + '%')
        GROUP BY dk.MaDieuKhoan, dk.TenDieuKhoan, dk.HinhThucXuPhat, dk.MucPhat, dk.TrangThai
        ORDER BY dk.MaDieuKhoan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @HinhThucXuPhat IS NOT NULL AND @HinhThucXuPhat NOT IN ('Nhắc nhở', 'Phạt tiền')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @MucPhat IS NOT NULL AND @MucPhat < 0
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDieuKhoan IS NULL OR @HinhThucXuPhat IS NULL)
            RAISE EXCEPTION %;

        IF @TenDieuKhoan IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DieuKhoanViPham
            WHERE TenDieuKhoan = @TenDieuKhoan
              AND (@MaDieuKhoan IS NULL OR MaDieuKhoan <> @MaDieuKhoan)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDieuKhoan INT;

        IF @HinhThucXuPhat = 'Phạt tiền' AND COALESCE(@MucPhat, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucXuPhat = 'Nhắc nhở' AND @MucPhat IS NULL
            SET @MucPhat = 0;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDieuKhoan IS NULL
            BEGIN
                SELECT @SoDieuKhoan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDieuKhoan, 3, 4))), 0) + 1
                FROM dbo.DieuKhoanViPham 
                WHERE MaDieuKhoan LIKE 'VP[0-9][0-9][0-9][0-9]';

                IF @SoDieuKhoan > 9999
                    RAISE EXCEPTION %;

                SET @MaDieuKhoan = CONCAT('VP', RIGHT(CONCAT('0000', @SoDieuKhoan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DieuKhoanViPham (
                MaDieuKhoan, TenDieuKhoan, HinhThucXuPhat, MucPhat, TrangThai
            )
            VALUES (
                @MaDieuKhoan, @TenDieuKhoan, @HinhThucXuPhat, COALESCE(@MucPhat, 0), COALESCE(@TrangThai, 'Hiệu lực')
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo điều khoản vi phạm',
                @DoiTuong = 'DieuKhoanViPham',
                @MaDoiTuong = @MaDieuKhoan,
                @NoiDung = @TenDieuKhoan;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DECLARE @HinhThucSau VARCHAR(20);
        DECLARE @MucPhatSau DECIMAL(15,2);

        SELECT
            @HinhThucSau = COALESCE(@HinhThucXuPhat, HinhThucXuPhat),
            @MucPhatSau = COALESCE(@MucPhat, MucPhat)
        FROM dbo.DieuKhoanViPham
        WHERE MaDieuKhoan = @MaDieuKhoan;

        IF @HinhThucSau = 'Phạt tiền' AND COALESCE(@MucPhatSau, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucSau = 'Nhắc nhở' AND @MucPhatSau IS NULL
            SET @MucPhatSau = 0;

        DECLARE @DuLieuTruocDieuKhoan TEXT;
        SELECT @DuLieuTruocDieuKhoan = (
            SELECT * FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DieuKhoanViPham
        SET TenDieuKhoan = COALESCE(@TenDieuKhoan, TenDieuKhoan),
            HinhThucXuPhat = @HinhThucSau,
            MucPhat = @MucPhatSau,
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan,
            @DuLieuTruoc = @DuLieuTruocDieuKhoan;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        UPDATE dbo.DieuKhoanViPham
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.BienBanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDieuKhoan AS maDieuKhoan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDieuKhoanViPham @ThaoTac = 'DANH_SACH', @MaDieuKhoan = @MaDieuKhoan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhThamSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhThamSo
    @ThaoTac    VARCHAR(20)  = 'DANH_SACH',
    @MaThamSo   VARCHAR(50)   = NULL,
    @NhomThamSo VARCHAR(50)  = NULL,
    @TenThamSo  VARCHAR(100) = NULL,
    @GiaTri     VARCHAR(255) = NULL,
    @KieuDuLieu VARCHAR(20)  = NULL,
    @DonViTinh  VARCHAR(30)  = NULL,
    @MoTa       TEXT = NULL,
    @AdminId    VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaThamSo = NULLIF(TRIM(@MaThamSo)), '');
    SET @NhomThamSo = NULLIF(TRIM(@NhomThamSo)), '');
    SET @TenThamSo = NULLIF(TRIM(@TenThamSo)), '');
    SET @GiaTri = NULLIF(TRIM(@GiaTri)), '');
    SET @KieuDuLieu = NULLIF(TRIM(@KieuDuLieu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            MaThamSo AS maThamSo,
            NhomThamSo AS nhomThamSo,
            TenThamSo AS tenThamSo,
            GiaTri AS giaTri,
            KieuDuLieu AS kieuDuLieu,
            DonViTinh AS donViTinh,
            MoTa AS moTa,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.ThamSoHeThong
        WHERE (@MaThamSo IS NULL OR MaThamSo = @MaThamSo)
          AND (@NhomThamSo IS NULL OR NhomThamSo = @NhomThamSo)
        ORDER BY NhomThamSo, MaThamSo;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT')
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO' AND (@MaThamSo IS NULL OR @NhomThamSo IS NULL OR @TenThamSo IS NULL OR @GiaTri IS NULL)
        THROW 51262, 'Vui lòng nhập đủ mã, nhóm, tên và giá trị tham số.', 1;

    IF @MaThamSo IS NULL
        RAISE EXCEPTION %;

    IF @KieuDuLieu IS NOT NULL AND @KieuDuLieu NOT IN ('Chuỗi', 'Số', 'Ngày', 'Boolean')
        RAISE EXCEPTION %;

    DECLARE @KieuDuLieuSau VARCHAR(20);
    DECLARE @GiaTriSau VARCHAR(255);

    IF @ThaoTac = 'TAO'
    BEGIN
        SET @KieuDuLieuSau = COALESCE(@KieuDuLieu, 'Chuỗi');
        SET @GiaTriSau = @GiaTri;
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        SELECT
            @KieuDuLieuSau = COALESCE(@KieuDuLieu, KieuDuLieu),
            @GiaTriSau = COALESCE(@GiaTri, GiaTri)
        FROM dbo.ThamSoHeThong
        WHERE MaThamSo = @MaThamSo;
    END;

    IF @KieuDuLieuSau = 'Số' AND (TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) IS NULL OR TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) < 0)
        RAISE EXCEPTION %;

    IF @MaThamSo = 'THOI_HAN_THANH_TOAN_COC_GIO'
       AND (TRY_CONVERT(INT, @GiaTriSau) IS NULL OR TRY_CONVERT(INT, @GiaTriSau) <= 0)
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        INSERT INTO dbo.ThamSoHeThong (
            MaThamSo, NhomThamSo, TenThamSo, GiaTri, KieuDuLieu, DonViTinh, MoTa, CapNhatBoi
        )
        VALUES (
            @MaThamSo, @NhomThamSo, @TenThamSo, @GiaTriSau, @KieuDuLieuSau, @DonViTinh, @MoTa, @AdminId
        );

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @NoiDung = @TenThamSo;
    END
    ELSE
    BEGIN
        DECLARE @DuLieuTruocThamSo TEXT;
        SELECT @DuLieuTruocThamSo = (
            SELECT * FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.ThamSoHeThong
        SET NhomThamSo = COALESCE(@NhomThamSo, NhomThamSo),
            TenThamSo = COALESCE(@TenThamSo, TenThamSo),
            GiaTri = @GiaTriSau,
            KieuDuLieu = @KieuDuLieuSau,
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            MoTa = COALESCE(@MoTa, MoTa),
            CapNhatLuc = CURRENT_TIMESTAMP,
            CapNhatBoi = @AdminId
        WHERE MaThamSo = @MaThamSo;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @DuLieuTruoc = @DuLieuTruocThamSo;
    END;

    EXEC dbo.SP_Admin_CauHinhThamSo @ThaoTac = 'DANH_SACH', @MaThamSo = @MaThamSo;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhSaoLuu
    @ChuKyFull        VARCHAR(20)  = NULL,
    @ChuKyIncremental VARCHAR(20)  = NULL,
    @ThuMucLuuTru     VARCHAR(500) = NULL,
    @AdminId          VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ChuKyFull = NULLIF(TRIM(@ChuKyFull)), '');
    SET @ChuKyIncremental = NULLIF(TRIM(@ChuKyIncremental)), '');
    SET @ThuMucLuuTru = NULLIF(TRIM(@ThuMucLuuTru)), '');

    IF @ChuKyFull IS NOT NULL AND @ChuKyFull NOT IN ('Hàng tuần', 'Hàng tháng')
        RAISE EXCEPTION %;

    IF @ChuKyIncremental IS NOT NULL AND @ChuKyIncremental NOT IN ('Hàng ngày', 'Hàng tuần')
        RAISE EXCEPTION %;

    IF @ThuMucLuuTru IS NOT NULL
    BEGIN
        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);
    END;

    IF @ChuKyFull IS NULL AND @ChuKyIncremental IS NULL AND @ThuMucLuuTru IS NULL
    BEGIN
        SELECT
            MaCauHinh AS maCauHinh,
            ChuKyFull AS chuKyFull,
            ChuKyIncremental AS chuKyIncremental,
            ThuMucLuuTru AS thuMucLuuTru,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;
        RETURN;
    END;

    DECLARE @DuLieuTruocSaoLuu TEXT;
    SELECT @DuLieuTruocSaoLuu = (
        SELECT * FROM dbo.CauHinhSaoLuu WHERE MaCauHinh = 1 FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    UPDATE dbo.CauHinhSaoLuu
    SET ChuKyFull = COALESCE(@ChuKyFull, ChuKyFull),
        ChuKyIncremental = COALESCE(@ChuKyIncremental, ChuKyIncremental),
        ThuMucLuuTru = COALESCE(@ThuMucLuuTru, ThuMucLuuTru),
        CapNhatLuc = CURRENT_TIMESTAMP,
        CapNhatBoi = @AdminId
    WHERE MaCauHinh = 1;

    EXEC dbo.SP_Admin_GhiNhatKy
        @AdminId = @AdminId,
        @HanhDong = 'Cấu hình sao lưu',
        @DoiTuong = 'CauHinhSaoLuu',
        @MaDoiTuong = '1',
        @DuLieuTruoc = @DuLieuTruocSaoLuu;

    SELECT
        MaCauHinh AS maCauHinh,
        ChuKyFull AS chuKyFull,
        ChuKyIncremental AS chuKyIncremental,
        ThuMucLuuTru AS thuMucLuuTru,
        CapNhatLuc AS capNhatLuc,
        CapNhatBoi AS capNhatBoi
    FROM dbo.CauHinhSaoLuu
    WHERE MaCauHinh = 1;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_SaoLuuThuCong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_SaoLuuThuCong
    @LoaiSaoLuu  VARCHAR(20)  = 'Full',
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    

    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');
    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');
    IF @LoaiSaoLuu IS NULL SET @LoaiSaoLuu = 'Full';

    DECLARE @LoaiSaoLuuChuan VARCHAR(20) = UPPER(@LoaiSaoLuu);
    IF @LoaiSaoLuuChuan = 'FULL'
        SET @LoaiSaoLuu = 'Full';
    ELSE IF @LoaiSaoLuuChuan IN ('INCREMENTAL', 'DIFFERENTIAL')
        SET @LoaiSaoLuu = 'Incremental';

    IF @LoaiSaoLuu NOT IN ('Full', 'Incremental')
        RAISE EXCEPTION %;

    IF @DuongDanFile IS NULL
    BEGIN
        DECLARE @ThuMucLuuTru VARCHAR(500);
        SELECT @ThuMucLuuTru = ThuMucLuuTru
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;

        IF @ThuMucLuuTru IS NULL
            RAISE EXCEPTION %;

        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);

        SET @DuongDanFile =
            @ThuMucLuuTru + '\' + DB_NAME() + '_' + @LoaiSaoLuu + '_' +
            CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112) + REPLACE(CONVERT(CHAR(8), CURRENT_TIMESTAMP, 108), ':', '') + '.bak';
    END;

    DECLARE @MaSaoLuu INT;
    DECLARE @LenhSaoLuu TEXT;

    INSERT INTO dbo.LichSuSaoLuu (
        LoaiSaoLuu, DuongDanFile, TrangThai, ThoiGianBatDau, MaNguoiDung
    )
    VALUES (
        @LoaiSaoLuu, @DuongDanFile, 'Đang chạy', CURRENT_TIMESTAMP, @AdminId
    );

    SET @MaSaoLuu = SCOPE_IDENTITY();
    SET @LenhSaoLuu =
        'BACKUP DATABASE ' + QUOTENAME(DB_NAME()) +
        ' TO DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') +
        ''' WITH ' +
        CASE WHEN @LoaiSaoLuu = 'Incremental' THEN 'DIFFERENTIAL, INIT' ELSE 'INIT' END +
        ';';

    BEGIN TRY
        EXEC(@LenhSaoLuu);

        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thành công',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = 'Sao lưu hoàn tất.'
        WHERE MaSaoLuu = @MaSaoLuu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Sao lưu thủ công',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thất bại',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = ERROR_MESSAGE()
        WHERE MaSaoLuu = @MaSaoLuu;

        THROW;
    END CATCH;

    SELECT
        MaSaoLuu AS maSaoLuu,
        LoaiSaoLuu AS loaiSaoLuu,
        DuongDanFile AS duongDanFile,
        TrangThai AS trangThai,
        ThoiGianBatDau AS thoiGianBatDau,
        ThoiGianKetThuc AS thoiGianKetThuc,
        ThongBao AS thongBao
    FROM dbo.LichSuSaoLuu
    WHERE MaSaoLuu = @MaSaoLuu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_DanhSachSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_DanhSachSaoLuu
    @SoDong     INT          = 100,
    @TrangThai  VARCHAR(20) = NULL,
    @LoaiSaoLuu VARCHAR(20) = NULL
AS
BEGIN
    

    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 100;

    SELECT TOP (@SoDong)
        ls.MaSaoLuu AS maSaoLuu,
        ls.LoaiSaoLuu AS loaiSaoLuu,
        ls.DuongDanFile AS duongDanFile,
        ls.DungLuongByte AS dungLuongByte,
        ls.TrangThai AS trangThai,
        ls.ThoiGianBatDau AS thoiGianBatDau,
        ls.ThoiGianKetThuc AS thoiGianKetThuc,
        ls.ThongBao AS thongBao,
        ls.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung
    FROM dbo.LichSuSaoLuu AS ls
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = ls.MaNguoiDung
    WHERE (@TrangThai IS NULL OR ls.TrangThai = @TrangThai)
      AND (@LoaiSaoLuu IS NULL OR ls.LoaiSaoLuu = @LoaiSaoLuu)
    ORDER BY ls.ThoiGianBatDau DESC, ls.MaSaoLuu DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_PhucHoiDuLieu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_PhucHoiDuLieu
    @MaSaoLuu    INT           = NULL,
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL,
    @ChiTaoLenh   BOOLEAN           = 1
AS
BEGIN
    

    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');

    IF @DuongDanFile IS NULL AND @MaSaoLuu IS NOT NULL
    BEGIN
        SELECT @DuongDanFile = DuongDanFile
        FROM dbo.LichSuSaoLuu
        WHERE MaSaoLuu = @MaSaoLuu
          AND TrangThai = 'Thành công';
    END;

    IF @DuongDanFile IS NULL
        RAISE EXCEPTION %;

    DECLARE @TenDatabase SYSNAME = DB_NAME();
    DECLARE @LenhSingleUser TEXT;
    DECLARE @LenhRestore TEXT;
    DECLARE @LenhMultiUser TEXT;
    DECLARE @LenhDayDu TEXT;

    SET @LenhSingleUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET SINGLE_USER WITH ROLLBACK IMMEDIATE;';
    SET @LenhRestore = 'USE [master]; RESTORE DATABASE ' + QUOTENAME(@TenDatabase) +
        ' FROM DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') + ''' WITH REPLACE;';
    SET @LenhMultiUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET MULTI_USER;';
    SET @LenhDayDu = @LenhSingleUser + CHAR(13) + CHAR(10) + @LenhRestore + CHAR(13) + CHAR(10) + @LenhMultiUser;

    IF @ChiTaoLenh = 1
    BEGIN
        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo lệnh phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;

        SELECT
            @TenDatabase AS tenDatabase,
            @DuongDanFile AS duongDanFile,
            @LenhDayDu AS lenhPhucHoi,
            CAST(1 AS BOOLEAN) AS chiTaoLenh;
        RETURN;
    END;

    BEGIN TRY
        EXEC(@LenhSingleUser);
        EXEC(@LenhRestore);
        EXEC(@LenhMultiUser);

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        BEGIN TRY
            EXEC(@LenhMultiUser);
        END TRY
        BEGIN CATCH
        END CATCH;

        THROW;
    END CATCH;

    SELECT
        @TenDatabase AS tenDatabase,
        @DuongDanFile AS duongDanFile,
        CAST(1 AS BOOLEAN) AS daPhucHoi;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_XemNhatKyHeThong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_XemNhatKyHeThong
    @TuNgay     TIMESTAMP  = NULL,
    @DenNgay    TIMESTAMP  = NULL,
    @AdminId    VARCHAR(6)    = NULL,
    @DoiTuong   VARCHAR(100) = NULL,
    @HanhDong   VARCHAR(100) = NULL,
    @TuKhoa     VARCHAR(100) = NULL,
    @SoDong     INT           = 200
AS
BEGIN
    

    SET @AdminId = NULLIF(TRIM(@AdminId)), '');
    SET @DoiTuong = NULLIF(TRIM(@DoiTuong)), '');
    SET @HanhDong = NULLIF(TRIM(@HanhDong)), '');
    SET @TuKhoa = NULLIF(TRIM(@TuKhoa)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 200;

    SELECT TOP (@SoDong)
        nk.MaNhatKy AS maNhatKy,
        nk.ThoiGian AS thoiGian,
        nk.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung,
        nk.VaiTro AS vaiTro,
        nk.ChucNang AS chucNang,
        nk.HanhDong AS hanhDong,
        nk.DoiTuong AS doiTuong,
        nk.MaDoiTuong AS maDoiTuong,
        nk.NoiDung AS noiDung,
        nk.DuLieuTruoc AS duLieuTruoc,
        nk.DuLieuSau AS duLieuSau
    FROM dbo.NhatKyHeThong AS nk
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nk.MaNguoiDung
    WHERE (@TuNgay IS NULL OR nk.ThoiGian >= @TuNgay)
      AND (@DenNgay IS NULL OR nk.ThoiGian < DATEADD(DAY, 1, @DenNgay))
      AND (@AdminId IS NULL OR nk.MaNguoiDung = @AdminId)
      AND (@DoiTuong IS NULL OR nk.DoiTuong = @DoiTuong)
      AND (@HanhDong IS NULL OR nk.HanhDong LIKE '%' + @HanhDong + '%')
      AND (
          @TuKhoa IS NULL
          OR nk.NoiDung LIKE '%' + @TuKhoa + '%'
          OR nk.MaDoiTuong LIKE '%' + @TuKhoa + '%'
          OR nk.HanhDong LIKE '%' + @TuKhoa + '%'
      )
    ORDER BY nk.ThoiGian DESC, nk.MaNhatKy DESC;
END; THEN (SUBSTRING(MaDichVu, 3, 4)::INT ELSE NULL END)), 0) + 1
                FROM dbo.DichVu 
                WHERE MaDichVu LIKE 'DV[0-9][0-9][0-9][0-9]';

                IF @SoDichVu > 9999
                    RAISE EXCEPTION %;

                SET @MaDichVu = CONCAT('DV', RIGHT(CONCAT('0000', @SoDichVu), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DichVu (MaDichVu, TenDichVu, DonViTinh, DonGia)
            VALUES (@MaDichVu, @TenDichVu, @DonViTinh, @DonGia);

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo dịch vụ',
                @DoiTuong = 'DichVu',
                @MaDoiTuong = @MaDichVu,
                @NoiDung = @TenDichVu;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocDichVu TEXT;
        SELECT @DuLieuTruocDichVu = (
            SELECT * FROM dbo.DichVu WHERE MaDichVu = @MaDichVu FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DichVu
        SET TenDichVu = COALESCE(@TenDichVu, TenDichVu),
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            DonGia = COALESCE(@DonGia, DonGia)
        WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu,
            @DuLieuTruoc = @DuLieuTruocDichVu;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDichVu IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DichVu WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.DichVuHopDong WHERE MaDichVu = @MaDichVu)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DichVu WHERE MaDichVu = @MaDichVu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa dịch vụ',
            @DoiTuong = 'DichVu',
            @MaDoiTuong = @MaDichVu;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDichVu AS maDichVu;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDichVu @ThaoTac = 'DANH_SACH', @MaDichVu = @MaDichVu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyNoiQuy AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyNoiQuy
    @ThaoTac      VARCHAR(20)  = 'DANH_SACH',
    @MaQuyDinh    VARCHAR(6)    = NULL,
    @TieuDeNoiQuy VARCHAR(255) = NULL,
    @NoiDung      TEXT = NULL,
    @TrangThai    VARCHAR(20)  = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaQuyDinh = NULLIF(TRIM(@MaQuyDinh)), '');
    SET @TieuDeNoiQuy = NULLIF(TRIM(@TieuDeNoiQuy)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            qd.MaQuyDinh AS maQuyDinh,
            qd.TieuDeNoiQuy AS tieuDeNoiQuy,
            qd.NoiDung AS noiDung,
            qd.TrangThai AS trangThai
        FROM dbo.QuiDinh AS qd
        WHERE (@MaQuyDinh IS NULL OR qd.MaQuyDinh = @MaQuyDinh)
          AND (@TrangThai IS NULL OR qd.TrangThai = @TrangThai)
          AND (@TieuDeNoiQuy IS NULL OR qd.TieuDeNoiQuy LIKE '%' + @TieuDeNoiQuy + '%')
        ORDER BY qd.MaQuyDinh;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND @TieuDeNoiQuy IS NULL
            RAISE EXCEPTION %;

        IF @TieuDeNoiQuy IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.QuiDinh
            WHERE TieuDeNoiQuy = @TieuDeNoiQuy
              AND (@MaQuyDinh IS NULL OR MaQuyDinh <> @MaQuyDinh)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoQuyDinhNoiQuy INT;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaQuyDinh IS NULL
            BEGIN
                SELECT @SoQuyDinhNoiQuy = COALESCE(MAX(CASE WHEN (SUBSTRING(MaQuyDinh, 3, 4) ~ '^[0-9]+)), 0) + 1
                FROM dbo.QuiDinh 
                WHERE MaQuyDinh LIKE 'QD[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinhNoiQuy > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinh = CONCAT('QD', RIGHT(CONCAT('0000', @SoQuyDinhNoiQuy), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuiDinh (MaQuyDinh, TieuDeNoiQuy, NoiDung, TrangThai)
            VALUES (@MaQuyDinh, @TieuDeNoiQuy, @NoiDung, COALESCE(@TrangThai, 'Hiệu lực'));

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo nội quy',
                @DoiTuong = 'QuiDinh',
                @MaDoiTuong = @MaQuyDinh,
                @NoiDung = @TieuDeNoiQuy;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocNoiQuy TEXT;
        SELECT @DuLieuTruocNoiQuy = (
            SELECT * FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuiDinh
        SET TieuDeNoiQuy = COALESCE(@TieuDeNoiQuy, TieuDeNoiQuy),
            NoiDung = COALESCE(@NoiDung, NoiDung),
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh,
            @DuLieuTruoc = @DuLieuTruocNoiQuy;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        UPDATE dbo.QuiDinh
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinh AS maQuyDinh;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyNoiQuy @ThaoTac = 'DANH_SACH', @MaQuyDinh = @MaQuyDinh;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham
    @ThaoTac        VARCHAR(20)  = 'DANH_SACH',
    @MaDieuKhoan    VARCHAR(6)    = NULL,
    @TenDieuKhoan   VARCHAR(255) = NULL,
    @HinhThucXuPhat VARCHAR(20)  = NULL,
    @MucPhat        DECIMAL(15,2) = NULL,
    @TrangThai      VARCHAR(20)  = NULL,
    @AdminId        VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDieuKhoan = NULLIF(TRIM(@MaDieuKhoan)), '');
    SET @TenDieuKhoan = NULLIF(TRIM(@TenDieuKhoan)), '');
    SET @HinhThucXuPhat = NULLIF(TRIM(@HinhThucXuPhat)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dk.MaDieuKhoan AS maDieuKhoan,
            dk.TenDieuKhoan AS tenDieuKhoan,
            dk.HinhThucXuPhat AS hinhThucXuPhat,
            dk.MucPhat AS mucPhat,
            dk.TrangThai AS trangThai,
            COUNT(bb.MaBBViPham) AS soBienBanApDung
        FROM dbo.DieuKhoanViPham AS dk
        LEFT JOIN dbo.BienBanViPham AS bb ON bb.MaDieuKhoan = dk.MaDieuKhoan
        WHERE (@MaDieuKhoan IS NULL OR dk.MaDieuKhoan = @MaDieuKhoan)
          AND (@TrangThai IS NULL OR dk.TrangThai = @TrangThai)
          AND (@TenDieuKhoan IS NULL OR dk.TenDieuKhoan LIKE '%' + @TenDieuKhoan + '%')
        GROUP BY dk.MaDieuKhoan, dk.TenDieuKhoan, dk.HinhThucXuPhat, dk.MucPhat, dk.TrangThai
        ORDER BY dk.MaDieuKhoan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @HinhThucXuPhat IS NOT NULL AND @HinhThucXuPhat NOT IN ('Nhắc nhở', 'Phạt tiền')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @MucPhat IS NOT NULL AND @MucPhat < 0
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDieuKhoan IS NULL OR @HinhThucXuPhat IS NULL)
            RAISE EXCEPTION %;

        IF @TenDieuKhoan IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DieuKhoanViPham
            WHERE TenDieuKhoan = @TenDieuKhoan
              AND (@MaDieuKhoan IS NULL OR MaDieuKhoan <> @MaDieuKhoan)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDieuKhoan INT;

        IF @HinhThucXuPhat = 'Phạt tiền' AND COALESCE(@MucPhat, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucXuPhat = 'Nhắc nhở' AND @MucPhat IS NULL
            SET @MucPhat = 0;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDieuKhoan IS NULL
            BEGIN
                SELECT @SoDieuKhoan = COALESCE(MAX(TRY_CONVERT(INT, SUBSTRING(MaDieuKhoan, 3, 4))), 0) + 1
                FROM dbo.DieuKhoanViPham 
                WHERE MaDieuKhoan LIKE 'VP[0-9][0-9][0-9][0-9]';

                IF @SoDieuKhoan > 9999
                    RAISE EXCEPTION %;

                SET @MaDieuKhoan = CONCAT('VP', RIGHT(CONCAT('0000', @SoDieuKhoan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DieuKhoanViPham (
                MaDieuKhoan, TenDieuKhoan, HinhThucXuPhat, MucPhat, TrangThai
            )
            VALUES (
                @MaDieuKhoan, @TenDieuKhoan, @HinhThucXuPhat, COALESCE(@MucPhat, 0), COALESCE(@TrangThai, 'Hiệu lực')
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo điều khoản vi phạm',
                @DoiTuong = 'DieuKhoanViPham',
                @MaDoiTuong = @MaDieuKhoan,
                @NoiDung = @TenDieuKhoan;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DECLARE @HinhThucSau VARCHAR(20);
        DECLARE @MucPhatSau DECIMAL(15,2);

        SELECT
            @HinhThucSau = COALESCE(@HinhThucXuPhat, HinhThucXuPhat),
            @MucPhatSau = COALESCE(@MucPhat, MucPhat)
        FROM dbo.DieuKhoanViPham
        WHERE MaDieuKhoan = @MaDieuKhoan;

        IF @HinhThucSau = 'Phạt tiền' AND COALESCE(@MucPhatSau, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucSau = 'Nhắc nhở' AND @MucPhatSau IS NULL
            SET @MucPhatSau = 0;

        DECLARE @DuLieuTruocDieuKhoan TEXT;
        SELECT @DuLieuTruocDieuKhoan = (
            SELECT * FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DieuKhoanViPham
        SET TenDieuKhoan = COALESCE(@TenDieuKhoan, TenDieuKhoan),
            HinhThucXuPhat = @HinhThucSau,
            MucPhat = @MucPhatSau,
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan,
            @DuLieuTruoc = @DuLieuTruocDieuKhoan;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        UPDATE dbo.DieuKhoanViPham
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.BienBanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDieuKhoan AS maDieuKhoan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDieuKhoanViPham @ThaoTac = 'DANH_SACH', @MaDieuKhoan = @MaDieuKhoan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhThamSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhThamSo
    @ThaoTac    VARCHAR(20)  = 'DANH_SACH',
    @MaThamSo   VARCHAR(50)   = NULL,
    @NhomThamSo VARCHAR(50)  = NULL,
    @TenThamSo  VARCHAR(100) = NULL,
    @GiaTri     VARCHAR(255) = NULL,
    @KieuDuLieu VARCHAR(20)  = NULL,
    @DonViTinh  VARCHAR(30)  = NULL,
    @MoTa       TEXT = NULL,
    @AdminId    VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaThamSo = NULLIF(TRIM(@MaThamSo)), '');
    SET @NhomThamSo = NULLIF(TRIM(@NhomThamSo)), '');
    SET @TenThamSo = NULLIF(TRIM(@TenThamSo)), '');
    SET @GiaTri = NULLIF(TRIM(@GiaTri)), '');
    SET @KieuDuLieu = NULLIF(TRIM(@KieuDuLieu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            MaThamSo AS maThamSo,
            NhomThamSo AS nhomThamSo,
            TenThamSo AS tenThamSo,
            GiaTri AS giaTri,
            KieuDuLieu AS kieuDuLieu,
            DonViTinh AS donViTinh,
            MoTa AS moTa,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.ThamSoHeThong
        WHERE (@MaThamSo IS NULL OR MaThamSo = @MaThamSo)
          AND (@NhomThamSo IS NULL OR NhomThamSo = @NhomThamSo)
        ORDER BY NhomThamSo, MaThamSo;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT')
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO' AND (@MaThamSo IS NULL OR @NhomThamSo IS NULL OR @TenThamSo IS NULL OR @GiaTri IS NULL)
        THROW 51262, 'Vui lòng nhập đủ mã, nhóm, tên và giá trị tham số.', 1;

    IF @MaThamSo IS NULL
        RAISE EXCEPTION %;

    IF @KieuDuLieu IS NOT NULL AND @KieuDuLieu NOT IN ('Chuỗi', 'Số', 'Ngày', 'Boolean')
        RAISE EXCEPTION %;

    DECLARE @KieuDuLieuSau VARCHAR(20);
    DECLARE @GiaTriSau VARCHAR(255);

    IF @ThaoTac = 'TAO'
    BEGIN
        SET @KieuDuLieuSau = COALESCE(@KieuDuLieu, 'Chuỗi');
        SET @GiaTriSau = @GiaTri;
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        SELECT
            @KieuDuLieuSau = COALESCE(@KieuDuLieu, KieuDuLieu),
            @GiaTriSau = COALESCE(@GiaTri, GiaTri)
        FROM dbo.ThamSoHeThong
        WHERE MaThamSo = @MaThamSo;
    END;

    IF @KieuDuLieuSau = 'Số' AND (TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) IS NULL OR TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) < 0)
        RAISE EXCEPTION %;

    IF @MaThamSo = 'THOI_HAN_THANH_TOAN_COC_GIO'
       AND (TRY_CONVERT(INT, @GiaTriSau) IS NULL OR TRY_CONVERT(INT, @GiaTriSau) <= 0)
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        INSERT INTO dbo.ThamSoHeThong (
            MaThamSo, NhomThamSo, TenThamSo, GiaTri, KieuDuLieu, DonViTinh, MoTa, CapNhatBoi
        )
        VALUES (
            @MaThamSo, @NhomThamSo, @TenThamSo, @GiaTriSau, @KieuDuLieuSau, @DonViTinh, @MoTa, @AdminId
        );

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @NoiDung = @TenThamSo;
    END
    ELSE
    BEGIN
        DECLARE @DuLieuTruocThamSo TEXT;
        SELECT @DuLieuTruocThamSo = (
            SELECT * FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.ThamSoHeThong
        SET NhomThamSo = COALESCE(@NhomThamSo, NhomThamSo),
            TenThamSo = COALESCE(@TenThamSo, TenThamSo),
            GiaTri = @GiaTriSau,
            KieuDuLieu = @KieuDuLieuSau,
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            MoTa = COALESCE(@MoTa, MoTa),
            CapNhatLuc = CURRENT_TIMESTAMP,
            CapNhatBoi = @AdminId
        WHERE MaThamSo = @MaThamSo;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @DuLieuTruoc = @DuLieuTruocThamSo;
    END;

    EXEC dbo.SP_Admin_CauHinhThamSo @ThaoTac = 'DANH_SACH', @MaThamSo = @MaThamSo;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhSaoLuu
    @ChuKyFull        VARCHAR(20)  = NULL,
    @ChuKyIncremental VARCHAR(20)  = NULL,
    @ThuMucLuuTru     VARCHAR(500) = NULL,
    @AdminId          VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ChuKyFull = NULLIF(TRIM(@ChuKyFull)), '');
    SET @ChuKyIncremental = NULLIF(TRIM(@ChuKyIncremental)), '');
    SET @ThuMucLuuTru = NULLIF(TRIM(@ThuMucLuuTru)), '');

    IF @ChuKyFull IS NOT NULL AND @ChuKyFull NOT IN ('Hàng tuần', 'Hàng tháng')
        RAISE EXCEPTION %;

    IF @ChuKyIncremental IS NOT NULL AND @ChuKyIncremental NOT IN ('Hàng ngày', 'Hàng tuần')
        RAISE EXCEPTION %;

    IF @ThuMucLuuTru IS NOT NULL
    BEGIN
        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);
    END;

    IF @ChuKyFull IS NULL AND @ChuKyIncremental IS NULL AND @ThuMucLuuTru IS NULL
    BEGIN
        SELECT
            MaCauHinh AS maCauHinh,
            ChuKyFull AS chuKyFull,
            ChuKyIncremental AS chuKyIncremental,
            ThuMucLuuTru AS thuMucLuuTru,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;
        RETURN;
    END;

    DECLARE @DuLieuTruocSaoLuu TEXT;
    SELECT @DuLieuTruocSaoLuu = (
        SELECT * FROM dbo.CauHinhSaoLuu WHERE MaCauHinh = 1 FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    UPDATE dbo.CauHinhSaoLuu
    SET ChuKyFull = COALESCE(@ChuKyFull, ChuKyFull),
        ChuKyIncremental = COALESCE(@ChuKyIncremental, ChuKyIncremental),
        ThuMucLuuTru = COALESCE(@ThuMucLuuTru, ThuMucLuuTru),
        CapNhatLuc = CURRENT_TIMESTAMP,
        CapNhatBoi = @AdminId
    WHERE MaCauHinh = 1;

    EXEC dbo.SP_Admin_GhiNhatKy
        @AdminId = @AdminId,
        @HanhDong = 'Cấu hình sao lưu',
        @DoiTuong = 'CauHinhSaoLuu',
        @MaDoiTuong = '1',
        @DuLieuTruoc = @DuLieuTruocSaoLuu;

    SELECT
        MaCauHinh AS maCauHinh,
        ChuKyFull AS chuKyFull,
        ChuKyIncremental AS chuKyIncremental,
        ThuMucLuuTru AS thuMucLuuTru,
        CapNhatLuc AS capNhatLuc,
        CapNhatBoi AS capNhatBoi
    FROM dbo.CauHinhSaoLuu
    WHERE MaCauHinh = 1;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_SaoLuuThuCong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_SaoLuuThuCong
    @LoaiSaoLuu  VARCHAR(20)  = 'Full',
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    

    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');
    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');
    IF @LoaiSaoLuu IS NULL SET @LoaiSaoLuu = 'Full';

    DECLARE @LoaiSaoLuuChuan VARCHAR(20) = UPPER(@LoaiSaoLuu);
    IF @LoaiSaoLuuChuan = 'FULL'
        SET @LoaiSaoLuu = 'Full';
    ELSE IF @LoaiSaoLuuChuan IN ('INCREMENTAL', 'DIFFERENTIAL')
        SET @LoaiSaoLuu = 'Incremental';

    IF @LoaiSaoLuu NOT IN ('Full', 'Incremental')
        RAISE EXCEPTION %;

    IF @DuongDanFile IS NULL
    BEGIN
        DECLARE @ThuMucLuuTru VARCHAR(500);
        SELECT @ThuMucLuuTru = ThuMucLuuTru
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;

        IF @ThuMucLuuTru IS NULL
            RAISE EXCEPTION %;

        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);

        SET @DuongDanFile =
            @ThuMucLuuTru + '\' + DB_NAME() + '_' + @LoaiSaoLuu + '_' +
            CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112) + REPLACE(CONVERT(CHAR(8), CURRENT_TIMESTAMP, 108), ':', '') + '.bak';
    END;

    DECLARE @MaSaoLuu INT;
    DECLARE @LenhSaoLuu TEXT;

    INSERT INTO dbo.LichSuSaoLuu (
        LoaiSaoLuu, DuongDanFile, TrangThai, ThoiGianBatDau, MaNguoiDung
    )
    VALUES (
        @LoaiSaoLuu, @DuongDanFile, 'Đang chạy', CURRENT_TIMESTAMP, @AdminId
    );

    SET @MaSaoLuu = SCOPE_IDENTITY();
    SET @LenhSaoLuu =
        'BACKUP DATABASE ' + QUOTENAME(DB_NAME()) +
        ' TO DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') +
        ''' WITH ' +
        CASE WHEN @LoaiSaoLuu = 'Incremental' THEN 'DIFFERENTIAL, INIT' ELSE 'INIT' END +
        ';';

    BEGIN TRY
        EXEC(@LenhSaoLuu);

        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thành công',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = 'Sao lưu hoàn tất.'
        WHERE MaSaoLuu = @MaSaoLuu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Sao lưu thủ công',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thất bại',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = ERROR_MESSAGE()
        WHERE MaSaoLuu = @MaSaoLuu;

        THROW;
    END CATCH;

    SELECT
        MaSaoLuu AS maSaoLuu,
        LoaiSaoLuu AS loaiSaoLuu,
        DuongDanFile AS duongDanFile,
        TrangThai AS trangThai,
        ThoiGianBatDau AS thoiGianBatDau,
        ThoiGianKetThuc AS thoiGianKetThuc,
        ThongBao AS thongBao
    FROM dbo.LichSuSaoLuu
    WHERE MaSaoLuu = @MaSaoLuu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_DanhSachSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_DanhSachSaoLuu
    @SoDong     INT          = 100,
    @TrangThai  VARCHAR(20) = NULL,
    @LoaiSaoLuu VARCHAR(20) = NULL
AS
BEGIN
    

    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 100;

    SELECT TOP (@SoDong)
        ls.MaSaoLuu AS maSaoLuu,
        ls.LoaiSaoLuu AS loaiSaoLuu,
        ls.DuongDanFile AS duongDanFile,
        ls.DungLuongByte AS dungLuongByte,
        ls.TrangThai AS trangThai,
        ls.ThoiGianBatDau AS thoiGianBatDau,
        ls.ThoiGianKetThuc AS thoiGianKetThuc,
        ls.ThongBao AS thongBao,
        ls.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung
    FROM dbo.LichSuSaoLuu AS ls
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = ls.MaNguoiDung
    WHERE (@TrangThai IS NULL OR ls.TrangThai = @TrangThai)
      AND (@LoaiSaoLuu IS NULL OR ls.LoaiSaoLuu = @LoaiSaoLuu)
    ORDER BY ls.ThoiGianBatDau DESC, ls.MaSaoLuu DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_PhucHoiDuLieu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_PhucHoiDuLieu
    @MaSaoLuu    INT           = NULL,
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL,
    @ChiTaoLenh   BOOLEAN           = 1
AS
BEGIN
    

    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');

    IF @DuongDanFile IS NULL AND @MaSaoLuu IS NOT NULL
    BEGIN
        SELECT @DuongDanFile = DuongDanFile
        FROM dbo.LichSuSaoLuu
        WHERE MaSaoLuu = @MaSaoLuu
          AND TrangThai = 'Thành công';
    END;

    IF @DuongDanFile IS NULL
        RAISE EXCEPTION %;

    DECLARE @TenDatabase SYSNAME = DB_NAME();
    DECLARE @LenhSingleUser TEXT;
    DECLARE @LenhRestore TEXT;
    DECLARE @LenhMultiUser TEXT;
    DECLARE @LenhDayDu TEXT;

    SET @LenhSingleUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET SINGLE_USER WITH ROLLBACK IMMEDIATE;';
    SET @LenhRestore = 'USE [master]; RESTORE DATABASE ' + QUOTENAME(@TenDatabase) +
        ' FROM DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') + ''' WITH REPLACE;';
    SET @LenhMultiUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET MULTI_USER;';
    SET @LenhDayDu = @LenhSingleUser + CHAR(13) + CHAR(10) + @LenhRestore + CHAR(13) + CHAR(10) + @LenhMultiUser;

    IF @ChiTaoLenh = 1
    BEGIN
        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo lệnh phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;

        SELECT
            @TenDatabase AS tenDatabase,
            @DuongDanFile AS duongDanFile,
            @LenhDayDu AS lenhPhucHoi,
            CAST(1 AS BOOLEAN) AS chiTaoLenh;
        RETURN;
    END;

    BEGIN TRY
        EXEC(@LenhSingleUser);
        EXEC(@LenhRestore);
        EXEC(@LenhMultiUser);

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        BEGIN TRY
            EXEC(@LenhMultiUser);
        END TRY
        BEGIN CATCH
        END CATCH;

        THROW;
    END CATCH;

    SELECT
        @TenDatabase AS tenDatabase,
        @DuongDanFile AS duongDanFile,
        CAST(1 AS BOOLEAN) AS daPhucHoi;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_XemNhatKyHeThong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_XemNhatKyHeThong
    @TuNgay     TIMESTAMP  = NULL,
    @DenNgay    TIMESTAMP  = NULL,
    @AdminId    VARCHAR(6)    = NULL,
    @DoiTuong   VARCHAR(100) = NULL,
    @HanhDong   VARCHAR(100) = NULL,
    @TuKhoa     VARCHAR(100) = NULL,
    @SoDong     INT           = 200
AS
BEGIN
    

    SET @AdminId = NULLIF(TRIM(@AdminId)), '');
    SET @DoiTuong = NULLIF(TRIM(@DoiTuong)), '');
    SET @HanhDong = NULLIF(TRIM(@HanhDong)), '');
    SET @TuKhoa = NULLIF(TRIM(@TuKhoa)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 200;

    SELECT TOP (@SoDong)
        nk.MaNhatKy AS maNhatKy,
        nk.ThoiGian AS thoiGian,
        nk.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung,
        nk.VaiTro AS vaiTro,
        nk.ChucNang AS chucNang,
        nk.HanhDong AS hanhDong,
        nk.DoiTuong AS doiTuong,
        nk.MaDoiTuong AS maDoiTuong,
        nk.NoiDung AS noiDung,
        nk.DuLieuTruoc AS duLieuTruoc,
        nk.DuLieuSau AS duLieuSau
    FROM dbo.NhatKyHeThong AS nk
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nk.MaNguoiDung
    WHERE (@TuNgay IS NULL OR nk.ThoiGian >= @TuNgay)
      AND (@DenNgay IS NULL OR nk.ThoiGian < DATEADD(DAY, 1, @DenNgay))
      AND (@AdminId IS NULL OR nk.MaNguoiDung = @AdminId)
      AND (@DoiTuong IS NULL OR nk.DoiTuong = @DoiTuong)
      AND (@HanhDong IS NULL OR nk.HanhDong LIKE '%' + @HanhDong + '%')
      AND (
          @TuKhoa IS NULL
          OR nk.NoiDung LIKE '%' + @TuKhoa + '%'
          OR nk.MaDoiTuong LIKE '%' + @TuKhoa + '%'
          OR nk.HanhDong LIKE '%' + @TuKhoa + '%'
      )
    ORDER BY nk.ThoiGian DESC, nk.MaNhatKy DESC;
END; THEN (SUBSTRING(MaQuyDinh, 3, 4)::INT ELSE NULL END)), 0) + 1
                FROM dbo.QuiDinh 
                WHERE MaQuyDinh LIKE 'QD[0-9][0-9][0-9][0-9]';

                IF @SoQuyDinhNoiQuy > 9999
                    RAISE EXCEPTION %;

                SET @MaQuyDinh = CONCAT('QD', RIGHT(CONCAT('0000', @SoQuyDinhNoiQuy), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
                RAISE EXCEPTION %;

            INSERT INTO dbo.QuiDinh (MaQuyDinh, TieuDeNoiQuy, NoiDung, TrangThai)
            VALUES (@MaQuyDinh, @TieuDeNoiQuy, @NoiDung, COALESCE(@TrangThai, 'Hiệu lực'));

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo nội quy',
                @DoiTuong = 'QuiDinh',
                @MaDoiTuong = @MaQuyDinh,
                @NoiDung = @TieuDeNoiQuy;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DECLARE @DuLieuTruocNoiQuy TEXT;
        SELECT @DuLieuTruocNoiQuy = (
            SELECT * FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.QuiDinh
        SET TieuDeNoiQuy = COALESCE(@TieuDeNoiQuy, TieuDeNoiQuy),
            NoiDung = COALESCE(@NoiDung, NoiDung),
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh,
            @DuLieuTruoc = @DuLieuTruocNoiQuy;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        UPDATE dbo.QuiDinh
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaQuyDinh IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh)
            RAISE EXCEPTION %;

        DELETE FROM dbo.QuiDinh WHERE MaQuyDinh = @MaQuyDinh;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa nội quy',
            @DoiTuong = 'QuiDinh',
            @MaDoiTuong = @MaQuyDinh;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaQuyDinh AS maQuyDinh;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyNoiQuy @ThaoTac = 'DANH_SACH', @MaQuyDinh = @MaQuyDinh;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_QuanLyDieuKhoanViPham
    @ThaoTac        VARCHAR(20)  = 'DANH_SACH',
    @MaDieuKhoan    VARCHAR(6)    = NULL,
    @TenDieuKhoan   VARCHAR(255) = NULL,
    @HinhThucXuPhat VARCHAR(20)  = NULL,
    @MucPhat        DECIMAL(15,2) = NULL,
    @TrangThai      VARCHAR(20)  = NULL,
    @AdminId        VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaDieuKhoan = NULLIF(TRIM(@MaDieuKhoan)), '');
    SET @TenDieuKhoan = NULLIF(TRIM(@TenDieuKhoan)), '');
    SET @HinhThucXuPhat = NULLIF(TRIM(@HinhThucXuPhat)), '');
    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            dk.MaDieuKhoan AS maDieuKhoan,
            dk.TenDieuKhoan AS tenDieuKhoan,
            dk.HinhThucXuPhat AS hinhThucXuPhat,
            dk.MucPhat AS mucPhat,
            dk.TrangThai AS trangThai,
            COUNT(bb.MaBBViPham) AS soBienBanApDung
        FROM dbo.DieuKhoanViPham AS dk
        LEFT JOIN dbo.BienBanViPham AS bb ON bb.MaDieuKhoan = dk.MaDieuKhoan
        WHERE (@MaDieuKhoan IS NULL OR dk.MaDieuKhoan = @MaDieuKhoan)
          AND (@TrangThai IS NULL OR dk.TrangThai = @TrangThai)
          AND (@TenDieuKhoan IS NULL OR dk.TenDieuKhoan LIKE '%' + @TenDieuKhoan + '%')
        GROUP BY dk.MaDieuKhoan, dk.TenDieuKhoan, dk.HinhThucXuPhat, dk.MucPhat, dk.TrangThai
        ORDER BY dk.MaDieuKhoan;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT', 'VO_HIEU', 'XOA')
        RAISE EXCEPTION %;

    IF @HinhThucXuPhat IS NOT NULL AND @HinhThucXuPhat NOT IN ('Nhắc nhở', 'Phạt tiền')
        RAISE EXCEPTION %;

    IF @TrangThai IS NOT NULL AND @TrangThai NOT IN ('Hiệu lực', 'Hết hiệu lực')
        RAISE EXCEPTION %;

    IF @MucPhat IS NOT NULL AND @MucPhat < 0
        RAISE EXCEPTION %;

    IF @ThaoTac IN ('TAO', 'CAP_NHAT')
    BEGIN
        IF @ThaoTac = 'TAO' AND (@TenDieuKhoan IS NULL OR @HinhThucXuPhat IS NULL)
            RAISE EXCEPTION %;

        IF @TenDieuKhoan IS NOT NULL AND EXISTS (
            SELECT 1
            FROM dbo.DieuKhoanViPham
            WHERE TenDieuKhoan = @TenDieuKhoan
              AND (@MaDieuKhoan IS NULL OR MaDieuKhoan <> @MaDieuKhoan)
        )
            RAISE EXCEPTION %;
    END;

    IF @ThaoTac = 'TAO'
    BEGIN
        DECLARE @SoDieuKhoan INT;

        IF @HinhThucXuPhat = 'Phạt tiền' AND COALESCE(@MucPhat, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucXuPhat = 'Nhắc nhở' AND @MucPhat IS NULL
            SET @MucPhat = 0;

        BEGIN TRY
            BEGIN TRANSACTION;

            IF @MaDieuKhoan IS NULL
            BEGIN
                SELECT @SoDieuKhoan = COALESCE(MAX(CASE WHEN (SUBSTRING(MaDieuKhoan, 3, 4) ~ '^[0-9]+)), 0) + 1
                FROM dbo.DieuKhoanViPham 
                WHERE MaDieuKhoan LIKE 'VP[0-9][0-9][0-9][0-9]';

                IF @SoDieuKhoan > 9999
                    RAISE EXCEPTION %;

                SET @MaDieuKhoan = CONCAT('VP', RIGHT(CONCAT('0000', @SoDieuKhoan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DieuKhoanViPham (
                MaDieuKhoan, TenDieuKhoan, HinhThucXuPhat, MucPhat, TrangThai
            )
            VALUES (
                @MaDieuKhoan, @TenDieuKhoan, @HinhThucXuPhat, COALESCE(@MucPhat, 0), COALESCE(@TrangThai, 'Hiệu lực')
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo điều khoản vi phạm',
                @DoiTuong = 'DieuKhoanViPham',
                @MaDoiTuong = @MaDieuKhoan,
                @NoiDung = @TenDieuKhoan;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DECLARE @HinhThucSau VARCHAR(20);
        DECLARE @MucPhatSau DECIMAL(15,2);

        SELECT
            @HinhThucSau = COALESCE(@HinhThucXuPhat, HinhThucXuPhat),
            @MucPhatSau = COALESCE(@MucPhat, MucPhat)
        FROM dbo.DieuKhoanViPham
        WHERE MaDieuKhoan = @MaDieuKhoan;

        IF @HinhThucSau = 'Phạt tiền' AND COALESCE(@MucPhatSau, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucSau = 'Nhắc nhở' AND @MucPhatSau IS NULL
            SET @MucPhatSau = 0;

        DECLARE @DuLieuTruocDieuKhoan TEXT;
        SELECT @DuLieuTruocDieuKhoan = (
            SELECT * FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DieuKhoanViPham
        SET TenDieuKhoan = COALESCE(@TenDieuKhoan, TenDieuKhoan),
            HinhThucXuPhat = @HinhThucSau,
            MucPhat = @MucPhatSau,
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan,
            @DuLieuTruoc = @DuLieuTruocDieuKhoan;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        UPDATE dbo.DieuKhoanViPham
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.BienBanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDieuKhoan AS maDieuKhoan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDieuKhoanViPham @ThaoTac = 'DANH_SACH', @MaDieuKhoan = @MaDieuKhoan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhThamSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhThamSo
    @ThaoTac    VARCHAR(20)  = 'DANH_SACH',
    @MaThamSo   VARCHAR(50)   = NULL,
    @NhomThamSo VARCHAR(50)  = NULL,
    @TenThamSo  VARCHAR(100) = NULL,
    @GiaTri     VARCHAR(255) = NULL,
    @KieuDuLieu VARCHAR(20)  = NULL,
    @DonViTinh  VARCHAR(30)  = NULL,
    @MoTa       TEXT = NULL,
    @AdminId    VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaThamSo = NULLIF(TRIM(@MaThamSo)), '');
    SET @NhomThamSo = NULLIF(TRIM(@NhomThamSo)), '');
    SET @TenThamSo = NULLIF(TRIM(@TenThamSo)), '');
    SET @GiaTri = NULLIF(TRIM(@GiaTri)), '');
    SET @KieuDuLieu = NULLIF(TRIM(@KieuDuLieu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            MaThamSo AS maThamSo,
            NhomThamSo AS nhomThamSo,
            TenThamSo AS tenThamSo,
            GiaTri AS giaTri,
            KieuDuLieu AS kieuDuLieu,
            DonViTinh AS donViTinh,
            MoTa AS moTa,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.ThamSoHeThong
        WHERE (@MaThamSo IS NULL OR MaThamSo = @MaThamSo)
          AND (@NhomThamSo IS NULL OR NhomThamSo = @NhomThamSo)
        ORDER BY NhomThamSo, MaThamSo;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT')
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO' AND (@MaThamSo IS NULL OR @NhomThamSo IS NULL OR @TenThamSo IS NULL OR @GiaTri IS NULL)
        THROW 51262, 'Vui lòng nhập đủ mã, nhóm, tên và giá trị tham số.', 1;

    IF @MaThamSo IS NULL
        RAISE EXCEPTION %;

    IF @KieuDuLieu IS NOT NULL AND @KieuDuLieu NOT IN ('Chuỗi', 'Số', 'Ngày', 'Boolean')
        RAISE EXCEPTION %;

    DECLARE @KieuDuLieuSau VARCHAR(20);
    DECLARE @GiaTriSau VARCHAR(255);

    IF @ThaoTac = 'TAO'
    BEGIN
        SET @KieuDuLieuSau = COALESCE(@KieuDuLieu, 'Chuỗi');
        SET @GiaTriSau = @GiaTri;
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        SELECT
            @KieuDuLieuSau = COALESCE(@KieuDuLieu, KieuDuLieu),
            @GiaTriSau = COALESCE(@GiaTri, GiaTri)
        FROM dbo.ThamSoHeThong
        WHERE MaThamSo = @MaThamSo;
    END;

    IF @KieuDuLieuSau = 'Số' AND (TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) IS NULL OR TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) < 0)
        RAISE EXCEPTION %;

    IF @MaThamSo = 'THOI_HAN_THANH_TOAN_COC_GIO'
       AND (TRY_CONVERT(INT, @GiaTriSau) IS NULL OR TRY_CONVERT(INT, @GiaTriSau) <= 0)
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        INSERT INTO dbo.ThamSoHeThong (
            MaThamSo, NhomThamSo, TenThamSo, GiaTri, KieuDuLieu, DonViTinh, MoTa, CapNhatBoi
        )
        VALUES (
            @MaThamSo, @NhomThamSo, @TenThamSo, @GiaTriSau, @KieuDuLieuSau, @DonViTinh, @MoTa, @AdminId
        );

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @NoiDung = @TenThamSo;
    END
    ELSE
    BEGIN
        DECLARE @DuLieuTruocThamSo TEXT;
        SELECT @DuLieuTruocThamSo = (
            SELECT * FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.ThamSoHeThong
        SET NhomThamSo = COALESCE(@NhomThamSo, NhomThamSo),
            TenThamSo = COALESCE(@TenThamSo, TenThamSo),
            GiaTri = @GiaTriSau,
            KieuDuLieu = @KieuDuLieuSau,
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            MoTa = COALESCE(@MoTa, MoTa),
            CapNhatLuc = CURRENT_TIMESTAMP,
            CapNhatBoi = @AdminId
        WHERE MaThamSo = @MaThamSo;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @DuLieuTruoc = @DuLieuTruocThamSo;
    END;

    EXEC dbo.SP_Admin_CauHinhThamSo @ThaoTac = 'DANH_SACH', @MaThamSo = @MaThamSo;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhSaoLuu
    @ChuKyFull        VARCHAR(20)  = NULL,
    @ChuKyIncremental VARCHAR(20)  = NULL,
    @ThuMucLuuTru     VARCHAR(500) = NULL,
    @AdminId          VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ChuKyFull = NULLIF(TRIM(@ChuKyFull)), '');
    SET @ChuKyIncremental = NULLIF(TRIM(@ChuKyIncremental)), '');
    SET @ThuMucLuuTru = NULLIF(TRIM(@ThuMucLuuTru)), '');

    IF @ChuKyFull IS NOT NULL AND @ChuKyFull NOT IN ('Hàng tuần', 'Hàng tháng')
        RAISE EXCEPTION %;

    IF @ChuKyIncremental IS NOT NULL AND @ChuKyIncremental NOT IN ('Hàng ngày', 'Hàng tuần')
        RAISE EXCEPTION %;

    IF @ThuMucLuuTru IS NOT NULL
    BEGIN
        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);
    END;

    IF @ChuKyFull IS NULL AND @ChuKyIncremental IS NULL AND @ThuMucLuuTru IS NULL
    BEGIN
        SELECT
            MaCauHinh AS maCauHinh,
            ChuKyFull AS chuKyFull,
            ChuKyIncremental AS chuKyIncremental,
            ThuMucLuuTru AS thuMucLuuTru,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;
        RETURN;
    END;

    DECLARE @DuLieuTruocSaoLuu TEXT;
    SELECT @DuLieuTruocSaoLuu = (
        SELECT * FROM dbo.CauHinhSaoLuu WHERE MaCauHinh = 1 FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    UPDATE dbo.CauHinhSaoLuu
    SET ChuKyFull = COALESCE(@ChuKyFull, ChuKyFull),
        ChuKyIncremental = COALESCE(@ChuKyIncremental, ChuKyIncremental),
        ThuMucLuuTru = COALESCE(@ThuMucLuuTru, ThuMucLuuTru),
        CapNhatLuc = CURRENT_TIMESTAMP,
        CapNhatBoi = @AdminId
    WHERE MaCauHinh = 1;

    EXEC dbo.SP_Admin_GhiNhatKy
        @AdminId = @AdminId,
        @HanhDong = 'Cấu hình sao lưu',
        @DoiTuong = 'CauHinhSaoLuu',
        @MaDoiTuong = '1',
        @DuLieuTruoc = @DuLieuTruocSaoLuu;

    SELECT
        MaCauHinh AS maCauHinh,
        ChuKyFull AS chuKyFull,
        ChuKyIncremental AS chuKyIncremental,
        ThuMucLuuTru AS thuMucLuuTru,
        CapNhatLuc AS capNhatLuc,
        CapNhatBoi AS capNhatBoi
    FROM dbo.CauHinhSaoLuu
    WHERE MaCauHinh = 1;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_SaoLuuThuCong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_SaoLuuThuCong
    @LoaiSaoLuu  VARCHAR(20)  = 'Full',
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    

    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');
    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');
    IF @LoaiSaoLuu IS NULL SET @LoaiSaoLuu = 'Full';

    DECLARE @LoaiSaoLuuChuan VARCHAR(20) = UPPER(@LoaiSaoLuu);
    IF @LoaiSaoLuuChuan = 'FULL'
        SET @LoaiSaoLuu = 'Full';
    ELSE IF @LoaiSaoLuuChuan IN ('INCREMENTAL', 'DIFFERENTIAL')
        SET @LoaiSaoLuu = 'Incremental';

    IF @LoaiSaoLuu NOT IN ('Full', 'Incremental')
        RAISE EXCEPTION %;

    IF @DuongDanFile IS NULL
    BEGIN
        DECLARE @ThuMucLuuTru VARCHAR(500);
        SELECT @ThuMucLuuTru = ThuMucLuuTru
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;

        IF @ThuMucLuuTru IS NULL
            RAISE EXCEPTION %;

        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);

        SET @DuongDanFile =
            @ThuMucLuuTru + '\' + DB_NAME() + '_' + @LoaiSaoLuu + '_' +
            CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112) + REPLACE(CONVERT(CHAR(8), CURRENT_TIMESTAMP, 108), ':', '') + '.bak';
    END;

    DECLARE @MaSaoLuu INT;
    DECLARE @LenhSaoLuu TEXT;

    INSERT INTO dbo.LichSuSaoLuu (
        LoaiSaoLuu, DuongDanFile, TrangThai, ThoiGianBatDau, MaNguoiDung
    )
    VALUES (
        @LoaiSaoLuu, @DuongDanFile, 'Đang chạy', CURRENT_TIMESTAMP, @AdminId
    );

    SET @MaSaoLuu = SCOPE_IDENTITY();
    SET @LenhSaoLuu =
        'BACKUP DATABASE ' + QUOTENAME(DB_NAME()) +
        ' TO DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') +
        ''' WITH ' +
        CASE WHEN @LoaiSaoLuu = 'Incremental' THEN 'DIFFERENTIAL, INIT' ELSE 'INIT' END +
        ';';

    BEGIN TRY
        EXEC(@LenhSaoLuu);

        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thành công',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = 'Sao lưu hoàn tất.'
        WHERE MaSaoLuu = @MaSaoLuu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Sao lưu thủ công',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thất bại',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = ERROR_MESSAGE()
        WHERE MaSaoLuu = @MaSaoLuu;

        THROW;
    END CATCH;

    SELECT
        MaSaoLuu AS maSaoLuu,
        LoaiSaoLuu AS loaiSaoLuu,
        DuongDanFile AS duongDanFile,
        TrangThai AS trangThai,
        ThoiGianBatDau AS thoiGianBatDau,
        ThoiGianKetThuc AS thoiGianKetThuc,
        ThongBao AS thongBao
    FROM dbo.LichSuSaoLuu
    WHERE MaSaoLuu = @MaSaoLuu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_DanhSachSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_DanhSachSaoLuu
    @SoDong     INT          = 100,
    @TrangThai  VARCHAR(20) = NULL,
    @LoaiSaoLuu VARCHAR(20) = NULL
AS
BEGIN
    

    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 100;

    SELECT TOP (@SoDong)
        ls.MaSaoLuu AS maSaoLuu,
        ls.LoaiSaoLuu AS loaiSaoLuu,
        ls.DuongDanFile AS duongDanFile,
        ls.DungLuongByte AS dungLuongByte,
        ls.TrangThai AS trangThai,
        ls.ThoiGianBatDau AS thoiGianBatDau,
        ls.ThoiGianKetThuc AS thoiGianKetThuc,
        ls.ThongBao AS thongBao,
        ls.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung
    FROM dbo.LichSuSaoLuu AS ls
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = ls.MaNguoiDung
    WHERE (@TrangThai IS NULL OR ls.TrangThai = @TrangThai)
      AND (@LoaiSaoLuu IS NULL OR ls.LoaiSaoLuu = @LoaiSaoLuu)
    ORDER BY ls.ThoiGianBatDau DESC, ls.MaSaoLuu DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_PhucHoiDuLieu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_PhucHoiDuLieu
    @MaSaoLuu    INT           = NULL,
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL,
    @ChiTaoLenh   BOOLEAN           = 1
AS
BEGIN
    

    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');

    IF @DuongDanFile IS NULL AND @MaSaoLuu IS NOT NULL
    BEGIN
        SELECT @DuongDanFile = DuongDanFile
        FROM dbo.LichSuSaoLuu
        WHERE MaSaoLuu = @MaSaoLuu
          AND TrangThai = 'Thành công';
    END;

    IF @DuongDanFile IS NULL
        RAISE EXCEPTION %;

    DECLARE @TenDatabase SYSNAME = DB_NAME();
    DECLARE @LenhSingleUser TEXT;
    DECLARE @LenhRestore TEXT;
    DECLARE @LenhMultiUser TEXT;
    DECLARE @LenhDayDu TEXT;

    SET @LenhSingleUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET SINGLE_USER WITH ROLLBACK IMMEDIATE;';
    SET @LenhRestore = 'USE [master]; RESTORE DATABASE ' + QUOTENAME(@TenDatabase) +
        ' FROM DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') + ''' WITH REPLACE;';
    SET @LenhMultiUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET MULTI_USER;';
    SET @LenhDayDu = @LenhSingleUser + CHAR(13) + CHAR(10) + @LenhRestore + CHAR(13) + CHAR(10) + @LenhMultiUser;

    IF @ChiTaoLenh = 1
    BEGIN
        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo lệnh phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;

        SELECT
            @TenDatabase AS tenDatabase,
            @DuongDanFile AS duongDanFile,
            @LenhDayDu AS lenhPhucHoi,
            CAST(1 AS BOOLEAN) AS chiTaoLenh;
        RETURN;
    END;

    BEGIN TRY
        EXEC(@LenhSingleUser);
        EXEC(@LenhRestore);
        EXEC(@LenhMultiUser);

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        BEGIN TRY
            EXEC(@LenhMultiUser);
        END TRY
        BEGIN CATCH
        END CATCH;

        THROW;
    END CATCH;

    SELECT
        @TenDatabase AS tenDatabase,
        @DuongDanFile AS duongDanFile,
        CAST(1 AS BOOLEAN) AS daPhucHoi;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_XemNhatKyHeThong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_XemNhatKyHeThong
    @TuNgay     TIMESTAMP  = NULL,
    @DenNgay    TIMESTAMP  = NULL,
    @AdminId    VARCHAR(6)    = NULL,
    @DoiTuong   VARCHAR(100) = NULL,
    @HanhDong   VARCHAR(100) = NULL,
    @TuKhoa     VARCHAR(100) = NULL,
    @SoDong     INT           = 200
AS
BEGIN
    

    SET @AdminId = NULLIF(TRIM(@AdminId)), '');
    SET @DoiTuong = NULLIF(TRIM(@DoiTuong)), '');
    SET @HanhDong = NULLIF(TRIM(@HanhDong)), '');
    SET @TuKhoa = NULLIF(TRIM(@TuKhoa)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 200;

    SELECT TOP (@SoDong)
        nk.MaNhatKy AS maNhatKy,
        nk.ThoiGian AS thoiGian,
        nk.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung,
        nk.VaiTro AS vaiTro,
        nk.ChucNang AS chucNang,
        nk.HanhDong AS hanhDong,
        nk.DoiTuong AS doiTuong,
        nk.MaDoiTuong AS maDoiTuong,
        nk.NoiDung AS noiDung,
        nk.DuLieuTruoc AS duLieuTruoc,
        nk.DuLieuSau AS duLieuSau
    FROM dbo.NhatKyHeThong AS nk
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nk.MaNguoiDung
    WHERE (@TuNgay IS NULL OR nk.ThoiGian >= @TuNgay)
      AND (@DenNgay IS NULL OR nk.ThoiGian < DATEADD(DAY, 1, @DenNgay))
      AND (@AdminId IS NULL OR nk.MaNguoiDung = @AdminId)
      AND (@DoiTuong IS NULL OR nk.DoiTuong = @DoiTuong)
      AND (@HanhDong IS NULL OR nk.HanhDong LIKE '%' + @HanhDong + '%')
      AND (
          @TuKhoa IS NULL
          OR nk.NoiDung LIKE '%' + @TuKhoa + '%'
          OR nk.MaDoiTuong LIKE '%' + @TuKhoa + '%'
          OR nk.HanhDong LIKE '%' + @TuKhoa + '%'
      )
    ORDER BY nk.ThoiGian DESC, nk.MaNhatKy DESC;
END; THEN (SUBSTRING(MaDieuKhoan, 3, 4)::INT ELSE NULL END)), 0) + 1
                FROM dbo.DieuKhoanViPham 
                WHERE MaDieuKhoan LIKE 'VP[0-9][0-9][0-9][0-9]';

                IF @SoDieuKhoan > 9999
                    RAISE EXCEPTION %;

                SET @MaDieuKhoan = CONCAT('VP', RIGHT(CONCAT('0000', @SoDieuKhoan), 4));
            END;

            IF EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
                RAISE EXCEPTION %;

            INSERT INTO dbo.DieuKhoanViPham (
                MaDieuKhoan, TenDieuKhoan, HinhThucXuPhat, MucPhat, TrangThai
            )
            VALUES (
                @MaDieuKhoan, @TenDieuKhoan, @HinhThucXuPhat, COALESCE(@MucPhat, 0), COALESCE(@TrangThai, 'Hiệu lực')
            );

            EXEC dbo.SP_Admin_GhiNhatKy
                @AdminId = @AdminId,
                @HanhDong = 'Tạo điều khoản vi phạm',
                @DoiTuong = 'DieuKhoanViPham',
                @MaDoiTuong = @MaDieuKhoan,
                @NoiDung = @TenDieuKhoan;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0
                ROLLBACK TRANSACTION;
            THROW;
        END CATCH;
    END
    ELSE IF @ThaoTac = 'CAP_NHAT'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DECLARE @HinhThucSau VARCHAR(20);
        DECLARE @MucPhatSau DECIMAL(15,2);

        SELECT
            @HinhThucSau = COALESCE(@HinhThucXuPhat, HinhThucXuPhat),
            @MucPhatSau = COALESCE(@MucPhat, MucPhat)
        FROM dbo.DieuKhoanViPham
        WHERE MaDieuKhoan = @MaDieuKhoan;

        IF @HinhThucSau = 'Phạt tiền' AND COALESCE(@MucPhatSau, 0) <= 0
            RAISE EXCEPTION %;

        IF @HinhThucSau = 'Nhắc nhở' AND @MucPhatSau IS NULL
            SET @MucPhatSau = 0;

        DECLARE @DuLieuTruocDieuKhoan TEXT;
        SELECT @DuLieuTruocDieuKhoan = (
            SELECT * FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.DieuKhoanViPham
        SET TenDieuKhoan = COALESCE(@TenDieuKhoan, TenDieuKhoan),
            HinhThucXuPhat = @HinhThucSau,
            MucPhat = @MucPhatSau,
            TrangThai = COALESCE(@TrangThai, TrangThai)
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan,
            @DuLieuTruoc = @DuLieuTruocDieuKhoan;
    END
    ELSE IF @ThaoTac = 'VO_HIEU'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        UPDATE dbo.DieuKhoanViPham
        SET TrangThai = 'Hết hiệu lực'
        WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Vô hiệu hóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;
    END
    ELSE IF @ThaoTac = 'XOA'
    BEGIN
        IF @MaDieuKhoan IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        IF EXISTS (SELECT 1 FROM dbo.BienBanViPham WHERE MaDieuKhoan = @MaDieuKhoan)
            RAISE EXCEPTION %;

        DELETE FROM dbo.DieuKhoanViPham WHERE MaDieuKhoan = @MaDieuKhoan;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Xóa điều khoản vi phạm',
            @DoiTuong = 'DieuKhoanViPham',
            @MaDoiTuong = @MaDieuKhoan;

        SELECT CAST(1 AS BOOLEAN) AS daXoa, @MaDieuKhoan AS maDieuKhoan;
        RETURN;
    END;

    EXEC dbo.SP_Admin_QuanLyDieuKhoanViPham @ThaoTac = 'DANH_SACH', @MaDieuKhoan = @MaDieuKhoan;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhThamSo AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhThamSo
    @ThaoTac    VARCHAR(20)  = 'DANH_SACH',
    @MaThamSo   VARCHAR(50)   = NULL,
    @NhomThamSo VARCHAR(50)  = NULL,
    @TenThamSo  VARCHAR(100) = NULL,
    @GiaTri     VARCHAR(255) = NULL,
    @KieuDuLieu VARCHAR(20)  = NULL,
    @DonViTinh  VARCHAR(30)  = NULL,
    @MoTa       TEXT = NULL,
    @AdminId    VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ThaoTac = UPPER(NULLIF(TRIM(@ThaoTac)), ''));
    SET @MaThamSo = NULLIF(TRIM(@MaThamSo)), '');
    SET @NhomThamSo = NULLIF(TRIM(@NhomThamSo)), '');
    SET @TenThamSo = NULLIF(TRIM(@TenThamSo)), '');
    SET @GiaTri = NULLIF(TRIM(@GiaTri)), '');
    SET @KieuDuLieu = NULLIF(TRIM(@KieuDuLieu)), '');
    SET @DonViTinh = NULLIF(TRIM(@DonViTinh)), '');
    IF @ThaoTac IS NULL SET @ThaoTac = 'DANH_SACH';

    IF @ThaoTac = 'DANH_SACH'
    BEGIN
        SELECT
            MaThamSo AS maThamSo,
            NhomThamSo AS nhomThamSo,
            TenThamSo AS tenThamSo,
            GiaTri AS giaTri,
            KieuDuLieu AS kieuDuLieu,
            DonViTinh AS donViTinh,
            MoTa AS moTa,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.ThamSoHeThong
        WHERE (@MaThamSo IS NULL OR MaThamSo = @MaThamSo)
          AND (@NhomThamSo IS NULL OR NhomThamSo = @NhomThamSo)
        ORDER BY NhomThamSo, MaThamSo;
        RETURN;
    END;

    IF @ThaoTac NOT IN ('TAO', 'CAP_NHAT')
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO' AND (@MaThamSo IS NULL OR @NhomThamSo IS NULL OR @TenThamSo IS NULL OR @GiaTri IS NULL)
        THROW 51262, 'Vui lòng nhập đủ mã, nhóm, tên và giá trị tham số.', 1;

    IF @MaThamSo IS NULL
        RAISE EXCEPTION %;

    IF @KieuDuLieu IS NOT NULL AND @KieuDuLieu NOT IN ('Chuỗi', 'Số', 'Ngày', 'Boolean')
        RAISE EXCEPTION %;

    DECLARE @KieuDuLieuSau VARCHAR(20);
    DECLARE @GiaTriSau VARCHAR(255);

    IF @ThaoTac = 'TAO'
    BEGIN
        SET @KieuDuLieuSau = COALESCE(@KieuDuLieu, 'Chuỗi');
        SET @GiaTriSau = @GiaTri;
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        SELECT
            @KieuDuLieuSau = COALESCE(@KieuDuLieu, KieuDuLieu),
            @GiaTriSau = COALESCE(@GiaTri, GiaTri)
        FROM dbo.ThamSoHeThong
        WHERE MaThamSo = @MaThamSo;
    END;

    IF @KieuDuLieuSau = 'Số' AND (TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) IS NULL OR TRY_CONVERT(DECIMAL(18,2), @GiaTriSau) < 0)
        RAISE EXCEPTION %;

    IF @MaThamSo = 'THOI_HAN_THANH_TOAN_COC_GIO'
       AND (CASE WHEN (@GiaTriSau) ~ '^[0-9]+ IS NULL OR TRY_CONVERT(INT, @GiaTriSau) <= 0)
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        INSERT INTO dbo.ThamSoHeThong (
            MaThamSo, NhomThamSo, TenThamSo, GiaTri, KieuDuLieu, DonViTinh, MoTa, CapNhatBoi
        )
        VALUES (
            @MaThamSo, @NhomThamSo, @TenThamSo, @GiaTriSau, @KieuDuLieuSau, @DonViTinh, @MoTa, @AdminId
        );

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @NoiDung = @TenThamSo;
    END
    ELSE
    BEGIN
        DECLARE @DuLieuTruocThamSo TEXT;
        SELECT @DuLieuTruocThamSo = (
            SELECT * FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.ThamSoHeThong
        SET NhomThamSo = COALESCE(@NhomThamSo, NhomThamSo),
            TenThamSo = COALESCE(@TenThamSo, TenThamSo),
            GiaTri = @GiaTriSau,
            KieuDuLieu = @KieuDuLieuSau,
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            MoTa = COALESCE(@MoTa, MoTa),
            CapNhatLuc = CURRENT_TIMESTAMP,
            CapNhatBoi = @AdminId
        WHERE MaThamSo = @MaThamSo;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @DuLieuTruoc = @DuLieuTruocThamSo;
    END;

    EXEC dbo.SP_Admin_CauHinhThamSo @ThaoTac = 'DANH_SACH', @MaThamSo = @MaThamSo;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhSaoLuu
    @ChuKyFull        VARCHAR(20)  = NULL,
    @ChuKyIncremental VARCHAR(20)  = NULL,
    @ThuMucLuuTru     VARCHAR(500) = NULL,
    @AdminId          VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ChuKyFull = NULLIF(TRIM(@ChuKyFull)), '');
    SET @ChuKyIncremental = NULLIF(TRIM(@ChuKyIncremental)), '');
    SET @ThuMucLuuTru = NULLIF(TRIM(@ThuMucLuuTru)), '');

    IF @ChuKyFull IS NOT NULL AND @ChuKyFull NOT IN ('Hàng tuần', 'Hàng tháng')
        RAISE EXCEPTION %;

    IF @ChuKyIncremental IS NOT NULL AND @ChuKyIncremental NOT IN ('Hàng ngày', 'Hàng tuần')
        RAISE EXCEPTION %;

    IF @ThuMucLuuTru IS NOT NULL
    BEGIN
        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);
    END;

    IF @ChuKyFull IS NULL AND @ChuKyIncremental IS NULL AND @ThuMucLuuTru IS NULL
    BEGIN
        SELECT
            MaCauHinh AS maCauHinh,
            ChuKyFull AS chuKyFull,
            ChuKyIncremental AS chuKyIncremental,
            ThuMucLuuTru AS thuMucLuuTru,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;
        RETURN;
    END;

    DECLARE @DuLieuTruocSaoLuu TEXT;
    SELECT @DuLieuTruocSaoLuu = (
        SELECT * FROM dbo.CauHinhSaoLuu WHERE MaCauHinh = 1 FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    UPDATE dbo.CauHinhSaoLuu
    SET ChuKyFull = COALESCE(@ChuKyFull, ChuKyFull),
        ChuKyIncremental = COALESCE(@ChuKyIncremental, ChuKyIncremental),
        ThuMucLuuTru = COALESCE(@ThuMucLuuTru, ThuMucLuuTru),
        CapNhatLuc = CURRENT_TIMESTAMP,
        CapNhatBoi = @AdminId
    WHERE MaCauHinh = 1;

    EXEC dbo.SP_Admin_GhiNhatKy
        @AdminId = @AdminId,
        @HanhDong = 'Cấu hình sao lưu',
        @DoiTuong = 'CauHinhSaoLuu',
        @MaDoiTuong = '1',
        @DuLieuTruoc = @DuLieuTruocSaoLuu;

    SELECT
        MaCauHinh AS maCauHinh,
        ChuKyFull AS chuKyFull,
        ChuKyIncremental AS chuKyIncremental,
        ThuMucLuuTru AS thuMucLuuTru,
        CapNhatLuc AS capNhatLuc,
        CapNhatBoi AS capNhatBoi
    FROM dbo.CauHinhSaoLuu
    WHERE MaCauHinh = 1;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_SaoLuuThuCong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_SaoLuuThuCong
    @LoaiSaoLuu  VARCHAR(20)  = 'Full',
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    

    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');
    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');
    IF @LoaiSaoLuu IS NULL SET @LoaiSaoLuu = 'Full';

    DECLARE @LoaiSaoLuuChuan VARCHAR(20) = UPPER(@LoaiSaoLuu);
    IF @LoaiSaoLuuChuan = 'FULL'
        SET @LoaiSaoLuu = 'Full';
    ELSE IF @LoaiSaoLuuChuan IN ('INCREMENTAL', 'DIFFERENTIAL')
        SET @LoaiSaoLuu = 'Incremental';

    IF @LoaiSaoLuu NOT IN ('Full', 'Incremental')
        RAISE EXCEPTION %;

    IF @DuongDanFile IS NULL
    BEGIN
        DECLARE @ThuMucLuuTru VARCHAR(500);
        SELECT @ThuMucLuuTru = ThuMucLuuTru
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;

        IF @ThuMucLuuTru IS NULL
            RAISE EXCEPTION %;

        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);

        SET @DuongDanFile =
            @ThuMucLuuTru + '\' + DB_NAME() + '_' + @LoaiSaoLuu + '_' +
            CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112) + REPLACE(CONVERT(CHAR(8), CURRENT_TIMESTAMP, 108), ':', '') + '.bak';
    END;

    DECLARE @MaSaoLuu INT;
    DECLARE @LenhSaoLuu TEXT;

    INSERT INTO dbo.LichSuSaoLuu (
        LoaiSaoLuu, DuongDanFile, TrangThai, ThoiGianBatDau, MaNguoiDung
    )
    VALUES (
        @LoaiSaoLuu, @DuongDanFile, 'Đang chạy', CURRENT_TIMESTAMP, @AdminId
    );

    SET @MaSaoLuu = SCOPE_IDENTITY();
    SET @LenhSaoLuu =
        'BACKUP DATABASE ' + QUOTENAME(DB_NAME()) +
        ' TO DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') +
        ''' WITH ' +
        CASE WHEN @LoaiSaoLuu = 'Incremental' THEN 'DIFFERENTIAL, INIT' ELSE 'INIT' END +
        ';';

    BEGIN TRY
        EXEC(@LenhSaoLuu);

        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thành công',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = 'Sao lưu hoàn tất.'
        WHERE MaSaoLuu = @MaSaoLuu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Sao lưu thủ công',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thất bại',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = ERROR_MESSAGE()
        WHERE MaSaoLuu = @MaSaoLuu;

        THROW;
    END CATCH;

    SELECT
        MaSaoLuu AS maSaoLuu,
        LoaiSaoLuu AS loaiSaoLuu,
        DuongDanFile AS duongDanFile,
        TrangThai AS trangThai,
        ThoiGianBatDau AS thoiGianBatDau,
        ThoiGianKetThuc AS thoiGianKetThuc,
        ThongBao AS thongBao
    FROM dbo.LichSuSaoLuu
    WHERE MaSaoLuu = @MaSaoLuu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_DanhSachSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_DanhSachSaoLuu
    @SoDong     INT          = 100,
    @TrangThai  VARCHAR(20) = NULL,
    @LoaiSaoLuu VARCHAR(20) = NULL
AS
BEGIN
    

    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 100;

    SELECT TOP (@SoDong)
        ls.MaSaoLuu AS maSaoLuu,
        ls.LoaiSaoLuu AS loaiSaoLuu,
        ls.DuongDanFile AS duongDanFile,
        ls.DungLuongByte AS dungLuongByte,
        ls.TrangThai AS trangThai,
        ls.ThoiGianBatDau AS thoiGianBatDau,
        ls.ThoiGianKetThuc AS thoiGianKetThuc,
        ls.ThongBao AS thongBao,
        ls.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung
    FROM dbo.LichSuSaoLuu AS ls
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = ls.MaNguoiDung
    WHERE (@TrangThai IS NULL OR ls.TrangThai = @TrangThai)
      AND (@LoaiSaoLuu IS NULL OR ls.LoaiSaoLuu = @LoaiSaoLuu)
    ORDER BY ls.ThoiGianBatDau DESC, ls.MaSaoLuu DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_PhucHoiDuLieu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_PhucHoiDuLieu
    @MaSaoLuu    INT           = NULL,
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL,
    @ChiTaoLenh   BOOLEAN           = 1
AS
BEGIN
    

    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');

    IF @DuongDanFile IS NULL AND @MaSaoLuu IS NOT NULL
    BEGIN
        SELECT @DuongDanFile = DuongDanFile
        FROM dbo.LichSuSaoLuu
        WHERE MaSaoLuu = @MaSaoLuu
          AND TrangThai = 'Thành công';
    END;

    IF @DuongDanFile IS NULL
        RAISE EXCEPTION %;

    DECLARE @TenDatabase SYSNAME = DB_NAME();
    DECLARE @LenhSingleUser TEXT;
    DECLARE @LenhRestore TEXT;
    DECLARE @LenhMultiUser TEXT;
    DECLARE @LenhDayDu TEXT;

    SET @LenhSingleUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET SINGLE_USER WITH ROLLBACK IMMEDIATE;';
    SET @LenhRestore = 'USE [master]; RESTORE DATABASE ' + QUOTENAME(@TenDatabase) +
        ' FROM DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') + ''' WITH REPLACE;';
    SET @LenhMultiUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET MULTI_USER;';
    SET @LenhDayDu = @LenhSingleUser + CHAR(13) + CHAR(10) + @LenhRestore + CHAR(13) + CHAR(10) + @LenhMultiUser;

    IF @ChiTaoLenh = 1
    BEGIN
        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo lệnh phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;

        SELECT
            @TenDatabase AS tenDatabase,
            @DuongDanFile AS duongDanFile,
            @LenhDayDu AS lenhPhucHoi,
            CAST(1 AS BOOLEAN) AS chiTaoLenh;
        RETURN;
    END;

    BEGIN TRY
        EXEC(@LenhSingleUser);
        EXEC(@LenhRestore);
        EXEC(@LenhMultiUser);

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        BEGIN TRY
            EXEC(@LenhMultiUser);
        END TRY
        BEGIN CATCH
        END CATCH;

        THROW;
    END CATCH;

    SELECT
        @TenDatabase AS tenDatabase,
        @DuongDanFile AS duongDanFile,
        CAST(1 AS BOOLEAN) AS daPhucHoi;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_XemNhatKyHeThong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_XemNhatKyHeThong
    @TuNgay     TIMESTAMP  = NULL,
    @DenNgay    TIMESTAMP  = NULL,
    @AdminId    VARCHAR(6)    = NULL,
    @DoiTuong   VARCHAR(100) = NULL,
    @HanhDong   VARCHAR(100) = NULL,
    @TuKhoa     VARCHAR(100) = NULL,
    @SoDong     INT           = 200
AS
BEGIN
    

    SET @AdminId = NULLIF(TRIM(@AdminId)), '');
    SET @DoiTuong = NULLIF(TRIM(@DoiTuong)), '');
    SET @HanhDong = NULLIF(TRIM(@HanhDong)), '');
    SET @TuKhoa = NULLIF(TRIM(@TuKhoa)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 200;

    SELECT TOP (@SoDong)
        nk.MaNhatKy AS maNhatKy,
        nk.ThoiGian AS thoiGian,
        nk.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung,
        nk.VaiTro AS vaiTro,
        nk.ChucNang AS chucNang,
        nk.HanhDong AS hanhDong,
        nk.DoiTuong AS doiTuong,
        nk.MaDoiTuong AS maDoiTuong,
        nk.NoiDung AS noiDung,
        nk.DuLieuTruoc AS duLieuTruoc,
        nk.DuLieuSau AS duLieuSau
    FROM dbo.NhatKyHeThong AS nk
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nk.MaNguoiDung
    WHERE (@TuNgay IS NULL OR nk.ThoiGian >= @TuNgay)
      AND (@DenNgay IS NULL OR nk.ThoiGian < DATEADD(DAY, 1, @DenNgay))
      AND (@AdminId IS NULL OR nk.MaNguoiDung = @AdminId)
      AND (@DoiTuong IS NULL OR nk.DoiTuong = @DoiTuong)
      AND (@HanhDong IS NULL OR nk.HanhDong LIKE '%' + @HanhDong + '%')
      AND (
          @TuKhoa IS NULL
          OR nk.NoiDung LIKE '%' + @TuKhoa + '%'
          OR nk.MaDoiTuong LIKE '%' + @TuKhoa + '%'
          OR nk.HanhDong LIKE '%' + @TuKhoa + '%'
      )
    ORDER BY nk.ThoiGian DESC, nk.MaNhatKy DESC;
END; THEN (@GiaTriSau)::INT ELSE NULL END IS NULL OR CASE WHEN (@GiaTriSau) ~ '^[0-9]+ <= 0)
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        INSERT INTO dbo.ThamSoHeThong (
            MaThamSo, NhomThamSo, TenThamSo, GiaTri, KieuDuLieu, DonViTinh, MoTa, CapNhatBoi
        )
        VALUES (
            @MaThamSo, @NhomThamSo, @TenThamSo, @GiaTriSau, @KieuDuLieuSau, @DonViTinh, @MoTa, @AdminId
        );

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @NoiDung = @TenThamSo;
    END
    ELSE
    BEGIN
        DECLARE @DuLieuTruocThamSo TEXT;
        SELECT @DuLieuTruocThamSo = (
            SELECT * FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.ThamSoHeThong
        SET NhomThamSo = COALESCE(@NhomThamSo, NhomThamSo),
            TenThamSo = COALESCE(@TenThamSo, TenThamSo),
            GiaTri = @GiaTriSau,
            KieuDuLieu = @KieuDuLieuSau,
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            MoTa = COALESCE(@MoTa, MoTa),
            CapNhatLuc = CURRENT_TIMESTAMP,
            CapNhatBoi = @AdminId
        WHERE MaThamSo = @MaThamSo;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @DuLieuTruoc = @DuLieuTruocThamSo;
    END;

    EXEC dbo.SP_Admin_CauHinhThamSo @ThaoTac = 'DANH_SACH', @MaThamSo = @MaThamSo;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhSaoLuu
    @ChuKyFull        VARCHAR(20)  = NULL,
    @ChuKyIncremental VARCHAR(20)  = NULL,
    @ThuMucLuuTru     VARCHAR(500) = NULL,
    @AdminId          VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ChuKyFull = NULLIF(TRIM(@ChuKyFull)), '');
    SET @ChuKyIncremental = NULLIF(TRIM(@ChuKyIncremental)), '');
    SET @ThuMucLuuTru = NULLIF(TRIM(@ThuMucLuuTru)), '');

    IF @ChuKyFull IS NOT NULL AND @ChuKyFull NOT IN ('Hàng tuần', 'Hàng tháng')
        RAISE EXCEPTION %;

    IF @ChuKyIncremental IS NOT NULL AND @ChuKyIncremental NOT IN ('Hàng ngày', 'Hàng tuần')
        RAISE EXCEPTION %;

    IF @ThuMucLuuTru IS NOT NULL
    BEGIN
        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);
    END;

    IF @ChuKyFull IS NULL AND @ChuKyIncremental IS NULL AND @ThuMucLuuTru IS NULL
    BEGIN
        SELECT
            MaCauHinh AS maCauHinh,
            ChuKyFull AS chuKyFull,
            ChuKyIncremental AS chuKyIncremental,
            ThuMucLuuTru AS thuMucLuuTru,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;
        RETURN;
    END;

    DECLARE @DuLieuTruocSaoLuu TEXT;
    SELECT @DuLieuTruocSaoLuu = (
        SELECT * FROM dbo.CauHinhSaoLuu WHERE MaCauHinh = 1 FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    UPDATE dbo.CauHinhSaoLuu
    SET ChuKyFull = COALESCE(@ChuKyFull, ChuKyFull),
        ChuKyIncremental = COALESCE(@ChuKyIncremental, ChuKyIncremental),
        ThuMucLuuTru = COALESCE(@ThuMucLuuTru, ThuMucLuuTru),
        CapNhatLuc = CURRENT_TIMESTAMP,
        CapNhatBoi = @AdminId
    WHERE MaCauHinh = 1;

    EXEC dbo.SP_Admin_GhiNhatKy
        @AdminId = @AdminId,
        @HanhDong = 'Cấu hình sao lưu',
        @DoiTuong = 'CauHinhSaoLuu',
        @MaDoiTuong = '1',
        @DuLieuTruoc = @DuLieuTruocSaoLuu;

    SELECT
        MaCauHinh AS maCauHinh,
        ChuKyFull AS chuKyFull,
        ChuKyIncremental AS chuKyIncremental,
        ThuMucLuuTru AS thuMucLuuTru,
        CapNhatLuc AS capNhatLuc,
        CapNhatBoi AS capNhatBoi
    FROM dbo.CauHinhSaoLuu
    WHERE MaCauHinh = 1;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_SaoLuuThuCong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_SaoLuuThuCong
    @LoaiSaoLuu  VARCHAR(20)  = 'Full',
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL
AS
BEGIN
    

    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');
    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');
    IF @LoaiSaoLuu IS NULL SET @LoaiSaoLuu = 'Full';

    DECLARE @LoaiSaoLuuChuan VARCHAR(20) = UPPER(@LoaiSaoLuu);
    IF @LoaiSaoLuuChuan = 'FULL'
        SET @LoaiSaoLuu = 'Full';
    ELSE IF @LoaiSaoLuuChuan IN ('INCREMENTAL', 'DIFFERENTIAL')
        SET @LoaiSaoLuu = 'Incremental';

    IF @LoaiSaoLuu NOT IN ('Full', 'Incremental')
        RAISE EXCEPTION %;

    IF @DuongDanFile IS NULL
    BEGIN
        DECLARE @ThuMucLuuTru VARCHAR(500);
        SELECT @ThuMucLuuTru = ThuMucLuuTru
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;

        IF @ThuMucLuuTru IS NULL
            RAISE EXCEPTION %;

        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);

        SET @DuongDanFile =
            @ThuMucLuuTru + '\' + DB_NAME() + '_' + @LoaiSaoLuu + '_' +
            CONVERT(CHAR(8), CURRENT_TIMESTAMP, 112) + REPLACE(CONVERT(CHAR(8), CURRENT_TIMESTAMP, 108), ':', '') + '.bak';
    END;

    DECLARE @MaSaoLuu INT;
    DECLARE @LenhSaoLuu TEXT;

    INSERT INTO dbo.LichSuSaoLuu (
        LoaiSaoLuu, DuongDanFile, TrangThai, ThoiGianBatDau, MaNguoiDung
    )
    VALUES (
        @LoaiSaoLuu, @DuongDanFile, 'Đang chạy', CURRENT_TIMESTAMP, @AdminId
    );

    SET @MaSaoLuu = SCOPE_IDENTITY();
    SET @LenhSaoLuu =
        'BACKUP DATABASE ' + QUOTENAME(DB_NAME()) +
        ' TO DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') +
        ''' WITH ' +
        CASE WHEN @LoaiSaoLuu = 'Incremental' THEN 'DIFFERENTIAL, INIT' ELSE 'INIT' END +
        ';';

    BEGIN TRY
        EXEC(@LenhSaoLuu);

        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thành công',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = 'Sao lưu hoàn tất.'
        WHERE MaSaoLuu = @MaSaoLuu;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Sao lưu thủ công',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        UPDATE dbo.LichSuSaoLuu
        SET TrangThai = 'Thất bại',
            ThoiGianKetThuc = CURRENT_TIMESTAMP,
            ThongBao = ERROR_MESSAGE()
        WHERE MaSaoLuu = @MaSaoLuu;

        THROW;
    END CATCH;

    SELECT
        MaSaoLuu AS maSaoLuu,
        LoaiSaoLuu AS loaiSaoLuu,
        DuongDanFile AS duongDanFile,
        TrangThai AS trangThai,
        ThoiGianBatDau AS thoiGianBatDau,
        ThoiGianKetThuc AS thoiGianKetThuc,
        ThongBao AS thongBao
    FROM dbo.LichSuSaoLuu
    WHERE MaSaoLuu = @MaSaoLuu;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_DanhSachSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_DanhSachSaoLuu
    @SoDong     INT          = 100,
    @TrangThai  VARCHAR(20) = NULL,
    @LoaiSaoLuu VARCHAR(20) = NULL
AS
BEGIN
    

    SET @TrangThai = NULLIF(TRIM(@TrangThai)), '');
    SET @LoaiSaoLuu = NULLIF(TRIM(@LoaiSaoLuu)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 100;

    SELECT TOP (@SoDong)
        ls.MaSaoLuu AS maSaoLuu,
        ls.LoaiSaoLuu AS loaiSaoLuu,
        ls.DuongDanFile AS duongDanFile,
        ls.DungLuongByte AS dungLuongByte,
        ls.TrangThai AS trangThai,
        ls.ThoiGianBatDau AS thoiGianBatDau,
        ls.ThoiGianKetThuc AS thoiGianKetThuc,
        ls.ThongBao AS thongBao,
        ls.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung
    FROM dbo.LichSuSaoLuu AS ls
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = ls.MaNguoiDung
    WHERE (@TrangThai IS NULL OR ls.TrangThai = @TrangThai)
      AND (@LoaiSaoLuu IS NULL OR ls.LoaiSaoLuu = @LoaiSaoLuu)
    ORDER BY ls.ThoiGianBatDau DESC, ls.MaSaoLuu DESC;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_PhucHoiDuLieu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_PhucHoiDuLieu
    @MaSaoLuu    INT           = NULL,
    @DuongDanFile VARCHAR(500) = NULL,
    @AdminId      VARCHAR(6)    = NULL,
    @ChiTaoLenh   BOOLEAN           = 1
AS
BEGIN
    

    SET @DuongDanFile = NULLIF(TRIM(@DuongDanFile)), '');

    IF @DuongDanFile IS NULL AND @MaSaoLuu IS NOT NULL
    BEGIN
        SELECT @DuongDanFile = DuongDanFile
        FROM dbo.LichSuSaoLuu
        WHERE MaSaoLuu = @MaSaoLuu
          AND TrangThai = 'Thành công';
    END;

    IF @DuongDanFile IS NULL
        RAISE EXCEPTION %;

    DECLARE @TenDatabase SYSNAME = DB_NAME();
    DECLARE @LenhSingleUser TEXT;
    DECLARE @LenhRestore TEXT;
    DECLARE @LenhMultiUser TEXT;
    DECLARE @LenhDayDu TEXT;

    SET @LenhSingleUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET SINGLE_USER WITH ROLLBACK IMMEDIATE;';
    SET @LenhRestore = 'USE [master]; RESTORE DATABASE ' + QUOTENAME(@TenDatabase) +
        ' FROM DISK = N''' + REPLACE(@DuongDanFile, '''', '''''') + ''' WITH REPLACE;';
    SET @LenhMultiUser = 'USE [master]; ALTER DATABASE ' + QUOTENAME(@TenDatabase) + ' SET MULTI_USER;';
    SET @LenhDayDu = @LenhSingleUser + CHAR(13) + CHAR(10) + @LenhRestore + CHAR(13) + CHAR(10) + @LenhMultiUser;

    IF @ChiTaoLenh = 1
    BEGIN
        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo lệnh phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;

        SELECT
            @TenDatabase AS tenDatabase,
            @DuongDanFile AS duongDanFile,
            @LenhDayDu AS lenhPhucHoi,
            CAST(1 AS BOOLEAN) AS chiTaoLenh;
        RETURN;
    END;

    BEGIN TRY
        EXEC(@LenhSingleUser);
        EXEC(@LenhRestore);
        EXEC(@LenhMultiUser);

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Phục hồi dữ liệu',
            @DoiTuong = 'LichSuSaoLuu',
            @MaDoiTuong = @MaSaoLuu,
            @NoiDung = @DuongDanFile;
    END TRY
    BEGIN CATCH
        BEGIN TRY
            EXEC(@LenhMultiUser);
        END TRY
        BEGIN CATCH
        END CATCH;

        THROW;
    END CATCH;

    SELECT
        @TenDatabase AS tenDatabase,
        @DuongDanFile AS duongDanFile,
        CAST(1 AS BOOLEAN) AS daPhucHoi;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_XemNhatKyHeThong AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_XemNhatKyHeThong
    @TuNgay     TIMESTAMP  = NULL,
    @DenNgay    TIMESTAMP  = NULL,
    @AdminId    VARCHAR(6)    = NULL,
    @DoiTuong   VARCHAR(100) = NULL,
    @HanhDong   VARCHAR(100) = NULL,
    @TuKhoa     VARCHAR(100) = NULL,
    @SoDong     INT           = 200
AS
BEGIN
    

    SET @AdminId = NULLIF(TRIM(@AdminId)), '');
    SET @DoiTuong = NULLIF(TRIM(@DoiTuong)), '');
    SET @HanhDong = NULLIF(TRIM(@HanhDong)), '');
    SET @TuKhoa = NULLIF(TRIM(@TuKhoa)), '');

    IF @SoDong IS NULL OR @SoDong < 1 OR @SoDong > 1000
        SET @SoDong = 200;

    SELECT TOP (@SoDong)
        nk.MaNhatKy AS maNhatKy,
        nk.ThoiGian AS thoiGian,
        nk.MaNguoiDung AS maNguoiDung,
        nd.HoTen AS hoTenNguoiDung,
        nk.VaiTro AS vaiTro,
        nk.ChucNang AS chucNang,
        nk.HanhDong AS hanhDong,
        nk.DoiTuong AS doiTuong,
        nk.MaDoiTuong AS maDoiTuong,
        nk.NoiDung AS noiDung,
        nk.DuLieuTruoc AS duLieuTruoc,
        nk.DuLieuSau AS duLieuSau
    FROM dbo.NhatKyHeThong AS nk
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = nk.MaNguoiDung
    WHERE (@TuNgay IS NULL OR nk.ThoiGian >= @TuNgay)
      AND (@DenNgay IS NULL OR nk.ThoiGian < DATEADD(DAY, 1, @DenNgay))
      AND (@AdminId IS NULL OR nk.MaNguoiDung = @AdminId)
      AND (@DoiTuong IS NULL OR nk.DoiTuong = @DoiTuong)
      AND (@HanhDong IS NULL OR nk.HanhDong LIKE '%' + @HanhDong + '%')
      AND (
          @TuKhoa IS NULL
          OR nk.NoiDung LIKE '%' + @TuKhoa + '%'
          OR nk.MaDoiTuong LIKE '%' + @TuKhoa + '%'
          OR nk.HanhDong LIKE '%' + @TuKhoa + '%'
      )
    ORDER BY nk.ThoiGian DESC, nk.MaNhatKy DESC;
END; THEN (@GiaTriSau)::INT ELSE NULL END <= 0)
        RAISE EXCEPTION %;

    IF @ThaoTac = 'TAO'
    BEGIN
        IF EXISTS (SELECT 1 FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo)
            RAISE EXCEPTION %;

        INSERT INTO dbo.ThamSoHeThong (
            MaThamSo, NhomThamSo, TenThamSo, GiaTri, KieuDuLieu, DonViTinh, MoTa, CapNhatBoi
        )
        VALUES (
            @MaThamSo, @NhomThamSo, @TenThamSo, @GiaTriSau, @KieuDuLieuSau, @DonViTinh, @MoTa, @AdminId
        );

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Tạo tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @NoiDung = @TenThamSo;
    END
    ELSE
    BEGIN
        DECLARE @DuLieuTruocThamSo TEXT;
        SELECT @DuLieuTruocThamSo = (
            SELECT * FROM dbo.ThamSoHeThong WHERE MaThamSo = @MaThamSo FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        UPDATE dbo.ThamSoHeThong
        SET NhomThamSo = COALESCE(@NhomThamSo, NhomThamSo),
            TenThamSo = COALESCE(@TenThamSo, TenThamSo),
            GiaTri = @GiaTriSau,
            KieuDuLieu = @KieuDuLieuSau,
            DonViTinh = COALESCE(@DonViTinh, DonViTinh),
            MoTa = COALESCE(@MoTa, MoTa),
            CapNhatLuc = CURRENT_TIMESTAMP,
            CapNhatBoi = @AdminId
        WHERE MaThamSo = @MaThamSo;

        EXEC dbo.SP_Admin_GhiNhatKy
            @AdminId = @AdminId,
            @HanhDong = 'Cập nhật tham số hệ thống',
            @DoiTuong = 'ThamSoHeThong',
            @MaDoiTuong = @MaThamSo,
            @DuLieuTruoc = @DuLieuTruocThamSo;
    END;

    EXEC dbo.SP_Admin_CauHinhThamSo @ThaoTac = 'DANH_SACH', @MaThamSo = @MaThamSo;
END;

    EXEC('CREATE PROCEDURE dbo.SP_Admin_CauHinhSaoLuu AS BEGIN  RETURN 0; END;');
CREATE OR ALTER PROCEDURE dbo.SP_Admin_CauHinhSaoLuu
    @ChuKyFull        VARCHAR(20)  = NULL,
    @ChuKyIncremental VARCHAR(20)  = NULL,
    @ThuMucLuuTru     VARCHAR(500) = NULL,
    @AdminId          VARCHAR(6)    = NULL
AS
BEGIN
    
    

    SET @ChuKyFull = NULLIF(TRIM(@ChuKyFull)), '');
    SET @ChuKyIncremental = NULLIF(TRIM(@ChuKyIncremental)), '');
    SET @ThuMucLuuTru = NULLIF(TRIM(@ThuMucLuuTru)), '');

    IF @ChuKyFull IS NOT NULL AND @ChuKyFull NOT IN ('Hàng tuần', 'Hàng tháng')
        RAISE EXCEPTION %;

    IF @ChuKyIncremental IS NOT NULL AND @ChuKyIncremental NOT IN ('Hàng ngày', 'Hàng tuần')
        RAISE EXCEPTION %;

    IF @ThuMucLuuTru IS NOT NULL
    BEGIN
        SET @ThuMucLuuTru = REPLACE(@ThuMucLuuTru, '/', '\');
        WHILE RIGHT(@ThuMucLuuTru, 1) = '\'
            SET @ThuMucLuuTru = LEFT(@ThuMucLuuTru, LENGTH(@ThuMucLuuTru) - 1);
    END;

    IF @ChuKyFull IS NULL AND @ChuKyIncremental IS NULL AND @ThuMucLuuTru IS NULL
    BEGIN
        SELECT
            MaCauHinh AS maCauHinh,
            ChuKyFull AS chuKyFull,
            ChuKyIncremental AS chuKyIncremental,
            ThuMucLuuTru AS thuMucLuuTru,
            CapNhatLuc AS capNhatLuc,
            CapNhatBoi AS capNhatBoi
        FROM dbo.CauHinhSaoLuu
        WHERE MaCauHinh = 1;
        RETURN;
    END;

    DECLARE @DuLieuTruocSaoLuu TEXT;
    SELECT @DuLieuTruocSaoLuu = (
        SELECT * FROM dbo.CauHinhSaoLuu WHERE MaCauHinh = 1 FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    UPDATE dbo.CauHinhSaoLuu
    SET ChuKyFull = COALESCE(@ChuKyFull, ChuKyFull),
        ChuKyIncremental = COALESCE(@ChuKyIncremental, ChuKyIncremental),
        ThuMucLuuTru = COALESCE(@ThuMucLuuTru, ThuMucLuuTru),
        CapNhatLuc = CURRENT_TIMESTAMP,
        CapNhatBoi = @AdminId
    WHERE MaCauHinh = 1;

    EXEC dbo.SP_Admin_GhiNhatKy
        @AdminId = @AdminId,
        @HanhDong = 'Cấu hình sao lưu',
        @DoiTuong = 'CauHinhSaoLuu',
        @MaDoiTuong = '1',
        @DuLieuTruoc = @DuLieuTruocSaoLuu;

    SELECT
        MaCauHinh AS maCauHinh,
        ChuKyFull AS chuKyFull,
        ChuKyIncremental AS chuKyIncremental,
        ThuMucLuuTru AS thuMucLuuTru,
        CapNhatLuc AS capNhatLuc,
        CapNhatBoi AS capNhatBoi
    FROM dbo.CauHinhSaoLuu
    WHERE MaCauHinh = 1;
END;

