        nd.HoTen AS hoTenNguoiDung
    FROM dbo.LichSuSaoLuu AS ls
    LEFT JOIN dbo.NguoiDung AS nd ON nd.MaNguoiDung = ls.MaNguoiDung
    WHERE (@TrangThai IS NULL OR ls.TrangThai = @TrangThai)
